window.Q=window.Q||{};Q["m37_S2"]=[{"i":"S2-1-1-학개론-01","r":"S2","g":1,"c":1,"n":1,"s":"학개론","q":"부동산의 개념에 관한 설명으로 틀린 것은?","b":null,"bs":"없음","img":[],"ch":["민법 상 부동산은 토지 및 그 정착물이다.","경제적 측면의 부동산은 부동산가치에 영향을 미치는 수익성, 수급조절, 시장정보를 포함한다.","물리적 측면의 부동산에는 생산요소, 자산, 공간, 자연이 포함된다.","등기ㆍ등록의 공시방법을 갖춤으로써 부동산에 준하여 취급되는 동산은 준부동산으로 간주한다.","공간적 측면의 부동산에는 지하, 지표, 공중공간이 포함된다."],"a":[3],"L":"학1-1","o":"기출","x":{"한줄":"생산요소와 자산은 경제적(자산·자본·생산요소) 개념이고, 물리적(기술적) 개념에는 공간·위치·환경·자연이 들어간다.","근거":[{"법령":"민법","조문":"제99조","원문":"①토지 및 그 정착물은 부동산이다.\n②부동산 이외의 물건은 동산이다."},{"이론":"부동산의 복합개념","내용":"법률적(협의·광의), 경제적(자산·자본·생산요소·상품·소비재), 물리적(공간·위치·환경·자연) 세 측면으로 나눈다."}],"선지":[{"번호":1,"판정":"옳음","설명":"민법 제99조 제1항. 협의의 부동산이 곧 토지와 정착물이다."},{"번호":2,"판정":"옳음","설명":"수익성·수급조절·시장정보는 가치에 영향을 주는 경제적 측면의 내용이다."},{"번호":3,"판정":"틀림","설명":"생산요소와 자산은 경제적 개념이다. 물리적 개념은 공간·위치·환경·자연이다."},{"번호":4,"판정":"옳음","설명":"등기 대상(입목·공장재단·광업재단·20톤 이상 선박)과 등록 대상(자동차·항공기·건설기계)은 준부동산이다."},{"번호":5,"판정":"옳음","설명":"공간적 개념은 지하·지표·공중공간을 포함하는 입체 공간이다."}],"개념":[{"종류":"표","제목":"부동산 복합개념 세 측면","머리":["측면","구분","내용"],"행":[["법률적","협의","민법 제99조의 토지 + 정착물"],["법률적","광의","협의의 부동산 + 준부동산"],["경제적","성격","자산·자본·생산요소·상품·소비재"],["경제적","가치 영향","수익성·수급조절·시장정보"],["물리적(기술적)","대상","공간·위치·환경·자연"]]},{"종류":"표","제목":"준부동산 공시방법","머리":["공시","대상"],"행":[["등기","입목, 공장재단, 광업재단, 20톤 이상 선박"],["등록","자동차, 항공기, 건설기계"],["등록(권리)","광업권, 어업권"],["정착물 구분","종속정착물(구거·교량·담장·다년생 식물) / 독립정착물(건물·등기된 입목·명인방법을 갖춘 수목 집단)"]]}],"함정":"생산요소·자산을 물리적 개념에 넣은 문장에서 걸린다. 생산요소·자산은 경제적 개념이다."}},{"i":"S2-1-1-학개론-02","r":"S2","g":1,"c":1,"n":2,"s":"학개론","q":"이용상태에 따른 토지 관련 용어의 설명으로 틀린 것은?","b":null,"bs":"없음","img":[],"ch":["획지는 가격수준이 비슷한 일단의 토지로서 이용과 개발의 단위가 된다.","나지는 건물 등 정착물이 없고 지상권 같은 사법상 제한도 없는 토지이며, 공법상 제한은 받는다.","법지는 소유권은 인정되나 택지 경계의 경사면이어서 이용 가치가 낮은 토지를 말한다.","포락지는 바다와 육지 사이에 있는 해변으로서 소유권이 인정되지 않는 토지를 말한다.","이행지는 택지지역 안에서 주거지역이 상업지역으로 바뀌어 가는 토지처럼 같은 대분류 안의 소분류 사이에서 전환 중인 토지를 말한다."],"a":[4],"L":"학1-2","o":"변형","x":{"한줄":"바다와 육지 사이의 소유권 없는 해변은 빈지이고, 포락지는 소유권이 있던 전·답이 물에 깎여 수면 아래로 잠긴 토지다.","근거":[{"이론":"토지의 이용상태별 용어","내용":"빈지는 소유권이 없는 해변, 포락지는 소유권 있던 토지가 물에 잠긴 것, 법지는 소유권이 있으나 이용 가치가 낮은 경사지다."}],"선지":[{"번호":1,"판정":"옳음","설명":"획지는 이용·개발·평가의 단위이고, 등록단위는 필지다."},{"번호":2,"판정":"옳음","설명":"나지는 정착물과 사법상 제한이 없는 토지다. 건축 제한 같은 공법상 제한은 받는다."},{"번호":3,"판정":"옳음","설명":"법지는 소유권 ○, 이용 가치 낮음."},{"번호":4,"판정":"틀림","설명":"소유권이 없는 해변은 빈지다. 포락지는 원래 등록된 전·답이 물에 깎여 하천·수면 밑으로 변한 토지다."},{"번호":5,"판정":"옳음","설명":"이행지는 대분류 안 소분류 간 전환, 후보지는 대분류(택지·농지·임지) 간 전환이다."}],"개념":[{"종류":"표","제목":"물가의 땅 셋","머리":["구분","소유권","상태"],"행":[["빈지","없음","바다와 육지 사이 해변·갯벌, 이용 가치 있음"],["포락지","있던 땅","전·답이 물에 깎여 하천·수면 아래로 잠김"],["법지","있음","택지 경계 경사지, 이용 가치 낮음"],["선하지","있음","고압선 아래 땅, 이용·거래 제한이 많음"]]},{"종류":"비교","제목":"후보지와 이행지","왼쪽":{"이름":"후보지","항목":["대분류 사이 전환 중(택지↔농지↔임지)","예: 농지지역이 택지지역으로 바뀌는 중"]},"오른쪽":{"이름":"이행지","항목":["대분류 안 소분류 사이 전환 중","예: 택지지역 안에서 주거→상업, 공업→상업"]}}],"함정":"포락지와 빈지를 바꿔 쓴 보기에서 걸린다. 소유권 유무로 가른다."}},{"i":"S2-1-1-학개론-03","r":"S2","g":1,"c":1,"n":3,"s":"학개론","q":"토지의 특성에 관한 설명으로 옳은 것은?","b":null,"bs":"없음","img":[],"ch":["영속성은 토지에 감가상각을 적용하는 근거가 된다.","부증성은 토지의 물리적 공급을 탄력적으로 만든다.","개별성은 토지 가격을 표준화하여 일물일가의 법칙이 성립하게 한다.","부동성은 부동산 활동과 시장을 국지화시키며 지역분석의 근거가 된다.","토지의 병합·분할 가능성은 자연적 특성에 속한다."],"a":[4],"L":"학1-3","o":"변형","x":{"한줄":"움직이지 않는 부동성 때문에 시장이 지역별로 나뉘고, 그래서 해당 지역의 특성을 먼저 살피는 지역분석이 필요하다.","근거":[{"이론":"토지의 특성","내용":"자연적 특성은 부동성·영속성·부증성·개별성, 인문적 특성은 용도의 다양성·병합분할 가능성·위치의 가변성이다."}],"선지":[{"번호":1,"판정":"틀림","설명":"영속성(비소모성)은 토지에 감가상각을 적용하지 않는 근거다. 건물은 내용연수가 있어 감가상각 대상이다."},{"번호":2,"판정":"틀림","설명":"부증성 때문에 물리적 공급은 비탄력적(고정)이다. 용도 전환으로 용도적 공급만 조절된다."},{"번호":3,"판정":"틀림","설명":"개별성 때문에 표준화·일물일가가 성립하지 않고, 시장은 불완전하며 가격은 개별적으로 결정된다."},{"번호":4,"판정":"옳음","설명":"부동성이 국지성·지역분석의 근거다."},{"번호":5,"판정":"틀림","설명":"병합·분할 가능성은 인문적 특성이다."}],"개념":[{"종류":"표","제목":"자연적 특성과 파생현상","머리":["특성","의미","파생현상"],"행":[["부동성","위치가 고정되어 이동 불가","시장의 국지화·지역분석, 외부효과, 임장활동, 등기·공시"],["영속성","소모되지 않고 존속","가치보존력, 토지는 감가상각 제외, 소유 이익(자본이득)과 이용 이익(임대수익) 구분"],["부증성","생산·증가 불가","물리적 공급의 비탄력, 지대·지가 발생, 최유효이용의 근거"],["개별성","동일한 토지가 없음","비표준화, 불완전시장, 개별분석, 일물일가 불성립"]]},{"종류":"표","제목":"인문적 특성","머리":["특성","내용"],"행":[["용도의 다양성","용도를 바꿀 수 있어 최유효이용의 근거"],["병합·분할 가능성","필지의 합필·분필"],["위치의 가변성","사회적·경제적·행정적 위치가 변함"]]}],"함정":"병합·분할 가능성을 자연적 특성으로 착각한다. 인문적 특성이다."}},{"i":"S2-1-1-학개론-04","r":"S2","g":1,"c":1,"n":4,"s":"학개론","q":"부동산의 수요와 공급에 관한 설명으로 틀린 것은? (단, 부동산은 정상재이며, 다른 조건은 동일함)","b":null,"bs":"없음","img":[],"ch":["수요곡선상의 수요량은 주어진 가격에서 수요자들이 구입 또는 임차하고자 하는 부동산의 최대수량이다.","부동산의 공급량과 그 공급량에 영향을 주는 요인들과 의 관계를 나타낸 것이 공급함수이다.","공급의 법칙에 따르면 가격(임대료)과 공급량은 비례관계이다.","부동산 시장수요곡선은 개별수요곡선을 수직으로 합하여 도출한다.","건축원자재의 가격 상승은 부동산의 공급을 축소시켜 공급곡선을 좌측(좌상향)으로 이동하게 한다."],"a":[4],"L":"학2-1","o":"기출","x":{"한줄":"시장수요곡선은 같은 가격에서 개별 수요량을 더하므로 개별수요곡선을 수평(수량 방향)으로 합해 구한다.","근거":[{"이론":"시장수요곡선의 도출","내용":"각 가격 수준에서 개별 수요량을 합산한다. 수평 합이다. 수직 합은 공공재의 시장수요 도출 방식이다."}],"선지":[{"번호":1,"판정":"옳음","설명":"수요량은 실제 구매량이 아니라 일정 가격에서 사려고 하는 최대 수량이다."},{"번호":2,"판정":"옳음","설명":"공급함수는 공급량과 그 결정 요인의 관계를 나타낸다."},{"번호":3,"판정":"옳음","설명":"가격과 공급량은 정(+)의 관계다."},{"번호":4,"판정":"틀림","설명":"개별수요곡선을 수평으로 합한다."},{"번호":5,"판정":"옳음","설명":"원자재 가격 상승은 생산비 증가 요인이어서 공급곡선이 좌상향으로 이동한다."}],"개념":[{"종류":"표","제목":"수요곡선 이동요인과 공급곡선 이동요인","머리":["구분","우측(증가)","좌측(감소)"],"행":[["수요(정상재)","소득 증가, 인구 증가, 대체재 가격 상승, 보완재 가격 하락, 금리 하락","소득 감소, 대체재 가격 하락, 보완재 가격 상승, 금리 상승"],["공급","건축비 하락, 기술 진보, 공급자 수 증가, 세금 감소","건축비·원자재 가격 상승, 규제 강화, 세금 증가"],["해당 재 가격 변화","곡선 위의 이동(수요량·공급량 변화)","곡선 위의 이동"]]},{"종류":"비교","제목":"수요량 변화와 수요 변화","왼쪽":{"이름":"수요량 변화","항목":["해당 재의 가격 변화가 원인","같은 수요곡선 위에서 이동"]},"오른쪽":{"이름":"수요 변화","항목":["가격 이외 요인이 원인","수요곡선 자체가 좌우로 이동"]}}],"함정":"시장수요곡선을 수직합으로 그리는 선택지가 정답이다. 수평합이다."}},{"i":"S2-1-1-학개론-05","r":"S2","g":1,"c":1,"n":5,"s":"학개론","q":"부동산의 수요와 공급에 관한 설명으로 옳은 것은? (단, 부동산은 정상재이며, 수요곡선은 우하향하고 공급곡선은 우상향하며, 다른 조건은 동일함)","b":null,"bs":"없음","img":[],"ch":["해당 부동산의 가격이 하락하면 수요량이 증가하여 수요곡선이 우측으로 이동한다.","대체재의 가격이 상승하면 해당 부동산의 수요곡선은 좌측으로 이동한다.","보완재의 가격이 상승하면 해당 부동산의 수요곡선은 우측으로 이동한다.","건축기술의 발달로 건축비가 절감되면 공급곡선이 우측으로 이동하여 균형가격은 하락하고 균형거래량은 증가한다.","수요가 증가하고 동시에 공급이 감소하면 균형가격은 상승하고 균형거래량은 증가한다."],"a":[4],"L":"학2-1","o":"변형","x":{"한줄":"건축비 절감은 공급곡선을 우측으로 옮긴다. 수요곡선이 그대로이므로 균형가격은 내리고 균형거래량은 늘어난다.","근거":[{"이론":"균형의 변화","내용":"수요 불변에서 공급이 증가하면 균형가격 하락, 균형거래량 증가. 수요와 공급이 반대로 움직이면 거래량 또는 가격 중 하나는 변화 폭에 따라 정해진다."}],"선지":[{"번호":1,"판정":"틀림","설명":"해당 재의 가격 변화는 수요곡선 위의 이동(수요량 변화)이다. 곡선이 이동하지 않는다."},{"번호":2,"판정":"틀림","설명":"대체재 가격이 오르면 상대적으로 싸진 해당 부동산으로 수요가 몰려 수요곡선이 우측으로 이동한다."},{"번호":3,"판정":"틀림","설명":"보완재 가격이 오르면 함께 쓰는 해당 부동산의 수요가 줄어 좌측으로 이동한다."},{"번호":4,"판정":"옳음","설명":"공급 증가 → 균형가격 하락, 균형거래량 증가."},{"번호":5,"판정":"틀림","설명":"수요 증가와 공급 감소는 모두 가격을 올린다. 거래량은 수요 증가폭과 공급 감소폭에 따라 늘 수도 줄 수도 있다."}],"개념":[{"종류":"표","제목":"수요·공급이 동시에 변할 때 균형","머리":["수요","공급","균형가격","균형거래량"],"행":[["증가","증가","변화폭에 따라 결정","증가"],["증가","감소","상승","변화폭에 따라 결정"],["감소","증가","하락","변화폭에 따라 결정"],["감소","감소","변화폭에 따라 결정","감소"]]},{"종류":"표","제목":"단독 이동의 균형 변화","머리":["이동","균형가격","균형거래량"],"행":[["수요 증가(공급 불변)","상승","증가"],["수요 감소(공급 불변)","하락","감소"],["공급 증가(수요 불변)","하락","증가"],["공급 감소(수요 불변)","상승","감소"]]}],"함정":"수요 증가와 공급 감소를 함께 놓고 거래량까지 확정하는 보기를 고르기 쉽다. 이 조합에서 확정되는 것은 가격 상승뿐이다."}},{"i":"S2-1-1-학개론-06","r":"S2","g":1,"c":1,"n":6,"s":"학개론","q":"상가의 분양수요함수가 Qd = 1,000 − 2P로 주어져 있다. 이 경우 사업시행자가 분양수입을 극대화하기 위한 분양가격은? (단, P는 분양가격이고 단위는 만원/m², Qd는 수요량이고 단위는 m², X축은 수량, Y축은 가격이며, 주어진 조건에 한함)","b":null,"bs":"없음","img":[],"ch":["125만원/m²","200만원/m²","225만원/m²","240만원/m²","250만원/m²"],"a":[5],"L":"학2-2","o":"변형","x":{"한줄":"분양수입 P·Q = 1,000P − 2P²을 P로 미분해 0으로 놓으면 P = 250이고, 이때 수요의 가격탄력성이 1이다.","근거":[{"이론":"총수입 극대화","내용":"직선 수요곡선에서 총수입은 탄력성이 1인 점(수요곡선 중점)에서 최대다. 탄력적 구간에서는 가격을 내리면, 비탄력적 구간에서는 올리면 수입이 늘어난다."}],"선지":[{"번호":1,"판정":"-","설명":"P=125이면 Q=750, 수입 93,750만원. 최대가 아니다."},{"번호":2,"판정":"-","설명":"P=200이면 Q=600, 수입 120,000만원."},{"번호":3,"판정":"-","설명":"P=225이면 Q=550, 수입 123,750만원."},{"번호":4,"판정":"-","설명":"P=240이면 Q=520, 수입 124,800만원."},{"번호":5,"판정":"-","설명":"P=250이면 Q=500, 수입 125,000만원으로 가장 크다."}],"개념":[{"종류":"계산","제목":"분양수입 극대화 가격","단계":[{"설명":"총수입 식 세우기","식":"R = P × Qd = P(1,000 − 2P)","값":"R = 1,000P − 2P²"},{"설명":"P로 미분해 0","식":"dR/dP = 1,000 − 4P = 0","값":"P = 250"},{"설명":"수량 구하기","식":"Qd = 1,000 − 2×250","값":"500m²"},{"설명":"총수입","식":"250 × 500","값":"125,000만원"},{"설명":"탄력성으로 검산","식":"|ε| = (2 × 250) ÷ 500","값":"1 (총수입 극대)"}]},{"종류":"표","제목":"탄력성과 총수입","머리":["구간","탄력성","가격 인상 시 총수입"],"행":[["탄력적","|ε| > 1","감소"],["단위탄력적","|ε| = 1","변화 없음, 총수입 극대점"],["비탄력적","|ε| < 1","증가"],["직선 수요곡선","가격 절편 500의 중점","P = 250에서 극대"]]}],"함정":"수요가 0이 되는 가격(500)이나 그 절반의 절반(125)을 고르기 쉽다. 가격 절편의 절반인 250이 탄력성 1인 점이다."}},{"i":"S2-1-1-학개론-07","r":"S2","g":1,"c":1,"n":7,"s":"학개론","q":"수요와 공급의 가격탄력성에 관한 설명으로 옳은 것은? (단, X축은 수량, Y축은 가격, 수요의 가격탄력성은 절댓값을 의미하며, 다른 조건은 동일함)","b":null,"bs":"없음","img":[],"ch":["가격이 변화하여도 수요량이 전혀 변화하지 않는다면, 수요의 가격탄력성은 완전탄력적이다.","가격변화율보다 공급량의 변화율이 커서 1보다 큰 값을 가진다면, 공급의 가격탄력성은 비탄력적이다.","공급의 가격탄력성이 0이라면, 완전탄력적이다.","수요의 가격탄력성이 1보다 작은 값을 가진다면, 수요의 가격탄력성은 탄력적이다.","공급곡선이 수직선이면, 공급의 가격탄력성은 완전비탄력적이다."],"a":[5],"L":"학2-2","o":"기출","x":{"한줄":"공급곡선이 수직선이면 가격이 변해도 공급량이 그대로이므로 탄력성이 0, 곧 완전비탄력적이다.","근거":[{"이론":"가격탄력성의 구분","내용":"ε=0 완전비탄력(수직선), 0<ε<1 비탄력, ε=1 단위탄력, 1<ε<∞ 탄력, ε=∞ 완전탄력(수평선)."}],"선지":[{"번호":1,"판정":"틀림","설명":"가격이 변해도 수요량이 불변이면 완전비탄력적(ε=0)이다."},{"번호":2,"판정":"틀림","설명":"공급량 변화율이 가격 변화율보다 커서 ε>1이면 탄력적이다."},{"번호":3,"판정":"틀림","설명":"ε=0은 완전비탄력적이다."},{"번호":4,"판정":"틀림","설명":"ε<1이면 비탄력적이다."},{"번호":5,"판정":"옳음","설명":"수직선 공급곡선은 ε=0, 완전비탄력적이다."}],"개념":[{"종류":"표","제목":"가격탄력성 구분","머리":["탄력성 값","명칭","곡선 모양","의미"],"행":[["ε = 0","완전비탄력적","수직선","가격이 변해도 수량 불변"],["0 < ε < 1","비탄력적","가파른 곡선","수량 변화율 < 가격 변화율"],["ε = 1","단위탄력적","직각쌍곡선(수요)","수량 변화율 = 가격 변화율"],["1 < ε < ∞","탄력적","완만한 곡선","수량 변화율 > 가격 변화율"],["ε = ∞","완전탄력적","수평선","특정 가격에서 수량이 무한히 변함"]]},{"종류":"표","제목":"소득·교차탄력성 부호","머리":["탄력성","부호","해석"],"행":[["소득탄력성","(+)","정상재, 1보다 크면 사치재"],["소득탄력성","(−)","열등재"],["교차탄력성","(+)","대체재 관계"],["교차탄력성","(−)","보완재 관계"]]}],"함정":"수요량이 전혀 변하지 않는 경우를 완전탄력적으로 고르기 쉽다. 완전비탄력적이다."}},{"i":"S2-1-1-학개론-08","r":"S2","g":1,"c":1,"n":8,"s":"학개론","q":"부동산경기변동에 관한 설명으로 옳은 것은?","b":null,"bs":"없음","img":[],"ch":["계절변동은 장기간에 걸쳐 나타나는 상승 또는 하락의 흐름을 말한다.","부동산경기는 일반경기에 비해 순환 주기가 길고, 지역별·용도별로 국면이 다르게 나타날 수 있다.","스태그플레이션은 경기침체 속에서 물가가 하락하는 현상이다.","회복시장에서 과거의 거래사례가격은 새로운 거래가격의 상한선이 된다.","상향시장은 수요자가 거래를 주도하는 매수자 중심의 시장이다."],"a":[2],"L":"학2-3","o":"변형","x":{"한줄":"부동산경기는 건축에 시간이 걸리고 시장이 국지적이어서 일반경기보다 주기가 길고 지역·용도에 따라 국면이 어긋난다.","근거":[{"이론":"부동산경기변동의 특징","내용":"주기가 길고 지역별·부문별로 국면이 다르며, 경기 국면의 시차가 크다. 순환변동·추세변동·계절변동·불규칙변동으로 나눈다."}],"선지":[{"번호":1,"판정":"틀림","설명":"장기 상승·하락의 흐름은 추세변동이다. 계절변동은 1년 단위로 반복되는 변동이다."},{"번호":2,"판정":"옳음","설명":"건설기간이 길고 시장이 국지적이어서 주기가 길며 지역·용도별로 국면이 다르다."},{"번호":3,"판정":"틀림","설명":"스태그플레이션은 경기침체와 물가 상승이 함께 나타나는 현상이다."},{"번호":4,"판정":"틀림","설명":"회복시장에서 과거 사례가격은 하한선이다. 상한선이 되는 것은 후퇴·하향시장이다."},{"번호":5,"판정":"틀림","설명":"상향시장은 매도자 중심 시장이다. 매수자 중심은 하향시장이다."}],"개념":[{"종류":"표","제목":"경기변동의 형태","머리":["형태","내용"],"행":[["추세변동","장기간에 걸친 상승 또는 하락의 흐름"],["순환변동","회복→상향→후퇴→하향의 반복(안정국면 별도)"],["계절변동","1년 단위로 반복(예: 이사철)"],["불규칙(우발)변동","예측하기 어려운 사건에 따른 변동"]]},{"종류":"표","제목":"국면별 시장과 사례가격","머리":["국면","시장 성격","과거 사례가격"],"행":[["회복","매수자 우위에서 매도자 우위로","하한선"],["상향","매도자 중심","하한선"],["후퇴","매수자 중심으로 전환","상한선"],["하향","매수자 중심","상한선"],["안정","가격이 안정적","신뢰할 수 있는 지표"]]}],"함정":"회복시장과 후퇴시장의 사례가격 방향을 바꿔 쓴 보기를 고르기 쉽다. 회복·상향은 하한선, 후퇴·하향은 상한선이다."}},{"i":"S2-1-1-학개론-09","r":"S2","g":1,"c":1,"n":9,"s":"학개론","q":"토지시장의 특성에 관한 설명으로 틀린 것은?","b":null,"bs":"없음","img":[],"ch":["수급조절이 용이하다.","법·제도적 규제가 많다.","재화의 이질성을 보인다.","정보의 불완전성 및 비대칭성을 보인다.","부분시장으로 나뉠 수 있는 국지성을 보인다."],"a":[1],"L":"학3-1","o":"기출","x":{"한줄":"토지는 물리적 공급이 고정되어 있고 개발에 시간이 걸려 수급조절이 어렵다.","근거":[{"이론":"부동산시장의 특성","내용":"거래의 비공개성, 정보의 비대칭성, 수급조절의 곤란, 법·제도 규제, 국지성(부분시장), 상품의 이질성, 단기 비탄력적 공급."}],"선지":[{"번호":1,"판정":"틀림","설명":"수급조절이 어렵다. 공급이 비탄력적이고 개발에 시간이 걸린다."},{"번호":2,"판정":"옳음","설명":"토지이용 규제 등 법·제도 규제가 많다."},{"번호":3,"판정":"옳음","설명":"개별성 때문에 재화가 이질적이다."},{"번호":4,"판정":"옳음","설명":"거래가 비공개적이어서 정보가 불완전하고 비대칭적이다."},{"번호":5,"판정":"옳음","설명":"지역별·용도별로 시장이 나뉘는 국지성이 있다."}],"개념":[{"종류":"표","제목":"부동산시장의 특성","머리":["특성","원인·내용"],"행":[["수급조절 곤란","공급의 비탄력성, 건설 시차"],["정보 비대칭","거래의 비공개성, 개별성"],["국지성","부동성 → 부분시장으로 분화"],["이질성","개별성 → 표준화 곤란"],["법·제도 규제","토지이용 규제, 거래 규제"]]},{"종류":"표","제목":"효율적 시장의 세 형태","머리":["형태","반영된 정보","초과이윤 가능 여부"],"행":[["약성","과거의 정보","기술적 분석 무의미, 기본적 분석·내부정보로는 가능"],["준강성","과거 + 공표된 정보","기술적·기본적 분석 무의미, 내부정보로는 가능"],["강성","과거 + 공표 + 내부정보","어떤 정보로도 불가능"]]}],"함정":"수급조절이 어렵다는 점을 반대로 외운 경우 고른다. 토지는 단기 공급이 고정된다."}},{"i":"S2-1-1-학개론-10","r":"S2","g":1,"c":1,"n":10,"s":"학개론","q":"지대이론에 관한 설명으로 옳은 것은?","b":null,"bs":"없음","img":[],"ch":["튀넨(J. H. von Thünen)의 위치지대설에 따르면, 비옥도 차이에 기초한 지대에 의해 비농업적 토지이용이 결정된다.","마샬(A. Marshall)의 준지대설에 따르면, 생산을 위하여 사람이 만든 기계나 기구들로부터 얻은 일시적인 소득은 준지대에 속한다.","리카도(D. Ricardo)의 차액지대설에서 지대는 토지의 생산성과 운송비의 차이에 의해 결정된다.","마르크스(K. Marx)의 절대지대설에 따르면, 최열등지에서는 지대가 발생하지 않는다.","헤이그(R. Haig)의 마찰비용이론에서 지대는 마찰비용과 교통비의 합으로 산정된다."],"a":[2],"L":"학3-3","o":"기출","x":{"한줄":"마샬의 준지대는 사람이 만든 기계·기구에서 생기는 일시적 소득이다.","근거":[{"이론":"지대이론","내용":"리카도 차액지대(비옥도 차이), 튀넨 위치지대(시장까지의 거리·운송비), 마르크스 절대지대(최열등지에도 발생), 마샬 준지대(인공 자본의 일시적 소득), 헤이그 마찰비용(지대 + 교통비 = 마찰비용)."}],"선지":[{"번호":1,"판정":"틀림","설명":"위치지대설은 시장까지의 거리(운송비 차이)에 기초한다. 비옥도 차이는 리카도다."},{"번호":2,"판정":"옳음","설명":"준지대는 인공물(기계·기구)로부터 얻는 일시적 소득이다."},{"번호":3,"판정":"틀림","설명":"리카도는 비옥도(생산성) 차이로 설명했다. 운송비는 튀넨의 위치지대다."},{"번호":4,"판정":"틀림","설명":"절대지대는 최열등지에도 발생한다. 최열등지에서 지대가 없다는 것은 리카도의 차액지대다."},{"번호":5,"판정":"틀림","설명":"마찰비용(지대 + 교통비) 중 교통비를 뺀 몫이 지대가 된다. 지대는 교통비 절약분이다."}],"개념":[{"종류":"표","제목":"지대이론 비교","머리":["학자","이론","핵심"],"행":[["리카도","차액지대","비옥도 차이, 최열등지는 지대 없음"],["튀넨","위치지대(고립국)","시장까지의 거리에 따른 운송비 차이"],["마르크스","절대지대","사적 소유 자체로 최열등지에도 발생"],["마샬","준지대","인공 자본의 일시적 소득"],["파레토","경제지대","공급이 비탄력적인 생산요소의 대가 중 전용수입 초과분"],["알론소","입찰지대","중심에서 멀어질수록 입찰지대 하락"],["헤이그","마찰비용","지대 + 교통비 = 마찰비용"]]}],"함정":"리카도와 튀넨을 섞는 오답을 고르기 쉽다. 비옥도는 리카도, 운송비는 튀넨이다."}},{"i":"S2-1-1-학개론-11","r":"S2","g":1,"c":1,"n":11,"s":"학개론","q":"토지세를 제외한 다른 모든 조세를 없애고 정부의 재정은 토지세만으로 충당하는 토지단일세를 주장한 학자는?","b":null,"bs":"없음","img":[],"ch":["뢰쉬(A. LÖsch)","레일리(W. Reilly)","알론소 W. Alonso)","헨리 조지(H. George)","버제스(E. Burgess)"],"a":[4],"L":"학3-3","o":"기출","x":{"한줄":"헨리 조지는 토지 지대를 조세로 환수하는 토지단일세를 주장했다.","근거":[{"이론":"헨리 조지의 지대조세론","내용":"지대는 토지 소유자의 노력 없이 생기는 불로소득이므로 토지세 하나로 재정을 충당하고 다른 조세는 폐지하자고 주장했다."}],"선지":[{"번호":1,"판정":"-","설명":"뢰쉬는 수요 원추를 이용한 최대수요이론(공업·시장지역)을 제시했다."},{"번호":2,"판정":"-","설명":"레일리는 소매인력법칙을 제시했다."},{"번호":3,"판정":"-","설명":"알론소는 입찰지대곡선을 제시했다."},{"번호":4,"판정":"-","설명":"토지단일세를 주장한 학자는 헨리 조지다."},{"번호":5,"판정":"-","설명":"버제스는 동심원 도시공간구조이론을 제시했다."}],"개념":[{"종류":"표","제목":"학자별 핵심 이론","머리":["학자","이론","영역"],"행":[["헨리 조지","토지단일세(지대조세론)","지대·조세"],["버제스","동심원이론","도시공간구조"],["호이트","선형이론","도시공간구조"],["해리스·울만","다핵심이론","도시공간구조"],["레일리","소매인력법칙","상업입지"],["알론소","입찰지대","지대·토지이용"],["뢰쉬","최대수요이론","공업입지"]]}],"함정":"토지세와 관련된 학자를 알론소(입찰지대)와 혼동한다. 단일세는 헨리 조지다."}},{"i":"S2-1-1-학개론-12","r":"S2","g":1,"c":1,"n":12,"s":"학개론","q":"베버(A. Weber)의 최소비용이론에 관한 설명으로 틀린 것은? (단, 기업은 단일 입지 공장이고, 다른 조건은 동일함)","b":null,"bs":"없음","img":[],"ch":["최소비용지점은 최소운송비 지점, 최소노동비 지점, 집적이익이 발생하는 구역을 종합적으로 고려해서 결정한다.","등비용선(isodapane)은 최소운송비 지점으로부터 기업이 입지를 바꿀 경우, 운송비와 노동비가 동일한 지점을 연결한 곡선을 의미한다.","원료지수(material index)가 1보다 큰 공장은 원료지향적 입지를 선호한다.","제품 중량이 국지원료 중량보다 큰 제품을 생산하는 공장은 시장지향적 입지를 선호한다.","운송비는 원료와 제품의 무게, 원료와 제품이 수송되는 거리에 의해 결정된다."],"a":[2],"L":"학3-4","o":"기출","x":{"한줄":"등비용선은 최소운송비 지점에서 멀어질 때 추가로 드는 운송비가 같은 지점을 이은 선이다. 운송비와 노동비를 같게 이은 선이 아니다.","근거":[{"이론":"베버의 최소비용이론","내용":"운송비 최소점(입지삼각형)을 기준으로 노동비 절약액과 추가 운송비를 견주고(등비용선·임계등비용선), 집적이익까지 더해 입지를 정한다. 원료지수 = 국지원료 중량 ÷ 제품 중량."}],"선지":[{"번호":1,"판정":"옳음","설명":"운송비, 노동비, 집적이익을 차례로 고려한다."},{"번호":2,"판정":"틀림","설명":"등비용선은 추가 운송비가 같은 지점의 연결선이다."},{"번호":3,"판정":"옳음","설명":"원료지수 > 1이면 원료지향, < 1이면 시장지향."},{"번호":4,"판정":"옳음","설명":"제품이 국지원료보다 무거우면 원료지수가 1 미만이어서 시장지향이다."},{"번호":5,"판정":"옳음","설명":"운송비는 무게와 거리에 비례한다."}],"개념":[{"종류":"흐름","제목":"베버 입지 결정 순서","단계":[{"이름":"최소운송비 지점","설명":"입지삼각형에서 운송비가 가장 적은 지점을 찾는다. 원료지수로 원료지향·시장지향을 판단"},{"이름":"등비용선","설명":"최소운송비 지점에서 멀어질 때 추가 운송비가 같은 지점을 연결"},{"이름":"임계등비용선","설명":"노동비 절약액과 추가 운송비가 같아지는 등비용선"},{"이름":"최소노동비 지점","설명":"임계등비용선 안에 있으면 그 지점으로 이동"},{"이름":"집적이익","설명":"집적으로 비용이 줄면 입지를 다시 조정"}]},{"종류":"표","제목":"원료지수와 입지","머리":["원료지수","의미","입지"],"행":[["MI > 1","국지원료 중량이 제품보다 큼","원료지향"],["MI < 1","제품 중량이 국지원료보다 큼","시장지향"],["MI = 1","양쪽 같음","중간 입지 가능"],["보편원료","어디서나 구함","시장지향(운송비 부담 없음)"]]}],"함정":"등비용선을 운송비와 노동비가 같은 선으로 보는 선택지를 놓친다. 정의는 추가 운송비가 같은 선이다."}},{"i":"S2-1-1-학개론-13","r":"S2","g":1,"c":1,"n":13,"s":"학개론","q":"입지 및 도시공간구조 이론에 관한 설명으로 틀린 것은?","b":null,"bs":"없음","img":[],"ch":["호이트(H. Hoty)의 선형이론은 단핵의 중심지를 가진 동심원 도시구조를 기본으로 하고 있다는 점에서 동심원이론을 발전시킨 것이라 할 수 있다.","크리스탈러(W. Christaller)는 중심성의 크기를 기초로 중심지가 고차중심지와 저차중심지로 구분되는 동심원이론을 설명했다.","해리스(C. Harris)와 울만(E. Ullman))은 도시 내부의 토지이용이 단일한 중심의 주위에 형성되는 것이 아니라 몇 개의 핵심지역 주위에 형성된다는 점을 강조하면서, 도시공간구조가 다핵심구조를 가질 수 있다고 보았다.","베버(A. Weber))는 운송비의 관점에서 특정 공장이 원료지향적인지 또는 시장지향적인지를 판단하기 위해 원료지수(material index)개념을 사용했다.","허프(D. Huff)모형의 공간(거리)마찰계수는 도로환경, 지형, 주행수단 등 다양한 요인에 영향을 받을 수 있는 값이며, 이 모형을 적용하려면 공간(거리)마찰계수가 정해져야 한다."],"a":[2],"L":"학3-4","o":"기출","x":{"한줄":"크리스탈러의 이론은 중심지이론이다. 동심원이론은 버제스의 도시공간구조이론이다.","근거":[{"이론":"도시공간구조이론과 중심지이론","내용":"동심원(버제스), 선형(호이트), 다핵심(해리스·울만)은 도시 내부 구조를, 중심지이론(크리스탈러)은 중심지의 계층과 배후지를 설명한다."}],"선지":[{"번호":1,"판정":"옳음","설명":"선형이론은 동심원 구조에 방사형 교통축의 영향을 더해 발전시켰다."},{"번호":2,"판정":"틀림","설명":"크리스탈러는 중심지이론이다. 동심원이론은 버제스."},{"번호":3,"판정":"옳음","설명":"다핵심이론의 내용이다."},{"번호":4,"판정":"옳음","설명":"원료지수로 원료지향·시장지향을 판단한다."},{"번호":5,"판정":"옳음","설명":"허프모형에서 거리마찰계수는 사전에 정해야 하는 값이다."}],"개념":[{"종류":"표","제목":"도시공간구조 세 이론","머리":["이론","학자","핵심"],"행":[["동심원이론","버제스","중심업무지구 → 점이지대 → 저소득층 주거 → 중산층 주거 → 통근자 주거"],["선형이론","호이트","교통축을 따라 부채꼴로 확장, 소득계층별 주거 분화"],["다핵심이론","해리스·울만","여러 핵심 주위로 토지이용 분화"]]},{"종류":"비교","제목":"중심지이론과 동심원이론","왼쪽":{"이름":"중심지이론(크리스탈러)","항목":["중심지의 계층(고차·저차)과 배후지","육각형 상권, 최소요구치와 도달범위"]},"오른쪽":{"이름":"동심원이론(버제스)","항목":["도시 내부 토지이용이 동심원 띠로 분화","중심업무지구에서 바깥으로 띠 구조"]}}],"함정":"크리스탈러와 버제스의 이론을 섞어 놓은 보기에서 걸린다."}},{"i":"S2-1-1-학개론-14","r":"S2","g":1,"c":1,"n":14,"s":"학개론","q":"크리스탈러(W. Christaller)의 중심지이론에 관한 설명으로 옳은 것은?","b":null,"bs":"없음","img":[],"ch":["최소요구범위 - 중심지 기능이 유지되기 위한 최소한의 수요 요구 규모","최소요구치 - 중심지로부터 어느 기능에 대한 수요가 0이 되는 곳까지의 거리","배후지 - 중심지에 의해 재화와 서비스를 제공받는 주변지역","도달범위 - 판매자가 정상이윤을 얻을 만큼의 충분한 소비자들을 포함하는 경계까지의 거리","중심지 재화 및 서비스 - 배후지에서 중심지로 제공되는 재화 및 서비스"],"a":[3],"L":"학3-4","o":"기출","x":{"한줄":"배후지는 중심지가 재화와 서비스를 공급하는 주변지역이다.","근거":[{"이론":"중심지이론의 용어","내용":"도달범위는 수요가 0이 되는 거리, 최소요구치는 중심지 기능 유지에 필요한 최소 수요 규모, 최소요구범위는 정상이윤을 얻을 만큼의 소비자를 포함하는 경계까지의 거리다."}],"선지":[{"번호":1,"판정":"틀림","설명":"이 서술은 최소요구치의 정의다. 최소요구범위는 정상이윤을 얻을 만큼의 소비자가 있는 경계까지의 거리."},{"번호":2,"판정":"틀림","설명":"수요가 0이 되는 곳까지의 거리는 도달범위다."},{"번호":3,"판정":"옳음","설명":"배후지는 재화·서비스를 공급받는 주변지역이다."},{"번호":4,"판정":"틀림","설명":"이 서술은 최소요구범위의 정의다. 도달범위는 수요가 0이 되는 거리."},{"번호":5,"판정":"틀림","설명":"중심지 재화·서비스는 중심지에서 배후지로 제공된다."}],"개념":[{"종류":"표","제목":"중심지이론 용어","머리":["용어","뜻"],"행":[["중심지","재화·서비스를 공급하는 장소"],["배후지","중심지에서 재화·서비스를 공급받는 주변지역"],["도달범위","중심지로부터 수요가 0이 되는 곳까지의 거리"],["최소요구치","중심지 기능이 유지되기 위한 최소 수요 규모"],["최소요구범위","정상이윤을 얻을 만큼의 소비자를 포함하는 경계까지의 거리"]]},{"종류":"표","제목":"상업입지 이론","머리":["이론","핵심"],"행":[["레일리 소매인력법칙","인구에 비례, 거리의 제곱에 반비례"],["컨버스 분기점","경쟁 도시 상권의 분기점 = 거리 ÷ (1 + √(상대 인구 ÷ 자기 인구))"],["허프 확률모형","점포 면적에 비례, 거리의 마찰계수 제곱에 반비례하여 이용 확률 결정"],["넬슨 입지원칙","상업지 선정 8원칙(접근성·성장 가능성·집적이익 등)"]]}],"함정":"최소요구치, 최소요구범위, 도달범위 정의를 서로 바꿔 놓은 보기가 나란히 있다."}},{"i":"S2-1-1-학개론-15","r":"S2","g":1,"c":1,"n":15,"s":"학개론","q":"정부의 부동산정책에 관한 설명으로 옳은 것은?","b":null,"bs":"없음","img":[],"ch":["개발이익환수제에서 개발이익은 토지 가액의 증가분 전체를 말하며 정상지가상승분을 포함한다.","개발부담금은 국토교통부장관이 부과·징수한다.","토지비축제도는 지가가 상승할 때 토지를 사들이고 하락할 때 팔아 지가를 안정시키는 제도다.","토지거래허가구역은 국토교통부장관 또는 시·도지사가 5년 이내의 기간을 정하여 지정할 수 있다.","공공재는 무임승차 문제 때문에 시장에서 사회적 최적 수준보다 과다하게 공급된다."],"a":[4],"L":"학4-1","o":"변형","x":{"한줄":"토지거래허가구역은 국토교통부장관 또는 시·도지사가 5년 이내의 기간을 정해 지정한다(부동산 거래신고 등에 관한 법률 제10조 제1항).","근거":[{"법령":"부동산 거래신고 등에 관한 법률","조문":"제10조제1항","원문":"국토교통부장관 또는 시ㆍ도지사는 국토의 이용 및 관리에 관한 계획의 원활한 수립과 집행, 합리적인 토지 이용 등을 위하여 토지의 투기적인 거래가 성행하거나 지가(地價)가 급격히 상승하는 지역과 그러한 우려가 있는 지역으로서 대통령령으로 정하는 지역에 대해서는 다음 각 호의 구분에 따라 5년 이내의 기간을 정하여 제11조제1항에 따른 토지거래계약에 관한 허가구역(이하 \"허가구역\"이라 한다)으로 지정할 수 있다."},{"법령":"개발이익 환수에 관한 법률","조문":"제2조제1호·제4호","원문":"\"개발이익\"이란 개발사업의 시행이나 토지이용계획의 변경, 그 밖에 사회적ㆍ경제적 요인에 따라 정상지가(正常地價)상승분을 초과하여 개발사업을 시행하는 자(이하 \"사업시행자\"라 한다)나 토지 소유자에게 귀속되는 토지 가액의 증가분을 말한다. / \"개발부담금\"이란 개발이익 중 이 법에 따라 특별자치시장ㆍ특별자치도지사ㆍ시장ㆍ군수 또는 구청장(구청장은 자치구의 구청장을 말하며, 이하 \"시장ㆍ군수ㆍ구청장\"이라 한다)이 부과ㆍ징수하는 금액을 말한다."}],"선지":[{"번호":1,"판정":"틀림","설명":"개발이익은 정상지가상승분을 초과하는 증가분이다(개발이익 환수에 관한 법률 제2조 제1호)."},{"번호":2,"판정":"틀림","설명":"개발부담금은 시장·군수·구청장이 부과·징수한다(같은 조 제4호)."},{"번호":3,"판정":"틀림","설명":"토지비축은 지가 하락기·안정기에 매입하고 상승기에 매각해 가격을 안정시킨다."},{"번호":4,"판정":"옳음","설명":"부동산 거래신고 등에 관한 법률 제10조 제1항."},{"번호":5,"판정":"틀림","설명":"공공재는 비배제성·비경합성 때문에 무임승차가 생겨 시장에서 과소공급된다."}],"개념":[{"종류":"표","제목":"지정 주체와 근거","머리":["제도","지정·부과 주체","근거"],"행":[["토지거래허가구역","국토교통부장관 또는 시·도지사, 5년 이내","부동산 거래신고 등에 관한 법률 제10조"],["투기과열지구","국토교통부장관 또는 시·도지사","주택법 제63조"],["분양가상한제 적용지역","국토교통부장관","주택법 제57조·제58조"],["개발제한구역","국토교통부장관(도시·군관리계획 결정)","국토의 계획 및 이용에 관한 법률 제38조"],["개발부담금","시장·군수·구청장이 부과·징수","개발이익 환수에 관한 법률 제2조"]]},{"종류":"표","제목":"시장실패 원인과 결과","머리":["원인","시장 결과"],"행":[["정(+)의 외부효과","사회적 최적 수준보다 과소생산"],["부(−)의 외부효과","사회적 최적 수준보다 과다생산"],["공공재(비경합·비배제)","무임승차로 과소공급"],["정보의 비대칭","역선택·도덕적 해이"]]}],"함정":"개발이익의 정의를 정상지가상승분 포함으로 놓는 보기, 부과 주체를 중앙정부로 놓는 보기가 함께 나온다. 정의는 정상지가상승분 초과분, 부과는 시장·군수·구청장이다."}},{"i":"S2-1-1-학개론-16","r":"S2","g":1,"c":1,"n":16,"s":"학개론","q":"정부의 부동산정책에 관한 설명으로 틀린 것은?","b":null,"bs":"없음","img":[],"ch":["시·도지사는 도시의 무질서한 확산을 방지하고 도시 주변의 자연환경을 보전하기 위하여 개발제한구역을 지정할 수 있다.","국토교통부장관 또는 시·도지사는 주택가격의 안정을 위하여 필요한 경우 일정한 지역을 투기과열지구로 지정할 수 있다.","국토는 토지의 이용실태와 특성 등을 고려하여 도시지역, 관리지역, 농림지역, 자연환경보전지역의 용도지역으로 구분한다.","개발이익환수제도는 개발사업으로 정상지가상승분을 초과하여 생긴 개발이익을 개발부담금으로 환수한다.","토지거래허가구역에서 토지 소유권을 유상으로 이전하는 계약을 체결하려면 시장·군수 또는 구청장의 허가를 받아야 한다."],"a":[1],"L":"학4-1","o":"변형","x":{"한줄":"개발제한구역은 국토교통부장관이 도시·군관리계획으로 지정한다(국토의 계획 및 이용에 관한 법률 제38조 제1항).","근거":[{"법령":"국토의 계획 및 이용에 관한 법률","조문":"제38조제1항","원문":"국토교통부장관은 도시의 무질서한 확산을 방지하고 도시주변의 자연환경을 보전하여 도시민의 건전한 생활환경을 확보하기 위하여 도시의 개발을 제한할 필요가 있거나 국방부장관의 요청이 있어 보안상 도시의 개발을 제한할 필요가 있다고 인정되면 개발제한구역의 지정 또는 변경을 도시ㆍ군관리계획으로 결정할 수 있다."},{"법령":"주택법","조문":"제63조제1항","원문":"국토교통부장관 또는 시ㆍ도지사는 주택가격의 안정을 위하여 필요한 경우에는 주거정책심의위원회(시ㆍ도지사의 경우에는 「주거기본법」 제9조에 따른 시ㆍ도 주거정책심의위원회를 말한다. 이하 이 조에서 같다)의 심의를 거쳐 일정한 지역을 투기과열지구로 지정하거나 이를 해제할 수 있다."},{"법령":"국토의 계획 및 이용에 관한 법률","조문":"제6조","원문":"국토는 토지의 이용실태 및 특성, 장래의 토지 이용 방향, 지역 간 균형발전 등을 고려하여 다음과 같은 용도지역으로 구분한다. 1. 도시지역 2. 관리지역 3. 농림지역 4. 자연환경보전지역"}],"선지":[{"번호":1,"판정":"틀림","설명":"지정 주체는 국토교통부장관이다(국토계획법 제38조 제1항)."},{"번호":2,"판정":"옳음","설명":"주택법 제63조 제1항."},{"번호":3,"판정":"옳음","설명":"국토계획법 제6조의 용도지역 네 가지."},{"번호":4,"판정":"옳음","설명":"개발이익 환수에 관한 법률 제2조 제1호, 제4호."},{"번호":5,"판정":"옳음","설명":"부동산 거래신고 등에 관한 법률 제11조 제1항(대가를 받고 이전·설정하는 경우의 허가)."}],"개념":[{"종류":"표","제목":"정책수단 지정권자","머리":["수단","지정권자","근거"],"행":[["개발제한구역","국토교통부장관","국토계획법 제38조"],["투기과열지구","국토교통부장관 또는 시·도지사","주택법 제63조"],["토지거래허가구역","국토교통부장관 또는 시·도지사(허가는 시장·군수·구청장)","부동산 거래신고 등에 관한 법률 제10조·제11조"],["용도지역","도시지역·관리지역·농림지역·자연환경보전지역","국토계획법 제6조"]]},{"종류":"비교","제목":"직접개입과 간접개입","왼쪽":{"이름":"직접개입","항목":["정부가 시장에 직접 참여","토지비축, 공영개발, 공공임대주택 공급"]},"오른쪽":{"이름":"간접개입","항목":["규제·유인으로 민간 행위를 유도","용도지역제, 개발부담금, 토지거래허가구역, 조세"]}}],"함정":"지정권자를 시·도지사로 바꾼 보기를 놓친다. 개발제한구역은 국토교통부장관이 정한다."}},{"i":"S2-1-1-학개론-17","r":"S2","g":1,"c":1,"n":17,"s":"학개론","q":"임대주택정책에 관한 설명으로 옳은 것은? (단, 수요곡선은 우하향하고 공급곡선은 우상향하며, 다른 조건은 동일함)","b":null,"bs":"없음","img":[],"ch":["규제임대료가 균형임대료보다 높은 수준으로 설정되면 임대주택에 초과수요가 발생한다.","임대료 상한 규제가 장기간 유지되면 임대주택의 질이 향상되고 공급량이 늘어난다.","임차인에게 지급하는 임대료 보조금은 임대주택 공급이 고정된 단기에 임대료를 하락시킨다.","임대료 보조는 임대료 규제와 달리 장기에도 임대주택 공급을 감소시킨다.","규제임대료가 균형임대료보다 낮으면 초과수요가 발생하고, 임대인이 유지·보수를 줄여 주택의 질이 떨어질 수 있다."],"a":[5],"L":"학4-2","o":"변형","x":{"한줄":"균형 아래로 임대료 상한을 묶으면 수요량이 공급량보다 많아 초과수요가 생기고, 임대인은 비용을 줄이려 유지·보수를 기피한다.","근거":[{"이론":"임대료 규제의 효과","내용":"규제임대료가 균형임대료보다 낮을 때에만 구속력이 있다. 초과수요, 임대주택 공급 감소, 질 저하, 암시장 발생이 따른다."}],"선지":[{"번호":1,"판정":"틀림","설명":"균형보다 높은 규제임대료는 구속력이 없어 시장임대료가 그대로 유지된다."},{"번호":2,"판정":"틀림","설명":"장기 규제는 신규 공급을 줄이고 유지·보수 부실로 질을 떨어뜨린다."},{"번호":3,"판정":"틀림","설명":"단기에는 공급이 고정되어 있어 수요 증가로 임대료가 오른다."},{"번호":4,"판정":"틀림","설명":"임대료 보조는 수요를 늘려 임대료를 올리므로 장기에는 공급이 증가한다."},{"번호":5,"판정":"옳음","설명":"균형 이하 규제의 대표 효과다."}],"개념":[{"종류":"표","제목":"규제임대료 수준별 효과","머리":["규제임대료","효과"],"행":[["균형임대료보다 높음","구속력 없음, 시장 균형 유지"],["균형임대료보다 낮음","초과수요, 임대주택 공급 감소, 질 저하, 암시장"],["규제 장기화","신규 임대주택 건설 기피, 기존 주택의 전환(매각·용도변경)"]]},{"종류":"비교","제목":"임대료 규제와 임대료 보조","왼쪽":{"이름":"임대료 규제","항목":["가격 상한으로 임차인 부담 직접 낮춤","공급 감소·질 저하 우려"]},"오른쪽":{"이름":"임대료 보조","항목":["수요를 늘려 소득 보전","단기 임대료 상승, 장기 공급 증가"]}}],"함정":"임대료 보조를 규제처럼 공급 감소 정책으로 외우면 틀린다. 장기에는 공급이 늘어난다."}},{"i":"S2-1-1-학개론-18","r":"S2","g":1,"c":1,"n":18,"s":"학개론","q":"분양가상한제에 관한 설명으로 옳은 것은?","b":null,"bs":"없음","img":[],"ch":["분양가상한제는 공공택지에서 공급하는 주택에만 적용할 수 있고 민간택지에는 적용할 수 없다.","공공택지에서 공급하는 도시형 생활주택에도 분양가상한제가 적용된다.","분양가상한제 적용주택의 분양가격은 택지비와 건축비로 구성되며, 토지임대부 분양주택은 건축비만 해당한다.","분양가상한제는 신규 분양주택의 공급을 늘리고 주택의 질을 높이는 효과가 있다.","공공택지 외의 택지에서 분양가상한제 적용 지역은 시·도지사가 지정한다."],"a":[3],"L":"학4-2","o":"변형","x":{"한줄":"분양가격은 택지비와 건축비로 구성되고, 토지임대부 분양주택은 건축비만 해당한다(주택법 제57조 제3항).","근거":[{"법령":"주택법","조문":"제57조제1항","원문":"사업주체가 제54조에 따라 일반인에게 공급하는 공동주택 중 다음 각 호의 어느 하나에 해당하는 지역에서 공급하는 주택의 경우에는 이 조에서 정하는 기준에 따라 산정되는 분양가격 이하로 공급(이에 따라 공급되는 주택을 \"분양가상한제 적용주택\"이라 한다. 이하 같다)하여야 한다. 1. 공공택지 2. 공공택지 외의 택지에서 주택가격 상승 우려가 있어 제58조에 따라 국토교통부장관이 「주거기본법」 제8조에 따른 주거정책심의위원회(이하 \"주거정책심의위원회\"라 한다)의 심의를 거쳐 지정하는 지역"},{"법령":"주택법","조문":"제57조제2항제1호","원문":"제1항에도 불구하고 다음 각 호의 어느 하나에 해당하는 경우에는 제1항을 적용하지 아니한다. 1. 도시형 생활주택"},{"법령":"주택법","조문":"제57조제3항","원문":"제1항의 분양가격은 택지비와 건축비로 구성(토지임대부 분양주택의 경우에는 건축비만 해당한다)되며, 구체적인 명세, 산정방식, 감정평가기관 선정방법 등은 국토교통부령으로 정한다."},{"법령":"주택법","조문":"제58조제1항","원문":"국토교통부장관은 제57조제1항제2호에 따라 주택가격상승률이 물가상승률보다 현저히 높은 지역으로서 그 지역의 주택가격ㆍ주택거래 등과 지역 주택시장 여건 등을 고려하였을 때 주택가격이 급등하거나 급등할 우려가 있는 지역 중 대통령령으로 정하는 기준을 충족하는 지역은 주거정책심의위원회 심의를 거쳐 분양가상한제 적용 지역으로 지정할 수 있다."}],"선지":[{"번호":1,"판정":"틀림","설명":"공공택지 외의 택지도 국토교통부장관이 지정한 지역이면 적용된다(제57조 제1항 제2호)."},{"번호":2,"판정":"틀림","설명":"도시형 생활주택은 적용하지 않는다(제57조 제2항 제1호). 택지 종류와 무관하다."},{"번호":3,"판정":"옳음","설명":"제57조 제3항."},{"번호":4,"판정":"틀림","설명":"분양가를 낮게 묶으면 사업성이 떨어져 신규 공급이 위축되고 질이 하락할 수 있다."},{"번호":5,"판정":"틀림","설명":"지정 주체는 국토교통부장관이다(제58조 제1항)."}],"개념":[{"종류":"표","제목":"분양가상한제 적용 범위","머리":["구분","내용","근거"],"행":[["적용 대상","공공택지에서 공급하는 공동주택","주택법 제57조 제1항 제1호"],["적용 대상","공공택지 외 택지 중 국토교통부장관이 지정한 지역","제57조 제1항 제2호, 제58조"],["적용 제외","도시형 생활주택","제57조 제2항 제1호"],["분양가격 구성","택지비 + 건축비(토지임대부 분양주택은 건축비만)","제57조 제3항"]]},{"종류":"비교","제목":"분양가상한제의 기대와 부작용","왼쪽":{"이름":"기대효과","항목":["분양가 인하로 무주택자의 부담 완화","주택가격 안정"]},"오른쪽":{"이름":"부작용","항목":["사업성 하락으로 신규 공급 위축","주택의 질 저하, 당첨자와 비당첨자 간 격차"]}}],"함정":"공공택지에 한정된다는 보기, 도시형 생활주택까지 적용된다는 보기에 걸린다. 지정 지역은 국토교통부장관이 정한다."}},{"i":"S2-1-1-학개론-19","r":"S2","g":1,"c":1,"n":19,"s":"학개론","q":"부동산조세에 관한 설명으로 옳은 것은? (단, 수요곡선은 우하향하고 공급곡선은 우상향하며, 다른 조건은 동일함)","b":null,"bs":"없음","img":[],"ch":["임대주택에 재산세를 부과하면, 수요가 공급보다 비탄력적일수록 임차인이 부담하는 몫이 커진다.","양도소득세를 중과하면 동결효과로 주택의 공급이 증가한다.","주택 취득세율을 낮추면 주택 수요가 감소한다.","토지 공급의 가격탄력성이 0이면, 토지세는 모두 토지 수요자에게 전가된다.","종합부동산세는 지방세이며 시·군·구가 부과한다."],"a":[1],"L":"학4-3","o":"변형","x":{"한줄":"세금은 더 비탄력적인 쪽이 더 많이 부담한다. 수요가 공급보다 비탄력적이면 임차인이 큰 몫을 진다.","근거":[{"이론":"조세의 전가와 귀착","내용":"수요가 비탄력적일수록 소비자(임차인)가, 공급이 비탄력적일수록 공급자(임대인)가 더 많이 부담한다. 토지 공급이 완전비탄력적이면 세 부담은 모두 토지소유자에게 귀착한다."}],"선지":[{"번호":1,"판정":"옳음","설명":"비탄력적인 쪽이 세 부담을 더 진다."},{"번호":2,"판정":"틀림","설명":"동결효과는 양도세 부담 때문에 처분을 미뤄 공급이 감소하는 현상이다."},{"번호":3,"판정":"틀림","설명":"취득세율 인하는 거래비용을 낮춰 수요를 늘린다."},{"번호":4,"판정":"틀림","설명":"공급이 완전비탄력적이면 토지소유자가 전부 부담한다."},{"번호":5,"판정":"틀림","설명":"종합부동산세는 국세다. 지방세는 취득세·재산세 등."}],"개념":[{"종류":"표","제목":"부동산 세금의 과세단계와 구분","머리":["단계","세목","구분"],"행":[["취득","취득세","지방세"],["보유","재산세","지방세"],["보유","종합부동산세","국세"],["양도","양도소득세","국세"],["양도","지방소득세(양도소득분)","지방세"]]},{"종류":"표","제목":"탄력성에 따른 세 부담","머리":["조건","부담이 큰 쪽"],"행":[["수요가 공급보다 비탄력적","소비자(수요자)"],["공급이 수요보다 비탄력적","공급자"],["공급 완전비탄력(ε=0)","공급자가 전부 부담"],["수요 완전비탄력(ε=0)","수요자가 전부 부담"]]}],"함정":"토지 공급이 비탄력적이면 세금이 수요자에게 넘어간다고 반대로 생각하기 쉽다. 공급이 비탄력적이면 공급자 부담이 커진다."}},{"i":"S2-1-1-학개론-20","r":"S2","g":1,"c":1,"n":20,"s":"학개론","q":"부동산 투자수익률에 관한 설명으로 옳은 것은? (단, 위험회피형 투자자를 가정함)","b":null,"bs":"없음","img":[],"ch":["기대수익률이 요구수익률보다 높을 경우 투자자는 투자가치가 있는 것으로 판단한다.","기대수익률은 투자에 대한 위험이 주어졌을 때, 투자자가 투자부동산에 대하여 자금을 투자하기 위해 충족되어야 할 최소한의 수익률을 말한다.","요구수익률은 투자가 이루어진 후 현실적으로 달성된 수익률을 말한다.","요구수익률은 투자에 수반되는 위험이 클수록 작아진다.","실현수익률은 다른 투자의 기회를 포기한다는 점에서 기회비용이라고도 한다."],"a":[1],"L":"학5-1","o":"기출","x":{"한줄":"기대수익률이 요구수익률보다 높으면 투자가치가 있다고 본다.","근거":[{"이론":"수익률의 구분","내용":"기대수익률은 예상하는 수익률, 요구수익률은 투자자가 최소한 요구하는 수익률(무위험률 + 위험할증률 + 예상인플레이션율), 실현수익률은 투자 후 실제 달성된 수익률이다."}],"선지":[{"번호":1,"판정":"옳음","설명":"기대수익률 > 요구수익률이면 투자한다."},{"번호":2,"판정":"틀림","설명":"이 서술은 요구수익률의 정의다. 기대수익률은 투자로 예상되는 수익률."},{"번호":3,"판정":"틀림","설명":"이 서술은 실현수익률의 정의다. 요구수익률은 투자 전에 최소한 요구하는 수익률."},{"번호":4,"판정":"틀림","설명":"위험이 클수록 위험할증률이 커져 요구수익률은 높아진다."},{"번호":5,"판정":"틀림","설명":"다른 투자 기회를 포기한다는 의미의 기회비용은 요구수익률에 해당한다."}],"개념":[{"종류":"표","제목":"수익률 세 가지","머리":["구분","시점","뜻"],"행":[["기대수익률","투자 전","투자로 예상되는 수익률"],["요구수익률","투자 전","최소한 요구하는 수익률, 기회비용, 위험이 클수록 상승"],["실현수익률","투자 후","실제로 달성된 수익률, 역사적 수익률"]]},{"종류":"표","제목":"투자 결정 기준","머리":["비교","결정"],"행":[["기대수익률 > 요구수익률","투자 채택"],["기대수익률 = 요구수익률","무차별"],["기대수익률 < 요구수익률","투자 기각"],["요구수익률 구성","무위험률 + 위험할증률 + 예상인플레이션율"]]}],"함정":"기대수익률과 요구수익률의 정의를 바꿔 쓴 보기를 고르기 쉽다. 요구수익률은 최소한 요구하는 수익률, 기대수익률은 예상 수익률이다."}},{"i":"S2-1-1-학개론-21","r":"S2","g":1,"c":1,"n":21,"s":"학개론","q":"부동산투자의 수익률과 위험에 관한 설명으로 옳은 것은?","b":null,"bs":"없음","img":[],"ch":["요구수익률은 투자안에서 얻을 것으로 예상되는 수익률로서, 시장이 정해 주는 객관적인 값이다.","분산투자를 하면 비체계적 위험은 줄일 수 있으나, 체계적 위험은 없앨 수 없다.","투자수익률의 표준편차가 클수록 투자위험은 작다.","두 자산 수익률의 상관계수가 +1이면 포트폴리오의 위험분산 효과가 가장 크다.","총자본수익률이 저당수익률보다 낮은 경우, 부채비율을 높이면 지분수익률이 상승한다."],"a":[2],"L":"학5-1","o":"변형","x":{"한줄":"비체계적 위험은 개별 부동산의 고유 요인이라 포트폴리오로 줄어들지만, 체계적 위험은 시장 전체 요인이라 분산해도 남는다.","근거":[{"이론":"투자 위험의 종류","내용":"체계적 위험(시장위험)은 금리·물가·경기처럼 모든 자산에 영향을 주어 분산투자로 제거되지 않는다. 비체계적 위험은 입지·공실·임차인 등 개별 자산 고유의 위험으로 분산투자로 줄어든다."},{"이론":"지렛대 효과","내용":"자기자본수익률 = 총자본수익률 + (총자본수익률 − 저당수익률) × 부채비율. 총자본수익률이 저당수익률보다 낮으면 부(−)의 지렛대 효과가 나타난다."},{"이론":"포트폴리오 이론","내용":"두 자산의 상관계수가 +1이면 같은 방향·같은 비율로 움직여 위험이 줄지 않고, −1일 때 위험 감소 효과가 가장 크다."}],"선지":[{"번호":1,"판정":"틀림","설명":"투자안에서 얻을 것으로 예상되는 수익률은 기대수익률이고 객관적 성격을 띤다. 요구수익률은 투자자가 최소한 받아야 한다고 보는 주관적 수익률이며 무위험률 + 위험할증률 + 예상인플레이션율로 구한다."},{"번호":2,"판정":"옳음","설명":"체계적 위험은 포트폴리오를 어떻게 짜도 남고, 비체계적 위험만 자산 수를 늘려 줄일 수 있다."},{"번호":3,"판정":"틀림","설명":"위험은 분산·표준편차로 측정하며 표준편차가 클수록 수익률 변동이 커서 위험이 크다."},{"번호":4,"판정":"틀림","설명":"상관계수 +1은 두 자산이 완전히 같이 움직이므로 분산효과가 없다. 분산효과는 상관계수 −1에서 가장 크다."},{"번호":5,"판정":"틀림","설명":"총자본수익률 < 저당수익률이면 부(−)의 지렛대 효과다. 이때 부채비율을 높이면 지분수익률이 오히려 떨어진다."}],"개념":[{"종류":"표","제목":"상관계수와 분산투자 효과","머리":["상관계수","두 자산의 움직임","위험 감소 효과"],"행":[["+1","완전히 같은 방향","없음"],["0 초과 1 미만","대체로 같은 방향","일부 감소"],["0","서로 무관","상당히 감소"],["−1","정반대 방향","최대 (위험 0 구성 가능)"]]},{"종류":"비교","제목":"체계적 위험과 비체계적 위험","왼쪽":{"이름":"체계적 위험(시장위험)","항목":["금리·물가·경기 등 시장 전체 요인","분산투자로 제거 불가","요구수익률의 위험할증률에 반영"]},"오른쪽":{"이름":"비체계적 위험(개별위험)","항목":["입지·공실·임차인 등 자산 고유 요인","분산투자로 감소","상관계수가 낮은 자산을 결합할수록 감소"]}}],"함정":"④ 상관계수 부호를 거꾸로 외운 경우에 고른다. +1이 분산효과 0이고 −1이 최대다. ⑤ 정(+)·부(−) 지렛대의 방향을 바꿔 읽으면 부채를 늘릴수록 수익이 오른다고 착각한다. ① 기대수익률과 요구수익률의 정의를 맞바꾼 선지다."}},{"i":"S2-1-1-학개론-22","r":"S2","g":1,"c":1,"n":22,"s":"학개론","q":"화폐의 시간가치 계산에 관한 설명으로 옳은 것은?","b":null,"bs":"없음","img":[],"ch":["현재 10억 원인 아파트가 매년 2 %씩 가격이 상승한다고 가정할 때, 5년 후의 아파트가격을 산정하는 경우 연금의 미래가치계수를 사용한다.","원리금균등상환방식으로 담보대출 받은 가구가 매월 상환할 금액을 산정하는 경우, 일시불의 현재가치계수를 사용한다.","연금의 현재가치계수에 감채기금계수를 곱하면 일시불의 현재가치계수이다.","임대기간 동안 월임대료를 모두 적립할 경우, 이 금액의 현재시점 가치를 산정한다면 감채기금계수를 사용한다.","나대지에 투자하여 5년 후 8억 원에 매각하고 싶은 투자자는 현재 이 나대지의 구입금액을 산정하는 경우, 저당상수를 사용한다."],"a":[3],"L":"학5-2","o":"기출","x":{"한줄":"연금의 현재가치계수에 감채기금계수를 곱하면 (1+r)^-n, 곧 일시불의 현재가치계수가 된다.","근거":[{"이론":"화폐의 시간가치 6계수","내용":"일시불 내가 (1+r)^n, 일시불 현가 1/(1+r)^n, 연금 내가 [(1+r)^n−1]/r, 연금 현가 [1−(1+r)^-n]/r, 감채기금 r/[(1+r)^n−1], 저당상수 r/[1−(1+r)^-n]."},{"이론":"계수 사이의 관계","내용":"감채기금계수는 연금 내가계수의 역수, 저당상수는 연금 현가계수의 역수다. 연금 현가계수 × 감채기금계수 = 일시불 현가계수."}],"선지":[{"번호":1,"판정":"틀림","설명":"현재 가격에서 5년 후 가격을 구하는 것은 한 번의 복리 성장이므로 일시불의 내가계수를 쓴다. 연금의 내가계수는 매기 같은 금액을 모을 때 쓴다."},{"번호":2,"판정":"틀림","설명":"원리금균등상환 대출의 매월 상환액은 대출액에 저당상수를 곱해 구한다. 일시불의 현가계수가 아니다."},{"번호":3,"판정":"옳음","설명":"[1−(1+r)^-n]/r × r/[(1+r)^n−1] = (1+r)^-n 이다. 수치로 확인하면 r=10%, n=2에서 1.7355 × 0.4762 = 0.8264 = 1/1.1²."},{"번호":4,"판정":"틀림","설명":"매기 받는 임대료 전부의 현재시점 가치는 연금의 현재가치계수로 구한다. 감채기금계수는 장래 목표액을 모으기 위해 매기 적립할 금액을 구할 때 쓴다."},{"번호":5,"판정":"틀림","설명":"5년 후 8억 원의 현재 가치는 일시불의 현재가치계수로 구한다. 저당상수는 현재 대출액에서 매기 상환액을 구할 때 쓴다."}],"개념":[{"종류":"표","제목":"6계수의 용도","머리":["계수","구하려는 것","식","역수·관계"],"행":[["일시불의 내가계수","현재 금액의 미래 금액","(1+r)^n","일시불 현가의 역수"],["일시불의 현가계수","미래 금액의 현재 금액","1/(1+r)^n","일시불 내가의 역수"],["연금의 내가계수","매기 금액의 미래 합계","[(1+r)^n−1]/r","감채기금의 역수"],["감채기금계수","목표 금액을 모으는 매기 적립액","r/[(1+r)^n−1]","연금 내가의 역수"],["연금의 현가계수","매기 금액의 현재 합계","[1−(1+r)^-n]/r","저당상수의 역수"],["저당상수","현재 대출액의 매기 상환액","r/[1−(1+r)^-n]","연금 현가의 역수"]]},{"종류":"계산","제목":"연금 현가계수 × 감채기금계수 = 일시불 현가계수 (r=10%, n=2)","단계":[{"설명":"연금의 현재가치계수","식":"[1−1.1^-2] ÷ 0.1","값":"1.7355"},{"설명":"감채기금계수","식":"0.1 ÷ (1.1² − 1)","값":"0.4762"},{"설명":"두 계수의 곱","식":"1.7355 × 0.4762","값":"0.8264"},{"설명":"일시불의 현재가치계수","식":"1 ÷ 1.1²","값":"0.8264"}]}],"함정":"계수 이름과 용도를 짝지어 두지 않으면 ④·⑤처럼 이름만 보고 고른다. 저당상수와 감채기금계수는 이름이 비슷하지만 각각 연금 현가·연금 내가의 역수라서 쓰이는 방향이 반대다."}},{"i":"S2-1-1-학개론-23","r":"S2","g":1,"c":1,"n":23,"s":"학개론","q":"부동산투자분석에 관한 설명으로 옳은 것은?","b":null,"bs":"없음","img":[],"ch":["순영업소득에서 부채서비스액을 빼면 세전현금수지이고, 여기에 영업소득세를 더하면 세후현금수지가 된다.","세전지분복귀액은 순매도소득에 미상환 저당잔금을 더하여 구한다.","투자안의 현금흐름 부호가 여러 번 바뀌어도 내부수익률은 항상 하나만 존재한다.","단순회수기간법은 회수기간 이후의 현금흐름과 화폐의 시간가치를 모두 반영한다.","단일 투자안에서 순현재가치가 0보다 크면 수익성지수는 1보다 크고 내부수익률은 요구수익률보다 크다."],"a":[5],"L":"학5-3","o":"변형","x":{"한줄":"NPV > 0 ⇔ PI > 1 ⇔ IRR > 요구수익률이라서 세 기준은 같은 결론을 낸다.","근거":[{"이론":"영업현금흐름과 지분복귀액","내용":"순영업소득 − 부채서비스액 = 세전현금수지, 세전현금수지 − 영업소득세 = 세후현금수지. 매도가격 − 매도경비 = 순매도소득, 순매도소득 − 미상환 저당잔금 = 세전지분복귀액."},{"이론":"할인현금흐름분석","내용":"NPV = 현금유입 현가 − 현금유출 현가, PI = 현금유입 현가 ÷ 현금유출 현가, IRR은 NPV를 0으로 만드는 할인율이다. NPV = 0일 때 PI = 1이고 IRR = 요구수익률이다."}],"선지":[{"번호":1,"판정":"틀림","설명":"세후현금수지는 세전현금수지에서 영업소득세를 뺀 값이다. 더하지 않는다."},{"번호":2,"판정":"틀림","설명":"순매도소득에서 미상환 저당잔금을 빼야 지분복귀액이 된다. 저당잔금은 갚아야 할 돈이다."},{"번호":3,"판정":"틀림","설명":"부호가 여러 번 바뀌면 내부수익률이 여러 개이거나 아예 없을 수 있다."},{"번호":4,"판정":"틀림","설명":"단순회수기간법은 할인하지 않으며 회수가 끝난 뒤의 현금흐름도 보지 않는다."},{"번호":5,"판정":"옳음","설명":"NPV > 0이면 유입 현가가 유출 현가보다 커서 PI > 1이다. 요구수익률로 할인해 NPV > 0이면 NPV를 0으로 만드는 할인율인 IRR이 요구수익률보다 높다."}],"개념":[{"종류":"흐름","제목":"영업현금흐름 계산 순서","단계":[{"이름":"가능총소득","설명":"임대료 × 임대 단위 수"},{"이름":"유효총소득","설명":"가능총소득 − 공실·불량부채 + 기타소득"},{"이름":"순영업소득","설명":"유효총소득 − 영업경비"},{"이름":"세전현금수지","설명":"순영업소득 − 부채서비스액(원금 + 이자)"},{"이름":"세후현금수지","설명":"세전현금수지 − 영업소득세"}]},{"종류":"표","제목":"투자지표 비교","머리":["구분","NPV","IRR","PI","단순회수기간"],"행":[["구하는 값","유입 현가 − 유출 현가","NPV를 0으로 만드는 할인율","유입 현가 ÷ 유출 현가","투자액을 되찾는 기간"],["할인","요구수익률","—","요구수익률","하지 않음"],["채택 기준","NPV > 0","IRR > 요구수익률","PI > 1","회수기간 < 목표기간"],["회수 후 현금흐름","반영","반영","반영","무시"]]}],"함정":"③ 부호 변화가 잦은 투자안에서 IRR이 하나라고 단정하면 틀린다. ④ 단순회수기간법을 할인법으로 분류하는 오류다. ①·②는 뺄셈과 덧셈을 바꿔 놓은 선지다."}},{"i":"S2-1-1-학개론-24","r":"S2","g":1,"c":1,"n":24,"s":"학개론","q":"부동산투자분석에 관한 설명으로 틀린 것은?","b":null,"bs":"없음","img":[],"ch":["내부수익률은 수익성지수를 0으로, 순현재가치를 1로 만드는 할인율이다.","회계적 이익률법은 현금흐름의 시간적 가치를 고려하지 않는다.","내부수익률법에서는 내부수익률과 요구수익률을 비교하여 투자여부를 결정한다.","순현재가치법, 내부수익률법은 할인현금수지분석법에 해당한다.","담보인정비율(LTV)은 부동산가치에 대한 융자액의 비율이다."],"a":[1],"L":"학5-3","o":"기출","x":{"한줄":"내부수익률은 순현재가치를 0으로, 수익성지수를 1로 만드는 할인율이다.","근거":[{"이론":"내부수익률(IRR)","내용":"유입 현가와 유출 현가를 같게 하는 할인율이다. 따라서 NPV = 0, PI = 1이 된다."},{"이론":"투자분석기법의 분류","내용":"할인법(시간가치 반영): 순현재가치법·내부수익률법·수익성지수법. 비할인법: 단순회수기간법·회계적이익률법·승수법·비율분석법."}],"선지":[{"번호":1,"판정":"틀림","설명":"수익성지수는 1로, 순현재가치는 0으로 만드는 할인율이 내부수익률이다. 0과 1이 바뀌어 있다."},{"번호":2,"판정":"옳음","설명":"회계적이익률법은 회계상 이익을 기준으로 하므로 현금흐름의 시간가치를 반영하지 않는다."},{"번호":3,"판정":"옳음","설명":"IRR이 요구수익률 이상이면 채택하고 미만이면 기각한다."},{"번호":4,"판정":"옳음","설명":"순현재가치법·내부수익률법·수익성지수법이 할인현금수지분석법이다."},{"번호":5,"판정":"옳음","설명":"LTV는 융자액 ÷ 부동산 가치다."}],"개념":[{"종류":"표","제목":"투자분석기법의 분류","머리":["구분","기법","시간가치","특징"],"행":[["할인법","순현재가치법·내부수익률법·수익성지수법","반영","미래 현금흐름을 할인"],["비할인법","단순회수기간법·회계적이익률법","무시","계산은 쉬우나 회수 후 현금흐름을 안 본다"],["어림셈법","승수법·수익률법","무시","소득 한 해분만 사용"],["비율분석법","부채감당률·LTV·DTI·부채비율·채무불이행률","무시","상환능력·위험 점검"]]},{"종류":"표","제목":"세 지표가 만나는 점","머리":["구분","NPV","PI","IRR"],"행":[["채택","0 초과","1 초과","요구수익률 초과"],["무차별","0","1","요구수익률과 같음"],["기각","0 미만","1 미만","요구수익률 미만"],["구하는 값","유입 현가 − 유출 현가","유입 현가 ÷ 유출 현가","NPV를 0으로 만드는 할인율"]]}],"함정":"0과 1을 맞바꾼 선지에 가장 많이 걸린다. NPV의 기준값은 0, PI의 기준값은 1이다."}},{"i":"S2-1-1-학개론-25","r":"S2","g":1,"c":1,"n":25,"s":"학개론","q":"다음 조건의 투자안에 대한 순현재가치(ㄱ)와 수익성지수(ㄴ)는? (단, 현금흐름은 모두 연말에 발생하며, 주어진 조건에 한함)","b":"○ 현재 투자금액: 1억원\n○ 1년 말 현금유입: 6,600만원\n○ 2년 말 현금유입: 7,260만원\n○ 요구수익률: 연 10%","bs":"글자","img":[],"ch":["ㄱ: 1억 2,000만원, ㄴ: 1.20","ㄱ: 2,000만원, ㄴ: 0.20","ㄱ: 2,600만원, ㄴ: 1.26","ㄱ: 2,000만원, ㄴ: 1.20","ㄱ: 3,860만원, ㄴ: 1.39"],"a":[4],"L":"학5-3","o":"변형","x":{"한줄":"현금유입 현가가 1억 2,000만 원이므로 NPV는 2,000만 원, PI는 1.20이다.","근거":[{"이론":"순현재가치와 수익성지수","내용":"NPV = 현금유입의 현가 − 현금유출의 현가, PI = 현금유입의 현가 ÷ 현금유출의 현가. 현가는 요구수익률로 할인한다."}],"선지":[{"번호":1,"판정":"-","설명":"현금유입 현가의 합 1억 2,000만 원을 NPV로 착각한 값이다. 투자금 1억 원을 빼지 않았다."},{"번호":2,"판정":"-","설명":"NPV는 맞지만 PI를 NPV ÷ 투자금(0.20)으로 계산했다. PI는 유입 현가 ÷ 유출 현가다."},{"번호":3,"판정":"-","설명":"2년 말 현금유입을 1년치만 할인(7,260 ÷ 1.1 = 6,600)해서 현가 합이 1억 2,600만 원이 된 값이다."},{"번호":4,"판정":"-","설명":"6,600 ÷ 1.1 + 7,260 ÷ 1.1² = 1억 2,000만 원이므로 NPV 2,000만 원, PI 1.20이다."},{"번호":5,"판정":"-","설명":"할인하지 않고 6,600 + 7,260 = 1억 3,860만 원으로 계산한 값이다."}],"개념":[{"종류":"계산","제목":"순현재가치·수익성지수 계산","단계":[{"설명":"1년 말 현금유입의 현가","식":"6,600 ÷ 1.10","값":"6,000만원"},{"설명":"2년 말 현금유입의 현가","식":"7,260 ÷ 1.10²","값":"6,000만원"},{"설명":"현금유입 현가의 합","식":"6,000 + 6,000","값":"12,000만원"},{"설명":"순현재가치","식":"12,000 − 10,000","값":"2,000만원"},{"설명":"수익성지수","식":"12,000 ÷ 10,000","값":"1.20"},{"설명":"판단","식":"NPV > 0, PI > 1","값":"채택"}]},{"종류":"비교","제목":"순현재가치법과 수익성지수법","왼쪽":{"이름":"순현재가치법(NPV)","항목":["유입 현가 − 유출 현가","금액(원)으로 표시","투자 규모가 크면 값도 커진다","채택 기준 0 초과"]},"오른쪽":{"이름":"수익성지수법(PI)","항목":["유입 현가 ÷ 유출 현가","비율로 표시","투자 규모 차이를 반영하지 못해 NPV법과 순위가 갈릴 수 있다","채택 기준 1 초과"]}}],"함정":"할인 횟수를 틀리는 경우(③)와 할인을 빠뜨리는 경우(⑤)가 가장 흔하다. 2년 말 금액은 두 번 할인한다. PI는 뺄셈이 아니라 나눗셈이다."}},{"i":"S2-1-1-학개론-26","r":"S2","g":1,"c":1,"n":26,"s":"학개론","q":"부동산투자분석 기법에 관한 설명으로 틀린 것은?","b":null,"bs":"없음","img":[],"ch":["순현재가치법과 내부수익률법은 화폐의 시간가치를 반영한 투자분석방법이다.","복수의 투자안을 비교할 때 투자금액의 차이가 큰 경우, 순현재가치법과 내부수익률법은 분석결과가 서로 다를 수 있다.","하나의 투자안에 있어 수익성 지수가 1보다 크면 순현재가치는 0보다 크다.","투자자산의 현금흐름에 따라 복수의 내부수익률이 존재할 수 있다.","내부수익률법에서는 현금흐름의 재투자율로 투자자의 요구수익률을 가정한다."],"a":[5],"L":"학5-3","o":"기출","x":{"한줄":"내부수익률법은 현금흐름의 재투자율을 내부수익률로 가정하고, 순현재가치법은 요구수익률로 가정한다.","근거":[{"이론":"NPV법과 IRR법의 재투자율 가정","내용":"NPV법: 중간 현금흐름을 요구수익률로 재투자한다고 가정한다. IRR법: 내부수익률로 재투자한다고 가정한다."},{"이론":"IRR의 한계","내용":"현금흐름의 부호가 여러 번 바뀌면 내부수익률이 여럿이거나 없을 수 있다. 투자규모·현금흐름 시점이 다른 상호배타적 투자안은 NPV법과 IRR법의 결론이 다를 수 있다."}],"선지":[{"번호":1,"판정":"옳음","설명":"두 방법 모두 현금흐름을 할인해 시간가치를 반영한다."},{"번호":2,"판정":"옳음","설명":"투자금액 차이가 크면 NPV가 큰 안과 IRR이 높은 안이 달라질 수 있다."},{"번호":3,"판정":"옳음","설명":"PI > 1이면 유입 현가가 유출 현가보다 크므로 NPV > 0이다."},{"번호":4,"판정":"옳음","설명":"부호가 여러 번 바뀌는 현금흐름에서는 내부수익률이 복수로 존재할 수 있다."},{"번호":5,"판정":"틀림","설명":"내부수익률법의 재투자율 가정은 내부수익률이다. 요구수익률을 재투자율로 보는 쪽은 순현재가치법이다."}],"개념":[{"종류":"비교","제목":"순현재가치법과 내부수익률법","왼쪽":{"이름":"순현재가치법","항목":["할인율은 요구수익률","재투자율은 요구수익률","가치가산의 원리 성립","결과는 금액"]},"오른쪽":{"이름":"내부수익률법","항목":["구하려는 값이 할인율","재투자율은 내부수익률","가치가산의 원리 불성립","복수의 IRR이 있거나 없을 수 있다"]}},{"종류":"표","제목":"두 방법의 결론이 갈리는 경우","머리":["상황","NPV법","IRR법","우선하는 기준"],"행":[["투자 규모 차이가 큰 상호배타 안","NPV가 큰 안","IRR이 높은 안","NPV법(부의 극대화)"],["현금흐름 시점이 다른 안","요구수익률로 재투자 가정","내부수익률로 재투자 가정","NPV법"],["부호가 여러 번 바뀌는 안","하나의 값","복수 또는 없음","NPV법"],["재투자율 가정","요구수익률","내부수익률","—"]]}],"함정":"⑤처럼 재투자율을 서로 바꿔 놓는 선지에 걸린다. 요구수익률 = NPV법, 내부수익률 = IRR법으로 묶어 둔다."}},{"i":"S2-1-1-학개론-27","r":"S2","g":1,"c":1,"n":27,"s":"학개론","q":"甲은 주택구입을 위해 연초에 9억원을 대출받았다. 甲이 받은 대출조건이 다음과 같을 때, 대출금리( ㄱ )와 10회차 이자납부액( ㄴ )은? (단, 주어진 조건에 한함)","b":"○ 대출금리방식: 고정금리\n○ 대출기간: 30년\n○ 원리금 상환조건: 원금균등분할상환방식, 매년 말 연단위로 상환\n○ 1회차 원리금상환액: 5,700만원","bs":"글자","img":[],"ch":["ㄱ: 연 3%, ㄴ: 1,710만원","ㄱ: 연 3%, ㄴ: 1,800만원","ㄱ: 연 3%, ㄴ: 1,890만원","ㄱ: 연 4%, ㄴ: 2,450만원","ㄱ: 연 4%, ㄴ: 2,520만원"],"a":[3],"L":"학6-1","o":"기출","x":{"한줄":"원금균등 연 원금 3,000만 원과 1회차 이자 2,700만 원에서 금리 3%를 얻고, 10회차 이자는 잔금 6억 3,000만 원의 3%인 1,890만 원이다.","근거":[{"이론":"원금균등분할상환","내용":"매기 원금상환액 = 대출액 ÷ 상환횟수. 이자 = 기초 잔금 × 금리. 원리금은 이자가 줄어드는 만큼 매기 감소한다."}],"선지":[{"번호":1,"판정":"-","설명":"1,710만 원은 잔금 5억 7,000만 원의 3%로, 12회차 이자다."},{"번호":2,"판정":"-","설명":"1,800만 원은 잔금 6억 원의 3%로, 11회차 이자다."},{"번호":3,"판정":"-","설명":"금리 3%, 10회차 이자 6억 3,000만 원 × 3% = 1,890만 원이다."},{"번호":4,"판정":"-","설명":"연 4%이면 1회차 원리금이 3,000 + 3,600 = 6,600만 원이 되어 조건과 맞지 않고, 2,450만 원은 어느 회차의 이자와도 맞지 않는다."},{"번호":5,"판정":"-","설명":"연 4%이면 1회차 원리금이 6,600만 원이라 조건과 맞지 않는다. 10회차 이자 2,520만 원은 4%를 가정할 때의 값이다."}],"개념":[{"종류":"계산","제목":"10회차 이자납부액 구하기","단계":[{"설명":"연간 원금상환액","식":"9억 ÷ 30","값":"3,000만원"},{"설명":"1회차 이자","식":"5,700 − 3,000","값":"2,700만원"},{"설명":"대출금리","식":"2,700 ÷ 90,000","값":"3%"},{"설명":"9회까지 상환한 원금","식":"3,000 × 9","값":"2억 7,000만원"},{"설명":"10회차 기초 잔금","식":"9억 − 2억 7,000만","값":"6억 3,000만원"},{"설명":"10회차 이자","식":"6억 3,000만 × 3%","값":"1,890만원"}]},{"종류":"표","제목":"상환방식 비교","머리":["구분","원리금균등","원금균등","만기일시"],"행":[["매기 원금","점차 증가","일정","만기에 전액"],["매기 이자","점차 감소","점차 감소","일정 (잔금이 그대로)"],["매기 원리금","일정","점차 감소","이자만 납부"],["초기 상환부담","원금균등보다 작음","가장 큼","이자만이라 가장 작음"],["총 이자","원금균등보다 많음","균등 방식 중 작음","가장 많음"]]}],"함정":"회차를 하나 틀리면 ①(12회차)·②(11회차) 값이 나온다. 10회차 이자는 9회까지 상환한 뒤의 잔금에 곱한다. 연 4%는 1회차 원리금 6,600만 원이 되어 조건에 어긋난다."}},{"i":"S2-1-1-학개론-28","r":"S2","g":1,"c":1,"n":28,"s":"학개론","q":"주택담보대출에 관한 설명으로 틀린 것은?","b":null,"bs":"없음","img":[],"ch":["담보인정비율(LTV)은 주택담보대출 취급시 담보가치에 대한 대출취급가능금액의 비율을 말한다.","총부채상환비율(DTI)은 차주의 소득을 중심으로 대출규모를 결정하는 기준이다.","담보인정비율이나 총부채상환비율에 대한 구체적인 기준은 한국은행장이 정하는 기준에 의한다.","총부채원리금상환비율(DSR)은 차주의 총 금융부채 상환부담을 판단하기 위하여 산정하는 차주의 연간 소득대비 연간 금융부채 원리금 상환액 비율을 말한다.","변동금리 주택담보대출은 이자율 변동으로 인한 위험을 차주에게 전가하는 방식으로 금융기관의 이자율 변동위험을 줄일 수 있다."],"a":[3],"L":"학6-1","o":"기출","x":{"한줄":"LTV·DTI의 구체적 기준은 한국은행장이 아니라 금융위원회 등 금융감독 당국의 규정으로 정한다.","근거":[{"이론":"주택담보대출 규제비율","내용":"LTV = 대출액 ÷ 담보가치, DTI = (주택담보대출 연 원리금 + 기타 부채 연 이자) ÷ 연소득, DSR = 모든 금융부채의 연 원리금 ÷ 연소득. 비율 기준은 금융감독 당국이 정한다."},{"이론":"변동금리 대출","내용":"이자율 변동 위험을 차주에게 넘기므로 금융기관의 이자율 위험이 줄어든다."}],"선지":[{"번호":1,"판정":"옳음","설명":"LTV는 담보가치에 대한 대출 가능 금액의 비율이다."},{"번호":2,"판정":"옳음","설명":"DTI는 차주의 소득을 중심으로 대출규모를 정하는 기준이다."},{"번호":3,"판정":"틀림","설명":"LTV·DTI 기준은 금융위원회 등 금융감독 당국이 정한다. 한국은행장이 정하는 기준이 아니다."},{"번호":4,"판정":"옳음","설명":"DSR은 연소득 대비 모든 금융부채의 연간 원리금 상환액 비율이다."},{"번호":5,"판정":"옳음","설명":"변동금리 대출은 금리 변동 위험이 차주에게 넘어가므로 금융기관의 위험이 줄어든다."}],"개념":[{"종류":"표","제목":"LTV·DTI·DSR 비교","머리":["구분","LTV","DTI","DSR"],"행":[["기준이 되는 것","담보가치(자산)","소득","소득"],["식","대출액 ÷ 담보가치","(주택담보대출 연 원리금 + 기타 부채 연 이자) ÷ 연소득","모든 금융부채 연 원리금 ÷ 연소득"],["반영하는 부채","해당 대출","주택담보대출 원리금 + 기타 부채 이자","모든 금융부채 원리금"],["기준을 정하는 곳","금융위원회 등 금융감독 당국","금융위원회 등 금융감독 당국","금융위원회 등 금융감독 당국"]]},{"종류":"비교","제목":"고정금리와 변동금리","왼쪽":{"이름":"고정금리","항목":["금리 변동 위험은 금융기관 부담","금리 하락기에 차주 불리","변동금리보다 초기 금리가 높은 편"]},"오른쪽":{"이름":"변동금리","항목":["금리 변동 위험을 차주에 전가","금융기관의 이자율 위험 감소","초기 금리가 낮은 편"]}}],"함정":"③은 기관 이름만 바꾼 선지다. 한국은행은 통화정책 기관이고 LTV·DTI 기준은 금융감독 규정으로 정한다. ⑤는 위험이 차주에게 넘어간다는 점에서 맞는 문장이다."}},{"i":"S2-1-1-학개론-29","r":"S2","g":1,"c":1,"n":29,"s":"학개론","q":"저당담보부증권(MBS)의 가격변동에 관한 설명으로 옳은 것은? (단, 주어진 조건에 한함)","b":null,"bs":"없음","img":[],"ch":["투자자들이 가까운 시일에 채권시장 수익률의 하락을 예상한다면, 가중평균상환기간(duration)이 긴 저당담보부증권일수록 그 가격이 더 크게 하락한다.","채무불이행위험이 없는 저당담보부증권의 가격은 채권시장 수익률의 변동에 영향을 받지 않는다.","자본시장 내 다른 투자수단들과 경쟁하므로, 동일위험수준의 다른 투자수단들의 수익률이 상승하면 저당담보부증권의 가격은 상승한다.","채권시장 수익률이 상승할 때 가중평균상환기간이 긴 저당담보부증권일수록 그 가격의 변동 정도가 작다.","고정이자를 지급하는 저당담보부증권은 채권시장 수익률이 상승하면 그 가격이 하락한다."],"a":[5],"L":"학6-2","o":"기출","x":{"한줄":"고정이자를 지급하는 증권은 시장수익률이 오르면 현재가치가 줄어 가격이 하락한다.","근거":[{"이론":"MBS 가격과 시장수익률","내용":"MBS 가격은 미래 현금흐름의 현재가치다. 시장수익률(할인율)이 오르면 가격이 하락하고, 내리면 상승한다. 듀레이션이 긴 증권일수록 가격 변동폭이 크다."}],"선지":[{"번호":1,"판정":"틀림","설명":"시장수익률 하락이 예상되면 가격이 오른다. 듀레이션이 긴 증권일수록 상승폭이 더 크다."},{"번호":2,"판정":"틀림","설명":"채무불이행 위험이 없어도 할인율인 시장수익률이 변하면 가격이 변한다."},{"번호":3,"판정":"틀림","설명":"동일위험 투자수단의 수익률이 오르면 MBS의 할인율도 올라 가격이 내린다."},{"번호":4,"판정":"틀림","설명":"듀레이션이 긴 증권일수록 시장수익률 변동에 따른 가격 변동폭이 크다."},{"번호":5,"판정":"옳음","설명":"고정이자 MBS는 시장수익률이 오르면 가격이 하락한다."}],"개념":[{"종류":"표","제목":"시장수익률과 MBS 가격","머리":["상황","MBS 가격","듀레이션이 긴 증권","비고"],"행":[["시장수익률 상승","하락","하락폭 더 큼","할인율 상승"],["시장수익률 하락","상승","상승폭 더 큼","할인율 하락"],["동일위험 다른 투자수단 수익률 상승","하락","하락폭 더 큼","경쟁 투자수단 수익률은 할인율에 반영"],["채무불이행 위험 없음","시장수익률 영향은 그대로 받음","—","위험은 요구금리에 반영"]]},{"종류":"비교","제목":"MBS 세 가지","왼쪽":{"이름":"MPTS(지분형)","항목":["저당채권 소유권은 투자자","원리금 수취권은 투자자","조기상환위험은 투자자","초과담보 없음"]},"오른쪽":{"이름":"MBB(채권형)","항목":["소유권·원리금 수취권은 발행자","조기상환위험은 발행자","발행자가 초과담보 제공","MPTB는 소유권은 발행자, 수취권·조기상환위험은 투자자"]}}],"함정":"방향을 잘못 읽는 경우가 대부분이다. 수익률(할인율)과 가격은 반대로 움직인다. 듀레이션은 변동폭의 크기만 키우고 방향은 바꾸지 않는다."}},{"i":"S2-1-1-학개론-30","r":"S2","g":1,"c":1,"n":30,"s":"학개론","q":"부동산투자회사법령상 부동산투자회사에 관한 설명으로 옳은 것은?","b":null,"bs":"없음","img":[],"ch":["위탁관리 부동산투자회사는 직원을 고용하거나 상근 임원을 둘 수 없으며, 자산의 투자·운용업무는 자산관리회사에 위탁하여야 한다.","자기관리 부동산투자회사는 영업인가를 받은 날부터 6개월이 지나면 자본금이 50억원 이상이 되어야 한다.","부동산투자회사는 부동산을 현물출자 받는 방법으로 발기설립할 수 있다.","주주 1인과 그 특별관계자는 주식 공모를 완료한 이후 발행주식 총수의 100분의 30을 초과하여 소유할 수 없다.","자기관리 부동산투자회사는 해당 연도 이익배당한도의 100분의 90 이상을 반드시 배당하여야 한다."],"a":[1],"L":"학6-3","o":"변형","x":{"한줄":"위탁관리 부동산투자회사는 본점 외 지점, 직원, 상근 임원을 둘 수 없고 투자·운용업무를 자산관리회사에 맡긴다.","근거":[{"법령":"부동산투자회사법","조문":"제11조의2","원문":"위탁관리 부동산투자회사는 본점 외의 지점을 설치할 수 없으며, 직원을 고용하거나 상근 임원을 둘 수 없다."},{"법령":"부동산투자회사법","조문":"제22조의2제1항","원문":"① 위탁관리 부동산투자회사는 자산의 투자ㆍ운용업무는 자산관리회사에 위탁하여야 하고, 주식발행업무 및 일반적인 사무는 대통령령으로 정하는 요건을 갖춘 기관(이하 \"일반사무등 위탁기관\"이라 한다)에 위탁하여야 한다."},{"법령":"부동산투자회사법","조문":"제10조","원문":"  1. 자기관리 부동산투자회사: 70억원\n  2. 위탁관리 부동산투자회사 및 기업구조조정 부동산투자회사: 50억원"},{"법령":"부동산투자회사법","조문":"제5조제1항·제2항","원문":"① 부동산투자회사는 발기설립의 방법으로 하여야 한다.\n② 부동산투자회사는 「상법」 제290조제2호에도 불구하고 현물출자에 의한 설립을 할 수 없다."},{"법령":"부동산투자회사법","조문":"제15조제1항","원문":"① 주주 1인과 그 특별관계자는 제14조의8제2항에 따른 주식의 공모를 완료한 이후에는 부동산투자회사가 발행한 주식 총수의 100분의 50(이하 \"1인당 주식소유한도\"라 한다)을 초과하여 주식을 소유하지 못한다."},{"법령":"부동산투자회사법","조문":"제28조제1항","원문":"① 부동산투자회사는 「상법」 제462조제1항에 따른 해당 연도 이익배당한도[자산의 평가손실(직전 사업연도까지 누적된 평가손실을 포함한다)은 고려하지 아니한다. 이하 이 조 및 제52조에서 같다]의 100분의 90 이상을 주주에게 배당하여야 한다."},{"법령":"부동산투자회사법","조문":"제28조제2항","원문":"② 제1항에도 불구하고 자기관리 부동산투자회사의 경우 「상법」 제462조제1항에 따른 해당 연도 이익배당한도의 100분의 50 이상을 주주에게 배당하여야 하며"}],"선지":[{"번호":1,"판정":"옳음","설명":"위탁관리 REIT는 지점 설치, 직원 고용, 상근 임원 선임이 모두 금지되고(제11조의2), 투자·운용은 자산관리회사에 위탁한다(제22조의2제1항)."},{"번호":2,"판정":"틀림","설명":"영업인가 후 6개월이 지난 자기관리 REIT의 최저자본금은 70억원이다. 50억원은 위탁관리·기업구조조정 REIT의 금액이다(제10조)."},{"번호":3,"판정":"틀림","설명":"부동산투자회사는 발기설립으로만 설립하며, 현물출자에 의한 설립은 할 수 없다(제5조제1항·제2항)."},{"번호":4,"판정":"틀림","설명":"1인당 주식소유한도는 발행주식 총수의 100분의 50이다(제15조제1항)."},{"번호":5,"판정":"틀림","설명":"100분의 90 이상 배당이 원칙이지만, 자기관리 REIT는 100분의 50 이상 배당하면 된다(제28조제2항). 50% 이상 90% 미만으로 정하려면 주주총회 특별결의가 필요하다."}],"개념":[{"종류":"표","제목":"부동산투자회사 종류별 비교","머리":["구분","자기관리","위탁관리","기업구조조정"],"행":[["자산의 투자·운용","직접 수행","자산관리회사에 위탁","자산관리회사에 위탁"],["설립 자본금","5억원 이상","3억원 이상","3억원 이상"],["최저자본금 (영업인가 후 6개월 경과)","70억원","50억원","50억원"],["직원·상근 임원","상근 임직원과 자산운용 전문인력을 둔다","직원 고용·상근 임원 불가","—"],["이익배당","이익배당한도의 50% 이상","이익배당한도의 90% 이상","이익배당한도의 90% 이상"]]},{"종류":"표","제목":"공통으로 외울 수치","머리":["항목","기준","조문"],"행":[["법인격","주식회사, 발기설립만 가능, 현물출자 설립 불가","제3조·제5조"],["1인당 주식소유한도","주주 1인과 특별관계자는 발행주식 총수의 100분의 50 이하","제15조제1항"],["자산구성","매 분기 말 총자산의 100분의 80 이상을 부동산·부동산 관련 증권·현금으로, 그중 100분의 70 이상은 부동산","제25조제1항"],["차입·사채","자기자본의 2배 이내, 주주총회 특별결의 시 10배 이내","제29조제2항"],["자산운용 전문인력(자기관리)","감정평가사·공인중개사로서 해당 분야 5년 이상 종사한 사람 등을 상근으로 둔다","제22조제1항"]]}],"함정":"설립 자본금(자기관리 5억, 나머지 3억)과 최저자본금(70억, 50억)을 섞으면 ②에서 걸린다. 배당은 90%가 원칙이고 자기관리만 50%로 낮아진다. 지분 한도는 50%다.","개정":"제15조제1항 1인당 주식소유한도는 2025.5.27 개정 조문이며 현행 한도는 100분의 50이다. 옛 기출 풀이의 수치와 다르면 현행 수치를 따른다."}},{"i":"S2-1-1-학개론-31","r":"S2","g":1,"c":1,"n":31,"s":"학개론","q":"부동산개발사업에 관한 설명으로 틀린 것은?","b":null,"bs":"없음","img":[],"ch":["부동산개발의 타당성분석 과정에서 시장분석을 수행하기 위해서는 먼저 시장지역을 설정하여야 한다.","부동산개발업의 관리 및 육성에 관한 법령상 건축물을 리모델링 또는 용도변경하는 행위(다만, 시공을 담당하는 행위는 제외한다)는 부동산개발에 포함된다.","민간투자사업에 있어 민간사업자가 자금을 조달하여 시설을 건설하고 일정기간 소유 및 운영을 한 후 국가 또는 지방자치단체에게 시설의 소유권을 이전하는 방식은 BOT(build-operate-transfer)방식이다.","부동산개발의 유형을 신개발방식과 재개발방식으로 구분하는 경우, 도시 및 주거환경정비법령상 재건축사업은 재개발방식에 속한다.","개발사업의 방식 중 사업위탁방식과 신탁개발방식의 공통점은 토지소유자가 개발사업의 전문성이 있는 제3자에게 토지소유권을 이전하고 사업을 위탁하는 점이다."],"a":[5],"L":"학7-1","o":"기출","x":{"한줄":"사업위탁방식은 토지소유권을 넘기지 않고 사업만 맡기고, 신탁개발방식은 토지소유권을 수탁자에게 이전한다.","근거":[{"이론":"개발사업의 방식","내용":"사업위탁방식: 토지소유자가 개발업자에게 사업 수행을 위탁하고 수수료를 지급하며 소유권은 소유자가 보유한다. 신탁개발방식: 토지를 신탁회사에 신탁(소유권 이전)하고 신탁회사가 개발·관리·처분한다."},{"이론":"민간투자사업 방식","내용":"BOT는 민간이 건설(Build)하고 소유·운영(Operate)한 뒤 소유권을 이전(Transfer)한다. BTO는 건설 후 소유권을 먼저 이전하고 운영한다."}],"선지":[{"번호":1,"판정":"옳음","설명":"타당성분석의 시장분석은 시장지역(영향권)을 설정하는 것에서 시작한다."},{"번호":2,"판정":"옳음","설명":"개발업법상 부동산개발에는 건축물의 건축·대수선·리모델링·용도변경과 공작물 설치가 포함되며, 시공을 담당하는 행위는 제외된다."},{"번호":3,"판정":"옳음","설명":"BOT는 건설 → 소유·운영 → 이전 순서다."},{"번호":4,"판정":"옳음","설명":"신개발방식과 재개발방식으로 나눌 때 재건축·재개발 등 정비사업은 재개발방식에 속한다."},{"번호":5,"판정":"틀림","설명":"사업위탁방식에서는 토지소유권이 이전되지 않는다. 소유권을 이전하는 방식은 신탁개발방식이다."}],"개념":[{"종류":"표","제목":"개발사업 방식 비교","머리":["방식","토지 소유권","사업 주체","대가·수익"],"행":[["자체개발","소유자 보유","소유자","개발이익 전부 소유자"],["사업위탁(수탁)","소유자 보유","개발업자가 위탁받아 수행","소유자가 수수료 지급"],["신탁개발","수탁자에게 이전","신탁회사","수익자에게 신탁수익 배분"],["토지소유자·개발업자 공동","각자 보유 후 개발","공동 (지분 또는 분양수익 배분)","합의한 비율로 배분"]]},{"종류":"표","제목":"민간투자사업 방식","머리":["방식","순서","소유권 이전 시점"],"행":[["BTO","건설 → 이전 → 운영","준공 직후"],["BOT","건설 → 소유·운영 → 이전","운영기간 종료 후"],["BTL","건설 → 이전 → 임대(정부가 임차료 지급)","준공 직후"],["BOO","건설 → 소유·운영","이전 없음"]]}],"함정":"⑤는 사업위탁과 신탁을 같은 것으로 묶은 선지다. 소유권 이전 여부가 둘을 가른다. ④는 재건축이 신규 택지 조성이 아니라 기존 지역을 다시 정비하는 사업이라는 점에서 재개발방식으로 분류한다."}},{"i":"S2-1-1-학개론-32","r":"S2","g":1,"c":1,"n":32,"s":"학개론","q":"부동산개발의 위험에 관한 설명으로 옳은 것은?","b":null,"bs":"없음","img":[],"ch":["정책 변화로 생기는 인·허가 지연위험은 개발업자가 사업계획을 조정하여 스스로 통제할 수 있는 위험이다.","개발대상 토지를 이용계획이 확정된 뒤에 매입하면 법률위험을 줄일 수 있다.","개발사업의 기간이 길어질수록 시장위험에 노출되는 정도는 줄어든다.","워포드(L. Wofford)는 개발위험을 법률위험, 시장위험, 비용위험으로 나누었으며, 분양가 하락과 같은 수요 변화는 비용위험에 속한다.","실비정산 보수가산식 공사계약은 공사비 초과위험을 시공자에게 넘기는 수단이다."],"a":[2],"L":"학7-1","o":"변형","x":{"한줄":"이용계획이 확정된 토지를 사면 용도변경·인허가 불확실성이 줄어 법률위험이 낮아진다.","근거":[{"이론":"워포드의 개발위험 구분","내용":"법률위험(인허가·용도지역·소송 등), 시장위험(수요·분양가·임대료·금리 변동), 비용위험(공사비 상승·공기 지연·이자비용 증가)으로 나눈다."},{"이론":"위험 처리 방법","내용":"위험회피(위험이 큰 사업을 하지 않음), 위험보유(스스로 부담), 위험전가(계약으로 상대방에게 넘김), 위험분담(공동 부담)."},{"이론":"공사계약과 비용위험","내용":"정액(확정금액) 도급은 비용위험을 시공자에게 넘기고, 실비정산 보수가산식은 비용 증가분을 발주자가 부담하므로 비용위험이 발주자에게 남는다."}],"선지":[{"번호":1,"판정":"틀림","설명":"정책·행정 변화로 인한 인허가 지연은 개발업자가 통제할 수 없는 위험이다. 관리 가능한 위험이 아니다."},{"번호":2,"판정":"옳음","설명":"용도지역·지구 변경, 건축허가 같은 이용계획이 확정된 토지를 사면 법률위험이 줄어든다."},{"번호":3,"판정":"틀림","설명":"개발기간이 길수록 수요·금리·분양가 변동에 노출되는 시간이 늘어 시장위험이 커진다."},{"번호":4,"판정":"틀림","설명":"워포드의 3분류는 맞지만 분양가 하락·수요 변화는 시장위험에 속한다. 비용위험은 공사비·공기·금융비용 증가다."},{"번호":5,"판정":"틀림","설명":"실비정산 보수가산식은 실제 공사비를 발주자가 부담하므로 비용위험이 발주자에게 남는다. 시공자에게 넘기는 방식은 정액 도급이다."}],"개념":[{"종류":"표","제목":"워포드의 개발위험 3유형","머리":["유형","내용","예","줄이는 방법"],"행":[["법률위험","법령·행정 변화, 인허가 불확실","용도변경 불허, 허가 지연, 소송","이용계획이 확정된 토지 매입, 인허가 후 착공"],["시장위험","수요·가격·금리 변동","분양률 하락, 임대료 하락, 금리 상승","시장분석, 단계별 개발, 사전 분양·임대"],["비용위험","개발비용 증가","공사비 상승, 공기 지연, 이자비용 증가","정액 도급, 공사 지연 보증, 예비비"]]},{"종류":"표","제목":"위험 처리 방법","머리":["방법","내용","예"],"행":[["위험회피","위험이 큰 사업을 하지 않는다","인허가가 불확실한 토지는 매입하지 않음"],["위험보유","발생 손실을 스스로 부담한다","예상 가능한 소액 비용은 예비비로 처리"],["위험전가","계약으로 상대방에게 넘긴다","정액 도급, 보험·보증"],["위험분담","여러 주체가 나누어 부담한다","공동개발, 컨소시엄, PF 참여자 분담"]]}],"함정":"②와 ④가 가장 가깝다. 수요 변화·가격 변동은 시장위험이고 공사비 증가는 비용위험이다. ⑤는 어느 계약 방식에서 위험이 누구에게 남는지를 물은 것이다."}},{"i":"S2-1-1-학개론-33","r":"S2","g":1,"c":1,"n":33,"s":"학개론","q":"부동산마케팅 전략에 관한 설명으로 틀린 것은?","b":null,"bs":"없음","img":[],"ch":["시장점유 전략은 수요자 측면의 접근으로 목표시장을 선점하거나 점유율을 높이는 것을 말한다.","적응가격 전략이란 동일하거나 유사한 제품으로 다양한 수요자들의 구매를 유입하고, 구매량을 늘리도록 유도하기 위하여 가격을 다르게 하여 판매하는 것을 말한다.","마케팅믹스란 기업의 부동산 상품이 표적시장에 도달하기 위해 이용하는 마케팅에 관련된 여러 요소들의 조합을 말한다.","시장세분화 전략이란 수요자 집단을 인구ㆍ경제적 특성에 따라 세분하고, 세분된 시장에서 상품의 판매지향점을 분명히 하는 것을 말한다.","고객점유 전략은 소비자의 구매의사결정 과정의 각 단계에서 소비자와의 심리적인 접점을 마련하고 전달하려는 정보의 취지와 강약을 조절하는 것을 말한다."],"a":[1],"L":"학7-2","o":"기출","x":{"한줄":"시장점유 전략은 공급자 측면의 접근이고, 소비자 구매과정에 초점을 두는 것은 고객점유 전략이다.","근거":[{"이론":"부동산 마케팅 전략의 구분","내용":"시장점유 전략(공급자 중심): STP와 4P Mix로 목표시장을 선점하고 점유율을 높인다. 고객점유 전략(소비자 중심): AIDA 모형에 따라 구매의사결정 단계마다 소비자와의 접점을 마련한다. 관계 마케팅: 고객과 지속적 관계를 유지한다."}],"선지":[{"번호":1,"판정":"틀림","설명":"시장점유 전략은 공급자 측면의 접근이다. 수요자(소비자) 측면의 접근은 고객점유 전략이다."},{"번호":2,"판정":"옳음","설명":"적응가격(차별가격) 전략은 같은 제품을 구매자에 따라 다른 가격으로 판매하는 것이다."},{"번호":3,"판정":"옳음","설명":"마케팅믹스는 표적시장에 도달하기 위해 쓰는 마케팅 요소의 조합이다."},{"번호":4,"판정":"옳음","설명":"시장세분화는 수요자 집단을 인구·경제적 특성 등으로 나누고 그 시장에서 판매지향점을 분명히 하는 전략이다."},{"번호":5,"판정":"옳음","설명":"고객점유 전략은 구매의사결정 과정(AIDA)의 각 단계에서 소비자와 접점을 마련하고 정보의 강약을 조절한다."}],"개념":[{"종류":"표","제목":"마케팅 전략 3종","머리":["구분","시장점유 전략","고객점유 전략","관계 마케팅"],"행":[["관점","공급자 중심","소비자 중심","고객과 공급자의 장기 관계"],["도구","STP, 4P Mix","AIDA 모형","고객 관리, 사후 서비스"],["목표","목표시장 선점, 점유율 확대","구매 단계별 심리 접점 확보","재구매, 구전 효과"],["핵심 단어","세분화·표적시장·포지셔닝","주의·관심·욕망·행동","지속적 관계"]]},{"종류":"흐름","제목":"AIDA 구매의사결정 단계","단계":[{"이름":"주의(Attention)","설명":"광고 등으로 소비자의 눈길을 끈다"},{"이름":"관심(Interest)","설명":"상품 정보를 제공해 흥미를 일으킨다"},{"이름":"욕망(Desire)","설명":"구입하고 싶은 마음이 생기게 한다"},{"이름":"행동(Action)","설명":"계약·구매로 이어지게 한다"}]}],"함정":"공급자 측면과 수요자 측면을 맞바꾼 ① 한 곳만 틀렸다. 시장점유 = 공급자, 고객점유 = 소비자다. 나머지 선지는 정의 그대로다."}},{"i":"S2-1-1-학개론-34","r":"S2","g":1,"c":1,"n":34,"s":"학개론","q":"부동산마케팅에 관한 설명으로 틀린 것은?","b":null,"bs":"없음","img":[],"ch":["부동산시장이 공급자 우위에서 수요자 우위의 시장으로 전환되면 마케팅의 중요성이 더욱 증대된다.","STP전략이란 고객집단을 세분화(Segmentation)하고 표적시장을 선정(Targeting)하여 효과적으로 판매촉진(Promotion)을 하는 전략이다.","경쟁사의 가격을 추종해야 할 경우 4P Mix의 가격전략으로 시가전략을 이용한다.","관계 마케팅전략이란 고객과 공급자 간의 지속적인 관계를 유지하여 마케팅효과를 도모하는 전략이다.","시장점유 마케팅전략이란 부동산시장을 점유하기 위한 전략으로 4P Mix전략, STP전략이 있다."],"a":[2],"L":"학7-2","o":"기출","x":{"한줄":"STP의 P는 판매촉진(Promotion)이 아니라 포지셔닝(Positioning)이다.","근거":[{"이론":"STP 전략","내용":"시장세분화(Segmentation) → 표적시장 선정(Targeting) → 포지셔닝(Positioning). 4P Mix의 P는 제품·가격·유통경로·판매촉진이다."}],"선지":[{"번호":1,"판정":"옳음","설명":"공급자 우위 시장에서 수요자 우위 시장으로 바뀌면 판매 노력이 필요해져 마케팅의 중요성이 커진다."},{"번호":2,"판정":"틀림","설명":"STP는 세분화·표적시장 선정·포지셔닝이다. 판매촉진은 4P Mix에 속한다."},{"번호":3,"판정":"옳음","설명":"경쟁사 가격을 따라가는 가격전략이 시가전략이다."},{"번호":4,"판정":"옳음","설명":"관계 마케팅은 고객과 공급자 사이의 지속적 관계로 마케팅 효과를 높이는 전략이다."},{"번호":5,"판정":"옳음","설명":"시장점유 마케팅전략에는 4P Mix전략과 STP전략이 있다."}],"개념":[{"종류":"표","제목":"STP 3단계","머리":["단계","내용","예"],"행":[["시장세분화(S)","구매자 집단을 동질적 하위 집단으로 나눈다","연령·소득·가구 구성 등 기준별로 구분"],["표적시장 선정(T)","세분 시장 가운데 공략할 시장을 고른다","세분 시장 중 공략 대상으로 선정한 시장"],["포지셔닝(P)","표적시장에서 상품의 판매지향점을 분명히 한다","경쟁 상품과 구별되는 위치 설정"]]},{"종류":"표","제목":"가격전략","머리":["전략","내용","적합한 상황"],"행":[["시가전략","경쟁 부동산 가격을 따라간다","가격경쟁을 피하려는 경우"],["저가전략","시장가격보다 낮게 정한다","빠른 자금회수, 구매력이 낮은 시장"],["고가전략","시장가격보다 높게 정한다","고급 이미지, 수요가 가격에 비탄력적일 때"],["적응(차별)가격","같은 제품을 구매자별로 다르게 정한다","다양한 수요자의 구매 유도"]]}],"함정":"STP와 4P의 P를 섞는 선지다. STP의 P는 포지셔닝, 4P의 P는 제품·가격·유통경로·판매촉진이다."}},{"i":"S2-1-1-학개론-35","r":"S2","g":1,"c":1,"n":35,"s":"학개론","q":"부동산 마케팅에 관한 설명으로 옳은 것은?","b":null,"bs":"없음","img":[],"ch":["시장세분화는 STP 전략의 마지막 단계로, 선정한 표적시장에서 상품의 위치를 정하는 활동이다.","표적시장 선정은 세분된 시장에서 상품의 판매지향점을 분명히 하는 단계이다.","4P Mix의 유통경로(Place)에는 분양대행사의 활용과 광고·홍보 활동이 포함된다.","마케팅믹스의 4P는 제품(Product), 가격(Price), 유통경로(Place), 포지셔닝(Positioning)이다.","빠른 자금회수가 필요하고 지역 구매자의 구매력이 낮은 경우에는 저가전략을 이용한다."],"a":[5],"L":"학7-2","o":"변형","x":{"한줄":"빠른 자금회수가 필요하고 구매력이 낮은 시장에서는 시장가격보다 낮게 정하는 저가전략이 맞다.","근거":[{"이론":"가격전략","내용":"저가전략: 빠른 자금회수, 구매력이 낮은 시장에 적합. 고가전략: 고급 이미지, 비탄력적 수요에 적합. 시가전략: 경쟁 가격 추종."},{"이론":"STP와 4P","내용":"STP: 세분화 → 표적시장 선정 → 포지셔닝. 4P: 제품·가격·유통경로·판매촉진."}],"선지":[{"번호":1,"판정":"틀림","설명":"시장세분화는 STP의 첫 단계다. 표적시장에서 상품의 위치를 정하는 활동은 포지셔닝이다."},{"번호":2,"판정":"틀림","설명":"표적시장 선정은 세분 시장 가운데 공략할 시장을 고르는 단계다. 판매지향점을 분명히 하는 것은 포지셔닝이다."},{"번호":3,"판정":"틀림","설명":"분양대행사 활용은 유통경로에 속하지만 광고·홍보는 판매촉진(Promotion)에 속한다."},{"번호":4,"판정":"틀림","설명":"4P의 마지막은 포지셔닝이 아니라 판매촉진(Promotion)이다."},{"번호":5,"판정":"옳음","설명":"빠른 자금회수와 낮은 구매력에는 저가전략을 쓴다."}],"개념":[{"종류":"비교","제목":"STP 전략과 4P Mix","왼쪽":{"이름":"STP 전략 (표적시장을 정하는 틀)","항목":["S 시장세분화: 구매자 집단을 나눈다","T 표적시장 선정: 공략할 시장을 고른다","P 포지셔닝: 판매지향점을 분명히 한다"]},"오른쪽":{"이름":"4P Mix (표적시장에 접근하는 수단)","항목":["Product 제품","Price 가격","Place 유통경로","Promotion 판매촉진"]}},{"종류":"표","제목":"4P 가려내기","머리":["P","이런 선지면 여기"],"행":[["제품(Product)","평면 차별화, 커뮤니티 시설, 보안 디지털화, 주차장 지하화"],["가격(Price)","시가·저가·고가 전략, 위치·층별 차등 가격"],["유통경로(Place)","직접 판매, 분양대행사, 중개업소 활용"],["판매촉진(Promotion)","광고, 홍보, 인적 판매, 경품·사은품"]]}],"함정":"① ②는 STP 순서를 뒤섞은 선지다. S → T → P 순서와 각 단계의 뜻을 짝지어 둔다. ③은 광고·홍보를 유통경로로 분류한 오류, ④는 4P의 P 하나를 포지셔닝으로 바꾼 오류다."}},{"i":"S2-1-1-학개론-36","r":"S2","g":1,"c":1,"n":36,"s":"학개론","q":"감정평가 3방식 및 시산가액에 관한 설명으로 옳은 것은?","b":null,"bs":"없음","img":[],"ch":["원가방식에는 원가법과 적산법이, 수익방식에는 수익환원법과 거래사례비교법이 속한다.","공시지가기준법은 원가방식에 속한다.","감정평가법인등은 어느 하나의 감정평가방법으로 산정한 시산가액을 다른 감정평가방식에 속하는 방법으로 산출한 시산가액과 비교하여 합리성을 검토하는 것이 원칙이다.","시산가액의 합리성이 없다고 판단되면 감정평가법인등은 3방식의 시산가액을 산술평균하여 감정평가액을 결정하여야 한다.","적산법은 수익성의 원리에 기초하여 대상물건의 임대료를 구하는 감정평가방법이다."],"a":[3],"L":"학8-2","o":"변형","x":{"한줄":"주된 방법으로 구한 시산가액은 다른 방식의 시산가액과 비교해 합리성을 검토한다. 합리성이 없으면 시산가액을 조정해 감정평가액을 정한다.","근거":[{"법령":"감정평가에 관한 규칙","조문":"제11조","원문":"  1. 원가방식: 원가법 및 적산법 등 비용성의 원리에 기초한 감정평가방식\n  2. 비교방식: 거래사례비교법, 임대사례비교법 등 시장성의 원리에 기초한 감정평가방식 및 공시지가기준법\n  3. 수익방식: 수익환원법 및 수익분석법 등 수익성의 원리에 기초한 감정평가방식"},{"법령":"감정평가에 관한 규칙","조문":"제12조제2항","원문":"② 감정평가법인등은 대상물건의 감정평가액을 결정하기 위하여 제1항에 따라 어느 하나의 감정평가방법을 적용하여 산정(算定)한 가액[이하 \"시산가액(試算價額)\"이라 한다]을 제11조 각 호의 감정평가방식 중 다른 감정평가방식에 속하는 하나 이상의 감정평가방법(이 경우 공시지가기준법과 그 밖의 비교방식에 속한 감정평가방법은 서로 다른 감정평가방식에 속한 것으로 본다)으로 산출한 시산가액과 비교하여 합리성을 검토해야 한다. 다만, 대상물건의 특성 등으로 인하여 다른 감정평가방법을 적용하는 것이 곤란하거나 불필요한 경우에는 그렇지 않다."},{"법령":"감정평가에 관한 규칙","조문":"제12조제3항","원문":"③ 감정평가법인등은 제2항에 따른 검토 결과 제1항에 따라 산출한 시산가액의 합리성이 없다고 판단되는 경우에는 주된 방법 및 다른 감정평가방법으로 산출한 시산가액을 조정하여 감정평가액을 결정할 수 있다."}],"선지":[{"번호":1,"판정":"틀림","설명":"거래사례비교법은 시장성에 기초한 비교방식이다. 수익방식은 수익환원법과 수익분석법이다(제11조)."},{"번호":2,"판정":"틀림","설명":"공시지가기준법은 비교방식에 속한다(제11조제2호)."},{"번호":3,"판정":"옳음","설명":"제12조제2항은 시산가액을 다른 감정평가방식에 속하는 방법의 시산가액과 비교해 합리성을 검토하도록 한다. 다만 다른 방법을 적용하기 곤란하거나 불필요하면 예외다."},{"번호":4,"판정":"틀림","설명":"합리성이 없으면 시산가액을 조정하여 결정할 수 있다(제12조제3항). 산술평균으로 정해진 것이 아니며 각 시산가액에 합리적인 가중치를 둘 수 있다."},{"번호":5,"판정":"틀림","설명":"적산법은 비용성의 원리에 기초한 원가방식이다. 수익성의 원리에 기초한 임대료 산정법은 수익분석법이다."}],"개념":[{"종류":"표","제목":"3방식 6방법","머리":["방식 (원리)","가액을 구하는 방법","임대료를 구하는 방법"],"행":[["원가방식 (비용성)","원가법 → 적산가액","적산법 → 적산임료"],["비교방식 (시장성)","거래사례비교법 → 비준가액, 공시지가기준법","임대사례비교법 → 비준임료"],["수익방식 (수익성)","수익환원법 → 수익가액","수익분석법 → 수익임료"]]},{"종류":"흐름","제목":"감정평가액의 결정 과정 (제12조)","단계":[{"이름":"주된 방법 적용","설명":"대상물건별로 정한 주된 방법으로 시산가액을 산정한다"},{"이름":"다른 방식과 비교","설명":"다른 방식에 속하는 방법의 시산가액과 비교해 합리성을 검토한다"},{"이름":"합리성 판단","설명":"합리성이 없다고 판단하면"},{"이름":"시산가액 조정","설명":"주된 방법과 다른 방법의 시산가액을 조정한다"},{"이름":"감정평가액 결정","설명":"조정한 결과로 감정평가액을 결정한다"}]}],"함정":"공시지가기준법을 원가나 수익방식으로 분류하는 ②와, 시산가액 조정을 산술평균으로 한정하는 ④가 단골이다. 조정은 상호 관련 재검토이며 산술평균만 인정되는 것이 아니다."}},{"i":"S2-1-1-학개론-37","r":"S2","g":1,"c":1,"n":37,"s":"학개론","q":"원가법에서 사용하는 감가수정 방법에 관한 설명으로 틀린 것은?","b":null,"bs":"없음","img":[],"ch":["정률법에서는 매년 감가율이 감소함에 따라 감가액이 감소한다.","정액법에서는 감가누계액이 경과연수에 정비례하여 증가한다.","정액법을 직선법 또는 균등상각법이라고도 한다.","상환기금법은 건물 등의 내용연수가 만료될 때 감가누계상당액과 그에 대한 복리계산의 이자상당액분을 포함하여 당해 내용연수로 상환하는 방법이다.","정액법, 정률법, 상환기금법은 모두 내용연수에 의한 감가수정 방법이다."],"a":[1],"L":"학8-2","o":"기출","x":{"한줄":"정률법은 매년 감가율이 일정하고, 감가액이 해마다 줄어든다.","근거":[{"법령":"감정평가에 관한 규칙","조문":"제2조제12호","원문":"  12. \"감가수정\"이란 대상물건에 대한 재조달원가를 감액하여야 할 요인이 있는 경우에 물리적 감가, 기능적 감가 또는 경제적 감가 등을 고려하여 그에 해당하는 금액을 재조달원가에서 공제하여 기준시점에 있어서의 대상물건의 가액을 적정화하는 작업을 말한다."},{"이론":"감가수정 방법","내용":"정액법: 매년 감가액이 일정하고 감가누계액이 경과연수에 정비례한다(직선법·균등상각법). 정률법: 매년 감가율이 일정하여 감가액이 체감한다. 상환기금법: 감가액에 복리 이자 상당분을 더해 내용연수 만료 시 재조달원가를 적립한다. 세 방법 모두 내용연수에 의한 방법이다."}],"선지":[{"번호":1,"판정":"틀림","설명":"정률법은 감가율이 매년 일정하다. 감가율이 바뀌는 것이 아니라 잔존가액이 줄어 감가액이 감소한다."},{"번호":2,"판정":"옳음","설명":"정액법은 매년 감가액이 일정하므로 감가누계액이 경과연수에 비례한다."},{"번호":3,"판정":"옳음","설명":"정액법의 다른 이름은 직선법 또는 균등상각법이다."},{"번호":4,"판정":"옳음","설명":"상환기금법은 감가누계상당액과 복리 이자상당액을 포함해 내용연수 동안 상환하는 방법이다."},{"번호":5,"판정":"옳음","설명":"정액법·정률법·상환기금법은 모두 내용연수에 의한 감가수정 방법이다."}],"개념":[{"종류":"비교","제목":"정액법과 정률법","왼쪽":{"이름":"정액법","항목":["매년 감가액이 일정","감가누계액은 경과연수에 정비례","직선법·균등상각법","적산가액은 중간 수준"]},"오른쪽":{"이름":"정률법","항목":["매년 감가율이 일정","감가액은 해마다 감소(초기 감가액이 가장 큼)","잔존가액이 급감해 초기에 적산가액이 작아짐","기계·설비에 어울린다"]}},{"종류":"계산","제목":"정액법과 정률법의 감가액 비교 (재조달원가 1억원)","단계":[{"설명":"정액법 연 감가액 (내용연수 50년, 잔존가치 0)","식":"1억 ÷ 50","값":"200만원"},{"설명":"정액법 20년 경과 감가누계액","식":"200만 × 20","값":"4,000만원"},{"설명":"정액법 적산가액","식":"1억 − 4,000만","값":"6,000만원"},{"설명":"정률법 1년차 감가액 (감가율 10%)","식":"1억 × 10%","값":"1,000만원"},{"설명":"정률법 2년차 감가액","식":"(1억 − 1,000만) × 10%","값":"900만원"}]}],"함정":"정률법은 ‘감가율이 줄어든다’고 쓰면 틀린다. 줄어드는 것은 감가액이고, 감가율은 일정하다. 정액법은 감가액이 일정하다."}},{"i":"S2-1-1-학개론-38","r":"S2","g":1,"c":1,"n":38,"s":"학개론","q":"원가법에서의 재조달원가에 관한 설명으로 틀린 것은?","b":null,"bs":"없음","img":[],"ch":["재조달원가란 대상물건을 기준시점에 재생산하거나 재취득하는 데 필요한 적정원가의 총액을 말한다.","총량조사법, 구성단위법, 비용지수법은 재조달원가의 산정방법에 해당한다.","재조달원가는 대상물건을 일반적인 방법으로 생산하거나 취득하는 데 드는 비용으로 하되, 제세공과금은 제외한다.","재조달원가를 구성하는 표준적 건설비에는 수급인의 적정이윤이 포함된다.","재조달원가를 구할 때 직접법과 간접법을 병용할 수 있다."],"a":[3],"L":"학8-2","o":"기출","x":{"한줄":"재조달원가에는 제세공과금이 포함된다. 제외한다는 선지가 틀렸다.","근거":[{"법령":"감정평가에 관한 규칙","조문":"제2조제5호","원문":"  5. \"원가법\"이란 대상물건의 재조달원가에 감가수정(減價修正)을 하여 대상물건의 가액을 산정하는 감정평가방법을 말한다."},{"법령":"감정평가에 관한 규칙","조문":"제15조제1항","원문":"① 감정평가법인등은 건물을 감정평가할 때에 원가법을 적용해야 한다."},{"이론":"재조달원가","내용":"기준시점에 대상물건을 재생산하거나 재취득하는 데 필요한 적정원가의 총액이다. 표준적 건설비, 통상 부대비용, 수급인의 적정이윤, 제세공과금 등을 포함한다. 산정은 직접법(총량조사법·구성단위법)과 간접법(비용지수법)을 쓰며 병용할 수 있다."}],"선지":[{"번호":1,"판정":"옳음","설명":"재조달원가의 정의 그대로다."},{"번호":2,"판정":"옳음","설명":"총량조사법·구성단위법·비용지수법은 재조달원가 산정방법이다."},{"번호":3,"판정":"틀림","설명":"재조달원가는 일반적인 방법으로 생산하거나 취득하는 데 드는 비용에 제세공과금 등을 포함한다."},{"번호":4,"판정":"옳음","설명":"표준적 건설비에는 수급인의 적정이윤이 포함된다."},{"번호":5,"판정":"옳음","설명":"재조달원가를 구할 때 직접법과 간접법을 병용할 수 있다."}],"개념":[{"종류":"표","제목":"재조달원가의 산정방법","머리":["구분","방법","내용"],"행":[["직접법","총량조사법","대상물건 전체에 소요되는 자재량·노무량을 조사해 단가를 곱한다"],["직접법","구성단위법","건물을 구성단위(지붕·벽 등)로 나눠 단위별 단가를 곱한다"],["간접법","비용지수법","건축 당시의 공사비에 기준시점까지의 건축비지수를 반영한다"],["병용","직접법 + 간접법","두 방법을 함께 써서 검증한다"]]},{"종류":"비교","제목":"재생산비용과 대체비용","왼쪽":{"이름":"재생산비용(복제원가)","항목":["물리적으로 동일한 물건을 재생산하는 비용","재조달원가 산정의 원칙"]},"오른쪽":{"이름":"대체비용(대치원가)","항목":["효용이 동일한 물건으로 대체하는 비용","구식 건물처럼 효용이 같은 현대식 물건으로 대체할 때 쓰며, 기능적 감가를 따로 반영할 필요가 없다"]}}],"함정":"‘제세공과금 제외’ 문장 하나에서 걸린다. 재조달원가에는 건설비 외에 수급인의 이윤, 제세공과금 등 부대비용이 들어간다."}},{"i":"S2-1-1-학개론-39","r":"S2","g":1,"c":1,"n":39,"s":"학개론","q":"감정평가에 관한 규칙상 감정평가의 절차에 관한 설명으로 옳은 것은?","b":null,"bs":"없음","img":[],"ch":["감정평가의 절차는 어떠한 경우에도 규칙이 정한 순서를 바꿀 수 없다.","기준시점은 감정평가서 작성일로 한다.","대상물건의 확인은 실지조사 없이 자료만으로 하는 것이 원칙이다.","기본적 사항의 확정 단계에서는 의뢰인과 협의하여 의뢰인, 대상물건, 감정평가 목적, 기준시점 등을 확정한다.","감정평가방법의 선정 및 적용은 자료수집 및 정리보다 앞서 한다."],"a":[4],"L":"학8-3","o":"변형","x":{"한줄":"감정평가는 기본적 사항의 확정부터 시작하며, 이 단계에서 의뢰인·대상물건·감정평가 목적·기준시점 등을 의뢰인과 협의해 정한다.","근거":[{"법령":"감정평가에 관한 규칙","조문":"제8조","원문":"감정평가법인등은 다음 각 호의 순서에 따라 감정평가를 해야 한다. 다만, 합리적이고 능률적인 감정평가를 위하여 필요할 때에는 순서를 조정할 수 있다.\n  1. 기본적 사항의 확정\n  2. 처리계획 수립\n  3. 대상물건 확인\n  4. 자료수집 및 정리\n  5. 자료검토 및 가치형성요인의 분석\n  6. 감정평가방법의 선정 및 적용\n  7. 감정평가액의 결정 및 표시"},{"법령":"감정평가에 관한 규칙","조문":"제9조제1항","원문":"① 감정평가법인등은 감정평가를 의뢰받았을 때에는 의뢰인과 협의하여 다음 각 호의 사항을 확정해야 한다.\n  1. 의뢰인\n  2. 대상물건\n  3. 감정평가 목적\n  4. 기준시점\n  5. 감정평가조건\n  6. 기준가치\n  7. 관련 전문가에 대한 자문 또는 용역(이하 \"자문등\"이라 한다)에 관한 사항\n  8. 수수료 및 실비에 관한 사항"},{"법령":"감정평가에 관한 규칙","조문":"제9조제2항","원문":"② 기준시점은 대상물건의 가격조사를 완료한 날짜로 한다. 다만, 기준시점을 미리 정하였을 때에는 그 날짜에 가격조사가 가능한 경우에만 기준시점으로 할 수 있다."},{"법령":"감정평가에 관한 규칙","조문":"제10조제1항","원문":"① 감정평가법인등이 감정평가를 할 때에는 실지조사를 하여 대상물건을 확인해야 한다."}],"선지":[{"번호":1,"판정":"틀림","설명":"합리적이고 능률적인 감정평가를 위해 필요하면 순서를 조정할 수 있다(제8조 단서)."},{"번호":2,"판정":"틀림","설명":"기준시점은 대상물건의 가격조사를 완료한 날짜다. 미리 정했다면 그 날짜에 가격조사가 가능한 경우에만 기준시점으로 할 수 있다(제9조제2항)."},{"번호":3,"판정":"틀림","설명":"실지조사를 하여 대상물건을 확인하는 것이 원칙이고, 천재지변 등 예외에 한해 생략할 수 있다(제10조)."},{"번호":4,"판정":"옳음","설명":"제9조제1항에 따라 의뢰인, 대상물건, 감정평가 목적, 기준시점, 감정평가조건, 기준가치, 자문등, 수수료 및 실비를 확정한다."},{"번호":5,"판정":"틀림","설명":"순서는 자료수집 및 정리(4호) → 자료검토 및 가치형성요인의 분석(5호) → 감정평가방법의 선정 및 적용(6호)이다."}],"개념":[{"종류":"흐름","제목":"감정평가의 절차 (제8조)","단계":[{"이름":"기본적 사항의 확정","설명":"의뢰인과 협의해 의뢰인·대상물건·감정평가 목적·기준시점 등을 정한다"},{"이름":"처리계획 수립","설명":"감정평가 업무의 처리계획을 세운다"},{"이름":"대상물건 확인","설명":"실지조사로 대상물건을 확인한다"},{"이름":"자료수집 및 정리","설명":"감정평가에 필요한 자료를 모으고 정리한다"},{"이름":"자료검토 및 가치형성요인의 분석","설명":"수집 자료를 검토하고 일반·지역·개별요인을 분석한다"},{"이름":"감정평가방법의 선정 및 적용","설명":"주된 방법과 다른 방법을 선택해 시산가액을 산정한다"},{"이름":"감정평가액의 결정 및 표시","설명":"시산가액을 검토·조정해 감정평가액을 정한다"}]},{"종류":"표","제목":"기본적 사항의 확정 항목 (제9조제1항)","머리":["확정 사항","비고"],"행":[["의뢰인","누가 의뢰했는지"],["대상물건","감정평가할 물건"],["감정평가 목적","담보·경매·보상 등"],["기준시점","가격조사를 완료한 날짜가 원칙"],["감정평가조건","가정·한정 조건이 있을 때"],["기준가치","원칙은 시장가치"],["자문 또는 용역","관련 전문가 자문등이 필요할 때"],["수수료 및 실비","의뢰인과 협의"]]}],"함정":"감정평가 ‘의뢰’는 규칙 제8조의 7단계에 들어 있지 않다. 절차는 기본적 사항의 확정부터 시작한다. 순서는 원칙이지 절대 규칙이 아니라 필요할 때 조정할 수 있다."}},{"i":"S2-1-1-학개론-40","r":"S2","g":1,"c":1,"n":40,"s":"학개론","q":"부동산 가격공시에 관한 법령에 규정된 내용으로 틀린 것은?","b":null,"bs":"없음","img":[],"ch":["표준지공시지가는 토지시장에 지가정보를 제공하고 일반적인 토지거래의 지표가 되며, 국가ㆍ지방자치단체 등이 그 업무와 관련하여 지가를 산정하거나 감정평가법인등이 개별적으로 토지를 감정평가하는 경우에 기준이 된다.","국토교통부장관이 표준지공시지가를 조사ㆍ산정할 때에는 한국부동산원법 에 따른 한국부동산원에게 이를 의뢰하여야 한다.","표준지공시지가에 이의가 있는 자는 그 공시일부터 30일 이내에 서면(전자문서를 포함한다)으로 국토교통부장관에게 이의를 신청할 수 있다.","시장ㆍ군수 또는 구청장이 개별공시지가를 결정ㆍ공시하는 경우에는 해당 토지와 유사한 이용가치를 지닌다고 인정되는 하나 또는 둘 이상의 표준지의 공시지가를 기준으로 토지가격비준표를 사용하여 지가를 산정하되, 해당 토지의 가격과 표준지공시지가가 균형을 유지하도록 하여야 한다.","표준지로 선정된 토지에 대하여는 개별공시지가를 결정ㆍ공시하지 아니할 수 있다. 이 경우 표준지로 선정된 토지에 대하여는 해당 토지의 표준지공시지가를 개별공시지가로 본다."],"a":[2],"L":"학8-4","o":"기출","x":{"한줄":"표준지공시지가는 둘 이상의 감정평가법인등에 의뢰하여 조사·평가한다. 한국부동산원에 의뢰한다는 선지가 틀렸다.","근거":[{"법령":"부동산 가격공시에 관한 법률","조문":"제3조제5항","원문":"⑤ 국토교통부장관이 제1항에 따라 표준지공시지가를 조사ㆍ평가할 때에는 업무실적, 신인도(信認度) 등을 고려하여 둘 이상의 「감정평가 및 감정평가사에 관한 법률」에 따른 감정평가법인등(이하 \"감정평가법인등\"이라 한다)에게 이를 의뢰하여야 한다. 다만, 지가 변동이 작은 경우 등 대통령령으로 정하는 기준에 해당하는 표준지에 대해서는 하나의 감정평가법인등에 의뢰할 수 있다."},{"법령":"부동산 가격공시에 관한 법률","조문":"제7조제1항","원문":"① 표준지공시지가에 이의가 있는 자는 그 공시일부터 30일 이내에 서면(전자문서를 포함한다. 이하 같다)으로 국토교통부장관에게 이의를 신청할 수 있다."},{"법령":"부동산 가격공시에 관한 법률","조문":"제9조","원문":"표준지공시지가는 토지시장에 지가정보를 제공하고 일반적인 토지거래의 지표가 되며, 국가ㆍ지방자치단체 등이 그 업무와 관련하여 지가를 산정하거나 감정평가법인등이 개별적으로 토지를 감정평가하는 경우에 기준이 된다."},{"법령":"부동산 가격공시에 관한 법률","조문":"제10조제2항","원문":"② 제1항에도 불구하고 표준지로 선정된 토지, 조세 또는 부담금 등의 부과대상이 아닌 토지, 그 밖에 대통령령으로 정하는 토지에 대하여는 개별공시지가를 결정ㆍ공시하지 아니할 수 있다. 이 경우 표준지로 선정된 토지에 대하여는 해당 토지의 표준지공시지가를 개별공시지가로 본다."},{"법령":"부동산 가격공시에 관한 법률","조문":"제10조제4항","원문":"④ 시장ㆍ군수 또는 구청장이 개별공시지가를 결정ㆍ공시하는 경우에는 해당 토지와 유사한 이용가치를 지닌다고 인정되는 하나 또는 둘 이상의 표준지의 공시지가를 기준으로 토지가격비준표를 사용하여 지가를 산정하되, 해당 토지의 가격과 표준지공시지가가 균형을 유지하도록 하여야 한다."}],"선지":[{"번호":1,"판정":"옳음","설명":"표준지공시지가의 효력이다(제9조)."},{"번호":2,"판정":"틀림","설명":"국토교통부장관은 업무실적, 신인도 등을 고려하여 둘 이상의 감정평가법인등에 의뢰하여야 한다. 지가변동이 작은 경우 등 대통령령으로 정한 표준지는 하나의 감정평가법인등에 의뢰할 수 있다(제3조제5항)."},{"번호":3,"판정":"옳음","설명":"표준지공시지가 이의신청은 공시일부터 30일 이내에 서면으로 국토교통부장관에게 한다(제7조제1항)."},{"번호":4,"판정":"옳음","설명":"개별공시지가는 표준지공시지가를 기준으로 토지가격비준표를 사용해 산정하며 균형을 유지해야 한다(제10조제4항)."},{"번호":5,"판정":"옳음","설명":"표준지로 선정된 토지는 개별공시지가를 결정·공시하지 않을 수 있으며, 이때 표준지공시지가가 개별공시지가로 간주된다(제10조제2항)."}],"개념":[{"종류":"표","제목":"표준지공시지가와 개별공시지가","머리":["구분","표준지공시지가","개별공시지가"],"행":[["공시 주체","국토교통부장관","시장·군수·구청장"],["심의 기구","중앙부동산가격공시위원회","시·군·구부동산가격공시위원회"],["산정 방법","표준지를 조사·평가 (둘 이상의 감정평가법인등에 의뢰)","표준지공시지가 + 토지가격비준표, 감정평가법인등의 검증"],["이의신청","공시일부터 30일 이내, 국토교통부장관에게","결정·공시일부터 30일 이내, 시장·군수·구청장에게"],["이의신청 처리","신청기간 만료일부터 30일 이내 심사·통지","신청기간 만료일부터 30일 이내 심사·통지"],["효력·용도","지가정보 제공, 토지거래의 지표, 보상·평가의 기준","세금 부과 등 각종 법령상 지가산정의 기준"]]},{"종류":"흐름","제목":"표준지공시지가의 공시","단계":[{"이름":"표준지 선정","설명":"토지이용상황 등이 일반적으로 유사한 일단의 토지 중에서 선정한다"},{"이름":"토지소유자 의견 청취","설명":"조사·평가할 때 해당 토지 소유자의 의견을 듣는다"},{"이름":"조사·평가","설명":"업무실적·신인도 등을 고려해 둘 이상의 감정평가법인등에 의뢰한다"},{"이름":"심의·공시","설명":"중앙부동산가격공시위원회의 심의를 거쳐 공시한다"},{"이름":"열람 및 이의신청","설명":"시장·군수·구청장을 통해 열람하게 하고, 공시일부터 30일 이내 이의신청을 받는다"}]}],"함정":"평가 의뢰 대상은 둘 이상의 감정평가법인등이다. 기관 이름을 바꿔 놓은 선지에 걸린다. 이의신청 기간 30일과 처리 기간 30일은 표준지·개별 모두 같다."}},{"i":"S2-1-1-민법-01","r":"S2","g":1,"c":1,"n":41,"s":"민법","q":"甲은 자신의 X토지를 乙에게 매도하고 계약금과 중도금을 지급받았다. 그 후 丙이 甲에게 이중매매를 적극 권유하여 甲과 X토지에 대한 매매계약을 체결하고 자신 명의로 소유권이전등기를 마쳤다. 다음 설명 중 옳은 것은? (다툼이 있으면 판례에 따름)","b":null,"bs":"없음","img":[],"ch":["乙은 甲을 대위하여 丙 명의의 소유권이전등기의 말소를 청구할 수 있다.","乙은 丙에게 직접 소유권이전등기를 청구할 수 있다.","丙이 이중매매 사실을 알고 있었다면, 적극 가담하지 않았더라도 丙과 甲의 매매계약은 무효이다.","甲이 丙과의 매매계약을 추인하면 그 계약은 처음부터 유효한 것이 된다.","丙으로부터 X토지를 매수하여 등기를 마친 선의의 丁은 甲·丙 매매계약의 유효를 주장할 수 있다."],"a":[1],"L":"민1-1","o":"변형","x":{"한줄":"丙이 매도인의 배임행위에 적극 가담한 이중매매는 제103조 위반으로 무효이므로, 乙은 자신의 이전등기청구권을 보전하기 위해 甲을 대위하여 丙 명의 등기를 말소할 수 있다.","근거":[{"법령":"민법","조문":"제103조","원문":"선량한 풍속 기타 사회질서에 위반한 사항을 내용으로 하는 법률행위는 무효로 한다."},{"판례":"대법원 판례(이중매매의 반사회적 무효)","요지":"제2매수인이 매도인의 배임행위에 적극 가담한 이중매매는 절대적 무효다. 제1매수인은 매도인을 대위하여 제2매수인 명의 등기의 말소를 청구할 수 있으나, 제2매수인에게 직접 이전등기를 청구할 수는 없다. 이중매매 사실을 아는 것만으로는 무효가 되지 않는다."}],"선지":[{"번호":1,"판정":"옳음","설명":"제1매수인은 채권자대위권(제404조)으로 매도인의 말소청구권을 행사한다."},{"번호":2,"판정":"틀림","설명":"乙의 채권은 甲에 대한 것이고 X토지의 소유자는 여전히 甲이다. 丙에게 직접 이전등기를 청구할 권리가 없다."},{"번호":3,"판정":"틀림","설명":"이중매매 사실을 아는 것만으로는 무효가 아니고, 매도인의 배임행위에 적극 가담해야 제103조 위반이 된다."},{"번호":4,"판정":"틀림","설명":"반사회질서 법률행위는 추인해도 효력이 생기지 않는다(제139조 본문)."},{"번호":5,"판정":"틀림","설명":"반사회질서 무효는 절대적 무효라서 선의의 제3자에게도 무효를 주장할 수 있다. 丁은 유효를 주장하지 못한다."}],"개념":[{"종류":"표","제목":"반사회질서(제103조)와 불공정(제104조) 비교","머리":["구분","제103조","제104조"],"행":[["판단 시점","법률행위가 성립한 때","법률행위 당시"],["요건","내용이 사회질서에 반함(동기는 표시·인식된 경우)","객관: 현저한 불균형 / 주관: 궁박·경솔·무경험과 폭리자의 악용 인식"],["대리","-","궁박은 본인, 경솔·무경험은 대리인 기준"],["효과","절대적 무효, 선의 제3자에게도 주장 가능","무효, 무효행위 전환 법리 적용 가능"],["추인","불가(제139조)","불가(제139조)"],["경매","-","경매에는 적용되지 않음"]]},{"종류":"표","제목":"이중매매 법률관계","머리":["구분","제2매수인","제1매수인의 구제"],"행":[["단순 악의","매매 유효, 소유권 취득","먼저 등기한 자가 우선. 매도인에게 채무불이행 책임 추궁"],["적극 가담","매매 무효","매도인을 대위하여 말소 청구, 丙에게 불법행위 손해배상 청구"],["제2매수인의 전득자","선의여도 보호되지 않음(절대 무효)","전득자 명의 등기도 말소 대상"],["매도인의 해제","중도금 수령 후에는 이행 착수라 계약금 배액상환 해제 불가(제565조)","-"]]}],"함정":"3번을 고르기 쉽다. 이중매매는 알았다는 것만으로는 무효가 되지 않고 적극 가담이 있어야 무효다. 2번은 말소청구와 이전등기청구를 섞은 선지다."}},{"i":"S2-1-1-민법-02","r":"S2","g":1,"c":1,"n":42,"s":"민법","q":"법률행위의 효력에 관한 설명으로 틀린 것은? (다툼이 있으면 판례에 따름)","b":null,"bs":"없음","img":[],"ch":["변호사와 의뢰인 사이의 형사사건 성공보수약정은 무효이다.","민사사건에 관한 성공보수약정도 반사회질서의 법률행위로서 무효이다.","불공정한 법률행위에서 급부의 현저한 불균형 여부는 법률행위 당시를 기준으로 판단한다.","대리인이 매매계약을 체결한 경우, 궁박 상태는 본인을 기준으로 판단한다.","법률행위의 성립과정에서 강박이 있었다는 사정만으로 그 법률행위가 반사회질서 법률행위가 되는 것은 아니다."],"a":[2],"L":"민1-1","o":"변형","x":{"한줄":"민사사건 성공보수약정은 유효하다. 무효가 되는 것은 형사사건 성공보수약정이다.","근거":[{"법령":"민법","조문":"제103조","원문":"선량한 풍속 기타 사회질서에 위반한 사항을 내용으로 하는 법률행위는 무효로 한다."},{"법령":"민법","조문":"제104조","원문":"당사자의 궁박, 경솔 또는 무경험으로 인하여 현저하게 공정을 잃은 법률행위는 무효로 한다."},{"판례":"대법원 2015. 7. 23. 선고 2015다200111 전원합의체 판결","요지":"형사사건 성공보수약정은 선량한 풍속 기타 사회질서에 반해 무효다. 민사사건의 성공보수약정은 유효하다."}],"선지":[{"번호":1,"판정":"옳음","설명":"형사사건 성공보수약정은 제103조 위반으로 무효다."},{"번호":2,"판정":"틀림","설명":"민사사건 성공보수약정은 유효하다."},{"번호":3,"판정":"옳음","설명":"불균형은 법률행위 당시 기준으로 따진다."},{"번호":4,"판정":"옳음","설명":"대리인이 계약한 경우 경솔·무경험은 대리인을 기준으로, 궁박은 본인을 기준으로 판단한다."},{"번호":5,"판정":"옳음","설명":"강박은 취소 사유(제110조 제1항)이고, 성립과정의 불법만으로 내용이 반사회적이 되지는 않는다."}],"개념":[{"종류":"표","제목":"무효 사유 구별","머리":["사례","결론","근거"],"행":[["허위진술 대가 약정","무효","제103조"],["형사사건 성공보수약정","무효","제103조, 대법원 판례"],["민사사건 성공보수약정","유효","-"],["강박으로 체결한 계약","취소 가능","제110조"],["강제집행을 피하려는 허위 근저당 설정","무효(통정허위표시)","제108조"],["양도세를 줄이려 낮춰 쓴 매매대금","유효(단속규정 위반)","-"]]}],"함정":"성공보수약정을 모두 무효로 외우기 쉽다. 형사사건만 무효이고 민사사건은 유효하다."}},{"i":"S2-1-1-민법-03","r":"S2","g":1,"c":1,"n":43,"s":"민법","q":"甲은 채권자의 강제집행을 피하려고 乙과 통정하여 자신의 X토지에 관한 허위의 매매계약을 체결하고 乙 앞으로 소유권이전등기를 해주었다. 그 후 乙은 이러한 사정을 모르는 丙과 X토지에 관한 매매계약을 체결하고 丙 앞으로 소유권이전등기를 해주었다. 다음 설명 중 옳은 것은? (다툼이 있으면 판례에 따름)","b":null,"bs":"없음","img":[],"ch":["甲과 乙 사이의 매매계약은 甲이 취소하지 않는 한 유효하다.","丙이 선의라면 과실이 있더라도 X토지의 소유권을 취득한다.","丙의 선의에 관한 증명책임은 丙에게 있다.","甲은 丙 앞으로 등기가 넘어가기 전이라도 乙을 상대로 이전등기의 말소를 청구할 수 없다.","丙이 악의라면 丙으로부터 X토지를 매수한 선의의 丁도 보호받지 못한다."],"a":[2],"L":"민1-2","o":"변형","x":{"한줄":"제108조 제2항의 제3자는 선의이면 충분하고 무과실까지는 요구되지 않는다.","근거":[{"법령":"민법","조문":"제108조","원문":"①상대방과 통정한 허위의 의사표시는 무효로 한다.\n②전항의 의사표시의 무효는 선의의 제삼자에게 대항하지 못한다."},{"판례":"대법원 판례(허위표시의 제3자)","요지":"제3자는 선의이면 되고 무과실은 필요 없다. 제3자의 악의는 무효를 주장하는 자가 증명한다. 악의의 제3자로부터 전득한 선의자는 보호된다."}],"선지":[{"번호":1,"판정":"틀림","설명":"허위표시는 취소가 필요 없이 처음부터 무효다."},{"번호":2,"판정":"옳음","설명":"선의의 제3자는 과실이 있어도 보호된다."},{"번호":3,"판정":"틀림","설명":"선의는 추정되고, 무효를 주장하는 甲이 丙의 악의를 증명해야 한다."},{"번호":4,"판정":"틀림","설명":"甲은 乙을 상대로 소유권에 기한 말소를 청구할 수 있다. 계약이 무효이기 때문이다."},{"번호":5,"판정":"틀림","설명":"전득자 丁이 선의이면 보호된다. 선의의 제3자 보호는 전득자 단계에서 다시 판단한다."}],"개념":[{"종류":"표","제목":"의사표시 하자와 제3자 보호","머리":["유형","효과","제3자 보호 조문","보호 요건"],"행":[["비진의표시","원칙 유효, 상대방 악의·과실 시 무효","제107조 제2항","선의"],["통정허위표시","무효","제108조 제2항","선의(무과실 불요)"],["착오","취소","제109조 제2항","선의"],["사기·강박","취소","제110조 제3항","선의"]]},{"종류":"표","제목":"허위표시의 제3자 해당 여부","머리":["해당","해당하지 않음"],"행":[["가장매수인으로부터 목적물을 취득한 자","가장매수인의 일반채권자(압류 전)"],["가장매수인으로부터 저당권을 설정받은 자","대리인·상속인 등 포괄승계인"],["가장채권의 양수인","-"],["가장매수인의 채권자로서 목적물을 압류한 자","-"]]}],"함정":"과실이 있으면 보호받지 못한다고 생각하기 쉽다. 허위표시의 제3자는 선의이면 족하고, 악의의 증명책임은 무효를 주장하는 쪽에 있다."}},{"i":"S2-1-1-민법-04","r":"S2","g":1,"c":1,"n":44,"s":"민법","q":"甲은 乙과 체결한 매매계약을 적법하게 해제한다는 의사표시를 등기우편으로 乙에게 발송하였다. 다음 설명 중 옳은 것은? (다툼이 있으면 판례에 따름)","b":null,"bs":"없음","img":[],"ch":["甲은 해제의 의사표시가 乙에게 도달한 후에도 乙의 동의 없이 이를 철회할 수 있다.","乙이 우편물의 내용을 실제로 읽지 않았다면 해제의 효력은 생기지 않는다.","해제의 효력은 甲이 우편을 발송한 때에 생긴다.","해제의 의사표시가 도달한 때 乙이 미성년자였다면, 乙의 법정대리인이 도달 사실을 알기 전에도 甲은 그 효력을 주장할 수 있다.","甲이 우편을 발송한 후 도달 전에 성년후견개시의 심판을 받았더라도 해제의 의사표시의 효력에는 영향이 없다."],"a":[5],"L":"민1-2","o":"변형","x":{"한줄":"의사표시를 발송한 후 표의자가 제한능력자가 되어도 효력은 도달 시에 그대로 생긴다.","근거":[{"법령":"민법","조문":"제111조","원문":"① 상대방이 있는 의사표시는 상대방에게 도달한 때에 그 효력이 생긴다.\n② 의사표시자가 그 통지를 발송한 후 사망하거나 제한능력자가 되어도 의사표시의 효력에 영향을 미치지 아니한다."},{"법령":"민법","조문":"제543조","원문":"②전항의 의사표시는 철회하지 못한다."},{"법령":"민법","조문":"제112조","원문":"의사표시의 상대방이 의사표시를 받은 때에 제한능력자인 경우에는 의사표시자는 그 의사표시로써 대항할 수 없다. 다만, 그 상대방의 법정대리인이 의사표시가 도달한 사실을 안 후에는 그러하지 아니하다."}],"선지":[{"번호":1,"판정":"틀림","설명":"해제의 의사표시는 철회하지 못한다(제543조 제2항)."},{"번호":2,"판정":"틀림","설명":"도달은 상대방이 내용을 알 수 있는 상태에 놓이면 족하고, 실제로 읽었는지는 문제 되지 않는다."},{"번호":3,"판정":"틀림","설명":"상대방 있는 의사표시는 도달한 때 효력이 생긴다(제111조 제1항)."},{"번호":4,"판정":"틀림","설명":"상대방이 의사표시를 받은 때 제한능력자이면 법정대리인이 도달 사실을 알기 전에는 대항하지 못한다(제112조)."},{"번호":5,"판정":"옳음","설명":"발송 후 사망하거나 제한능력자가 되어도 효력에 영향이 없다(제111조 제2항)."}],"개념":[{"종류":"표","제목":"효력 발생 시기","머리":["구분","시기","조문"],"행":[["상대방 있는 의사표시 일반","도달한 때","제111조 제1항"],["격지자 사이의 계약 성립","승낙 통지를 발송한 때","제531조"],["제한능력자 상대방의 확답 촉구에 대한 확답","발송 기준(기간 내 발송 안 하면 추인 간주)","제15조"],["무권대리 상대방의 최고에 대한 확답","기간 내 발하지 않으면 추인 거절 간주","제131조"],["제한능력자에게 한 의사표시","법정대리인이 도달 사실을 안 후 대항 가능","제112조"]]}],"함정":"표의자가 사망하면 효력이 없어진다고 생각하기 쉽다. 발송 후 사망·제한능력은 영향이 없고, 문제는 상대방이 제한능력자인 경우다."}},{"i":"S2-1-1-민법-05","r":"S2","g":1,"c":1,"n":45,"s":"민법","q":"乙은 모친 甲 소유의 X토지에 관하여 대리권 없이 甲의 이름으로 丙과 매매계약을 체결하고 丙 앞으로 이전등기를 마쳤다. 표현대리는 성립하지 않는다. 다음 설명 중 틀린 것은? (다툼이 있으면 판례에 따름)","b":null,"bs":"없음","img":[],"ch":["甲이 乙의 행위를 추인하면 그 계약은 추인한 때부터 비로소 효력이 생긴다.","甲이 추인을 거절하면 무권대리행위는 확정적으로 무효가 되어 그 후에는 추인할 수 없다.","甲이 사망하여 乙이 단독상속한 경우, 乙은 본인의 지위에서 추인을 거절할 수 없다.","丙이 선의·무과실이면 丙은 乙에게 계약의 이행 또는 손해배상을 선택하여 청구할 수 있다.","추인의 의사표시를 乙에게 한 경우, 丙이 그 사실을 알기 전에는 甲은 丙에게 추인을 주장하지 못한다."],"a":[1],"L":"민1-3","o":"변형","x":{"한줄":"무권대리 추인은 다른 의사표시가 없으면 계약 시로 소급하여 효력이 생긴다.","근거":[{"법령":"민법","조문":"제133조","원문":"추인은 다른 의사표시가 없는 때에는 계약시에 소급하여 그 효력이 생긴다. 그러나 제삼자의 권리를 해하지 못한다."},{"법령":"민법","조문":"제135조","원문":"① 다른 자의 대리인으로서 계약을 맺은 자가 그 대리권을 증명하지 못하고 또 본인의 추인을 받지 못한 경우에는 그는 상대방의 선택에 따라 계약을 이행할 책임 또는 손해를 배상할 책임이 있다.\n② 대리인으로서 계약을 맺은 자에게 대리권이 없다는 사실을 상대방이 알았거나 알 수 있었을 때 또는 대리인으로서 계약을 맺은 사람이 제한능력자일 때에는 제1항을 적용하지 아니한다."},{"법령":"민법","조문":"제132조","원문":"추인 또는 거절의 의사표시는 상대방에 대하여 하지 아니하면 그 상대방에 대항하지 못한다. 그러나 상대방이 그 사실을 안 때에는 그러하지 아니하다."}],"선지":[{"번호":1,"판정":"틀림","설명":"추인은 소급효가 있다. 새로운 법률행위로 보는 것은 무효행위 추인(제139조 단서)이다."},{"번호":2,"판정":"옳음","설명":"추인을 거절하면 효력 불발생이 확정되어 다시 추인할 수 없다."},{"번호":3,"판정":"옳음","설명":"무권대리인이 본인을 상속한 경우 추인 거절은 신의칙에 반해 허용되지 않는다."},{"번호":4,"판정":"옳음","설명":"제135조 제1항. 상대방의 선의·무과실은 같은 조 제2항으로 요구된다."},{"번호":5,"판정":"옳음","설명":"제132조."}],"개념":[{"종류":"표","제목":"무권대리의 법률관계","머리":["주체","권리·책임","내용","조문"],"행":[["본인","추인권","소급 효력, 제3자 권리는 해하지 못함","제133조"],["본인","추인거절권","거절하면 확정적 무효","제130조"],["상대방","최고권","확답 없으면 거절 간주","제131조"],["상대방","철회권","선의일 때, 추인 전까지","제134조"],["무권대리인","이행 또는 손해배상 책임","상대방 선의·무과실, 무권대리인이 행위능력자일 때","제135조"]]},{"종류":"표","제목":"표현대리 3유형","머리":["유형","요건","상대방 요건","조문"],"행":[["대리권수여표시","본인이 대리권을 수여했다고 표시","선의·무과실","제125조"],["권한을 넘은 표현대리","기본대리권이 있고 권한 밖의 행위","정당한 이유(선의·무과실)","제126조"],["대리권소멸 후","대리권이 있었다가 소멸","선의·무과실","제129조"]]}],"함정":"추인을 새 법률행위로 보는 선지를 놓치기 쉽다. 무권대리 추인은 소급하고, 무효행위 추인은 비소급이다."}},{"i":"S2-1-1-민법-06","r":"S2","g":1,"c":1,"n":46,"s":"민법","q":"甲으로부터 甲소유 X토지의 매도 대리권을 수여받은 乙은 甲을 대리하여 丙과 X토지에 대한 매매계약을 체결하였다. 다음 설명 중 틀린 것은? (다툼이 있으면 판례에 따름)","b":null,"bs":"없음","img":[],"ch":["乙은 특별한 사정이 없는 한 매매잔금의 수령 권한을 가진다.","丙의 채무불이행이 있는 경우, 특별한 사정이 없는 한 乙은 매매계약을 해제할 수 없다.","매매계약의 해제로 인한 원상회복의무는 甲과 丙이 부담한다.","丙이 매매계약을 해제한 경우, 丙은 乙에게 채무불이행으로 인한 손해배상을 청구할 수 없다.","乙이 자기의 이익을 위하여 배임적 대리행위를 하였고 丙도 이를 안 경우, 乙의 대리행위는 甲에게 효력을 미친다."],"a":[5],"L":"민1-3","o":"기출","x":{"한줄":"대리인이 자기 이익을 위해 배임적 행위를 하고 상대방도 이를 알았다면 제107조 제1항 단서가 유추되어 본인에게 효력이 없다.","근거":[{"법령":"민법","조문":"제107조","원문":"①의사표시는 표의자가 진의아님을 알고 한 것이라도 그 효력이 있다. 그러나 상대방이 표의자의 진의아님을 알았거나 이를 알 수 있었을 경우에는 무효로 한다."},{"판례":"대법원 판례(대리권 남용)","요지":"대리인이 자기나 제3자의 이익을 도모하려 대리권을 남용한 경우, 상대방이 이를 알았거나 알 수 있었으면 제107조 제1항 단서를 유추해 본인에게 효력이 없다."}],"선지":[{"번호":1,"판정":"옳음","설명":"매매계약 체결 권한이 있으면 특별한 사정이 없는 한 잔금 수령 권한도 있다."},{"번호":2,"판정":"옳음","설명":"해제권은 대리권의 범위에 당연히 포함되지 않는다."},{"번호":3,"판정":"옳음","설명":"계약의 당사자는 본인이므로 원상회복의무도 본인이 진다."},{"번호":4,"판정":"옳음","설명":"대리인은 계약 당사자가 아니어서 손해배상 책임의 상대방이 아니다."},{"번호":5,"판정":"틀림","설명":"상대방이 대리권 남용을 알았거나 알 수 있었으면 본인에게 효력이 없다."}],"개념":[{"종류":"표","제목":"대리권의 범위","머리":["유형","범위","비고"],"행":[["권한을 정하지 않은 대리인","보존행위, 이용·개량행위(제118조)","처분행위는 불가"],["매매 대리인","중도금·잔금 수령 가능","특별한 사정이 없는 한"],["계약 체결 대리인","해제권은 당연히 포함되지 않음","별도 수권 필요"],["대리권 남용","상대방 악의·과실 시 본인에게 무효","제107조 제1항 단서 유추"]]}],"함정":"5번에서 대리인이 권한 내에서 행위했으니 유효라고 생각하기 쉽다. 상대방이 배임 사실을 알면 효력이 없다."}},{"i":"S2-1-1-민법-07","r":"S2","g":1,"c":1,"n":47,"s":"민법","q":"계약의 무권대리에 관한 설명으로 옳은 것은? (다툼이 있으면 판례에 따름)","b":null,"bs":"없음","img":[],"ch":["본인이 추인하면 특별한 사정이 없는 한 그때부터 계약의 효력이 생긴다.","본인의 추인의 의사표시는 무권대리행위로 인한 권리의 승계인에 대하여는 할 수 없다.","계약 당시 무권대리행위임을 알았던 상대방은 본인의 추인이 있을 때까지 의사표시를 철회할 수 있다.","무권대리의 상대방은 상당한 기간을 정하여 본인에게 추인여부의 확답을 최고할 수 있고, 본인이 그 기간 내에 확답을 발하지 않으면 추인한 것으로 본다.","본인이 무권대리행위를 안 후 그것이 자기에게 효력이 없다고 이의를 제기하지 않고 이를 장시간 방치한 사실만으로는 추인하였다고 볼 수 없다."],"a":[5],"L":"민1-3","o":"기출","x":{"한줄":"본인이 무권대리행위를 알고 이의 없이 오래 방치한 사실만으로는 추인으로 인정되지 않는다.","근거":[{"법령":"민법","조문":"제131조","원문":"대리권없는 자가 타인의 대리인으로 계약을 한 경우에 상대방은 상당한 기간을 정하여 본인에게 그 추인여부의 확답을 최고할 수 있다. 본인이 그 기간내에 확답을 발하지 아니한 때에는 추인을 거절한 것으로 본다."},{"법령":"민법","조문":"제134조","원문":"대리권없는 자가 한 계약은 본인의 추인이 있을 때까지 상대방은 본인이나 그 대리인에 대하여 이를 철회할 수 있다. 그러나 계약당시에 상대방이 대리권 없음을 안 때에는 그러하지 아니하다."}],"선지":[{"번호":1,"판정":"틀림","설명":"추인은 계약 시로 소급한다(제133조)."},{"번호":2,"판정":"틀림","설명":"추인은 무권대리행위로 인한 권리의 승계인에게도 할 수 있다."},{"번호":3,"판정":"틀림","설명":"계약 당시 대리권 없음을 안 상대방은 철회할 수 없다(제134조 단서)."},{"번호":4,"판정":"틀림","설명":"확답이 없으면 추인을 거절한 것으로 본다(제131조)."},{"번호":5,"판정":"옳음","설명":"방치만으로는 묵시적 추인이 아니다."}],"개념":[{"종류":"표","제목":"무권대리 상대방의 권리","머리":["권리","요건","효과","조문"],"행":[["최고권","선의·악의 불문","확답 없으면 거절 간주","제131조"],["철회권","선의일 것, 추인 전","계약 철회","제134조"],["무권대리인 책임 추궁","선의·무과실","이행 또는 손해배상","제135조"],["추인 거절의 확정","본인의 거절","이후 추인 불가","제130조"]]}],"함정":"4번에서 최고에 응하지 않으면 추인으로 본다고 오해하기 쉽다. 침묵은 거절이다."}},{"i":"S2-1-1-민법-08","r":"S2","g":1,"c":1,"n":48,"s":"민법","q":"법률행위의 무효에 관한 설명으로 틀린 것은? (다툼이 있으면 판례에 따름)","b":null,"bs":"없음","img":[],"ch":["무효행위의 추인은 묵시적인 방법으로도 할 수 있다.","무효행위의 추인은 그 무효 원인이 소멸한 후에 하여야 한다.","무효인 법률행위는 그에 따른 법률효과를 침해하는 것처럼 보이는 위법행위가 있더라도 법률효과의 침해에 따른 손해배상을 청구할 수 없다.","무권리자의 처분이 계약으로 이루어진 경우, 권리자가 이를 추인하면 계약의 효과는 원칙적으로 추인한 때부터 권리자에게 귀속한다.","토지거래허가구역 안의 토지거래계약이 허가를 받지 못해 유동적 무효인 상태에서 허가구역 지정이 해제되면 그 계약은 확정적 유효가 된다."],"a":[4],"L":"민1-4","o":"기출","x":{"한줄":"무권리자 처분의 추인은 무권대리 추인에 준해 계약 시로 소급하여 효력이 생긴다.","근거":[{"법령":"민법","조문":"제139조","원문":"무효인 법률행위는 추인하여도 그 효력이 생기지 아니한다. 그러나 당사자가 그 무효임을 알고 추인한 때에는 새로운 법률행위로 본다."},{"법령":"민법","조문":"제133조","원문":"추인은 다른 의사표시가 없는 때에는 계약시에 소급하여 그 효력이 생긴다. 그러나 제삼자의 권리를 해하지 못한다."},{"판례":"대법원 1999. 6. 17. 선고 98다40459 전원합의체 판결","요지":"토지거래허가구역 안의 허가 전 계약은 유동적 무효이고, 허가구역 지정이 해제되면 확정적으로 유효가 된다."}],"선지":[{"번호":1,"판정":"옳음","설명":"묵시적 추인도 가능하다."},{"번호":2,"판정":"옳음","설명":"무효 원인이 소멸한 후에 추인해야 새로운 법률행위로 효력이 있다."},{"번호":3,"판정":"옳음","설명":"무효인 법률행위에는 보호할 법률효과가 없다."},{"번호":4,"판정":"틀림","설명":"무권리자 처분의 추인은 소급한다. 무효행위 추인(비소급)과 구별한다."},{"번호":5,"판정":"옳음","설명":"지정 해제로 유동적 무효가 확정적 유효로 바뀐다."}],"개념":[{"종류":"표","제목":"무효를 살리는 길","머리":["구분","요건","효과","시점"],"행":[["일부무효(제137조)","무효 부분이 없어도 행위했을 것으로 인정","나머지 유효","-"],["무효행위 전환(제138조)","다른 법률행위의 요건 구비 + 당사자 의사","다른 법률행위로 유효","-"],["무효행위 추인(제139조)","무효임을 알고 추인","새로운 법률행위","추인한 때부터"],["무권대리·무권리자 처분 추인","본인·권리자의 추인","계약 시로 소급","소급"]]},{"종류":"표","제목":"무효와 취소 비교","머리":["구분","무효","취소"],"행":[["효력","처음부터 당연 무효","취소하면 처음부터 무효"],["주장권자","누구든지","취소권자만(제140조)"],["기간","제한 없음","추인할 수 있는 날부터 3년, 행위일부터 10년"],["추인","원칙 불가, 알고 추인 시 새 행위","추인하면 취소 불가"]]}],"함정":"4번을 비소급이라고 외운 무효행위 추인과 섞기 쉽다. 무권리자 처분 추인은 소급한다."}},{"i":"S2-1-1-민법-09","r":"S2","g":1,"c":1,"n":49,"s":"민법","q":"취소할 수 있는 법률행위에 관한 설명으로 옳은 것은?","b":null,"bs":"없음","img":[],"ch":["제한능력자는 법정대리인의 동의 없이는 자신의 행위를 취소할 수 없다.","취소권은 추인할 수 있는 날부터 10년, 법률행위를 한 날부터 3년 내에 행사하여야 한다.","취소권자가 이의를 보류하지 않고 추인할 수 있는 후에 전부나 일부의 이행을 한 경우, 추인한 것으로 본다.","법정대리인이 추인하는 경우에도 취소의 원인이 소멸한 후에 하여야 효력이 있다.","취소된 법률행위에서 제한능력자는 그 행위로 받은 이익 전부를 상환하여야 한다."],"a":[3],"L":"민1-4","o":"변형","x":{"한줄":"추인할 수 있는 후에 이의 없이 전부나 일부를 이행하면 법정추인이 된다.","근거":[{"법령":"민법","조문":"제145조","원문":"취소할 수 있는 법률행위에 관하여 전조의 규정에 의하여 추인할 수 있는 후에 다음 각호의 사유가 있으면 추인한 것으로 본다. 그러나 이의를 보류한 때에는 그러하지 아니하다.\n  1. 전부나 일부의 이행"},{"법령":"민법","조문":"제146조","원문":"취소권은 추인할 수 있는 날로부터 3년내에 법률행위를 한 날로부터 10년내에 행사하여야 한다."},{"법령":"민법","조문":"제144조","원문":"② 제1항은 법정대리인 또는 후견인이 추인하는 경우에는 적용하지 아니한다."}],"선지":[{"번호":1,"판정":"틀림","설명":"제한능력자도 단독으로 취소할 수 있다(제140조)."},{"번호":2,"판정":"틀림","설명":"기간이 거꾸로다. 추인할 수 있는 날부터 3년, 행위일부터 10년이다(제146조)."},{"번호":3,"판정":"옳음","설명":"제145조 제1호."},{"번호":4,"판정":"틀림","설명":"법정대리인의 추인에는 원인소멸 요건이 적용되지 않는다(제144조 제2항)."},{"번호":5,"판정":"틀림","설명":"제한능력자는 현존이익의 한도에서만 상환한다(제141조 단서)."}],"개념":[{"종류":"표","제목":"법정추인 사유(제145조)","머리":["호","사유","비고"],"행":[["1","전부나 일부의 이행","취소권자가 이행한 경우와 상대방 이행을 수령한 경우"],["2","이행의 청구","취소권자가 청구"],["3","경개","-"],["4","담보의 제공","취소권자가 제공하거나 수령"],["5","취소할 수 있는 행위로 취득한 권리의 양도","-"],["6","강제집행","-"]]},{"종류":"표","제목":"취소권 행사 기간(제146조)","머리":["기산점","기간","성질"],"행":[["추인할 수 있는 날","3년","제척기간"],["법률행위를 한 날","10년","제척기간, 먼저 끝나는 기간으로 소멸"]]}],"함정":"기간 숫자를 바꿔 낸 2번을 고르기 쉽다. 3년은 추인할 수 있는 날, 10년은 행위일이다."}},{"i":"S2-1-1-민법-10","r":"S2","g":1,"c":1,"n":50,"s":"민법","q":"법률행위의 부관에 관한 설명으로 틀린 것은? (다툼이 있으면 판례에 따름)","b":null,"bs":"없음","img":[],"ch":["조건의사가 있더라도 외부에 표시되지 않으면 그것만 으로는 조건이 되지 않는다.","기한이익 상실특약은 특별한 사정이 없는 한 정지조건부기한이익 상실특약으로 추정한다.","조건을 붙일 수 없는 법률행위에 조건을 붙인 경우, 다른 정함이 없으면 그 법률행위 전부가 무효로 된다.","'정지조건부 법률행위에 해당한다는 사실'에 대한 증명책임은 그 법률행위로 인한 법률효과의 발생을 다투는 자에게 있다.","불확정한 사실이 발생한 때를 이행기한으로 정한 경우, 그 사실의 발생이 불가능하게 된 때에도 기한이 도래한 것으로 보아야 한다."],"a":[2],"L":"민1-5","o":"기출","x":{"한줄":"기한이익 상실특약은 특별한 사정이 없는 한 채권자의 청구가 있어야 상실되는 형성권적 상실특약으로 추정한다.","근거":[{"법령":"민법","조문":"제153조","원문":"①기한은 채무자의 이익을 위한 것으로 추정한다.\n②기한의 이익은 이를 포기할 수 있다. 그러나 상대방의 이익을 해하지 못한다."},{"판례":"대법원 판례(기한이익 상실특약)","요지":"기한이익 상실특약은 특별한 사정이 없는 한 형성권적 기한이익 상실특약으로 추정한다. 정지조건부 특약으로 보려면 그런 취지가 인정되어야 한다."}],"선지":[{"번호":1,"판정":"옳음","설명":"표시되지 않은 조건의사는 조건이 아니다."},{"번호":2,"판정":"틀림","설명":"정지조건부가 아니라 형성권적 특약으로 추정한다."},{"번호":3,"판정":"옳음","설명":"조건을 붙일 수 없는 행위(혼인, 상계 등)에 조건을 붙이면 전부 무효다."},{"번호":4,"판정":"옳음","설명":"정지조건 사실은 효력 발생을 다투는 자가 증명한다."},{"번호":5,"판정":"옳음","설명":"불확정기한은 사실이 발생하거나 발생하지 않기로 확정된 때 도래한다."}],"개념":[{"종류":"표","제목":"조건과 기한","머리":["구분","조건","기한"],"행":[["내용","발생 여부가 불확실","도래가 확실"],["효력","정지조건: 성취 시 발생 / 해제조건: 성취 시 소멸(제147조)","시기: 도래 시 발생 / 종기: 도래 시 소멸(제152조)"],["소급","당사자 의사로 소급 가능(제147조 제3항)","-"],["이익","-","채무자의 이익으로 추정, 포기 가능(제153조)"],["붙일 수 없는 행위","혼인, 입양, 상계, 취소, 추인 등","-"]]},{"종류":"표","제목":"조건 관련 특수 문제","머리":["유형","효과","조문"],"행":[["불법조건","법률행위 전부 무효","제151조 제1항"],["기성조건","정지조건이면 조건 없는 행위, 해제조건이면 무효","제151조 제2항"],["불능조건","해제조건이면 조건 없는 행위, 정지조건이면 무효","제151조 제3항"],["반신의행위","방해로 조건성취 주장 가능","제150조"]]}],"함정":"2번을 정지조건부로 외우기 쉽다. 판례는 청구가 있어야 상실되는 형성권적 특약으로 추정한다."}},{"i":"S2-1-1-민법-11","r":"S2","g":1,"c":1,"n":51,"s":"민법","q":"물권에 관한 설명으로 틀린 것은? (다툼이 있으면 판례에 따름)","b":null,"bs":"없음","img":[],"ch":["민법 제185조에서의 '법률'은 국회가 제정한 형식적 의미의 법률을 의미한다.","사용ㆍ수익 권능을 대세적ㆍ영구적으로 포기한 소유권도 존재한다.","처분권능이 없는 소유권은 인정되지 않는다.","근린공원을 자유롭게 이용한 사정만으로 공원이용권이라는 배타적 권리를 취득하였다고 볼 수는 없다.","온천에 관한 권리를 관습법상의 물권이라고 볼 수는 없다."],"a":[2],"L":"민2-1","o":"기출","x":{"한줄":"사용·수익 권능을 영구적으로 포기한 소유권은 물권법정주의에 반해 인정되지 않는다.","근거":[{"법령":"민법","조문":"제185조","원문":"물권은 법률 또는 관습법에 의하는 외에는 임의로 창설하지 못한다."}],"선지":[{"번호":1,"판정":"옳음","설명":"제185조의 법률은 형식적 의미의 법률이고 명령·규칙은 포함되지 않는다."},{"번호":2,"판정":"틀림","설명":"소유권의 핵심 권능을 영구적으로 배제하는 것은 내용 강제에 반해 허용되지 않는다."},{"번호":3,"판정":"옳음","설명":"처분권능은 소유권의 본질이어서 이를 배제한 소유권은 인정되지 않는다."},{"번호":4,"판정":"옳음","설명":"반사적 이익에 불과하다."},{"번호":5,"판정":"옳음","설명":"온천권은 관습법상 물권이 아니다."}],"개념":[{"종류":"표","제목":"물권법정주의","머리":["항목","내용"],"행":[["창설 근거","법률 또는 관습법(제185조)"],["법률","국회가 제정한 형식적 의미의 법률"],["관습법상 물권","분묘기지권, 관습법상 법정지상권, 동산 양도담보 등"],["관습법상 물권이 아닌 것","온천권, 공원이용권"],["내용 강제","소유권의 사용·수익·처분권능 영구 배제 불가"]]}],"함정":"2번의 소유권 권능 포기는 계약자유로 허용된다고 보기 쉽다. 물권법정주의에 반해 불가하다."}},{"i":"S2-1-1-민법-12","r":"S2","g":1,"c":1,"n":52,"s":"민법","q":"물권에 관한 설명으로 옳은 것은? (다툼이 있으면 판례에 따름)","b":null,"bs":"없음","img":[],"ch":["물건 이외의 재산권은 물권의 객체가 될 수 없다.","물권은 부동산등기규칙에 의해 창설될 수 있다.","구분소유의 목적이 되는 건물의 등기부상 표시에서 전유부분의 면적 표시가 잘못된 경우, 그 잘못 표시된 면적만큼의 소유권보존등기를 말소할 수 없다.","1필의 토지의 일부를 객체로 하여 지상권을 설정할 수 없다.","기술적인 착오로 지적도의 경계선이 실제 경계선과 다르게 작성된 경우, 토지의 경계는 지적도의 경계선에 의해 확정된다."],"a":[3],"L":"민2-1","o":"기출","x":{"한줄":"전유부분의 면적 표시가 잘못된 경우 그 부분만 떼어 보존등기를 말소할 수 없다는 것이 판례다.","근거":[{"법령":"민법","조문":"제185조","원문":"물권은 법률 또는 관습법에 의하는 외에는 임의로 창설하지 못한다."}],"선지":[{"번호":1,"판정":"틀림","설명":"지상권·전세권 등 권리도 저당권·권리질권의 객체가 된다."},{"번호":2,"판정":"틀림","설명":"규칙은 법률이 아니다(제185조)."},{"번호":3,"판정":"옳음","설명":"일부 면적 표시의 오류는 일부 말소의 대상이 되지 않는다."},{"번호":4,"판정":"틀림","설명":"1필 토지의 일부에도 지상권을 설정할 수 있다."},{"번호":5,"판정":"틀림","설명":"기술적 착오로 잘못 작성된 지적도는 경계 확정의 기준이 되지 않고 실제 경계를 따른다."}],"개념":[{"종류":"표","제목":"물권의 객체","머리":["구분","내용"],"행":[["원칙","독립한 특정의 물건(일물일권)"],["일부 객체","1필 토지의 일부에 지상권·지역권·전세권 설정 가능, 소유권은 불가"],["권리","지상권·전세권은 저당권의 객체, 권리질권"],["집합물","구성 부분 특정 가능하면 양도담보 가능"],["구분소유","전유부분 면적 오류만큼의 보존등기 일부 말소 불가"]]}],"함정":"4번의 토지 일부 지상권 불가는 일물일권 때문에 헷갈린다. 지상권은 토지 일부에도 설정된다."}},{"i":"S2-1-1-민법-13","r":"S2","g":1,"c":1,"n":53,"s":"민법","q":"다음 중 서로 잘못 짝지어진 것은?","b":null,"bs":"없음","img":[],"ch":["상속에 의한 소유권 취득 - 포괄승계","건물 신축에 의한 소유권 취득 - 원시취득","채권양도 - 준물권행위","취득시효 완성에 의한 소유권 취득 - 승계취득","전세권의 설정 - 설정적 승계"],"a":[4],"L":"민2-2","o":"변형","x":{"한줄":"시효취득은 종전 소유자의 권리와 관계없이 새로 취득하는 원시취득이다.","근거":[{"법령":"민법","조문":"제245조","원문":"①20년간 소유의 의사로 평온, 공연하게 부동산을 점유하는 자는 등기함으로써 그 소유권을 취득한다."},{"이론":"권리변동의 분류","내용":"원시취득은 타인의 권리에 바탕을 두지 않는 취득(신축, 선점, 시효취득), 승계취득은 타인 권리에 바탕을 둔 취득이다. 승계취득은 이전적 승계(특정승계·포괄승계)와 설정적 승계(제한물권 설정)로 나뉜다."}],"선지":[{"번호":1,"판정":"옳음","설명":"상속은 피상속인의 권리를 일괄 승계하는 포괄승계다."},{"번호":2,"판정":"옳음","설명":"신축 건물은 새로 생긴 물건이라 원시취득이다."},{"번호":3,"판정":"옳음","설명":"채권양도는 채권을 변동시키는 준물권행위다."},{"번호":4,"판정":"틀림","설명":"시효취득은 원시취득이다."},{"번호":5,"판정":"옳음","설명":"제한물권 설정은 설정적 승계다."}],"개념":[{"종류":"표","제목":"권리변동의 분류","머리":["구분","종류","예"],"행":[["원시취득","-","신축, 무주물 선점, 시효취득, 선의취득"],["승계취득","이전적 승계(특정승계)","매매에 의한 소유권 이전"],["승계취득","이전적 승계(포괄승계)","상속, 합병"],["승계취득","설정적 승계","지상권·전세권·저당권 설정"],["법률행위 종류","준물권행위","채권양도, 채무면제"]]},{"종류":"표","제목":"등기 없이 물권이 바뀌는 경우(제187조)","머리":["사유","등기 없이 취득","처분"],"행":[["상속","가능","등기해야 처분 가능"],["공용징수","가능","등기해야 처분 가능"],["판결(형성판결)","가능","등기해야 처분 가능"],["경매","가능","등기해야 처분 가능"],["점유취득시효","불가(등기해야 취득, 제245조 제1항)","-"]]}],"함정":"4번에서 시효취득을 승계로 보는 것이 헷갈린다. 점유 기간이 이어져도 원시취득이다."}},{"i":"S2-1-1-민법-14","r":"S2","g":1,"c":1,"n":54,"s":"민법","q":"간접점유에 관한 설명으로 틀린 것은? (다툼이 있으면 판례에 따름)","b":null,"bs":"없음","img":[],"ch":["임차인이 임차물을 전대한 경우, 임대인도 간접점유자가 될 수 있다.","직접점유자의 점유가 침탈된 경우, 간접점유자는 자기에게 반환할 것을 먼저 청구할 수 있다.","점유보조자는 점유자가 아니고 그에게 지시를 한 타인만이 점유자이다.","제3자가 직접점유자의 점유를 방해하는 경우, 간접점유자도 방해의 제거를 청구할 수 있다.","주택임차인이 주택을 간접점유하는 방법으로 인도를 받은 경우에도 대항요건의 인도가 인정될 수 있다."],"a":[2],"L":"민2-3","o":"변형","x":{"한줄":"점유가 침탈된 경우 간접점유자는 먼저 직접점유자에게 반환할 것을 청구하고, 직접점유자가 반환받을 수 없거나 원하지 않을 때 자기에게 반환을 청구한다.","근거":[{"법령":"민법","조문":"제207조","원문":"②점유자가 점유의 침탈을 당한 경우에 간접점유자는 그 물건을 점유자에게 반환할 것을 청구할 수 있고 점유자가 그 물건의 반환을 받을 수 없거나 이를 원하지 아니하는 때에는 자기에게 반환할 것을 청구할 수 있다."},{"법령":"민법","조문":"제195조","원문":"가사상, 영업상 기타 유사한 관계에 의하여 타인의 지시를 받어 물건에 대한 사실상의 지배를 하는 때에는 그 타인만을 점유자로 한다."},{"법령":"민법","조문":"제194조","원문":"지상권, 전세권, 질권, 사용대차, 임대차, 임치 기타의 관계로 타인으로 하여금 물건을 점유하게 한 자는 간접으로 점유권이 있다."}],"선지":[{"번호":1,"판정":"옳음","설명":"간접점유는 여러 단계로 겹칠 수 있다(제194조)."},{"번호":2,"판정":"틀림","설명":"먼저 직접점유자에게 반환을 청구하는 것이 원칙이다(제207조 제2항)."},{"번호":3,"판정":"옳음","설명":"점유보조자는 제195조에 의해 점유자가 아니다."},{"번호":4,"판정":"옳음","설명":"간접점유자도 제204~206조의 청구권을 가진다(제207조 제1항)."},{"번호":5,"판정":"옳음","설명":"임차인의 간접점유 취득도 대항요건의 인도로 인정된다."}],"개념":[{"종류":"표","제목":"점유보호청구권(제204~206조)","머리":["청구권","요건","내용","행사 기간"],"행":[["점유회수","점유 침탈","반환·손해배상","침탈 날부터 1년"],["점유보유","점유 방해","방해 제거·손해배상","방해 종료일부터 1년(공사 시 착수 후 1년 경과 또는 완성 시 제거 불가)"],["점유보전","방해 염려","방해 예방·손해배상 담보","-"],["회수 상대방","침탈자 및 악의의 특별승계인","선의의 특별승계인에게는 불가","-"]]},{"종류":"비교","제목":"간접점유자와 점유보조자","왼쪽":{"이름":"간접점유자","항목":["점유매개관계에 의해 점유를 가짐(제194조)","점유권 있음","점유보호청구권 행사 가능(제207조)"]},"오른쪽":{"이름":"점유보조자","항목":["타인의 지시를 받아 사실상 지배(제195조)","점유자 아님","지시한 타인만 점유자"]}}],"함정":"침탈 시 곧바로 자기에게 반환을 청구한다고 보기 쉽다. 순서는 직접점유자에게 먼저다."}},{"i":"S2-1-1-민법-15","r":"S2","g":1,"c":1,"n":55,"s":"민법","q":"민법상 합유에 관한 설명으로 틀린 것은? (특약은 없으며, 다툼이 있으면 판례에 따름)","b":null,"bs":"없음","img":[],"ch":["합유자의 권리는 합유물 전부에 미친다.","합유자는 합유물의 분할을 청구하지 못한다.","합유자 중 1인이 사망하면 그의 상속인이 합유자의 지위를 승계한다.","합유물의 보존행위는 합유자 각자가 할 수 있다.","합유자는 그 전원의 동의 없이 합유지분을 처분하지 못한다."],"a":[3],"L":"민2-4","o":"기출","x":{"한줄":"합유자가 사망하면 합유지분은 상속되지 않고 잔존 합유자의 합유로 귀속된다.","근거":[{"법령":"민법","조문":"제271조","원문":"①법률의 규정 또는 계약에 의하여 수인이 조합체로서 물건을 소유하는 때에는 합유로 한다. 합유자의 권리는 합유물 전부에 미친다."},{"법령":"민법","조문":"제273조","원문":"①합유자는 전원의 동의없이 합유물에 대한 지분을 처분하지 못한다.\n②합유자는 합유물의 분할을 청구하지 못한다."},{"법령":"민법","조문":"제272조","원문":"합유물을 처분 또는 변경함에는 합유자 전원의 동의가 있어야 한다. 그러나 보존행위는 각자가 할 수 있다."}],"선지":[{"번호":1,"판정":"옳음","설명":"제271조 제1항."},{"번호":2,"판정":"옳음","설명":"제273조 제2항."},{"번호":3,"판정":"틀림","설명":"합유지분은 상속의 대상이 아니다. 특약이 없으면 잔존 합유자에게 귀속된다."},{"번호":4,"판정":"옳음","설명":"제272조 단서."},{"번호":5,"판정":"옳음","설명":"제273조 제1항."}],"개념":[{"종류":"표","제목":"공유·합유·총유 비교","머리":["구분","주체","지분 처분","물건 처분","분할","사망 시"],"행":[["공유","개인 간","자유","전원 동의","자유(제268조)","상속"],["합유","조합체","전원 동의","전원 동의","불가","잔존자에 귀속(상속 안 됨)"],["총유","법인 아닌 사단","지분 없음","사원총회 결의","없음","사원 지위 상실"]]}],"함정":"3번에서 합유자도 사망 시 상속된다고 생각하기 쉽다. 합유 지분은 상속되지 않는다."}},{"i":"S2-1-1-민법-16","r":"S2","g":1,"c":1,"n":56,"s":"민법","q":"甲, 乙, 丙이 각 1/3 지분으로 나대지인 X토지를 공유하고 있다. 이에 관한 설명으로 틀린 것은? (다툼이 있으면 판례에 따름)","b":null,"bs":"없음","img":[],"ch":["甲은 X토지를 무단 점유하는 제3자 戊에게 X토지 전부의 인도를 청구할 수 있다.","甲과 乙은 丙의 동의 없이 X토지를 丁에게 임대할 수 있다.","丙이 X토지 전부를 단독으로 배타적으로 사용하고 있다면, 甲은 자기 지분에 상응하는 부당이득의 반환을 청구할 수 있다.","甲이 乙·丙의 동의 없이 X토지 전부를 丁에게 매도하고 이전등기를 마친 경우, 甲의 지분도 丁에게 이전되지 않는다.","甲이 공유지분을 포기한 경우, 등기를 하여야 포기에 따른 물권변동의 효력이 생긴다."],"a":[4],"L":"민2-4","o":"변형","x":{"한줄":"다른 공유자의 동의 없이 공유물 전부를 처분해도 처분자 자신의 지분 범위에서는 효력이 있다.","근거":[{"법령":"민법","조문":"제264조","원문":"공유자는 다른 공유자의 동의없이 공유물을 처분하거나 변경하지 못한다."},{"법령":"민법","조문":"제265조","원문":"공유물의 관리에 관한 사항은 공유자의 지분의 과반수로써 결정한다. 그러나 보존행위는 각자가 할 수 있다."},{"법령":"민법","조문":"제267조","원문":"공유자가 그 지분을 포기하거나 상속인없이 사망한 때에는 그 지분은 다른 공유자에게 각 지분의 비율로 귀속한다."}],"선지":[{"번호":1,"판정":"옳음","설명":"제3자에 대한 인도청구는 보존행위로서 각자가 할 수 있다."},{"번호":2,"판정":"옳음","설명":"임대는 관리행위이므로 과반수 지분(2/3)으로 결정할 수 있다."},{"번호":3,"판정":"옳음","설명":"지분을 넘는 배타적 사용에는 부당이득이 성립한다."},{"번호":4,"판정":"틀림","설명":"자기 지분의 범위에서는 유효하게 이전된다."},{"번호":5,"판정":"옳음","설명":"법률행위(포기)에 의한 변동이므로 등기가 필요하다(제186조)."}],"개념":[{"종류":"표","제목":"공유물에 관한 행위","머리":["유형","요건","예"],"행":[["지분 처분","단독","지분 양도, 담보 설정"],["공유물 처분·변경","전원 동의(제264조)","매도, 건물 신축"],["관리","지분 과반수(제265조)","임대, 임대차 해지, 사용방법 결정"],["보존","각자 단독(제265조 단서)","제3자에 대한 인도·말소 청구"],["비용 부담","지분 비율, 1년 이상 지체 시 지분 매수 가능(제266조)","-"]]}],"함정":"4번에서 동의 없는 처분은 전부 무효라고 생각하기 쉽다. 자기 지분 범위에서는 유효하다."}},{"i":"S2-1-1-민법-17","r":"S2","g":1,"c":1,"n":57,"s":"민법","q":"합유에 관한 설명으로 틀린 것은? (다툼이 있으면 판례에 따름)","b":null,"bs":"없음","img":[],"ch":["합유자 중 1인이 합유물 전부를 단독으로 제3자에게 처분하고 이전등기를 한 경우, 자기 지분의 범위에서는 유효하다.","합유자는 전원의 동의 없이 합유지분을 처분하지 못한다.","합유자 중 1인이 사망한 경우 특약이 없으면, 잔존 합유자가 2인 이상일 때 합유물은 잔존 합유자의 합유로 귀속된다.","조합체의 해산으로 합유는 종료하고, 합유물의 분할에는 공유물 분할에 관한 규정이 준용된다.","합유물에 대한 방해제거청구는 보존행위로서 합유자 각자가 할 수 있다."],"a":[1],"L":"민2-4","o":"변형","x":{"한줄":"합유는 지분이 합유물 전부에 미치는 구조여서, 전원 동의 없는 처분은 자기 지분 범위에서도 유효하지 않다.","근거":[{"법령":"민법","조문":"제272조","원문":"합유물을 처분 또는 변경함에는 합유자 전원의 동의가 있어야 한다. 그러나 보존행위는 각자가 할 수 있다."},{"법령":"민법","조문":"제273조","원문":"①합유자는 전원의 동의없이 합유물에 대한 지분을 처분하지 못한다."},{"법령":"민법","조문":"제274조","원문":"①합유는 조합체의 해산 또는 합유물의 양도로 인하여 종료한다.\n②전항의 경우에 합유물의 분할에 관하여는 공유물의 분할에 관한 규정을 준용한다."}],"선지":[{"번호":1,"판정":"틀림","설명":"합유물의 처분은 전원 동의가 필요하며, 동의 없는 처분은 자기 지분 범위에서도 효력이 없다."},{"번호":2,"판정":"옳음","설명":"제273조 제1항."},{"번호":3,"판정":"옳음","설명":"사망한 합유자의 지분은 상속되지 않고 잔존 합유자에게 귀속된다."},{"번호":4,"판정":"옳음","설명":"제274조."},{"번호":5,"판정":"옳음","설명":"제272조 단서."}],"개념":[{"종류":"비교","제목":"공유와 합유","왼쪽":{"이름":"공유","항목":["지분을 자유롭게 처분(제263조)","분할 청구 자유(제268조)","관리는 지분 과반수","지분은 상속됨"]},"오른쪽":{"이름":"합유","항목":["지분 처분에 전원 동의(제273조 제1항)","분할 청구 불가(제273조 제2항)","처분·변경은 전원 동의, 보존은 각자","지분은 상속되지 않음"]}}],"함정":"1번을 공유에서처럼 지분 범위 내 유효로 보기 쉽다. 합유는 지분 처분 자체가 제한된다."}},{"i":"S2-1-1-민법-18","r":"S2","g":1,"c":1,"n":58,"s":"민법","q":"법정지상권에 관한 설명으로 옳은 것은? (다툼이 있으면 판례에 따름)","b":null,"bs":"없음","img":[],"ch":["저당권 설정 당시 토지 위에 건물이 없었더라도 그 후 토지소유자가 건물을 신축하였다면, 저당권 실행 경매 시 법정지상권이 성립한다.","법정지상권의 지료는 당사자의 합의가 없으면 무상이다.","저당권 설정 당시 토지와 건물이 동일인 소유였다면, 그 후 건물이 제3자에게 양도되어 소유자가 달라졌더라도 토지 경매 시 법정지상권이 성립한다.","법정지상권자가 2년 이상 지료를 지급하지 않으면 지상권은 당연히 소멸한다.","토지와 건물에 공동저당권이 설정된 후 건물이 철거되고 새 건물이 신축된 경우, 신축 건물을 위한 법정지상권이 성립한다."],"a":[3],"L":"민2-5","o":"변형","x":{"한줄":"제366조의 요건은 저당권 설정 당시 토지와 건물이 동일인 소유였는지이고, 그 후 소유자가 갈려도 법정지상권은 성립한다.","근거":[{"법령":"민법","조문":"제366조","원문":"저당물의 경매로 인하여 토지와 그 지상건물이 다른 소유자에 속한 경우에는 토지소유자는 건물소유자에 대하여 지상권을 설정한 것으로 본다. 그러나 지료는 당사자의 청구에 의하여 법원이 이를 정한다."},{"법령":"민법","조문":"제287조","원문":"지상권자가 2년 이상의 지료를 지급하지 아니한 때에는 지상권설정자는 지상권의 소멸을 청구할 수 있다."}],"선지":[{"번호":1,"판정":"틀림","설명":"저당권 설정 당시 건물이 존재하지 않으면 법정지상권은 성립하지 않는다."},{"번호":2,"판정":"틀림","설명":"지료는 당사자의 청구에 의해 법원이 정한다(제366조 단서)."},{"번호":3,"판정":"옳음","설명":"저당권 설정 당시 동일인 소유이면 족하다."},{"번호":4,"판정":"틀림","설명":"2년 이상의 지료 연체는 소멸 청구 사유이고(제287조), 당연 소멸은 아니다."},{"번호":5,"판정":"틀림","설명":"공동저당 후 건물이 철거·신축된 경우 신축 건물에는 법정지상권이 성립하지 않는다는 것이 판례다."}],"개념":[{"종류":"표","제목":"법정지상권의 종류","머리":["종류","근거","요건"],"행":[["저당권 실행","제366조","저당권 설정 당시 토지·건물 동일인 소유, 경매로 소유자 분리"],["건물 전세권","제305조","동일 소유자의 대지·건물, 건물에 전세권 설정 후 대지 소유권 특별승계"],["입목법","입목에 관한 법률 제6조","토지와 입목 소유자 분리"],["가등기담보","가등기담보법 제10조","토지·건물 동일 소유자, 담보 목적 가등기 후 본등기"],["관습법상","관습법","동일인 소유 토지·건물이 매매 등으로 분리, 철거 특약 없음"]]},{"종류":"표","제목":"지상권 존속기간·지료","머리":["항목","내용","조문"],"행":[["최단 기간(견고한 건물·수목)","30년","제280조"],["최단 기간(그 밖의 건물)","15년","제280조"],["최단 기간(공작물)","5년","제280조"],["소멸청구","2년 이상 지료 연체","제287조"],["지료","당사자 청구에 의해 법원이 결정","제366조 단서"]]}],"함정":"공동저당 후 신축 건물에도 성립한다고 보기 쉽다. 담보가치 보호 때문에 성립하지 않는다."}},{"i":"S2-1-1-민법-19","r":"S2","g":1,"c":1,"n":59,"s":"민법","q":"지역권에 관한 설명으로 틀린 것은? (다툼이 있으면 판례에 따름)","b":null,"bs":"없음","img":[],"ch":["지역권은 요역지 소유권에 부종하여 이전하는 것이 원칙이다.","승역지 소유자는 지역권의 행사를 방해하지 않는 범위에서 지역권자가 설치한 공작물을 사용할 수 있고, 수익 비율로 비용을 분담한다.","토지공유자의 1인은 자기 지분에 관하여 그 토지가 부담한 지역권을 소멸하게 하지 못한다.","요역지가 공유인 경우 그 1인에 의한 지역권 소멸시효의 중단은 다른 공유자를 위해서도 효력이 있다.","지역권은 계속되지 않더라도 표현된 것이면 시효취득할 수 있다."],"a":[5],"L":"민2-5","o":"변형","x":{"한줄":"지역권은 계속되고 표현된 것에 한하여 시효취득할 수 있어, 계속되지 않는 지역권은 시효취득할 수 없다.","근거":[{"법령":"민법","조문":"제294조","원문":"지역권은 계속되고 표현된 것에 한하여 제245조의 규정을 준용한다."},{"법령":"민법","조문":"제292조","원문":"①지역권은 요역지소유권에 부종하여 이전하며 또는 요역지에 대한 소유권이외의 권리의 목적이 된다. 그러나 다른 약정이 있는 때에는 그 약정에 의한다."},{"법령":"민법","조문":"제293조","원문":"①토지공유자의 1인은 지분에 관하여 그 토지를 위한 지역권 또는 그 토지가 부담한 지역권을 소멸하게 하지 못한다."}],"선지":[{"번호":1,"판정":"옳음","설명":"제292조 제1항."},{"번호":2,"판정":"옳음","설명":"제300조."},{"번호":3,"판정":"옳음","설명":"제293조 제1항."},{"번호":4,"판정":"옳음","설명":"제296조."},{"번호":5,"판정":"틀림","설명":"계속과 표현이 모두 필요하다(제294조)."}],"개념":[{"종류":"표","제목":"지역권의 성질","머리":["성질","내용","조문"],"행":[["부종성","요역지와 분리하여 양도·처분 불가","제292조"],["불가분성","공유자 1인의 소멸 불가, 취득 시 모두 취득","제293조, 제295조"],["시효취득","계속되고 표현된 것에 한함","제294조"],["소멸시효","요역지 공유자 1인의 중단·정지는 다른 공유자에게도 효력","제296조"],["준용","방해제거·예방청구권(제214조)","제301조"]]},{"종류":"비교","제목":"지상권과 지역권","왼쪽":{"이름":"지상권","항목":["타인 토지에서 건물·공작물·수목을 소유(제279조)","존속기간 최단 규정(제280조)","지료 청구 가능","토지 이용 자체가 목적"]},"오른쪽":{"이름":"지역권","항목":["자기 토지의 편익을 위해 타인 토지 이용(제291조)","요역지에 부종","시효취득은 계속·표현에 한함","요역지와 분리 처분 불가"]}}],"함정":"5번에서 표현만으로 족하다고 보기 쉽다. 계속과 표현이 모두 요구된다."}},{"i":"S2-1-1-민법-20","r":"S2","g":1,"c":1,"n":60,"s":"민법","q":"지역권에 관한 설명으로 틀린 것은? (다툼이 있으면 판례에 따름)","b":null,"bs":"없음","img":[],"ch":["지역권은 요역지와 분리하여 양도할 수 없다.","공유자 중 1인이 지역권을 취득한 때에는 다른 공유자도 이를 취득한다.","통행지역권을 주장하는 자는 통행으로 편익을 얻는 요역지가 있음을 주장ㆍ증명해야 한다.","요역지의 불법점유자도 통행지역권을 시효취득할 수 있다.","지역권은 계속되고 표현된 것에 한하여 시효취득할 수 있다."],"a":[4],"L":"민2-5","o":"기출","x":{"한줄":"요역지의 불법점유자는 통행지역권을 시효취득할 수 없다는 것이 판례다.","근거":[{"법령":"민법","조문":"제292조","원문":"②지역권은 요역지와 분리하여 양도하거나 다른 권리의 목적으로 하지 못한다."},{"법령":"민법","조문":"제295조","원문":"①공유자의 1인이 지역권을 취득한 때에는 다른 공유자도 이를 취득한다."},{"법령":"민법","조문":"제294조","원문":"지역권은 계속되고 표현된 것에 한하여 제245조의 규정을 준용한다."}],"선지":[{"번호":1,"판정":"옳음","설명":"제292조 제2항."},{"번호":2,"판정":"옳음","설명":"제295조 제1항."},{"번호":3,"판정":"옳음","설명":"요역지의 존재는 지역권을 주장하는 자가 증명한다."},{"번호":4,"판정":"틀림","설명":"불법점유자는 요역지를 정당하게 이용하는 자가 아니라서 통행지역권을 시효취득하지 못한다."},{"번호":5,"판정":"옳음","설명":"제294조."}],"개념":[{"종류":"표","제목":"지역권 시효취득","머리":["요건","내용"],"행":[["객체","계속되고 표현된 지역권"],["통행지역권","요역지 소유자가 승역지에 통로를 개설하고 계속 통행"],["취득 주체","요역지의 소유자(불법점유자 제외)"],["공유","1인이 취득하면 전원 취득(제295조 제1항)"],["기간","제245조 준용(20년 점유 등)"]]}],"함정":"4번의 불법점유자 시효취득을 허용된다고 보기 쉽다. 정당한 이용권원이 없어서 불가하다."}},{"i":"S2-1-1-민법-21","r":"S2","g":1,"c":1,"n":61,"s":"민법","q":"전세권에 관한 설명으로 옳은 것은? (다툼이 있으면 판례에 따름)","b":null,"bs":"없음","img":[],"ch":["전세금의 지급은 전세권 성립의 요소이므로 현실로 수수되어야 하고, 기존의 채권으로 갈음할 수 없다.","건물의 일부에 전세권을 설정한 전세권자는 전세금의 반환이 지체되면 건물 전부에 대하여 경매를 청구할 수 있다.","건물에 대한 전세권의 존속기간을 6개월로 정한 경우 그 약정대로 6개월의 존속기간이 인정된다.","전세권의 존속기간을 약정하지 아니한 경우, 각 당사자는 언제든지 상대방에게 전세권의 소멸을 통고할 수 있다.","건물의 전세권이 법정갱신된 경우 그 존속기간은 갱신 전 전세권과 같은 기간으로 본다."],"a":[4],"L":"민2-6","o":"변형","x":{"한줄":"존속기간을 약정하지 않은 전세권은 어느 당사자든 소멸을 통고할 수 있고, 상대방이 통고를 받은 날부터 6개월이 지나면 소멸한다.","근거":[{"법령":"민법","조문":"제313조","원문":"제313조(전세권의 소멸통고) 전세권의 존속기간을 약정하지 아니한 때에는 각 당사자는 언제든지 상대방에 대하여 전세권의 소멸을 통고할 수 있고 상대방이 이 통고를 받은 날로부터 6월이 경과하면 전세권은 소멸한다."},{"법령":"민법","조문":"제312조제2항·제4항","원문":"②건물에 대한 전세권의 존속기간을 1년 미만으로 정한 때에는 이를 1년으로 한다. … ④ … 그 기간이 만료된 때에 전전세권과 동일한 조건으로 다시 전세권을 설정한 것으로 본다. 이 경우 전세권의 존속기간은 그 정함이 없는 것으로 본다."},{"법령":"민법","조문":"제318조","원문":"제318조(전세권자의 경매청구권) 전세권설정자가 전세금의 반환을 지체한 때에는 전세권자는 민사집행법의 정한 바에 의하여 전세권의 목적물의 경매를 청구할 수 있다."},{"판례":"대법원 판례(전세금의 수수)","요지":"전세금의 지급은 전세권 성립의 요소이지만 현실로 수수될 필요는 없고 기존 채권으로 갈음할 수 있다. 건물 일부에 설정한 전세권의 경매청구와 우선변제는 전세권의 목적물인 그 부분에 한한다."}],"선지":[{"번호":1,"판정":"틀림","설명":"기존 채권으로 전세금 지급을 갈음할 수 있다. 현실 수수가 필수가 아니다(판례)."},{"번호":2,"판정":"틀림","설명":"경매청구는 전세권의 목적물에 대해 한다(제318조). 건물 일부 전세권자는 나머지 부분까지 경매청구할 수 없다."},{"번호":3,"판정":"틀림","설명":"건물 전세권을 1년 미만으로 정하면 1년으로 본다(제312조 제2항)."},{"번호":4,"판정":"옳음","설명":"제313조. 소멸통고를 받은 날부터 6개월이 지나면 전세권이 소멸한다."},{"번호":5,"판정":"틀림","설명":"법정갱신된 전세권의 존속기간은 정함이 없는 것으로 본다(제312조 제4항). 종전 기간이 이어지지 않는다."}],"개념":[{"종류":"표","제목":"전세권 존속기간","머리":["구분","내용","근거"],"행":[["최장기간","10년. 약정이 이를 넘으면 10년으로 단축","제312조 제1항"],["건물 최단기간","1년 미만으로 정하면 1년","제312조 제2항"],["갱신","갱신한 날부터 10년을 넘지 못함","제312조 제3항"],["법정갱신","만료 6월~1월 전 사이에 갱신거절·조건변경 통지가 없으면 종전과 같은 조건, 기간은 정함 없음","제312조 제4항"],["기간 미약정","언제든 소멸통고, 통고를 받은 날부터 6월 경과 시 소멸","제313조"]]},{"종류":"흐름","제목":"전세권 소멸 후 전세금 회수","단계":[{"이름":"전세권 소멸","설명":"기간 만료, 소멸통고, 소멸청구 등"},{"이름":"동시이행","설명":"전세금 반환 = 목적물 인도 + 말소등기 서류 교부(제317조)"},{"이름":"반환 지체","설명":"전세권자가 목적물 경매 청구(제318조)"},{"이름":"우선변제","설명":"후순위권리자·일반채권자보다 먼저 전세금 변제(제303조 제1항)"}]}],"함정":"2번을 맞게 읽는 경우가 많다. 제303조 제1항의 부동산 전부에 대한 우선변제를 경매청구 범위로 넓혀 읽기 때문이다. 우선변제와 경매청구 모두 전세권의 목적물을 기준으로 한다. 5번은 법정갱신을 종전 기간 연장으로 오해한 선지다. 갱신 뒤에는 기간이 정해지지 않아 제313조의 소멸통고로 끝낼 수 있다."}},{"i":"S2-1-1-민법-22","r":"S2","g":1,"c":1,"n":62,"s":"민법","q":"甲은 乙 소유의 X건물에 보일러 교체공사를 완료하였으나 乙이 공사대금을 지급하지 않자 X건물을 점유하고 있다. 甲의 유치권에 관한 설명으로 옳은 것은? (다툼이 있으면 판례에 따름)","b":null,"bs":"없음","img":[],"ch":["공사대금채권의 변제기가 도래하기 전이라도 甲은 X건물을 유치할 수 있다.","甲이 乙의 승낙 없이 X건물을 丙에게 임대한 경우, 乙은 유치권의 소멸을 청구할 수 있다.","甲은 X건물에서 생기는 과실을 수취하더라도 이를 공사대금채권의 변제에 충당할 수 없다.","甲이 X건물을 점유하고 있는 동안에는 공사대금채권의 소멸시효가 진행하지 않는다.","甲은 X건물의 경매대금에서 乙의 다른 채권자보다 먼저 변제를 받을 수 있다."],"a":[2],"L":"민2-7","o":"변형","x":{"한줄":"유치권자가 채무자의 승낙 없이 유치물을 대여하면 채무자는 유치권의 소멸을 청구할 수 있다.","근거":[{"법령":"민법","조문":"제324조제2항·제3항","원문":"②유치권자는 채무자의 승낙없이 유치물의 사용, 대여 또는 담보제공을 하지 못한다. 그러나 유치물의 보존에 필요한 사용은 그러하지 아니하다. ③유치권자가 전2항의 규정에 위반한 때에는 채무자는 유치권의 소멸을 청구할 수 있다."},{"법령":"민법","조문":"제320조제1항","원문":"①타인의 물건 또는 유가증권을 점유한 자는 그 물건이나 유가증권에 관하여 생긴 채권이 변제기에 있는 경우에는 변제를 받을 때까지 그 물건 또는 유가증권을 유치할 권리가 있다."},{"법령":"민법","조문":"제323조제1항","원문":"①유치권자는 유치물의 과실을 수취하여 다른 채권보다 먼저 그 채권의 변제에 충당할 수 있다. 그러나 과실이 금전이 아닌 때에는 경매하여야 한다."},{"법령":"민법","조문":"제326조","원문":"제326조(피담보채권의 소멸시효) 유치권의 행사는 채권의 소멸시효의 진행에 영향을 미치지 아니한다."},{"법령":"민법","조문":"제322조제1항","원문":"①유치권자는 채권의 변제를 받기 위하여 유치물을 경매할 수 있다."}],"선지":[{"번호":1,"판정":"틀림","설명":"채권이 변제기에 있어야 유치권이 성립한다(제320조 제1항)."},{"번호":2,"판정":"옳음","설명":"승낙 없는 대여는 제324조 제2항 위반이고, 그 경우 채무자가 소멸을 청구할 수 있다(제3항)."},{"번호":3,"판정":"틀림","설명":"유치권자는 과실을 수취해 다른 채권보다 먼저 채권 변제에 충당할 수 있다(제323조 제1항). 금전이 아닌 과실은 경매한다."},{"번호":4,"판정":"틀림","설명":"유치권 행사는 소멸시효의 진행에 영향이 없다(제326조). 점유 중에도 시효는 흐른다."},{"번호":5,"판정":"틀림","설명":"유치권자에게는 경매권만 있고 우선변제권은 없다(제322조 제1항). 경매대금에서 우선변제를 받지 못한다."}],"개념":[{"종류":"표","제목":"유치권 성립요건과 효력","머리":["구분","내용","근거"],"행":[["목적물","타인의 물건 또는 유가증권. 채무자 소유일 필요 없음","제320조 제1항"],["견련성","그 물건에 관하여 생긴 채권(공사대금, 비용상환 등)","제320조 제1항"],["변제기","피담보채권이 변제기에 있을 것","제320조 제1항"],["점유","점유가 불법행위로 시작되지 않았을 것. 점유를 잃으면 소멸","제320조 제2항, 제328조"],["불가분성","채권 전부를 변제받을 때까지 유치물 전부에 행사","제321조"],["경매·충당","경매권, 정당한 이유 있으면 간이변제충당. 우선변제권은 없음","제322조"]]},{"종류":"표","제목":"유치권자의 권리와 의무","머리":["구분","내용","근거"],"행":[["과실수취","과실을 수취해 먼저 이자, 다음 원본에 충당","제323조"],["선관의무","선량한 관리자의 주의로 점유","제324조 제1항"],["사용·대여·담보제공","채무자 승낙 필요. 위반 시 채무자가 소멸 청구. 보존에 필요한 사용은 허용","제324조 제2항·제3항"],["비용상환","필요비는 상환 청구, 유익비는 가액 증가가 현존할 때 선택에 따라 상환","제325조"],["시효","행사해도 피담보채권 소멸시효 진행에 영향 없음","제326조"]]}],"함정":"5번을 맞다고 보기 쉽다. 담보물권이라는 이름 때문에 우선변제를 떠올리지만 유치권은 인도를 거절하는 권리이고 경매권만 있다. 4번도 같은 맥락이다. 점유를 계속하는 것과 시효가 정지되는 것은 별개다."}},{"i":"S2-1-1-민법-23","r":"S2","g":1,"c":1,"n":63,"s":"민법","q":"유치권에 관한 설명으로 옳은 것은? (다툼이 있으면 판례에 따름)","b":null,"bs":"없음","img":[],"ch":["건물의 임차인은 임대차 종료 후 건물을 점유하고 있더라도 임차보증금반환채권을 이유로 그 건물에 대하여 유치권을 주장할 수 없다.","점유를 침탈당한 유치권자가 점유회수의 소 등으로 점유를 회복하지 않고 있어도 유치권은 소멸하지 않는다.","유치권자는 채무자의 승낙 없이도 유치물을 타인에게 담보로 제공할 수 있다.","유치권은 채무자 소유의 물건에 대해서만 성립한다.","유치권자가 채권의 일부를 변제받으면 변제받은 비율에 따라 유치물의 일부를 반환하여야 한다."],"a":[1],"L":"민2-7","o":"변형","x":{"한줄":"보증금반환채권은 건물 자체에 관하여 생긴 채권이 아니어서 이를 근거로 한 유치권은 성립하지 않는다.","근거":[{"법령":"민법","조문":"제320조제1항","원문":"①타인의 물건 또는 유가증권을 점유한 자는 그 물건이나 유가증권에 관하여 생긴 채권이 변제기에 있는 경우에는 변제를 받을 때까지 그 물건 또는 유가증권을 유치할 권리가 있다."},{"법령":"민법","조문":"제328조","원문":"제328조(점유상실과 유치권소멸) 유치권은 점유의 상실로 인하여 소멸한다."},{"법령":"민법","조문":"제324조제2항","원문":"②유치권자는 채무자의 승낙없이 유치물의 사용, 대여 또는 담보제공을 하지 못한다."},{"법령":"민법","조문":"제321조","원문":"제321조(유치권의 불가분성) 유치권자는 채권전부의 변제를 받을 때까지 유치물전부에 대하여 그 권리를 행사할 수 있다."},{"판례":"대법원 판례(보증금·권리금반환채권)","요지":"임차인의 보증금반환채권이나 권리금반환채권은 임차 건물에 관하여 생긴 채권이 아니므로 이를 피담보채권으로 한 유치권은 인정되지 않는다. 유치권자가 점유를 침탈당해도 점유물반환청구권을 행사해 점유를 회복하면 유치권은 되살아난다."}],"선지":[{"번호":1,"판정":"옳음","설명":"보증금반환채권은 건물에 관하여 생긴 채권이 아니어서 견련성이 없다(판례)."},{"번호":2,"판정":"틀림","설명":"점유를 잃으면 유치권은 소멸한다(제328조). 점유물반환청구권을 행사해 점유를 회복해야 유치권이 유지된다(판례)."},{"번호":3,"판정":"틀림","설명":"담보제공은 채무자의 승낙이 있어야 한다. 위반하면 채무자가 소멸을 청구한다(제324조 제2항·제3항)."},{"번호":4,"판정":"틀림","설명":"유치권의 목적은 타인의 물건이다(제320조 제1항). 채무자 소유로 한정되지 않는다."},{"번호":5,"판정":"틀림","설명":"불가분성에 따라 채권 전부를 변제받을 때까지 유치물 전부에 행사한다(제321조)."}],"개념":[{"종류":"표","제목":"유치권이 인정되는지 여부(판례)","머리":["피담보채권","유치권","이유"],"행":[["건물 수리비·공사대금","성립","건물에 관하여 생긴 채권"],["임차인의 필요비 상환청구권","성립","목적물에 관하여 생긴 채권"],["임차보증금반환채권","불성립","목적물 자체에서 생긴 채권이 아님"],["권리금반환채권","불성립","목적물 자체에서 생긴 채권이 아님"]]},{"종류":"비교","제목":"유치권의 소멸","왼쪽":{"이름":"소멸하는 경우","항목":["점유의 상실(제328조)","채무자의 소멸청구(승낙 없는 사용·대여·담보제공, 제324조 제3항)","피담보채권의 소멸(부종성)"]},"오른쪽":{"이름":"소멸하지 않는 경우","항목":["점유 침탈 후 점유물반환청구로 점유 회복","피담보채권의 소멸시효 진행 자체(제326조)","채권 일부 변제(제321조)"]}}],"함정":"2번을 맞는 문장으로 읽는 경우가 많다. 점유물반환청구권으로 점유를 회복하면 되살아난다는 판례 문장과 비슷하게 보이기 때문이다. 회복하기 전에는 점유 상실로 소멸한 상태이고, 회복하는 행위가 있어야 한다."}},{"i":"S2-1-1-민법-24","r":"S2","g":1,"c":1,"n":64,"s":"민법","q":"근저당권의 피담보채권의 확정에 관한 설명으로 옳은 것은? (다툼이 있으면 판례에 따름)","b":null,"bs":"없음","img":[],"ch":["후순위 근저당권자의 신청으로 경매개시결정이 있으면, 선순위 근저당권의 피담보채권은 그때 확정된다.","확정 전 근저당권부 채권의 일부를 양도하면, 근저당권도 그 비율만큼 양수인에게 이전된다.","후순위 근저당권자의 신청으로 개시된 경매에서 선순위 근저당권의 피담보채권 중 매수인이 매각대금을 완납할 때까지 발생한 것은 채권최고액 범위에서 담보된다.","피담보채권이 확정된 후 새로 발생한 원본채권도 채권최고액 범위에서 그 근저당권으로 담보된다.","근저당권의 채권최고액에는 이자가 포함되지 않으므로 이자는 채권최고액을 넘어서도 담보된다."],"a":[3],"L":"민2-8","o":"변형","x":{"한줄":"후순위자가 신청한 경매에서 선순위 근저당권의 피담보채권은 매수인의 대금 완납 시에 확정되므로, 그때까지 발생한 채권이 최고액 범위에서 담보된다.","근거":[{"법령":"민법","조문":"제357조","원문":"①저당권은 그 담보할 채무의 최고액만을 정하고 채무의 확정을 장래에 보류하여 이를 설정할 수 있다. 이 경우에는 그 확정될 때까지의 채무의 소멸 또는 이전은 저당권에 영향을 미치지 아니한다. ②전항의 경우에는 채무의 이자는 최고액 중에 산입한 것으로 본다."},{"법령":"민법","조문":"제360조","원문":"저당권은 원본, 이자, 위약금, 채무불이행으로 인한 손해배상 및 저당권의 실행비용을 담보한다. 그러나 지연배상에 대하여는 원본의 이행기일을 경과한 후의 1년분에 한하여 저당권을 행사할 수 있다."},{"판례":"대법원 판례(근저당 확정시기)","요지":"후순위 근저당권자가 경매를 신청한 경우 선순위 근저당권의 피담보채권은 매수인이 대금을 완납한 때 확정된다. 확정 이후 새로 발생한 원본채권은 담보되지 않고, 확정 전에 채권이 양도되어도 근저당권은 이전되지 않는다."}],"선지":[{"번호":1,"판정":"틀림","설명":"경매개시결정 시가 아니라 매수인의 대금 완납 시에 확정된다(판례)."},{"번호":2,"판정":"틀림","설명":"확정 전에는 근저당권이 채권에 수반하지 않는다. 채권이 양도되어도 근저당권은 양수인에게 이전되지 않는다(제357조 제1항, 판례)."},{"번호":3,"판정":"옳음","설명":"대금 완납 시에 확정되므로 그때까지 발생한 채권이 최고액 범위에서 담보된다(판례)."},{"번호":4,"판정":"틀림","설명":"확정 이후에 발생한 원본채권은 담보하지 않는다. 확정은 담보할 원본을 고정하는 효과다(판례)."},{"번호":5,"판정":"틀림","설명":"채무의 이자는 최고액 중에 산입한 것으로 본다(제357조 제2항). 이자도 최고액 안에서만 담보된다."}],"개념":[{"종류":"표","제목":"근저당권 피담보채권의 확정","머리":["확정 사유","확정 시기","비고"],"행":[["존속기간·결산기 정함","그 기간·결산기 도래 시","계약상 확정"],["기본계약 해지·종료","해지·종료 시","거래 종료"],["근저당권자 자신이 경매 신청","경매신청 시","자기 신청"],["후순위 권리자가 경매 신청","매수인의 대금 완납 시","그때까지 발생 채권 담보"],["확정 이후","원본 증감 없음","확정 후 새 원본채권은 불담보"]]},{"종류":"표","제목":"저당권의 효력 범위","머리":["구분","내용","근거"],"행":[["목적물의 범위","부합물과 종물에 미침. 설정행위로 배제 가능","제358조"],["과실","압류 이후 설정자가 수취한 과실에 미침","제359조"],["피담보채권","원본·이자·위약금·손해배상·실행비용. 지연배상은 이행기 후 1년분","제360조"],["처분제한","피담보채권과 분리하여 양도·담보제공 불가","제361조"],["일괄경매","설정 후 설정자가 건물을 지으면 토지와 건물을 함께 경매 청구, 우선변제는 토지 대가에 한함","제365조"],["공동저당","동시배당은 경매대가에 비례, 이시배당은 차순위자가 대위","제368조"]]}],"함정":"1번을 맞다고 보기 쉽다. 경매개시결정 시에 확정된다는 설명은 근저당권자가 직접 신청한 경우의 경매신청 시점과 섞인 것이다. 후순위자가 신청한 경매에서는 대금 완납 시다. 5번은 제357조 제2항과 반대로 이자를 최고액 밖으로 보는 선지다."}},{"i":"S2-1-1-민법-25","r":"S2","g":1,"c":1,"n":65,"s":"민법","q":"1필의 토지의 일부를 객체로 할 수 없는 권리는? (다툼이 있으면 판례에 따름)","b":null,"bs":"없음","img":[],"ch":["저당권","전세권","지상권","임차권","점유권"],"a":[1],"L":"민2-8","o":"기출","x":{"한줄":"저당권은 1필 토지의 일부에 설정할 수 없다. 나머지 권리는 토지의 일부를 목적으로 할 수 있다.","근거":[{"법령":"부동산등기법","조문":"제69조제6호","원문":"6. 지상권설정의 범위가 토지의 일부인 경우에는 그 부분을 표시한 도면의 번호"},{"법령":"부동산등기법","조문":"제72조제1항제6호","원문":"6. 전세권설정이나 전전세의 범위가 부동산의 일부인 경우에는 그 부분을 표시한 도면의 번호"},{"법령":"부동산등기법","조문":"제74조제7호","원문":"7. 임차권설정 또는 임차물전대의 범위가 부동산의 일부인 때에는 그 부분을 표시한 도면의 번호"},{"이론":"일물일권주의","내용":"물권의 객체는 독립한 하나의 물건이다. 1필 토지의 일부는 독립성이 없어 소유권과 저당권의 객체가 되지 못한다. 용익권은 일부를 사용·수익하는 권리라 일부에 설정할 수 있고, 점유권은 사실상 지배가 미치는 부분에 인정된다."}],"선지":[{"번호":1,"판정":"옳음","설명":"저당권은 1필 토지의 일부를 객체로 할 수 없다. 일부에 설정하려면 분필 후 설정한다."},{"번호":2,"판정":"틀림","설명":"전세권은 부동산 일부에 설정할 수 있고 그 부분을 표시한 도면의 번호를 등기한다(부동산등기법 제72조 제1항 제6호)."},{"번호":3,"판정":"틀림","설명":"지상권은 토지의 일부에 설정할 수 있다(부동산등기법 제69조 제6호)."},{"번호":4,"판정":"틀림","설명":"임차권은 부동산 일부에 설정할 수 있다(부동산등기법 제74조 제7호)."},{"번호":5,"판정":"틀림","설명":"점유권은 사실상 지배가 미치는 부분에 성립하므로 토지의 일부에 대해서도 인정된다."}],"개념":[{"종류":"표","제목":"1필 토지의 일부에 성립 가능한 권리","머리":["권리","일부 성립","근거"],"행":[["소유권","불가(분필 후 가능)","일물일권주의"],["저당권","불가","일물일권주의, 등기사항에 일부 도면 없음(부동산등기법 제75조)"],["지상권","가능","부동산등기법 제69조 제6호"],["지역권(승역지)","가능","부동산등기법 제70조 제5호"],["전세권","가능","부동산등기법 제72조 제1항 제6호"],["임차권","가능","부동산등기법 제74조 제7호"],["점유권","가능","사실상 지배의 범위"]]}],"함정":"임차권을 채권이라 일부에 못 한다고 보거나, 전세권을 담보물권 성격 때문에 저당권과 같이 취급하는 경우가 많다. 전세권은 용익물권으로서 일부 설정이 가능하고 등기도 도면으로 한다."}},{"i":"S2-1-1-민법-26","r":"S2","g":1,"c":1,"n":66,"s":"민법","q":"계약의 유형에 관한 설명으로 옳은 것은?","b":null,"bs":"없음","img":[],"ch":["매매계약은 요물계약이다.","교환계약은 무상계약이다.","증여계약은 낙성계약이다.","도급계약은 요물계약이다.","임대차계약은 편무계약이다."],"a":[3],"L":"민3-1","o":"기출","x":{"한줄":"증여는 당사자 일방이 무상으로 재산을 수여한다는 의사표시에 상대방이 승낙하면 성립하는 낙성계약이다.","근거":[{"법령":"민법","조문":"제554조","원문":"제554조(증여의 의의) 증여는 당사자 일방이 무상으로 재산을 상대방에 수여하는 의사를 표시하고 상대방이 이를 승낙함으로써 그 효력이 생긴다."},{"법령":"민법","조문":"제563조","원문":"제563조(매매의 의의) 매매는 당사자 일방이 재산권을 상대방에게 이전할 것을 약정하고 상대방이 그 대금을 지급할 것을 약정함으로써 그 효력이 생긴다."},{"법령":"민법","조문":"제664조","원문":"제664조(도급의 의의) 도급은 당사자 일방이 어느 일을 완성할 것을 약정하고 상대방이 그 일의 결과에 대하여 보수를 지급할 것을 약정함으로써 그 효력이 생긴다."},{"법령":"민법","조문":"제618조","원문":"제618조(임대차의 의의) 임대차는 당사자 일방이 상대방에게 목적물을 사용, 수익하게 할 것을 약정하고 상대방이 이에 대하여 차임을 지급할 것을 약정함으로써 그 효력이 생긴다."}],"선지":[{"번호":1,"판정":"틀림","설명":"매매는 합의만으로 성립하는 낙성계약이다(제563조)."},{"번호":2,"판정":"틀림","설명":"교환은 서로 재산권을 이전하는 유상·쌍무계약이다(제596조, 제567조)."},{"번호":3,"판정":"옳음","설명":"증여는 의사표시의 합치로 성립하는 낙성·무상·편무계약이다(제554조)."},{"번호":4,"판정":"틀림","설명":"도급은 일의 완성과 보수 지급의 합의만으로 성립하는 낙성계약이다(제664조)."},{"번호":5,"판정":"틀림","설명":"임대차는 사용·수익 제공과 차임 지급이 서로 대가관계에 있는 쌍무계약이다(제618조)."}],"개념":[{"종류":"표","제목":"계약의 분류","머리":["계약","쌍무/편무","유상/무상","낙성/요물"],"행":[["매매","쌍무","유상","낙성"],["교환","쌍무","유상","낙성"],["임대차","쌍무","유상","낙성"],["도급","쌍무","유상","낙성"],["증여","편무","무상","낙성"],["사용대차","편무","무상","낙성"]]},{"종류":"표","제목":"분류의 실익","머리":["분류","적용되는 규정"],"행":[["쌍무계약","동시이행항변권(제536조), 위험부담(제537조·제538조)"],["유상계약","매매 규정 준용(제567조), 매도인 담보책임"],["무상계약","증여자의 담보책임 경감(제559조)"],["낙성계약","합의로 성립"],["요물계약","계약금계약처럼 금전 교부가 성립요건(판례)"]]}],"함정":"증여를 서면이 없으면 성립하지 않는 계약으로 오해하기 쉽다. 서면이 없는 증여는 각 당사자가 해제할 수 있을 뿐 성립은 합의만으로 한다(제555조). 요물계약의 대표 사례는 판례가 인정하는 계약금계약이다."}},{"i":"S2-1-1-민법-27","r":"S2","g":1,"c":1,"n":67,"s":"민법","q":"매도인 甲과 매수인 乙사이에 매매대금을 丙에게 지급하기로 하는 제3자를 위한 계약을 체결하였고, 丙이 乙에게 수익의 의사표시를 하였다. 다음 설명 중 옳은 것은?(다툼이 있으면 판례에 따름)","b":null,"bs":"없음","img":[],"ch":["乙의 대금채무 불이행이 있는 경우, 甲은 丙의 동의 없이 乙과의 계약을 해제할 수 없다.","乙의 기망행위로 甲과 乙의 계약이 체결된 경우, 丙은 사기를 이유로 그 계약을 취소할 수 있다.","甲과 丙의 법률관계가 무효인 경우, 특별한 사정이 없는 한 乙은 丙에게 대금지급을 거절할 수 있다.","乙이 매매대금을 丙에게 지급한 후에 甲과 乙의 계약이 취소된 경우, 乙은 丙에게 부당이득반환을 청구할 수 있다.","甲과 乙이 계약을 체결할 때 丙의 권리를 변경시킬 수 있음을 유보한 경우, 甲과 乙은 丙의 권리를 변경시킬 수 있다."],"a":[5],"L":"민3-1","o":"기출","x":{"한줄":"제3자의 권리가 생긴 뒤에는 당사자가 이를 변경·소멸시키지 못하지만, 계약에서 변경 권한을 유보했다면 변경할 수 있다.","근거":[{"법령":"민법","조문":"제539조","원문":"①계약에 의하여 당사자 일방이 제삼자에게 이행할 것을 약정한 때에는 그 제삼자는 채무자에게 직접 그 이행을 청구할 수 있다. ②전항의 경우에 제삼자의 권리는 그 제삼자가 채무자에 대하여 계약의 이익을 받을 의사를 표시한 때에 생긴다."},{"법령":"민법","조문":"제541조","원문":"제541조(제삼자의 권리의 확정) 제539조의 규정에 의하여 제삼자의 권리가 생긴 후에는 당사자는 이를 변경 또는 소멸시키지 못한다."},{"판례":"대법원 판례(제3자를 위한 계약)","요지":"요약자는 수익자의 동의 없이 낙약자의 채무불이행을 이유로 계약을 해제할 수 있다. 수익자는 계약당사자가 아니어서 취소권·해제권을 갖지 않는다. 요약자와 수익자 사이의 대가관계가 무효이더라도 낙약자는 이를 이유로 급부를 거절하지 못하고, 낙약자가 수익자에게 급부한 뒤 기본계약이 취소되면 낙약자는 요약자에게 부당이득반환을 청구한다."}],"선지":[{"번호":1,"판정":"틀림","설명":"해제권은 계약당사자인 요약자에게 있고 수익자의 동의가 필요 없다(판례)."},{"번호":2,"판정":"틀림","설명":"수익자는 계약당사자가 아니므로 계약을 취소하지 못한다. 취소권은 당사자인 甲에게 있다."},{"번호":3,"판정":"틀림","설명":"요약자와 수익자 사이의 대가관계 흠결은 낙약자가 주장할 항변사유가 아니다. 乙은 대금지급을 거절하지 못한다(판례)."},{"번호":4,"판정":"틀림","설명":"급부한 낙약자는 계약 상대방인 요약자(甲)에게 부당이득반환을 청구한다. 수익자에게는 청구하지 못한다(판례)."},{"번호":5,"판정":"옳음","설명":"변경·소멸의 권한을 유보했다면 제541조의 제한이 적용되지 않고 당사자가 丙의 권리를 변경할 수 있다."}],"개념":[{"종류":"흐름","제목":"제3자를 위한 계약의 권리 발생","단계":[{"이름":"계약 체결","설명":"요약자와 낙약자가 제3자에게 이행하기로 약정(제539조 제1항)"},{"이름":"수익의 의사표시","설명":"수익자가 낙약자에게 계약의 이익을 받겠다고 표시, 이때 권리 발생(제539조 제2항)"},{"이름":"권리 확정","설명":"권리 발생 후 당사자는 변경·소멸 불가(제541조)"},{"이름":"최고","설명":"낙약자는 상당한 기간을 정해 확답을 최고, 확답 없으면 거절로 간주(제540조)"}]},{"종류":"표","제목":"제3자를 위한 계약의 3면 관계","머리":["관계","당사자","내용"],"행":[["기본관계(원인관계)","요약자-낙약자","계약의 효력, 하자가 있으면 낙약자가 수익자에게 대항 가능"],["대가관계(보상관계)","요약자-수익자","흠결이 있어도 낙약자의 급부의무에 영향 없음"],["급부관계","낙약자-수익자","수익자가 낙약자에게 직접 이행 청구"],["해제·취소","요약자","수익자는 당사자가 아니라 해제권·취소권이 없음"]]}],"함정":"3번을 맞다고 보기 쉽다. 요약자와 수익자 사이의 관계가 무효이면 급부를 받을 이유가 없다는 직관 때문이다. 대가관계는 요약자와 수익자 사이의 사정이라 낙약자의 항변사유가 아니다. 4번은 부당이득 반환의 상대방을 수익자로 잘못 잡은 선지다."}},{"i":"S2-1-1-민법-28","r":"S2","g":1,"c":1,"n":68,"s":"민법","q":"甲은 자신의 토지를 乙에게 매도하고 중도금까지 수령하였으나 그 토지가 재결수용되어 乙에게 소유권을 이전할 수 없게 되었다. 이에 관한 설명으로 옳은 것을 모두 고른 것은? (다툼이 있으면 판례에 따름)","b":"ㄱ. 甲과 乙은 특약으로 乙이 대가위험을 부담하는 것으로 정할 수 있다.\nㄴ. 乙은 이행불능을 이유로 매매계약을 해제할 수 있다.\nㄷ. 甲이 수용보상금청구권을 취득한 경우, 乙이 매매대금 전부를 지급하면 그 수용보상금청구권 자체가 乙에게 귀속한다.","bs":"글자","img":[],"ch":["ㄱ","ㄷ","ㄱ, ㄴ","ㄴ, ㄷ","ㄱ, ㄴ, ㄷ"],"a":[1],"L":"민3-1","o":"기출","x":{"한줄":"위험부담 규정은 임의규정이라 특약으로 달리 정할 수 있고, 쌍방 무책 불능에는 해제권이 없으며 수용보상금청구권은 이전청구의 대상일 뿐이다.","근거":[{"법령":"민법","조문":"제537조","원문":"제537조(채무자위험부담주의) 쌍무계약의 당사자 일방의 채무가 당사자쌍방의 책임없는 사유로 이행할 수 없게 된 때에는 채무자는 상대방의 이행을 청구하지 못한다."},{"법령":"민법","조문":"제546조","원문":"제546조(이행불능과 해제) 채무자의 책임있는 사유로 이행이 불능하게 된 때에는 채권자는 계약을 해제할 수 있다."},{"판례":"대법원 판례(대상청구)","요지":"이행불능을 가져온 사정으로 채무자가 대상을 취득한 경우 채권자는 그 대상의 이전을 청구할 수 있다. 쌍방 무책의 불능에서 채권자는 반대급부를 이행하고 채무자에게 보상금청구권의 양도 또는 보상금의 인도를 청구하는 것이지, 청구권이 당연히 채권자에게 귀속하지는 않는다."}],"선지":[{"번호":1,"판정":"-","설명":"옳은 것은 ㄱ뿐이다. 조합이 맞다."},{"번호":2,"판정":"-","설명":"ㄷ은 틀린 보기다. ㄱ이 빠져 있다."},{"번호":3,"판정":"-","설명":"ㄴ이 틀린 보기다."},{"번호":4,"판정":"-","설명":"ㄴ, ㄷ이 모두 틀린 보기다."},{"번호":5,"판정":"-","설명":"ㄴ, ㄷ이 포함되어 있어 틀린 조합이다."}],"보기판정":[{"기호":"ㄱ","판정":"옳음","설명":"제537조는 임의규정이다. 대가위험을 매수인이 지는 특약은 유효하다."},{"기호":"ㄴ","판정":"틀림","설명":"재결수용은 쌍방 무책 사유다. 제546조의 해제는 채무자의 책임 있는 불능을 요건으로 하므로 해제할 수 없다. 乙은 대금지급의무를 면한다(제537조)."},{"기호":"ㄷ","판정":"틀림","설명":"乙은 대금을 지급하고 대상(보상금청구권 또는 보상금)의 이전을 청구할 수 있을 뿐, 청구권 자체가 당연히 귀속하지는 않는다(판례)."}],"개념":[{"종류":"표","제목":"후발적 불능과 위험부담","머리":["귀책","계약 해제","반대급부 청구","근거"],"행":[["채무자 귀책","가능","채무불이행 책임(손해배상)","제546조"],["쌍방 무책","불가","채무자는 대금 청구 불가","제537조"],["채권자 귀책","채권자는 불가","채무자는 대금 청구 가능, 자기 채무 면한 이익 상환","제538조 제1항·제2항"]]},{"종류":"흐름","제목":"쌍방 무책 불능 시 처리","단계":[{"이름":"불능 발생","설명":"재결수용 등 쌍방 책임 없는 사유로 소유권 이전 불가"},{"이름":"대금 청구 불가","설명":"매도인은 대금청구를 못 하고 받은 중도금은 반환(제537조, 부당이득)"},{"이름":"대상청구","설명":"매수인이 반대급부를 이행하고 보상금청구권 이전 또는 보상금 인도를 청구"},{"이름":"특약","설명":"위험부담은 임의규정이라 매수인 부담으로 정하면 그대로 효력"}]}],"함정":"ㄷ을 맞다고 읽기 쉽다. 대금을 모두 냈으니 보상금청구권이 자기 것이 된다는 직관 때문이다. 판례는 이전을 청구할 수 있다는 것이고 청구권이 저절로 귀속하지는 않는다. ㄴ은 불능이 채무자 책임일 때만 제546조로 해제한다."}},{"i":"S2-1-1-민법-29","r":"S2","g":1,"c":1,"n":69,"s":"민법","q":"동시이행의 관계에 있지 않는 것은? (다툼이 있으면 판례에 따름)","b":null,"bs":"없음","img":[],"ch":["계약이 해제된 경우 매도인의 대금반환의무와 매수인의 소유권이전등기 말소의무","임대차가 종료된 경우 임대인의 보증금반환의무와 임차인의 목적물 반환의무","토지임차인이 지상건물 매수청구권을 행사한 경우 임대인의 매매대금 지급의무와 임차인의 지상건물 인도 및 소유권이전등기의무","전세권이 소멸한 경우 전세권설정자의 전세금 반환의무와 전세권자의 목적물 인도 및 말소등기 서류 교부의무","저당권의 피담보채무 변제의무와 저당권설정등기 말소의무"],"a":[5],"L":"민3-1","o":"변형","x":{"한줄":"피담보채무의 변제는 저당권설정등기 말소보다 먼저 이행해야 하는 선이행 관계라 동시이행이 아니다.","근거":[{"법령":"민법","조문":"제549조","원문":"제549조(원상회복의무와 동시이행) 제536조의 규정은 전조의 경우에 준용한다."},{"법령":"민법","조문":"제317조","원문":"제317조(전세권의 소멸과 동시이행) 전세권이 소멸한 때에는 전세권설정자는 전세권자로부터 그 목적물의 인도 및 전세권설정등기의 말소등기에 필요한 서류의 교부를 받는 동시에 전세금을 반환하여야 한다."},{"법령":"민법","조문":"제643조","원문":"제643조(임차인의 갱신청구권, 매수청구권) 건물 기타 공작물의 소유 또는 식목, 채염, 목축을 목적으로 한 토지임대차의 기간이 만료한 경우에 건물, 수목 기타 지상시설이 현존한 때에는 제283조의 규정을 준용한다."},{"판례":"대법원 판례(동시이행의 범위)","요지":"임대차 종료 시 보증금반환과 목적물 반환은 동시이행 관계다. 지상물매수청구권 행사 뒤 매매대금 지급과 건물 인도·이전등기도 동시이행이다. 피담보채무 변제와 저당권 말소는 변제가 먼저이므로 동시이행 관계가 아니다."}],"선지":[{"번호":1,"판정":"옳음","설명":"해제의 원상회복의무는 서로 동시이행이다(제549조, 제536조). 이 문항에서 판정은 동시이행 관계에 있다는 진술의 참거짓이다."},{"번호":2,"판정":"옳음","설명":"보증금반환과 목적물 반환은 동시이행 관계다(판례)."},{"번호":3,"판정":"옳음","설명":"지상물매수청구권 행사로 성립한 매매의 대금 지급과 건물 인도·등기 이전은 동시이행 관계다(제643조, 판례)."},{"번호":4,"판정":"옳음","설명":"제317조가 동시이행을 명시한다."},{"번호":5,"판정":"틀림","설명":"변제가 선이행이다. 채무를 변제한 뒤에 말소를 청구하므로 동시이행 관계가 아니다(판례)."}],"개념":[{"종류":"표","제목":"동시이행 여부 정리","머리":["대상","동시이행","근거"],"행":[["매매 대금 지급 ↔ 이전등기·인도","동시이행","제568조 제2항"],["해제 시 쌍방 원상회복","동시이행","제549조"],["전세금 반환 ↔ 인도·말소서류 교부","동시이행","제317조"],["보증금 반환 ↔ 목적물 반환","동시이행","판례"],["청산금 지급 ↔ 본등기·인도","동시이행","가등기담보법 제4조 제3항"],["피담보채무 변제 → 저당권 말소","선이행(동시이행 아님)","판례"],["경매 무효 시 낙찰자의 말소의무 ↔ 근저당권자의 배당금 반환의무","동시이행 아님","판례"]]},{"종류":"비교","제목":"동시이행과 선이행","왼쪽":{"이름":"동시이행","항목":["쌍방 채무가 서로 대가 관계","항변권으로 상대방 이행 제공 시까지 거절(제536조 제1항)","이행 제공 후에는 거절 불가"]},"오른쪽":{"이름":"선이행","항목":["한쪽이 먼저 이행해야 하는 관계","먼저 이행할 자는 항변권이 없음","상대방의 이행이 곤란할 현저한 사유가 있으면 거절 가능(제536조 제2항)"]}}],"함정":"5번을 동시이행이라 보는 경우가 많다. 등기를 말소해 주는 것과 돈을 갚는 것이 서로 맞바꾸는 관계처럼 보여서다. 변제로 담보가 소멸한 다음에 말소를 구하는 순서이므로 선이행이다. 1~4번은 모두 법조문이나 판례로 동시이행이 인정된다."}},{"i":"S2-1-1-민법-30","r":"S2","g":1,"c":1,"n":70,"s":"민법","q":"甲은 승낙기간을 2026. 5. 8.로 하여 자신의 X건물을 乙에게 4억원에 팔겠다고 청약하였고, 그 청약은 2026. 5. 1. 乙에게 도달하였다. 이에 관한 설명으로 틀린 것은? (다툼이 있으면 판례에 따름)","b":null,"bs":"없음","img":[],"ch":["甲의 청약은 乙에게 도달한 때에 그 효력이 생긴다.","甲이 청약을 발송한 후 도달 전에 사망하더라도 그 청약의 효력에는 영향이 없다.","乙의 승낙이 2026. 5. 12. 甲에게 도달한 경우, 甲은 이를 새로운 청약으로 보아 승낙함으로써 계약을 성립시킬 수 있다.","甲이 \"2026. 5. 8.까지 이의가 없으면 승낙한 것으로 본다\"고 표시한 경우, 乙이 그 기간까지 이의하지 않으면 계약이 성립한다.","乙이 4억원이 아닌 4천만원에 매수하겠다는 승낙을 2026. 5. 8. 甲에게 도달시킨 경우, 이는 甲의 청약을 거절하고 새로 청약한 것으로 본다."],"a":[4],"L":"민3-1","o":"변형","x":{"한줄":"침묵을 승낙으로 본다는 청약자의 일방적 표시만으로는 계약이 성립하지 않는다.","근거":[{"법령":"민법","조문":"제111조","원문":"① 상대방이 있는 의사표시는 상대방에게 도달한 때에 그 효력이 생긴다. ② 의사표시자가 그 통지를 발송한 후 사망하거나 제한능력자가 되어도 의사표시의 효력에 영향을 미치지 아니한다."},{"법령":"민법","조문":"제530조","원문":"제530조(연착된 승낙의 효력) 전2조의 경우에 연착된 승낙은 청약자가 이를 새 청약으로 볼 수 있다."},{"법령":"민법","조문":"제534조","원문":"제534조(변경을 가한 승낙) 승낙자가 청약에 대하여 조건을 붙이거나 변경을 가하여 승낙한 때에는 그 청약의 거절과 동시에 새로 청약한 것으로 본다."},{"판례":"대법원 판례(침묵과 승낙)","요지":"청약자가 일방적으로 일정 기간 내에 회답이 없으면 승낙한 것으로 본다고 표시해도 상대방에게 회답할 의무가 생기지 않는다. 상대방이 침묵하면 계약은 성립하지 않는다."}],"선지":[{"번호":1,"판정":"옳음","설명":"상대방 있는 의사표시는 도달한 때 효력이 생긴다(제111조 제1항)."},{"번호":2,"판정":"옳음","설명":"발송 후 사망해도 의사표시의 효력에 영향이 없다(제111조 제2항)."},{"번호":3,"판정":"옳음","설명":"승낙기간 뒤에 도달한 승낙은 연착된 승낙이고 청약자는 이를 새 청약으로 볼 수 있다(제528조 제1항, 제530조)."},{"번호":4,"판정":"틀림","설명":"청약자가 일방적으로 침묵을 승낙으로 간주한다고 표시해도 계약은 성립하지 않는다(판례)."},{"번호":5,"판정":"옳음","설명":"청약 내용과 다른 조건으로 한 승낙은 청약의 거절이자 새 청약이다(제534조)."}],"개념":[{"종류":"흐름","제목":"계약의 성립 절차","단계":[{"이름":"청약","설명":"상대방 있는 의사표시, 도달 시 효력(제111조 제1항), 철회 불가(제527조)"},{"이름":"승낙기간 확인","설명":"승낙기간을 정한 청약은 그 기간 내에 승낙의 통지를 받지 못하면 효력 상실(제528조 제1항)"},{"이름":"승낙","설명":"청약과 일치하는 승낙. 격지자 사이는 승낙을 발송한 때 성립(제531조)"},{"이름":"계약 성립","설명":"합의가 일치한 때"}]},{"종류":"표","제목":"승낙에 관한 특수한 경우","머리":["유형","효과","근거"],"행":[["연착된 승낙","청약자가 새 청약으로 볼 수 있음","제530조"],["변경을 가한 승낙","청약의 거절 + 새 청약","제534조"],["의사실현","승낙으로 인정되는 사실이 있는 때 성립","제532조"],["승낙기간 없는 청약","상당한 기간 내 승낙이 없으면 효력 상실","제529조"],["침묵","승낙으로 보지 않음(판례)","-"]]}],"함정":"4번을 맞다고 보기 쉽다. 청약자가 조건을 달았으니 상대방이 따라야 한다고 생각하기 때문이다. 청약자가 상대방에게 회답 의무를 지울 수는 없다. 3번은 연착된 승낙이 곧바로 계약을 성립시키지는 않고 청약자가 새 청약으로 볼 수 있다는 점이 핵심이다."}},{"i":"S2-1-1-민법-31","r":"S2","g":1,"c":1,"n":71,"s":"민법","q":"수량을 지정한 매매의 목적물의 일부가 멸실된 경우 매도인의 담보책임에 관한 설명으로 틀린 것은? (단, 이에 관한 특약은 없으며, 다툼이 있으면 판례에 따름)","b":null,"bs":"없음","img":[],"ch":["수량을 지정한 매매란 특정물이 일정한 수량을 가지고 있다는 데 주안을 두고 대금도 그 수량을 기준으로 정한 경우를 말한다.","악의의 매수인은 대금감액과 손해배상을 청구할 수 있다.","선의의 매수인은 멸실된 부분의 비율로 대금감액을 청구할 수 있다.","잔존한 부분만이면 매수하지 아니하였을 때에는 선의의 매수인은 계약전부를 해제할 수 있다.","선의의 매수인은 일부멸실의 사실을 안 날부터 1년내에 매도인의 담보책임에 따른 매수인의 권리를 행사해야 한다."],"a":[2],"L":"민3-2","o":"기출","x":{"한줄":"일부멸실의 담보책임은 매수인이 그 멸실을 알지 못한 때에만 적용되므로 악의의 매수인은 감액도 손해배상도 청구하지 못한다.","근거":[{"법령":"민법","조문":"제574조","원문":"제574조(수량부족, 일부멸실의 경우와 매도인의 담보책임) 전2조의 규정은 수량을 지정한 매매의 목적물이 부족되는 경우와 매매목적물의 일부가 계약당시에 이미 멸실된 경우에 매수인이 그 부족 또는 멸실을 알지 못한 때에 준용한다."},{"법령":"민법","조문":"제572조","원문":"①매매의 목적이 된 권리의 일부가 타인에게 속함으로 인하여 매도인이 그 권리를 취득하여 매수인에게 이전할 수 없는 때에는 매수인은 그 부분의 비율로 대금의 감액을 청구할 수 있다. ②전항의 경우에 잔존한 부분만이면 매수인이 이를 매수하지 아니하였을 때에는 선의의 매수인은 계약전부를 해제할 수 있다. ③선의의 매수인은 감액청구 또는 계약해제외에 손해배상을 청구할 수 있다."},{"법령":"민법","조문":"제573조","원문":"제573조(전조의 권리행사의 기간) 전조의 권리는 매수인이 선의인 경우에는 사실을 안 날로부터, 악의인 경우에는 계약한 날로부터 1년내에 행사하여야 한다."}],"선지":[{"번호":1,"판정":"옳음","설명":"수량을 지정한 매매의 개념 설명이다(판례)."},{"번호":2,"판정":"틀림","설명":"제574조는 매수인이 멸실을 알지 못한 때에만 준용된다. 악의 매수인은 감액·손해배상 모두 청구하지 못한다."},{"번호":3,"판정":"옳음","설명":"선의 매수인은 멸실된 부분의 비율로 감액을 청구한다(제574조, 제572조 제1항)."},{"번호":4,"판정":"옳음","설명":"잔존 부분만으로는 매수하지 않았을 때 선의 매수인은 계약 전부를 해제할 수 있다(제574조, 제572조 제2항)."},{"번호":5,"판정":"옳음","설명":"선의 매수인은 사실을 안 날부터 1년 내에 행사한다(제574조, 제573조)."}],"개념":[{"종류":"표","제목":"매도인의 담보책임(권리의 하자·물건의 하자)","머리":["유형","매수인의 권리","행사기간","근거"],"행":[["권리 전부가 타인에게 속함","해제, 손해배상(악의는 손해배상 불가)","기간 제한 없음","제570조"],["권리 일부가 타인에게 속함","감액 청구, 선의는 해제·손해배상 추가","선의 안 날부터, 악의 계약일부터 1년","제572조, 제573조"],["수량부족·일부멸실","선의 매수인만 제572조 준용","안 날부터 1년","제574조"],["제한물권 있음","선의 매수인, 목적 달성 불가 시 해제, 그 밖에는 손해배상","안 날부터 1년","제575조"],["저당권·전세권 행사","해제, 출재 상환, 손해배상","기간 제한 없음","제576조"],["물건의 하자","선의·무과실 매수인, 해제(목적 달성 불가) 또는 손해배상","안 날부터 6월","제580조, 제582조"]]}],"함정":"악의의 매수인도 감액은 된다고 보기 쉽다. 제572조 제1항의 감액청구는 선악 구분이 없기 때문이다. 수량부족과 일부멸실은 제574조에서 매수인이 알지 못한 때에만 준용하므로 악의 매수인은 모든 권리가 없다. 기간도 선의면 안 날부터 1년이다."}},{"i":"S2-1-1-민법-32","r":"S2","g":1,"c":1,"n":72,"s":"민법","q":"교환계약에 관한 설명으로 옳은 것은? (다툼이 있으면 판례에 따름)","b":null,"bs":"없음","img":[],"ch":["교환계약은 당사자 쌍방이 금전 이외의 재산권을 상호 이전하기로 약정하는 것이므로, 금전의 보충지급을 약정하면 교환이 아니라 매매로 된다.","교환계약에는 매도인의 담보책임에 관한 규정이 준용되지 않는다.","교환계약에서 당사자 일방이 금전의 보충지급을 약정한 경우, 그 금전에 대하여는 매매대금에 관한 규정이 준용된다.","교환계약 체결 후 쌍방의 책임 없는 사유로 일방의 목적물이 멸실되어도 위험부담의 법리는 적용되지 않는다.","교환계약은 서면으로 하지 않으면 효력이 없다."],"a":[3],"L":"민3-2","o":"변형","x":{"한줄":"금전의 보충지급이 약정된 교환에서 그 금전에는 매매대금 규정이 준용된다.","근거":[{"법령":"민법","조문":"제596조","원문":"제596조(교환의 의의) 교환은 당사자 쌍방이 금전 이외의 재산권을 상호이전할 것을 약정함으로써 그 효력이 생긴다."},{"법령":"민법","조문":"제597조","원문":"제597조(금전의 보충지급의 경우) 당사자 일방이 전조의 재산권이전과 금전의 보충지급을 약정한 때에는 그 금전에 대하여는 매매대금에 관한 규정을 준용한다."},{"법령":"민법","조문":"제567조","원문":"제567조(유상계약에의 준용) 본절의 규정은 매매 이외의 유상계약에 준용한다. 그러나 그 계약의 성질이 이를 허용하지 아니하는 때에는 그러하지 아니하다."},{"법령":"민법","조문":"제537조","원문":"제537조(채무자위험부담주의) 쌍무계약의 당사자 일방의 채무가 당사자쌍방의 책임없는 사유로 이행할 수 없게 된 때에는 채무자는 상대방의 이행을 청구하지 못한다."}],"선지":[{"번호":1,"판정":"틀림","설명":"보충금이 있어도 교환계약이다. 그 금전에 매매대금 규정을 준용할 뿐이다(제597조)."},{"번호":2,"판정":"틀림","설명":"교환은 유상계약이어서 매매 규정이 준용되므로 담보책임이 적용된다(제567조)."},{"번호":3,"판정":"옳음","설명":"제597조. 보충금에는 매매대금 규정이 준용된다."},{"번호":4,"판정":"틀림","설명":"교환은 쌍무계약이라 위험부담(제537조)이 적용된다. 멸실된 목적물의 이전의무를 면한 쪽은 상대방의 이행을 청구하지 못한다."},{"번호":5,"판정":"틀림","설명":"교환은 불요식 낙성계약이다. 서면이 효력요건이 아니다."}],"개념":[{"종류":"비교","제목":"매매와 교환","왼쪽":{"이름":"매매(제563조)","항목":["재산권 이전 ↔ 금전 지급","매도인 담보책임 규정 적용","환매 가능(제590조)"]},"오른쪽":{"이름":"교환(제596조)","항목":["금전 이외 재산권 ↔ 금전 이외 재산권","담보책임 규정 준용(제567조)","보충금에는 매매대금 규정 준용(제597조)"]}},{"종류":"표","제목":"교환계약에 적용되는 규정","머리":["쟁점","적용 여부","근거"],"행":[["동시이행","적용(쌍무계약)","제536조"],["위험부담","적용","제537조"],["담보책임","준용","제567조"],["해약금","준용","제567조, 제565조"],["보충금","매매대금 규정 준용","제597조"]]}],"함정":"1번처럼 금전이 섞이면 매매라고 보기 쉽다. 교환의 목적물은 금전 이외의 재산권이고 보충금은 부수적이다. 4번은 교환은 소유권만 맞바꾸는 계약이라 위험부담이 안 맞는다고 오해한 선지다."}},{"i":"S2-1-1-민법-33","r":"S2","g":1,"c":1,"n":73,"s":"민법","q":"甲은 자기 소유 X토지를 3억원에 乙에게 매도하면서 동시에 환매할 권리를 보유하기로 약정하고 乙이 X토지에 대한 소유권 이전등기를 마쳤다. 이에 관한 설명으로 틀린 것은? (다툼이 있으면 판례에 따름)","b":null,"bs":"없음","img":[],"ch":["특별한 약정이 없는 한, 甲은 환매기간 내에 그가 수령한 3억원과 乙이 부담한 매매비용을 반환하고 X토지를 환매할 수 있다.","甲과 乙이 환매기간을 정하지 아니한 경우 그 기간은 5년으로 한다.","환매등기는 乙명의의 소유권이전등기에 대한 부기등기의 형식으로 한다.","만일 甲의 환매등기 후 丙이 乙로부터 X토지를 매수하였다면, 乙은 환매등기를 이유로 丙의 X토지에 대한 소유권이전등기청구를 거절할 수 있다.","만일 甲의 환매등기 후 丁이 X토지에 乙에 대한 채권을 담보하기 위하여 저당권을 설정하였다면, 甲이 적법하게 환매권을 행사하여 X토지의 소유권이전등기를 마친 경우 丁의 저당권은 소멸한다."],"a":[4],"L":"민3-2","o":"기출","x":{"한줄":"환매등기는 제3자에 대한 대항력을 줄 뿐, 환매 전의 소유자 乙이 丙과 맺은 매매의 이행을 거절할 사유가 되지 못한다.","근거":[{"법령":"민법","조문":"제590조","원문":"①매도인이 매매계약과 동시에 환매할 권리를 보류한 때에는 그 영수한 대금 및 매수인이 부담한 매매비용을 반환하고 그 목적물을 환매할 수 있다."},{"법령":"민법","조문":"제591조","원문":"①환매기간은 부동산은 5년, 동산은 3년을 넘지 못한다. … ③환매기간을 정하지 아니한 때에는 그 기간은 부동산은 5년, 동산은 3년으로 한다."},{"법령":"민법","조문":"제592조","원문":"제592조(환매등기) 매매의 목적물이 부동산인 경우에 매매등기와 동시에 환매권의 보류를 등기한 때에는 제삼자에 대하여 그 효력이 있다."},{"법령":"부동산등기법","조문":"제52조제6호","원문":"등기관이 다음 각 호의 등기를 할 때에는 부기로 하여야 한다. … 6. 제53조의 환매특약등기"}],"선지":[{"번호":1,"판정":"옳음","설명":"환매대금은 영수한 대금과 매수인이 부담한 매매비용이다(제590조 제1항)."},{"번호":2,"판정":"옳음","설명":"환매기간을 정하지 않으면 부동산은 5년이다(제591조 제3항)."},{"번호":3,"판정":"옳음","설명":"환매특약등기는 부기로 한다(부동산등기법 제52조 제6호)."},{"번호":4,"판정":"틀림","설명":"환매등기는 환매권이 제3자에게 대항력을 가진다는 뜻이다(제592조). 乙은 丙과의 매매를 이행해야 하고, 丙은 환매권 행사 시 소유권을 잃을 뿐이다."},{"번호":5,"판정":"옳음","설명":"환매등기 후에 생긴 저당권은 환매권자에게 대항하지 못하므로 환매권 행사 후 이전등기를 마치면 소멸한다(제592조)."}],"개념":[{"종류":"표","제목":"환매","머리":["구분","내용","근거"],"행":[["성립","매매계약과 동시에 환매권 보류","제590조 제1항"],["환매대금","영수한 대금 + 매수인이 부담한 매매비용(특약 우선). 과실과 이자는 상계로 봄","제590조 제2항·제3항"],["기간","부동산 5년, 동산 3년 한도. 정한 뒤 연장 불가. 미정이면 5년·3년","제591조"],["등기","매매등기와 동시에 환매권 보류를 등기하면 제3자에 대항. 부기등기","제592조, 부동산등기법 제52조 제6호"],["실행","기간 내에 대금과 매매비용을 제공해야 하고 안 하면 환매권 상실","제594조 제1항"]]},{"종류":"흐름","제목":"환매 실행","단계":[{"이름":"환매권 보류","설명":"매매계약과 동시에 약정"},{"이름":"환매등기","설명":"매매등기와 동시에 환매특약등기(부기)"},{"이름":"대금 제공","설명":"환매기간 내에 영수한 대금과 매매비용 제공(제594조 제1항)"},{"이름":"이전등기","설명":"환매권 행사 후 소유권 회복, 환매등기 후 생긴 권리는 대항 불가"},{"이름":"비용 상환","설명":"매수인·전득자가 지출한 비용은 제203조에 따라 상환(제594조 제2항)"}]}],"함정":"4번의 환매등기를 제3자의 이전등기청구를 막는 사유로 읽는 경우가 많다. 환매등기는 소유권 이전이 금지된다는 뜻이 아니다. 乙은 丙에게 팔 수 있고, 다만 丙은 환매권자에게 소유권을 넘겨줘야 한다. 5번은 환매등기 후 설정된 권리가 사라진다는 점에서 맞다."}},{"i":"S2-1-1-민법-34","r":"S2","g":1,"c":1,"n":74,"s":"민법","q":"甲 소유의 X건물을 임차한 乙이 丙에게 X건물을 전대하였다. 이에 관한 설명으로 옳은 것은? (다툼이 있으면 판례에 따름)","b":null,"bs":"없음","img":[],"ch":["甲의 동의를 얻어 전대한 경우, 丙은 乙에게 차임을 지급하였다는 사유로 甲에게 대항하지 못한다.","甲의 동의를 얻어 전대한 경우, 甲과 乙이 합의로 임대차를 종료시키면 丙의 권리도 소멸한다.","甲의 동의 없이 전대한 경우, 乙과 丙 사이의 전대차계약은 무효이다.","甲의 동의 없이 전대한 경우, 임대차가 존속하는 동안에도 甲은 丙에게 불법점유를 이유로 차임 상당의 손해배상을 청구할 수 있다.","乙이 X건물의 소부분을 甲의 동의 없이 丙에게 사용하게 한 경우에도 甲은 이를 이유로 임대차계약을 해지할 수 있다."],"a":[1],"L":"민3-3","o":"변형","x":{"한줄":"동의를 얻은 전차인은 임대인에게 직접 의무를 부담하고, 전대인에게 차임을 지급했다는 사유로 임대인에게 대항하지 못한다.","근거":[{"법령":"민법","조문":"제630조제1항","원문":"①임차인이 임대인의 동의를 얻어 임차물을 전대한 때에는 전차인은 직접 임대인에 대하여 의무를 부담한다. 이 경우에 전차인은 전대인에 대한 차임의 지급으로써 임대인에게 대항하지 못한다."},{"법령":"민법","조문":"제631조","원문":"제631조(전차인의 권리의 확정) 임차인이 임대인의 동의를 얻어 임차물을 전대한 경우에는 임대인과 임차인의 합의로 계약을 종료한 때에도 전차인의 권리는 소멸하지 아니한다."},{"법령":"민법","조문":"제629조","원문":"①임차인은 임대인의 동의없이 그 권리를 양도하거나 임차물을 전대하지 못한다. ②임차인이 전항의 규정에 위반한 때에는 임대인은 계약을 해지할 수 있다."},{"법령":"민법","조문":"제632조","원문":"제632조(임차건물의 소부분을 타인에게 사용케 하는 경우) 전3조의 규정은 건물의 임차인이 그 건물의 소부분을 타인에게 사용하게 하는 경우에 적용하지 아니한다."},{"판례":"대법원 판례(무단 전대)","요지":"임대인의 동의 없는 전대차도 전대인과 전차인 사이에서는 유효하다. 임대차가 존속하는 동안에는 임대인이 무단 전차인에게 불법점유를 이유로 차임 상당 손해배상을 청구할 수 없다."}],"선지":[{"번호":1,"판정":"옳음","설명":"전차인은 임대인에게 직접 의무를 지고, 전대인에게 낸 차임으로 임대인에게 대항하지 못한다(제630조 제1항)."},{"번호":2,"판정":"틀림","설명":"합의해지로 임대차가 끝나도 동의를 얻은 전차인의 권리는 소멸하지 않는다(제631조)."},{"번호":3,"판정":"틀림","설명":"동의가 없어도 乙과 丙 사이의 전대차는 유효하다. 임대인에게 대항하지 못할 뿐이다(판례)."},{"번호":4,"판정":"틀림","설명":"임대차가 존속하는 동안 임대인은 무단 전차인에게 차임 상당 손해배상을 청구하지 못한다. 임대인과 임차인 사이의 관계가 계속되기 때문이다(판례)."},{"번호":5,"판정":"틀림","설명":"건물의 소부분을 사용하게 하는 경우에는 제629조가 적용되지 않는다(제632조). 해지할 수 없다."}],"개념":[{"종류":"비교","제목":"전대차의 법률관계","왼쪽":{"이름":"동의를 얻은 전대","항목":["전차인이 임대인에게 직접 의무 부담(제630조 제1항)","전대인에게 낸 차임으로 임대인에게 대항 불가","합의해지로도 전차인의 권리 소멸 없음(제631조)","전차인은 부속물매수청구 가능(제647조)"]},"오른쪽":{"이름":"동의 없는 전대","항목":["전대차 자체는 전대인·전차인 사이에서 유효","임대인은 임대차계약을 해지할 수 있음(제629조 제2항)","임대차 존속 중 무단 전차인에게 차임 상당 손해배상 불가","소부분 전대는 해지 사유 아님(제632조)"]}},{"종류":"표","제목":"임대차 해지와 전차인","머리":["유형","내용","근거"],"행":[["기간 약정 없음","당사자는 언제든 해지 통고, 건물은 임대인 통고 6월·임차인 통고 1월 후 효력","제635조"],["해지통고 후 전차인","적법하게 전대된 경우 임대인이 전차인에게 사유를 통지하지 않으면 해지로 대항 불가","제638조 제1항"],["차임연체 해지","건물은 2기의 차임액에 달하면 임대인이 해지","제640조"],["전차인의 부속물매수청구","임대인의 동의를 얻은 부속물에 대해 전대차 종료 시 임대인에게 청구","제647조"]]}],"함정":"2번을 맞는 문장으로 읽는 경우가 많다. 임대인과 임차인이 계약의 주인이니 합의로 끝낼 수 있다고 보기 때문이다. 동의를 얻은 전차인은 그 합의로 권리를 잃지 않는다. 5번은 소부분 전대에 제629조가 적용된다고 보는 선지다. 제632조가 적용을 배제한다."}},{"i":"S2-1-1-민법-35","r":"S2","g":1,"c":1,"n":75,"s":"민법","q":"다음 중 연결이 잘못된 것은? (다툼이 있으면 판례에 따름)","b":null,"bs":"없음","img":[],"ch":["임차인의 필요비상환청구권 - 형성권","지명채권의 양도 - 준물권행위","부동산 매매에 의한 소유권 취득 - 특정승계","부동산 점유취득시효완성으로 인한 소유권 취득 - 원시취득","무권대리에서 추인 여부에 대한 확답의 최고 - 의사의 통지"],"a":[1],"L":"민3-3","o":"기출","x":{"한줄":"임차인의 필요비상환청구권은 임대인에게 상환을 요구하는 청구권이고 일방적 의사표시로 법률관계를 바꾸는 형성권이 아니다.","근거":[{"법령":"민법","조문":"제626조제1항","원문":"①임차인이 임차물의 보존에 관한 필요비를 지출한 때에는 임대인에 대하여 그 상환을 청구할 수 있다."},{"법령":"민법","조문":"제450조제1항","원문":"①지명채권의 양도는 양도인이 채무자에게 통지하거나 채무자가 승낙하지 아니하면 채무자 기타 제삼자에게 대항하지 못한다."},{"법령":"민법","조문":"제245조제1항","원문":"①20년간 소유의 의사로 평온, 공연하게 부동산을 점유하는 자는 등기함으로써 그 소유권을 취득한다."},{"법령":"민법","조문":"제131조","원문":"제131조(상대방의 최고권) 대리권없는 자가 타인의 대리인으로 계약을 한 경우에 상대방은 상당한 기간을 정하여 본인에게 그 추인여부의 확답을 최고할 수 있다. 본인이 그 기간내에 확답을 발하지 아니한 때에는 추인을 거절한 것으로 본다."}],"선지":[{"번호":1,"판정":"틀림","설명":"필요비 상환은 청구권(채권)이다(제626조 제1항). 형성권이 아니다."},{"번호":2,"판정":"옳음","설명":"지명채권 양도는 채권을 직접 처분하는 계약으로 준물권행위다."},{"번호":3,"판정":"옳음","설명":"매매로 소유권을 이전받는 것은 승계취득 중 개별 재산을 취득하는 특정승계다."},{"번호":4,"판정":"옳음","설명":"시효취득은 전 소유자의 권리를 승계하지 않는 원시취득이다(제245조 제1항)."},{"번호":5,"판정":"옳음","설명":"최고는 상대방에게 일정한 행위를 요구하는 의사의 통지다(제131조)."}],"개념":[{"종류":"표","제목":"형성권과 청구권","머리":["권리","성질","근거"],"행":[["취소권·해제권","형성권","제140조, 제543조"],["지상물매수청구권","형성권","제283조, 제643조"],["부속물매수청구권","형성권","제646조"],["지료증감청구권","형성권","제286조"],["필요비·유익비 상환청구권","청구권","제626조"]]},{"종류":"표","제목":"준법률행위의 유형","머리":["유형","예"],"행":[["의사의 통지","최고, 거절"],["관념의 통지","채권양도의 통지, 승낙연착의 통지, 채무의 승인"],["감정의 표시","용서 등"]]}],"함정":"1번의 형성권 연결이 맞다고 착각하기 쉽다. 같은 임대차에서 지상물매수청구권과 부속물매수청구권이 형성권이어서, 필요비 상환까지 형성권으로 묶어 외우는 경우가 많다. 필요비와 유익비의 상환은 형성권이 아니라 청구권이다."}},{"i":"S2-1-1-민법-36","r":"S2","g":1,"c":1,"n":76,"s":"민법","q":"임차인 乙은 임대인 甲에게 2024. 3. 10.로 기간이 만료되는 X주택의 임대차계약에 대해 주택임대차보호법에 따라 갱신요구 통지를 하여 그 통지가 2024. 1. 5. 甲에게 도달하였고, 甲이 갱신거절 통지를 하지 않아 계약이 갱신되었다. 그 후 乙이 갱신된 계약기간이 개시되기 전인 2024. 1. 29. 갱신된 임대차계약의 해지를 통지하여 2024. 1. 30. 甲에게 도달하였다. 임대차계약의 종료일은? (다툼이 있으면 판례에 따름)","b":null,"bs":"없음","img":[],"ch":["2024. 1. 30.","2024. 3. 10.","2024. 4. 30.","2024. 6. 10.","2026. 3. 10."],"a":[3],"L":"민4-1","o":"기출","x":{"한줄":"갱신된 임대차의 해지는 임대인이 통지를 받은 날부터 3개월이 지나면 효력이 생기므로 2024. 1. 30.부터 3개월이 지난 2024. 4. 30.에 끝난다.","근거":[{"법령":"주택임대차보호법","조문":"제6조의3제1항·제2항·제4항","원문":"① 제6조에도 불구하고 임대인은 임차인이 제6조제1항 전단의 기간 이내에 계약갱신을 요구할 경우 정당한 사유 없이 거절하지 못한다. … ② 임차인은 제1항에 따른 계약갱신요구권을 1회에 한하여 행사할 수 있다. 이 경우 갱신되는 임대차의 존속기간은 2년으로 본다. … ④ 제1항에 따라 갱신되는 임대차의 해지에 관하여는 제6조의2를 준용한다."},{"법령":"주택임대차보호법","조문":"제6조의2","원문":"① 제6조제1항에 따라 계약이 갱신된 경우 같은 조 제2항에도 불구하고 임차인은 언제든지 임대인에게 계약해지(契約解止)를 통지할 수 있다. ② 제1항에 따른 해지는 임대인이 그 통지를 받은 날부터 3개월이 지나면 그 효력이 발생한다."},{"법령":"주택임대차보호법","조문":"제6조제1항","원문":"① 임대인이 임대차기간이 끝나기 6개월 전부터 2개월 전까지의 기간에 임차인에게 갱신거절(更新拒絶)의 통지를 하지 아니하거나 … 그 기간이 끝난 때에 전 임대차와 동일한 조건으로 다시 임대차한 것으로 본다."}],"선지":[{"번호":1,"판정":"-","설명":"해지 통지가 도달한 날이다. 해지는 도달일부터 3개월이 지나야 효력이 생긴다."},{"번호":2,"판정":"-","설명":"종전 임대차의 만료일이다. 갱신된 임대차가 시작되기 전에도 해지 통지를 할 수 있고 효력은 도달일 기준 3개월 뒤다."},{"번호":3,"판정":"-","설명":"통지 도달일 2024. 1. 30.부터 3개월이 지난 날이다. 정답."},{"번호":4,"판정":"-","설명":"만료일 2024. 3. 10.부터 3개월을 센 날로 기산점이 틀렸다."},{"번호":5,"판정":"-","설명":"갱신된 2년 기간의 만료일이다. 임차인이 중도 해지를 통지했으므로 이 날까지 가지 않는다."}],"개념":[{"종류":"흐름","제목":"갱신요구권 행사 후 종료","단계":[{"이름":"갱신요구","설명":"만료 6개월 전부터 2개월 전까지, 이 사례는 2024. 1. 5. 도달(2024. 1. 10.까지 가능)"},{"이름":"갱신","설명":"임대인이 거절 사유 없이 거절하지 않으면 전 임대차와 같은 조건, 존속기간 2년(제6조의3 제2항·제3항)"},{"이름":"임차인의 해지 통지","설명":"언제든 가능(제6조의2 제1항), 2024. 1. 30. 도달"},{"이름":"해지 효력","설명":"임대인이 통지를 받은 날부터 3개월이 지나면 효력(제6조의2 제2항), 2024. 4. 30."}]},{"종류":"표","제목":"임대인이 갱신요구를 거절할 수 있는 사유","머리":["사유","근거"],"행":[["2기의 차임액에 이르도록 연체","제6조의3 제1항 제1호"],["거짓·부정한 방법으로 임차","제2호"],["합의로 상당한 보상 제공","제3호"],["동의 없는 전대","제4호"],["고의·중과실로 주택 파손","제5호"],["철거·재건축","제7호"],["임대인(직계존비속 포함) 실거주","제8호"]]}],"함정":"2번이나 5번을 고르는 경우가 많다. 갱신 효과 때문에 3월 10일이나 갱신 만료일에 끝난다고 보기 때문이다. 갱신된 임대차에서 임차인은 언제든 해지를 통지할 수 있고 효력은 임대인이 통지를 받은 날부터 3개월 뒤다. 임차인의 해지 통지일(1월 29일)이 아니라 도달일(1월 30일)이 기준이다."}},{"i":"S2-1-1-민법-37","r":"S2","g":1,"c":1,"n":77,"s":"민법","q":"상가건물 임대차보호법에 관한 설명으로 옳은 것은? (다툼이 있으면 판례에 따름)","b":null,"bs":"없음","img":[],"ch":["기간을 정하지 아니하거나 기간을 1년 미만으로 정한 임대차는 그 기간을 2년으로 본다.","임차인의 계약갱신요구권은 최초의 임대차기간을 포함한 전체 임대차기간이 10년을 초과하지 않는 범위에서만 행사할 수 있다.","환산보증금이 대통령령으로 정한 보증금액을 초과하는 임대차에는 대항력에 관한 규정이 적용되지 않는다.","차임 증액 후 6개월이 지나면 다시 차임의 증액을 청구할 수 있다.","임차인의 차임연체액이 2기의 차임액에 달하면 임대인은 계약을 해지할 수 있다."],"a":[2],"L":"민4-2","o":"변형","x":{"한줄":"계약갱신요구권은 최초 임대차기간을 포함해 전체 임대차기간이 10년을 넘지 않는 범위에서만 행사할 수 있다.","근거":[{"법령":"상가건물 임대차보호법","조문":"제10조제2항","원문":"② 임차인의 계약갱신요구권은 최초의 임대차기간을 포함한 전체 임대차기간이 10년을 초과하지 아니하는 범위에서만 행사할 수 있다."},{"법령":"상가건물 임대차보호법","조문":"제9조제1항","원문":"① 기간을 정하지 아니하거나 기간을 1년 미만으로 정한 임대차는 그 기간을 1년으로 본다. 다만, 임차인은 1년 미만으로 정한 기간이 유효함을 주장할 수 있다."},{"법령":"상가건물 임대차보호법","조문":"제2조제3항","원문":"③ 제1항 단서에도 불구하고 제3조, 제10조제1항, 제2항, 제3항 본문, 제10조의2부터 제10조의9까지의 규정, 제11조의2 및 제19조는 제1항 단서에 따른 보증금액을 초과하는 임대차에 대하여도 적용한다."},{"법령":"상가건물 임대차보호법","조문":"제11조제2항","원문":"② 제1항에 따른 증액 청구는 임대차계약 또는 약정한 차임 등의 증액이 있은 후 1년 이내에는 하지 못한다."},{"법령":"상가건물 임대차보호법","조문":"제10조의8","원문":"제10조의8(차임연체와 해지) 임차인의 차임연체액이 3기의 차임액에 달하는 때에는 임대인은 계약을 해지할 수 있다."}],"선지":[{"번호":1,"판정":"틀림","설명":"기간을 정하지 않거나 1년 미만으로 정하면 1년으로 본다(제9조 제1항). 2년이 아니다."},{"번호":2,"판정":"옳음","설명":"제10조 제2항. 전체 임대차기간 10년이 한도다."},{"번호":3,"판정":"틀림","설명":"보증금액을 초과하는 임대차에도 제3조(대항력)는 적용된다(제2조 제3항)."},{"번호":4,"판정":"틀림","설명":"증액 후 1년 이내에는 다시 증액을 청구하지 못한다(제11조 제2항)."},{"번호":5,"판정":"틀림","설명":"상가의 해지 사유는 3기의 차임액 연체다(제10조의8). 2기는 주택 갱신거절 사유와 민법 제640조의 숫자다."}],"개념":[{"종류":"표","제목":"상가건물 임대차보호법 주요 수치","머리":["항목","내용","근거"],"행":[["최단기간","기간 없음·1년 미만 → 1년(임차인은 1년 미만 유효 주장 가능)","제9조 제1항"],["갱신요구권","만료 6개월 전~1개월 전, 전체 10년 한도","제10조 제1항·제2항"],["갱신된 임대차의 기간","1년(묵시적 갱신)","제10조 제4항"],["차임 증액","청구 당시 차임의 5% 한도, 증액 후 1년 이내 재증액 불가","시행령 제4조, 제11조 제2항"],["차임연체 해지","3기의 차임액","제10조의8"],["권리금 손해배상청구권","임대차 종료일부터 3년","제10조의4 제4항"]]},{"종류":"표","제목":"보증금액 초과 임대차에도 적용되는 규정","머리":["규정","내용"],"행":[["제3조","대항력"],["제10조 제1항·제2항·제3항 본문","갱신요구권, 10년 한도, 갱신조건"],["제10조의2~제10조의9","권리금 회수기회 보호, 차임연체 해지 등"],["제11조의2·제19조","폐업으로 인한 임차인의 해지권, 표준계약서"]]}],"함정":"1번에서 주택임대차의 2년을 상가에 그대로 적용하는 경우가 많다. 상가는 1년이다. 3번은 환산보증금을 초과하면 법 전체가 적용되지 않는다고 생각하는 선지로, 제2조 제3항이 대항력·갱신요구권·권리금 보호 등은 계속 적용한다고 정한다."}},{"i":"S2-1-1-민법-38","r":"S2","g":1,"c":1,"n":78,"s":"민법","q":"가등기담보 등에 관한 법률이 적용되는 가등기담보에 관한 설명으로 옳은 것은? (다툼이 있으면 판례에 따름)","b":null,"bs":"없음","img":[],"ch":["채무자가 아닌 제3자는 가등기담보권의 설정자가 될 수 없다.","귀속청산에서 변제기 후 청산금의 평가액을 채무자에게 통지한 경우, 채권자는 그가 통지한 청산금의 금액에 관하여 다툴 수 있다.","공사대금채권을 담보하기 위하여 담보가등기를 한 경우, ｢가등기담보 등에 관한 법률｣이 적용된다.","가등기담보권자는 특별한 사정이 없는 한 가등기담보권을 그 피담보채권과 함께 제3자에게 양도할 수 있다.","가등기담보권자는 담보목적물에 대한 경매를 청구할 수 없다."],"a":[4],"L":"민4-3","o":"기출","x":{"한줄":"가등기담보권은 피담보채권과 함께라면 제3자에게 양도할 수 있다.","근거":[{"법령":"가등기담보 등에 관한 법률","조문":"제2조제2호","원문":"2. \"채무자등\"이란 다음 각 목의 자를 말한다. 가. 채무자 나. 담보가등기목적 부동산의 물상보증인(物上保證人) 다. 담보가등기 후 소유권을 취득한 제삼자"},{"법령":"가등기담보 등에 관한 법률","조문":"제1조","원문":"이 법은 차용물(借用物)의 반환에 관하여 차주(借主)가 차용물을 갈음하여 다른 재산권을 이전할 것을 예약할 때 그 재산의 예약 당시 가액(價額)이 차용액(借用額)과 이에 붙인 이자를 합산한 액수를 초과하는 경우에 이에 따른 담보계약(擔保契約)과 그 담보의 목적으로 마친 가등기(假登記) 또는 소유권이전등기(所有權移轉登記)의 효력을 정함을 목적으로 한다."},{"법령":"가등기담보 등에 관한 법률","조문":"제12조제1항","원문":"① 담보가등기권리자는 그 선택에 따라 제3조에 따른 담보권을 실행하거나 담보목적부동산의 경매를 청구할 수 있다. 이 경우 경매에 관하여는 담보가등기권리를 저당권으로 본다."},{"법령":"가등기담보 등에 관한 법률","조문":"제3조제1항","원문":"① 채권자가 담보계약에 따른 담보권을 실행하여 그 담보목적부동산의 소유권을 취득하기 위하여는 그 채권(債權)의 변제기(辨濟期) 후에 제4조의 청산금(淸算金)의 평가액을 채무자등에게 통지하고, 그 통지가 채무자등에게 도달한 날부터 2개월(이하 \"청산기간\"이라 한다)이 지나야 한다."}],"선지":[{"번호":1,"판정":"틀림","설명":"물상보증인과 담보가등기 후 소유권을 취득한 제3자도 채무자등에 포함된다(제2조 제2호). 제3자도 설정자가 될 수 있다."},{"번호":2,"판정":"틀림","설명":"채권자가 통지한 청산금 평가액은 채권자를 구속하므로 그 금액을 다툴 수 없다(판례). 채무자등은 실제 가액이 더 크다고 다툴 수 있다."},{"번호":3,"판정":"틀림","설명":"이 법은 차용물 반환채권(소비대차) 담보에 적용된다(제1조). 공사대금채권을 담보하는 가등기는 적용 대상이 아니다(판례)."},{"번호":4,"판정":"옳음","설명":"가등기담보권은 피담보채권과 함께 양도할 수 있고, 가등기는 부기등기로 이전한다(판례)."},{"번호":5,"판정":"틀림","설명":"담보가등기권리자는 담보권 실행 대신 경매를 청구할 수 있다(제12조 제1항)."}],"개념":[{"종류":"흐름","제목":"가등기담보 실행(귀속청산)","단계":[{"이름":"변제기 도래","설명":"채무의 변제기가 지남"},{"이름":"청산금 통지","설명":"변제기 후 청산금 평가액을 채무자등에게 통지, 부동산 평가액과 채권액 명시(제3조)"},{"이름":"청산기간","설명":"통지가 도달한 날부터 2개월(제3조 제1항)"},{"이름":"청산금 지급","설명":"가등기는 청산기간 후 본등기 청구, 청산금 지급과 본등기·인도는 동시이행(제4조)"},{"이름":"소유권 취득","설명":"소유권이전등기를 마친 경우 청산기간 후 청산금을 지급한 때(제4조 제2항)"}]},{"종류":"표","제목":"가등기담보법 주요 규정","머리":["구분","내용","근거"],"행":[["적용 대상","차용물 반환채권 담보, 예약 당시 가액이 차용액+이자 초과","제1조"],["채무자등","채무자, 물상보증인, 담보가등기 후 소유권 취득 제3자","제2조 제2호"],["불리한 특약","청산 규정에 어긋나는 채무자 불리 특약은 무효","제4조 제4항"],["후순위권리자","청산금에 대해 통지 평가액 범위에서 권리 행사","제5조"],["말소청구","청산금채권을 변제받을 때까지 채무액 지급하고 말소 청구, 변제기 후 10년이 지나면 불가","제11조"],["우선변제","강제경매등에서 저당권으로 보아 우선변제","제13조"]]}],"함정":"2번은 채권자와 채무자의 위치를 바꿔 읽기 쉽다. 통지는 채권자가 한 것이므로 채권자가 그 금액에 스스로 구속된다. 3번은 이 법이 모든 채권 담보에 적용된다고 보는 선지다. 소비대차에서 생긴 채권의 담보만 대상이다."}},{"i":"S2-1-1-민법-39","r":"S2","g":1,"c":1,"n":79,"s":"민법","q":"집합건물의 소유 및 관리에 관한 법률상 관리단집회의 결의 요건에 관한 설명으로 옳은 것은?","b":null,"bs":"없음","img":[],"ch":["공용부분의 변경은 원칙적으로 구분소유자 및 의결권의 각 과반수의 결의로 한다.","규약의 설정·변경 및 폐지는 구분소유자 및 의결권의 각 3분의 2 이상의 찬성으로 한다.","구분소유자의 전유부분 및 대지사용권의 경매청구는 구분소유자 및 의결권의 각 과반수의 결의로 한다.","구분소유자의 전유부분 사용금지의 청구는 구분소유자 및 의결권의 각 5분의 4 이상의 결의로 한다.","재건축 결의는 구분소유자 및 의결권의 각 5분의 4 이상의 결의로 한다."],"a":[5],"L":"민4-4","o":"변형","x":{"한줄":"재건축 결의는 구분소유자의 5분의 4 이상 및 의결권의 5분의 4 이상이 있어야 한다.","근거":[{"법령":"집합건물의 소유 및 관리에 관한 법률","조문":"제47조제2항","원문":"② 제1항의 결의는 구분소유자의 5분의 4 이상 및 의결권의 5분의 4 이상의 결의에 따른다. 다만, 「관광진흥법」 제3조제1항제2호나목에 따른 휴양 콘도미니엄업의 운영을 위한 휴양 콘도미니엄의 재건축 결의는 구분소유자의 3분의 2 이상 및 의결권의 3분의 2 이상의 결의에 따른다."},{"법령":"집합건물의 소유 및 관리에 관한 법률","조문":"제15조제1항","원문":"① 공용부분의 변경에 관한 사항은 관리단집회에서 구분소유자의 3분의 2 이상 및 의결권의 3분의 2 이상의 결의로써 결정한다. 다만, 다음 각 호의 어느 하나에 해당하는 경우에는 제38조제1항에 따른 통상의 집회결의로써 결정할 수 있다."},{"법령":"집합건물의 소유 및 관리에 관한 법률","조문":"제29조제1항","원문":"① 규약의 설정ㆍ변경 및 폐지는 관리단집회에서 구분소유자의 4분의 3 이상 및 의결권의 4분의 3 이상의 찬성을 얻어서 한다."},{"법령":"집합건물의 소유 및 관리에 관한 법률","조문":"제44조제2항","원문":"② 제1항의 청구는 구분소유자의 4분의 3 이상 및 의결권의 4분의 3 이상의 관리단집회 결의가 있어야 한다."},{"법령":"집합건물의 소유 및 관리에 관한 법률","조문":"제45조제2항","원문":"② 제1항의 청구는 구분소유자의 4분의 3 이상 및 의결권의 4분의 3 이상의 관리단집회 결의가 있어야 한다."}],"선지":[{"번호":1,"판정":"틀림","설명":"공용부분의 변경은 원칙적으로 구분소유자와 의결권의 각 3분의 2 이상이다(제15조 제1항 본문)."},{"번호":2,"판정":"틀림","설명":"규약의 설정·변경·폐지는 각 4분의 3 이상이다(제29조 제1항)."},{"번호":3,"판정":"틀림","설명":"경매청구는 각 4분의 3 이상의 결의가 있어야 한다(제45조 제2항)."},{"번호":4,"판정":"틀림","설명":"사용금지 청구도 각 4분의 3 이상이다(제44조 제2항). 5분의 4는 재건축 결의의 요건이다."},{"번호":5,"판정":"옳음","설명":"제47조 제2항. 구분소유자와 의결권 각 5분의 4 이상이다."}],"개념":[{"종류":"표","제목":"관리단집회 결의 정족수","머리":["안건","구분소유자·의결권","근거"],"행":[["통상의 결의","각 과반수","제38조 제1항"],["공용부분의 변경","각 3분의 2 이상(개량 목적이고 과도한 비용이 아니면 통상결의)","제15조 제1항"],["규약의 설정·변경·폐지","각 4분의 3 이상","제29조 제1항"],["전유부분 사용금지 청구","각 4분의 3 이상","제44조 제2항"],["구분소유권 경매청구","각 4분의 3 이상","제45조 제2항"],["점유자에 대한 계약해제·인도청구","각 4분의 3 이상(제44조 제2항 준용)","제46조 제2항"],["일부 멸실 시 공용부분 복구 결의","각 5분의 4 이상","제50조 제4항"],["재건축 결의","각 5분의 4 이상(휴양 콘도미니엄은 3분의 2 이상)","제47조 제2항"]]}],"함정":"4번을 맞게 읽는 경우가 많다. 사용금지·경매청구 같은 제재가 무거워 재건축처럼 5분의 4가 필요하다고 보기 때문이다. 제재 안건은 4분의 3이고 5분의 4는 재건축과 일부 멸실 시 복구 결의다. 규약은 3분의 2가 아니라 4분의 3이다."}},{"i":"S2-1-1-민법-40","r":"S2","g":1,"c":1,"n":80,"s":"민법","q":"2022. 8. 16. 甲은 조세포탈의 목적으로 친구인 乙과 명의신탁약정을 맺고 乙은 이에 따라 甲으로부터 매수자금을 받아 丙소유의 X토지를 자신의 명의로 매수하여 등기를 이전받았다. 이에 관한 설명으로 틀린 것은? (다툼이 있으면 판례에 따름)","b":null,"bs":"없음","img":[],"ch":["甲과 乙의 명의신탁약정은 무효이다.","甲과 乙의 명의신탁약정이 있었다는 사실을 丙이 몰랐다면, 乙은 丙으로부터 X토지의 소유권을 승계취득한다.","乙이 X토지의 소유권을 취득하더라도, 甲은 乙에 대하여 부당이득을 원인으로 X토지의 소유권이전등기를 청구할 수 없다.","甲은 乙에 대해 가지는 매수자금 상당의 부당이득반환청구권에 기하여 X토지에 유치권을 행사할 수 없다.","만일 乙이 丁에게 X토지를 양도한 경우, 丁이 명의신탁약정에 대하여 단순히 알고 있었다면 丁은 X토지의 소유권을 취득하지 못한다."],"a":[5],"L":"민4-5","o":"기출","x":{"한줄":"명의신탁약정의 무효와 등기의 무효는 제3자에게 대항하지 못하므로, 丁이 약정을 알고 있었더라도 소유권을 취득한다.","근거":[{"법령":"부동산 실권리자명의 등기에 관한 법률","조문":"제4조","원문":"① 명의신탁약정은 무효로 한다. ② 명의신탁약정에 따른 등기로 이루어진 부동산에 관한 물권변동은 무효로 한다. 다만, 부동산에 관한 물권을 취득하기 위한 계약에서 명의수탁자가 어느 한쪽 당사자가 되고 상대방 당사자는 명의신탁약정이 있다는 사실을 알지 못한 경우에는 그러하지 아니하다. ③ 제1항 및 제2항의 무효는 제3자에게 대항하지 못한다."},{"판례":"대법원 판례(계약명의신탁)","요지":"계약명의신탁에서 매도인이 선의이면 수탁자가 소유권을 취득하고, 신탁자는 수탁자에게 매수자금 상당의 부당이득반환만 청구할 수 있으며 토지 자체의 이전등기를 청구하지 못한다. 매수자금 반환채권은 토지에 관하여 생긴 채권이 아니어서 유치권이 성립하지 않는다."}],"선지":[{"번호":1,"판정":"옳음","설명":"명의신탁약정은 무효다(제4조 제1항)."},{"번호":2,"판정":"옳음","설명":"계약명의신탁에서 상대방(丙)이 약정을 모르면 물권변동이 유효하다(제4조 제2항 단서). 乙이 소유권을 취득한다."},{"번호":3,"판정":"옳음","설명":"신탁자는 부동산 자체가 아니라 매수자금 상당의 부당이득반환만 청구할 수 있다(판례)."},{"번호":4,"판정":"옳음","설명":"매수자금 반환채권은 토지에 관해 생긴 채권이 아니어서 유치권이 성립하지 않는다(판례)."},{"번호":5,"판정":"틀림","설명":"무효는 제3자에게 대항하지 못한다(제4조 제3항). 丁이 악의여도 소유권을 취득한다."}],"개념":[{"종류":"표","제목":"명의신탁 유형별 효력","머리":["유형","약정","물권변동","결과"],"행":[["양자간 등기명의신탁","무효","무효","소유권은 신탁자에게 남음, 말소 청구 가능"],["3자간 등기명의신탁(중간생략형)","무효","무효","소유권은 매도인에게 남음, 신탁자는 매도인을 대위해 수탁자 명의 등기의 말소를 청구"],["계약명의신탁(매도인 선의)","무효","유효","수탁자가 소유권 취득, 신탁자는 매수자금 부당이득 반환 청구"],["계약명의신탁(매도인 악의)","무효","무효","소유권은 매도인에게 남음, 신탁자는 수탁자에게 매수자금 반환 청구"]]},{"종류":"비교","제목":"제4조 제3항의 대항 불능","왼쪽":{"이름":"제3자에게 대항 못 함","항목":["약정 무효","등기에 따른 물권변동 무효","수탁자로부터 취득한 제3자는 선악을 불문하고 보호"]},"오른쪽":{"이름":"특례(제8조)","항목":["종중이 보유한 부동산을 종중 외 명의로 등기","배우자 명의 등기","종교단체 산하 조직의 부동산을 종교단체 명의로 등기","조세포탈·강제집행 면탈·법령상 제한 회피 목적이 없을 때 제4조 적용 배제"]}}],"함정":"5번을 맞다고 읽는 경우가 많다. 악의의 제3자는 보호할 필요가 없다는 일반 법감정 때문이다. 이 법의 무효는 제3자의 선의·악의를 구별하지 않고 대항하지 못한다. 2번은 계약명의신탁에서 상대방의 선의를 요건으로 하는 제4조 제2항 단서에 해당한다."}},{"i":"S2-2-1-중개사법-01","r":"S2","g":2,"c":2,"n":1,"s":"중개사법","q":"공인중개사법령상 용어의 정의에 관한 설명으로 옳은 것은? (다툼이 있으면 판례에 따름)","b":null,"bs":"없음","img":[],"ch":["“공인중개사”는 이 법에 따라 자격을 취득한 자 중 중개사무소 개설등록을 마친 자만을 말한다.","개업공인중개사인 법인의 임원으로서 공인중개사인 자가 그 법인의 중개업무를 수행하거나 보조하는 경우 “소속공인중개사”에 해당한다.","“중개보조원”은 개업공인중개사에 소속되어 현장안내 등 단순한 업무를 보조하는 자로서, 공인중개사 자격의 유무를 묻지 않는다.","중개행위에 해당하는지는 개업공인중개사의 주관적 의사를 기준으로 가리므로, 알선하려는 의사가 없었다면 객관적으로 알선행위로 보이더라도 중개행위가 아니다.","“중개업”은 다른 사람의 의뢰에 의하여 중개를 업으로 행하는 것을 말하며, 보수를 받는지는 요건이 아니다."],"a":[2],"L":"중1-1","o":"변형","x":{"한줄":"법인의 사원·임원인 공인중개사는 개업공인중개사가 아니라 소속공인중개사에 포함된다(법 제2조 제5호).","근거":[{"법령":"공인중개사법","조문":"제2조 제2호 제3호 제4호 제5호 제6호","원문":"2. \"공인중개사\"라 함은 이 법에 의한 공인중개사자격을 취득한 자를 말한다.\n3. \"중개업\"이라 함은 다른 사람의 의뢰에 의하여 일정한 보수를 받고 중개를 업으로 행하는 것을 말한다.\n4. \"개업공인중개사\"라 함은 이 법에 의하여 중개사무소의 개설등록을 한 자를 말한다.\n5. \"소속공인중개사\"라 함은 개업공인중개사에 소속된 공인중개사(개업공인중개사인 법인의 사원 또는 임원으로서 공인중개사인 자를 포함한다)로서 중개업무를 수행하거나 개업공인중개사의 중개업무를 보조하는 자를 말한다.\n6. \"중개보조원\"이라 함은 공인중개사가 아닌 자로서 개업공인중개사에 소속되어 중개대상물에 대한 현장안내 및 일반서무 등 개업공인중개사의 중개업무와 관련된 단순한 업무를 보조하는 자를 말한다."}],"선지":[{"번호":1,"판정":"틀림","설명":"공인중개사는 자격 취득만으로 성립하고 등록 여부와 관계없다. 개설등록을 마친 자는 개업공인중개사다(법 제2조 제2호·제4호)."},{"번호":2,"판정":"옳음","설명":"소속공인중개사에는 법인의 사원·임원인 공인중개사도 포함된다(법 제2조 제5호 괄호)."},{"번호":3,"판정":"틀림","설명":"중개보조원은 공인중개사가 아닌 자다. 자격자가 단순 보조만 해도 소속공인중개사다(법 제2조 제6호)."},{"번호":4,"판정":"틀림","설명":"중개행위 여부는 행위를 객관적으로 보아 사회통념상 거래 알선을 위한 행위인지로 가린다(판례). 속마음은 기준이 아니다."},{"번호":5,"판정":"틀림","설명":"중개업은 ‘일정한 보수를 받고’ 중개를 업으로 하는 것이다. 보수를 받지 않았으면 중개업이 아니다(법 제2조 제3호)."}],"개념":[{"종류":"표","제목":"중개 관련 여섯 용어","머리":["용어","뜻","구별 기준"],"행":[["중개","중개대상물에 대한 매매·교환·임대차 그 밖의 권리 득실변경 행위의 알선","대상물이 법 제3조 범위일 것"],["공인중개사","이 법에 따라 자격을 취득한 자","자격 취득"],["중개업","다른 사람의 의뢰로 일정한 보수를 받고 중개를 업으로 하는 것","의뢰·보수·업"],["개업공인중개사","중개사무소 개설등록을 한 자","등록"],["소속공인중개사","개업공인중개사에 소속된 공인중개사(법인의 사원·임원인 공인중개사 포함)로서 중개업무를 수행하거나 보조하는 자","자격 있음 + 소속"],["중개보조원","공인중개사가 아닌 자로서 개업공인중개사에 소속되어 현장안내·일반서무 등 단순 업무를 보조하는 자","자격 없음 + 소속"]]},{"종류":"비교","제목":"소속공인중개사와 중개보조원","왼쪽":{"이름":"소속공인중개사","항목":["공인중개사 자격 있음","중개업무 수행 또는 보조","인장 등록 의무 있음","중개했으면 확인·설명서·거래계약서에 서명 및 날인"]},"오른쪽":{"이름":"중개보조원","항목":["공인중개사 자격 없음","현장안내·일반서무 등 단순 보조","인장 등록 의무 없음","서명·날인 의무 없음, 현장안내 때 중개보조원임을 미리 고지"]}}],"함정":"법인 임원인 공인중개사를 개업공인중개사로 보기 쉽다. 개업공인중개사는 등록을 한 법인 자체이고, 임원은 소속공인중개사다. 선지 5는 보수 요건을 빼 버린 문장이다."}},{"i":"S2-2-1-중개사법-02","r":"S2","g":2,"c":2,"n":2,"s":"중개사법","q":"공인중개사법령상 중개대상물에 해당하는 것은? (다툼이 있으면 판례에 따름)","b":null,"bs":"없음","img":[],"ch":["토지에서 채굴되지 않은 광물","영업상 노하우 등 무형의 재산적 가치","토지로부터 분리된 수목","지목(地目)이 양어장인 토지","주택이 철거될 경우 일정한 요건하에 택지개발지구 내 이주자택지를 공급받을 수 있는 지위"],"a":[4],"L":"중1-1","o":"기출","x":{"한줄":"토지는 지목과 관계없이 중개대상물이므로 양어장 토지도 대상이다(법 제3조 제1호).","근거":[{"법령":"공인중개사법","조문":"제3조","원문":"제3조(중개대상물의 범위) 이 법에 의한 중개대상물은 다음 각 호와 같다.\n1. 토지\n2. 건축물 그 밖의 토지의 정착물\n3. 그 밖에 대통령령으로 정하는 재산권 및 물건"},{"법령":"공인중개사법 시행령","조문":"제2조 제1호 제2호","원문":"1. 「입목에 관한 법률」에 따른 입목\n2. 「공장 및 광업재단 저당법」에 따른 공장재단 및 광업재단"}],"선지":[{"번호":1,"판정":"-","설명":"채굴되지 않은 광물은 토지의 정착물이나 법정 재산권이 아니라서 중개대상물이 아니다(법 제3조, 영 제2조)."},{"번호":2,"판정":"-","설명":"거래처·신용·노하우·점포 위치의 이점 같은 무형의 재산적 가치는 중개대상물이 아니다(판례)."},{"번호":3,"판정":"-","설명":"토지에서 베어 낸 수목은 동산이다. 중개대상물은 토지·건축물·정착물·입목·공장재단·광업재단이다."},{"번호":4,"판정":"-","설명":"토지는 지목과 상관없이 법 제3조 제1호의 중개대상물이다."},{"번호":5,"판정":"-","설명":"이주자택지를 공급받을 지위(대토권)는 특정한 물건이 아니라 지위에 불과해 중개대상물이 아니다(판례)."}],"개념":[{"종류":"표","제목":"중개대상물 해당 여부","머리":["대상","해당 여부","이유"],"행":[["토지(지목 불문)","해당","법 제3조 제1호"],["미등기·무허가 건물, 가압류된 토지, 유치권 행사 중 건물","해당","거래가 가능한 건축물·토지"],["동·호수가 특정되어 분양계약이 체결된 아파트 분양권","해당","특정할 수 있는 장래의 건물"],["입목, 공장재단, 광업재단","해당","영 제2조"],["입주권·대토권","비해당","특정 물건이 아닌 지위"],["권리금, 영업시설·비품, 거래처·신용","비해당","무형 재산가치·동산"],["채굴되지 않은 광물, 온천수, 금전채권, 점유","비해당","법정 범위 밖"],["토지에서 베어 낸 수목","비해당","동산"]]}],"함정":"입주권·대토권을 분양권과 같게 보고 고르기 쉽다. 분양권은 동·호수가 특정된 건물이라 대상이고, 입주권·대토권은 지위라서 대상이 아니다."}},{"i":"S2-2-1-중개사법-03","r":"S2","g":2,"c":2,"n":3,"s":"중개사법","q":"공인중개사법령상 공인중개사자격증에 관한 설명으로 옳은 것을 모두 고른 것은?","b":"ㄱ. 공인중개사는 다른 사람에게 자기의 공인중개사자격증을 양도하여서는 아니된다.\nㄴ. 누구든지 다른 사람의 공인중개사자격증을 양수하여 이를 사용하여서는 아니된다.\nㄷ. 공인중개사는 다른 공인중개사가 공인중개사자격증을 대여하는 것을 알선할 수 있다.","bs":"글자","img":[],"ch":["ㄱ","ㄱ, ㄴ","ㄱ, ㄷ","ㄴ, ㄷ","ㄱ, ㄴ, ㄷ"],"a":[2],"L":"중1-2","o":"기출","x":{"한줄":"자격증의 양도·양수·대여는 금지되고 그 알선도 누구에게나 금지되므로 ㄱ·ㄴ만 옳다(법 제7조).","근거":[{"법령":"공인중개사법","조문":"제7조","원문":"제7조(자격증 대여 등의 금지)\n①공인중개사는 다른 사람에게 자기의 성명을 사용하여 중개업무를 하게 하거나 자기의 공인중개사자격증을 양도 또는 대여하여서는 아니된다.\n②누구든지 다른 사람의 공인중개사자격증을 양수하거나 대여받아 이를 사용하여서는 아니된다.\n③ 누구든지 제1항 및 제2항에서 금지한 행위를 알선하여서는 아니 된다."},{"법령":"공인중개사법","조문":"제49조 제1항 제1호 1의2.","원문":"①다음 각 호의 어느 하나에 해당하는 자는 1년 이하의 징역 또는 1천만원 이하의 벌금에 처한다.\n1. 제7조제1항 또는 제2항을 위반하여 다른 사람에게 자기의 성명을 사용하여 중개업무를 하게 하거나 공인중개사자격증을 양도ㆍ대여한 자 또는 다른 사람의 공인중개사자격증을 양수ㆍ대여받은 자\n1의2. 제7조제3항을 위반하여 같은 조 제1항 및 제2항에서 금지한 행위를 알선한 자\n2. 제8조의 규정을 위반하여 공인중개사가 아닌 자로서 공인중개사 또는 이와 유사한 명칭을 사용한 자\n3. 제12조의 규정을 위반하여 이중으로 중개사무소의 개설등록을 하거나 둘 이상의 중개사무소에 소속된 자\n4. 제13조제1항의 규정을 위반하여 둘 이상의 중개사무소를 둔 자\n5. 제13조제2항의 규정을 위반하여 임시 중개시설물을 설치한 자\n5의2. 제15조제3항을 위반하여 중개보조원을 고용한 자\n6. 제18조제2항의 규정을 위반하여 개업공인중개사가 아닌 자로서 \"공인중개사사무소\", \"부동산중개\" 또는 이와 유사한 명칭을 사용한 자\n6의2. 제18조의2제3항을 위반하여 개업공인중개사가 아닌 자로서 중개업을  하기 위하여 중개대상물에 대한 표시ㆍ광고를 한 자\n7. 제19조제1항 또는 제2항을 위반하여 다른 사람에게 자기의 성명 또는 상호를 사용하여 중개업무를 하게 하거나 중개사무소등록증을 다른 사람에게 양도ㆍ대여한 자 또는 다른 사람의 성명ㆍ상호를 사용하여 중개업무를 하거나 중개사무소등록증을 양수ㆍ대여받은 자\n7의2. 제19조제3항을 위반하여 같은 조 제1항 및 제2항에서 금지한 행위를 알선한 자\n8. 제24조제4항의 규정을 위반하여 정보를 공개한 자\n9. 제29조제2항의 규정을 위반하여 업무상 비밀을 누설한 자\n10. 제33조제1항제1호부터 제4호까지의 규정을 위반한 자\n1. 제7조제1항 또는 제2항을 위반하여 다른 사람에게 자기의 성명을 사용하여 중개업무를 하게 하거나 공인중개사자격증을 양도ㆍ대여한 자 또는 다른 사람의 공인중개사자격증을 양수ㆍ대여받은 자\n1의2. 제7조제3항을 위반하여 같은 조 제1항 및 제2항에서 금지한 행위를 알선한 자"}],"선지":[{"번호":1,"판정":"-","설명":"ㄴ도 옳으므로 ㄱ만으로는 부족하다."},{"번호":2,"판정":"-","설명":"ㄱ, ㄴ이 옳다."},{"번호":3,"판정":"-","설명":"ㄷ이 틀려서 맞지 않다."},{"번호":4,"판정":"-","설명":"ㄱ이 빠지고 ㄷ이 들어갔다."},{"번호":5,"판정":"-","설명":"ㄷ이 틀려서 맞지 않다."}],"보기판정":[{"기호":"ㄱ","판정":"옳음","설명":"자격증 양도·대여는 금지다(법 제7조 제1항)."},{"기호":"ㄴ","판정":"옳음","설명":"남의 자격증을 양수하거나 대여받아 쓰는 것도 누구에게나 금지다(법 제7조 제2항)."},{"기호":"ㄷ","판정":"틀림","설명":"자격증 양도·대여의 알선은 금지다(법 제7조 제3항). 위반하면 1년 이하 징역 또는 1천만원 이하 벌금(법 제49조 제1항 제1호의2)."}],"개념":[{"종류":"표","제목":"자격증·등록증 대여 등 금지 비교","머리":["구분","금지 행위","금지 대상자","벌칙"],"행":[["공인중개사 자격증(법 제7조)","성명 사용 중개업무, 자격증 양도·대여, 양수·대여받아 사용, 알선","①②는 공인중개사 또는 누구든지, ③ 알선은 누구든지","1년 이하 징역 또는 1천만원 이하 벌금"],["중개사무소등록증(법 제19조)","성명·상호 사용 중개업무, 등록증 양도·대여, 양수·대여받아 사용, 알선","①은 개업공인중개사, ②③은 누구든지","1년 이하 징역 또는 1천만원 이하 벌금"],["행정처분","자격증: 성명 사용·양도·대여는 자격취소 사유","등록증: 성명·상호 사용, 양도·대여는 절대적 등록취소 사유","자격취소·등록취소 후 3년간 결격"]]},{"종류":"표","제목":"유사명칭 사용금지","머리":["구분","금지 명칭","벌칙"],"행":[["공인중개사가 아닌 자","공인중개사 또는 이와 유사한 명칭","1년 이하 징역 또는 1천만원 이하 벌금"],["개업공인중개사가 아닌 자","공인중개사사무소, 부동산중개 또는 이와 유사한 명칭","1년 이하 징역 또는 1천만원 이하 벌금"]]}],"함정":"ㄷ을 고르면 틀린다. 금지 대상이 ‘양도·대여’ 행위자뿐이라고 보기 쉬운데 2023년 신설된 제3항이 알선 자체를 금지한다.","개정":"2023.6.1 신설된 법 제7조 제3항이 자격증 양도·대여 알선을 금지한다(제49조 제1항 제1호의2)."}},{"i":"S2-2-1-중개사법-04","r":"S2","g":2,"c":2,"n":4,"s":"중개사법","q":"공인중개사법령상 공인중개사 자격시험과 정책심의위원회에 관한 설명으로 옳은 것은?","b":null,"bs":"없음","img":[],"ch":["시험시행기관장은 부득이한 사정이 있더라도 해당 연도의 시험을 시행하지 아니할 수 없다.","시험시행기관장은 시험일시, 시험장소, 시험방법 등 시험의 시행에 필요한 사항을 시험시행일 90일 전까지 공고해야 한다.","시·도지사는 시험합격자 결정 공고일부터 3개월 이내에 합격자에게 공인중개사자격증을 교부해야 한다.","공인중개사 정책심의위원회는 위원장 1명을 포함하여 5명 이상 9명 이내의 위원으로 구성한다.","위원장이 부득이한 사유로 직무를 수행할 수 없을 때에는 부위원장이 그 직무를 대행한다."],"a":[2],"L":"중1-2","o":"변형","x":{"한줄":"시험의 세부 사항(시험일시·장소·방법 등)은 시험시행일 90일 전까지 공고한다(영 제7조 제3항).","근거":[{"법령":"공인중개사법 시행령","조문":"제7조 제1항 제3항","원문":"①시험은 매년 1회 이상 시행한다. 다만, 시험시행기관장은 시험을 시행하기 어려운 부득이한 사정이 있는 경우에는 심의위원회의 의결을 거쳐 당해연도의 시험을 시행하지 아니할 수 있다.\n③시험시행기관장은 제2항에 따른 공고 후 시험을 시행하려는 때에는 시험일시, 시험장소, 시험방법, 합격자 결정방법 및 응시수수료의 반환에 관한 사항 등 시험의 시행에 필요한 사항을 시험시행일 90일 전까지 일간신문, 관보, 방송 중 하나 이상에 공고하고, 인터넷 홈페이지 등에도 이를 공고해야 한다."},{"법령":"공인중개사법 시행규칙","조문":"제3조 제1항","원문":"①특별시장ㆍ광역시장ㆍ도지사ㆍ특별자치도지사(이하 \"시ㆍ도지사\"라 한다)는 「공인중개사법」(이하 \"법\"이라 한다) 제5조제1항에 따른 시험합격자의 결정 공고일부터 1개월 이내에 시험합격자에 관한 사항을 별지 제2호서식의 공인중개사자격증교부대장에 기재한 후, 시험 합격자에게 별지 제3호서식의 공인중개사자격증을 교부하여야 한다."},{"법령":"공인중개사법 시행령","조문":"제1조의2 제1항","원문":"① 「공인중개사법」(이하 \"법\"이라 한다) 제2조의2제1항에 따른 공인중개사 정책심의위원회(이하 \"심의위원회\"라 한다)는 위원장 1명을 포함하여 7명 이상 11명 이내의 위원으로 구성한다."},{"법령":"공인중개사법 시행령","조문":"제1조의4 제2항","원문":"② 위원장이 부득이한 사유로 직무를 수행할 수 없을 때에는 위원장이 미리 지명한 위원이 그 직무를 대행한다."}],"선지":[{"번호":1,"판정":"틀림","설명":"부득이한 사정이 있으면 심의위원회 의결을 거쳐 해당 연도 시험을 시행하지 않을 수 있다(영 제7조 제1항 단서)."},{"번호":2,"판정":"옳음","설명":"개략 사항은 매년 2월 말일까지, 세부 사항은 시험시행일 90일 전까지 공고한다(영 제7조 제2항·제3항)."},{"번호":3,"판정":"틀림","설명":"합격자 결정 공고일부터 1개월 이내에 교부대장에 적고 자격증을 교부한다(칙 제3조 제1항)."},{"번호":4,"판정":"틀림","설명":"위원장 포함 7명 이상 11명 이내다(영 제1조의2 제1항)."},{"번호":5,"판정":"틀림","설명":"위원장이 미리 지명한 위원이 대행한다. 부위원장 제도는 없다(영 제1조의4 제2항)."}],"개념":[{"종류":"표","제목":"시험·자격증 기간과 주체","머리":["항목","내용"],"행":[["시험 시행","시·도지사. 국토교통부장관은 필요하면 직접 출제·시행하되 미리 심의위원회 의결"],["시행 횟수","매년 1회 이상. 부득이하면 심의위원회 의결로 그해 시험 생략 가능"],["개략 공고","매년 2월 말일까지"],["세부 공고","시험시행일 90일 전까지"],["자격증 교부","시·도지사, 합격자 결정 공고일부터 1개월 이내"],["자격증 재교부","교부한 시·도지사에게 신청"],["부정행위자","시험 무효, 처분일부터 5년간 응시자격 정지"]]},{"종류":"표","제목":"공인중개사 정책심의위원회","머리":["항목","내용"],"행":[["설치","국토교통부(임의 설치)"],["심의사항","자격취득, 중개업 육성, 중개보수 변경, 손해배상책임 보장"],["구성","위원장 포함 7명 이상 11명 이내, 위원장은 국토교통부 제1차관"],["위원 임명","국토교통부장관이 임명·위촉"],["직무대행","위원장이 미리 지명한 위원"],["의결","재적위원 과반수 출석, 출석위원 과반수 찬성"],["시·도지사 구속","자격취득 심의사항만 따라야 함"]]}],"함정":"심의위원회 숫자(7~11명)와 공고 시기(2월 말일 / 90일 전)를 섞어 고르기 쉽다. 교부 기간 1개월을 3개월로 바꾼 선지도 자주 나온다."}},{"i":"S2-2-1-중개사법-05","r":"S2","g":2,"c":2,"n":5,"s":"중개사법","q":"공인중개사법령상 중개사무소의 개설등록 및 등록의 결격사유 등에 관한 설명으로 틀린 것은?","b":null,"bs":"없음","img":[],"ch":["개업공인중개사는 다른 개업공인중개사의 중개보조원이 될 수 있다.","피성년후견인은 중개사무소의 개설등록을 할 수 없다.","공인중개사(소속공인중개사는 제외) 또는 법인이 아닌 자는 중개사무소의 개설등록을 신청할 수 없다.","자본금이 3천만원인 「상법」상 회사는 다른 법률의 규정이 있는 경우를 제외하고, 중개사무소의 개설등록을 할 수 없다.","금고 이상의 형의 집행유예를 받고 그 유예기간이 만료된 날부터 2년이 지나지 아니한 자는 소속공인중개사가 될 수 없다."],"a":[1],"L":"중1-3","o":"기출","x":{"한줄":"개업공인중개사는 다른 개업공인중개사의 소속공인중개사·중개보조원이 될 수 없다(법 제12조 제2항).","근거":[{"법령":"공인중개사법","조문":"제12조 제2항","원문":"②개업공인중개사등은 다른 개업공인중개사의 소속공인중개사ㆍ중개보조원 또는 개업공인중개사인 법인의 사원ㆍ임원이 될 수 없다."},{"법령":"공인중개사법","조문":"제9조 제2항","원문":"②공인중개사(소속공인중개사는 제외한다) 또는 법인이 아닌 자는 제1항에 따라 중개사무소의 개설등록을 신청할 수 없다."},{"법령":"공인중개사법 시행령","조문":"제13조 제1항 제2호 가목","원문":"①법 제9조제3항에 따른 중개사무소 개설등록의 기준은 다음 각 호와 같다. 다만, 다른 법률의 규정에 따라 부동산중개업을 할 수 있는 경우에는 다음 각 호의 기준을 적용하지 아니한다.\n1. 공인중개사가 중개사무소를 개설하고자 하는 경우\n가. 법 제34조제1항의 규정에 따른 실무교육을 받았을 것\n나. 건축물대장(「건축법」 제20조제5항에 따른 가설건축물대장은 제외한다. 이하 같다)에 기재된 건물(준공검사, 준공인가, 사용승인, 사용검사 등을 받은 건물로서 건축물대장에 기재되기 전의 건물을 포함한다. 이하 같다)에 중개사무소를 확보(소유ㆍ전세ㆍ임대차 또는 사용대차 등의 방법에 의하여 사용권을 확보하여야 한다)할 것\n2. 법인이 중개사무소를 개설하려는 경우\n가. 「상법」상 회사 또는 「협동조합 기본법」 제2조제1호에 따른 협동조합(같은 조 제3호에 따른 사회적협동조합은 제외한다)으로서 자본금이 5천만원 이상일 것\n나. 법 제14조에 규정된 업무만을 영위할 목적으로 설립된 법인일 것\n다. 대표자는 공인중개사이어야 하며, 대표자를 제외한 임원 또는 사원(합명회사 또는 합자회사의 무한책임사원을 말한다. 이하 이 조에서 같다)의 3분의 1 이상은 공인중개사일 것\n라. 대표자, 임원 또는 사원 전원 및 분사무소의 책임자(법 제13조제3항에 따라 분사무소를 설치하려는 경우에만 해당한다)가 법 제34조제1항에 따른 실무교육을 받았을 것\n마. 건축물대장에 기재된 건물에 중개사무소를 확보(소유ㆍ전세ㆍ임대차 또는 사용대차 등의 방법에 의하여 사용권을 확보하여야 한다)할 것\n2. 법인이 중개사무소를 개설하려는 경우\n가. 법 제34조제1항의 규정에 따른 실무교육을 받았을 것"},{"법령":"공인중개사법","조문":"제10조 제5호 제2항","원문":"5. 금고 이상의 형의 집행유예를 받고 그 유예기간이 만료된 날부터 2년이 지나지 아니한 자\n②제1항제1호부터 제11호까지의 어느 하나에 해당하는 자는 소속공인중개사 또는 중개보조원이 될 수 없다."}],"선지":[{"번호":1,"판정":"틀림","설명":"이중소속은 금지다. 개업공인중개사등은 다른 개업공인중개사의 소속공인중개사·중개보조원이 될 수 없다(법 제12조 제2항)."},{"번호":2,"판정":"옳음","설명":"피성년후견인은 결격사유다(법 제10조 제1항 제2호)."},{"번호":3,"판정":"옳음","설명":"공인중개사(소속공인중개사 제외)나 법인이 아니면 신청할 수 없다(법 제9조 제2항)."},{"번호":4,"판정":"옳음","설명":"법인의 자본금은 5천만원 이상이어야 한다(영 제13조 제1항 제2호 가목)."},{"번호":5,"판정":"옳음","설명":"집행유예 기간 만료 후 2년이 지나지 않은 자는 결격이고, 결격자는 소속공인중개사·중개보조원도 될 수 없다(법 제10조 제1항 제5호·제2항)."}],"개념":[{"종류":"표","제목":"형벌별 결격 기간","머리":["구분","결격 기간"],"행":[["금고 이상 실형","집행 종료·면제일부터 3년"],["금고 이상 집행유예","유예기간 + 만료일부터 2년"],["선고유예","결격 아님"],["이 법 위반 벌금 300만원 이상","선고 후 3년"],["이 법 위반 벌금 300만원 미만, 다른 법 위반 벌금","결격 아님"],["자격 취소","취소 후 3년"],["등록 취소(사망·해산·결격·등록기준 미달 제외)","취소 후 3년"]]},{"종류":"표","제목":"법인 개설등록 기준(영 제13조)","머리":["항목","기준"],"행":[["형태·자본금","상법상 회사 또는 협동조합(사회적협동조합 제외), 자본금 5천만원 이상"],["업무","법 제14조 업무만 영위할 목적으로 설립"],["대표자","공인중개사"],["임원·사원","대표자 제외 3분의 1 이상 공인중개사"],["실무교육","대표자·임원·사원 전원(분사무소 책임자 포함)"],["사무소","건축물대장 기재 건물에 사용권 확보"]]}],"함정":"개업공인중개사가 다른 곳의 ‘중개보조원’이 되는 것은 자격이 필요 없다고 생각해 맞는 문장으로 보기 쉽다. 이중소속 금지는 소속공인중개사·중개보조원·법인 임원 전부에 걸린다."}},{"i":"S2-2-1-중개사법-06","r":"S2","g":2,"c":2,"n":6,"s":"중개사법","q":"공인중개사법령에 관한 내용으로 옳은 것은? (다툼이 있으면 판례에 따름)","b":null,"bs":"없음","img":[],"ch":["개업공인중개사가 폐업신고 후 3년을 초과하여 다시 중개사무소의 개설등록을 한 경우에도, 폐업신고 전의 위반행위를 이유로 등록취소처분을 할 수 있다.","이 법을 위반하여 200만원의 벌금형을 선고받고 3년이 지나지 아니한 자는 중개사무소의 개설등록을 할 수 없다.","피특정후견인은 중개사무소의 개설등록을 할 수 없다.","휴업기간 중에 있는 개업공인중개사는 다른 개업공인중개사의 소속공인중개사가 될 수 있다.","등기되지 아니한 건물이나 허가를 받지 않고 지은 건물도 중개대상물이 될 수 있다."],"a":[5],"L":"중1-3","o":"변형","x":{"한줄":"미등기 건물이나 무허가 건물도 ‘건축물’로서 법 제3조 제2호의 중개대상물이다.","근거":[{"법령":"공인중개사법","조문":"제3조","원문":"제3조(중개대상물의 범위) 이 법에 의한 중개대상물은 다음 각 호와 같다.\n1. 토지\n2. 건축물 그 밖의 토지의 정착물\n3. 그 밖에 대통령령으로 정하는 재산권 및 물건"},{"법령":"공인중개사법","조문":"제40조 제3항","원문":"③제1항의 경우 재등록 개업공인중개사에 대하여 폐업신고 전의 제38조제1항 각 호, 같은 조 제2항 각 호 및 제39조제1항 각 호의 위반행위에 대한 행정처분을 할 수 있다. 다만, 다음 각 호의 어느 하나에 해당하는 경우는 제외한다.\n1. 폐업신고를 한 날부터 다시 중개사무소의 개설등록을 한 날까지의 기간(이하 제2호에서 \"폐업기간\"이라 한다)이 3년을 초과한 경우\n2. 폐업신고 전의 위반행위에 대한 행정처분이 업무정지에 해당하는 경우로서 폐업기간이 1년을 초과한 경우"},{"법령":"공인중개사법","조문":"제10조 제2호 제11호","원문":"2. 피성년후견인 또는 피한정후견인\n11. 이 법을 위반하여 300만원 이상의 벌금형의 선고를 받고 3년이 지나지 아니한 자"},{"법령":"공인중개사법","조문":"제12조 제2항","원문":"②개업공인중개사등은 다른 개업공인중개사의 소속공인중개사ㆍ중개보조원 또는 개업공인중개사인 법인의 사원ㆍ임원이 될 수 없다."}],"선지":[{"번호":1,"판정":"틀림","설명":"폐업기간이 3년을 초과하면 폐업 전 위반행위에 대한 행정처분을 할 수 없다(법 제40조 제3항 제1호)."},{"번호":2,"판정":"틀림","설명":"결격이 되는 벌금형은 이 법 위반으로 300만원 이상을 선고받고 3년이 지나지 않은 경우다(법 제10조 제1항 제11호). 200만원은 해당하지 않는다."},{"번호":3,"판정":"틀림","설명":"결격은 피성년후견인과 피한정후견인이다. 피특정후견인은 결격이 아니다(법 제10조 제1항 제2호)."},{"번호":4,"판정":"틀림","설명":"휴업 중에도 이중소속이 금지된다. 개업공인중개사는 다른 개업공인중개사의 소속공인중개사·중개보조원이 될 수 없다(법 제12조 제2항)."},{"번호":5,"판정":"옳음","설명":"건축물에는 등기 여부나 허가 여부가 요건이 아니다. 기둥·지붕·주벽을 갖춘 신축 중 건물도 대상이다(법 제3조 제2호)."}],"개념":[{"종류":"표","제목":"폐업 후 재등록 개업공인중개사에 대한 처분(법 제40조)","머리":["구분","내용"],"행":[["지위 승계","폐업신고 후 다시 등록하면 폐업신고 전 개업공인중개사의 지위를 승계"],["처분효과 승계","업무정지·과태료 처분의 효과는 처분일부터 1년간 승계"],["폐업 전 위반행위 처분","재등록자에게 등록취소·업무정지 처분 가능"],["처분 불가","폐업기간 3년 초과, 또는 업무정지 해당 위반행위에서 폐업기간 1년 초과"],["처분 때 고려","폐업기간과 폐업의 사유"]]},{"종류":"표","제목":"이중등록·이중소속 금지","머리":["구분","금지 행위","제재"],"행":[["이중등록","이미 등록한 개업공인중개사가 다시 개설등록","절대적 등록취소, 1년 이하 징역 또는 1천만원 이하 벌금"],["이중소속","다른 개업공인중개사의 소속공인중개사·중개보조원, 법인의 사원·임원이 되는 것","절대적 등록취소(개업공인중개사), 1년 이하 징역 또는 1천만원 이하 벌금"],["휴업 중","금지는 휴업 중에도 그대로 적용","같음"]]}],"함정":"200만원 벌금을 결격으로 보거나 피특정후견인을 결격으로 보기 쉽다. 결격 벌금은 이 법 위반 300만원 이상이고, 후견 결격은 성년후견·한정후견이다."}},{"i":"S2-2-1-중개사법-07","r":"S2","g":2,"c":2,"n":7,"s":"중개사법","q":"공인중개사법령상 중개사무소의 명칭 등에 관한 설명으로 틀린 것은?","b":null,"bs":"없음","img":[],"ch":["개업공인중개사가 옥외광고물을 설치하는 경우 벽면 이용간판, 돌출간판 또는 옥상간판에 등록증에 표기된 성명을 인식할 수 있는 크기로 표기해야 한다.","법인 분사무소에 옥외광고물을 설치하는 경우에는 분사무소설치신고확인서에 기재된 책임자의 성명을 표기해야 한다.","사무소의 명칭에 “공인중개사사무소” 또는 “부동산중개”라는 문자를 사용하지 아니한 개업공인중개사는 100만원 이하의 과태료 부과대상이 된다.","개업공인중개사가 아닌 자가 사무소의 명칭에 “부동산중개”라는 문자를 사용한 경우 100만원 이하의 과태료 부과대상이 된다.","개업공인중개사가 등록관청에 폐업사실을 신고한 경우 지체 없이 사무소의 간판을 철거해야 한다."],"a":[4],"L":"중1-4","o":"변형","x":{"한줄":"개업공인중개사가 아닌 자가 ‘부동산중개’ 명칭을 쓰면 과태료가 아니라 1년 이하 징역 또는 1천만원 이하 벌금이다(법 제49조 제1항 제6호).","근거":[{"법령":"공인중개사법 시행규칙","조문":"제10조의2","원문":"제10조의2(성명의 표기방법 등) 개업공인중개사는 법 제18조제3항에 따라 옥외광고물을 설치하는 경우 「옥외광고물 등의 관리와 옥외광고산업 진흥에 관한 법률 시행령」 제3조에 따른 옥외광고물 중 벽면 이용간판, 돌출간판 또는 옥상간판에 개업공인중개사(법인의 경우에는 대표자, 법인 분사무소의 경우에는 법 제13조제4항에 따른 신고확인서에 기재된 책임자를 말한다)의 성명을 인식할 수 있는 정도의 크기로 표기해야 한다."},{"법령":"공인중개사법","조문":"제18조 제1항 제2항 제3항","원문":"①개업공인중개사는 그 사무소의 명칭에 \"공인중개사사무소\" 또는 \"부동산중개\"라는 문자를 사용하여야 한다.\n②개업공인중개사가 아닌 자는 \"공인중개사사무소\", \"부동산중개\" 또는 이와 유사한 명칭을 사용하여서는 아니된다.\n③개업공인중개사가 「옥외광고물 등의 관리와 옥외광고산업 진흥에 관한 법률」 제2조제1호에 따른 옥외광고물을 설치하는 경우 중개사무소등록증에 표기된 개업공인중개사(법인의 경우에는 대표자, 법인 분사무소의 경우에는 제13조제4항의 규정에 따른 신고확인서에 기재된 책임자를 말한다)의 성명을 표기하여야 한다."},{"법령":"공인중개사법","조문":"제49조 제1항 제6호","원문":"①다음 각 호의 어느 하나에 해당하는 자는 1년 이하의 징역 또는 1천만원 이하의 벌금에 처한다.\n1. 제7조제1항 또는 제2항을 위반하여 다른 사람에게 자기의 성명을 사용하여 중개업무를 하게 하거나 공인중개사자격증을 양도ㆍ대여한 자 또는 다른 사람의 공인중개사자격증을 양수ㆍ대여받은 자\n1의2. 제7조제3항을 위반하여 같은 조 제1항 및 제2항에서 금지한 행위를 알선한 자\n2. 제8조의 규정을 위반하여 공인중개사가 아닌 자로서 공인중개사 또는 이와 유사한 명칭을 사용한 자\n3. 제12조의 규정을 위반하여 이중으로 중개사무소의 개설등록을 하거나 둘 이상의 중개사무소에 소속된 자\n4. 제13조제1항의 규정을 위반하여 둘 이상의 중개사무소를 둔 자\n5. 제13조제2항의 규정을 위반하여 임시 중개시설물을 설치한 자\n5의2. 제15조제3항을 위반하여 중개보조원을 고용한 자\n6. 제18조제2항의 규정을 위반하여 개업공인중개사가 아닌 자로서 \"공인중개사사무소\", \"부동산중개\" 또는 이와 유사한 명칭을 사용한 자\n6의2. 제18조의2제3항을 위반하여 개업공인중개사가 아닌 자로서 중개업을  하기 위하여 중개대상물에 대한 표시ㆍ광고를 한 자\n7. 제19조제1항 또는 제2항을 위반하여 다른 사람에게 자기의 성명 또는 상호를 사용하여 중개업무를 하게 하거나 중개사무소등록증을 다른 사람에게 양도ㆍ대여한 자 또는 다른 사람의 성명ㆍ상호를 사용하여 중개업무를 하거나 중개사무소등록증을 양수ㆍ대여받은 자\n7의2. 제19조제3항을 위반하여 같은 조 제1항 및 제2항에서 금지한 행위를 알선한 자\n8. 제24조제4항의 규정을 위반하여 정보를 공개한 자\n9. 제29조제2항의 규정을 위반하여 업무상 비밀을 누설한 자\n10. 제33조제1항제1호부터 제4호까지의 규정을 위반한 자\n6. 제18조제2항의 규정을 위반하여 개업공인중개사가 아닌 자로서 \"공인중개사사무소\", \"부동산중개\" 또는 이와 유사한 명칭을 사용한 자"},{"법령":"공인중개사법","조문":"제21조의2 제1항","원문":"① 개업공인중개사는 다음 각 호의 어느 하나에 해당하는 경우에는 지체 없이 사무소의 간판을 철거하여야 한다.\n1. 제20조제1항에 따라 등록관청에 중개사무소의 이전사실을 신고한 경우\n2. 제21조제1항에 따라 등록관청에 폐업사실을 신고한 경우\n3. 제38조제1항 또는 제2항에 따라 중개사무소의 개설등록 취소처분을 받은 경우"}],"선지":[{"번호":1,"판정":"옳음","설명":"옥외광고물은 벽면 이용간판·돌출간판·옥상간판에 성명을 인식할 수 있는 크기로 적는다(칙 제10조의2)."},{"번호":2,"판정":"옳음","설명":"법인 분사무소는 신고확인서에 기재된 책임자의 성명을 표기한다(법 제18조 제3항)."},{"번호":3,"판정":"옳음","설명":"명칭 문자 미사용은 100만원 이하 과태료다(법 제51조 제3항 제2호). 등록취소 사유는 아니다."},{"번호":4,"판정":"틀림","설명":"비개업자의 명칭 사용은 형사처벌 대상이다. 1년 이하 징역 또는 1천만원 이하 벌금이다(법 제18조 제2항, 제49조 제1항 제6호)."},{"번호":5,"판정":"옳음","설명":"이전신고·폐업신고를 했거나 등록취소 처분을 받으면 지체 없이 간판을 철거한다(법 제21조의2 제1항)."}],"개념":[{"종류":"표","제목":"명칭·간판·광고 위반 제재","머리":["위반 행위","제재"],"행":[["개업공인중개사가 명칭에 ‘공인중개사사무소’·‘부동산중개’ 미사용","100만원 이하 과태료"],["옥외광고물에 성명 미표기·거짓 표기","100만원 이하 과태료"],["명시사항 위반 표시·광고(법 제18조의2 제1항·제2항)","100만원 이하 과태료"],["부당한 표시·광고(법 제18조의2 제4항)","500만원 이하 과태료"],["비개업자가 ‘공인중개사사무소’·‘부동산중개’ 또는 유사 명칭 사용","1년 이하 징역 또는 1천만원 이하 벌금"],["비개업자가 중개대상물 표시·광고","1년 이하 징역 또는 1천만원 이하 벌금"],["법 제18조 제1항~제3항 위반 간판","등록관청의 철거 명령, 행정대집행"]]},{"종류":"표","제목":"간판 철거 사유(법 제21조의2)","머리":["사유","철거"],"행":[["이전신고","지체 없이 철거"],["폐업신고","지체 없이 철거"],["등록취소 처분","지체 없이 철거"],["휴업신고","철거 사유 아님"]]}],"함정":"과태료와 형사처벌을 바꿔 읽기 쉽다. 개업공인중개사가 명칭을 안 쓴 경우는 과태료지만, 비개업자가 쓴 경우는 형사처벌이다."}},{"i":"S2-2-1-중개사법-08","r":"S2","g":2,"c":2,"n":8,"s":"중개사법","q":"공인중개사법령상 중개업 등에 관한 설명으로 옳은 것은?","b":null,"bs":"없음","img":[],"ch":["소속공인중개사는 중개사무소의 개설등록을 신청할 수 있다.","법인인 개업공인중개사는 '중개업'과 '개업공인중개사를 대상으로 한 중개업의 경영기법 및 경영정보의 제공업무'를 함께 할 수 없다.","법인인 개업공인중개사가 등록관청의 관할 구역 외의지역에 분사무소를 두기 위해서는 등록관청의 허가를 받아야 한다.","소속공인중개사는 등록관청에 신고를 거쳐 천막 그 밖에 이동이 용이한 임시 중개시설물을 설치할 수 있다.","개업공인중개사는 의뢰받은 중개대상물에 대한 표시ㆍ광고에 중개보조원에 관한 사항을 명시해서는 아니된다."],"a":[5],"L":"중1-4","o":"기출","x":{"한줄":"중개대상물 표시·광고에는 중개사무소·개업공인중개사 사항을 명시하되 중개보조원 사항은 명시할 수 없다(법 제18조의2 제1항).","근거":[{"법령":"공인중개사법","조문":"제18조의2 제1항","원문":"① 개업공인중개사가 의뢰받은 중개대상물에 대하여 표시ㆍ광고(「표시ㆍ광고의 공정화에 관한 법률」 제2조에 따른 표시ㆍ광고를 말한다. 이하 같다)를 하려면 중개사무소, 개업공인중개사에 관한 사항으로서 대통령령으로 정하는 사항을 명시하여야 하며, 중개보조원에 관한 사항은 명시해서는 아니 된다."},{"법령":"공인중개사법","조문":"제9조 제2항","원문":"②공인중개사(소속공인중개사는 제외한다) 또는 법인이 아닌 자는 제1항에 따라 중개사무소의 개설등록을 신청할 수 없다."},{"법령":"공인중개사법","조문":"제14조 제1항 제3호","원문":"①법인인 개업공인중개사는 다른 법률에 규정된 경우를 제외하고는 중개업 및 다음 각 호에 규정된 업무와 제2항에 규정된 업무 외에 다른 업무를 함께 할 수 없다.\n1. 상업용 건축물 및 주택의 임대관리 등 부동산의 관리대행\n2. 부동산의 이용ㆍ개발 및 거래에 관한 상담\n3. 개업공인중개사를 대상으로 한 중개업의 경영기법 및 경영정보의 제공\n4. 상업용 건축물 및 주택의 분양대행\n5. 그 밖에 중개업에 부수되는 업무로서 대통령령으로 정하는 업무\n3. 개업공인중개사를 대상으로 한 중개업의 경영기법 및 경영정보의 제공"},{"법령":"공인중개사법","조문":"제13조 제2항 제3항","원문":"②개업공인중개사는 천막 그 밖에 이동이 용이한 임시 중개시설물을 설치하여서는 아니된다.\n③제1항에도 불구하고 법인인 개업공인중개사는 대통령령으로 정하는 기준과 절차에 따라 등록관청에 신고하고 그 관할 구역 외의 지역에 분사무소를 둘 수 있다."}],"선지":[{"번호":1,"판정":"틀림","설명":"개설등록은 소속공인중개사를 제외한 공인중개사와 법인만 신청할 수 있다(법 제9조 제2항)."},{"번호":2,"판정":"틀림","설명":"경영기법·경영정보 제공은 법 제14조 제1항 제3호가 허용하는 법인의 겸업 업무다."},{"번호":3,"판정":"틀림","설명":"분사무소는 허가가 아니라 신고 대상이다(법 제13조 제3항)."},{"번호":4,"판정":"틀림","설명":"임시 중개시설물은 설치할 수 없다. 신고로 허용되는 길도 없다(법 제13조 제2항)."},{"번호":5,"판정":"옳음","설명":"표시·광고에 중개보조원 사항은 명시해서는 아니 된다(법 제18조의2 제1항)."}],"개념":[{"종류":"표","제목":"법인인 개업공인중개사의 겸업 범위(법 제14조)","머리":["업무","내용"],"행":[["관리대행","상업용 건축물·주택의 임대관리 등"],["상담","부동산의 이용·개발 및 거래"],["경영기법 제공","개업공인중개사를 대상으로 한 중개업 경영기법·경영정보"],["분양대행","상업용 건축물·주택"],["부수 업무","도배·이사업체 소개 등 주거이전 용역 알선(영 제17조 제2항)"],["경매·공매 대리","권리분석·취득 알선, 매수신청·입찰신청 대리(개업공인중개사 공통)"]]},{"종류":"표","제목":"사무소 설치 규칙","머리":["항목","내용"],"행":[["사무소 수","등록관청 관할 구역 안 1개"],["임시 중개시설물","설치 금지(천막 등)"],["분사무소","법인만, 신고(허가 아님)"],["위반 시","등록취소 가능, 1년 이하 징역 또는 1천만원 이하 벌금"]]}],"함정":"분사무소를 ‘허가’로, 법인의 겸업을 ‘전면 금지’로 알기 쉽다. 법인은 중개업 외에 법 제14조 업무까지만 가능하다."}},{"i":"S2-2-1-중개사법-09","r":"S2","g":2,"c":2,"n":9,"s":"중개사법","q":"공인중개사법령상 중개사무소의 명칭 및 등록증 등의 게시에 관한 설명으로 틀린 것은? (다툼이 있으면 판례에 따름)","b":null,"bs":"없음","img":[],"ch":["법인인 개업공인중개사의 분사무소에는 분사무소설치신고확인서 원본을 게시해야 한다.","소속공인중개사가 있는 경우 그 소속공인중개사의 공인중개사자격증 원본도 게시해야 한다.","개업공인중개사가 아닌 자가 '부동산중개'라는 명칭을 사용한 경우, 3년 이하의 징역 또는 3천만원 이하의 벌금에 처한다.","무자격자가 자신의 명함에 '부동산뉴스 대표'라는 명칭을 기재하여 사용하였다면 공인중개사와 유사한 명칭을 사용한 것에 해당한다.","공인중개사인 개업공인중개사가 ｢옥외광고물 등의 관리와 옥외광고산업 진흥에 관한 법률｣에 따른 옥외광고물을 설치하는 경우, 중개사무소등록증에 표기된 개업공인중개사의 성명을 표기해야 한다."],"a":[3],"L":"중1-4","o":"기출","x":{"한줄":"비개업자의 ‘부동산중개’ 명칭 사용은 1년 이하 징역 또는 1천만원 이하 벌금이다(법 제49조 제1항 제6호).","근거":[{"법령":"공인중개사법 시행규칙","조문":"제10조","원문":"제10조(중개사무소등록증 등의 게시) 법 제17조에서 \"국토교통부령으로 정하는 사항\"이란 다음 각 호의 사항을 말한다.\n1. 중개사무소등록증 원본(법인인 개업공인중개사의 분사무소의 경우에는 분사무소설치신고확인서 원본을 말한다)\n2. 중개보수ㆍ실비의 요율 및 한도액표\n3. 개업공인중개사 및 소속공인중개사의 공인중개사자격증 원본(해당되는 자가 있는 경우로 한정한다)\n4. 보증의 설정을 증명할 수 있는 서류\n5. 「부가가치세법 시행령」 제11조에 따른 사업자등록증"},{"법령":"공인중개사법","조문":"제49조 제1항 제6호","원문":"①다음 각 호의 어느 하나에 해당하는 자는 1년 이하의 징역 또는 1천만원 이하의 벌금에 처한다.\n1. 제7조제1항 또는 제2항을 위반하여 다른 사람에게 자기의 성명을 사용하여 중개업무를 하게 하거나 공인중개사자격증을 양도ㆍ대여한 자 또는 다른 사람의 공인중개사자격증을 양수ㆍ대여받은 자\n1의2. 제7조제3항을 위반하여 같은 조 제1항 및 제2항에서 금지한 행위를 알선한 자\n2. 제8조의 규정을 위반하여 공인중개사가 아닌 자로서 공인중개사 또는 이와 유사한 명칭을 사용한 자\n3. 제12조의 규정을 위반하여 이중으로 중개사무소의 개설등록을 하거나 둘 이상의 중개사무소에 소속된 자\n4. 제13조제1항의 규정을 위반하여 둘 이상의 중개사무소를 둔 자\n5. 제13조제2항의 규정을 위반하여 임시 중개시설물을 설치한 자\n5의2. 제15조제3항을 위반하여 중개보조원을 고용한 자\n6. 제18조제2항의 규정을 위반하여 개업공인중개사가 아닌 자로서 \"공인중개사사무소\", \"부동산중개\" 또는 이와 유사한 명칭을 사용한 자\n6의2. 제18조의2제3항을 위반하여 개업공인중개사가 아닌 자로서 중개업을  하기 위하여 중개대상물에 대한 표시ㆍ광고를 한 자\n7. 제19조제1항 또는 제2항을 위반하여 다른 사람에게 자기의 성명 또는 상호를 사용하여 중개업무를 하게 하거나 중개사무소등록증을 다른 사람에게 양도ㆍ대여한 자 또는 다른 사람의 성명ㆍ상호를 사용하여 중개업무를 하거나 중개사무소등록증을 양수ㆍ대여받은 자\n7의2. 제19조제3항을 위반하여 같은 조 제1항 및 제2항에서 금지한 행위를 알선한 자\n8. 제24조제4항의 규정을 위반하여 정보를 공개한 자\n9. 제29조제2항의 규정을 위반하여 업무상 비밀을 누설한 자\n10. 제33조제1항제1호부터 제4호까지의 규정을 위반한 자\n6. 제18조제2항의 규정을 위반하여 개업공인중개사가 아닌 자로서 \"공인중개사사무소\", \"부동산중개\" 또는 이와 유사한 명칭을 사용한 자"},{"법령":"공인중개사법","조문":"제18조 제3항","원문":"③개업공인중개사가 「옥외광고물 등의 관리와 옥외광고산업 진흥에 관한 법률」 제2조제1호에 따른 옥외광고물을 설치하는 경우 중개사무소등록증에 표기된 개업공인중개사(법인의 경우에는 대표자, 법인 분사무소의 경우에는 제13조제4항의 규정에 따른 신고확인서에 기재된 책임자를 말한다)의 성명을 표기하여야 한다."}],"선지":[{"번호":1,"판정":"옳음","설명":"분사무소는 등록증 대신 신고확인서 원본을 게시한다(칙 제10조 제1호)."},{"번호":2,"판정":"옳음","설명":"개업공인중개사와 소속공인중개사의 자격증 원본을 해당자가 있으면 게시한다(칙 제10조 제3호)."},{"번호":3,"판정":"틀림","설명":"벌칙은 1년 이하 징역 또는 1천만원 이하 벌금이다. 3년 이하·3천만원 이하는 법 제48조의 벌칙이다."},{"번호":4,"판정":"옳음","설명":"명함의 ‘부동산뉴스 대표’는 공인중개사와 유사한 명칭 사용에 해당한다(판례)."},{"번호":5,"판정":"옳음","설명":"옥외광고물에는 등록증에 표기된 성명을 표기한다(법 제18조 제3항)."}],"개념":[{"종류":"표","제목":"사무소 안 게시 사항(칙 제10조)","머리":["게시물","비고"],"행":[["중개사무소등록증 원본","분사무소는 신고확인서 원본"],["중개보수·실비 요율 및 한도액표",""],["개업공인중개사·소속공인중개사 자격증 원본","해당자가 있는 경우"],["보증 설정 증명서류",""],["사업자등록증","부가가치세법 시행령 제11조"]]},{"종류":"표","제목":"게시 대상이 아닌 것","머리":["서류","게시 여부"],"행":[["실무교육 수료확인증","아님"],["고용신고서","아님"],["중개보조원 관련 서류","아님"]]}],"함정":"형량의 구간을 섞기 쉽다. 제48조(3년·3천만원)는 무등록 중개업 등, 제49조(1년·1천만원)는 명칭 사용·이중등록·금지행위 일부다."}},{"i":"S2-2-1-중개사법-10","r":"S2","g":2,"c":2,"n":10,"s":"중개사법","q":"공인중개사법령상 휴업과 폐업에 관한 설명으로 틀린 것은?","b":null,"bs":"없음","img":[],"ch":["3개월을 초과하여 휴업하려는 개업공인중개사는 신고서에 중개사무소등록증을 첨부하여 등록관청에 미리 신고해야 한다.","임신 또는 출산을 이유로 하는 휴업은 6개월을 초과할 수 있다.","휴업한 중개업을 재개하려는 경우에는 신고서에 중개사무소등록증을 첨부해야 한다.","관할 세무서장이 「부가가치세법 시행령」에 따라 휴업·폐업 신고서를 받아 등록관청에 송부한 경우에는 등록관청에 신고서가 제출된 것으로 본다.","분사무소를 둔 법인인 개업공인중개사는 휴업·폐업 신고를 분사무소별로 할 수 있다."],"a":[3],"L":"중1-4","o":"변형","x":{"한줄":"등록증(분사무소는 신고확인서)은 휴업·폐업 신고에만 첨부하고 재개·기간변경 신고에는 첨부하지 않는다(영 제18조 제1항).","근거":[{"법령":"공인중개사법 시행령","조문":"제18조 제1항 제2항 제4항 제6항","원문":"① 개업공인중개사는 법 제21조제1항에 따라 다음 각 호의 어느 하나에 해당하는 경우에는 국토교통부령으로 정하는 신고서에 중개사무소등록증을 첨부(제1호 및 제2호의 경우만 해당한다)하여 등록관청에 미리 신고(제3호 및 제4호에 해당하여 신고하는 경우에는 전자문서에 의한 신고를 포함한다)해야 한다.\n1. 3개월을 초과하여 휴업(법 제9조에 따른 중개사무소 개설등록 후 업무를 개시하지 않는 경우를 포함한다. 이하 이 조에서 같다)하려는 경우\n2. 폐업하려는 경우\n3. 3개월을 초과하여 휴업한 부동산중개업을 재개하려는 경우\n4. 신고한 휴업기간을 변경하려는 경우\n② 법인인 개업공인중개사는 제1항에도 불구하고 법 제13조제3항에 따라 분사무소를 둔 경우에는 제1항에 따른 신고를 분사무소별로 할 수 있다. 이 경우 법 제13조제4항에 따른 신고확인서를 첨부(제1항제1호 및 제2호의 경우만 해당한다)해야 한다.\n④ 관할 세무서장이 「부가가치세법 시행령」 제13조제5항에 따라 제1항의 신고서를 받아 해당 등록관청에 송부한 경우에는 제1항의 신고서가 제출된 것으로 본다.\n⑥법 제21조제2항에서 \"대통령령으로 정하는 부득이한 사유\"란 다음 각 호의 어느 하나에 해당하는 사유를 말한다.\n1. 질병으로 인한 요양\n2. 징집으로 인한 입영\n3. 취학\n4. 임신 또는 출산\n5. 그 밖에 제1호부터 제4호까지의 규정에 준하는 부득이한 사유로서 국토교통부장관이 정하여 고시하는 사유"},{"법령":"공인중개사법","조문":"제21조 제2항","원문":"②제1항에 따른 휴업은 6개월을 초과할 수 없다. 다만, 질병으로 인한 요양등 대통령령으로 정하는 부득이한 사유가 있는 경우에는 그러하지 아니하다."}],"선지":[{"번호":1,"판정":"옳음","설명":"3개월 초과 휴업은 등록증을 첨부해 미리 신고한다(영 제18조 제1항 제1호)."},{"번호":2,"판정":"옳음","설명":"질병 요양, 입영, 취학, 임신·출산 등 부득이한 사유는 6개월 초과 휴업이 가능하다(법 제21조 제2항, 영 제18조 제6항)."},{"번호":3,"판정":"틀림","설명":"등록증 첨부는 휴업(제1호)·폐업(제2호) 신고에만 해당한다. 재개신고(제3호)에는 등록증을 첨부하지 않고 전자문서로도 할 수 있다(영 제18조 제1항)."},{"번호":4,"판정":"옳음","설명":"세무서장이 송부한 신고서는 제출된 것으로 본다(영 제18조 제4항)."},{"번호":5,"판정":"옳음","설명":"분사무소를 둔 법인은 분사무소별로 신고할 수 있고, 휴업·폐업 때는 신고확인서를 첨부한다(영 제18조 제2항)."}],"개념":[{"종류":"흐름","제목":"휴업·폐업 신고 절차","단계":[{"이름":"신고 대상 판단","설명":"3개월 초과 휴업(개설등록 후 업무 미개시 포함), 폐업, 재개, 휴업기간 변경. 3개월 이하 휴업은 신고 의무 없음"},{"이름":"미리 신고","설명":"등록관청에 신고서 제출, 휴업·폐업은 등록증(분사무소는 신고확인서) 첨부"},{"이름":"재개·변경","설명":"전자문서 신고 가능, 등록증 첨부 없음. 등록관청은 반납받은 등록증을 즉시 반환"},{"이름":"간판 철거","설명":"폐업신고 후 지체 없이 간판 철거. 휴업은 철거 사유 아님"},{"이름":"6개월 한도","설명":"휴업은 6개월 초과 불가. 질병 요양·입영·취학·임신·출산 등은 예외"}]},{"종류":"표","제목":"휴업·폐업 신고 비교","머리":["구분","등록증 첨부","전자문서 신고 명문 규정"],"행":[["3개월 초과 휴업","첨부","없음"],["폐업","첨부","없음"],["재개","없음","있음"],["휴업기간 변경","없음","있음"]]}],"함정":"재개신고에도 등록증을 내야 한다고 알기 쉽다. 등록증 첨부는 휴업·폐업 신고에만 해당하고, 재개신고를 받은 등록관청은 이미 반납받은 등록증을 즉시 돌려준다."}},{"i":"S2-2-1-중개사법-11","r":"S2","g":2,"c":2,"n":11,"s":"중개사법","q":"공인중개사법령상 중개사무소의 설치 등에 관한 설명으로 틀린 것은?","b":null,"bs":"없음","img":[],"ch":["법인인 개업공인중개사가 분사무소를 설치하는 경우 분사무소 책임자는 신고일 전 1년 이내에 시·도지사가 실시하는 실무교육을 받아야 한다.","분사무소는 주된 사무소의 소재지가 속한 시·군·구를 제외한 시·군·구별로 설치하되, 시·군·구별로 1개소를 초과할 수 없다.","준공검사를 받았으나 건축물대장에 아직 기재되지 않은 건물도 중개사무소로 확보할 수 있다.","다른 개업공인중개사와 중개사무소를 공동으로 사용하려는 개업공인중개사는 등록 또는 이전신고 때 그 사무소를 사용할 권리가 있는 개업공인중개사의 승낙서를 첨부해야 한다.","분사무소 설치신고를 받은 등록관청은 그 신고내용이 적합하더라도 분사무소 설치예정지역을 관할하는 시장·군수·구청장에게 통보할 필요는 없다."],"a":[5],"L":"중1-4","o":"변형","x":{"한줄":"등록관청은 신고확인서를 교부하고 지체 없이 분사무소 설치예정지역 관할 시장·군수·구청장에게 통보해야 한다(법 제13조 제4항).","근거":[{"법령":"공인중개사법","조문":"제13조 제4항","원문":"④제3항에 따라 분사무소 설치신고를 받은 등록관청은 그 신고내용이 적합한 경우에는 국토교통부령으로 정하는 신고확인서를 교부하고 지체 없이 그 분사무소설치예정지역을 관할하는 시장ㆍ군수 또는 구청장에게 이를 통보하여야 한다."},{"법령":"공인중개사법 시행령","조문":"제15조 제1항","원문":"①법 제13조제3항에 따른 분사무소는 주된 사무소의 소재지가 속한 시(구가 설치되지 아니한 시와 특별자치도의 행정시를 말한다. 이하 이 조에서 같다)ㆍ군ㆍ구를 제외한 시ㆍ군ㆍ구별로 설치하되, 시ㆍ군ㆍ구별로 1개소를 초과할 수 없다."},{"법령":"공인중개사법 시행령","조문":"제13조 제1항 제1호 나목","원문":"①법 제9조제3항에 따른 중개사무소 개설등록의 기준은 다음 각 호와 같다. 다만, 다른 법률의 규정에 따라 부동산중개업을 할 수 있는 경우에는 다음 각 호의 기준을 적용하지 아니한다.\n1. 공인중개사가 중개사무소를 개설하고자 하는 경우\n가. 법 제34조제1항의 규정에 따른 실무교육을 받았을 것\n나. 건축물대장(「건축법」 제20조제5항에 따른 가설건축물대장은 제외한다. 이하 같다)에 기재된 건물(준공검사, 준공인가, 사용승인, 사용검사 등을 받은 건물로서 건축물대장에 기재되기 전의 건물을 포함한다. 이하 같다)에 중개사무소를 확보(소유ㆍ전세ㆍ임대차 또는 사용대차 등의 방법에 의하여 사용권을 확보하여야 한다)할 것\n2. 법인이 중개사무소를 개설하려는 경우\n가. 「상법」상 회사 또는 「협동조합 기본법」 제2조제1호에 따른 협동조합(같은 조 제3호에 따른 사회적협동조합은 제외한다)으로서 자본금이 5천만원 이상일 것\n나. 법 제14조에 규정된 업무만을 영위할 목적으로 설립된 법인일 것\n다. 대표자는 공인중개사이어야 하며, 대표자를 제외한 임원 또는 사원(합명회사 또는 합자회사의 무한책임사원을 말한다. 이하 이 조에서 같다)의 3분의 1 이상은 공인중개사일 것\n라. 대표자, 임원 또는 사원 전원 및 분사무소의 책임자(법 제13조제3항에 따라 분사무소를 설치하려는 경우에만 해당한다)가 법 제34조제1항에 따른 실무교육을 받았을 것\n마. 건축물대장에 기재된 건물에 중개사무소를 확보(소유ㆍ전세ㆍ임대차 또는 사용대차 등의 방법에 의하여 사용권을 확보하여야 한다)할 것\n1. 공인중개사가 중개사무소를 개설하고자 하는 경우\n나. 건축물대장(「건축법」 제20조제5항에 따른 가설건축물대장은 제외한다. 이하 같다)에 기재된 건물(준공검사, 준공인가, 사용승인, 사용검사 등을 받은 건물로서 건축물대장에 기재되기 전의 건물을 포함한다. 이하 같다)에 중개사무소를 확보(소유ㆍ전세ㆍ임대차 또는 사용대차 등의 방법에 의하여 사용권을 확보하여야 한다)할 것"},{"법령":"공인중개사법 시행령","조문":"제16조 제1항","원문":"①법 제13조제6항 본문에 따라 중개사무소를 공동으로 사용하려는 개업공인중개사는 법 제9조에 따른 중개사무소의 개설등록 또는 법 제20조에 따른 중개사무소의 이전신고를 하는 때에 그 중개사무소를 사용할 권리가 있는 다른 개업공인중개사의 승낙서를 첨부하여야 한다."}],"선지":[{"번호":1,"판정":"옳음","설명":"분사무소 책임자도 신고일 전 1년 이내 실무교육 대상이다(법 제34조 제1항, 영 제13조 제1항 제2호 라목)."},{"번호":2,"판정":"옳음","설명":"주된 사무소가 속한 시·군·구는 제외하고 시·군·구마다 1개소까지 둔다(영 제15조 제1항)."},{"번호":3,"판정":"옳음","설명":"사용승인·준공검사 등을 받은 건물로서 대장 기재 전의 건물도 확보 대상이다(영 제13조 제1항 제1호 나목). 이 경우 대장 기재가 지연되는 사유를 적은 서류를 함께 낸다."},{"번호":4,"판정":"옳음","설명":"공동사용은 등록 또는 이전신고 때 승낙서를 첨부해서 한다(영 제16조 제1항)."},{"번호":5,"판정":"틀림","설명":"등록관청은 지체 없이 설치예정지역 관할 시장·군수·구청장에게 통보해야 한다(법 제13조 제4항)."}],"개념":[{"종류":"흐름","제목":"분사무소 설치 절차","단계":[{"이름":"책임자 준비","설명":"공인중개사를 책임자로 둔다(다른 법률로 중개업을 하는 법인은 예외). 신고일 전 1년 이내 실무교육"},{"이름":"신고","설명":"주된 사무소 소재지 등록관청에 분사무소설치신고서 제출. 보증 설정 증명서류·사무소 확보 서류 첨부"},{"이름":"자격 확인","설명":"등록관청이 자격증 발급 시·도지사에게 책임자의 공인중개사 자격 확인 요청"},{"이름":"교부·통보","설명":"신고확인서 교부, 지체 없이 설치예정지역 시장·군수·구청장에게 통보"},{"이름":"협회 통보","설명":"매월 모아 다음 달 10일까지 한국공인중개사협회에 통보"}]},{"종류":"표","제목":"사무소 확보 요건","머리":["항목","기준"],"행":[["대상 건물","건축물대장에 기재된 건물(가설건축물대장 제외). 사용승인 등을 받고 대장 기재 전인 건물 포함"],["사용권","소유·전세·임대차·사용대차 등 사용권 확보. 소유권은 필요 없음"],["면적","기준 없음"],["공동사용","사용권 있는 개업공인중개사의 승낙서. 업무정지 중인 자는 새로 공동사용 불가"]]}],"함정":"신고의 주체는 개업공인중개사지만 통보는 등록관청의 의무다. ‘통보는 임의’라는 선지는 법 제13조 제4항의 ‘통보하여야 한다’에 어긋난다."}},{"i":"S2-2-1-중개사법-12","r":"S2","g":2,"c":2,"n":12,"s":"중개사법","q":"공인중개사법령상 개업공인중개사의 중개사무소 이전신고 등에 관한 설명으로 틀린 것은?","b":null,"bs":"없음","img":[],"ch":["개업공인중개사가 중개사무소를 등록관청의 관할 지역 외의 지역으로 이전한 경우에는 이전 후의 중개사무소를 관할하는 시장ㆍ군수 또는 구청장에게 신고하여야 한다.","개업공인중개사가 등록관청에 중개사무소의 이전사실을 신고한 경우에는 지체 없이 사무소의 간판을 철거하여야 한다.","분사무소의 이전신고를 하려는 경우에는 주된 사무소의 소재지를 관할하는 등록관청에 중개사무소이전신고서를 제출해야 한다.","업무정지 기간 중에 있는 개업공인중개사는 중개사무소의 이전신고를 하는 방법으로 다른 개업공인중개사의 중개사무소를 공동으로 사용할 수 없다.","공인중개사인 개업공인중개사가 중개사무소이전신고서를 제출할 때 중개사무소등록증을 첨부하지 않아도 된다."],"a":[5],"L":"중1-4","o":"기출","x":{"한줄":"이전신고서에는 중개사무소등록증(분사무소는 신고확인서)과 사무소 확보 서류를 첨부한다(칙 제11조 제1항).","근거":[{"법령":"공인중개사법","조문":"제20조 제1항 제3항","원문":"①개업공인중개사는 중개사무소를 이전한 때에는 이전한 날부터 10일 이내에 국토교통부령으로 정하는 바에 따라 등록관청에 이전사실을 신고하여야 한다. 다만, 중개사무소를 등록관청의 관할 지역 외의 지역으로 이전한 경우에는 이전 후의 중개사무소를 관할하는 시장ㆍ군수 또는 구청장(이하 이 조에서 \"이전후 등록관청\"이라 한다)에게 신고하여야 한다.\n③제1항 단서에 따른 신고 전에 발생한 사유로 인한 개업공인중개사에 대한 행정처분은 이전후 등록관청이 이를 행한다."},{"법령":"공인중개사법 시행규칙","조문":"제11조 제1항 제2항 제3항","원문":"①법 제20조제1항에 따라 중개사무소의 이전신고를 하려는 자는 별지 제12호서식의 중개사무소이전신고서에 다음 각 호의 서류를 첨부하여 등록관청(분사무소의 경우에는 주된 사무소의 소재지를 관할하는 등록관청을 말한다. 이하 이 조에서 같다)에 제출해야 한다.\n1. 중개사무소등록증(분사무소의 경우에는 분사무소설치신고확인서를 말한다)\n2. 건축물대장에 기재된 건물에 중개사무소를 확보(소유ㆍ전세ㆍ임대차 또는 사용대차 등의 방법에 의하여 사용권을 확보하여야 한다)하였음을 증명하는 서류. 다만, 건축물대장에 기재되지 아니한 건물에 중개사무소를 확보하였을 경우에는 건축물대장 기재가 지연되는 사유를 적은 서류도 함께 내야 한다.\n②제1항에 따라 중개사무소의 이전신고를 받은 등록관청은 그 내용이 적합한 경우에는 중개사무소등록증 또는 분사무소설치신고확인서를 재교부해야 한다. 다만, 개업공인중개사가 등록관청의 관할지역 내로 이전한 경우에는 등록관청은 중개사무소등록증 또는 분사무소설치신고확인서에 변경사항을 적어 교부할 수 있다.\n③등록관청은 분사무소의 이전신고를 받은 때에는 지체 없이 그 분사무소의 이전 전 및 이전 후의 소재지를 관할하는 시장ㆍ군수 또는 구청장에게 이를 통보하여야 한다."},{"법령":"공인중개사법 시행령","조문":"제16조 제2항","원문":"② 법 제39조에 따른 업무의 정지기간 중에 있는 개업공인중개사는 법 제13조제6항 단서에 따라 다음 각 호의 어느 하나에 해당하는 방법으로 다른 개업공인중개사와 중개사무소를 공동으로 사용할 수 없다.\n1. 법 제39조에 따른 업무의 정지기간 중에 있는 개업공인중개사가 다른 개업공인중개사에게 중개사무소의 공동사용을 위하여 제1항에 따른 승낙서를 주는 방법. 다만, 법 제39조에 따른 업무의 정지기간 중에 있는 개업공인중개사가 영업정지 처분을 받기 전부터 중개사무소를 공동사용 중인 다른 개업공인중개사는 제외한다.\n2. 법 제39조에 따른 업무의 정지기간 중에 있는 개업공인중개사가 다른 개업공인중개사의 중개사무소를 공동으로 사용하기 위하여 중개사무소의 이전신고를 하는 방법"}],"선지":[{"번호":1,"판정":"옳음","설명":"관할 밖으로 옮기면 이전 후 등록관청에 신고한다(법 제20조 제1항 단서)."},{"번호":2,"판정":"옳음","설명":"이전신고를 했으면 지체 없이 간판을 철거한다(법 제21조의2 제1항 제1호)."},{"번호":3,"판정":"옳음","설명":"분사무소 이전신고는 주된 사무소 소재지 등록관청에 한다(칙 제11조 제1항)."},{"번호":4,"판정":"옳음","설명":"업무정지 중인 개업공인중개사는 이전신고로 다른 개업공인중개사의 사무소를 공동사용할 수 없다(영 제16조 제2항 제2호)."},{"번호":5,"판정":"틀림","설명":"공인중개사인 개업공인중개사든 법인이든 등록증(분사무소는 신고확인서)을 첨부한다(칙 제11조 제1항 제1호)."}],"개념":[{"종류":"표","제목":"중개사무소 이전신고 비교","머리":["구분","신고할 곳","첨부 서류","등록증 처리"],"행":[["관할 안 이전","종전 등록관청","등록증 + 사무소 확보 서류","재교부 또는 변경사항 적어 교부"],["관할 밖 이전","이전 후 등록관청","등록증 + 사무소 확보 서류","재교부, 종전 등록관청이 관련 서류 송부"],["분사무소 이전","주된 사무소 등록관청","신고확인서 + 사무소 확보 서류","신고확인서 재교부, 이전 전·후 소재지 시장·군수·구청장에게 통보"]]},{"종류":"표","제목":"이전신고 기타","머리":["항목","내용"],"행":[["기한","이전한 날부터 10일 이내"],["미신고","100만원 이하 과태료"],["행정처분","신고 전에 생긴 사유의 처분은 이전 후 등록관청"],["송부 서류","등록대장, 개설등록 신청서류, 최근 1년간 행정처분 관련 서류"]]}],"함정":"공인중개사 개인사무소는 서류가 간단할 것이라 짐작하기 쉽다. 개인·법인 구별 없이 등록증이 필수 첨부 서류다."}},{"i":"S2-2-1-중개사법-13","r":"S2","g":2,"c":2,"n":13,"s":"중개사법","q":"공인중개사법령상 개업공인중개사의 고용인에 관한 설명으로 틀린 것은?","b":null,"bs":"없음","img":[],"ch":["개업공인중개사는 중개보조원과 고용관계가 종료된 경우 그 종료일부터 10일 이내에 등록관청에 신고해야 한다.","소속공인중개사의 고용신고를 받은 등록관청은 공인중개사 자격증을 발급한 시ㆍ도지사에게 그 소속공인중개사의 공인중개사 자격 확인을 요청해야 한다.","중개보조원뿐만 아니라 소속공인중개사의 업무상 행위는 그를 고용한 개업공인중개사의 행위로 본다.","개업공인중개사는 중개보조원을 고용한 경우, 등록관청에 신고한 후 업무개시 전까지 등록관청이 실시하는 직무교육을 받도록 해야 한다.","중개보조원의 고용신고를 받은 등록관청은 그 사실을 한국공인중개사협회에 통보해야 한다."],"a":[4],"L":"중1-5","o":"기출","x":{"한줄":"교육을 받게 한 뒤에 업무개시 전까지 신고하는 순서이므로, 신고 후 교육을 받게 한다는 문장이 틀리다(칙 제8조 제1항).","근거":[{"법령":"공인중개사법 시행규칙","조문":"제8조 제1항 제2항 제4항","원문":"①개업공인중개사는 소속공인중개사 또는 중개보조원을 고용한 경우에는 법 제34조제2항 또는 제3항에 따른 교육을 받도록 한 후 법 제15조제1항에 따라 업무개시 전까지 등록관청에 신고(전자문서에 의한 신고를 포함한다)하여야 한다.\n② 제1항에 따른 고용 신고를 받은 등록관청은 법 제5조제2항에 따라 공인중개사 자격증을 발급한 시ㆍ도지사에게 그 소속공인중개사의 공인중개사 자격 확인을 요청하여야 한다.\n④ 개업공인중개사는 소속공인중개사 또는 중개보조원과의 고용관계가 종료된 때에는 법 제15조제1항에 따라 고용관계가 종료된 날부터 10일 이내에 등록관청에 신고하여야 한다."},{"법령":"공인중개사법","조문":"제15조 제2항","원문":"②소속공인중개사 또는 중개보조원의 업무상 행위는 그를 고용한 개업공인중개사의 행위로 본다."},{"법령":"공인중개사법 시행령","조문":"제14조 제3호","원문":"3. 법 제15조제1항에 따라 소속공인중개사 또는 중개보조원의 고용이나 고용관계 종료의 신고를 받은 때"}],"선지":[{"번호":1,"판정":"옳음","설명":"고용관계 종료 신고는 종료한 날부터 10일 이내다(칙 제8조 제4항)."},{"번호":2,"판정":"옳음","설명":"소속공인중개사 고용신고를 받으면 자격증 발급 시·도지사에게 자격 확인을 요청한다(칙 제8조 제2항). 중개보조원에는 자격 확인이 없다."},{"번호":3,"판정":"옳음","설명":"소속공인중개사·중개보조원의 업무상 행위는 개업공인중개사의 행위로 본다(법 제15조 제2항)."},{"번호":4,"판정":"틀림","설명":"교육을 받도록 한 후 업무개시 전까지 신고한다(칙 제8조 제1항). 중개보조원의 직무교육은 시·도지사 또는 등록관청이 실시한다(법 제34조 제3항)."},{"번호":5,"판정":"옳음","설명":"고용·고용관계 종료 신고를 받으면 한국공인중개사협회에 통보한다(영 제14조 제3호, 칙 제6조)."}],"개념":[{"종류":"표","제목":"고용 신고 정리","머리":["항목","소속공인중개사","중개보조원"],"행":[["고용 전 교육","실무교육(시·도지사), 신고일 전 1년 이내","직무교육(시·도지사 또는 등록관청), 신고일 전 1년 이내"],["신고 시기","교육 후 업무개시 전","교육 후 업무개시 전"],["종료 신고","종료일부터 10일 이내","종료일부터 10일 이내"],["자격 확인","자격증 발급 시·도지사에 요청","없음"],["인장 등록","의무 있음","의무 없음"],["수 제한","없음","개업공인중개사와 소속공인중개사 합한 수의 5배 이하"],["외국인","고용 가능, 결격 아님 증명서류 첨부","고용 가능, 결격 아님 증명서류 첨부"]]},{"종류":"표","제목":"고용인 위반에 대한 책임","머리":["구분","내용"],"행":[["업무상 행위","고용한 개업공인중개사의 행위로 본다(추정이 아님)"],["벌칙 위반(제48·49조)","행위자 처벌 + 개업공인중개사도 벌금형, 상당한 주의·감독을 했으면 제외"],["손해배상","고용인과 개업공인중개사 모두 책임, 배상 후 구상 가능"],["중개보조원 고지의무 위반","본인과 소속 개업공인중개사에 500만원 이하 과태료(주의·감독 다했으면 제외)"]]}],"함정":"신고와 교육의 선후를 거꾸로 읽기 쉽다. 교육이 먼저이고 신고가 그다음이며, 업무개시 후 사후 신고는 인정되지 않는다.","개정":"선지 5의 협회 명칭은 2026.2.27 개정 법 제41조(한국공인중개사협회)와 영 제14조(2026.8.18 개정)에 맞춰 ‘한국공인중개사협회’로 고쳤다. 정오는 달라지지 않는다."}},{"i":"S2-2-1-중개사법-14","r":"S2","g":2,"c":2,"n":14,"s":"중개사법","q":"공인중개사법령상 전속중개계약서 서식에는 기재되어 있으나 일반중개계약서 서식에는 기재되어 있지 않은 사항은?","b":null,"bs":"없음","img":[],"ch":["중개의뢰인이 중개대상물의 거래에 관한 중개를 다른 개업공인중개사에게도 의뢰할 수 있다는 내용","개업공인중개사가 계약체결 후 2주일에 1회 이상 중개업무 처리상황을 문서로 통지해야 한다는 내용","계약의 유효기간은 3개월을 원칙으로 하되 당사자가 합의하여 별도로 정할 수 있다는 내용","중개보수 또는 실비를 과다하게 수령한 경우 차액을 환급해야 한다는 내용","중개대상물의 확인·설명을 소홀히 하여 재산상 피해를 발생하게 한 경우 손해액을 배상해야 한다는 내용"],"a":[2],"L":"중1-6","o":"변형","x":{"한줄":"처리상황 문서 통지(2주일에 1회 이상)는 전속중개계약서에만 있고 일반중개계약서에는 없다.","근거":[{"법령":"공인중개사법 시행규칙","조문":"별지 제15호서식(전속중개계약서) 1. 을의 의무사항","원문":"① 을은 갑에게 계약체결 후 2주일에 1회 이상 중개업무 처리상황을 문서로 통지하여야 한다.\n② 을은 이 전속중개계약 체결 후 7일 이내 「공인중개사법」(이하 \"법\"이라 한다) 제24조에 따른 부동산거래정보망 또는 일간신문에 중개대상물에 관한 정보를 공개하여야 하며, 중개대상물을 공개한 때에는 지체 없이 갑에게 그 내용을 문서로 통지하여야 한다. 다만, 갑이 비공개를 요청한 경우에는 이를 공개하지 아니한다."},{"법령":"공인중개사법 시행규칙","조문":"별지 제14호서식(일반중개계약서) 2. 갑의 권리ㆍ의무 사항","원문":"1) 갑은 이 계약에도 불구하고 중개대상물의 거래에 관한 중개를 다른 개업공인중개사에게도 의뢰할 수 있다.\n2) 갑은 을이 「공인중개사법」(이하 \"법\"이라 한다) 제25조에 따른 중개대상물의 확인ㆍ설명의무를 이행하는데 협조하여야 한다."},{"법령":"공인중개사법 시행령","조문":"제20조 제1항","원문":"①법 제23조제1항의 규정에 따른 전속중개계약의 유효기간은 3월로 한다. 다만, 당사자간에 다른 약정이 있는 경우에는 그 약정에 따른다."}],"선지":[{"번호":1,"판정":"-","설명":"일반중개계약서에만 있다. 전속중개계약서에는 다른 개업공인중개사에게 의뢰하면 위약금을 문다는 내용이 들어간다."},{"번호":2,"판정":"-","설명":"전속중개계약서 ‘을의 의무사항’ ①에만 있다. 일반중개계약에는 처리상황 통지 의무가 없다."},{"번호":3,"판정":"-","설명":"두 서식에 모두 있다(‘3. 유효기간’)."},{"번호":4,"판정":"-","설명":"두 서식에 모두 있다(‘5. 을의 손해배상 책임’ 1))."},{"번호":5,"판정":"-","설명":"두 서식에 모두 있다(‘5. 을의 손해배상 책임’ 2))."}],"개념":[{"종류":"비교","제목":"일반중개계약과 전속중개계약","왼쪽":{"이름":"일반중개계약","항목":["서식 별지 제14호, 표준서식은 사용 권장","말로도 체결 가능, 의뢰인이 서면 작성을 요청할 수 있음","같은 물건을 여러 개업공인중개사에게 의뢰 가능","처리상황 통지·정보공개·계약서 보존 의무 없음","위약금 규정 없음"]},"오른쪽":{"이름":"전속중개계약","항목":["서식 별지 제15호, 이 서식으로만 체결","유효기간 3개월(별도 약정 우선)","의뢰인은 한 사람의 개업공인중개사에게만 의뢰","계약체결 후 7일 이내 정보 공개 + 2주일에 1회 이상 문서 통지, 계약서 3년 보존","유효기간 내 다른 중개사에 의뢰하거나 직접 거래하면 중개보수 상당 위약금(스스로 찾은 상대방은 중개보수 50% 범위의 소요 비용)"]}},{"종류":"표","제목":"전속중개계약 정보공개","머리":["항목","내용"],"행":[["공개 매체","부동산거래정보망 또는 일간신문"],["기한","계약체결 후 7일 이내, 공개하면 지체 없이 의뢰인에게 문서 통지"],["비공개 요청","의뢰인이 요청하면 공개 금지"],["권리관계","공개하되 권리자의 주소·성명 등 인적 사항은 공개 금지"],["공시지가","임대차는 공개하지 않을 수 있음"],["위반","정보를 공개하지 않거나 비공개 요청에도 공개하면 등록취소 가능"]]}],"함정":"일반중개계약에도 정보공개와 통지 의무가 있다고 생각하기 쉽다. 이 의무들은 전속중개계약에만 붙고, 손해배상 책임과 유효기간 항목은 두 서식이 같다."}},{"i":"S2-2-1-중개사법-15","r":"S2","g":2,"c":2,"n":15,"s":"중개사법","q":"공인중개사법령상 부동산거래정보망과 거래정보사업자에 관한 설명으로 틀린 것은?","b":null,"bs":"없음","img":[],"ch":["거래정보사업자로 지정받을 수 있는 자는 「전기통신사업법」에 따른 부가통신사업자로서 국토교통부령으로 정하는 요건을 갖춘 자이다.","거래정보사업자는 개업공인중개사로부터 공개를 의뢰받은 중개대상물의 정보에 한정하여 이를 부동산거래정보망에 공개해야 한다.","거래정보사업자로 지정받으려는 자는 정보처리기사 1명 이상과 공인중개사 1명 이상을 확보해야 한다.","거래정보사업자로 지정받으려면 부동산거래정보망 가입·이용신청을 한 개업공인중개사가 500명 이상이어야 하고, 3개 이상의 시·도에서 각각 30인 이상이 신청해야 한다.","국토교통부장관은 거래정보사업자가 정당한 사유 없이 지정받은 날부터 1년 이내에 부동산거래정보망을 설치·운영하지 않은 경우 그 지정을 취소할 수 있다."],"a":[4],"L":"중1-6","o":"변형","x":{"한줄":"지정요건은 가입·이용신청 개업공인중개사 500명 이상, 2개 이상의 시·도에서 각각 30인 이상이다(칙 제15조 제2항 제1호).","근거":[{"법령":"공인중개사법","조문":"제24조 제2항 제4항 제5항","원문":"②제1항에 따라 지정을 받을 수 있는 자는 「전기통신사업법」의 규정에 의한 부가통신사업자로서 국토교통부령으로 정하는 요건을 갖춘 자로 한다.\n④거래정보사업자는 개업공인중개사로부터 공개를 의뢰받은 중개대상물의 정보에 한정하여 이를 부동산거래정보망에 공개하여야 하며, 의뢰받은 내용과 다르게 정보를 공개하거나 어떠한 방법으로든지 개업공인중개사에 따라 정보가 차별적으로 공개되도록 하여서는 아니된다.\n⑤국토교통부장관은 거래정보사업자가 다음 각 호의 어느 하나에 해당하는 경우에는 그 지정을 취소할 수 있다.\n1. 거짓이나 그 밖의 부정한 방법으로 지정을 받은 경우\n2. 제3항의 규정을 위반하여 운영규정의 승인 또는 변경승인을 받지 아니하거나 운영규정을 위반하여 부동산거래정보망을 운영한 경우\n3. 제4항의 규정을 위반하여 정보를 공개한 경우\n4. 정당한 사유 없이 지정받은 날부터 1년 이내에 부동산거래정보망을 설치ㆍ운영하지 아니한 경우\n5. 개인인 거래정보사업자의 사망 또는 법인인 거래정보사업자의 해산 그 밖의 사유로 부동산거래정보망의 계속적인 운영이 불가능한 경우"},{"법령":"공인중개사법 시행규칙","조문":"제15조 제2항","원문":"②제1항에 따라 부동산거래정보망을 설치ㆍ운영할 자로 지정받으려는 자는 다음 각 호의 요건을 갖추어야 한다.\n1. 그 부동산거래정보망의 가입ㆍ이용신청을 한 개업공인중개사의 수가 5백명 이상이고 2개 이상의 특별시ㆍ광역시ㆍ도 및 특별자치도(이하 \"시ㆍ도\"라 한다)에서 각각 30인 이상의 개업공인중개사가 가입ㆍ이용신청을 하였을 것\n2. 정보처리기사 1명 이상을 확보할 것\n3. 공인중개사 1명 이상을 확보할 것\n4. 부동산거래정보망의 가입자가 이용하는데 지장이 없는 정도로서 국토교통부장관이 정하는 용량 및 성능을 갖춘 컴퓨터설비를 확보할 것"}],"선지":[{"번호":1,"판정":"옳음","설명":"부가통신사업자로서 국토교통부령이 정하는 요건을 갖춘 자가 지정 대상이다(법 제24조 제2항)."},{"번호":2,"판정":"옳음","설명":"의뢰받은 정보에 한정해 공개하고, 내용을 달리하거나 개업공인중개사에 따라 차별 공개해서는 안 된다(법 제24조 제4항)."},{"번호":3,"판정":"옳음","설명":"정보처리기사 1명 이상, 공인중개사 1명 이상을 확보해야 한다(칙 제15조 제2항 제2호·제3호)."},{"번호":4,"판정":"틀림","설명":"2개 이상의 시·도에서 각각 30인 이상이다. 3개 이상이 아니다(칙 제15조 제2항 제1호)."},{"번호":5,"판정":"옳음","설명":"정당한 사유 없이 지정받은 날부터 1년 이내에 설치·운영하지 않으면 취소할 수 있다(법 제24조 제5항 제4호)."}],"개념":[{"종류":"흐름","제목":"거래정보사업자 지정과 운영","단계":[{"이름":"지정 신청","설명":"국토교통부장관에게 지정신청서 제출. 가입·이용신청서와 등록증 사본, 정보처리기사·공인중개사 자격증 사본 첨부"},{"이름":"지정 검토","설명":"신청일부터 30일 이내 검토, 적합하면 지정대장 기재 후 지정서 교부"},{"이름":"운영규정 승인","설명":"지정받은 날부터 3개월 이내 운영규정을 정해 국토교통부장관의 승인. 변경 때도 승인"},{"이름":"운영","설명":"의뢰받은 정보에 한정 공개, 차별 공개 금지. 거래가 완성되면 개업공인중개사가 지체 없이 통보"},{"이름":"지정 취소","설명":"거짓 지정, 운영규정 승인 위반, 정보 공개 위반, 1년 내 미운영, 계속 운영 불능. 앞의 네 사유는 청문"}]},{"종류":"표","제목":"지정요건(칙 제15조 제2항)","머리":["항목","기준"],"행":[["신청 개업공인중개사","500명 이상 + 2개 이상 시·도에서 각각 30인 이상"],["정보처리기사","1명 이상"],["공인중개사","1명 이상"],["컴퓨터설비","국토교통부장관이 정하는 용량·성능"],["사업자","전기통신사업법상 부가통신사업자"]]}],"함정":"숫자 선지다. 500명 / 2개 이상 시·도 / 각 30인 / 운영규정 3개월 / 미운영 1년을 서로 바꿔 놓은 선지가 나온다."}},{"i":"S2-2-1-중개사법-16","r":"S2","g":2,"c":2,"n":16,"s":"중개사법","q":"공인중개사법령상 개업공인중개사등의 금지행위와 그 벌칙에 관한 설명으로 틀린 것은?","b":null,"bs":"없음","img":[],"ch":["개업공인중개사가 중개의뢰인과 직접 거래를 한 경우 3년 이하의 징역 또는 3천만원 이하의 벌금에 처한다.","개업공인중개사가 거래당사자 쌍방을 대리하는 행위는 금지행위에 해당한다.","개업공인중개사가 중개대상물의 거래상 중요사항에 관하여 거짓된 언행으로 중개의뢰인의 판단을 그르치게 한 경우 3년 이하의 징역 또는 3천만원 이하의 벌금에 처한다.","사례·증여 그 밖의 어떠한 명목으로도 법정 보수 또는 실비를 초과하여 금품을 받는 행위는 금지행위에 해당한다.","단체를 구성하여 단체 구성원 이외의 자와 공동중개를 제한하는 행위는 금지행위에 해당한다."],"a":[3],"L":"중1-7","o":"변형","x":{"한줄":"중요사항에 관한 거짓 언행은 제33조 제1항 제4호 위반으로 1년 이하 징역 또는 1천만원 이하 벌금이다(법 제49조 제1항 제10호).","근거":[{"법령":"공인중개사법","조문":"제33조 제1항 제4호 제6호 제9호","원문":"① 개업공인중개사등은 다음 각 호의 행위를 하여서는 아니된다.\n1. 제3조에 따른 중개대상물의 매매를 업으로 하는 행위\n2. 제9조에 따른 중개사무소의 개설등록을 하지 아니하고 중개업을 영위하는 자인 사실을 알면서 그를 통하여 중개를 의뢰받거나 그에게 자기의 명의를 이용하게 하는 행위\n3. 사례ㆍ증여 그 밖의 어떠한 명목으로도 제32조에 따른 보수 또는 실비를 초과하여 금품을 받는 행위\n4. 해당 중개대상물의 거래상의 중요사항에 관하여 거짓된 언행 그 밖의 방법으로 중개의뢰인의 판단을 그르치게 하는 행위\n5. 관계 법령에서 양도ㆍ알선 등이 금지된 부동산의 분양ㆍ임대 등과 관련 있는 증서 등의 매매ㆍ교환 등을 중개하거나 그 매매를 업으로 하는 행위\n6. 중개의뢰인과 직접 거래를 하거나 거래당사자 쌍방을 대리하는 행위\n7. 탈세 등 관계 법령을 위반할 목적으로 소유권보존등기 또는 이전등기를 하지 아니한 부동산이나 관계 법령의 규정에 의하여 전매 등 권리의 변동이 제한된 부동산의 매매를 중개하는 등 부동산투기를 조장하는 행위\n8. 부당한 이익을 얻거나 제3자에게 부당한 이익을 얻게 할 목적으로 거짓으로 거래가 완료된 것처럼 꾸미는 등 중개대상물의 시세에 부당한 영향을 주거나 줄 우려가 있는 행위\n9. 단체를 구성하여 특정 중개대상물에 대하여 중개를 제한하거나 단체 구성원 이외의 자와 공동중개를 제한하는 행위\n4. 해당 중개대상물의 거래상의 중요사항에 관하여 거짓된 언행 그 밖의 방법으로 중개의뢰인의 판단을 그르치게 하는 행위\n6. 중개의뢰인과 직접 거래를 하거나 거래당사자 쌍방을 대리하는 행위\n9. 단체를 구성하여 특정 중개대상물에 대하여 중개를 제한하거나 단체 구성원 이외의 자와 공동중개를 제한하는 행위"},{"법령":"공인중개사법","조문":"제48조 제3호","원문":"3. 제33조제1항제5호부터 제9호까지의 규정을 위반한 자"},{"법령":"공인중개사법","조문":"제49조 제1항 제10호","원문":"①다음 각 호의 어느 하나에 해당하는 자는 1년 이하의 징역 또는 1천만원 이하의 벌금에 처한다.\n1. 제7조제1항 또는 제2항을 위반하여 다른 사람에게 자기의 성명을 사용하여 중개업무를 하게 하거나 공인중개사자격증을 양도ㆍ대여한 자 또는 다른 사람의 공인중개사자격증을 양수ㆍ대여받은 자\n1의2. 제7조제3항을 위반하여 같은 조 제1항 및 제2항에서 금지한 행위를 알선한 자\n2. 제8조의 규정을 위반하여 공인중개사가 아닌 자로서 공인중개사 또는 이와 유사한 명칭을 사용한 자\n3. 제12조의 규정을 위반하여 이중으로 중개사무소의 개설등록을 하거나 둘 이상의 중개사무소에 소속된 자\n4. 제13조제1항의 규정을 위반하여 둘 이상의 중개사무소를 둔 자\n5. 제13조제2항의 규정을 위반하여 임시 중개시설물을 설치한 자\n5의2. 제15조제3항을 위반하여 중개보조원을 고용한 자\n6. 제18조제2항의 규정을 위반하여 개업공인중개사가 아닌 자로서 \"공인중개사사무소\", \"부동산중개\" 또는 이와 유사한 명칭을 사용한 자\n6의2. 제18조의2제3항을 위반하여 개업공인중개사가 아닌 자로서 중개업을  하기 위하여 중개대상물에 대한 표시ㆍ광고를 한 자\n7. 제19조제1항 또는 제2항을 위반하여 다른 사람에게 자기의 성명 또는 상호를 사용하여 중개업무를 하게 하거나 중개사무소등록증을 다른 사람에게 양도ㆍ대여한 자 또는 다른 사람의 성명ㆍ상호를 사용하여 중개업무를 하거나 중개사무소등록증을 양수ㆍ대여받은 자\n7의2. 제19조제3항을 위반하여 같은 조 제1항 및 제2항에서 금지한 행위를 알선한 자\n8. 제24조제4항의 규정을 위반하여 정보를 공개한 자\n9. 제29조제2항의 규정을 위반하여 업무상 비밀을 누설한 자\n10. 제33조제1항제1호부터 제4호까지의 규정을 위반한 자\n10. 제33조제1항제1호부터 제4호까지의 규정을 위반한 자"}],"선지":[{"번호":1,"판정":"옳음","설명":"직접 거래(제33조 제1항 제6호)는 제48조 제3호의 3년 이하·3천만원 이하 벌칙이다."},{"번호":2,"판정":"옳음","설명":"직접 거래와 함께 거래당사자 쌍방 대리도 제6호의 금지행위다."},{"번호":3,"판정":"틀림","설명":"제4호 위반은 제49조 제1항 제10호에 따라 1년 이하 징역 또는 1천만원 이하 벌금이다."},{"번호":4,"판정":"옳음","설명":"보수·실비 초과 금품 수수는 제33조 제1항 제3호의 금지행위다."},{"번호":5,"판정":"옳음","설명":"단체를 구성해 공동중개를 제한하는 행위는 제33조 제1항 제9호의 금지행위다(제48조 제3호 벌칙)."}],"개념":[{"종류":"표","제목":"금지행위(법 제33조 제1항)와 벌칙","머리":["호","금지행위","벌칙"],"행":[["1","중개대상물의 매매를 업으로 하는 행위","1년 이하 징역 또는 1천만원 이하 벌금(제49조)"],["2","무등록 중개업자인 줄 알면서 의뢰받거나 명의를 이용하게 하는 행위","같음"],["3","사례·증여 등 명목으로 보수·실비 초과 금품 수수","같음"],["4","거래상 중요사항에 관한 거짓된 언행","같음"],["5","양도·알선 금지 부동산의 분양·임대 관련 증서 등의 매매·교환 중개, 매매업","3년 이하 징역 또는 3천만원 이하 벌금(제48조)"],["6","중개의뢰인과 직접 거래, 거래당사자 쌍방 대리","같음"],["7","미등기 부동산 또는 전매 제한 부동산의 매매 중개 등 투기 조장","같음"],["8","거짓 거래 꾸미기 등 시세에 부당한 영향","같음"],["9","단체 구성으로 중개 제한·공동중개 제한","같음"]]},{"종류":"표","제목":"금지행위 위반의 행정처분","머리":["대상","처분"],"행":[["개업공인중개사","등록취소 가능(제38조 제2항 제9호), 업무정지"],["소속공인중개사","자격정지"],["제33조 제2항(업무방해)","누구든지 해당, 3년 이하 징역 또는 3천만원 이하 벌금"]]}],"함정":"제48조와 제49조의 경계가 5호다. 1~4호는 1년·1천만원, 5~9호는 3년·3천만원으로 갈린다. 직접 거래(6호)는 3년 쪽이다."}},{"i":"S2-2-1-중개사법-17","r":"S2","g":2,"c":2,"n":17,"s":"중개사법","q":"공인중개사법령상 중개대상물 확인ㆍ설명서[Ⅱ] (비주거용 건축물)에서 개업공인중개사 기본 확인사항이 아닌 것은?","b":null,"bs":"없음","img":[],"ch":["토지의 소재지, 면적 등 대상물건의 표시","소유권 외의 권리사항 등 등기부 기재사항","관리비","입지조건","거래예정금액"],"a":[3],"L":"중1-8","o":"기출","x":{"한줄":"비주거용 확인·설명서[Ⅱ]의 기본 확인사항에는 관리비 항목이 없다. 관리비는 주택 임대차의 확인사항이고 주거용[Ⅰ] 서식에 있다.","근거":[{"법령":"공인중개사법 시행령","조문":"제21조 제1항 제1호 제2호 제3호 3의2. 제8호","원문":"①법 제25조제1항에 따라 개업공인중개사가 확인ㆍ설명해야 하는 사항은 다음 각 호와 같다. 다만, 제3호의2 및 제10호부터 제12호까지의 사항은 주택 임대차 중개의 경우에만 적용한다.\n1. 중개대상물의 종류ㆍ소재지ㆍ지번ㆍ지목ㆍ면적ㆍ용도ㆍ구조 및 건축연도 등 중개대상물에 관한 기본적인 사항\n2. 소유권ㆍ전세권ㆍ저당권ㆍ지상권 및 임차권 등 중개대상물의 권리관계에 관한 사항\n3. 거래예정금액ㆍ중개보수 및 실비의 금액과 그 산출내역\n3의2. 관리비 금액과 그 산출내역\n4. 토지이용계획, 공법상의 거래규제 및 이용제한에 관한 사항\n5. 수도ㆍ전기ㆍ가스ㆍ소방ㆍ열공급ㆍ승강기 및 배수 등 시설물의 상태\n6. 벽면ㆍ바닥면 및 도배의 상태\n7. 일조ㆍ소음ㆍ진동 등 환경조건\n8. 도로 및 대중교통수단과의 연계성, 시장ㆍ학교와의 근접성 등 입지조건\n9. 중개대상물에 대한 권리를 취득함에 따라 부담하여야 할 조세의 종류 및 세율\n10. 「주택임대차보호법」 제3조의7에 따른 임대인의 정보 제시 의무 및 같은 법 제8조에 따른 보증금 중 일정액의 보호에 관한 사항\n11. 「주민등록법」 제29조의2에 따른 전입세대확인서의 열람 또는 교부에 관한 사항\n12. 「민간임대주택에 관한 특별법」 제49조에 따른 임대보증금에 대한 보증에 관한 사항(중개대상물인 주택이 같은 법에 따른 민간임대주택인 경우만 해당한다)\n1. 중개대상물의 종류ㆍ소재지ㆍ지번ㆍ지목ㆍ면적ㆍ용도ㆍ구조 및 건축연도 등 중개대상물에 관한 기본적인 사항\n2. 소유권ㆍ전세권ㆍ저당권ㆍ지상권 및 임차권 등 중개대상물의 권리관계에 관한 사항\n3. 거래예정금액ㆍ중개보수 및 실비의 금액과 그 산출내역\n3의2. 관리비 금액과 그 산출내역\n8. 도로 및 대중교통수단과의 연계성, 시장ㆍ학교와의 근접성 등 입지조건"},{"법령":"공인중개사법 시행규칙","조문":"별지 제20호의2서식(비주거용 건축물) Ⅰ. 개업공인중개사 기본 확인사항","원문":"① 대상물건의 표시\n② 권리관계(등기부 기재사항)\n③ 토지이용계획, 공법상 이용제한 및 거래규제에 관한 사항(토지)\n④ 입지조건\n⑤ 관리에 관한 사항(경비실, 관리주체)\n⑥ 거래예정금액 등\n⑦ 취득 시 부담할 조세의 종류 및 세율"}],"선지":[{"번호":1,"판정":"-","설명":"①번 항목이다. 기본 확인사항이다."},{"번호":2,"판정":"-","설명":"②번 권리관계 항목의 등기부 기재사항이다. 기본 확인사항이다."},{"번호":3,"판정":"-","설명":"[Ⅱ] 기본 확인사항에 관리비 금액·산출내역 항목은 없다. 관리에 관한 사항은 경비실과 관리주체만 적는다."},{"번호":4,"판정":"-","설명":"④번 항목이다. 기본 확인사항이다."},{"번호":5,"판정":"-","설명":"⑥번 거래예정금액 등 항목이다. 기본 확인사항이다."}],"개념":[{"종류":"표","제목":"확인·설명서[Ⅱ](비주거용) 구성","머리":["구분","항목"],"행":[["Ⅰ. 기본 확인사항","① 대상물건의 표시 ② 권리관계 ③ 토지이용계획·공법상 제한(토지) ④ 입지조건 ⑤ 관리에 관한 사항 ⑥ 거래예정금액 등 ⑦ 취득 시 조세"],["Ⅱ. 세부 확인사항","⑧ 실제 권리관계 또는 공시되지 않은 물건의 권리 사항 ⑨ 내부·외부 시설물의 상태 ⑩ 벽면 및 바닥면"],["Ⅲ. 중개보수 등","⑪ 중개보수 및 실비의 금액과 산출내역"]]},{"종류":"표","제목":"확인·설명서 서식 4종(칙 제16조)","머리":["서식","대상"],"행":[["[Ⅰ] 별지 제20호","주거용 건축물"],["[Ⅱ] 별지 제20호의2","비주거용 건축물"],["[Ⅲ] 별지 제20호의3","토지"],["[Ⅳ] 별지 제20호의4","입목·광업재단·공장재단"]]}],"함정":"관리비와 비선호시설은 주거용 [Ⅰ]에만 있는 항목이다. [Ⅱ]에서 이 두 가지가 정답이 된다."}},{"i":"S2-2-1-중개사법-18","r":"S2","g":2,"c":2,"n":18,"s":"중개사법","q":"공인중개사법령상 중개대상물 확인ㆍ설명서[Ⅱ](비주거용 건축물)에서 개업공인중개사의 기본 확인사항이 아닌 것은?","b":null,"bs":"없음","img":[],"ch":["소재지, 면적 등 대상물건의 표시에 관한 사항","소유권 외의 권리사항","비선호시설(1km이내)의 유무에 관한 사항","관리주체 등 관리에 관한 사항","소유권에 관한 사항"],"a":[3],"L":"중1-8","o":"기출","x":{"한줄":"비선호시설(1km 이내) 항목은 주거용 [Ⅰ] 서식의 기본 확인사항이고 비주거용 [Ⅱ]에는 없다.","근거":[{"법령":"공인중개사법 시행규칙","조문":"별지 제20호의2서식(비주거용 건축물) Ⅰ. 개업공인중개사 기본 확인사항","원문":"① 대상물건의 표시\n② 권리관계(등기부 기재사항: 소유권에 관한 사항, 소유권 외의 권리사항)\n③ 토지이용계획, 공법상 이용제한 및 거래규제에 관한 사항(토지)\n④ 입지조건\n⑤ 관리에 관한 사항(경비실, 관리주체)\n⑥ 거래예정금액 등\n⑦ 취득 시 부담할 조세의 종류 및 세율"},{"법령":"공인중개사법 시행규칙","조문":"별지 제20호서식(주거용 건축물) Ⅰ. 개업공인중개사 기본 확인사항","원문":"⑥ 관리에 관한 사항(경비실, 관리주체, 관리비)\n⑦ 비선호시설(1km이내)"}],"선지":[{"번호":1,"판정":"-","설명":"①번 대상물건의 표시다. 기본 확인사항이다."},{"번호":2,"판정":"-","설명":"②번 권리관계의 소유권 외의 권리사항이다. 기본 확인사항이다."},{"번호":3,"판정":"-","설명":"비선호시설(1km이내)은 [Ⅰ] 주거용 서식에만 있다."},{"번호":4,"판정":"-","설명":"⑤번 관리에 관한 사항의 관리주체다. 기본 확인사항이다."},{"번호":5,"판정":"-","설명":"②번 권리관계의 소유권에 관한 사항이다. 기본 확인사항이다."}],"개념":[{"종류":"표","제목":"주거용[Ⅰ]과 비주거용[Ⅱ] 기본 확인사항 차이","머리":["항목","주거용[Ⅰ]","비주거용[Ⅱ]"],"행":[["대상물건의 표시","있음","있음"],["권리관계(등기부)","있음","있음"],["임대차 확정일자 부여현황 정보","있음","없음"],["입지조건","있음","있음"],["관리에 관한 사항","경비실·관리주체·관리비","경비실·관리주체"],["비선호시설(1km 이내)","있음","없음"],["거래예정금액 등","있음","있음"],["취득 시 조세","있음","있음"]]},{"종류":"표","제목":"확인·설명의 공통 규칙","머리":["항목","내용"],"행":[["설명 시기","중개가 완성되기 전"],["설명 상대방","권리를 취득하려는 중개의뢰인"],["서명 및 날인","개업공인중개사(법인은 대표자, 분사무소는 책임자) + 해당 중개를 한 소속공인중개사"],["보존","원본·사본 또는 전자문서 3년"],["자료요구 불응","그 사실을 설명하고 확인·설명서에 기재"]]}],"함정":"비주거용에도 입지조건·관리가 있다 보니 주거용 전용 항목(관리비, 비선호시설)까지 있는 것처럼 읽기 쉽다."}},{"i":"S2-2-1-중개사법-19","r":"S2","g":2,"c":2,"n":19,"s":"중개사법","q":"공인중개사법령상 중개대상물의 확인·설명에 관한 설명으로 옳은 것은? (다툼이 있으면 판례에 따름)","b":null,"bs":"없음","img":[],"ch":["개업공인중개사는 중개대상물의 확인·설명을 중개가 완성된 후에 하면 된다.","중개대상물 확인·설명서에는 개업공인중개사가 서명 및 날인하되, 해당 중개행위를 한 소속공인중개사가 있는 경우 그 소속공인중개사도 함께 서명 및 날인해야 한다.","개업공인중개사는 중개대상물 확인·설명서의 원본, 사본 또는 전자문서를 5년간 보존해야 한다.","매도의뢰인이 중개대상물의 상태에 관한 자료요구에 불응한 경우, 개업공인중개사는 그 사실을 확인·설명서에 기재하지 않아도 된다.","개업공인중개사는 해당 중개대상물에 관한 권리를 이전하려는 중개의뢰인에게 성실·정확하게 설명하고 근거자료를 제시해야 한다."],"a":[2],"L":"중1-8","o":"변형","x":{"한줄":"확인·설명서에는 개업공인중개사가 서명 및 날인하고, 해당 중개를 한 소속공인중개사가 있으면 함께 서명 및 날인한다(법 제25조 제4항).","근거":[{"법령":"공인중개사법","조문":"제25조 제1항 제4항","원문":"①개업공인중개사는 중개를 의뢰받은 경우에는 중개가 완성되기 전에 다음 각 호의 사항을 확인하여 이를 해당 중개대상물에 관한 권리를 취득하고자 하는 중개의뢰인에게 성실ㆍ정확하게 설명하고, 토지대장 등본 또는 부동산종합증명서, 등기사항증명서, 신탁원부, 건축물대장 등본 등 설명의 근거자료를 제시하여야 한다.\n1. 해당 중개대상물의 상태ㆍ입지 및 권리관계\n2. 법령의 규정에 의한 거래 또는 이용제한사항\n3. 그 밖에 대통령령으로 정하는 사항\n④제3항에 따른 확인ㆍ설명서에는 개업공인중개사(법인인 경우에는 대표자를 말하며, 법인에 분사무소가 설치되어 있는 경우에는 분사무소의 책임자를 말한다)가 서명 및 날인하되, 해당 중개행위를 한 소속공인중개사가 있는 경우에는 소속공인중개사가 함께 서명 및 날인하여야 한다."},{"법령":"공인중개사법 시행령","조문":"제21조 제2항 제4항","원문":"②개업공인중개사는 매도의뢰인ㆍ임대의뢰인 등이 법 제25조제2항의 규정에 따른 중개대상물의 상태에 관한 자료요구에 불응한 경우에는 그 사실을 매수의뢰인ㆍ임차의뢰인 등에게 설명하고, 제3항의 규정에 따른 중개대상물확인ㆍ설명서에 기재하여야 한다.\n④ 법 제25조제3항 본문에서 \"대통령령이 정하는 기간\"이란 3년을 말한다."},{"법령":"공인중개사법 시행령","조문":"제22조 제2항","원문":"②법 제26조제1항에서 \"대통령령이 정하는 기간\"이라 함은 5년을 말한다."}],"선지":[{"번호":1,"판정":"틀림","설명":"중개가 완성되기 전에 확인·설명한다(법 제25조 제1항)."},{"번호":2,"판정":"옳음","설명":"서명 ‘및’ 날인이다. 소속공인중개사도 해당 중개를 했으면 함께 한다(법 제25조 제4항)."},{"번호":3,"판정":"틀림","설명":"확인·설명서 보존기간은 3년이다(영 제21조 제4항). 5년은 거래계약서 보존기간이다(영 제22조 제2항)."},{"번호":4,"판정":"틀림","설명":"자료요구에 불응하면 그 사실을 매수·임차의뢰인 등에게 설명하고 확인·설명서에 기재한다(영 제21조 제2항)."},{"번호":5,"판정":"틀림","설명":"설명 상대방은 권리를 취득하려는 중개의뢰인이다(법 제25조 제1항)."}],"개념":[{"종류":"표","제목":"확인·설명서와 거래계약서 비교","머리":["구분","확인·설명서","거래계약서"],"행":[["작성 시점","중개가 완성되어 거래계약서를 작성할 때(설명은 완성 전)","중개가 완성된 때"],["교부 대상","거래당사자","거래당사자"],["보존기간","3년","5년"],["서명 및 날인","개업공인중개사 + 해당 중개한 소속공인중개사","같음(법 제26조 제2항)"],["근거","법 제25조, 영 제21조","법 제26조, 영 제22조"]]},{"종류":"표","제목":"확인·설명 의무 정리","머리":["항목","내용"],"행":[["설명 상대방","권리를 취득하려는 중개의뢰인"],["근거자료 제시","토지대장 등본 또는 부동산종합증명서, 등기사항증명서, 신탁원부, 건축물대장 등본 등"],["위반 시","성실·정확하게 설명하지 않았거나 근거자료를 제시하지 않으면 500만원 이하 과태료"],["소속공인중개사 위반","자격정지"],["매도·임대의뢰인 자료요구","필요하면 요구할 수 있음"]]}],"함정":"보존기간 3년(확인·설명서)과 5년(거래계약서)을 바꿔 놓는 선지가 반복해서 나온다. 설명 상대방도 취득하려는 쪽이다."}},{"i":"S2-2-1-중개사법-20","r":"S2","g":2,"c":2,"n":20,"s":"중개사법","q":"공인중개사법령상 계약금등의 반환채무이행의 보장 등에 관한 설명으로 틀린 것은?","b":null,"bs":"없음","img":[],"ch":["「우체국예금·보험에 관한 법률」에 따른 체신관서는 계약금등의 예치명의자가 될 수 있다.","개업공인중개사가 계약금등을 자기 명의로 예치한 경우, 거래당사자의 동의 없이 예치된 계약금등을 인출해서는 안 된다.","계약금등을 예치한 경우 매도인 등 수령할 권리가 있는 자는 계약 해제 시 반환을 보장하는 금융기관 또는 보증보험회사 발행 보증서를 예치명의자에게 교부하고 계약금등을 미리 수령할 수 있다.","개업공인중개사가 계약금등을 자기 명의로 예치하는 경우 예치대상 금액을 보장하는 보증보험 또는 공제에 가입하거나 공탁을 해야 하고, 거래당사자에게 관계증서의 사본을 교부해야 한다.","계약금등의 예치 권고 대상은 계약금에 한정되며, 중도금과 잔금은 포함되지 않는다."],"a":[5],"L":"중1-9","o":"변형","x":{"한줄":"예치 권고 대상은 계약금·중도금 또는 잔금 전부다(법 제31조 제1항).","근거":[{"법령":"공인중개사법","조문":"제31조 제1항 제2항","원문":"①개업공인중개사는 거래의 안전을 보장하기 위하여 필요하다고 인정하는 경우에는 거래계약의 이행이 완료될 때까지 계약금ㆍ중도금 또는 잔금(이하 이 조에서 \"계약금등\"이라 한다)을 개업공인중개사 또는 대통령령으로 정하는 자의 명의로 금융기관, 제42조에 따라 공제사업을 하는 자 또는 「자본시장과 금융투자업에 관한 법률」에 따른 신탁업자 등에 예치하도록 거래당사자에게 권고할 수 있다.\n②제1항에 따라 계약금등을 예치한 경우 매도인ㆍ임대인 등 계약금등을 수령할 수 있는 권리가 있는 자는 해당 계약을 해제한 때에 계약금등의 반환을 보장하는 내용의 금융기관 또는 보증보험회사가 발행하는 보증서를 계약금등의 예치명의자에게 교부하고 계약금등을 미리 수령할 수 있다."},{"법령":"공인중개사법 시행령","조문":"제27조 제1항 제4호 제3항 제4항","원문":"①법 제31조제1항에서 \"대통령령이 정하는 자\"라 함은 다음 각 호의 자를 말한다.\n1. 「은행법」에 따른 은행\n2. 「보험업법」에 따른 보험회사\n3. 「자본시장과 금융투자업에 관한 법률」에 따른 신탁업자\n4. 「우체국예금ㆍ보험에 관한 법률」에 따른 체신관서\n5. 법 제42조의 규정에 따라 공제사업을 하는 자\n6. 부동산 거래계약의 이행을 보장하기 위하여 계약금ㆍ중도금 또는 잔금(이하 이 조에서 \"계약금등\"이라 한다) 및 계약 관련서류를 관리하는 업무를 수행하는 전문회사\n4. 「우체국예금ㆍ보험에 관한 법률」에 따른 체신관서\n③개업공인중개사는 제2항의 규정에 따라 거래계약과 관련된 계약금등을 자기 명의로 금융기관 등에 예치하는 경우에는 자기 소유의 예치금과 분리하여 관리될 수 있도록 하여야 하며, 예치된 계약금등은 거래당사자의 동의 없이 인출하여서는 아니 된다.\n④개업공인중개사는 제2항의 규정에 따라 계약금등을 자기 명의로 금융기관 등에 예치하는 경우에는 그 계약금등을 거래당사자에게 지급할 것을 보장하기 위하여 예치대상이 되는 계약금등에 해당하는 금액을 보장하는 보증보험 또는 법 제42조의 규정에 따른 공제에 가입하거나 공탁을 하여야 하며, 거래당사자에게 관계증서의 사본을 교부하거나 관계증서에 관한 전자문서를 제공하여야 한다."}],"선지":[{"번호":1,"판정":"옳음","설명":"체신관서는 예치명의자가 될 수 있는 자다(영 제27조 제1항 제4호)."},{"번호":2,"판정":"옳음","설명":"자기 명의로 예치한 계약금등은 거래당사자의 동의 없이 인출할 수 없다(영 제27조 제3항)."},{"번호":3,"판정":"옳음","설명":"보증서를 예치명의자에게 교부하면 계약금등을 미리 수령할 수 있다(법 제31조 제2항)."},{"번호":4,"판정":"옳음","설명":"자기 명의 예치 때는 보증보험·공제 가입 또는 공탁과 관계증서 교부가 필요하다(영 제27조 제4항)."},{"번호":5,"판정":"틀림","설명":"계약금·중도금 또는 잔금이 모두 대상이다(법 제31조 제1항)."}],"개념":[{"종류":"표","제목":"계약금등 예치 제도","머리":["항목","내용"],"행":[["성격","거래 안전을 위해 필요하다고 인정할 때 개업공인중개사가 권고(의무 아님)"],["예치 대상","계약금·중도금 또는 잔금"],["예치 기간","거래계약의 이행이 완료될 때까지"],["예치기관","금융기관, 공제사업자, 신탁업자 등"],["예치명의자","개업공인중개사, 은행, 보험회사, 신탁업자, 체신관서, 공제사업자, 이행보장 전문회사"],["개업공인중개사 명의 예치","분리 관리, 동의 없이 인출 금지, 보증보험·공제·공탁 + 관계증서 교부"],["미리 수령","보증서 교부 후 매도인 등이 해제 시 반환을 보장하고 수령 가능"]]},{"종류":"표","제목":"업무보증 설정 비교","머리":["구분","내용"],"행":[["손해배상 보장 수단","보증보험, 공제 가입 또는 공탁"],["설정 시기","업무를 개시하기 전"],["공탁금 회수","폐업·사망한 날부터 3년 이내에는 불가"],["거래당사자 설명","중개가 완성되면 보장금액·보증기관·보장기간을 설명하고 증서 사본 교부"]]}],"함정":"예치는 의무가 아니라 권고다. 예치 대상은 세 가지 모두이고, 예치명의자 범위에 공제사업자가 들어간다는 점을 놓치기 쉽다."}},{"i":"S2-2-1-중개사법-21","r":"S2","g":2,"c":2,"n":21,"s":"중개사법","q":"공인중개사법령상 중개보수 등에 관한 설명으로 옳은 것은?","b":null,"bs":"없음","img":[],"ch":["계약금 등의 반환채무이행 보장에 소요되는 실비는 매도ㆍ임대 그 밖의 권리를 이전하려는 중개의뢰인에게 영수증 등을 첨부하여 청구한다.","중개보수의 지급시기를 약정하지 않은 경우에는 거래계약서를 작성한 날에 지급한다.","전용면적 80제곱미터이고 상ㆍ하수도 시설이 갖추어진 전용입식 부엌, 전용수세식 화장실 및 목욕시설을 갖춘 오피스텔의 임대차를 중개한 경우에는 주택의 중개보수 상한요율(시행규칙 별표 1)이 적용된다.","보증금 2천만원에 월 차임 25만원인 상가건물 임대차를 중개한 경우 중개보수 계산에 적용하는 거래금액은 3천750만원이다.","동일한 주택에 대하여 동일 당사자 간에 매매(2억원)와 임대차(보증금 1억원)가 동일 기회에 이루어진 경우 거래금액은 3억원으로 계산한다."],"a":[4],"L":"중1-10","o":"변형","x":{"한줄":"월 차임이 있는 임대차는 차임에 100을 곱해 보증금에 더하고, 그 합계가 5천만원 미만이면 70을 곱해 더한다. 2천만원 + 25만원 × 70 = 3천750만원이다.","근거":[{"법령":"공인중개사법 시행규칙","조문":"제20조 제5항","원문":"⑤제1항 및 제4항의 경우 거래금액의 계산은 다음 각 호에 따른다.\n1. 임대차 중 보증금 외에 차임이 있는 경우에는 월 단위의 차임액에 100을 곱한 금액을 보증금에 합산한 금액을 거래금액으로 한다. 다만, 본문의 규정에 따라 합산한 금액이 5천만원 미만인 경우에는 본문의 규정에 불구하고 월 단위의 차임액에 70을 곱한 금액과 보증금을 합산한 금액을 거래금액으로 한다.\n2. 교환계약의 경우에는 교환대상 중개대상물 중 거래금액이 큰 중개대상물의 가액을 거래금액으로 한다.\n3. 동일한 중개대상물에 대하여 동일 당사자간에 매매를 포함한 둘 이상의 거래가 동일 기회에 이루어지는 경우에는 매매계약에 관한 거래금액만을 적용한다."},{"법령":"공인중개사법 시행령","조문":"제27조의2","원문":"제27조의2(중개보수의 지급시기) 법 제32조제3항에 따른 중개보수의 지급시기는 개업공인중개사와 중개의뢰인간의 약정에 따르되, 약정이 없을 때에는 중개대상물의 거래대금 지급이 완료된 날로 한다."},{"법령":"공인중개사법 시행규칙","조문":"제20조 제2항","원문":"②법 제32조제4항에 따른 실비의 한도는 중개대상물의 권리관계 등의 확인 또는 계약금 등의 반환채무이행 보장에 드는 비용으로 하되, 개업공인중개사가 영수증 등을 첨부하여 매도ㆍ임대 그 밖의 권리를 이전하고자 하는 중개의뢰인(계약금 등의 반환채무이행 보장에 소요되는 실비의 경우에는 매수ㆍ임차 그 밖의 권리를 취득하고자 하는 중개의뢰인을 말한다)에게 청구할 수 있다."},{"법령":"공인중개사법 시행규칙","조문":"제20조 제4항","원문":"④법 제32조제4항에 따라 주택 외의 중개대상물에 대한 중개보수는 다음 각 호의 구분에 따른다.\n1. 「건축법 시행령」 별표 1 제14호나목2)에 따른 오피스텔(다음 각 목의 요건을 모두 갖춘 경우에 한정한다): 중개의뢰인 쌍방으로부터 각각 받되, 별표 2의 상한요율 이내에서 중개의뢰인과 개업공인중개사가 서로 협의하여 결정한다.\n가. 전용면적이 85제곱미터 이하일 것\n나. 상ㆍ하수도 시설이 갖추어진 전용입식 부엌, 전용수세식 화장실 및 목욕시설(전용수세식 화장실에 목욕시설을 갖춘 경우를 포함한다)을 갖출 것\n2. 제1호 외의 경우: 중개의뢰인 쌍방으로부터 각각 받되, 거래금액의 1천분의 9 이내에서 중개의뢰인과 개업공인중개사가 서로 협의하여 결정한다."}],"선지":[{"번호":1,"판정":"틀림","설명":"계약금 등의 반환채무이행 보장에 든 실비는 매수ㆍ임차 그 밖의 권리를 취득하려는 중개의뢰인에게 청구한다. 매도인ㆍ임대인에게 청구하는 실비는 권리관계 등의 확인에 든 비용이다(시행규칙 제20조제2항)."},{"번호":2,"판정":"틀림","설명":"약정이 없으면 중개대상물의 거래대금 지급이 완료된 날에 지급한다. 계약서를 쓴 날이 아니다(시행령 제27조의2)."},{"번호":3,"판정":"틀림","설명":"요건을 갖춘 오피스텔은 주택이 아니라 주택 외의 중개대상물이다. 별표 2 상한요율(매매ㆍ교환 1천분의 5, 임대차 등 1천분의 4)을 적용한다(시행규칙 제20조제4항제1호). 전용면적 85제곱미터 이하이고 부엌ㆍ화장실ㆍ목욕시설을 모두 갖춘 경우에 한한다."},{"번호":4,"판정":"옳음","설명":"2천만원 + 25만원 × 100 = 4천500만원이 5천만원 미만이므로 70을 적용한다. 2천만원 + 25만원 × 70 = 3천750만원이다(시행규칙 제20조제5항제1호)."},{"번호":5,"판정":"틀림","설명":"같은 물건ㆍ같은 당사자ㆍ같은 기회에 매매를 포함한 둘 이상의 거래가 이루어지면 매매계약의 거래금액만 적용한다. 2억원이고 임대차 보증금은 더하지 않는다(시행규칙 제20조제5항제3호)."}],"개념":[{"종류":"계산","제목":"월 차임이 있는 임대차의 거래금액과 보수 계산 (시행규칙 제20조제5항)","단계":[{"설명":"월 차임에 100을 곱해 보증금에 더한다","식":"2,000만원 + 25만원 × 100","값":"4,500만원"},{"설명":"합계가 5천만원 미만이면 100 대신 70을 곱한다","식":"4,500만원 < 5,000만원","값":"70 적용"},{"설명":"월 차임에 70을 곱해 보증금에 더한다","식":"2,000만원 + 25만원 × 70","값":"3,750만원"},{"설명":"경계 확인: 보증금 3천만원, 월 차임 20만원이면 100을 곱한 합계가 5천만원이어서 미만이 아니다","식":"3,000만원 + 20만원 × 100","값":"5,000만원(100 유지)"},{"설명":"상가 임대차 보수 한도(요율표에 적은 자기 상한이 1천분의 9인 경우)","식":"3,750만원 × 9/1,000","값":"33만 7,500원"}]},{"종류":"표","제목":"주택 중개보수 상한요율 (시행규칙 별표 1, 일방에게 받는 한도)","머리":["구분","거래금액","상한요율","한도액"],"행":[["매매ㆍ교환","5천만원 미만","1천분의 6","25만원"],["매매ㆍ교환","5천만원 이상 2억원 미만","1천분의 5","80만원"],["매매ㆍ교환","2억원 이상 9억원 미만","1천분의 4","-"],["매매ㆍ교환","9억원 이상 12억원 미만","1천분의 5","-"],["매매ㆍ교환","12억원 이상 15억원 미만","1천분의 6","-"],["매매ㆍ교환","15억원 이상","1천분의 7","-"],["임대차 등","5천만원 미만","1천분의 5","20만원"],["임대차 등","5천만원 이상 1억원 미만","1천분의 4","30만원"],["임대차 등","1억원 이상 6억원 미만","1천분의 3","-"],["임대차 등","6억원 이상 12억원 미만","1천분의 4","-"],["임대차 등","12억원 이상 15억원 미만","1천분의 5","-"],["임대차 등","15억원 이상","1천분의 6","-"]]}],"함정":"5번은 매매 2억원과 보증금 1억원을 더해 3억원으로 읽기 쉽다. 동일 기회의 복수 거래는 매매금액 하나만 쓴다. 4번에서 70과 100 중 무엇을 곱하는지는 100을 곱한 합계가 5천만원 미만인지로 가른다. 3번은 오피스텔이 요건을 갖추면 주택 요율이 아니라 별표 2를 쓴다는 점에서 틀렸다. 1번은 실비 청구 상대방이 실비의 종류에 따라 다르다는 점을 뒤바꾼 문장이다."}},{"i":"S2-2-1-중개사법-22","r":"S2","g":2,"c":2,"n":22,"s":"중개사법","q":"공인중개사법령상 개업공인중개사등의 교육 및 포상금에 관한 설명으로 틀린 것은?","b":null,"bs":"없음","img":[],"ch":["시ㆍ도지사가 실무교육, 직무교육 및 연수교육에 관한 업무를 위탁하려면 부동산 관련 학과가 개설된 「고등교육법」상의 학교, 협회, 공기업 또는 준정부기관 중 인력과 시설을 갖춘 기관 또는 단체를 지정하여 위탁해야 한다.","포상금은 행정기관에 의하여 발각되기 전에 등록관청이나 수사기관에 신고 또는 고발한 자에게 그 사건에 대하여 검사가 공소제기 또는 기소유예의 결정을 한 경우에 한하여 지급한다.","하나의 사건에 대하여 2건 이상의 신고 또는 고발이 접수된 경우 등록관청은 포상금을 신고자들에게 균등하게 배분하여 지급한다.","포상금의 지급에 소요되는 비용 중 국고에서 보조할 수 있는 비율은 100분의 50 이내로 한다.","시ㆍ도지사는 연수교육을 실시하려는 경우 실무교육 또는 연수교육을 받은 후 2년이 되기 2개월 전까지 연수교육의 일시ㆍ장소ㆍ내용 등을 대상자에게 통지해야 한다."],"a":[3],"L":"중1-11","o":"변형","x":{"한줄":"하나의 사건에 신고가 2건 이상 접수되면 최초로 신고 또는 고발한 자에게만 포상금을 지급한다. 균등 배분은 2인 이상이 공동으로 신고한 경우의 방식이다.","근거":[{"법령":"공인중개사법 시행규칙","조문":"제28조 제3항 제4항","원문":"③등록관청은 하나의 사건에 대하여 2인 이상이 공동으로 신고 또는 고발한 경우에는 영 제36조의2제1항에 따른 포상금을 균등하게 배분하여 지급한다. 다만, 포상금을 지급받을 자가 배분방법에 관하여 미리 합의하여 포상금의 지급을 신청한 경우에는 그 합의된 방법에 따라 지급한다.\n④등록관청은 하나의 사건에 대하여 2건 이상의 신고 또는 고발이 접수된 경우에는 최초로 신고 또는 고발한 자에게 포상금을 지급한다."},{"법령":"공인중개사법 시행령","조문":"제36조의2","원문":"제36조의2(포상금)\n①법 제46조제1항의 규정에 따른 포상금은 1건당 50만원으로 한다.\n②제1항의 규정에 따른 포상금은 법 제46조제1항 각 호의 어느 하나에 해당하는 자가 행정기관에 의하여 발각되기 전에 등록관청이나 수사기관에 신고 또는 고발한 자에게 그 신고 또는 고발사건에 대하여 검사가 공소제기 또는 기소유예의 결정을 한 경우에 한하여 지급한다.\n③법 제46조제2항의 규정에 따라 포상금의 지급에 소요되는 비용 중 국고에서 보조할 수 있는 비율은 100분의 50이내로 한다.\n④그 밖에 포상금의 지급방법 및 절차 등에 관하여 필요한 사항은 국토교통부령으로 정한다."},{"법령":"공인중개사법 시행령","조문":"제36조 제1항","원문":"①시ㆍ도지사는 법 제45조에 따라 법 제34조제1항부터 제4항까지의 규정에 따른 실무교육, 직무교육 및 연수교육에 관한 업무를 위탁하는 때에는 다음 각 호의 기관 또는 단체 중 국토교통부령으로 정하는 인력 및 시설을 갖춘 기관 또는 단체를 지정하여 위탁하여야 한다.\n1. 부동산 관련 학과가 개설된 「고등교육법」 제2조에 따른 학교\n2. 협회\n3. 「공공기관의 운영에 관한 법률」 제5조제4항에 따른 공기업 또는 준정부기관"},{"법령":"공인중개사법 시행령","조문":"제28조 제4항","원문":"④ 시ㆍ도지사는 법 제34조제4항에 따른 연수교육을 실시하려는 경우 실무교육 또는 연수교육을 받은 후 2년이 되기 2개월 전까지 연수교육의 일시ㆍ장소ㆍ내용 등을 대상자에게 통지하여야 한다."}],"선지":[{"번호":1,"판정":"옳음","설명":"위탁 대상은 부동산 관련 학과가 개설된 학교, 협회, 공기업ㆍ준정부기관 중 국토교통부령이 정한 인력과 시설을 갖춘 기관이다(시행령 제36조제1항)."},{"번호":2,"판정":"옳음","설명":"행정기관에 발각되기 전에 신고하고 검사가 공소제기 또는 기소유예를 결정한 경우에 한해 지급한다(시행령 제36조의2제2항)."},{"번호":3,"판정":"틀림","설명":"2건 이상의 신고가 접수되면 최초로 신고 또는 고발한 자에게 지급한다(시행규칙 제28조제4항). 2인 이상이 공동으로 신고한 때에만 균등하게 배분한다(같은 조 제3항)."},{"번호":4,"판정":"옳음","설명":"포상금 비용 중 국고 보조 비율은 100분의 50 이내다(시행령 제36조의2제3항)."},{"번호":5,"판정":"옳음","설명":"연수교육 통지 시한은 실무교육 또는 연수교육을 받은 후 2년이 되기 2개월 전까지다(시행령 제28조제4항)."}],"개념":[{"종류":"표","제목":"개업공인중개사등 교육 (법 제34조, 시행령 제28조)","머리":["구분","대상","받는 시기","시간","실시 주체"],"행":[["실무교육","개설등록 신청자(법인은 사원ㆍ임원, 분사무소는 책임자), 소속공인중개사","등록신청일ㆍ고용신고일 전 1년 이내","45시간","시ㆍ도지사"],["직무교육","중개보조원","고용신고일 전 1년 이내","3시간 이상 4시간 이하","시ㆍ도지사 또는 등록관청"],["연수교육","실무교육을 받은 개업공인중개사ㆍ소속공인중개사","실무교육을 받은 후 2년마다","12시간 이상 16시간 이하","시ㆍ도지사"],["부동산거래사고 예방교육","개업공인중개사등","교육일 10일 전까지 공고 또는 통지","규정 없음","국토교통부장관, 시ㆍ도지사, 등록관청"]]},{"종류":"흐름","제목":"포상금 지급 절차 (법 제46조, 시행령 제36조의2, 시행규칙 제28조)","단계":[{"이름":"신고ㆍ고발","설명":"행정기관에 발각되기 전에 등록관청, 수사기관 또는 신고센터에 신고 또는 고발한다. 대상은 무등록 중개업, 부정 등록, 등록증ㆍ자격증 양도ㆍ대여, 개업공인중개사가 아닌 자의 중개 표시ㆍ광고, 거짓 거래로 시세를 교란하거나 단체를 구성해 중개를 제한하는 행위, 시세 교란 목적의 업무방해 6가지다."},{"이름":"검사의 처분","설명":"그 사건에 대하여 검사가 공소제기 또는 기소유예 결정을 해야 지급 대상이 된다."},{"이름":"신청","설명":"포상금지급신청서를 등록관청에 제출한다."},{"이름":"조회ㆍ결정","설명":"등록관청이 수사기관의 처분내용을 조회한 뒤 지급을 결정한다."},{"이름":"지급","설명":"결정일부터 1월 이내에 1건당 50만원을 지급한다. 2인 이상 공동 신고는 균등 배분, 2건 이상 각각 신고는 최초 신고자에게 지급한다."}]}],"함정":"3번은 균등 배분이라는 말이 포상금 규정에 실제로 있어서 맞는 문장처럼 읽힌다. 균등 배분은 한 사건을 2인 이상이 함께 신고했을 때의 규칙이고, 따로 접수된 2건 이상은 최초 신고자 한 사람에게 지급한다. 5번의 2개월 전 통지, 4번의 100분의 50은 숫자를 바꿔 내는 단골 자리다."}},{"i":"S2-2-1-중개사법-23","r":"S2","g":2,"c":2,"n":23,"s":"중개사법","q":"공인중개사법령상 한국공인중개사협회(이하 '협회'라 함)의 공제사업에 관한 설명으로 틀린 것은?","b":null,"bs":"없음","img":[],"ch":["협회는 공제사업을 다른 회계와 구분하여 별도의 회계로 관리해야 한다.","공제규정에서 정하는 책임준비금의 적립비율은 공제료 수입액의 100분의 20이상으로 한다.","국토교통부장관은 협회의 자산상황이 불량하여 공제 가입자의 권익을 해칠 우려가 있다고 인정하면 자산예탁기관의 변경을 명할 수 있다.","국토교통부장관은 협회의 자산상황이 불량하여 중개사고 피해자의 권익을 해칠 우려가 있다고 인정하면 불건전한 자산에 대한 적립금의 보유를 명할 수 있다.","협회는 대통령령으로 정하는 바에 따라 매년도의 공제사업 운용실적을 일간신문ㆍ협회보 등을 통하여 공제계약자에게 공시해야 한다."],"a":[2],"L":"중1-12","o":"기출","x":{"한줄":"책임준비금의 적립비율은 공제료 수입액의 100분의 10 이상으로 정한다(시행령 제34조제3호). 100분의 20은 틀린 숫자다.","근거":[{"법령":"공인중개사법 시행령","조문":"제34조 제3호","원문":"3. 책임준비금의 적립비율 : 공제사고 발생률 및 공제금 지급액 등을 종합적으로 고려하여 정하되, 공제료 수입액의 100분의 10이상으로 정한다."},{"법령":"공인중개사법","조문":"제42조 제4항 제5항","원문":"④협회는 공제사업을 다른 회계와 구분하여 별도의 회계로 관리하여야 하며, 책임준비금을 다른 용도로 사용하고자 하는 경우에는 국토교통부장관의 승인을 얻어야 한다.\n⑤협회는 대통령령으로 정하는 바에 따라 매년도의 공제사업 운용실적을 일간신문ㆍ협회보 등을 통하여 공제계약자에게 공시하여야 한다."},{"법령":"공인중개사법","조문":"제42조의4","원문":"제42조의4(공제사업 운영의 개선명령) 국토교통부장관은 협회의 공제사업 운영이 적정하지 아니하거나 자산상황이 불량하여 중개사고 피해자 및 공제 가입자 등의 권익을 해칠 우려가 있다고 인정하면 다음 각 호의 조치를 명할 수 있다.\n1. 업무집행방법의 변경\n2. 자산예탁기관의 변경\n3. 자산의 장부가격의 변경\n4. 불건전한 자산에 대한 적립금의 보유\n5. 가치가 없다고 인정되는 자산의 손실 처리\n6. 그 밖에 이 법 및 공제규정을 준수하지 아니하여 공제사업의 건전성을 해할 우려가 있는 경우 이에 대한 개선명령"},{"법령":"공인중개사법 시행령","조문":"제35조","원문":"제35조(공제사업 운용실적의 공시) 협회는 법 제42조제5항에 따라 다음 각 호의 사항을 매 회계연도 종료 후 3개월 이내에 일간신문 또는 협회보에 공시하고 협회의 인터넷 홈페이지에 게시해야 한다.\n1. 결산서인 요약 재무상태표, 손익계산서 및 감사보고서\n2. 공제료 수입액, 공제금 지급액, 책임준비금 적립액\n3. 그 밖에 공제사업의 운용과 관련된 참고사항"}],"선지":[{"번호":1,"판정":"옳음","설명":"공제사업은 다른 회계와 구분해 별도 회계로 관리하고, 책임준비금을 다른 용도로 쓰려면 국토교통부장관의 승인을 받는다(법 제42조제4항)."},{"번호":2,"판정":"틀림","설명":"적립비율은 공제료 수입액의 100분의 10 이상이다(시행령 제34조제3호)."},{"번호":3,"판정":"옳음","설명":"공제사업 운영이 적정하지 않거나 자산상황이 불량해 피해자와 가입자의 권익을 해칠 우려가 있으면 자산예탁기관의 변경을 명할 수 있다(법 제42조의4제2호)."},{"번호":4,"판정":"옳음","설명":"같은 조 제4호가 불건전한 자산에 대한 적립금의 보유를 명할 수 있는 조치로 정한다(법 제42조의4제4호)."},{"번호":5,"판정":"옳음","설명":"운용실적은 일간신문ㆍ협회보 등으로 공제계약자에게 공시한다(법 제42조제5항). 시행령은 매 회계연도 종료 후 3개월 이내에 일간신문 또는 협회보에 공시하고 협회 홈페이지에 게시하도록 한다(시행령 제35조)."}],"개념":[{"종류":"표","제목":"공제사업에 대한 국토교통부장관의 통제 수단","머리":["수단","내용","근거"],"행":[["공제규정 승인","제정ㆍ변경 모두 국토교통부장관 승인","법 제42조제2항"],["책임준비금 전용 승인","다른 용도로 쓰려면 승인","법 제42조제4항"],["개선명령","업무집행방법 변경, 자산예탁기관 변경, 자산 장부가격 변경, 불건전 자산 적립금 보유, 무가치 자산 손실 처리, 그 밖의 개선명령","법 제42조의4"],["임원 제재","공제규정 위반, 개선명령 불이행, 재무건전성 기준 위반 시 임원 징계ㆍ해임 요구 또는 시정명령","법 제42조의5"],["재무건전성","지급여력비율 100분의 100 이상 유지, 구상채권 등 분류와 대손충당금 적립","법 제42조의6, 시행령 제35조의3"],["조사ㆍ검사","국토교통부장관의 요청이 있으면 금융감독원장이 공제사업을 조사ㆍ검사","법 제42조의3"]]},{"종류":"표","제목":"공제 운영위원회 (법 제42조의2, 시행령 제35조의2)","머리":["항목","내용"],"행":[["설치 목적","공제사업 사항 심의, 업무집행 감독"],["위원 수","19명 이내"],["구성","협회 임원, 중개업ㆍ법률ㆍ회계ㆍ금융ㆍ보험ㆍ부동산 전문가, 관계 공무원, 이해관계자"],["일부 위원의 제한","협회 회장과 협회 이사회가 선임한 임원 위원은 전체 위원의 3분의 1 미만"],["임기","선임ㆍ위촉 위원(시행령 제35조의2제2항제3호ㆍ제4호) 2년, 1회 연임 가능"],["의결","재적위원 과반수 출석, 출석위원 과반수 찬성"]]}],"함정":"책임준비금 적립비율 100분의 10을 20으로 바꾼 2번이 답이다. 나머지는 법 제42조제4항과 제42조의4의 개선명령 목록에서 그대로 나온 문장이다. 3번과 4번의 권익 보호 대상이 가입자와 피해자로 다르게 적혀 있어도 법 제42조의4는 둘을 함께 보호 대상으로 적는다.","개정":"협회 명칭이 「공인중개사협회」에서 「한국공인중개사협회」로 법정화되었다(법 제41조제1항, 2026.2.27. 개정). 발문의 명칭만 현행에 맞췄고 정답은 그대로 2번이다."}},{"i":"S2-2-1-중개사법-24","r":"S2","g":2,"c":2,"n":24,"s":"중개사법","q":"공인중개사법령상 공인중개사의 자격취소에 관한 설명으로 틀린 것은?","b":null,"bs":"없음","img":[],"ch":["시ㆍ도지사는 공인중개사가 이 법을 위반하여 300만원 이상 벌금형의 선고를 받은 경우에는 그 자격을 취소해야 한다.","공인중개사의 자격이 취소된 자는 공인중개사자격증을 교부한 시ㆍ도지사에게 반납해야 한다.","시ㆍ도지사는 공인중개사의 자격취소처분을 한 때에는 5일 이내에 이를 국토교통부장관과 다른 시ㆍ도지사에게 통보해야 한다.","시ㆍ도지사는 공인중개사의 자격을 취소하고자 하는 경우에는 청문을 실시해야 한다.","시ㆍ도지사는 공인중개사가 부정한 방법으로 공인중개사의 자격을 취득한 경우에는 그 자격을 취소해야 한다."],"a":[1],"L":"중1-13","o":"기출","x":{"한줄":"자격취소 사유는 금고 이상의 형(집행유예 포함)을 선고받은 경우이고 벌금형은 해당하지 않는다. 300만원 이상 벌금형은 개설등록의 결격사유(법 제10조제1항제11호)다.","근거":[{"법령":"공인중개사법","조문":"제35조 제1항","원문":"①시ㆍ도지사는 공인중개사가 다음 각 호의 어느 하나에 해당하는 경우에는 그 자격을 취소하여야 한다.\n1. 부정한 방법으로 공인중개사의 자격을 취득한 경우\n2. 제7조제1항의 규정을 위반하여 다른 사람에게 자기의 성명을 사용하여 중개업무를 하게 하거나 공인중개사자격증을 양도 또는 대여한 경우\n3. 제36조에 따른 자격정지처분을 받고 그 자격정지기간 중에 중개업무를 행한 경우(다른 개업공인중개사의 소속공인중개사ㆍ중개보조원 또는 법인인 개업공인중개사의 사원ㆍ임원이 되는 경우를 포함한다)\n4. 이 법 또는 공인중개사의 직무와 관련하여 「형법」 제114조, 제231조, 제234조, 제347조, 제355조 또는 제356조를 위반하여 금고 이상의 형(집행유예를 포함한다)을 선고받은 경우"},{"법령":"공인중개사법","조문":"제35조 제2항 제3항 제4항","원문":"②시ㆍ도지사는 제1항에 따라 공인중개사의 자격을 취소하고자 하는 경우에는 청문을 실시하여야 한다.\n③제1항에 따라 공인중개사의 자격이 취소된 자는 국토교통부령으로 정하는 바에 따라 공인중개사자격증을 시ㆍ도지사에게 반납하여야 한다.\n④분실 등의 사유로 인하여 제3항에 따라 공인중개사자격증을 반납할 수 없는 자는 제3항에도 불구하고 자격증 반납을 대신하여 그 이유를 기재한 사유서를 시ㆍ도지사에게 제출하여야 한다."},{"법령":"공인중개사법 시행령","조문":"제29조 제3항","원문":"③시ㆍ도지사는 공인중개사의 자격취소처분을 한 때에는 5일 이내에 이를 국토교통부장관과 다른 시ㆍ도지사에게 통보해야 한다."},{"법령":"공인중개사법","조문":"제10조 제11호","원문":"11. 이 법을 위반하여 300만원 이상의 벌금형의 선고를 받고 3년이 지나지 아니한 자"}],"선지":[{"번호":1,"판정":"틀림","설명":"자격취소 사유는 이 법 또는 직무와 관련해 형법 제114조 등을 위반하여 금고 이상의 형을 선고받은 경우다(법 제35조제1항제4호). 300만원 이상 벌금형은 결격사유일 뿐 자격취소 사유가 아니다."},{"번호":2,"판정":"옳음","설명":"자격취소를 받은 자는 자격증을 교부한 시ㆍ도지사에게 반납한다(법 제35조제3항)."},{"번호":3,"판정":"옳음","설명":"취소처분 후 5일 이내에 국토교통부장관과 다른 시ㆍ도지사에게 통보한다(시행령 제29조제3항)."},{"번호":4,"판정":"옳음","설명":"자격을 취소하려면 청문을 실시해야 한다(법 제35조제2항)."},{"번호":5,"판정":"옳음","설명":"부정한 방법으로 자격을 취득한 경우는 필요적 취소 사유다(법 제35조제1항제1호)."}],"개념":[{"종류":"흐름","제목":"공인중개사 자격취소 절차","단계":[{"이름":"취소 사유 발생","설명":"부정한 방법으로 자격 취득, 자격증 양도ㆍ대여 또는 성명 사용 허용, 자격정지 기간 중 중개업무(소속공인중개사ㆍ중개보조원ㆍ법인 임원이 되는 경우 포함), 금고 이상의 형 선고(집행유예 포함) 중 하나다."},{"이름":"청문","설명":"시ㆍ도지사가 자격을 취소하려면 청문을 실시해야 한다(법 제35조제2항)."},{"이름":"취소처분","설명":"자격증을 교부한 시ㆍ도지사가 처분한다. 사무소 소재지 시ㆍ도지사가 다르면 사무소 소재지 시ㆍ도지사가 절차를 모두 이행한 뒤 자격증을 교부한 시ㆍ도지사에게 통보한다(시행령 제29조제1항ㆍ제2항)."},{"이름":"자격증 반납","설명":"처분을 받은 날부터 7일 이내에 자격증을 교부한 시ㆍ도지사에게 반납한다. 분실이면 반납 대신 사유서를 제출한다(법 제35조제3항ㆍ제4항, 시행규칙 제21조)."},{"이름":"통보","설명":"취소처분을 한 때부터 5일 이내에 국토교통부장관과 다른 시ㆍ도지사에게 통보한다(시행령 제29조제3항)."}]},{"종류":"표","제목":"벌금ㆍ금고 형 선고와 자격 관련 효과","머리":["선고 내용","효과","근거"],"행":[["이 법 위반으로 300만원 이상 벌금형","선고 후 3년이 지나지 않으면 개설등록 결격(자격취소는 아님)","법 제10조제1항제11호"],["금고 이상의 실형","집행 종료ㆍ면제 후 3년이 지나지 않으면 결격. 이 법 또는 직무 관련 형법 위반이면 자격취소","법 제10조제1항제4호, 제35조제1항제4호"],["금고 이상의 집행유예","유예기간 만료 후 2년이 지나지 않으면 결격. 이 법 또는 직무 관련 형법 위반이면 자격취소","법 제10조제1항제5호, 제35조제1항제4호"],["자격취소","취소된 후 3년이 지나지 않으면 개설등록 결격","법 제10조제1항제6호"]]}],"함정":"300만원 이상 벌금이라는 숫자는 결격사유 조문(제10조)의 것인데 자격취소 사유로 잘못 옮겨 놓았다. 자격취소는 금고 이상의 형이 기준이다. 나머지 네 선지는 법 제35조와 시행령 제29조의 문언 그대로라 옳다.","개정":"자격취소 후 통보 문언이 「국토교통부장관에게 보고하고 다른 시ㆍ도지사에게 통지」에서 「국토교통부장관과 다른 시ㆍ도지사에게 통보」로 정비되었다(시행령 제29조제3항, 2023.11.16.). 3번의 옳고 그름은 달라지지 않는다."}},{"i":"S2-2-1-중개사법-25","r":"S2","g":2,"c":2,"n":25,"s":"중개사법","q":"공인중개사법령상 지도ㆍ감독 및 행정처분에 관한 설명으로 옳은 것은?","b":null,"bs":"없음","img":[],"ch":["개업공인중개사가 최근 1년 이내에 이 법에 의하여 2회 이상 업무정지처분을 받고 다시 업무정지처분에 해당하는 행위를 한 경우, 등록관청은 중개사무소의 개설등록을 취소할 수 있다.","개업공인중개사가 이중으로 중개사무소의 개설등록을 한 경우, 등록관청은 청문을 거쳐 개설등록을 취소할 수 있다.","업무정지처분은 그 사유가 발생한 날부터 5년이 지난 때에는 이를 할 수 없다.","개업공인중개사가 거래계약서에 서명 및 날인을 하지 않은 경우, 등록관청이 명할 수 있는 업무정지기간의 기준은 3개월이다.","소속공인중개사가 등록하지 아니한 인장을 사용하여 중개행위를 한 경우, 시ㆍ도지사가 정하는 자격정지기간의 기준은 6개월이다."],"a":[4],"L":"중1-13","o":"변형","x":{"한줄":"거래계약서에 서명 및 날인을 하지 않은 경우 업무정지 기준은 3개월이다(시행규칙 별표 4 제2호 자목).","근거":[{"법령":"공인중개사법","조문":"제38조 제1항","원문":"①등록관청은 개업공인중개사가 다음 각 호의 어느 하나에 해당하는 경우에는 중개사무소의 개설등록을 취소하여야 한다.\n1. 개인인 개업공인중개사가 사망하거나 개업공인중개사인 법인이 해산한 경우\n2. 거짓이나 그 밖의 부정한 방법으로 중개사무소의 개설등록을 한 경우\n3. 제10조제1항제2호부터 제6호까지 또는 같은 항 제11호ㆍ제12호에 따른 결격사유에 해당하게 된 경우. 다만, 같은 항 제12호에 따른 결격사유에 해당하는 경우로서 그 사유가 발생한 날부터 2개월 이내에 그 사유를 해소한 경우에는 그러하지 아니하다.\n4. 제12조제1항의 규정을 위반하여 이중으로 중개사무소의 개설등록을 한 경우\n5. 제12조제2항의 규정을 위반하여 다른 개업공인중개사의 소속공인중개사ㆍ중개보조원 또는 개업공인중개사인 법인의 사원ㆍ임원이 된 경우\n5의2. 제15조제3항을 위반하여 중개보조원을 고용한 경우\n6. 제19조제1항의 규정을 위반하여 다른 사람에게 자기의 성명 또는 상호를 사용하여 중개업무를 하게 하거나 중개사무소등록증을 양도 또는 대여한 경우\n7. 업무정지기간 중에 중개업무를 하거나 자격정지처분을 받은 소속공인중개사로 하여금 자격정지기간 중에 중개업무를 하게 한 경우\n8. 최근 1년 이내에 이 법에 의하여 2회 이상 업무정지처분을 받고 다시 업무정지처분에 해당하는 행위를 한 경우"},{"법령":"공인중개사법","조문":"제39조 제3항","원문":"③제1항의 규정에 따른 업무정지처분은 같은 항 각 호의 어느 하나에 해당하는 사유가 발생한 날부터 3년이 지난 때에는 이를 할 수 없다."},{"법령":"공인중개사법 시행규칙","조문":"별표 4 제2호 자목","원문":"자. 법 제26조제2항을 위반하여 거래계약서에 서명ㆍ날인을 하지 않은 경우 / 근거 법조문 법 제39조제1항제9호 / 업무정지 3개월"},{"법령":"공인중개사법 시행규칙","조문":"별표 3 제2호","원문":"2. 법 제16조의 규정을 위반하여 인장등록을 하지 아니하거나 등록하지 아니한 인장을 사용한 경우 / 법 제36조제1항제2호 / 자격정지 3월"}],"선지":[{"번호":1,"판정":"틀림","설명":"최근 1년 이내 업무정지 2회 이상을 받고 다시 업무정지 사유에 해당하면 등록을 반드시 취소한다(법 제38조제1항제8호). 재량이 아니다."},{"번호":2,"판정":"틀림","설명":"이중 개설등록은 필요적 취소 사유다(법 제38조제1항제4호). 청문은 거치지만 취소할 수 있는 것이 아니라 취소하여야 한다(같은 조 제3항)."},{"번호":3,"판정":"틀림","설명":"업무정지처분은 사유가 발생한 날부터 3년이 지나면 할 수 없다(법 제39조제3항)."},{"번호":4,"판정":"옳음","설명":"거래계약서 서명 및 날인 누락은 법 제39조제1항제9호 사유이고 업무정지 3개월이다(시행규칙 별표 4)."},{"번호":5,"판정":"틀림","설명":"등록하지 않은 인장을 사용한 소속공인중개사의 자격정지 기준은 3월이다(시행규칙 별표 3 제2호). 6월은 이중소속, 거래계약서 거짓 기재, 금지행위의 기준이다."}],"개념":[{"종류":"비교","제목":"등록취소: 필요적 사유와 임의적 사유 (법 제38조)","왼쪽":{"이름":"필요적 취소(제1항, 반드시 취소)","항목":["개업공인중개사 사망 또는 법인 해산","거짓이나 부정한 방법으로 등록","결격사유 해당(제10조제1항제2호~제6호, 제11호ㆍ제12호)","이중으로 개설등록","이중소속(다른 개업공인중개사의 소속공인중개사ㆍ중개보조원ㆍ법인 사원ㆍ임원이 된 경우)","중개보조원 초과 고용(제15조제3항 위반)","등록증 양도ㆍ대여 또는 성명ㆍ상호 사용 허용","업무정지 기간 중 중개업무 또는 자격정지 중인 소속공인중개사에게 업무 수행 지시","최근 1년 이내 업무정지 2회 이상 후 다시 업무정지 해당 행위"]},"오른쪽":{"이름":"임의적 취소(제2항, 취소할 수 있음)","항목":["등록기준 미달","둘 이상의 중개사무소 설치","임시 중개시설물 설치","겸업 제한 위반","계속 6개월 초과 휴업","정보 비공개 요청 위반 등 제23조제3항 위반","거래계약서 거짓 기재 또는 이중 작성","손해배상책임 보장 조치 없이 업무 개시","금지행위(제33조제1항) 위반","최근 1년 이내 3회 이상 업무정지 또는 과태료 후 다시 해당 행위","사업자단체 공정거래법 위반 처분 2년 이내 2회 이상"]}},{"종류":"표","제목":"업무정지ㆍ자격정지 기준과 가감 (시행규칙 별표 3ㆍ별표 4, 제22조)","머리":["위반 행위","개업공인중개사 업무정지","소속공인중개사 자격정지"],"행":[["등록하지 않은 인장 사용 또는 인장 미등록","3개월","3월"],["중개대상물확인ㆍ설명서 서명ㆍ날인 누락","3개월","3월"],["거래계약서 서명ㆍ날인 누락","3개월","3월"],["성실ㆍ정확한 확인ㆍ설명 의무 위반","과태료 500만원 이하(법 제51조제2항제1호의6)","3월"],["거래계약서에 거래금액 거짓 기재 또는 이중 작성","임의적 등록취소 사유","6월"],["둘 이상의 중개사무소에 소속","-","6월"],["금지행위 위반","임의적 등록취소 사유","6월"],["가중과 감경","위반행위가 둘 이상이면 가장 무거운 기준의 2분의 1 범위에서 가중. 감경은 개별기준의 2분의 1 범위. 총 업무정지기간은 6개월을 넘지 못함","기준의 2분의 1 범위에서 가중 또는 감경. 가중해도 6월 초과 불가"],["처분 가능 기간","사유 발생일부터 3년 이내","-"]]}],"함정":"1번과 2번은 필요적 취소 사유를 임의적 취소(취소할 수 있다)로 바꾼 문장이다. 3번의 3년을 5년으로, 5번의 인장 위반 3월을 이중소속의 6월로 바꾼 것도 같은 유형이다. 인장 위반은 개업공인중개사 업무정지도 3개월, 소속공인중개사 자격정지도 3월로 같다."}},{"i":"S2-2-1-중개사법-26","r":"S2","g":2,"c":2,"n":26,"s":"중개사법","q":"공인중개사법령상 소속공인중개사로서 업무를 수행하는 기간 동안 발생한 사유 중 자격정지사유로 규정되어 있지 않은 것은?","b":null,"bs":"없음","img":[],"ch":["둘 이상의 중개사무소에 소속된 경우","성실ㆍ정확하게 중개대상물의 확인ㆍ설명을 하지 않은 경우","등록관청에 등록하지 않은 인장을 사용하여 중개행위를 한 경우","｢공인중개사법｣을 위반하여 징역형의 선고를 받은 경우","중개대상물의 매매를 업으로 하는 행위를 한 경우"],"a":[4],"L":"중1-13","o":"기출","x":{"한줄":"징역형을 선고받은 경우는 자격정지 사유가 아니라 자격취소 사유다. 자격정지 사유는 법 제36조제1항의 7가지로 한정된다.","근거":[{"법령":"공인중개사법","조문":"제36조 제1항","원문":"①시ㆍ도지사는 공인중개사가 소속공인중개사로서 업무를 수행하는 기간 중에 다음 각 호의 어느 하나에 해당하는 경우에는 6개월의 범위 안에서 기간을 정하여 그 자격을 정지할 수 있다.\n1. 제12조제2항의 규정을 위반하여 둘 이상의 중개사무소에 소속된 경우\n2. 제16조의 규정을 위반하여 인장등록을 하지 아니하거나 등록하지 아니한 인장을 사용한 경우\n3. 제25조제1항의 규정을 위반하여 성실ㆍ정확하게 중개대상물의 확인ㆍ설명을 하지 아니하거나 설명의 근거자료를 제시하지 아니한 경우\n4. 제25조제4항의 규정을 위반하여 중개대상물확인ㆍ설명서에 서명 및 날인을 하지 아니한 경우\n5. 제26조제2항의 규정을 위반하여 거래계약서에 서명 및 날인을 하지 아니한 경우\n6. 제26조제3항의 규정을 위반하여 거래계약서에 거래금액 등 거래내용을 거짓으로 기재하거나 서로 다른 둘 이상의 거래계약서를 작성한 경우\n7. 제33조제1항 각 호에 규정된 금지행위를 한 경우"},{"법령":"공인중개사법","조문":"제35조 제1항 제4호","원문":"①시ㆍ도지사는 공인중개사가 다음 각 호의 어느 하나에 해당하는 경우에는 그 자격을 취소하여야 한다.\n1. 부정한 방법으로 공인중개사의 자격을 취득한 경우\n2. 제7조제1항의 규정을 위반하여 다른 사람에게 자기의 성명을 사용하여 중개업무를 하게 하거나 공인중개사자격증을 양도 또는 대여한 경우\n3. 제36조에 따른 자격정지처분을 받고 그 자격정지기간 중에 중개업무를 행한 경우(다른 개업공인중개사의 소속공인중개사ㆍ중개보조원 또는 법인인 개업공인중개사의 사원ㆍ임원이 되는 경우를 포함한다)\n4. 이 법 또는 공인중개사의 직무와 관련하여 「형법」 제114조, 제231조, 제234조, 제347조, 제355조 또는 제356조를 위반하여 금고 이상의 형(집행유예를 포함한다)을 선고받은 경우\n4. 이 법 또는 공인중개사의 직무와 관련하여 「형법」 제114조, 제231조, 제234조, 제347조, 제355조 또는 제356조를 위반하여 금고 이상의 형(집행유예를 포함한다)을 선고받은 경우"},{"법령":"공인중개사법","조문":"제33조 제1항 제1호","원문":"① 개업공인중개사등은 다음 각 호의 행위를 하여서는 아니된다.\n1. 제3조에 따른 중개대상물의 매매를 업으로 하는 행위\n2. 제9조에 따른 중개사무소의 개설등록을 하지 아니하고 중개업을 영위하는 자인 사실을 알면서 그를 통하여 중개를 의뢰받거나 그에게 자기의 명의를 이용하게 하는 행위\n3. 사례ㆍ증여 그 밖의 어떠한 명목으로도 제32조에 따른 보수 또는 실비를 초과하여 금품을 받는 행위\n4. 해당 중개대상물의 거래상의 중요사항에 관하여 거짓된 언행 그 밖의 방법으로 중개의뢰인의 판단을 그르치게 하는 행위\n5. 관계 법령에서 양도ㆍ알선 등이 금지된 부동산의 분양ㆍ임대 등과 관련 있는 증서 등의 매매ㆍ교환 등을 중개하거나 그 매매를 업으로 하는 행위\n6. 중개의뢰인과 직접 거래를 하거나 거래당사자 쌍방을 대리하는 행위\n7. 탈세 등 관계 법령을 위반할 목적으로 소유권보존등기 또는 이전등기를 하지 아니한 부동산이나 관계 법령의 규정에 의하여 전매 등 권리의 변동이 제한된 부동산의 매매를 중개하는 등 부동산투기를 조장하는 행위\n8. 부당한 이익을 얻거나 제3자에게 부당한 이익을 얻게 할 목적으로 거짓으로 거래가 완료된 것처럼 꾸미는 등 중개대상물의 시세에 부당한 영향을 주거나 줄 우려가 있는 행위\n9. 단체를 구성하여 특정 중개대상물에 대하여 중개를 제한하거나 단체 구성원 이외의 자와 공동중개를 제한하는 행위\n1. 제3조에 따른 중개대상물의 매매를 업으로 하는 행위"}],"선지":[{"번호":1,"판정":"옳음","설명":"둘 이상의 중개사무소에 소속된 경우는 자격정지 사유다(법 제36조제1항제1호). 기준은 6월이다."},{"번호":2,"판정":"옳음","설명":"확인ㆍ설명을 성실ㆍ정확하게 하지 않으면 자격정지 사유다(법 제36조제1항제3호). 기준은 3월이다."},{"번호":3,"판정":"옳음","설명":"인장등록을 하지 않거나 등록하지 않은 인장을 사용하면 자격정지 사유다(법 제36조제1항제2호). 기준은 3월이다."},{"번호":4,"판정":"틀림","설명":"이 법 위반으로 금고 이상의 형을 선고받으면 자격을 취소한다(법 제35조제1항제4호). 자격정지 사유 7가지에는 형 선고가 없다."},{"번호":5,"판정":"옳음","설명":"중개대상물의 매매업은 금지행위(법 제33조제1항제1호)이고, 금지행위 위반은 자격정지 사유다(법 제36조제1항제7호). 기준은 6월이다."}],"개념":[{"종류":"표","제목":"소속공인중개사 자격정지 사유와 기준 (법 제36조, 시행규칙 별표 3)","머리":["호","자격정지 사유","기준"],"행":[["1","둘 이상의 중개사무소에 소속(제12조제2항)","6월"],["2","인장등록을 하지 않았거나 등록하지 않은 인장 사용(제16조)","3월"],["3","성실ㆍ정확한 확인ㆍ설명 의무 위반 또는 근거자료 미제시(제25조제1항)","3월"],["4","중개대상물확인ㆍ설명서에 서명 및 날인 누락(제25조제4항)","3월"],["5","거래계약서에 서명 및 날인 누락(제26조제2항)","3월"],["6","거래계약서에 거래금액 등 거짓 기재 또는 서로 다른 둘 이상의 계약서 작성(제26조제3항)","6월"],["7","금지행위(제33조제1항 각 호) 위반","6월"]]},{"종류":"비교","제목":"자격취소와 자격정지","왼쪽":{"이름":"자격취소(법 제35조)","항목":["처분: 시ㆍ도지사가 반드시 취소","청문 필수","사유: 부정 취득, 자격증 양도ㆍ대여 또는 성명 사용 허용, 자격정지 중 중개업무, 금고 이상의 형","효과: 자격증 반납, 3년간 개설등록 결격"]},"오른쪽":{"이름":"자격정지(법 제36조)","항목":["처분: 시ㆍ도지사가 6개월 범위에서 정지할 수 있음","사유: 소속공인중개사로 업무를 수행하는 기간 중 7가지","기준은 시행규칙 별표 3, 2분의 1 범위에서 가감","등록관청은 사유를 알게 되면 지체 없이 시ㆍ도지사에게 통보"]}}],"함정":"형 선고는 처벌과 관련되어 있어서 정지 사유로 보이지만, 형 선고는 자격취소 쪽에 있다. 2번과 5번은 중개 실무 의무를 어긴 경우와 금지행위 위반이라 자격정지 목록에 들어 있다. 자격정지 사유는 소속공인중개사로 일한 기간 중에 생긴 7가지로 한정된다."}},{"i":"S2-2-1-중개사법-27","r":"S2","g":2,"c":2,"n":27,"s":"중개사법","q":"공인중개사법령상 공인중개사의 자격취소 등에 관한 설명으로 틀린 것은?","b":null,"bs":"없음","img":[],"ch":["공인중개사의 자격취소처분은 청문을 거쳐 중개사무소의 개설등록증을 교부한 시ㆍ도지사가 행한다.","공인중개사가 자격정지처분을 받은 기간 중에 법인인 개업공인중개사의 임원이 되는 경우 시ㆍ도지사는 그 자격을 취소하여야 한다.","자격취소처분을 받아 공인중개사자격증을 반납하려는 자는 그 처분을 받은 날부터 7일 이내에 반납해야 한다.","시ㆍ도지사는 공인중개사의 자격취소처분을 한 때에는 5일 이내에 이를 국토교통부장관과 다른 시ㆍ도지사에게 통보하여야 한다.","분실로 인하여 공인중개사자격증을 반납할 수 없는 자는 자격증 반납을 대신하여 그 이유를 기재한 사유서를 시ㆍ도지사에게 제출하여야 한다."],"a":[1],"L":"중1-13","o":"기출","x":{"한줄":"자격취소처분은 자격증을 교부한 시ㆍ도지사가 한다. 개설등록증을 교부한 기관은 등록관청이라 처분권자가 아니다.","근거":[{"법령":"공인중개사법 시행령","조문":"제29조 제1항 제2항","원문":"①법 제35조의 규정에 따른 공인중개사의 자격취소처분 및 법 제36조의 규정에 따른 자격정지처분은 그 공인중개사자격증(이하 \"자격증\"이라 한다)을 교부한 시ㆍ도지사가 행한다.\n②자격증을 교부한 시ㆍ도지사와 공인중개사 사무소의 소재지를 관할하는 시ㆍ도지사가 서로 다른 경우에는 공인중개사 사무소의 소재지를 관할하는 시ㆍ도지사가 자격취소처분 또는 자격정지처분에 필요한 절차를 모두 이행한 후 자격증을 교부한 시ㆍ도지사에게 통보하여야 한다."},{"법령":"공인중개사법","조문":"제35조 제1항 제3호","원문":"①시ㆍ도지사는 공인중개사가 다음 각 호의 어느 하나에 해당하는 경우에는 그 자격을 취소하여야 한다.\n1. 부정한 방법으로 공인중개사의 자격을 취득한 경우\n2. 제7조제1항의 규정을 위반하여 다른 사람에게 자기의 성명을 사용하여 중개업무를 하게 하거나 공인중개사자격증을 양도 또는 대여한 경우\n3. 제36조에 따른 자격정지처분을 받고 그 자격정지기간 중에 중개업무를 행한 경우(다른 개업공인중개사의 소속공인중개사ㆍ중개보조원 또는 법인인 개업공인중개사의 사원ㆍ임원이 되는 경우를 포함한다)\n4. 이 법 또는 공인중개사의 직무와 관련하여 「형법」 제114조, 제231조, 제234조, 제347조, 제355조 또는 제356조를 위반하여 금고 이상의 형(집행유예를 포함한다)을 선고받은 경우\n3. 제36조에 따른 자격정지처분을 받고 그 자격정지기간 중에 중개업무를 행한 경우(다른 개업공인중개사의 소속공인중개사ㆍ중개보조원 또는 법인인 개업공인중개사의 사원ㆍ임원이 되는 경우를 포함한다)"},{"법령":"공인중개사법 시행규칙","조문":"제21조","원문":"제21조(공인중개사자격증의 반납) 법 제35조제3항의 규정에 따라 공인중개사자격증을 반납하고자 하는 자는 자격취소처분을 받은 날부터 7일 이내에 그 공인중개사자격증을 교부한 시ㆍ도지사에게 공인중개사자격증을 반납하여야 한다."},{"법령":"공인중개사법","조문":"제35조 제4항","원문":"④분실 등의 사유로 인하여 제3항에 따라 공인중개사자격증을 반납할 수 없는 자는 제3항에도 불구하고 자격증 반납을 대신하여 그 이유를 기재한 사유서를 시ㆍ도지사에게 제출하여야 한다."}],"선지":[{"번호":1,"판정":"틀림","설명":"자격취소와 자격정지는 그 공인중개사자격증을 교부한 시ㆍ도지사가 행한다(시행령 제29조제1항). 중개사무소 개설등록증은 등록관청이 교부한다."},{"번호":2,"판정":"옳음","설명":"자격정지 기간 중에 법인의 임원이 되는 경우도 중개업무를 행한 것에 포함되어 필요적 취소 사유다(법 제35조제1항제3호)."},{"번호":3,"판정":"옳음","설명":"자격취소처분을 받은 날부터 7일 이내에 자격증을 교부한 시ㆍ도지사에게 반납한다(시행규칙 제21조)."},{"번호":4,"판정":"옳음","설명":"처분 후 5일 이내에 국토교통부장관과 다른 시ㆍ도지사에게 통보한다(시행령 제29조제3항)."},{"번호":5,"판정":"옳음","설명":"분실처럼 반납할 수 없으면 사유서로 갈음한다(법 제35조제4항)."}],"개념":[{"종류":"표","제목":"자격취소 사유 4가지 (법 제35조제1항)","머리":["호","사유","특징"],"행":[["1","부정한 방법으로 공인중개사 자격 취득","-"],["2","다른 사람에게 자기 성명을 사용해 중개업무를 하게 하거나 자격증을 양도ㆍ대여","형사처벌: 1년 이하 징역 또는 1천만원 이하 벌금"],["3","자격정지처분을 받고 정지기간 중에 중개업무를 행함","다른 개업공인중개사의 소속공인중개사ㆍ중개보조원이 되거나 법인의 사원ㆍ임원이 되는 경우 포함"],["4","이 법 또는 직무와 관련해 형법 제114조, 제231조, 제234조, 제347조, 제355조, 제356조를 위반하여 금고 이상의 형을 선고받음","집행유예 포함"]]},{"종류":"표","제목":"반납ㆍ통보 기한과 관련 기관","머리":["대상","기한","상대방","근거"],"행":[["자격취소를 받은 자의 자격증 반납","처분을 받은 날부터 7일 이내","자격증을 교부한 시ㆍ도지사","시행규칙 제21조"],["등록취소를 받은 자의 등록증 반납","처분을 받은 날부터 7일 이내","등록관청","시행규칙 제24조제1항"],["자격증 분실 등 반납 불가","반납을 대신해 사유서 제출","시ㆍ도지사","법 제35조제4항"],["시ㆍ도지사의 자격취소 통보","처분을 한 때부터 5일 이내","국토교통부장관, 다른 시ㆍ도지사","시행령 제29조제3항"],["자격증 반납 불이행 과태료","100만원 이하, 시ㆍ도지사가 부과ㆍ징수","-","법 제51조제3항제6호ㆍ제5항제2호"]]}],"함정":"1번은 자격증과 개설등록증을 바꿔 쓴 문장이다. 자격 문제는 자격증을 교부한 시ㆍ도지사, 개설등록 문제는 등록관청으로 나눠 읽는다. 2번의 법인 임원이 되는 경우는 자격취소 사유 제3호의 괄호 안에 적혀 있다.","개정":"자격취소 후 통보 문언이 「국토교통부장관에게 보고」에서 「국토교통부장관과 다른 시ㆍ도지사에게 통보」로 정비되었다(시행령 제29조제3항, 2023.11.16.). 4번은 옳은 문장으로 유지된다."}},{"i":"S2-2-1-중개사법-28","r":"S2","g":2,"c":2,"n":28,"s":"중개사법","q":"공인중개사법령상 벌칙 및 과태료에 관한 설명으로 옳은 것은?","b":null,"bs":"없음","img":[],"ch":["중개사무소등록증을 다른 사람에게 양도 또는 대여한 개업공인중개사는 3년 이하의 징역 또는 3천만원 이하의 벌금에 처한다.","연수교육을 정당한 사유 없이 받지 아니한 자에게는 100만원 이하의 과태료를 부과한다.","중개사무소의 개설등록을 하지 아니하고 중개업을 한 자는 1년 이하의 징역 또는 1천만원 이하의 벌금에 처한다.","소속공인중개사가 중개업무에 관하여 이 법의 벌칙 규정에 해당하는 위반행위를 한 경우, 개업공인중개사는 상당한 주의와 감독을 게을리하지 않았더라도 행위자와 함께 벌금형을 받는다.","공인중개사자격증을 반납하지 아니한 자에 대한 100만원 이하의 과태료는 시ㆍ도지사가 부과ㆍ징수한다."],"a":[5],"L":"중1-14","o":"변형","x":{"한줄":"자격증 미반납 과태료(100만원 이하)와 연수교육 불이행 과태료는 시ㆍ도지사가 부과ㆍ징수한다(법 제51조제5항제2호).","근거":[{"법령":"공인중개사법","조문":"제51조 제5항","원문":"⑤ 제2항 및 제3항에 따른 과태료는 대통령령으로 정하는 바에 따라 다음 각 호의 자가 각각 부과ㆍ징수한다.\n1. 제2항제1호의2ㆍ제1호의3ㆍ제1호의5, 제6호부터 제8호까지, 제8호의2 및 제9호의 경우: 국토교통부장관\n2. 제2항제5호의2 및 제3항제6호의 경우: 시ㆍ도지사\n3. 삭제<2014.1.28>\n4. 제2항제1호ㆍ제1호의4ㆍ제1호의6, 제3항제1호ㆍ제2호ㆍ제2호의2, 제3호부터 제5호까지 및 제7호의 경우: 등록관청"},{"법령":"공인중개사법","조문":"제49조 제1항 제7호","원문":"①다음 각 호의 어느 하나에 해당하는 자는 1년 이하의 징역 또는 1천만원 이하의 벌금에 처한다.\n1. 제7조제1항 또는 제2항을 위반하여 다른 사람에게 자기의 성명을 사용하여 중개업무를 하게 하거나 공인중개사자격증을 양도ㆍ대여한 자 또는 다른 사람의 공인중개사자격증을 양수ㆍ대여받은 자\n1의2. 제7조제3항을 위반하여 같은 조 제1항 및 제2항에서 금지한 행위를 알선한 자\n2. 제8조의 규정을 위반하여 공인중개사가 아닌 자로서 공인중개사 또는 이와 유사한 명칭을 사용한 자\n3. 제12조의 규정을 위반하여 이중으로 중개사무소의 개설등록을 하거나 둘 이상의 중개사무소에 소속된 자\n4. 제13조제1항의 규정을 위반하여 둘 이상의 중개사무소를 둔 자\n5. 제13조제2항의 규정을 위반하여 임시 중개시설물을 설치한 자\n5의2. 제15조제3항을 위반하여 중개보조원을 고용한 자\n6. 제18조제2항의 규정을 위반하여 개업공인중개사가 아닌 자로서 \"공인중개사사무소\", \"부동산중개\" 또는 이와 유사한 명칭을 사용한 자\n6의2. 제18조의2제3항을 위반하여 개업공인중개사가 아닌 자로서 중개업을  하기 위하여 중개대상물에 대한 표시ㆍ광고를 한 자\n7. 제19조제1항 또는 제2항을 위반하여 다른 사람에게 자기의 성명 또는 상호를 사용하여 중개업무를 하게 하거나 중개사무소등록증을 다른 사람에게 양도ㆍ대여한 자 또는 다른 사람의 성명ㆍ상호를 사용하여 중개업무를 하거나 중개사무소등록증을 양수ㆍ대여받은 자\n7의2. 제19조제3항을 위반하여 같은 조 제1항 및 제2항에서 금지한 행위를 알선한 자\n8. 제24조제4항의 규정을 위반하여 정보를 공개한 자\n9. 제29조제2항의 규정을 위반하여 업무상 비밀을 누설한 자\n10. 제33조제1항제1호부터 제4호까지의 규정을 위반한 자\n7. 제19조제1항 또는 제2항을 위반하여 다른 사람에게 자기의 성명 또는 상호를 사용하여 중개업무를 하게 하거나 중개사무소등록증을 다른 사람에게 양도ㆍ대여한 자 또는 다른 사람의 성명ㆍ상호를 사용하여 중개업무를 하거나 중개사무소등록증을 양수ㆍ대여받은 자"},{"법령":"공인중개사법","조문":"제48조 제1호","원문":"1. 제9조에 따른 중개사무소의 개설등록을 하지 아니하고 중개업을 한 자"},{"법령":"공인중개사법","조문":"제50조","원문":"제50조(양벌규정) 소속공인중개사ㆍ중개보조원 또는 개업공인중개사인 법인의 사원ㆍ임원이 중개업무에 관하여 제48조 또는 제49조의 규정에 해당하는 위반행위를 한 때에는 그 행위자를 벌하는 외에 그 개업공인중개사에 대하여도 해당 조에 규정된 벌금형을 과한다. 다만, 그 개업공인중개사가 그 위반행위를 방지하기 위하여 해당 업무에 관하여 상당한 주의와 감독을 게을리하지 아니한 경우에는 그러하지 아니하다."}],"선지":[{"번호":1,"판정":"틀림","설명":"등록증을 양도ㆍ대여한 자는 1년 이하의 징역 또는 1천만원 이하의 벌금이다(법 제49조제1항제7호). 3년 이하는 무등록 중개업, 부정 등록, 금지행위 제5호~제9호 위반이다(법 제48조)."},{"번호":2,"판정":"틀림","설명":"연수교육 불이행 과태료는 500만원 이하다(법 제51조제2항제5호의2)."},{"번호":3,"판정":"틀림","설명":"무등록 중개업은 3년 이하의 징역 또는 3천만원 이하의 벌금이다(법 제48조제1호)."},{"번호":4,"판정":"틀림","설명":"개업공인중개사가 위반행위를 방지하기 위해 상당한 주의와 감독을 게을리하지 않았다면 벌금형을 과하지 않는다(법 제50조 단서)."},{"번호":5,"판정":"옳음","설명":"자격증 반납 의무 위반은 100만원 이하 과태료이고(법 제51조제3항제6호) 시ㆍ도지사가 부과ㆍ징수한다(같은 조 제5항제2호)."}],"개념":[{"종류":"표","제목":"징역ㆍ벌금 구분 (법 제48조ㆍ제49조)","머리":["구분","행위","근거"],"행":[["3년 이하 징역 또는 3천만원 이하 벌금","무등록 중개업, 거짓이나 부정한 방법으로 등록","제48조제1호ㆍ제2호"],["3년 이하 징역 또는 3천만원 이하 벌금","금지행위 중 관계 법령상 양도ㆍ알선 금지 증서 매매 중개(제5호), 중개의뢰인과 직접 거래 또는 쌍방 대리(제6호), 투기 조장(제7호), 거짓 거래 꾸며 시세 교란(제8호), 단체 구성 중개 제한(제9호)","제48조제3호"],["3년 이하 징역 또는 3천만원 이하 벌금","누구든지 하는 시세 교란 목적의 업무방해(제33조제2항)","제48조제4호"],["1년 이하 징역 또는 1천만원 이하 벌금","자격증ㆍ등록증 양도ㆍ대여ㆍ양수ㆍ알선, 이중 등록ㆍ이중 소속, 둘 이상의 중개사무소, 임시 중개시설물, 중개보조원 초과 고용, 유사명칭 사용, 비밀 누설(피해자 의사에 반해 벌하지 않음)","제49조제1항"],["1년 이하 징역 또는 1천만원 이하 벌금","금지행위 중 매매업(제1호), 무등록자를 통한 중개 의뢰ㆍ명의 이용(제2호), 보수ㆍ실비 초과 금품 수수(제3호), 거래상 중요사항에 관한 거짓 언행(제4호)","제49조제1항제10호"]]},{"종류":"표","제목":"과태료의 금액과 부과권자 (법 제51조)","머리":["금액","대표 사유","부과ㆍ징수권자"],"행":[["500만원 이하","연수교육 불이행","시ㆍ도지사"],["500만원 이하","부당한 표시ㆍ광고, 중개보조원 신분 미고지, 확인ㆍ설명 불성실","등록관청"],["500만원 이하","공제사업 운용실적 미공시, 개선명령 불이행, 협회에 대한 보고ㆍ검사 거부 등","국토교통부장관"],["100만원 이하","자격증 미반납 또는 사유서 미제출","시ㆍ도지사"],["100만원 이하","등록증 미게시, 명칭 위반, 이전ㆍ휴폐업 신고 위반, 손해배상 설명 위반, 등록증 미반납","등록관청"]]}],"함정":"1번과 3번은 형량을 서로 바꿔 놓은 문장이다. 등록증 대여는 1년 이하, 무등록 중개업은 3년 이하다. 4번은 양벌규정에 면책 단서가 있다는 점을 빼고 읽은 오답이다. 과태료는 금액만 외우지 말고 부과권자 세 부류(국토교통부장관, 시ㆍ도지사, 등록관청)까지 함께 정리한다."}},{"i":"S2-2-1-중개사법-29","r":"S2","g":2,"c":2,"n":29,"s":"중개사법","q":"부동산 거래신고 등에 관한 법령상 부동산 거래신고에 관한 설명으로 옳은 것은?","b":null,"bs":"없음","img":[],"ch":["부동산의 매매계약을 체결한 경우 거래당사자는 계약 체결일부터 60일 이내에 신고관청에 공동으로 신고하여야 한다.","거래당사자 중 일방이 「지방공기업법」에 따른 지방공사인 경우에는 그 지방공사가 신고를 하여야 한다.","거래당사자가 부동산거래계약 신고서를 신고관청에 제출한 때에 매수인은 「부동산등기 특별조치법」에 따른 검인을 받은 것으로 본다.","「주택법」에 따른 주택의 공급계약은 부동산 거래신고의 대상이 아니다.","수도권에 소재하는 실제 거래가격 1억원의 토지를 매수하는 경우 신고서와 함께 제출하는 토지취득자금 조달 및 토지이용계획서는 매도인과 매수인이 공동으로 서명 또는 날인하여야 한다."],"a":[2],"L":"중2-1","o":"변형","x":{"한줄":"거래당사자 중 일방이 국가, 지방자치단체 또는 공공기관ㆍ지방직영기업ㆍ지방공사ㆍ지방공단이면 그 국가등이 신고한다(법 제3조제1항 단서, 시행령 제3조제2항).","근거":[{"법령":"부동산 거래신고 등에 관한 법률","조문":"제3조 제1항","원문":"① 거래당사자는 다음 각 호의 어느 하나에 해당하는 계약을 체결한 경우 그 실제 거래가격 등 대통령령으로 정하는 사항을 거래계약의 체결일부터 30일 이내에 그 권리의 대상인 부동산등(권리에 관한 계약의 경우에는 그 권리의 대상인 부동산을 말한다)의 소재지를 관할하는 시장(구가 설치되지 아니한 시의 시장 및 특별자치시장과 특별자치도 행정시의 시장을 말한다)ㆍ군수 또는 구청장(이하 \"신고관청\"이라 한다)에게 공동으로 신고하여야 한다. 다만, 거래당사자 중 일방이 국가, 지방자치단체, 대통령령으로 정하는 자의 경우(이하 \"국가등\"이라 한다)에는 국가등이 신고를 하여야 한다.\n1. 부동산의 매매계약\n2. 「택지개발촉진법」, 「주택법」 등 대통령령으로 정하는 법률에 따른 부동산에 대한 공급계약\n3. 다음 각 목의 어느 하나에 해당하는 지위의 매매계약\n가. 제2호에 따른 계약을 통하여 부동산을 공급받는 자로 선정된 지위\n나. 「도시 및 주거환경정비법」 제74조에 따른 관리처분계획의 인가 및 「빈집 및 소규모주택 정비에 관한 특례법」 제29조에 따른 사업시행계획인가로 취득한 입주자로 선정된 지위"},{"법령":"부동산 거래신고 등에 관한 법률 시행령","조문":"제3조 제2항","원문":"② 법 제3조제1항 각 호 외의 부분 단서에서 \"대통령령으로 정하는 자\"란 다음 각 호의 기관을 말한다.\n1. 「공공기관의 운영에 관한 법률」에 따른 공공기관\n2. 「지방공기업법」에 따른 지방직영기업ㆍ지방공사 또는 지방공단"},{"법령":"부동산 거래신고 등에 관한 법률","조문":"제3조 제6항","원문":"⑥ 부동산등의 매수인은 신고인이 제5항에 따른 신고필증을 발급받은 때에 「부동산등기 특별조치법」 제3조제1항에 따른 검인을 받은 것으로 본다."},{"법령":"부동산 거래신고 등에 관한 법률 시행규칙","조문":"제2조 제8항","원문":"⑧ 영 별표 1 제4호 및 제5호에 따른 자금의 조달계획 및 토지의 이용계획을 신고해야 하는 경우에는 제1항부터 제4항까지의 규정에 따라 신고서를 제출할 때 매수인이 단독으로 서명 또는 날인한 별지 제1호의4서식의 토지취득자금 조달 및 토지이용계획서(이하 \"자금조달ㆍ토지이용계획서\"라 한다)를 신고관청에 함께 제출해야 한다."}],"선지":[{"번호":1,"판정":"틀림","설명":"신고 기한은 계약 체결일부터 30일 이내다(법 제3조제1항). 60일은 외국인등이 거래신고 대상이 아닌 계약(증여 등)으로 부동산을 취득했을 때의 기한이다(법 제8조제1항)."},{"번호":2,"판정":"옳음","설명":"시행령 제3조제2항이 공공기관, 지방직영기업ㆍ지방공사ㆍ지방공단을 국가등으로 정한다. 국가등이 당사자이면 국가등이 단독으로 신고서에 서명 또는 날인해 제출한다(시행규칙 제2조제2항)."},{"번호":3,"판정":"틀림","설명":"검인을 받은 것으로 보는 시점은 신고인이 신고필증을 발급받은 때다(법 제3조제6항)."},{"번호":4,"판정":"틀림","설명":"택지개발촉진법, 주택법 등에 따른 공급계약은 법 제3조제1항제2호의 신고 대상이다(시행령 제3조제3항제6호)."},{"번호":5,"판정":"틀림","설명":"자금조달ㆍ토지이용계획서는 매수인이 단독으로 서명 또는 날인해 제출한다(시행규칙 제2조제8항). 수도권등의 토지는 실제 거래가격 1억원 이상이면 제출 대상이다(시행령 별표 1 제4호)."}],"개념":[{"종류":"표","제목":"신고의무자와 신고 방법","머리":["경우","신고의무자","서명ㆍ날인 및 제출","근거"],"행":[["일반 매매 등","거래당사자","공동으로 서명 또는 날인하여 신고관청에 제출","법 제3조제1항, 시행규칙 제2조제1항"],["일방이 국가등","국가등","단독으로 서명 또는 날인","법 제3조제1항 단서, 시행규칙 제2조제2항"],["개업공인중개사가 거래계약서를 작성ㆍ교부","해당 개업공인중개사(공동중개이면 공동으로)","개업공인중개사가 서명 또는 날인","법 제3조제3항, 시행규칙 제2조제4항"],["일방이 신고를 거부","신고를 원하는 거래당사자 또는 개업공인중개사","단독으로 서명 또는 날인 + 거래계약서 사본, 계약금 지급 확인서류, 단독신고사유서 첨부","법 제3조제2항ㆍ제4항, 시행규칙 제2조제3항"],["소속공인중개사 대행","개업공인중개사의 위임을 받은 소속공인중개사","신분증명서를 보여주고 제출","시행규칙 제5조제2항"]]},{"종류":"표","제목":"주택ㆍ토지 매수 시 추가로 내는 서류 (시행령 별표 1, 시행규칙 제2조)","머리":["대상","추가 서류","서명ㆍ날인"],"행":[["법인이 주택 거래","법인 주택 거래계약 신고서(법인 등기현황, 임원 관계)","신고서와 함께 제출"],["법인이 주택 매수","주택취득자금 조달 및 입주계획서(투기과열지구는 증명서류 첨부)","매수인 단독"],["법인 외의 자가 6억원 이상 주택 매수 또는 투기과열지구ㆍ조정대상지역 주택 매수","주택취득자금 조달 및 입주계획서(투기과열지구는 증명서류 첨부)","매수인 단독"],["토지거래허가구역 안 주택 매수","주택취득자금 조달 및 입주계획서(증명서류 첨부)","매수인 단독"],["수도권등 1억원 이상, 그 밖의 지역 6억원 이상 토지 매수","토지취득자금 조달 및 토지이용계획서","매수인 단독"]]}],"함정":"1번은 외국인 취득신고의 60일을 거래신고 기한 30일과 바꿔 놓았다. 3번은 검인 간주 시점이 신고서 제출 시점이 아니라 신고필증 발급 시점이라는 점에서 틀렸다. 4번은 공급계약이 신고 대상에서 빠진다고 읽으면 틀린다. 공급계약에서 빠지는 것은 법인 현황 신고사항뿐이다. 5번은 서명 주체가 매수인 단독인 서류를 공동으로 바꿨다."}},{"i":"S2-2-1-중개사법-30","r":"S2","g":2,"c":2,"n":30,"s":"중개사법","q":"부동산 거래신고 등에 관한 법령상 부동산 거래신고 및 그 후속 절차에 관한 설명으로 틀린 것은?","b":null,"bs":"없음","img":[],"ch":["거래당사자 중 일방이 공동신고를 거부하여 단독으로 신고하는 경우에는 부동산거래계약 신고서에 단독으로 서명 또는 날인하여 제출하면 되고, 단독신고사유서는 제출하지 않아도 된다.","신고한 후 해당 거래계약이 해제된 경우 거래당사자는 해제가 확정된 날부터 30일 이내에 신고관청에 공동으로 해제등의 신고를 하여야 한다.","신고한 거래가격이 변경된 경우 거래당사자는 부동산등기법에 따른 등기신청 전에 신고관청에 변경 신고를 할 수 있다.","신고관청은 신고가격의 적정성을 검증한 결과를 해당 부동산의 소재지를 관할하는 세무관서의 장에게 통보하여야 한다.","개업공인중개사가 거래계약서를 작성ㆍ교부한 경우 신고사항에는 개업공인중개사의 인적사항과 중개사무소의 상호ㆍ전화번호 및 소재지가 포함된다."],"a":[1],"L":"중2-1","o":"변형","x":{"한줄":"단독신고는 거래계약서 사본, 계약금 지급 확인서류와 함께 단독신고사유서를 반드시 첨부해야 한다(시행규칙 제2조제3항).","근거":[{"법령":"부동산 거래신고 등에 관한 법률 시행규칙","조문":"제2조 제3항","원문":"③ 법 제3조제2항 또는 제4항에 따라 단독으로 부동산 거래계약을 신고하려는 자는 부동산거래계약 신고서에 단독으로 서명 또는 날인한 후 다음 각 호의 서류를 첨부하여 신고관청에 제출해야 한다. 이 경우 신고관청은 단독신고 사유에 해당하는지 여부를 확인해야 한다.\n1. 부동산 거래계약서 사본\n2. 영수증 사본 또는 통장 사본 등 계약금의 지급을 확인할 수 있는 서류\n3. 단독신고사유서"},{"법령":"부동산 거래신고 등에 관한 법률","조문":"제3조의2 제1항","원문":"① 거래당사자는 제3조에 따라 신고한 후 해당 거래계약이 해제, 무효 또는 취소(이하 \"해제등\"이라 한다)된 경우 해제등이 확정된 날부터 30일 이내에 해당 신고관청에 공동으로 신고하여야 한다. 다만, 거래당사자 중 일방이 신고를 거부하는 경우에는 국토교통부령으로 정하는 바에 따라 단독으로 신고할 수 있다."},{"법령":"부동산 거래신고 등에 관한 법률 시행규칙","조문":"제3조 제3항","원문":"③ 거래당사자 또는 개업공인중개사는 부동산 거래계약 신고 내용 중 다음 각 호의 어느 하나에 해당하는 사항이 변경된 경우에는 「부동산등기법」에 따른 부동산에 관한 등기신청 전에 신고관청에 신고 내용의 변경을 신고할 수 있다.\n1. 거래 지분 비율\n2. 거래 지분\n3. 거래대상 부동산등의 면적\n4. 계약의 조건 또는 기한\n5. 거래가격\n6. 중도금ㆍ잔금 및 지급일\n7. 공동매수의 경우 일부 매수인의 변경(매수인 중 일부가 제외되는 경우만 해당한다)\n8. 거래대상 부동산등이 다수인 경우 일부 부동산등의 변경(거래대상 부동산등 중 일부가 제외되는 경우만 해당한다)\n9. 위탁관리인의 성명, 주민등록번호, 주소 및 전화번호(휴대전화번호를 포함한다)"},{"법령":"부동산 거래신고 등에 관한 법률","조문":"제5조 제3항","원문":"③ 신고관청은 제2항에 따른 검증 결과를 해당 부동산의 소재지를 관할하는 세무관서의 장에게 통보하여야 하며, 통보받은 세무관서의 장은 해당 신고 내용을 국세 또는 지방세 부과를 위한 과세자료로 활용할 수 있다."},{"법령":"부동산 거래신고 등에 관한 법률 시행령","조문":"별표 1 제1호 자목","원문":"자. 개업공인중개사가 거래계약서를 작성ㆍ교부한 경우에는 다음의 사항 1) 개업공인중개사의 인적사항 2) 개업공인중개사가 「공인중개사법」 제9조에 따라 개설등록한 중개사무소의 상호ㆍ전화번호 및 소재지"}],"선지":[{"번호":1,"판정":"틀림","설명":"단독신고 때는 거래계약서 사본, 계약금 지급을 확인할 수 있는 서류, 단독신고사유서를 첨부한다. 신고관청이 단독신고 사유에 해당하는지 확인하기 때문이다(시행규칙 제2조제3항)."},{"번호":2,"판정":"옳음","설명":"해제, 무효 또는 취소가 확정된 날부터 30일 이내에 공동으로 신고한다(법 제3조의2제1항)."},{"번호":3,"판정":"옳음","설명":"거래가격은 변경신고 대상이고 등기신청 전에 신고할 수 있다(시행규칙 제3조제3항제5호)."},{"번호":4,"판정":"옳음","설명":"검증 결과는 소재지 관할 세무관서의 장에게 통보하고, 세무관서는 과세자료로 활용할 수 있다(법 제5조제3항)."},{"번호":5,"판정":"옳음","설명":"개업공인중개사의 인적사항과 중개사무소의 상호ㆍ전화번호ㆍ소재지는 공통 신고사항이다(시행령 별표 1 제1호 자목)."}],"개념":[{"종류":"비교","제목":"정정 신청과 변경 신고 (시행규칙 제3조)","왼쪽":{"이름":"정정 신청(잘못 적은 사항을 바로잡음)","항목":["거래당사자의 주소ㆍ전화번호","거래 지분 비율","개업공인중개사의 전화번호ㆍ상호ㆍ사무소 소재지","거래대상 건축물의 종류","거래대상 부동산등의 지목, 면적, 거래 지분 및 대지권비율","신고필증에 정정 사항을 표시하고 해당 부분에 서명 또는 날인해 제출","주소ㆍ전화번호 정정은 거래당사자 일방이 단독으로 신청 가능"]},"오른쪽":{"이름":"변경 신고(신고 후 바뀐 사항을 알림)","항목":["거래 지분 비율, 거래 지분","거래대상 부동산등의 면적","계약의 조건 또는 기한","거래가격","중도금ㆍ잔금 및 지급일","공동매수의 경우 일부 매수인의 변경(제외되는 경우만)","다수 부동산 중 일부 제외","위탁관리인의 인적사항","부동산등기법에 따른 등기신청 전에 변경 신고서 제출"]}},{"종류":"표","제목":"단독신고와 해제등 신고 서류","머리":["구분","신고 기한","방식","첨부 서류"],"행":[["거래신고(일방 거부)","계약 체결일부터 30일 이내","단독 서명 또는 날인","거래계약서 사본, 계약금 지급 확인서류, 단독신고사유서"],["해제등 신고(공동)","해제등이 확정된 날부터 30일 이내","공동 서명 또는 날인","부동산거래계약 해제등 신고서"],["해제등 신고(일방 거부)","해제등이 확정된 날부터 30일 이내","단독 서명 또는 날인","확정된 법원 판결문 등 해제등 확정 입증서류, 단독신고사유서"],["신고 후 발급","-","신고관청","거래신고는 신고필증, 해제등 신고는 해제등 확인서 발급"]]}],"함정":"단독신고 사유서를 빼도 된다고 쓴 1번이 답이다. 단독신고는 상대방 거부를 객관적으로 확인해야 해서 사유서와 증빙을 요구한다. 3번은 변경 신고를 해야 한다가 아니라 할 수 있다로 적혀 있어 의무가 아니라는 점까지 맞는다."}},{"i":"S2-2-1-중개사법-31","r":"S2","g":2,"c":2,"n":31,"s":"중개사법","q":"개업공인중개사가 외국인에게 부동산 거래신고 등에 관한 법령의 내용을 설명한 것으로 틀린 것은?","b":null,"bs":"없음","img":[],"ch":["외국인이 상속으로 대한민국 안의 부동산을 취득한 때에는 취득한 날부터 6개월 이내에 신고관청에 신고해야 한다.","외국인이 증여계약을 체결하여 대한민국 안의 부동산을 취득하는 경우에는 계약체결일부터 60일 이내에 신고관청에 신고해야 한다.","외국인이 군사기지 및 군사시설 보호구역 안의 토지를 허가 없이 취득하는 계약을 체결한 경우, 그 계약은 유효하고 과태료가 부과된다.","사원 또는 구성원의 2분의 1 이상이 대한민국의 국적을 보유하고 있지 아니한 개인인 법인은 외국인등에 해당한다.","외국인이 야생생물 특별보호구역 안의 토지를 취득하려는 경우에는 토지거래계약 허가를 받은 경우를 제외하고, 토지취득계약을 체결하기 전에 신고관청으로부터 토지취득의 허가를 받아야 한다."],"a":[3],"L":"중2-3","o":"변형","x":{"한줄":"허가를 받지 않고 체결한 토지취득계약은 효력이 발생하지 않는다. 계약이 유효하다는 말도, 과태료만 부과된다는 말도 틀렸고 2년 이하 징역 또는 2천만원 이하 벌금에 처한다.","근거":[{"법령":"부동산 거래신고 등에 관한 법률","조문":"제9조 제1항 제3항","원문":"① 제3조 및 제8조에도 불구하고 외국인등이 취득하려는 토지가 다음 각 호의 어느 하나에 해당하는 구역ㆍ지역 등에 있으면 토지를 취득하는 계약(이하 \"토지취득계약\"이라 한다)을 체결하기 전에 대통령령으로 정하는 바에 따라 신고관청으로부터 토지취득의 허가를 받아야 한다. 다만, 제11조에 따라 토지거래계약에 관한 허가를 받은 경우에는 그러하지 아니하다.\n1. 「군사기지 및 군사시설 보호법」 제2조제6호에 따른 군사기지 및 군사시설 보호구역, 그 밖에 국방목적을 위하여 외국인등의 토지취득을 특별히 제한할 필요가 있는 지역으로서 대통령령으로 정하는 지역\n2. 「문화유산의 보존 및 활용에 관한 법률」 제2조제3항에 따른 지정문화유산과 이를 위한 보호물 또는 보호구역\n2의2. 「자연유산의 보존 및 활용에 관한 법률」에 따라 지정된 천연기념물등과 이를 위한 보호물 또는 보호구역\n3. 「자연환경보전법」 제2조제12호에 따른 생태ㆍ경관보전지역\n4. 「야생생물 보호 및 관리에 관한 법률」 제27조에 따른 야생생물 특별보호구역\n③ 제1항을 위반하여 체결한 토지취득계약은 그 효력이 발생하지 아니한다."},{"법령":"부동산 거래신고 등에 관한 법률","조문":"제26조 제2항","원문":"② 제9조제1항에 따른 허가를 받지 아니하고 토지취득계약을 체결하거나 부정한 방법으로 허가를 받아 토지취득계약을 체결한 외국인등은 2년 이하의 징역 또는 2천만원 이하의 벌금에 처한다."},{"법령":"부동산 거래신고 등에 관한 법률","조문":"제8조 제1항 제2항","원문":"① 외국인등이 대한민국 안의 부동산등을 취득하는 계약(제3조제1항 각 호에 따른 계약은 제외한다)을 체결하였을 때에는 계약체결일부터 60일 이내에 대통령령으로 정하는 바에 따라 신고관청에 신고하여야 한다.\n② 외국인등이 상속ㆍ경매, 그 밖에 대통령령으로 정하는 계약 외의 원인으로 대한민국 안의 부동산등을 취득한 때에는 부동산등을 취득한 날부터 6개월 이내에 대통령령으로 정하는 바에 따라 신고관청에 신고하여야 한다."},{"법령":"부동산 거래신고 등에 관한 법률","조문":"제2조 제4호","원문":"4. \"외국인등\"이란 다음 각 목의 어느 하나에 해당하는 개인ㆍ법인 또는 단체를 말한다."}],"선지":[{"번호":1,"판정":"옳음","설명":"상속ㆍ경매 등 계약 외의 원인으로 취득하면 취득한 날부터 6개월 이내에 신고한다(법 제8조제2항)."},{"번호":2,"판정":"옳음","설명":"증여는 거래신고 대상 계약이 아니라서 법 제8조제1항에 따라 계약체결일부터 60일 이내에 외국인 취득신고를 한다."},{"번호":3,"판정":"틀림","설명":"법 제9조제1항을 위반해 체결한 토지취득계약은 효력이 발생하지 않는다(같은 조 제3항). 처벌은 2년 이하의 징역 또는 2천만원 이하의 벌금이다(법 제26조제2항)."},{"번호":4,"판정":"옳음","설명":"사원 또는 구성원의 2분의 1 이상이 외국 국적 개인인 법인은 외국인등이다(법 제2조제4호다목)."},{"번호":5,"판정":"옳음","설명":"야생생물 특별보호구역은 허가 대상 구역이다(법 제9조제1항제4호). 토지거래계약 허가를 받았으면 별도 허가는 필요 없다(같은 항 단서)."}],"개념":[{"종류":"표","제목":"외국인등의 부동산 취득ㆍ보유 신고와 허가","머리":["유형","의무","기한","위반 시"],"행":[["거래신고 대상 계약(매매 등)","법 제3조 거래신고","계약 체결일부터 30일","법 제28조 과태료"],["거래신고 대상이 아닌 계약(증여 등)","취득 신고","계약체결일부터 60일","300만원 이하 과태료"],["상속ㆍ경매ㆍ환매권 행사ㆍ법원 확정판결ㆍ법인 합병ㆍ건축물 신축 등","취득 신고","취득한 날부터 6개월","100만원 이하 과태료"],["국민ㆍ국내 법인이 외국인등으로 변경","계속보유 신고","변경된 날부터 6개월","100만원 이하 과태료"],["허가 대상 구역ㆍ지역의 토지","토지취득계약 체결 전 허가","신고관청 처리기간 군사 관련 구역 30일(부득이하면 30일 범위에서 연장), 그 밖의 구역 15일","계약은 효력 없음, 2년 이하 징역 또는 2천만원 이하 벌금"]]},{"종류":"표","제목":"외국인등의 토지취득 허가 대상 구역ㆍ지역 (법 제9조, 시행령 제6조)","머리":["구분","내용"],"행":[["군사 관련","군사기지 및 군사시설 보호구역, 그 밖에 국방목적상 필요한 지역(섬 지역, 군부대 주둔지와 인근, 국가중요시설과 인근)"],["문화유산","지정문화유산과 그 보호물 또는 보호구역"],["자연유산","천연기념물등과 그 보호물 또는 보호구역"],["생태ㆍ경관","생태ㆍ경관보전지역"],["야생생물","야생생물 특별보호구역"],["예외","토지거래계약 허가를 받은 경우에는 별도 허가 불필요"]]}],"함정":"허가가 필요한 구역에서 허가 없이 체결한 계약의 효력을 묻는 선지다. 거래신고 위반은 과태료 문제이지만 허가 위반은 계약이 무효이고 형사처벌 대상이다. 2번의 60일, 1번의 6개월은 각각 계약 취득과 계약 외 원인 취득에 대응하는 기한이다."}},{"i":"S2-2-1-중개사법-32","r":"S2","g":2,"c":2,"n":32,"s":"중개사법","q":"부동산 거래신고 등에 관한 법령상 토지거래계약 허가절차에 관한 설명으로 옳은 것은?","b":null,"bs":"없음","img":[],"ch":["허가관청은 토지거래계약 허가신청서를 받은 날부터 30일 이내에 허가 또는 불허가 처분을 하여야 한다.","토지거래계약 변경허가를 받으려는 자는 공동으로 토지거래계약 허가번호, 변경내용 및 변경사유 등을 기재한 신청서를 허가관청에 제출하여야 한다.","토지거래계약 허가신청은 토지의 매수인이 단독으로 하여야 한다.","허가구역을 지정하면서 면적을 따로 공고하지 않은 경우 도시지역 안 상업지역의 250제곱미터 토지거래계약에는 허가가 필요하지 않다.","자기의 거주용 주택용지로 이용하려고 토지거래계약 허가를 받은 자는 토지 취득일부터 4년 동안 허가받은 목적대로 이용하여야 한다."],"a":[2],"L":"중2-4","o":"변형","x":{"한줄":"변경허가 신청서에는 허가번호, 변경내용, 변경사유를 적고 공동으로 제출한다(시행령 제8조제2항).","근거":[{"법령":"부동산 거래신고 등에 관한 법률 시행령","조문":"제8조 제2항 제3항","원문":"② 법 제11조제1항 후단에 따른 토지거래계약 변경허가를 받으려는 자는 공동으로 다음 각 호의 사항을 기재한 신청서에 국토교통부령으로 정하는 서류를 첨부하여 허가관청에 제출하여야 한다.\n1. 제1항제1호부터 제3호까지의 사항\n2. 토지거래계약 허가번호\n3. 변경내용\n4. 변경사유\n③ 제1항 또는 제2항에 따른 신청서를 받은 허가관청은 지체 없이 필요한 조사를 하고 신청서를 받은 날부터 15일 이내에 허가ㆍ변경허가 또는 불허가 처분을 하여야 한다."},{"법령":"부동산 거래신고 등에 관한 법률","조문":"제11조 제1항","원문":"① 허가구역에 있는 토지에 관한 소유권ㆍ지상권(소유권ㆍ지상권의 취득을 목적으로 하는 권리를 포함한다)을 이전하거나 설정(대가를 받고 이전하거나 설정하는 경우만 해당한다)하는 계약(예약을 포함한다. 이하 \"토지거래계약\"이라 한다)을 체결하려는 당사자는 공동으로 대통령령으로 정하는 바에 따라 시장ㆍ군수 또는 구청장의 허가를 받아야 한다. 허가받은 사항을 변경하려는 경우에도 또한 같다."},{"법령":"부동산 거래신고 등에 관한 법률 시행령","조문":"제9조 제1항","원문":"① 법 제11조제2항제1호에서 \"대통령령으로 정하는 용도별 면적\"이란 다음 각 호의 구분에 따른 면적을 말한다. 다만, 국토교통부장관 또는 시ㆍ도지사가 허가구역을 지정할 당시 해당 지역에서의 거래실태 등을 고려하여 다음 각 호의 면적으로 하는 것이 타당하지 않다고 인정하여 해당 기준면적의 10퍼센트 이상 300퍼센트 이하의 범위에서 따로 정하여 공고한 경우에는 그에 따른다.\n1. 「국토의 계획 및 이용에 관한 법률」 제36조제1항제1호에 따른 도시지역(이하 \"도시지역\"이라 한다): 다음 각 목의 세부 용도지역별 구분에 따른 면적\n가. 주거지역: 60제곱미터\n나. 상업지역: 150제곱미터\n다. 공업지역: 150제곱미터\n라. 녹지지역: 200제곱미터\n마. 가목부터 라목까지의 구분에 따른 용도지역의 지정이 없는 구역: 60제곱미터\n2. 도시지역 외의 지역: 250제곱미터. 다만, 농지(「농지법」 제2조제1호에 따른 농지를 말한다. 이하 같다)의 경우에는 500제곱미터로 하고, 임야의 경우에는 1천제곱미터로 한다."},{"법령":"부동산 거래신고 등에 관한 법률 시행령","조문":"제14조 제2항","원문":"② 법 제17조제1항에서 \"대통령령으로 정하는 기간\"이란 다음 각 호의 구분에 따른 기간을 말한다.\n1. 법 제12조제1호가목부터 다목까지의 목적으로 허가를 받은 경우: 토지 취득일부터 2년\n2. 법 제12조제1호라목부터 바목까지의 목적으로 허가를 받은 경우: 토지 취득일부터 4년. 다만, 분양을 목적으로 허가를 받은 토지로서 개발에 착수한 후 토지 취득일부터 4년 이내에 분양을 완료한 경우에는 분양을 완료한 때에 4년이 지난 것으로 본다.\n3. 제10조제2항제1호에 따라 대체토지를 취득하기 위하여 허가를 받은 경우: 토지 취득일부터 2년\n4. 제10조제2항제2호에 따라 현상보존의 목적으로 토지를 취득하기 위하여 허가를 받은 경우: 토지 취득일부터 5년\n5. 제1호부터 제4호까지의 경우 외의 경우: 토지 취득일부터 5년"}],"선지":[{"번호":1,"판정":"틀림","설명":"허가ㆍ변경허가 또는 불허가 처분은 신청서를 받은 날부터 15일 이내에 한다(시행령 제8조제3항)."},{"번호":2,"판정":"옳음","설명":"변경허가 신청서의 기재사항은 제1항 제1호~제3호 사항, 토지거래계약 허가번호, 변경내용, 변경사유다(시행령 제8조제2항)."},{"번호":3,"판정":"틀림","설명":"허가는 당사자가 공동으로 신청한다(법 제11조제1항). 매수인 단독 신청이 아니다."},{"번호":4,"판정":"틀림","설명":"상업지역의 면제 기준 면적은 150제곱미터다(시행령 제9조제1항제1호나목). 250제곱미터는 기준을 넘으므로 허가가 필요하다."},{"번호":5,"판정":"틀림","설명":"법 제12조제1호 가목~다목의 목적으로 허가받은 경우 이용 의무 기간은 토지 취득일부터 2년이다(시행령 제14조제2항제1호). 4년은 라목~바목 목적의 기간이다."}],"개념":[{"종류":"표","제목":"토지거래계약 허가 면제 면적 (시행령 제9조제1항)","머리":["용도지역","면제 기준 면적(초과하면 허가 필요)"],"행":[["주거지역","60제곱미터"],["상업지역","150제곱미터"],["공업지역","150제곱미터"],["녹지지역","200제곱미터"],["도시지역 안 용도지역 지정이 없는 구역","60제곱미터"],["도시지역 외","250제곱미터(농지 500제곱미터, 임야 1천제곱미터)"],["조정","지정 당시 거래실태를 고려해 기준면적의 10퍼센트 이상 300퍼센트 이하 범위에서 따로 공고하면 그에 따름"]]},{"종류":"표","제목":"이용 의무 기간과 이행강제금 (시행령 제14조제2항, 제16조)","머리":["구분","내용"],"행":[["자기 거주용 주택용지 등(법 제12조제1호 가~다목)","취득일부터 2년"],["공익사업, 지역발전 사업 등(라~바목)","취득일부터 4년(분양 목적이고 개발 착수 후 4년 이내 분양 완료 시 그때까지)"],["대체토지 취득","취득일부터 2년"],["현상 보존 목적","취득일부터 5년"],["그 밖의 경우","취득일부터 5년"],["이행강제금 금액","방치 취득가액의 100분의 10, 임대 100분의 7, 허가관청 승인 없는 목적 변경 100분의 5, 그 밖에 100분의 7"],["이행명령ㆍ이의","이행명령 문서로 하고 이행기간은 3개월 이내. 이행강제금 부과처분에 대한 이의는 고지받은 날부터 30일 이내"]]}],"함정":"1번, 4번, 5번은 처분 기간 15일, 상업지역 150제곱미터, 주택용지 이용 의무 2년을 각각 30일, 250제곱미터, 4년으로 바꿨고, 3번은 신청 주체가 공동이라는 점을 바꿨다. 변경허가 신청서의 기재사항은 제1항의 신청서 기재사항에 변경 관련 항목을 더하는 구조라서 2번이 정답이다."}},{"i":"S2-2-1-중개사법-33","r":"S2","g":2,"c":2,"n":33,"s":"중개사법","q":"부동산 거래신고 등에 관한 법령상 토지거래허가에 관한 내용으로 옳은 것은?","b":null,"bs":"없음","img":[],"ch":["토지거래허가구역의 지정은 그 지정을 공고한 날부터 3일 후에 효력이 발생한다.","토지거래허가구역의 지정 당시 국토교통부장관 또는 시ㆍ도지사가 따로 정하여 공고하지 않은 경우, ｢국토의 계획 및 이용에 관한 법률｣에 따른 도시지역 중 녹지지역 안의 250제곱미터 면적의 토지거래계약에 관하여는 허가가 필요 없다.","토지거래계약을 허가받은 자는 대통령령으로 정하는 사유가 있는 경우 외에는 토지 취득일부터 10년간 그 토지를 허가받은 목적대로 이용해야 한다.","허가받은 목적대로 토지를 이용하지 않았음을 이유로 이행강제금 부과처분을 받은 자가 시장ㆍ군수ㆍ구청장에게 이의를 제기하려면 그 처분을 고지받은 날부터 60일 이내에 해야 한다.","토지거래허가신청에 대해 불허가처분을 받은 자는 그 통지를 받은 날부터 1개월 이내에 시장ㆍ군수ㆍ구청장에게 해당 토지에 관한 권리의 매수를 청구할 수 있다."],"a":[5],"L":"중2-4","o":"기출","x":{"한줄":"불허가처분을 받은 자는 그 통지를 받은 날부터 1개월 이내에 허가관청에 해당 토지의 매수를 청구할 수 있다(법 제16조제1항).","근거":[{"법령":"부동산 거래신고 등에 관한 법률","조문":"제16조 제1항","원문":"① 제11조제1항에 따른 허가신청에 대하여 불허가처분을 받은 자는 그 통지를 받은 날부터 1개월 이내에 시장ㆍ군수 또는 구청장에게 해당 토지에 관한 권리의 매수를 청구할 수 있다."},{"법령":"부동산 거래신고 등에 관한 법률","조문":"제10조 제5항","원문":"⑤ 허가구역의 지정은 제3항에 따라 허가구역의 지정을 공고한 날부터 5일 후에 그 효력이 발생한다."},{"법령":"부동산 거래신고 등에 관한 법률 시행령","조문":"제9조 제1항","원문":"① 법 제11조제2항제1호에서 \"대통령령으로 정하는 용도별 면적\"이란 다음 각 호의 구분에 따른 면적을 말한다. 다만, 국토교통부장관 또는 시ㆍ도지사가 허가구역을 지정할 당시 해당 지역에서의 거래실태 등을 고려하여 다음 각 호의 면적으로 하는 것이 타당하지 않다고 인정하여 해당 기준면적의 10퍼센트 이상 300퍼센트 이하의 범위에서 따로 정하여 공고한 경우에는 그에 따른다.\n1. 「국토의 계획 및 이용에 관한 법률」 제36조제1항제1호에 따른 도시지역(이하 \"도시지역\"이라 한다): 다음 각 목의 세부 용도지역별 구분에 따른 면적\n가. 주거지역: 60제곱미터\n나. 상업지역: 150제곱미터\n다. 공업지역: 150제곱미터\n라. 녹지지역: 200제곱미터\n마. 가목부터 라목까지의 구분에 따른 용도지역의 지정이 없는 구역: 60제곱미터\n2. 도시지역 외의 지역: 250제곱미터. 다만, 농지(「농지법」 제2조제1호에 따른 농지를 말한다. 이하 같다)의 경우에는 500제곱미터로 하고, 임야의 경우에는 1천제곱미터로 한다."},{"법령":"부동산 거래신고 등에 관한 법률 시행령","조문":"제14조 제2항","원문":"② 법 제17조제1항에서 \"대통령령으로 정하는 기간\"이란 다음 각 호의 구분에 따른 기간을 말한다.\n1. 법 제12조제1호가목부터 다목까지의 목적으로 허가를 받은 경우: 토지 취득일부터 2년\n2. 법 제12조제1호라목부터 바목까지의 목적으로 허가를 받은 경우: 토지 취득일부터 4년. 다만, 분양을 목적으로 허가를 받은 토지로서 개발에 착수한 후 토지 취득일부터 4년 이내에 분양을 완료한 경우에는 분양을 완료한 때에 4년이 지난 것으로 본다.\n3. 제10조제2항제1호에 따라 대체토지를 취득하기 위하여 허가를 받은 경우: 토지 취득일부터 2년\n4. 제10조제2항제2호에 따라 현상보존의 목적으로 토지를 취득하기 위하여 허가를 받은 경우: 토지 취득일부터 5년\n5. 제1호부터 제4호까지의 경우 외의 경우: 토지 취득일부터 5년"},{"법령":"부동산 거래신고 등에 관한 법률 시행령","조문":"제16조 제7항","원문":"⑦ 제6항에 따른 이행강제금 부과처분을 받은 자는 법 제18조제6항에 따라 이의를 제기하려는 경우에는 부과처분을 고지받은 날부터 30일 이내에 하여야 한다."}],"선지":[{"번호":1,"판정":"틀림","설명":"허가구역 지정은 공고한 날부터 5일 후에 효력이 발생한다(법 제10조제5항)."},{"번호":2,"판정":"틀림","설명":"녹지지역의 면제 기준은 200제곱미터다(시행령 제9조제1항제1호라목). 250제곱미터는 초과하므로 허가가 필요하다."},{"번호":3,"판정":"틀림","설명":"이용 의무 기간은 5년의 범위에서 영이 정하며 목적에 따라 2년, 4년, 5년이다(법 제17조제1항, 시행령 제14조제2항). 10년이 아니다."},{"번호":4,"판정":"틀림","설명":"이행강제금 부과처분에 대한 이의는 처분을 고지받은 날부터 30일 이내에 한다(시행령 제16조제7항)."},{"번호":5,"판정":"옳음","설명":"매수청구 기한은 불허가 통지를 받은 날부터 1개월이다(법 제16조제1항)."}],"개념":[{"종류":"흐름","제목":"토지거래허가구역 지정 절차 (법 제10조)","단계":[{"이름":"지정권자","설명":"둘 이상의 시ㆍ도에 걸치면 국토교통부장관, 한 시ㆍ도 안의 일부 지역이면 시ㆍ도지사가 지정한다. 지정기간은 5년 이내다."},{"이름":"심의","설명":"중앙도시계획위원회 또는 시ㆍ도도시계획위원회의 심의를 거친다. 지정기간이 끝나는 구역을 계속 지정할 때는 심의 전에 시장ㆍ군수ㆍ구청장 등의 의견을 듣는다."},{"이름":"공고ㆍ통지","설명":"지체 없이 허가대상자, 용도, 지목 등을 공고한다. 국토교통부장관은 시ㆍ도지사를 거쳐, 시ㆍ도지사는 직접 시장ㆍ군수ㆍ구청장에게 통지한다."},{"이름":"등기소 통지ㆍ공고ㆍ열람","설명":"시장ㆍ군수ㆍ구청장이 지체 없이 등기소장에게 통지하고 7일 이상 공고하며 15일간 열람하게 한다."},{"이름":"효력 발생","설명":"지정을 공고한 날부터 5일 후에 효력이 발생한다."}]},{"종류":"표","제목":"토지거래허가 관련 기간 모음","머리":["절차","기간","근거"],"행":[["허가ㆍ변경허가ㆍ불허가 처분","신청서를 받은 날부터 15일 이내","시행령 제8조제3항"],["선매자 지정 통지","허가신청이 있는 날부터 1개월 이내","법 제15조제2항"],["선매협의 서면 통지","지정 통지를 받은 날부터 15일 이내","시행령 제12조제2항"],["선매협의 조서 제출","지정 통지를 받은 날부터 1개월 이내","시행령 제12조제2항"],["불허가 토지 매수청구","불허가 통지를 받은 날부터 1개월 이내","법 제16조제1항"],["처분에 대한 이의신청","처분을 받은 날부터 1개월 이내","법 제13조제1항"],["이행강제금 이의","부과처분을 고지받은 날부터 30일 이내","시행령 제16조제7항"],["이행명령의 이행기간","3개월 이내","시행령 제16조제1항"]]}],"함정":"다섯 선지가 모두 기간이나 면적이라서 숫자를 정확히 알아야 한다. 효력 발생은 5일 후, 녹지지역 기준은 200제곱미터, 이용 의무는 2~5년, 이행강제금 이의는 30일, 매수청구는 1개월로 외운다. 허가 처분에 대한 이의신청 1개월과 이행강제금 부과처분에 대한 이의 30일은 서로 다른 기간이다."}},{"i":"S2-2-1-중개사법-34","r":"S2","g":2,"c":2,"n":34,"s":"중개사법","q":"부동산 거래신고 등에 관한 법령상 징역 또는 벌금에 처해질 수 있는 자가 아닌 것은?","b":null,"bs":"없음","img":[],"ch":["부당하게 재물이나 재산상 이득을 취할 목적으로 거짓으로 부동산 거래신고를 하는 행위를 조장한 자","토지취득의 허가를 받아야 함에도 허가를 받지 아니하고 토지취득계약을 체결한 대한민국의 국적을 보유하고 있지 아니한 개인","토지거래허가구역에서 허가를 받아야 함에도 허가를 받지 아니하고 토지거래계약을 체결한 자","토지거래허가구역에서 속임수나 그 밖의 부정한 방법으로 토지거래계약 허가를 받은 자","토지거래계약 허가를 받은 자가 그 토지를 허가받은 목적대로 이용하지 않음을 이유로 관할 행정청이 한 조치 명령을 위반한 자"],"a":[1],"L":"중2-5","o":"기출","x":{"한줄":"거짓 신고를 조장하거나 방조한 자는 500만원 이하의 과태료 대상이다(법 제28조제2항제3호). 징역ㆍ벌금 대상은 거짓으로 신고한 자 본인이다(법 제26조제1항).","근거":[{"법령":"부동산 거래신고 등에 관한 법률","조문":"제26조","원문":"제26조(벌칙)\n① 부당하게 재물이나 재산상 이득을 취득하거나 제3자로 하여금 이를 취득하게 할 목적으로 제4조제4호 또는 제5호를 위반하여 거짓으로 제3조 또는 제3조의2에 따라 신고한 자는 3년 이하의 징역 또는 3천만원 이하의 벌금에 처한다.\n② 제9조제1항에 따른 허가를 받지 아니하고 토지취득계약을 체결하거나 부정한 방법으로 허가를 받아 토지취득계약을 체결한 외국인등은 2년 이하의 징역 또는 2천만원 이하의 벌금에 처한다.\n③ 제11조제1항에 따른 허가 또는 변경허가를 받지 아니하고 토지거래계약을 체결하거나, 속임수나 그 밖의 부정한 방법으로 토지거래계약 허가를 받은 자는 2년 이하의 징역 또는 계약 체결 당시의 개별공시지가에 따른 해당 토지가격의 100분의 30에 해당하는 금액 이하의 벌금에 처한다.\n④ 제21조에 따른 허가 취소, 처분 또는 조치명령을 위반한 자는 1년 이하의 징역 또는 1천만원 이하의 벌금에 처한다."},{"법령":"부동산 거래신고 등에 관한 법률","조문":"제28조 제2항","원문":"② 다음 각 호의 어느 하나에 해당하는 자에게는 500만원 이하의 과태료를 부과한다.\n1. 제3조제1항부터 제4항까지의 규정을 위반하여 같은 항에 따른 신고를 하지 아니한 자(공동신고를 거부한 자를 포함한다)\n1의2. 제3조의2제1항을 위반하여 같은 항에 따른 신고를 하지 아니한 자(공동신고를 거부한 자를 포함한다)\n2. 제4조제1호를 위반하여 개업공인중개사에게 제3조에 따른 신고를 하지 아니하게 하거나 거짓으로 신고하도록 요구한 자\n3. 제4조제3호를 위반하여 거짓으로 제3조에 따른 신고를 하는 행위를 조장하거나 방조한 자\n4. 제6조를 위반하여 거래대금 지급을 증명할 수 있는 자료 외의 자료를 제출하지 아니하거나 거짓으로 제출한 자"},{"법령":"부동산 거래신고 등에 관한 법률","조문":"제4조 제3호","원문":"3. 거짓으로 제3조 또는 제3조의2에 따른 신고를 하는 행위를 조장하거나 방조하는 행위"}],"선지":[{"번호":1,"판정":"틀림","설명":"조장ㆍ방조(법 제4조제3호)는 징역ㆍ벌금이 아니라 500만원 이하의 과태료다(법 제28조제2항제3호). 부당이득 목적의 처벌은 제4조제4호ㆍ제5호의 거짓 신고 본인에게 적용된다(법 제26조제1항)."},{"번호":2,"판정":"옳음","설명":"허가 없이 토지취득계약을 체결한 외국인등은 2년 이하의 징역 또는 2천만원 이하의 벌금이다(법 제26조제2항)."},{"번호":3,"판정":"옳음","설명":"허가 없이 토지거래계약을 체결하면 2년 이하의 징역 또는 개별공시지가에 따른 토지가격의 100분의 30 이하 벌금이다(법 제26조제3항)."},{"번호":4,"판정":"옳음","설명":"속임수나 부정한 방법으로 허가를 받은 자도 같은 조 제3항의 처벌 대상이다."},{"번호":5,"판정":"옳음","설명":"법 제21조에 따른 허가 취소, 처분 또는 조치명령을 위반한 자는 1년 이하의 징역 또는 1천만원 이하의 벌금이다(법 제26조제4항)."}],"개념":[{"종류":"표","제목":"부동산 거래신고법 벌칙과 과태료","머리":["구분","대상 행위","근거"],"행":[["3년 이하 징역 또는 3천만원 이하 벌금","부당한 재산상 이득을 얻을 목적으로 거짓 거래신고ㆍ해제등 신고","법 제26조제1항"],["2년 이하 징역 또는 2천만원 이하 벌금","허가 없이 또는 부정한 방법으로 허가를 받아 토지취득계약을 체결한 외국인등","법 제26조제2항"],["2년 이하 징역 또는 토지가격 100분의 30 이하 벌금","허가 없이 토지거래계약 체결, 부정한 방법의 허가","법 제26조제3항"],["1년 이하 징역 또는 1천만원 이하 벌금","허가 취소, 처분 또는 조치명령 위반","법 제26조제4항"],["3천만원 이하 과태료","거짓 거래신고ㆍ해제등 신고(벌칙 대상이 아닌 경우), 거래대금 지급 증명자료 미제출ㆍ거짓 제출","법 제28조제1항"],["500만원 이하 과태료","신고 미이행(공동신고 거부 포함), 개업공인중개사에게 신고 안 하게 하거나 거짓 신고 요구, 거짓 신고 조장ㆍ방조","법 제28조제2항"],["취득가액 100분의 10 이하 과태료","거래신고를 거짓으로 한 자","법 제28조제3항"],["300만원 이하 과태료","외국인등의 취득 신고 위반(법 제8조제1항)","법 제28조제4항"],["100만원 이하 과태료","외국인등의 취득 신고(제8조제2항)ㆍ계속보유 신고 위반, 주택 임대차 신고 위반","법 제28조제5항"]]},{"종류":"표","제목":"신고포상금 (법 제25조의2, 시행령 제19조의2)","머리":["신고 대상","포상금","지급 요건"],"행":[["거짓 거래가격 신고, 거짓 거래신고ㆍ해제등 신고, 주택 임대차 계약금액 거짓 신고","부과되는 과태료의 100분의 20(거짓 거래가격 신고는 한도 1천만원)","신고관청이 적발하기 전에 신고하고 증거자료 제출, 과태료가 부과된 경우"],["허가 없이 토지거래계약 체결, 부정한 방법의 허가","50만원","허가관청 또는 수사기관이 적발하기 전에 신고ㆍ고발, 공소제기 또는 기소유예 결정"],["허가받은 목적대로 이용하지 않은 자","50만원","허가관청이 적발하기 전에 신고, 이행명령이 있는 경우"]]}],"함정":"조장이라는 말에서 처벌 수위를 높게 읽기 쉽다. 부당이득 목적을 붙여도 조장ㆍ방조는 과태료 500만원 이하다. 징역ㆍ벌금 문항에서는 허가 위반 계열(제26조제2항~제4항)과 부당이득 목적의 거짓 신고 본인(제26조제1항)만 고르면 된다."}},{"i":"S2-2-1-중개사법-35","r":"S2","g":2,"c":2,"n":35,"s":"중개사법","q":"개업공인중개사가 농지를 취득하려는 중개의뢰인에게 설명한 내용으로 틀린 것은?","b":null,"bs":"없음","img":[],"ch":["농업경영을 하려는 자에게 농지를 임대하는 경우, 임차인이 시ㆍ구ㆍ읍ㆍ면의 장의 확인을 받고 해당 농지를 인도받으면 그 다음 날부터 제삼자에 대하여 임대차의 효력이 생긴다.","상속으로 농지를 취득하는 경우에는 농지취득자격증명을 발급받지 않고 농지를 취득할 수 있다.","주말ㆍ체험영농을 하려는 자는 농업진흥지역 안의 농지도 세대원 전부의 소유 면적을 합하여 1천제곱미터 미만까지 소유할 수 있다.","농지위원회 심의 대상이 아니고 농업경영계획서를 작성하여 신청한 경우, 시ㆍ구ㆍ읍ㆍ면의 장은 신청을 받은 날부터 7일 이내에 농지취득자격증명을 발급하여야 한다.","임대인이 임대차 기간이 끝나기 3개월 전까지 임차인에게 임대차계약을 갱신하지 아니한다는 뜻을 통지하지 아니하면, 그 기간이 끝난 때에 이전과 같은 조건으로 다시 임대차계약을 한 것으로 본다."],"a":[3],"L":"중3-1","o":"변형","x":{"한줄":"주말ㆍ체험영농용 농지는 농업진흥지역 외의 농지만 소유할 수 있다(농지법 제6조제2항제3호).","근거":[{"법령":"농지법","조문":"제6조 제2항 제3호","원문":"②제1항에도 불구하고 다음 각 호의 어느 하나에 해당하는 경우에는 농지를 소유할 수 있다. 다만, 소유 농지는 농업경영에 이용되도록 하여야 한다(제2호 및 제3호는 제외한다).\n1. 국가나 지방자치단체가 농지를 소유하는 경우\n2. 「초ㆍ중등교육법」 및 「고등교육법」에 따른 학교, 농림축산식품부령으로 정하는 공공단체ㆍ농업연구기관ㆍ농업생산자단체 또는 종묘나 그 밖의 농업 기자재 생산자가 그 목적사업을 수행하기 위하여 필요한 시험지ㆍ연구지ㆍ실습지ㆍ종묘생산지 또는 과수 인공수분용 꽃가루 생산지로 쓰기 위하여 농림축산식품부령으로 정하는 바에 따라 농지를 취득하여 소유하는 경우\n3. 주말ㆍ체험영농을 하려고 제28조에 따른 농업진흥지역 외의 농지를 소유하는 경우\n4. 상속[상속인에게 한 유증(遺贈)을 포함한다. 이하 같다]으로 농지를 취득하여 소유하는 경우\n5. 대통령령으로 정하는 기간 이상 농업경영을 하던 사람이 이농(離農)한 후에도 이농 당시 소유하고 있던 농지를 계속 소유하는 경우\n6. 제13조제1항에 따라 담보농지를 취득하여 소유하는 경우(「자산유동화에 관한 법률」 제3조에 따른 유동화전문회사등이 제13조제1항제1호부터 제4호까지에 규정된 저당권자로부터 농지를 취득하는 경우를 포함한다)\n7. 제34조제1항에 따른 농지전용허가[다른 법률에 따라 농지전용허가가 의제(擬制)되는 인가ㆍ허가ㆍ승인 등을 포함한다]를 받거나 제35조 또는 제43조에 따른 농지전용신고를 한 자가 그 농지를 소유하는 경우\n8. 제34조제2항에 따른 농지전용협의를 마친 농지를 소유하는 경우\n9. 「한국농어촌공사 및 농지관리기금법」 제24조제2항에 따른 농지의 개발사업지구에 있는 농지로서 대통령령으로 정하는 1천500제곱미터 미만의 농지나 「농어촌정비법」 제98조제3항에 따른 농지를 취득하여 소유하는 경우\n9의2. 제28조에 따른 농업진흥지역 밖의 농지 중 최상단부부터 최하단부까지의 평균경사율이 15퍼센트 이상인 농지로서 대통령령으로 정하는 농지를 소유하는 경우\n10. 다음 각 목의 어느 하나에 해당하는 경우\n가. 「한국농어촌공사 및 농지관리기금법」에 따른 한국농어촌공사(이하 \"한국농어촌공사\"라 한다)가 같은 법에 따라 농지를 취득하여 소유하는 경우\n나. 「농어촌정비법」 제16조ㆍ제25조ㆍ제43조ㆍ제82조 또는 제100조에 따라 농지를 취득하여 소유하는 경우\n다. 「공유수면 관리 및 매립에 관한 법률」에 따라 매립농지를 취득하여 소유하는 경우\n라. 토지수용으로 농지를 취득하여 소유하는 경우\n마. 농림축산식품부장관과 협의를 마치고 「공익사업을 위한 토지 등의 취득 및 보상에 관한 법률」에 따라 농지를 취득하여 소유하는 경우\n바. 「공공토지의 비축에 관한 법률」제2조제1호가목에 해당하는 토지 중 같은 법 제7조제1항에 따른 공공토지비축심의위원회가 비축이 필요하다고 인정하는 토지로서 「국토의 계획 및 이용에 관한 법률」 제36조에 따른 계획관리지역과 자연녹지지역 안의 농지를 한국토지주택공사가 취득하여 소유하는 경우. 이 경우 그 취득한 농지를 전용하기 전까지는 한국농어촌공사에 지체 없이 위탁하여 임대하거나 무상사용하게 하여야 한다.\n3. 주말ㆍ체험영농을 하려고 제28조에 따른 농업진흥지역 외의 농지를 소유하는 경우"},{"법령":"농지법","조문":"제7조 제3항","원문":"③주말ㆍ체험영농을 하려는 사람은 총 1천제곱미터 미만의 농지를 소유할 수 있다. 이 경우 면적 계산은 그 세대원 전부가 소유하는 총 면적으로 한다."},{"법령":"농지법","조문":"제8조 제1항","원문":"①농지를 취득하려는 자는 농지 소재지를 관할하는 시장(구를 두지 아니한 시의 시장을 말하며, 도농 복합 형태의 시는 농지 소재지가 동지역인 경우만을 말한다), 구청장(도농 복합 형태의 시의 구에서는 농지 소재지가 동지역인 경우만을 말한다), 읍장 또는 면장(이하 \"시ㆍ구ㆍ읍ㆍ면의 장\"이라 한다)에게서 농지취득자격증명을 발급받아야 한다. 다만, 다음 각 호의 어느 하나에 해당하면 농지취득자격증명을 발급받지 아니하고 농지를 취득할 수 있다.\n1. 제6조제2항제1호ㆍ제4호ㆍ제6호ㆍ제8호 또는 제10호(같은 호 바목은 제외한다)에 따라 농지를 취득하는 경우\n2. 농업법인의 합병으로 농지를 취득하는 경우\n3. 공유 농지의 분할이나 그 밖에 대통령령으로 정하는 원인으로 농지를 취득하는 경우"},{"법령":"농지법","조문":"제24조 제2항","원문":"② 제1항에 따른 임대차계약은 그 등기가 없는 경우에도 임차인이 농지소재지를 관할하는 시ㆍ구ㆍ읍ㆍ면의 장의 확인을 받고, 해당 농지를 인도(引渡)받은 경우에는 그 다음 날부터 제삼자에 대하여 효력이 생긴다."},{"법령":"농지법","조문":"제25조","원문":"제25조(묵시의 갱신) 임대인이 임대차 기간이 끝나기 3개월 전까지 임차인에게 임대차계약을 갱신하지 아니한다는 뜻이나 임대차계약 조건을 변경한다는 뜻을 통지하지 아니하면 그 임대차 기간이 끝난 때에 이전의 임대차계약과 같은 조건으로 다시 임대차계약을 한 것으로 본다."}],"선지":[{"번호":1,"판정":"옳음","설명":"임대차는 등기가 없어도 확인과 인도를 마치면 다음 날부터 제삼자에게 효력이 있다(농지법 제24조제2항)."},{"번호":2,"판정":"옳음","설명":"상속은 소유 제한의 예외이고(제6조제2항제4호), 농지취득자격증명 없이 취득할 수 있다(제8조제1항단서 제1호)."},{"번호":3,"판정":"틀림","설명":"주말ㆍ체험영농용은 농업진흥지역 외의 농지에 한한다. 면적은 세대원 전부의 합계 1천제곱미터 미만이라 뒷부분은 맞다(제7조제3항)."},{"번호":4,"판정":"옳음","설명":"발급 기간은 원칙적으로 신청을 받은 날부터 7일이다. 계획서를 쓰지 않는 경우는 4일, 농지위원회 심의 대상은 14일이다(제8조제4항)."},{"번호":5,"판정":"옳음","설명":"임대차 기간 끝나기 3개월 전까지 갱신 거절이나 조건 변경 통지가 없으면 묵시적으로 갱신된다(제25조)."}],"개념":[{"종류":"표","제목":"농지 소유 제한의 예외와 상한 (농지법 제6조ㆍ제7조)","머리":["유형","소유 가능 범위","비고"],"행":[["자경 농업인ㆍ농업법인","농지를 자기 농업경영에 이용하는 자","원칙(제6조제1항)"],["상속으로 취득","농업경영을 하지 않으면 총 1만제곱미터까지","유증 포함, 제7조제1항"],["이농","이농 당시 소유 농지 중 총 1만제곱미터까지","제7조제2항"],["주말ㆍ체험영농","농업진흥지역 외의 농지, 세대원 전부 합계 1천제곱미터 미만","제6조제2항제3호, 제7조제3항"],["농지전용허가ㆍ신고를 한 자","전용 목적 농지","취득일부터 2년 내 목적사업에 착수하지 않으면 1년 내 처분(제10조제1항제5호)"],["담보농지 취득","저당권 실행 등으로 취득","제6조제2항제6호"]]},{"종류":"표","제목":"농지취득자격증명과 농지 임대차","머리":["항목","내용","근거"],"행":[["발급 면제","국가ㆍ지자체 취득, 상속, 담보농지 취득, 농지전용협의 농지, 농업법인의 합병, 공유 농지 분할 등","제8조제1항단서"],["발급 기간","원칙 7일, 계획서 생략 사유는 4일, 농지위원회 심의 대상은 14일","제8조제4항"],["계획서 보존","농업경영계획서ㆍ주말ㆍ체험영농계획서 10년","제8조의2제1항"],["임대차 계약","농업경영을 하려는 자에게 임대하면 서면계약이 원칙","제24조제1항"],["임대차 기간","3년 이상(다년생식물 재배지 등은 5년 이상). 기간을 정하지 않거나 짧게 정하면 그 기간으로 약정된 것으로 봄","제24조의2"],["묵시 갱신","기간 끝나기 3개월 전까지 갱신 거절 통지가 없으면 갱신","제25조"]]}],"함정":"3번은 면적 부분이 맞아서 통째로 맞는 문장처럼 읽힌다. 장소 요건(농업진흥지역 외)이 빠진 것을 찾아야 한다. 2번은 상속이 소유 제한과 자격증명 모두에서 예외라는 점을 물은 선지다."}},{"i":"S2-2-1-중개사법-36","r":"S2","g":2,"c":2,"n":36,"s":"중개사법","q":"개업공인중개사가 중개의뢰인에게 주택임대차보호법을 설명한 내용으로 틀린 것은?","b":null,"bs":"없음","img":[],"ch":["임차인이 주택의 인도와 주민등록을 마친 때에는 그 다음 날부터 제삼자에 대하여 효력이 생기며, 전입신고를 한 때에 주민등록이 된 것으로 본다.","임차주택의 양수인은 임대인의 지위를 승계한 것으로 본다.","묵시적 갱신으로 계약이 갱신된 경우 임차인은 언제든지 임대인에게 계약해지를 통지할 수 있고, 임대인이 그 통지를 받은 날부터 3개월이 지나면 효력이 발생한다.","임대인이 임대차기간이 끝나기 6개월 전부터 2개월 전까지의 기간에 갱신거절의 통지를 하지 않아 갱신된 것으로 보는 경우, 갱신된 임대차의 존속기간은 1년으로 본다.","임차권등기명령의 집행에 따른 임차권등기를 마친 임차인이 이후 주민등록을 이전하더라도 이미 취득한 대항력과 우선변제권은 상실되지 않는다."],"a":[4],"L":"중3-2","o":"변형","x":{"한줄":"묵시적으로 갱신된 임대차의 존속기간은 2년이다(주택임대차보호법 제6조제2항). 1년이 아니다.","근거":[{"법령":"주택임대차보호법","조문":"제6조 제1항 제2항","원문":"① 임대인이 임대차기간이 끝나기 6개월 전부터 2개월 전까지의 기간에 임차인에게 갱신거절(更新拒絶)의 통지를 하지 아니하거나 계약조건을 변경하지 아니하면 갱신하지 아니한다는 뜻의 통지를 하지 아니한 경우에는 그 기간이 끝난 때에 전 임대차와 동일한 조건으로 다시 임대차한 것으로 본다. 임차인이 임대차기간이 끝나기 2개월 전까지 통지하지 아니한 경우에도 또한 같다.\n② 제1항의 경우 임대차의 존속기간은 2년으로 본다."},{"법령":"주택임대차보호법","조문":"제6조의2","원문":"제6조의2(묵시적 갱신의 경우 계약의 해지)\n① 제6조제1항에 따라 계약이 갱신된 경우 같은 조 제2항에도 불구하고 임차인은 언제든지 임대인에게 계약해지(契約解止)를 통지할 수 있다.\n② 제1항에 따른 해지는 임대인이 그 통지를 받은 날부터 3개월이 지나면 그 효력이 발생한다."},{"법령":"주택임대차보호법","조문":"제3조 제1항 제4항","원문":"① 임대차는 그 등기(登記)가 없는 경우에도 임차인(賃借人)이 주택의 인도(引渡)와 주민등록을 마친 때에는 그 다음 날부터 제삼자에 대하여 효력이 생긴다. 이 경우 전입신고를 한 때에 주민등록이 된 것으로 본다.\n④ 임차주택의 양수인(讓受人)(그 밖에 임대할 권리를 승계한 자를 포함한다)은 임대인(賃貸人)의 지위를 승계한 것으로 본다."},{"법령":"주택임대차보호법","조문":"제3조의3 제5항","원문":"⑤ 임차인은 임차권등기명령의 집행에 따른 임차권등기를 마치면 제3조제1항ㆍ제2항 또는 제3항에 따른 대항력과 제3조의2제2항에 따른 우선변제권을 취득한다. 다만, 임차인이 임차권등기 이전에 이미 대항력이나 우선변제권을 취득한 경우에는 그 대항력이나 우선변제권은 그대로 유지되며, 임차권등기 이후에는 제3조제1항ㆍ제2항 또는 제3항의 대항요건을 상실하더라도 이미 취득한 대항력이나 우선변제권을 상실하지 아니한다."}],"선지":[{"번호":1,"판정":"옳음","설명":"인도와 주민등록을 마친 다음 날부터 대항력이 생기고 전입신고 때 주민등록이 된 것으로 본다(제3조제1항)."},{"번호":2,"판정":"옳음","설명":"양수인은 임대인의 지위를 승계한 것으로 본다(제3조제4항)."},{"번호":3,"판정":"옳음","설명":"해지 통지권은 임차인에게만 있고, 임대인이 통지를 받은 날부터 3개월 후 효력이 생긴다(제6조의2)."},{"번호":4,"판정":"틀림","설명":"갱신된 임대차의 존속기간은 2년으로 본다(제6조제2항)."},{"번호":5,"판정":"옳음","설명":"임차권등기를 마친 뒤에는 대항요건을 잃어도 이미 취득한 대항력과 우선변제권을 잃지 않는다(제3조의3제5항)."}],"개념":[{"종류":"비교","제목":"묵시적 갱신과 계약갱신요구권","왼쪽":{"이름":"묵시적 갱신(제6조ㆍ제6조의2)","항목":["임대인이 기간 끝나기 6개월 전부터 2개월 전까지 갱신거절 또는 조건변경 통지를 하지 않으면 갱신","임차인이 2개월 전까지 통지하지 않은 경우도 같음","존속기간 2년","임차인은 언제든 해지 통지 가능, 임대인이 통지를 받은 날부터 3개월 후 효력","2기의 차임액에 달하도록 연체한 임차인 등에는 적용하지 않음"]},"오른쪽":{"이름":"계약갱신요구권(제6조의3)","항목":["임차인이 6개월 전부터 2개월 전까지 요구하면 정당한 사유 없이 거절하지 못함","1회에 한하여 행사, 갱신 존속기간 2년","전 임대차와 동일한 조건. 차임과 보증금은 제7조 범위에서 증감","임대인의 직접 거주 사유로 거절하고 갱신 기간 만료 전에 정당한 사유 없이 제3자에게 임대하면 임차인에게 손해배상","갱신된 임대차의 해지는 제6조의2를 준용"]}},{"종류":"표","제목":"대항력ㆍ우선변제권ㆍ소액보증금 (주택임대차보호법 제3조, 제3조의2, 제8조, 시행령 제10조ㆍ제11조)","머리":["구분","요건","내용"],"행":[["대항력","주택의 인도 + 주민등록","다음 날부터 제삼자에 대하여 효력"],["우선변제권","대항요건 + 임대차계약증서상 확정일자","경매ㆍ공매 환가대금에서 후순위권리자나 그 밖의 채권자보다 우선 변제. 임차주택을 양수인에게 인도해야 보증금을 받음"],["소액보증금 최우선변제","경매신청 등기 전에 대항요건 구비 + 보증금이 기준 이하","서울 보증금 1억6천500만원 이하는 5천500만원까지, 과밀억제권역ㆍ세종ㆍ용인ㆍ화성ㆍ김포 1억4천500만원 이하는 4천800만원까지, 광역시ㆍ안산ㆍ광주ㆍ파주ㆍ이천ㆍ평택 8천500만원 이하는 2천800만원까지, 그 밖의 지역 7천500만원 이하는 2천500만원까지(주택가액의 2분의 1 한도)"],["임차권등기명령","임대차 종료 후 보증금 미반환","집행에 따른 등기 후 대항력ㆍ우선변제권 취득 또는 유지. 그 후 임차한 임차인은 소액보증금 최우선변제권 없음"]]}],"함정":"갱신 후 존속기간 2년은 묵시적 갱신과 계약갱신요구권 모두에 같은 숫자라서 4번의 1년만 찾으면 된다. 3번에서 해지 통지권자는 임차인이고 임대인에게는 해지권이 없다는 점도 같이 확인한다."}},{"i":"S2-2-1-중개사법-37","r":"S2","g":2,"c":2,"n":37,"s":"중개사법","q":"개업공인중개사가 아파트를 매수하려는 의뢰인에게 ｢집합건물의 소유 및 관리에 관한 법률｣의 내용에 관하여 설명한 것으로 옳은 것은?","b":null,"bs":"없음","img":[],"ch":["전유부분이 속하는 1동의 건물의 설치 또는 보존의 흠으로 인하여 다른 자에게 손해를 입힌 경우, 그 흠은 공용부분에 존재하는 것으로 추정한다.","구분소유자는 그 전유부분을 개량하기 위하여 필요한 범위에서 다른 구분소유자의 전유부분의 사용을 청구할 수 없다.","공용부분의 공유자가 공용부분에 관하여 다른 공유자에 대하여 가지는 채권은 그 특별승계인에 대하여 행사할 수 없다.","대지 위에 구분소유권의 목적인 건물이 속하는 1동의 건물이 있을 때에는 그 대지의 공유자는 그 건물 사용에 필요한 범위의 대지에 대하여 분할을 청구할 수 있다.","공용부분에 대한 공유자의 지분은 그가 가지는 전유부분의 처분에 따르지 않는다."],"a":[1],"L":"중3-2","o":"기출","x":{"한줄":"1동의 건물의 설치 또는 보존의 흠으로 생긴 손해는 흠이 공용부분에 있는 것으로 추정한다(집합건물법 제6조).","근거":[{"법령":"집합건물의 소유 및 관리에 관한 법률","조문":"제6조","원문":"제6조(건물의 설치ㆍ보존상의 흠 추정) 전유부분이 속하는 1동의 건물의 설치 또는 보존의 흠으로 인하여 다른 자에게 손해를 입힌 경우에는 그 흠은 공용부분에 존재하는 것으로 추정한다."},{"법령":"집합건물의 소유 및 관리에 관한 법률","조문":"제5조 제3항","원문":"③ 구분소유자는 그 전유부분이나 공용부분을 보존하거나 개량하기 위하여 필요한 범위에서 다른 구분소유자의 전유부분 또는 자기의 공유(共有)에 속하지 아니하는 공용부분의 사용을 청구할 수 있다. 이 경우 다른 구분소유자가 손해를 입었을 때에는 보상하여야 한다."},{"법령":"집합건물의 소유 및 관리에 관한 법률","조문":"제18조","원문":"제18조(공용부분에 관하여 발생한 채권의 효력) 공유자가 공용부분에 관하여 다른 공유자에 대하여 가지는 채권은 그 특별승계인에 대하여도 행사할 수 있다."},{"법령":"집합건물의 소유 및 관리에 관한 법률","조문":"제8조","원문":"제8조(대지공유자의 분할청구 금지) 대지 위에 구분소유권의 목적인 건물이 속하는 1동의 건물이 있을 때에는 그 대지의 공유자는 그 건물 사용에 필요한 범위의 대지에 대하여는 분할을 청구하지 못한다."},{"법령":"집합건물의 소유 및 관리에 관한 법률","조문":"제13조 제1항 제2항","원문":"① 공용부분에 대한 공유자의 지분은 그가 가지는 전유부분의 처분에 따른다.\n② 공유자는 그가 가지는 전유부분과 분리하여 공용부분에 대한 지분을 처분할 수 없다."}],"선지":[{"번호":1,"판정":"옳음","설명":"제6조가 흠의 공용부분 존재를 추정한다."},{"번호":2,"판정":"틀림","설명":"구분소유자는 전유부분이나 공용부분을 보존하거나 개량하기 위해 필요한 범위에서 다른 구분소유자의 전유부분 사용을 청구할 수 있다. 손해를 입은 구분소유자에게는 보상한다(제5조제3항)."},{"번호":3,"판정":"틀림","설명":"공유자가 다른 공유자에 대해 가지는 채권은 그 특별승계인에 대하여도 행사할 수 있다(제18조)."},{"번호":4,"판정":"틀림","설명":"대지공유자는 건물 사용에 필요한 범위의 대지에 대하여 분할을 청구하지 못한다(제8조)."},{"번호":5,"판정":"틀림","설명":"공용부분 지분은 전유부분의 처분에 따르며 분리 처분할 수 없다(제13조제1항ㆍ제2항)."}],"개념":[{"종류":"표","제목":"전유부분과 공용부분ㆍ대지사용권의 일체성","머리":["항목","내용","근거"],"행":[["공용부분 귀속","구분소유자 전원의 공유. 일부공용부분은 그들 구분소유자의 공유","제10조제1항"],["공용부분 지분","전유부분 면적 비율. 전유부분 처분에 따르고 분리 처분 불가","제12조, 제13조"],["공용부분 물권 변동","등기 불필요","제13조제3항"],["대지사용권","전유부분 처분에 따르고 분리 처분 불가(규약으로 달리 정하면 예외). 분리처분금지는 등기해야 선의 제3자에게 대항","제20조"],["대지 분할청구","건물 사용에 필요한 범위의 대지는 분할청구 불가","제8조"],["공용부분 채권","특별승계인에게도 행사 가능","제18조"],["흠 추정","건물의 설치ㆍ보존상 흠은 공용부분에 있는 것으로 추정","제6조"]]},{"종류":"표","제목":"관리인과 관리단집회","머리":["항목","내용","근거"],"행":[["관리인 선임 의무","구분소유자 10인 이상이면 선임","제24조제1항"],["관리인 임기","2년 범위에서 규약으로 정함, 구분소유자일 필요 없음","제24조제2항"],["관리단집회 의결","구분소유자 과반수 및 의결권 과반수","제38조제1항"],["구분소유권 경매 청구 결의","구분소유자 4분의 3 이상 및 의결권 4분의 3 이상","제45조제2항"],["의결권 행사","서면, 전자적 방법 또는 대리인","제38조제2항"]]}],"함정":"다섯 선지 중 네 개가 법 조문의 결론을 반대로 적었다. 구분소유자 간 사용 청구는 가능, 채권은 승계, 대지 분할은 금지, 지분은 전유부분과 일체라는 방향을 한 묶음으로 외운다."}},{"i":"S2-2-1-중개사법-38","r":"S2","g":2,"c":2,"n":38,"s":"중개사법","q":"甲 소유의 X주택에 대하여 임차인 乙이 2024.3.4. 주택의 인도를 받고 주민등록(전입신고)을 마쳤으며 같은 날 임대차계약증서에 확정일자를 받았다. 그 후 甲의 채권자 丙이 2024.7.1.에, 채권자 丁이 2024.11.1.에 각각 X주택에 근저당권설정등기를 마쳤다. 乙의 보증금은 2억원이다. 임차인 乙에게 개업공인중개사가 설명한 내용으로 옳은 것은? (다툼이 있으면 판례에 따름)","b":null,"bs":"없음","img":[],"ch":["丙이 근저당권을 실행하여 X주택이 경매로 매각된 경우, 乙이 배당요구를 하지 않았다면 매수인은 乙의 임차권을 인수한다.","丙이 근저당권을 실행하여 X주택이 경매로 매각된 경우, 乙이 배당요구를 하여 보증금 중 일부만 배당받았다면 乙의 임차권은 매각으로 소멸한다.","乙은 경매개시결정 후 별도의 배당요구를 하지 않아도 확정일자에 따른 순위로 丙, 丁보다 우선하여 배당받을 수 있다.","X주택이 경매로 매각된 경우 乙이 우선변제권으로 보증금을 배당받으려면 X주택을 임대인 甲에게 먼저 인도하여야 한다.","乙이 임차권등기명령에 따른 임차권등기를 마친 후 이사하면서 주민등록을 이전하면 乙은 대항력과 우선변제권을 상실한다."],"a":[1],"L":"중3-2","o":"변형","x":{"한줄":"乙은 丙의 근저당권보다 먼저 대항력을 갖춘 선순위 임차인이다. 배당요구로 보증금을 전부 받지 못하는 한 임차권은 매각으로 소멸하지 않는다(주택임대차보호법 제3조의5 단서).","근거":[{"법령":"주택임대차보호법","조문":"제3조 제1항","원문":"① 임대차는 그 등기(登記)가 없는 경우에도 임차인(賃借人)이 주택의 인도(引渡)와 주민등록을 마친 때에는 그 다음 날부터 제삼자에 대하여 효력이 생긴다. 이 경우 전입신고를 한 때에 주민등록이 된 것으로 본다."},{"법령":"주택임대차보호법","조문":"제3조의5","원문":"제3조의5(경매에 의한 임차권의 소멸) 임차권은 임차주택에 대하여 「민사집행법」에 따른 경매가 행하여진 경우에는 그 임차주택의 경락(競落)에 따라 소멸한다. 다만, 보증금이 모두 변제되지 아니한, 대항력이 있는 임차권은 그러하지 아니하다."},{"법령":"주택임대차보호법","조문":"제3조의2 제2항 제3항","원문":"② 제3조제1항ㆍ제2항 또는 제3항의 대항요건(對抗要件)과 임대차계약증서(제3조제2항 및 제3항의 경우에는 법인과 임대인 사이의 임대차계약증서를 말한다)상의 확정일자(確定日字)를 갖춘 임차인은 「민사집행법」에 따른 경매 또는 「국세징수법」에 따른 공매(公賣)를 할 때에 임차주택(대지를 포함한다)의 환가대금(換價代金)에서 후순위권리자(後順位權利者)나 그 밖의 채권자보다 우선하여 보증금을 변제(辨濟)받을 권리가 있다.\n③ 임차인은 임차주택을 양수인에게 인도하지 아니하면 제2항에 따른 보증금을 받을 수 없다."},{"법령":"주택임대차보호법","조문":"제3조의3 제5항","원문":"⑤ 임차인은 임차권등기명령의 집행에 따른 임차권등기를 마치면 제3조제1항ㆍ제2항 또는 제3항에 따른 대항력과 제3조의2제2항에 따른 우선변제권을 취득한다. 다만, 임차인이 임차권등기 이전에 이미 대항력이나 우선변제권을 취득한 경우에는 그 대항력이나 우선변제권은 그대로 유지되며, 임차권등기 이후에는 제3조제1항ㆍ제2항 또는 제3항의 대항요건을 상실하더라도 이미 취득한 대항력이나 우선변제권을 상실하지 아니한다."},{"법령":"민사집행법","조문":"제88조 제1항","원문":"①집행력 있는 정본을 가진 채권자, 경매개시결정이 등기된 뒤에 가압류를 한 채권자, 민법ㆍ상법, 그 밖의 법률에 의하여 우선변제청구권이 있는 채권자는 배당요구를 할 수 있다."}],"선지":[{"번호":1,"판정":"옳음","설명":"乙의 대항력은 2024.3.5.부터 생겨 丙의 근저당 설정 2024.7.1.보다 앞선다. 배당요구를 하지 않아 보증금이 변제되지 않았으므로 임차권은 소멸하지 않고 매수인이 인수한다(제3조의5 단서)."},{"번호":2,"판정":"틀림","설명":"대항력 있는 임차권은 보증금이 모두 변제되지 않으면 소멸하지 않는다. 일부만 배당받으면 나머지 보증금에 관하여 매수인에게 대항할 수 있다(제3조의5 단서)."},{"번호":3,"판정":"틀림","설명":"우선변제를 받으려면 배당요구종기까지 배당요구를 해야 한다. 우선변제권이 있어도 배당요구 없이 당연히 배당되지는 않는다(민사집행법 제88조제1항, 제84조제1항)."},{"번호":4,"판정":"틀림","설명":"임차인은 임차주택을 양수인(매수인)에게 인도해야 보증금을 받을 수 있다(제3조의2제3항). 임대인에게 인도하는 것이 아니다."},{"번호":5,"판정":"틀림","설명":"임차권등기를 마치면 그 후 대항요건을 잃어도 이미 취득한 대항력과 우선변제권은 상실되지 않는다(제3조의3제5항)."}],"개념":[{"종류":"흐름","제목":"임차인의 우선변제권 행사 절차","단계":[{"이름":"요건 구비","설명":"주택의 인도와 주민등록(대항요건)을 마치고 임대차계약증서에 확정일자를 받는다. 대항력은 그 다음 날부터 생긴다(제3조제1항, 제3조의2제2항)."},{"이름":"경매 개시","설명":"담보권자나 일반 채권자의 신청으로 경매개시결정이 나면 집행법원이 배당요구의 종기를 첫 매각기일 이전으로 정한다(민사집행법 제84조제1항)."},{"이름":"배당요구","설명":"우선변제청구권이 있는 채권자는 배당요구종기까지 배당요구를 한다(민사집행법 제88조제1항, 제84조)."},{"이름":"매각과 인도","설명":"임차주택을 양수인에게 인도해야 보증금을 받을 수 있다(제3조의2제3항)."},{"이름":"배당","설명":"환가대금에서 후순위권리자나 그 밖의 채권자보다 우선하여 변제받는다. 순위는 대항요건과 확정일자를 갖춘 시점과 담보물권 설정 시점의 선후로 가른다."}]},{"종류":"비교","제목":"대항력 있는 선순위 임차인의 경매 취급 (제3조의5)","왼쪽":{"이름":"배당요구를 하지 않은 경우","항목":["보증금이 변제되지 않음","임차권은 소멸하지 않음","매수인이 임차권을 인수하고 임대인 지위를 승계","임차인은 매수인에게 보증금 반환 청구"]},"오른쪽":{"이름":"배당요구를 한 경우","항목":["보증금 전액 배당받으면 임차권 소멸","일부만 배당받으면 나머지 보증금에 관하여 임차권이 존속","배당 순위는 우선변제권 발생 시점 기준","배당을 받으려면 매수인에게 주택 인도"]}}],"함정":"선순위 임차인이 배당요구를 하면 임차권이 반드시 소멸한다고 읽으면 2번이 맞아 보인다. 소멸 여부는 보증금을 전부 변제받았는지로 정해진다. 3번은 확정일자가 있으면 자동 배당된다고 믿게 하는 문장이고, 4번은 인도 상대방을 임대인으로 바꿨다."}},{"i":"S2-2-1-중개사법-39","r":"S2","g":2,"c":2,"n":39,"s":"중개사법","q":"공인중개사의 매수신청대리인 등록 등에 관한 규칙에 따른 매수신청대리인에 관한 설명으로 옳은 것은?","b":null,"bs":"없음","img":[],"ch":["매수신청대리인으로 등록하려는 개업공인중개사는 법원행정처장에게 등록하여야 한다.","매수신청대리인은 매각장소 또는 집행법원에서의 대리행위를 소속공인중개사에게 대신 출석하게 하여 할 수 있다.","매수신청대리 보수의 지급시기를 약정하지 않은 경우에는 위임계약을 체결한 날로 한다.","자동차와 건설기계도 매수신청대리의 대상물에 해당한다.","매수신청대리인으로 등록하려는 개업공인중개사는 등록신청일 전 1년 이내에 법원행정처장이 지정하는 교육기관에서 부동산 경매에 관한 실무교육을 이수하여야 한다."],"a":[5],"L":"중3-3","o":"변형","x":{"한줄":"등록하려는 개업공인중개사는 등록신청일 전 1년 이내에 법원행정처장이 지정한 교육기관에서 부동산 경매 실무교육을 이수해야 한다(규칙 제10조제1항).","근거":[{"법령":"공인중개사의 매수신청대리인 등록 등에 관한 규칙","조문":"제10조 제1항","원문":"①매수신청대리인 등록을 하고자 하는 개업공인중개사(다만, 법인인 개업공인중개사의 경우에는 공인중개사인 대표자를 말한다)는 등록신청일 전 1년 이내에 법원행정처장이 지정하는 교육기관에서 부동산 경매에 관한 실무교육을 이수하여야 한다. 다만, 제13조의2제1항 및 제18조제4항제2호의 규정에 따른 폐업신고 후 1년 이내에 다시 등록신청을 하고자 하는 자는 그러하지 아니하다."},{"법령":"공인중개사의 매수신청대리인 등록 등에 관한 규칙","조문":"제4조","원문":"제4조(매수신청대리인 등록) 매수신청대리인이 되고자 하는 개업공인중개사는 중개사무소(법인인 개업공인중개사의 경우에는 주된 중개사무소를 말한다)가 있는 곳을 관할하는 지방법원의 장(이하 \"지방법원장\"이라 한다)에게 매수신청대리인 등록을 하여야 한다."},{"법령":"공인중개사의 매수신청대리인 등록 등에 관한 규칙","조문":"제14조 제3항","원문":"③개업공인중개사는 제2조의 규정에 따른 대리행위를 함에 있어서 매각장소 또는 집행법원에 직접 출석하여야 한다."},{"법령":"공인중개사의 매수신청대리인 등록 등에 관한 규칙","조문":"제17조 제5항","원문":"⑤ 보수의 지급시기는 매수신청인과 매수신청대리인의 약정에 따르며, 약정이 없을 때에는 매각대금의 지급기한일로 한다."},{"법령":"공인중개사의 매수신청대리인 등록 등에 관한 규칙","조문":"제3조","원문":"제3조(매수신청대리의 대상물) 이 규칙에 의한 매수신청대리의 대상물은 다음 각 호와 같다.\n1. 토지\n2. 건물 그 밖의 토지의 정착물\n3. 「입목에 관한 법률」에 따른 입목\n4. 「공장 및 광업재단 저당법」에 따른 공장재단, 광업재단\n5. 삭제<2017.5.25>"}],"선지":[{"번호":1,"판정":"틀림","설명":"등록 상대방은 중개사무소(법인은 주된 중개사무소) 소재지를 관할하는 지방법원장이다(규칙 제4조)."},{"번호":2,"판정":"틀림","설명":"개업공인중개사는 대리행위를 할 때 매각장소 또는 집행법원에 직접 출석해야 한다(규칙 제14조제3항)."},{"번호":3,"판정":"틀림","설명":"약정이 없으면 매각대금의 지급기한일이다(규칙 제17조제5항)."},{"번호":4,"판정":"틀림","설명":"대상물은 토지, 건물 그 밖의 토지의 정착물, 입목, 공장재단, 광업재단이다(규칙 제3조). 자동차ㆍ건설기계는 없다."},{"번호":5,"판정":"옳음","설명":"교육 이수 시기는 등록신청일 전 1년 이내다. 폐업신고 후 1년 이내에 다시 등록하는 경우에는 면제된다(규칙 제10조제1항)."}],"개념":[{"종류":"표","제목":"매수신청대리인 등록ㆍ감독 숫자 모음","머리":["항목","내용","근거"],"행":[["등록 요건","개업공인중개사, 경매 실무교육 이수, 보증보험ㆍ공제 가입 또는 공탁","규칙 제5조"],["보증금액","법인 4억원 이상(분사무소마다 2억원 추가), 법인 아닌 개업공인중개사 2억원 이상","규칙 제13조제1항"],["공탁금 회수","폐업ㆍ사망ㆍ해산한 날부터 3년 이내에는 회수 불가","규칙 제11조제3항"],["휴업","3월 초과 휴업은 사전 신고, 휴업은 6월 초과 불가","규칙 제13조의2"],["신고 사유","사무소 이전, 휴폐업, 자격취소ㆍ정지, 등록취소, 업무정지, 분사무소 설치는 사유 발생일부터 10일 이내 지방법원장에게 신고","규칙 제18조제4항"],["등록 결격","등록 취소 후 3년이 지나지 않은 자 등(폐업에 따른 취소는 제외)","규칙 제6조제1호"],["업무정지 기간","1월 이상 2년 이하","규칙 제22조제3항"],["사건카드ㆍ확인설명서 보존","5년","규칙 제15조, 제16조"]]},{"종류":"흐름","제목":"경매 절차와 매수신청대리 행위","단계":[{"이름":"배당요구 종기","설명":"집행법원이 경매개시결정에 따른 압류의 효력이 생긴 때 첫 매각기일 이전으로 정한다(민사집행법 제84조제1항)."},{"이름":"위임과 설명","설명":"대리권 증명 문서를 내고, 대상물의 권리관계와 매수인이 부담할 사항을 설명하여 서면으로 교부한다(규칙 제14조, 제16조)."},{"이름":"매수신청","설명":"매수신청 보증 제공, 입찰표 작성ㆍ제출을 대리한다(규칙 제2조제1호ㆍ제2호)."},{"이름":"차순위매수신고","설명":"신고액이 최고가매수신고액에서 보증액을 뺀 금액을 넘을 때만 할 수 있다(민사집행법 제114조제2항). 대리 가능(규칙 제2조제3호)."},{"이름":"보증 반환 신청","설명":"최고가매수신고인과 차순위매수신고인이 아니면 매수신청 보증 반환을 신청할 수 있다(민사집행법 제115조제3항, 규칙 제2조제4호)."},{"이름":"대금 지급","설명":"매각허가결정이 확정되면 지급기한이 정해지고, 대금을 다 낸 때 소유권을 취득한다(민사집행법 제142조, 제135조)."}]}],"함정":"1번은 등록 상대방을 법원행정처장으로 바꿨고 실제는 관할 지방법원장이다. 법원행정처장은 교육기관 지정과 협회 감독 단계에 나온다. 2번은 직접 출석이 의무라는 점을 뒤집었다."}},{"i":"S2-2-1-중개사법-40","r":"S2","g":2,"c":2,"n":40,"s":"중개사법","q":"매수신청대리인으로 등록한 개업공인중개사가 X부동산에 대한 「민사집행법」상 경매절차에서 매수신청대리의 위임인에게 설명한 내용으로 틀린 것은? (다툼이 있으면 판례에 따름)","b":null,"bs":"없음","img":[],"ch":["최선순위의 전세권자는 배당요구 없이도 우선변제를 받을 수 있으며, 이 때 전세권은 매각으로 소멸한다.","X부동산에 대한 경매개시결정의 기입등기 전에 유치권을 취득한 자는 경매절차의 매수인에게 자기의 유치권으로 대항할 수 있다.","최선순위의 지상권은 경매절차의 매수인이 인수한다.","후순위 저당권자의 신청에 의한 경매라 하여도 선순위 저당권자의 저당권은 매각으로 소멸한다.","집행법원은 배당요구의 종기를 첫 매각기일 이전으로 정한다."],"a":[1],"L":"중3-3","o":"기출","x":{"한줄":"최선순위 전세권은 매수인이 인수하는 것이 원칙이고, 전세권자가 배당요구를 하면 매각으로 소멸한다. 배당요구 없이 우선변제를 받는다는 말이 틀렸다.","근거":[{"법령":"민사집행법","조문":"제91조 제2항 제3항 제4항 제5항","원문":"②매각부동산 위의 모든 저당권은 매각으로 소멸된다.\n③지상권ㆍ지역권ㆍ전세권 및 등기된 임차권은 저당권ㆍ압류채권ㆍ가압류채권에 대항할 수 없는 경우에는 매각으로 소멸된다.\n④제3항의 경우 외의 지상권ㆍ지역권ㆍ전세권 및 등기된 임차권은 매수인이 인수한다. 다만, 그중 전세권의 경우에는 전세권자가 제88조에 따라 배당요구를 하면 매각으로 소멸된다.\n⑤매수인은 유치권자(留置權者)에게 그 유치권(留置權)으로 담보하는 채권을 변제할 책임이 있다."},{"법령":"민사집행법","조문":"제88조 제1항","원문":"①집행력 있는 정본을 가진 채권자, 경매개시결정이 등기된 뒤에 가압류를 한 채권자, 민법ㆍ상법, 그 밖의 법률에 의하여 우선변제청구권이 있는 채권자는 배당요구를 할 수 있다."},{"법령":"민사집행법","조문":"제84조 제1항","원문":"①경매개시결정에 따른 압류의 효력이 생긴 때(그 경매개시결정전에 다른 경매개시결정이 있은 경우를 제외한다)에는 집행법원은 절차에 필요한 기간을 고려하여 배당요구를 할 수 있는 종기(終期)를 첫 매각기일 이전으로 정한다."}],"선지":[{"번호":1,"판정":"틀림","설명":"전세권자는 배당요구를 해야 우선변제를 받고 그때 전세권이 소멸한다. 배당요구를 하지 않으면 매수인이 인수한다(민사집행법 제91조제4항 단서, 제88조제1항)."},{"번호":2,"판정":"옳음","설명":"매수인은 유치권자에게 유치권으로 담보하는 채권을 변제할 책임이 있다(제91조제5항). 경매개시결정 기입등기로 압류의 효력이 생기기 전에 취득한 유치권은 매수인에게 대항할 수 있고, 압류 효력 발생 후에 취득한 유치권은 대항할 수 없다는 것이 판례다."},{"번호":3,"판정":"옳음","설명":"저당권ㆍ압류ㆍ가압류에 대항할 수 있는 최선순위 지상권은 소멸하지 않고 매수인이 인수한다(제91조제4항)."},{"번호":4,"판정":"옳음","설명":"매각부동산 위의 모든 저당권은 매각으로 소멸한다(제91조제2항). 소멸주의가 적용되어 신청한 사람이 후순위여도 같다."},{"번호":5,"판정":"옳음","설명":"배당요구 종기는 첫 매각기일 이전으로 정한다(제84조제1항)."}],"개념":[{"종류":"표","제목":"경매에서 매수인이 인수하는 권리와 소멸하는 권리","머리":["권리","취급","근거"],"행":[["저당권","모두 매각으로 소멸","민사집행법 제91조제2항"],["지상권ㆍ지역권ㆍ전세권ㆍ등기된 임차권(저당권ㆍ압류ㆍ가압류에 대항할 수 없는 것)","소멸","제91조제3항"],["최선순위 지상권ㆍ지역권","매수인이 인수","제91조제4항"],["최선순위 전세권","인수가 원칙. 전세권자가 배당요구를 하면 소멸","제91조제4항 단서"],["유치권","매수인이 유치권으로 담보하는 채권을 변제할 책임을 짐. 압류 효력 발생 전에 취득한 유치권만 대항 가능(판례)","제91조제5항"],["대항력 있는 임차권(주택임대차보호법)","보증금이 모두 변제되지 않으면 소멸하지 않음","주택임대차보호법 제3조의5"]]},{"종류":"표","제목":"배당요구와 매수신청에 관한 절차 규정","머리":["항목","내용","근거"],"행":[["배당요구 종기 결정","압류 효력이 생긴 때 첫 매각기일 이전, 1주 이내에 결정 및 공고","제84조제1항ㆍ제3항"],["배당요구권자","집행력 있는 정본을 가진 채권자, 경매개시결정 등기 후 가압류채권자, 우선변제청구권이 있는 채권자","제88조제1항"],["배당요구 철회","매수인 인수 부담이 바뀌면 종기 후 철회 불가","제88조제2항"],["차순위매수신고","신고액이 최고가매수신고액에서 보증액을 뺀 금액을 넘을 때에 한함","제114조"],["소유권 취득","매각대금을 다 낸 때","제135조"]]}],"함정":"전세권과 지상권은 최선순위이면 인수가 원칙이라는 점은 같지만 전세권에만 배당요구에 따른 소멸 예외가 있다. 1번은 이 예외를 배당요구 없이도 소멸하는 것으로 넓혀 놓았다. 유치권은 기입등기 전에 취득했느냐가 대항 여부를 가른다."}},{"i":"S2-2-1-공법-01","r":"S2","g":2,"c":2,"n":41,"s":"공법","q":"국토의 계획 및 이용에 관한 법령상 광역계획권과 광역도시계획에 관한 설명으로 틀린 것은?","b":null,"bs":"없음","img":[],"ch":["광역계획권이 둘 이상의 시ㆍ도의 관할 구역에 걸쳐 있는 경우 광역계획권은 도지사가 지정한다.","도지사가 광역계획권을 지정하려면 관계 중앙행정기관의 장, 관계 시ㆍ도지사, 시장 또는 군수의 의견을 들은 후 지방도시계획위원회의 심의를 거쳐야 한다.","국토교통부장관은 시ㆍ도지사가 요청하는 경우 관할 시ㆍ도지사와 공동으로 광역도시계획을 수립할 수 있다.","광역도시계획안에 대하여 의견을 요청받은 지방의회와 관계 시장 또는 군수는 특별한 사유가 없으면 30일 이내에 의견을 제시하여야 한다.","광역계획권이 같은 도의 관할 구역에 속하는 경우 광역계획권을 지정한 날부터 3년이 지날 때까지 관할 시장 또는 군수로부터 승인 신청이 없으면 관할 도지사가 광역도시계획을 수립한다."],"a":[1],"L":"공1-1","o":"변형","x":{"한줄":"둘 이상의 시ㆍ도에 걸친 광역계획권은 국토교통부장관이 지정하고, 도지사는 한 도의 관할 구역 안에 있는 광역계획권만 지정한다.","근거":[{"법령":"국토의 계획 및 이용에 관한 법률","조문":"제10조제1항","원문":"국토교통부장관 또는 도지사는 둘 이상의 특별시ㆍ광역시ㆍ특별자치시ㆍ특별자치도ㆍ시 또는 군의 공간구조 및 기능을 상호 연계시키고 환경을 보전하며 광역시설을 체계적으로 정비하기 위하여 필요한 경우에는 다음 각 호의 구분에 따라 인접한 둘 이상의 특별시ㆍ광역시ㆍ특별자치시ㆍ특별자치도ㆍ시 또는 군의 관할 구역 전부 또는 일부를 대통령령으로 정하는 바에 따라 광역계획권으로 지정할 수 있다. 1. 광역계획권이 둘 이상의 특별시ㆍ광역시ㆍ특별자치시ㆍ도 또는 특별자치도(이하 \"시ㆍ도\"라 한다)의 관할 구역에 걸쳐 있는 경우: 국토교통부장관이 지정 2. 광역계획권이 도의 관할 구역에 속하여 있는 경우: 도지사가 지정"},{"법령":"국토의 계획 및 이용에 관한 법률","조문":"제10조제4항","원문":"도지사가 광역계획권을 지정하거나 변경하려면 관계 중앙행정기관의 장, 관계 시ㆍ도지사, 시장 또는 군수의 의견을 들은 후 지방도시계획위원회의 심의를 거쳐야 한다."},{"법령":"국토의 계획 및 이용에 관한 법률","조문":"제11조제2항","원문":"국토교통부장관은 시ㆍ도지사가 요청하는 경우와 그 밖에 필요하다고 인정되는 경우에는 제1항에도 불구하고 관할 시ㆍ도지사와 공동으로 광역도시계획을 수립할 수 있다."},{"법령":"국토의 계획 및 이용에 관한 법률","조문":"제15조제3항","원문":"제1항과 제2항에 따른 시ㆍ도, 시 또는 군의 의회와 관계 시장 또는 군수는 특별한 사유가 없으면 30일 이내에 시ㆍ도지사, 시장 또는 군수에게 의견을 제시하여야 한다."},{"법령":"국토의 계획 및 이용에 관한 법률","조문":"제11조제1항제1호ㆍ제3호","원문":"국토교통부장관, 시ㆍ도지사, 시장 또는 군수는 다음 각 호의 구분에 따라 광역도시계획을 수립하여야 한다. 1. 광역계획권이 같은 도의 관할 구역에 속하여 있는 경우: 관할 시장 또는 군수가 공동으로 수립 3. 광역계획권을 지정한 날부터 3년이 지날 때까지 관할 시장 또는 군수로부터 제16조제1항에 따른 광역도시계획의 승인 신청이 없는 경우: 관할 도지사가 수립"}],"선지":[{"번호":1,"판정":"틀림","설명":"둘 이상의 시ㆍ도에 걸쳐 있으면 국토교통부장관이 지정한다. 도지사는 광역계획권이 도의 관할 구역에 속한 경우에 지정한다(법 제10조제1항)."},{"번호":2,"판정":"옳음","설명":"도지사의 지정ㆍ변경은 관계 중앙행정기관의 장, 시ㆍ도지사, 시장 또는 군수의 의견 청취 후 지방도시계획위원회 심의를 거친다. 국토교통부장관이 지정할 때는 중앙도시계획위원회 심의다(법 제10조제3항ㆍ제4항)."},{"번호":3,"판정":"옳음","설명":"국토교통부장관은 시ㆍ도지사의 요청이 있거나 필요하다고 인정하면 관할 시ㆍ도지사와 공동으로 수립할 수 있다(법 제11조제2항)."},{"번호":4,"판정":"옳음","설명":"의견 제시 기한은 30일이다(법 제15조제3항). 시ㆍ도지사, 시장 또는 군수가 수립ㆍ변경할 때 미리 의회와 관계 시장ㆍ군수의 의견을 듣는다(법 제15조제1항)."},{"번호":5,"판정":"옳음","설명":"지정일부터 3년이 지나도록 시장ㆍ군수의 승인 신청이 없으면 도지사가 수립한다. 시ㆍ도지사의 신청이 없으면 국토교통부장관이 수립한다(법 제11조제1항제3호ㆍ제4호)."}],"개념":[{"종류":"표","제목":"광역도시계획의 수립권자(법 제11조)","머리":["광역계획권의 범위","수립권자","확정"],"행":[["같은 도 안","관할 시장ㆍ군수 공동","도지사 승인(법 제16조제5항)"],["둘 이상의 시ㆍ도에 걸침","관할 시ㆍ도지사 공동","국토교통부장관 승인(법 제16조제1항)"],["지정한 날부터 3년간 시장ㆍ군수의 승인 신청 없음","도지사","도지사가 직접 수립(법 제11조제1항제3호)"],["국가계획 관련 또는 지정한 날부터 3년간 시ㆍ도지사의 승인 신청 없음","국토교통부장관","직접 수립, 관계 중앙행정기관 협의 후 중앙도시계획위원회 심의(법 제16조제2항)"],["시ㆍ도지사 요청 또는 필요 인정","국토교통부장관과 시ㆍ도지사 공동","관계 중앙행정기관 협의 후 중앙도시계획위원회 심의(법 제16조제2항)"]]},{"종류":"흐름","제목":"광역도시계획의 수립 절차","단계":[{"이름":"광역계획권 지정","설명":"국토교통부장관 또는 도지사가 지정, 의견 청취 후 중앙 또는 지방도시계획위원회 심의(법 제10조)"},{"이름":"기초조사","설명":"수립ㆍ변경 전에 인구ㆍ경제ㆍ토지이용 등을 조사(법 제13조)"},{"이름":"공청회","설명":"미리 공청회를 열어 주민ㆍ전문가 의견 청취, 타당하면 반영(법 제14조)"},{"이름":"지방자치단체 의견 청취","설명":"관계 의회와 시장ㆍ군수 의견, 30일 이내 제시(법 제15조)"},{"이름":"승인","설명":"관계 행정기관 협의 후 도시계획위원회 심의(법 제16조제2항ㆍ제6항)"},{"이름":"공고ㆍ열람","설명":"관계 서류 송부 후 시ㆍ도지사 등이 공고하고 일반이 열람(법 제16조제4항)"}]}],"함정":"국토교통부장관과 도지사의 지정 범위를 맞바꾼 선지 1을 놓치기 쉽다. 선지 3의 공동 수립은 법 제11조제2항이 허용하는 방식이다."}},{"i":"S2-2-1-공법-02","r":"S2","g":2,"c":2,"n":42,"s":"공법","q":"국토의 계획 및 이용에 관한 법령상 주민이 도시ㆍ군관리계획의 입안권자에게 그 입안을 제안할 수 있는 사항이 아닌 것은?","b":null,"bs":"없음","img":[],"ch":["도시ㆍ군계획시설입체복합구역의 지정 및 변경과 도시ㆍ군계획시설입체복합구역의 건축제한ㆍ건폐율ㆍ용적률ㆍ높이 등에 관한 사항","지구단위계획구역의 지정 및 변경과 지구단위계획의 수립 및 변경에 관한 사항","기반시설의 설치ㆍ정비 또는 개량에 관한 사항","산업ㆍ유통개발진흥지구의 변경에 관한 사항","시가화조정구역의 지정 및 변경에 관한 사항"],"a":[5],"L":"공1-2","o":"기출","x":{"한줄":"시가화조정구역의 지정ㆍ변경은 법 제26조제1항이 정한 입안 제안 대상 사항에 들어 있지 않다.","근거":[{"법령":"국토의 계획 및 이용에 관한 법률","조문":"제26조제1항","원문":"주민(이해관계자를 포함한다. 이하 같다)은 다음 각 호의 사항에 대하여 제24조에 따라 도시ㆍ군관리계획을 입안할 수 있는 자에게 도시ㆍ군관리계획의 입안을 제안할 수 있다. 이 경우 제안서에는 도시ㆍ군관리계획도서와 계획설명서를 첨부하여야 한다. 1. 기반시설의 설치ㆍ정비 또는 개량에 관한 사항 2. 지구단위계획구역의 지정 및 변경과 지구단위계획의 수립 및 변경에 관한 사항 3. 다음 각 목의 어느 하나에 해당하는 용도지구의 지정 및 변경에 관한 사항 가. 개발진흥지구 중 공업기능 또는 유통물류기능 등을 집중적으로 개발ㆍ정비하기 위한 개발진흥지구로서 대통령령으로 정하는 개발진흥지구 나. 제37조에 따라 지정된 용도지구 중 해당 용도지구에 따른 건축물이나 그 밖의 시설의 용도ㆍ종류 및 규모 등의 제한을 지구단위계획으로 대체하기 위한 용도지구 5. 도시ㆍ군계획시설입체복합구역의 지정 및 변경과 도시ㆍ군계획시설입체복합구역의 건축제한ㆍ건폐율ㆍ용적률ㆍ높이 등에 관한 사항"},{"법령":"국토의 계획 및 이용에 관한 법률 시행령","조문":"제19조의2제1항","원문":"법 제26조제1항제3호가목에서 \"대통령령으로 정하는 개발진흥지구\"란 제31조제2항제8호나목에 따른 산업ㆍ유통개발진흥지구를 말한다."}],"선지":[{"번호":1,"판정":"옳음","설명":"도시ㆍ군계획시설입체복합구역의 지정ㆍ변경과 건축제한ㆍ건폐율ㆍ용적률ㆍ높이 등은 제안 대상이다(법 제26조제1항제5호)."},{"번호":2,"판정":"옳음","설명":"지구단위계획구역의 지정ㆍ변경과 지구단위계획의 수립ㆍ변경은 제안 대상이다(법 제26조제1항제2호)."},{"번호":3,"판정":"옳음","설명":"기반시설의 설치ㆍ정비 또는 개량은 제안 대상이다(법 제26조제1항제1호)."},{"번호":4,"판정":"옳음","설명":"산업ㆍ유통개발진흥지구는 제안 대상 용도지구의 하나이고, 지정뿐 아니라 변경도 제안할 수 있다(법 제26조제1항제3호가목, 영 제19조의2제1항)."},{"번호":5,"판정":"틀림","설명":"시가화조정구역의 지정ㆍ변경은 도시ㆍ군관리계획 내용(법 제2조제4호나목)이지만 주민이 입안을 제안할 수 있는 사항으로 열거되어 있지 않다(법 제26조제1항)."}],"개념":[{"종류":"표","제목":"주민의 도시ㆍ군관리계획 입안 제안 대상(법 제26조제1항)","머리":["호","제안 가능 사항","동의 요건(영 제19조의2제2항)"],"행":[["제1호","기반시설의 설치ㆍ정비 또는 개량","토지 면적 5분의 4 이상"],["제2호","지구단위계획구역의 지정ㆍ변경, 지구단위계획의 수립ㆍ변경","토지 면적 3분의 2 이상"],["제3호가목","산업ㆍ유통개발진흥지구의 지정ㆍ변경","토지 면적 3분의 2 이상"],["제3호나목","지구단위계획으로 제한을 대체하는 용도지구의 지정ㆍ변경","토지 면적 3분의 2 이상"],["제4호","삭제(입지규제최소구역, 2024.2.6)","-"],["제5호","도시ㆍ군계획시설입체복합구역의 지정ㆍ변경과 건축제한 등","토지 면적 5분의 4 이상"],["제안 불가","시가화조정구역, 용도지역, 개발제한구역 등","-"]]},{"종류":"흐름","제목":"입안 제안의 처리","단계":[{"이름":"제안","설명":"제안서에 도시ㆍ군관리계획도서와 계획설명서 첨부(법 제26조제1항)"},{"이름":"검토","설명":"필요하면 중앙 또는 지방도시계획위원회 자문(영 제20조제2항)"},{"이름":"통보","설명":"제안일부터 45일 이내 반영 여부 통보, 부득이하면 1회 30일 연장(영 제20조제1항)"},{"이름":"비용 부담","설명":"제안자와 협의해 입안ㆍ결정 비용의 전부 또는 일부를 제안자에게 부담시킬 수 있음(법 제26조제3항)"}]}],"함정":"입지규제최소구역이 삭제된 뒤 제안 대상은 입체복합구역으로 바뀌었다. 용도구역 가운데 제안할 수 있는 것은 입체복합구역뿐이고, 시가화조정구역을 같은 용도구역으로 묶어 제안 대상으로 착각하기 쉽다.","개정":"씨앗 선지 1의 ‘입지규제최소구역의 지정 및 변경과 입지규제최소구역계획의 수립 및 변경’은 2024.2.6 개정으로 법 제26조제1항제4호와 제40조의2가 삭제되어 제안 대상이 아니다. 이대로 두면 선지 1도 제안할 수 없는 사항이 되어 정답이 둘이 되므로, 후신 제도인 도시ㆍ군계획시설입체복합구역(법 제26조제1항제5호)으로 고쳤다. 정답은 5번 그대로다."}},{"i":"S2-2-1-공법-03","r":"S2","g":2,"c":2,"n":43,"s":"공법","q":"국토의 계획 및 이용에 관한 법령상 주민이 도시ㆍ군관리계획의 입안을 제안하는 경우에 관한 설명으로 틀린 것은?","b":null,"bs":"없음","img":[],"ch":["도시ㆍ군계획시설입체복합구역의 지정 및 변경을 제안하려는 자는 대상 토지 면적(국ㆍ공유지 제외)의 3분의 2 이상에 해당하는 토지소유자의 동의를 받아야 한다.","입안 제안을 받은 시장 또는 군수는 제안일부터 45일 이내에 반영 여부를 제안자에게 통보하여야 하며, 부득이한 사정이 있으면 1회에 한하여 30일을 연장할 수 있다.","산업ㆍ유통개발진흥지구의 지정을 제안할 수 있는 대상지역은 면적이 1만제곱미터 이상 3만제곱미터 미만이어야 한다.","지구단위계획구역의 지정을 제안하려는 자는 대상 토지 면적(국ㆍ공유지 제외)의 3분의 2 이상에 해당하는 토지소유자의 동의를 받아야 한다.","입안 제안을 받은 시장 또는 군수는 반영 여부를 결정할 때 필요하면 해당 지방자치단체에 설치된 지방도시계획위원회의 자문을 거칠 수 있다."],"a":[1],"L":"공1-2","o":"변형","x":{"한줄":"입체복합구역의 지정ㆍ변경 제안은 대상 토지 면적의 5분의 4 이상의 동의가 필요하고, 3분의 2는 지구단위계획구역과 용도지구 제안의 요건이다.","근거":[{"법령":"국토의 계획 및 이용에 관한 법률 시행령","조문":"제19조의2제2항","원문":"법 제26조제1항에 따라 도시ㆍ군관리계획의 입안을 제안하려는 자는 다음 각 호의 구분에 따라 토지소유자의 동의를 받아야 한다. 이 경우 동의 대상 토지 면적에서 국ㆍ공유지는 제외한다. 1. 법 제26조제1항제1호 및 제5호의 사항에 대한 제안의 경우: 대상 토지 면적의 5분의 4 이상 2. 법 제26조제1항제2호 및 제3호의 사항에 대한 제안의 경우: 대상 토지 면적의 3분의 2 이상"},{"법령":"국토의 계획 및 이용에 관한 법률 시행령","조문":"제20조제1항","원문":"법 제26조제1항에 따라 도시ㆍ군관리계획입안의 제안을 받은 국토교통부장관, 시ㆍ도지사, 시장 또는 군수는 제안일부터 45일 이내에 도시ㆍ군관리계획입안에의 반영여부를 제안자에게 통보하여야 한다. 다만, 부득이한 사정이 있는 경우에는 1회에 한하여 30일을 연장할 수 있다."},{"법령":"국토의 계획 및 이용에 관한 법률 시행령","조문":"제20조제2항","원문":"국토교통부장관, 시ㆍ도지사, 시장 또는 군수는 법 제26조제1항의 규정에 의한 제안을 도시ㆍ군관리계획입안에 반영할 것인지 여부를 결정함에 있어서 필요한 경우에는 중앙도시계획위원회 또는 당해 지방자치단체에 설치된 지방도시계획위원회의 자문을 거칠 수 있다."},{"법령":"국토의 계획 및 이용에 관한 법률 시행령","조문":"제19조의2제3항제1호ㆍ제2호","원문":"법 제26조제4항에 따라 제1항에 따른 산업ㆍ유통개발진흥지구의 지정을 제안할 수 있는 대상지역은 다음 각 호의 요건을 모두 갖춘 지역으로 한다. 1. 지정 대상 지역의 면적은 1만제곱미터 이상 3만제곱미터 미만일 것 2. 지정 대상 지역이 자연녹지지역ㆍ계획관리지역 또는 생산관리지역일 것. 다만, 계획관리지역에 있는 기존 공장의 증축이 필요한 경우로서 해당 공장이 도로ㆍ철도ㆍ하천ㆍ건축물ㆍ바다 등으로 둘러싸여 있어 증축을 위해서는 불가피하게 보전관리지역 또는 농림지역을 포함해야 하는 경우에는 전체 면적의 20퍼센트 이하의 범위에서 보전관리지역 또는 농림지역을 포함하되, 다음 각 목의 어느 하나에 해당하는 경우에는 20퍼센트 이상으로 할 수 있다. 가. 보전관리지역 또는 농림지역의 해당 토지가 개발행위허가를 받는 등 이미 개발된 토지인 경우 나. 보전관리지역 또는 농림지역의 해당 토지를 개발하여도 주변지역의 환경오염ㆍ환경훼손 우려가 없는 경우로서 해당 도시계획위원회의 심의를 거친 경우"}],"선지":[{"번호":1,"판정":"틀림","설명":"제1호(기반시설)와 제5호(입체복합구역) 제안은 대상 토지 면적의 5분의 4 이상 동의다(영 제19조의2제2항제1호)."},{"번호":2,"판정":"옳음","설명":"제안일부터 45일 이내 통보, 부득이한 경우 1회에 한해 30일 연장이다(영 제20조제1항)."},{"번호":3,"판정":"옳음","설명":"지정 대상 지역의 면적은 1만제곱미터 이상 3만제곱미터 미만이다(영 제19조의2제3항제1호)."},{"번호":4,"판정":"옳음","설명":"제2호(지구단위계획)와 제3호(용도지구) 제안은 3분의 2 이상 동의이고, 국ㆍ공유지는 동의 대상 면적에서 뺀다(영 제19조의2제2항제2호)."},{"번호":5,"판정":"옳음","설명":"반영 여부를 정할 때 필요하면 중앙도시계획위원회 또는 해당 지방자치단체의 지방도시계획위원회 자문을 거칠 수 있다(영 제20조제2항)."}],"개념":[{"종류":"표","제목":"입안 제안의 토지소유자 동의 비율(영 제19조의2제2항)","머리":["제안 사항","동의 비율","비고"],"행":[["기반시설의 설치ㆍ정비ㆍ개량(제1호)","대상 토지 면적의 5분의 4 이상","국ㆍ공유지 제외"],["도시ㆍ군계획시설입체복합구역(제5호)","대상 토지 면적의 5분의 4 이상","국ㆍ공유지 제외"],["지구단위계획구역ㆍ지구단위계획(제2호)","대상 토지 면적의 3분의 2 이상","국ㆍ공유지 제외"],["용도지구의 지정ㆍ변경(제3호)","대상 토지 면적의 3분의 2 이상","국ㆍ공유지 제외"]]},{"종류":"표","제목":"산업ㆍ유통개발진흥지구 지정 제안 대상지역(영 제19조의2제3항)","머리":["요건","내용"],"행":[["면적","1만제곱미터 이상 3만제곱미터 미만"],["용도지역","자연녹지지역ㆍ계획관리지역 또는 생산관리지역"],["계획관리지역 비율","지정 대상 지역 전체 면적의 100분의 50 이상"],["토지특성","국토교통부장관이 고시하는 기준에 적합"]]}],"함정":"동의 비율은 제안 사항에 따라 5분의 4와 3분의 2로 갈린다. 기반시설과 입체복합구역은 5분의 4, 지구단위계획구역과 용도지구는 3분의 2다. 선지 1은 입체복합구역의 비율을 3분의 2로 바꿔 놓았다."}},{"i":"S2-2-1-공법-04","r":"S2","g":2,"c":2,"n":44,"s":"공법","q":"국토의 계획 및 이용에 관한 법령상 자연취락지구 안에서 건축할 수 있는 건축물에 해당하지 않는 것은? (단, 4층 이하의 건축물이고, 조례는 고려하지 않음)","b":null,"bs":"없음","img":[],"ch":["마을회관","아파트","골프연습장","축사","발전소"],"a":[2],"L":"공1-3","o":"변형","x":{"한줄":"아파트는 자연취락지구에서 조례로도 건축할 수 없다. 공동주택은 아파트를 뺀 나머지만 조례로 허용된다.","근거":[{"법령":"국토의 계획 및 이용에 관한 법률 시행령","조문":"제78조제1항","원문":"법 제76조제5항제1호의 규정에 의하여 자연취락지구안에서 건축할 수 있는 건축물은 별표 23과 같다."},{"법령":"국토의 계획 및 이용에 관한 법률 시행령","조문":"별표 23 제1호","원문":"건축할 수 있는 건축물(4층 이하의 건축물에 한한다. 다만, 4층 이하의 범위안에서 도시ㆍ군계획조례로 따로 층수를 정하는 경우에는 그 층수 이하의 건축물에 한한다) 가. 「건축법 시행령」 별표 1 제1호의 단독주택 나. 「건축법 시행령」 별표 1 제3호의 제1종 근린생활시설 ... 라. 「건축법 시행령」 별표 1 제13호의 운동시설 ... 바. 「건축법 시행령」 별표 1 제21호의 동물 및 식물관련시설 ... 자. 「건축법 시행령」 별표 1 제24호의 방송통신시설 차. 「건축법 시행령」 별표 1 제25호의 발전시설"},{"법령":"국토의 계획 및 이용에 관한 법률 시행령","조문":"별표 23 제2호 가목","원문":"도시ㆍ군계획조례가 정하는 바에 의하여 건축할 수 있는 건축물(4층 이하의 건축물에 한한다. ...) 가. 「건축법 시행령」 별표 1 제2호의 공동주택(아파트를 제외한다)"}],"선지":[{"번호":1,"판정":"옳음","설명":"마을회관은 제1종 근린생활시설이고(건축법 시행령 별표 1 제3호사목), 제1종 근린생활시설은 별표 23 제1호나목으로 건축할 수 있다."},{"번호":2,"판정":"틀림","설명":"아파트는 공동주택이다. 별표 23 제2호가목이 ‘아파트를 제외한’ 공동주택만 조례로 허용하므로 건축할 수 없다."},{"번호":3,"판정":"옳음","설명":"골프연습장은 운동시설(건축법 시행령 별표 1 제13호)이어서 별표 23 제1호라목으로 건축할 수 있다."},{"번호":4,"판정":"옳음","설명":"축사는 동물 및 식물 관련 시설(건축법 시행령 별표 1 제21호가목)로 별표 23 제1호바목에 든다."},{"번호":5,"판정":"옳음","설명":"발전소는 발전시설(건축법 시행령 별표 1 제25호)로 별표 23 제1호차목에 든다."}],"개념":[{"종류":"표","제목":"자연취락지구 안의 건축제한(영 제78조제1항, 별표 23)","머리":["구분","건축할 수 있는 건축물"],"행":[["제1호(바로 건축 가능)","단독주택, 제1종 근린생활시설, 제2종 근린생활시설(일부 제외), 운동시설, 농ㆍ임ㆍ축ㆍ수산업용 창고, 동물 및 식물 관련 시설, 교정시설, 국방ㆍ군사시설, 방송통신시설, 발전시설"],["제2호(조례로 허용)","아파트를 뺀 공동주택, 일부 제2종 근린생활시설, 문화 및 집회시설, 종교시설, 일부 판매시설, 일부 의료시설, 교육연구시설, 노유자시설, 수련시설, 자원순환 관련 시설, 야영장 시설 등"],["층수","4층 이하(조례로 4층 이하 범위에서 달리 정할 수 있음)"]]},{"종류":"표","제목":"취락지구의 세분(영 제31조제2항제7호)","머리":["지구","대상","건축제한"],"행":[["자연취락지구","녹지ㆍ관리ㆍ농림ㆍ자연환경보전지역 안의 취락 정비","영 제78조제1항, 별표 23"],["보호취락지구","녹지ㆍ관리ㆍ농림ㆍ자연환경보전지역 안의 취락을 농촌 주거환경 보호와 주거기능 강화를 위해 정비","영 제78조제2항, 별표 23의2"],["집단취락지구","개발제한구역 안의 취락 정비","개발제한구역법령에 따름(영 제78조제3항)"],["건폐율","취락지구 60퍼센트 이하","영 제84조제4항제1호"]]}],"함정":"공동주택을 통째로 조례 허용 대상으로 읽으면 아파트도 가능한 것으로 오해한다. 별표 23 제2호가목의 ‘아파트를 제외한다’를 놓치지 않아야 한다."}},{"i":"S2-2-1-공법-05","r":"S2","g":2,"c":2,"n":45,"s":"공법","q":"국토의 계획 및 이용에 관한 법령상 시가화조정구역에서 관할 행정청의 허가를 받아 할 수 있는 행위는? (단, 도시ㆍ군계획사업이 아니며, 주어진 조건 외의 것은 고려하지 않음)","b":null,"bs":"없음","img":[],"ch":["농업을 영위하는 자가 행하는 건축으로서 100제곱미터인 관리용건축물의 건축","증축 면적이 150제곱미터인 주택의 증축","새로운 대지조성을 수반하는 종교시설의 증축","공장ㆍ주택 등 시가화조정구역 안에서의 신축이 금지된 시설의 용도를 동물병원으로 변경하는 행위","시가화조정구역 지정 당시 이미 관계법령의 규정에 의하여 설치된 공장의 부대시설의 설치로서 새로운 대지 조성을 수반하는 건축"],"a":[4],"L":"공1-3","o":"기출","x":{"한줄":"신축이 금지된 공장ㆍ주택 등을 동물병원 같은 근린생활시설로 바꾸는 용도변경은 시가화조정구역에서 허가를 받아 할 수 있다.","근거":[{"법령":"국토의 계획 및 이용에 관한 법률","조문":"제81조제2항","원문":"시가화조정구역에서는 제56조와 제76조에도 불구하고 제1항에 따른 도시ㆍ군계획사업의 경우 외에는 다음 각 호의 어느 하나에 해당하는 행위에 한정하여 특별시장ㆍ광역시장ㆍ특별자치시장ㆍ특별자치도지사ㆍ시장 또는 군수의 허가를 받아 그 행위를 할 수 있다. 1. 농업ㆍ임업 또는 어업용의 건축물 중 대통령령으로 정하는 종류와 규모의 건축물이나 그 밖의 시설을 건축하는 행위 2. 마을공동시설, 공익시설ㆍ공공시설, 광공업 등 주민의 생활을 영위하는 데에 필요한 행위로서 대통령령으로 정하는 행위 3. 입목의 벌채, 조림, 육림, 토석의 채취, 그 밖에 대통령령으로 정하는 경미한 행위"},{"법령":"국토의 계획 및 이용에 관한 법률 시행령","조문":"제88조, 별표 24 제2호","원문":"법 제81조제2항의 규정에 의하여 시가화조정구역안에서 특별시장ㆍ광역시장ㆍ특별자치시장ㆍ특별자치도지사ㆍ시장 또는 군수의 허가를 받아 할 수 있는 행위는 별표 24와 같다. 가. 주택 및 그 부속건축물의 건축으로서 다음의 1에 해당하는 행위 (1) 주택의 증축(기존주택의 면적을 포함하여 100제곱미터 이하에 해당하는 면적의 증축을 말한다) 사. 다음의 1에 해당하는 용도변경행위 (3) 공장ㆍ주택 등 시가화조정구역안에서의 신축이 금지된 시설의 용도를 근린생활시설(수퍼마켓ㆍ... 동물병원ㆍ... 등) 또는 종교시설로 변경하는 행위 아. 종교시설의 증축(새로운 대지조성은 허용되지 아니하며, ...)"}],"선지":[{"번호":1,"판정":"틀림","설명":"농업 등을 영위하는 자의 관리용건축물은 기존 관리용건축물 면적을 포함해 33제곱미터 이하여야 한다. 100제곱미터는 초과한다(영 별표 24 제1호바목)."},{"번호":2,"판정":"틀림","설명":"주택 증축은 기존 주택 면적을 포함해 100제곱미터 이하의 증축만 허용된다. 증축 면적 150제곱미터는 초과한다(영 별표 24 제2호가목(1))."},{"번호":3,"판정":"틀림","설명":"종교시설의 증축은 새로운 대지조성이 허용되지 않는다(영 별표 24 제2호아목)."},{"번호":4,"판정":"옳음","설명":"신축이 금지된 시설을 근린생활시설(동물병원 포함)이나 종교시설로 바꾸는 용도변경은 허가받아 할 수 있다(영 별표 24 제2호사목(3))."},{"번호":5,"판정":"틀림","설명":"기존 공장의 부대시설 설치는 새로운 대지조성이 허용되지 않고 기존 공장 부지 안에서만 할 수 있다(영 별표 24 제2호라목(2))."}],"개념":[{"종류":"표","제목":"시가화조정구역에서 허가받아 할 수 있는 행위(영 별표 24)","머리":["구분","행위","한도"],"행":[["농ㆍ임ㆍ어업용(제1호)","축사, 퇴비사, 잠실, 창고, 생산시설, 양어장","-"],["농ㆍ임ㆍ어업용(제1호)","관리용건축물","기존 면적 포함 33제곱미터 이하"],["주택(제2호가목)","주택의 증축","기존 면적 포함 100제곱미터 이하"],["주택(제2호가목)","부속건축물의 건축","기존 면적 포함 33제곱미터 이하"],["종교시설(제2호아목)","종교시설의 증축","지정 당시 연면적의 200퍼센트 이하, 새 대지조성 불가"],["용도변경(제2호사목)","신축이 금지된 시설을 근린생활시설 또는 종교시설로 변경","-"],["경미한 행위(제3호)","입목의 벌채, 조림, 육림, 토석 채취, 토지의 합병ㆍ분할 등","-"]]},{"종류":"비교","제목":"시가화조정구역의 사업과 행위","왼쪽":{"이름":"도시ㆍ군계획사업","항목":["국방상 또는 공익상 불가피한 사업만 시행(법 제81조제1항)","관계 중앙행정기관장의 요청으로 국토교통부장관이 지정 목적 달성에 지장이 없다고 인정(영 제87조)"]},"오른쪽":{"이름":"개인의 행위","항목":["시장ㆍ군수 등의 허가를 받아 별표 24의 행위만 가능(법 제81조제2항)","허가 전에 공공시설 관리자 등과 협의(법 제81조제3항)"]}}],"함정":"관리용건축물은 기존 면적을 포함해 33제곱미터 이하, 주택 증축은 기존 면적을 포함해 100제곱미터 이하가 한도다. 종교시설의 증축과 공장 부대시설의 설치는 새로운 대지조성을 수반하면 허용되지 않는다."}},{"i":"S2-2-1-공법-06","r":"S2","g":2,"c":2,"n":46,"s":"공법","q":"국토의 계획 및 이용에 관한 법령상 건폐율의 최대한도가 낮은 지역부터 높은 지역 순으로 옳게 나열한 것은? (단, 조례 등 기타 강화ㆍ완화 조건은 고려하지 않음)","b":null,"bs":"없음","img":[],"ch":["제1종전용주거지역 - 계획관리지역 - 일반공업지역","계획관리지역 - 제2종일반주거지역 - 일반상업지역","자연녹지지역 - 중심상업지역 - 준공업지역","보전녹지지역 - 제2종일반주거지역 - 제3종일반주거지역","생산관리지역 - 일반상업지역 - 준주거지역"],"a":[2],"L":"공1-4","o":"변형","x":{"한줄":"계획관리지역 40퍼센트, 제2종일반주거지역 60퍼센트, 일반상업지역 80퍼센트 순으로 높아진다.","근거":[{"법령":"국토의 계획 및 이용에 관한 법률 시행령","조문":"제84조제1항","원문":"법 제77조제1항 및 제2항에 따른 건폐율은 다음 각 호의 범위에서 특별시ㆍ광역시ㆍ특별자치시ㆍ특별자치도ㆍ시 또는 군의 도시ㆍ군계획조례가 정하는 비율 이하로 한다. 1. 제1종전용주거지역 : 50퍼센트 이하 2. 제2종전용주거지역 : 50퍼센트 이하 3. 제1종일반주거지역 : 60퍼센트 이하 4. 제2종일반주거지역 : 60퍼센트 이하 5. 제3종일반주거지역 : 50퍼센트 이하 6. 준주거지역 : 70퍼센트 이하 7. 중심상업지역 : 90퍼센트 이하 8. 일반상업지역 : 80퍼센트 이하 9. 근린상업지역 : 70퍼센트 이하 10. 유통상업지역 : 80퍼센트 이하 11. 전용공업지역 : 70퍼센트 이하 12. 일반공업지역 : 70퍼센트이하 13. 준공업지역 : 70퍼센트 이하 14. 보전녹지지역 : 20퍼센트 이하 15. 생산녹지지역 : 20퍼센트 이하 16. 자연녹지지역 : 20퍼센트 이하 17. 보전관리지역 : 20퍼센트 이하 18. 생산관리지역 : 20퍼센트 이하 19. 계획관리지역 : 40퍼센트 이하 20. 농림지역 : 20퍼센트 이하 21. 자연환경보전지역 : 20퍼센트 이하"}],"선지":[{"번호":1,"판정":"틀림","설명":"제1종전용주거지역 50퍼센트, 계획관리지역 40퍼센트, 일반공업지역 70퍼센트다. 계획관리지역이 가장 낮다(영 제84조제1항제1호ㆍ제12호ㆍ제19호)."},{"번호":2,"판정":"옳음","설명":"계획관리지역 40퍼센트, 제2종일반주거지역 60퍼센트, 일반상업지역 80퍼센트로 점점 높아진다(영 제84조제1항제19호ㆍ제4호ㆍ제8호)."},{"번호":3,"판정":"틀림","설명":"자연녹지지역 20퍼센트, 중심상업지역 90퍼센트, 준공업지역 70퍼센트다. 중심상업지역이 준공업지역보다 높다(영 제84조제1항제16호ㆍ제7호ㆍ제13호)."},{"번호":4,"판정":"틀림","설명":"보전녹지지역 20퍼센트, 제2종일반주거지역 60퍼센트, 제3종일반주거지역 50퍼센트다. 제3종이 제2종보다 낮다(영 제84조제1항제14호ㆍ제4호ㆍ제5호)."},{"번호":5,"판정":"틀림","설명":"생산관리지역 20퍼센트, 일반상업지역 80퍼센트, 준주거지역 70퍼센트다. 준주거지역이 일반상업지역보다 낮다(영 제84조제1항제18호ㆍ제8호ㆍ제6호)."}],"개념":[{"종류":"표","제목":"용도지역별 건폐율 최대한도(영 제84조제1항)","머리":["건폐율","용도지역"],"행":[["20퍼센트","보전녹지ㆍ생산녹지ㆍ자연녹지, 보전관리ㆍ생산관리, 농림, 자연환경보전"],["40퍼센트","계획관리지역"],["50퍼센트","제1종전용주거ㆍ제2종전용주거ㆍ제3종일반주거"],["60퍼센트","제1종일반주거ㆍ제2종일반주거"],["70퍼센트","준주거, 근린상업, 전용공업ㆍ일반공업ㆍ준공업"],["80퍼센트","일반상업, 유통상업"],["90퍼센트","중심상업"]]},{"종류":"표","제목":"건폐율 특례(영 제84조제4항)","머리":["지역","건폐율"],"행":[["취락지구","60퍼센트 이하"],["개발진흥지구(도시지역 외)","40퍼센트(계획관리지역의 산업ㆍ유통개발진흥지구는 60퍼센트)"],["개발진흥지구(자연녹지지역)","30퍼센트"],["수산자원보호구역","40퍼센트 이하"],["자연공원","60퍼센트 이하"],["농공단지","70퍼센트 이하(기반시설이 충분하면 80퍼센트 이하)"]]}],"함정":"일반주거지역 안에서 제3종이 제1종ㆍ제2종보다 낮은 50퍼센트라는 점이 선지 4의 함정이다. 중심상업 90, 일반상업ㆍ유통상업 80, 근린상업 70의 순서도 자주 섞인다."}},{"i":"S2-2-1-공법-07","r":"S2","g":2,"c":2,"n":47,"s":"공법","q":"국토의 계획 및 이용에 관한 법령상 도시ㆍ군계획시설사업에 관한 설명으로 틀린 것은?","b":null,"bs":"없음","img":[],"ch":["시장 또는 군수는 이 법 또는 다른 법률에 특별한 규정이 있는 경우 외에는 관할 구역의 도시ㆍ군계획시설사업을 시행한다.","도시ㆍ군계획시설사업이 둘 이상의 시 또는 군의 관할 구역에 걸쳐 있고 같은 도에 속하는 경우 시장ㆍ군수 사이의 협의가 성립되지 아니하면 관할 도지사가 시행자를 지정한다.","지방공사가 도시ㆍ군계획시설사업의 시행자로 지정받으려면 국ㆍ공유지를 제외한 사업 대상 토지 면적의 3분의 2 이상을 소유하고 토지소유자 총수의 2분의 1 이상의 동의를 얻어야 한다.","법 제86조제7항 각 호에 해당하지 않는 민간기업이 시행자로 지정받으려면 국ㆍ공유지를 제외한 사업 대상 토지 면적의 3분의 2 이상을 소유하고 토지소유자 총수의 2분의 1 이상의 동의를 얻어야 한다.","도시ㆍ군계획시설결정 고시일부터 10년 이후에 실시계획을 인가받은 시행자가 실시계획 고시일부터 5년 이내에 재결신청을 하지 아니하면, 재결신청 없이 필요한 모든 권원을 확보한 경우가 아닌 한 5년이 지난 다음 날 그 실시계획은 효력을 잃는다."],"a":[3],"L":"공1-5","o":"변형","x":{"한줄":"지방공사ㆍ지방공단은 영 제96조제4항의 시행자라서, 토지 소유 면적과 동의 비율을 갖추지 않아도 지정받을 수 있다.","근거":[{"법령":"국토의 계획 및 이용에 관한 법률","조문":"제86조제1항","원문":"특별시장ㆍ광역시장ㆍ특별자치시장ㆍ특별자치도지사ㆍ시장 또는 군수는 이 법 또는 다른 법률에 특별한 규정이 있는 경우 외에는 관할 구역의 도시ㆍ군계획시설사업을 시행한다."},{"법령":"국토의 계획 및 이용에 관한 법률","조문":"제86조제3항","원문":"제2항에 따른 협의가 성립되지 아니하는 경우 도시ㆍ군계획시설사업을 시행하려는 구역이 같은 도의 관할 구역에 속하는 경우에는 관할 도지사가 시행자를 지정하고, 둘 이상의 시ㆍ도의 관할 구역에 걸치는 경우에는 국토교통부장관이 시행자를 지정한다."},{"법령":"국토의 계획 및 이용에 관한 법률","조문":"제86조제7항","원문":"다음 각 호에 해당하지 아니하는 자가 제5항에 따라 도시ㆍ군계획시설사업의 시행자로 지정을 받으려면 도시ㆍ군계획시설사업의 대상인 토지(국공유지는 제외한다)의 소유 면적 및 토지 소유자의 동의 비율에 관하여 대통령령으로 정하는 요건을 갖추어야 한다. 1. 국가 또는 지방자치단체 2. 대통령령으로 정하는 공공기관 3. 그 밖에 대통령령으로 정하는 자"},{"법령":"국토의 계획 및 이용에 관한 법률 시행령","조문":"제96조제2항","원문":"법 제86조제7항 각 호 외의 부분 중 \"대통령령으로 정하는 요건\"이란 도시ㆍ군계획시설사업의 대상인 토지(국ㆍ공유지를 제외한다. 이하 이 항에서 같다)면적의 3분의 2 이상에 해당하는 토지를 소유하고, 토지소유자 총수의 2분의 1 이상에 해당하는 자의 동의를 얻는 것을 말한다."},{"법령":"국토의 계획 및 이용에 관한 법률 시행령","조문":"제96조제4항제1호","원문":"법 제86조제7항제3호에서 \"대통령령으로 정하는 자\"란 다음 각 호의 어느 하나에 해당하는 자를 말한다. 1. 「지방공기업법」에 의한 지방공사 및 지방공단"},{"법령":"국토의 계획 및 이용에 관한 법률","조문":"제88조제7항","원문":"도시ㆍ군계획시설결정의 고시일부터 10년 이후에 제1항 또는 제2항에 따라 실시계획을 작성하거나 인가(다른 법률에 따라 의제된 경우는 제외한다) 받은 도시ㆍ군계획시설사업의 시행자(이하 이 조에서 \"장기미집행 도시ㆍ군계획시설사업의 시행자\"라 한다)가 제91조에 따른 실시계획 고시일부터 5년 이내에 「공익사업을 위한 토지 등의 취득 및 보상에 관한 법률」 제28조제1항에 따른 재결신청(이하 이 조에서 \"재결신청\"이라 한다)을 하지 아니한 경우에는 실시계획 고시일부터 5년이 지난 다음 날에 그 실시계획은 효력을 잃는다. 다만, 장기미집행 도시ㆍ군계획시설사업의 시행자가 재결신청을 하지 아니하고 실시계획 고시일부터 5년이 지나기 전에 해당 도시ㆍ군계획시설사업에 필요한 토지 면적의 3분의 2 이상을 소유하거나 사용할 수 있는 권원을 확보하고 실시계획 고시일부터 7년 이내에 재결신청을 하지 아니한 경우 실시계획 고시일부터 7년이 지난 다음 날에 그 실시계획은 효력을 잃는다."}],"선지":[{"번호":1,"판정":"옳음","설명":"시장ㆍ군수가 관할 구역의 시설사업을 시행하는 것이 원칙이다(법 제86조제1항)."},{"번호":2,"판정":"옳음","설명":"관계 시장ㆍ군수가 협의해 시행자를 정하고, 협의가 성립되지 않으면 같은 도 안이면 도지사가, 둘 이상의 시ㆍ도에 걸치면 국토교통부장관이 지정한다(법 제86조제2항ㆍ제3항)."},{"번호":3,"판정":"틀림","설명":"지방공사와 지방공단은 영 제96조제4항제1호로 법 제86조제7항제3호의 ‘대통령령으로 정하는 자’에 들어 소유 면적ㆍ동의 요건이 적용되지 않는다."},{"번호":4,"판정":"옳음","설명":"국가ㆍ지방자치단체, 대통령령이 정한 공공기관 등을 뺀 자는 토지(국ㆍ공유지 제외) 면적의 3분의 2 이상을 소유하고 토지소유자 총수의 2분의 1 이상의 동의를 얻어야 한다(법 제86조제7항, 영 제96조제2항)."},{"번호":5,"판정":"옳음","설명":"장기미집행 시설사업의 시행자가 실시계획 고시일부터 5년 안에 재결신청을 하지 않으면 5년이 지난 다음 날 실시계획이 효력을 잃는다. 재결신청 없이 모든 권원을 확보하면 효력이 유지된다(법 제88조제7항ㆍ제8항)."}],"개념":[{"종류":"표","제목":"도시ㆍ군계획시설사업의 시행자(법 제86조)","머리":["구분","시행자","근거"],"행":[["원칙","특별시장ㆍ광역시장ㆍ특별자치시장ㆍ특별자치도지사ㆍ시장 또는 군수","제1항"],["둘 이상의 시ㆍ군에 걸침","관계 시장ㆍ군수 협의, 불성립 시 같은 도면 도지사, 둘 이상의 시ㆍ도에 걸치면 국토교통부장관 지정","제2항ㆍ제3항"],["직접 시행","국토교통부장관(국가계획 관련 등), 도지사(광역도시계획 관련 등)","제4항"],["지정 시행자","그 밖의 자는 국토교통부장관, 시ㆍ도지사, 시장 또는 군수의 지정","제5항"],["요건 면제","국가ㆍ지방자치단체, 한국토지주택공사 등 열거된 공공기관, 지방공사ㆍ지방공단 등","제7항, 영 제96조제3항ㆍ제4항"],["요건 적용","그 밖의 민간 시행자: 토지(국ㆍ공유지 제외) 면적 3분의 2 이상 소유 + 토지소유자 총수 2분의 1 이상 동의","영 제96조제2항"]]},{"종류":"흐름","제목":"시행자 지정부터 준공까지","단계":[{"이름":"시행자 지정","설명":"지정 신청서 제출, 지정 내용 고시(법 제86조제5항ㆍ제6항, 영 제96조제1항)"},{"이름":"실시계획 작성","설명":"지정받은 자는 작성 전에 시장ㆍ군수의 의견을 들음(영 제97조제4항)"},{"이름":"실시계획 인가","설명":"국토교통부장관이 지정한 시행자는 국토교통부장관, 그 밖의 시행자는 시ㆍ도지사 또는 대도시 시장의 인가(영 제97조제2항)"},{"이름":"실시계획 고시","설명":"작성ㆍ인가ㆍ폐지 시 고시(법 제91조)"},{"이름":"수용ㆍ사용","설명":"토지ㆍ건축물과 소유권 외의 권리를 수용 또는 사용(법 제95조제1항)"},{"이름":"준공검사","설명":"시ㆍ도지사나 대도시 시장의 준공검사 후 공사완료 공고(법 제98조)"}]}],"함정":"선지 3과 선지 4는 같은 요건을 시행자만 바꿔 묻는다. 요건이 면제되는 자는 국가ㆍ지방자치단체뿐 아니라 영 제96조제3항의 공공기관과 제4항의 지방공사ㆍ지방공단 등 넓다. 한국토지주택공사와 지방공사 모두 소유ㆍ동의 요건 없이 지정받을 수 있다."}},{"i":"S2-2-1-공법-08","r":"S2","g":2,"c":2,"n":48,"s":"공법","q":"국토의 계획 및 이용에 관한 법령상 공동구에 관한 설명으로 옳은 것은?","b":null,"bs":"없음","img":[],"ch":["공동구가 설치된 경우 가스관은 공동구협의회의 심의를 거쳐 공동구에 수용할 수 있다.","택지개발지구의 규모가 200만제곱미터인 경우 해당 지구에서 개발사업을 시행하는 자는 공동구를 설치하여야 한다.","공동구관리자는 3년마다 해당 공동구의 안전 및 유지관리계획을 수립ㆍ시행하여야 한다.","공동구가 설치된 경우 수도관은 공동구협의회의 심의를 거쳐 공동구에 수용할 수 있다.","공동구관리자는 2년에 1회 이상 공동구의 안전점검을 실시하여야 한다."],"a":[1],"L":"공1-5","o":"변형","x":{"한줄":"가스관과 하수도관은 공동구협의회 심의를 거쳐 수용할 수 있고, 전선로ㆍ통신선로ㆍ수도관ㆍ열수송관ㆍ중수도관ㆍ쓰레기수송관은 반드시 수용한다.","근거":[{"법령":"국토의 계획 및 이용에 관한 법률 시행령","조문":"제35조의3","원문":"공동구가 설치된 경우에는 법 제44조제3항에 따라 제1호부터 제6호까지의 시설을 공동구에 수용하여야 하며, 제7호 및 제8호의 시설은 법 제44조의2제4항에 따른 공동구협의회(이하 \"공동구협의회\"라 한다)의 심의를 거쳐 수용할 수 있다. 1. 전선로 2. 통신선로 3. 수도관 4. 열수송관 5. 중수도관 6. 쓰레기수송관 7. 가스관 8. 하수도관, 그 밖의 시설"},{"법령":"국토의 계획 및 이용에 관한 법률 시행령","조문":"제35조의2제1항","원문":"법 제44조제1항 각 호 외의 부분에서 \"대통령령으로 정하는 규모\"란 200만제곱미터를 말한다."},{"법령":"국토의 계획 및 이용에 관한 법률","조문":"제44조의2제2항","원문":"공동구관리자는 5년마다 해당 공동구의 안전 및 유지관리계획을 대통령령으로 정하는 바에 따라 수립ㆍ시행하여야 한다."},{"법령":"국토의 계획 및 이용에 관한 법률","조문":"제44조의2제3항","원문":"공동구관리자는 대통령령으로 정하는 바에 따라 1년에 1회 이상 공동구의 안전점검을 실시하여야 하며, 안전점검결과 이상이 있다고 인정되는 때에는 지체 없이 정밀안전진단ㆍ보수ㆍ보강 등 필요한 조치를 하여야 한다."}],"선지":[{"번호":1,"판정":"옳음","설명":"제7호 가스관과 제8호 하수도관 등은 공동구협의회 심의를 거쳐 수용할 수 있다(영 제35조의3)."},{"번호":2,"판정":"틀림","설명":"공동구 설치 규모는 200만제곱미터를 ‘초과’할 때다. 200만제곱미터인 지구는 해당하지 않는다(법 제44조제1항, 영 제35조의2제1항)."},{"번호":3,"판정":"틀림","설명":"안전 및 유지관리계획은 5년마다 수립ㆍ시행한다(법 제44조의2제2항)."},{"번호":4,"판정":"틀림","설명":"수도관은 제1호부터 제6호까지의 시설이어서 협의회 심의 없이 반드시 수용하여야 한다(영 제35조의3)."},{"번호":5,"판정":"틀림","설명":"안전점검은 1년에 1회 이상 실시하고, 이상이 있으면 지체 없이 정밀안전진단ㆍ보수ㆍ보강 등을 한다(법 제44조의2제3항)."}],"개념":[{"종류":"표","제목":"공동구 수용 시설(영 제35조의3)","머리":["구분","시설","수용"],"행":[["제1호~제6호","전선로, 통신선로, 수도관, 열수송관, 중수도관, 쓰레기수송관","반드시 수용"],["제7호","가스관","공동구협의회 심의를 거쳐 수용할 수 있음"],["제8호","하수도관, 그 밖의 시설","공동구협의회 심의를 거쳐 수용할 수 있음"]]},{"종류":"표","제목":"공동구의 설치와 관리","머리":["항목","내용","근거"],"행":[["설치 의무자","도시개발구역, 택지개발지구, 경제자유구역, 정비구역, 공공주택지구, 도청이전신도시에서 개발사업을 시행하는 자","법 제44조제1항, 영 제35조의2제2항"],["설치 규모","200만제곱미터 초과","영 제35조의2제1항"],["관리자","특별시장ㆍ광역시장ㆍ특별자치시장ㆍ특별자치도지사ㆍ시장 또는 군수","법 제44조의2제1항"],["유지관리계획","5년마다 수립ㆍ시행, 관계 행정기관 협의 후 공동구협의회 심의","법 제44조의2제2항, 영 제39조제3항"],["안전점검","1년에 1회 이상","법 제44조의2제3항"],["공동구협의회","위원장ㆍ부위원장 포함 10명 이상 20명 이하","영 제39조의2제2항"],["관리비용 납부","연 2회로 분할","영 제39조의3"]]}],"함정":"200만제곱미터를 ‘초과’해야 하는데 경계값인 200만제곱미터 그대로를 포함시킨 선지 2가 걸림돌이다. 수도관을 협의회 심의 대상으로 섞은 선지 4도 같은 방식이다. 수용 시설 8종 가운데 심의 대상은 마지막 두 종류(가스관, 하수도관 등)뿐이다."}},{"i":"S2-2-1-공법-09","r":"S2","g":2,"c":2,"n":49,"s":"공법","q":"국토의 계획 및 이용에 관한 법령상 지구단위계획구역의 지정에 관한 설명으로 옳은 것은? (단, 조례는 고려하지 않음)","b":null,"bs":"없음","img":[],"ch":["「산업입지 및 개발에 관한 법률」에 따른 준산업단지에 대하여는 지구단위계획구역을 지정할 수 없다.","도시지역 내 복합적인 토지 이용을 증진시킬 필요가 있는 지역으로서 지구단위계획구역을 지정할 수 있는 지역에 일반공업지역은 해당하지 않는다.","「택지개발촉진법」에 따라 지정된 택지개발지구에서 시행되는 사업이 끝난 후 5년이 지나면 해당 지역은 지구단위계획구역으로 지정하여야 한다.","도시지역 외의 지역을 지구단위계획구역으로 지정하려면 지정하려는 구역 면적의 3분의 2 이상이 계획관리지역이어야 한다.","농림지역에 위치한 산업ㆍ유통개발진흥지구는 지구단위계획구역으로 지정할 수 있는 대상지역에 포함되지 않는다."],"a":[2],"L":"공1-6","o":"기출","x":{"한줄":"도시지역 안에서 복합적 토지 이용을 증진할 지구단위계획구역은 일반주거ㆍ준주거ㆍ준공업ㆍ상업지역에서만 지정할 수 있어 일반공업지역은 들어가지 않는다.","근거":[{"법령":"국토의 계획 및 이용에 관한 법률","조문":"제51조제1항제6호ㆍ제8호의2","원문":"국토교통부장관, 시ㆍ도지사, 시장 또는 군수는 다음 각 호의 어느 하나에 해당하는 지역의 전부 또는 일부에 대하여 지구단위계획구역을 지정할 수 있다. 6. 「산업입지 및 개발에 관한 법률」 제2조제8호의 산업단지와 같은 조 제12호의 준산업단지 8의2. 도시지역 내 주거ㆍ상업ㆍ업무 등의 기능을 결합하는 등 복합적인 토지 이용을 증진시킬 필요가 있는 지역으로서 대통령령으로 정하는 요건에 해당하는 지역"},{"법령":"국토의 계획 및 이용에 관한 법률 시행령","조문":"제43조제1항","원문":"법 제51조제1항제8호의2에서 \"대통령령으로 정하는 요건에 해당하는 지역\"이란 일반주거지역, 준주거지역, 준공업지역 및 상업지역에서 낙후된 도심 기능을 회복하거나 도시균형발전을 위한 중심지 육성이 필요한 경우로서 다음 각 호의 어느 하나에 해당하는 지역을 말한다. 1. 주요 역세권, 고속버스 및 시외버스 터미널, 간선도로의 교차지 등 양호한 기반시설을 갖추고 있어 대중교통 이용이 용이한 지역 2. 역세권의 체계적ㆍ계획적 개발이 필요한 지역 3. 세 개 이상의 노선이 교차하는 대중교통 결절지(結節地)로부터 1킬로미터 이내에 위치한 지역 4. 「역세권의 개발 및 이용에 관한 법률」에 따른 역세권개발구역, 「도시재정비 촉진을 위한 특별법」에 따른 고밀복합형 재정비촉진지구로 지정된 지역"},{"법령":"국토의 계획 및 이용에 관한 법률","조문":"제51조제2항제1호","원문":"국토교통부장관, 시ㆍ도지사, 시장 또는 군수는 다음 각 호의 어느 하나에 해당하는 지역은 지구단위계획구역으로 지정하여야 한다. 다만, 관계 법률에 따라 그 지역에 토지 이용과 건축에 관한 계획이 수립되어 있는 경우에는 그러하지 아니하다. 1. 제1항제3호 및 제4호의 지역에서 시행되는 사업이 끝난 후 10년이 지난 지역"},{"법령":"국토의 계획 및 이용에 관한 법률","조문":"제51조제3항제1호ㆍ제2호","원문":"도시지역 외의 지역을 지구단위계획구역으로 지정하려는 경우 다음 각 호의 어느 하나에 해당하여야 한다. 1. 지정하려는 구역 면적의 100분의 50 이상이 제36조에 따라 지정된 계획관리지역으로서 대통령령으로 정하는 요건에 해당하는 지역 2. 제37조에 따라 지정된 개발진흥지구로서 대통령령으로 정하는 요건에 해당하는 지역"},{"법령":"국토의 계획 및 이용에 관한 법률 시행령","조문":"제44조제2항","원문":"법 제51조제3항제2호에서 \"대통령령으로 정하는 요건\"이란 다음 각 호의 요건을 말한다. 1. 제1항제2호부터 제4호까지의 요건에 해당할 것 2. 당해 개발진흥지구가 다음 각 목의 지역에 위치할 것 가. 주거개발진흥지구, 복합개발진흥지구(주거기능이 포함된 경우에 한한다) 및 특정개발진흥지구 : 계획관리지역 나. 산업ㆍ유통개발진흥지구 및 복합개발진흥지구(주거기능이 포함되지 아니한 경우에 한한다) : 계획관리지역ㆍ생산관리지역 또는 농림지역 다. 관광ㆍ휴양개발진흥지구 : 도시지역외의 지역"}],"선지":[{"번호":1,"판정":"틀림","설명":"산업입지법상 산업단지와 준산업단지는 지구단위계획구역으로 지정할 수 있는 지역이다(법 제51조제1항제6호)."},{"번호":2,"판정":"옳음","설명":"복합적 토지 이용 증진이 필요한 지역은 일반주거지역, 준주거지역, 준공업지역 및 상업지역에 한한다. 일반공업지역은 해당하지 않는다(법 제51조제1항제8호의2, 영 제43조제1항)."},{"번호":3,"판정":"틀림","설명":"택지개발지구와 정비구역은 사업이 끝난 뒤 10년이 지나면 지정하여야 한다. 5년이 아니다(법 제51조제2항제1호)."},{"번호":4,"판정":"틀림","설명":"도시지역 외에서는 지정하려는 구역 면적의 100분의 50 이상이 계획관리지역이어야 한다(법 제51조제3항제1호). 3분의 2가 아니다."},{"번호":5,"판정":"틀림","설명":"산업ㆍ유통개발진흥지구는 계획관리지역ㆍ생산관리지역 또는 농림지역에 있으면 지정 대상이다(법 제51조제3항제2호, 영 제44조제2항제2호나목)."}],"개념":[{"종류":"표","제목":"지구단위계획구역 지정 대상(법 제51조)","머리":["구분","대상","근거"],"행":[["임의 지정(도시지역)","용도지구, 도시개발구역, 정비구역, 택지개발지구, 대지조성사업지구, 산업단지ㆍ준산업단지, 관광단지ㆍ관광특구","제1항제1호~제7호"],["임의 지정(도시지역)","개발제한구역 등에서 해제되는 구역, 복합적 토지 이용이 필요한 지역(제8호의2), 유휴토지ㆍ이전 시설 정비 지역(제8호의3)","제1항제8호~제8호의3"],["의무 지정","정비구역ㆍ택지개발지구에서 사업이 끝난 후 10년이 지난 지역","제2항제1호"],["의무 지정","제1항 각 호 중 체계적 관리가 필요한 지역으로 영이 정한 지역(30만제곱미터 이상 등)","제2항제2호, 영 제43조제5항"],["도시지역 외","구역 면적의 100분의 50 이상이 계획관리지역, 개발진흥지구, 용도지구를 폐지하고 지구단위계획으로 대체하는 지역","제3항"]]},{"종류":"표","제목":"도시지역 외 지구단위계획구역의 요건(영 제44조)","머리":["구분","요건"],"행":[["면적(아파트ㆍ연립 건설계획 포함)","30만제곱미터 이상(자연보전권역이거나 초등학교 용지를 확보하는 등 일정한 경우 10만제곱미터 이상)"],["면적(그 밖)","3만제곱미터 이상"],["산업ㆍ유통개발진흥지구","계획관리지역ㆍ생산관리지역 또는 농림지역"],["주거개발진흥지구","계획관리지역"],["관광ㆍ휴양개발진흥지구","도시지역 외의 지역"]]}],"함정":"시기 숫자는 사업 종료 후 10년이고 면적 비율은 100분의 50이다. 선지 3과 4는 이 숫자를 5년과 3분의 2로 바꾸어 놓았다. 선지 5는 산업ㆍ유통개발진흥지구의 지정 대상 지역에 농림지역이 포함된다는 점(영 제44조제2항제2호나목)을 묻는다. 이 문항의 정답률은 15퍼센트였다."}},{"i":"S2-2-1-공법-10","r":"S2","g":2,"c":2,"n":50,"s":"공법","q":"국토의 계획 및 이용에 관한 법령상 개발행위허가의 기준에 해당하지 않는 것은? (단, 관련 인ㆍ허가등의 의제는 고려하지 않음)","b":null,"bs":"없음","img":[],"ch":["개발행위에 필요한 자금조달계획이 사업 규모에 적합하게 수립되어 있을 것","개발행위허가제한지역에 해당하지 아니할 것","도시ㆍ군계획사업부지에 해당하지 아니할 것(허용되는 개발행위는 제외)","개발행위로 인하여 녹지축이 절단되지 아니할 것","대지와 도로의 관계는 「건축법」에 적합할 것"],"a":[1],"L":"공1-7","o":"변형","x":{"한줄":"개발행위허가 기준(영 별표 1의2)에는 자금조달계획이 없다. 자금조달계획은 도시ㆍ군계획시설사업 시행자 지정 신청서의 기재사항이다.","근거":[{"법령":"국토의 계획 및 이용에 관한 법률","조문":"제58조제1항제2호~제5호","원문":"특별시장ㆍ광역시장ㆍ특별자치시장ㆍ특별자치도지사ㆍ시장 또는 군수는 개발행위허가의 신청 내용이 다음 각 호의 기준에 맞는 경우에만 개발행위허가 또는 변경허가를 하여야 한다. 2. 도시ㆍ군관리계획 및 성장관리계획의 내용에 어긋나지 아니할 것 3. 도시ㆍ군계획사업의 시행에 지장이 없을 것 5. 해당 개발행위에 따른 기반시설의 설치나 그에 필요한 용지의 확보계획이 적절할 것"},{"법령":"국토의 계획 및 이용에 관한 법률 시행령","조문":"제56조제1항","원문":"법 제58조제3항에 따른 개발행위허가의 기준은 별표 1의2와 같다."},{"법령":"국토의 계획 및 이용에 관한 법률 시행령","조문":"별표 1의2 제1호","원문":"나. 도시ㆍ군관리계획 (1) 용도지역별 개발행위의 규모 및 건축제한 기준에 적합할 것 (2) 개발행위허가제한지역에 해당하지 아니할 것 / 다. 도시ㆍ군계획사업 (1) 도시ㆍ군계획사업부지에 해당하지 아니할 것(제61조의 규정에 의하여 허용되는 개발행위를 제외한다) / 라. 주변지역과의 관계 (3) 개발행위로 인하여 녹지축이 절단되지 아니하고, 개발행위로 배수가 변경되어 하천ㆍ호소ㆍ습지로의 유수를 막지 아니할 것 / 마. 기반시설 (2) 대지와 도로의 관계는 「건축법」에 적합할 것"},{"법령":"국토의 계획 및 이용에 관한 법률 시행령","조문":"제96조제1항제5호","원문":"법 제86조제5항의 규정에 의하여 도시ㆍ군계획시설사업의 시행자로 지정받고자 하는 자는 다음 각호의 사항을 기재한 신청서를 국토교통부장관, 시ㆍ도지사 또는 시장ㆍ군수에게 제출하여야 한다. 5. 자금조달계획"}],"선지":[{"번호":1,"판정":"틀림","설명":"별표 1의2의 검토분야(공통, 도시ㆍ군관리계획, 도시ㆍ군계획사업, 주변지역, 기반시설, 그 밖의 사항)에 자금조달계획은 없다. 시설사업 시행자 지정 신청서에 적는 사항이다(영 제96조제1항제5호)."},{"번호":2,"판정":"옳음","설명":"도시ㆍ군관리계획 분야 기준이다(영 별표 1의2 제1호나목(2))."},{"번호":3,"판정":"옳음","설명":"도시ㆍ군계획사업 분야 기준이다. 영 제61조가 허용하는 개발행위는 제외한다(영 별표 1의2 제1호다목(1))."},{"번호":4,"판정":"옳음","설명":"주변지역과의 관계 분야 기준이다(영 별표 1의2 제1호라목(3))."},{"번호":5,"판정":"옳음","설명":"기반시설 분야 기준이다(영 별표 1의2 제1호마목(2))."}],"개념":[{"종류":"표","제목":"개발행위허가의 규모(영 제55조제1항)","머리":["용도지역","토지 형질변경 면적"],"행":[["주거ㆍ상업ㆍ자연녹지ㆍ생산녹지지역","1만제곱미터 미만"],["공업지역","3만제곱미터 미만"],["보전녹지지역","5천제곱미터 미만"],["관리지역","3만제곱미터 미만"],["농림지역","3만제곱미터 미만"],["자연환경보전지역","5천제곱미터 미만"]]},{"종류":"표","제목":"개발행위허가 기준(법 제58조제1항, 영 별표 1의2)","머리":["분야","기준"],"행":[["법 제58조제1항","규모 적합, 도시ㆍ군관리계획 및 성장관리계획에 어긋나지 않을 것, 도시ㆍ군계획사업에 지장이 없을 것, 주변환경과 조화, 기반시설 설치 및 용지 확보계획이 적절할 것"],["공통","조수류ㆍ수목 집단서식지 및 우량농지 아닐 것, 원형보전 필요 없을 것"],["도시ㆍ군관리계획","용도지역별 규모ㆍ건축제한 적합, 개발행위허가제한지역이 아닐 것"],["도시ㆍ군계획사업","사업부지가 아닐 것, 개발시기ㆍ가설시설이 사업에 지장 없을 것"],["주변지역과의 관계","경관ㆍ미관 훼손 없음, 환경오염 우려 없음, 녹지축 절단ㆍ유수 차단 없음"],["기반시설","교통소통에 지장 없음, 대지와 도로의 관계는 건축법 적합"],["그 밖의 사항","공유수면매립 목적이 도시ㆍ군계획에 적합, 토지분할ㆍ물건 쌓기에 입목 벌채가 수반되지 않을 것"]]}],"함정":"자금조달계획은 도시ㆍ군계획시설사업 시행자 지정(영 제96조제1항)이나 시범도시 지정 기준(영 제126조제2항제4호) 같은 다른 제도에 나오는 낱말이다. 개발행위허가는 신청 내용이 법 제58조와 영 별표 1의2의 기준에 맞는지를 보며, 시행자의 재원 여부는 기준에 없다."}},{"i":"S2-2-1-공법-11","r":"S2","g":2,"c":2,"n":51,"s":"공법","q":"국토의 계획 및 이용에 관한 법령상 성장관리계획구역을 지정할 수 있는 지역에 해당하지 않는 것은?","b":null,"bs":"없음","img":[],"ch":["개발수요가 많아 무질서한 개발이 진행되고 있는 계획관리지역","주변지역과 연계하여 체계적인 관리가 필요한 보전관리지역","「토지이용규제 기본법」에 따른 지역ㆍ지구등의 변경으로 토지이용에 대한 행위제한이 완화되는 준공업지역","주변의 토지이용이나 교통여건 변화 등으로 향후 시가화가 예상되는 자연환경보전지역","개발수요가 많아 무질서한 개발이 진행될 것으로 예상되는 생산녹지지역"],"a":[3],"L":"공1-7","o":"변형","x":{"한줄":"성장관리계획구역은 녹지지역, 관리지역, 농림지역, 자연환경보전지역에만 지정할 수 있어, 공업지역인 준공업지역은 사유가 있어도 대상이 아니다.","근거":[{"법령":"국토의 계획 및 이용에 관한 법률","조문":"제75조의2제1항","원문":"특별시장ㆍ광역시장ㆍ특별자치시장ㆍ특별자치도지사ㆍ시장 또는 군수는 녹지지역, 관리지역, 농림지역 및 자연환경보전지역 중 다음 각 호의 어느 하나에 해당하는 지역의 전부 또는 일부에 대하여 성장관리계획구역을 지정할 수 있다. 1. 개발수요가 많아 무질서한 개발이 진행되고 있거나 진행될 것으로 예상되는 지역 2. 주변의 토지이용이나 교통여건 변화 등으로 향후 시가화가 예상되는 지역 3. 주변지역과 연계하여 체계적인 관리가 필요한 지역 4. 「토지이용규제 기본법」 제2조제1호에 따른 지역ㆍ지구등의 변경으로 토지이용에 대한 행위제한이 완화되는 지역 5. 그 밖에 난개발의 방지와 체계적인 관리가 필요한 지역으로서 대통령령으로 정하는 지역"}],"선지":[{"번호":1,"판정":"옳음","설명":"관리지역(계획관리지역)이고 사유도 제1호(무질서한 개발이 진행 중)에 해당한다."},{"번호":2,"판정":"옳음","설명":"관리지역(보전관리지역)이고 사유는 제3호(주변지역과 연계한 체계적 관리가 필요한 지역)에 해당한다."},{"번호":3,"판정":"틀림","설명":"제4호 사유(지역ㆍ지구등 변경으로 행위제한 완화)는 갖췄지만 준공업지역은 공업지역이라 지정 대상 지역(녹지ㆍ관리ㆍ농림ㆍ자연환경보전)에 없다."},{"번호":4,"판정":"옳음","설명":"자연환경보전지역이고 사유는 제2호(향후 시가화 예상)에 해당한다."},{"번호":5,"판정":"옳음","설명":"녹지지역(생산녹지지역)이고 사유는 제1호(무질서한 개발이 진행될 것으로 예상)에 해당한다."}],"개념":[{"종류":"표","제목":"성장관리계획구역의 지정(법 제75조의2)","머리":["구분","내용"],"행":[["지정권자","특별시장ㆍ광역시장ㆍ특별자치시장ㆍ특별자치도지사ㆍ시장 또는 군수"],["지정 지역","녹지지역, 관리지역, 농림지역, 자연환경보전지역"],["사유","무질서한 개발이 진행 중이거나 예상, 향후 시가화 예상, 주변과 연계한 체계적 관리 필요, 지역ㆍ지구등 변경으로 행위제한 완화, 영이 정한 난개발 방지 지역"],["영이 정한 지역(영 제70조의12)","인구 감소 등으로 압축적 도시성장관리가 필요한 지역, 공장 등과 입지 분리가 필요한 지역, 조례로 정하는 지역"],["절차","주민 의견 청취(14일 이상 열람, 영 제70조의13제2항), 지방의회 의견(60일), 관계 행정기관 협의(30일), 지방도시계획위원회 심의"],["재검토","성장관리계획은 5년마다 타당성 재검토(법 제75조의3제5항)"]]},{"종류":"표","제목":"성장관리계획구역 안의 건폐율ㆍ용적률 완화(법 제75조의3)","머리":["구분","완화 한도"],"행":[["계획관리지역 건폐율","50퍼센트 이하"],["생산관리지역ㆍ농림지역 건폐율","30퍼센트 이하"],["자연녹지지역ㆍ생산녹지지역 건폐율(영 제70조의14제2항)","30퍼센트 이하"],["계획관리지역 용적률","법 제78조제1항의 한도의 125퍼센트 이하"],["개발행위 등","성장관리계획에 맞게 하여야 함(법 제75조의4)"]]}],"함정":"사유가 나열된 호에 맞는지만 보면 선지 3도 맞는 것처럼 읽힌다. 먼저 지역이 녹지ㆍ관리ㆍ농림ㆍ자연환경보전지역인지 확인해야 한다. 도시지역이라도 녹지지역은 지정 대상이다.","개정":"예전 기출의 ‘성장관리방안’은 2021.1.12 개정으로 ‘성장관리계획구역 지정ㆍ성장관리계획 수립’으로 바뀌었다(법 제75조의2ㆍ제75조의3). 지정 대상 지역은 녹지ㆍ관리ㆍ농림ㆍ자연환경보전지역이다."}},{"i":"S2-2-1-공법-12","r":"S2","g":2,"c":2,"n":52,"s":"공법","q":"국토의 계획 및 이용에 관한 법령상 기반시설부담구역과 기반시설설치비용에 관한 설명으로 틀린 것은?","b":null,"bs":"없음","img":[],"ch":["납부의무자가 사업에 뚜렷한 손실을 입어 기반시설설치비용을 납부하기 곤란한 경우 시장 또는 군수는 3년의 범위에서 납부 기일을 연기하거나 분할 납부를 인정할 수 있다.","기반시설설치비용 산정에서 민간 개발사업자가 부담하는 부담률은 100분의 20이며, 시장 또는 군수가 건물의 규모, 지역 특성 등을 고려하여 100분의 25의 범위에서 가감할 수 있다.","기반시설부담구역의 지정고시일부터 1년이 되는 날까지 기반시설설치계획을 수립하지 아니하면 그 1년이 되는 날의 다음 날에 기반시설부담구역의 지정은 해제된 것으로 본다.","시장 또는 군수는 납부의무자가 건축허가를 받은 날부터 2개월 이내에 기반시설설치비용을 부과하여야 하고, 납부의무자는 사용승인 신청 시까지 이를 내야 한다.","납부의무자가 직접 기반시설을 설치하거나 그에 필요한 용지를 확보한 경우에는 그 설치ㆍ확보에 든 비용을 기반시설설치비용에서 공제한다."],"a":[1],"L":"공1-8","o":"변형","x":{"한줄":"납부 기일의 연기는 1년, 분할 납부는 2년의 범위에서 인정한다. 3년이 아니다.","근거":[{"법령":"국토의 계획 및 이용에 관한 법률 시행령","조문":"제70조의8제1항","원문":"특별시장ㆍ광역시장ㆍ특별자치시장ㆍ특별자치도지사ㆍ시장 또는 군수는 납부의무자가 다음 각 호의 어느 하나에 해당하여 기반시설설치비용을 납부하기가 곤란하다고 인정되면 해당 개발사업 목적에 따른 이용 상황 등을 고려하여 1년의 범위에서 납부 기일을 연기하거나 2년의 범위에서 분할 납부를 인정할 수 있다. 1. 재해나 도난으로 재산에 심한 손실을 입은 경우 2. 사업에 뚜렷한 손실을 입은 때 3. 사업이 중대한 위기에 처한 경우 4. 납부의무자나 그 동거 가족의 질병이나 중상해로 장기치료가 필요한 경우"},{"법령":"국토의 계획 및 이용에 관한 법률","조문":"제68조제5항","원문":"제2항에 따른 민간 개발사업자가 부담하는 부담률은 100분의 20으로 하며, 특별시장ㆍ광역시장ㆍ특별자치시장ㆍ특별자치도지사ㆍ시장 또는 군수가 건물의 규모, 지역 특성 등을 고려하여 100분의 25의 범위에서 부담률을 가감할 수 있다."},{"법령":"국토의 계획 및 이용에 관한 법률 시행령","조문":"제65조제3항","원문":"제1항 및 제2항에도 불구하고 법 제52조제1항에 따라 지구단위계획을 수립한 경우에는 기반시설설치계획을 수립한 것으로 본다."},{"법령":"국토의 계획 및 이용에 관한 법률 시행령","조문":"제65조제4항","원문":"기반시설부담구역의 지정고시일부터 1년이 되는 날까지 기반시설설치계획을 수립하지 아니하면 그 1년이 되는 날의 다음날에 기반시설부담구역의 지정은 해제된 것으로 본다."},{"법령":"국토의 계획 및 이용에 관한 법률","조문":"제69조제2항","원문":"특별시장ㆍ광역시장ㆍ특별자치시장ㆍ특별자치도지사ㆍ시장 또는 군수는 납부의무자가 국가 또는 지방자치단체로부터 건축허가(다른 법률에 따른 사업승인 등 건축허가가 의제되는 경우에는 그 사업승인)를 받은 날부터 2개월 이내에 기반시설설치비용을 부과하여야 하고, 납부의무자는 사용승인(다른 법률에 따라 준공검사 등 사용승인이 의제되는 경우에는 그 준공검사) 신청 시까지 이를 내야 한다."},{"법령":"국토의 계획 및 이용에 관한 법률 시행령","조문":"제70조제1항","원문":"법 제68조제6항에 따라 납부의무자가 직접 기반시설을 설치하거나 그에 필요한 용지를 확보한 경우에는 기반시설설치비용에서 직접 기반시설을 설치하거나 용지를 확보하는 데 든 비용을 공제한다."}],"선지":[{"번호":1,"판정":"틀림","설명":"납부 기일 연기는 1년의 범위, 분할 납부는 2년의 범위다. 사업에 뚜렷한 손실을 입은 때는 사유에 해당한다(영 제70조의8제1항제2호)."},{"번호":2,"판정":"옳음","설명":"부담률은 100분의 20이고, 건물 규모와 지역 특성 등을 고려해 100분의 25의 범위에서 가감할 수 있다(법 제68조제5항)."},{"번호":3,"판정":"옳음","설명":"지정고시일부터 1년이 되는 날까지 설치계획을 수립하지 않으면 다음 날 지정이 해제된 것으로 본다. 지구단위계획을 수립한 경우에는 설치계획을 수립한 것으로 본다(영 제65조제3항ㆍ제4항)."},{"번호":4,"판정":"옳음","설명":"허가일부터 2개월 이내에 부과하고, 사용승인(준공검사 등) 신청 시까지 낸다(법 제69조제2항)."},{"번호":5,"판정":"옳음","설명":"직접 기반시설을 설치하거나 용지를 확보한 비용은 기반시설설치비용에서 공제한다(영 제70조제1항)."}],"개념":[{"종류":"표","제목":"기반시설설치비용의 부과대상과 산정(법 제68조)","머리":["항목","내용"],"행":[["부과대상","기존 건축물 연면적을 포함해 200제곱미터를 초과하는 건축물의 신축ㆍ증축 행위"],["철거 후 신축","기존 건축연면적을 초과하는 건축행위만 부과"],["산정","(기반시설 표준시설비용 + 용지비용) × 부과대상 건축연면적 × 부담률"],["용지비용","개별공시지가 평균 × 기반시설유발계수 × 용지환산계수(0.4 범위에서 조례로 정함)"],["부담률","100분의 20, 규모ㆍ지역 특성에 따라 100분의 25의 범위에서 가감"],["표준시설비용 고시","매년 1월 1일 기준을 매년 6월 10일까지 고시(영 제68조)"]]},{"종류":"흐름","제목":"기반시설설치비용의 부과ㆍ납부","단계":[{"이름":"기반시설부담구역 지정","설명":"주민 의견 청취, 지방도시계획위원회 심의, 고시(법 제67조제2항)"},{"이름":"기반시설설치계획 수립","설명":"지정고시일부터 1년 안에 수립, 못 하면 지정 해제(영 제65조제4항)"},{"이름":"예정 통지","설명":"부과기준시점부터 30일 이내, 이의 있으면 15일 이내 고지 전 심사 청구(영 제70조의3)"},{"이름":"부과","설명":"건축허가일부터 2개월 이내 납부고지서 발급(법 제69조제2항, 영 제70조의5)"},{"이름":"납부","설명":"사용승인 신청 시까지 납부, 물납은 납부기한 20일 전까지 신청(영 제70조의7제2항)"},{"이름":"연기ㆍ분할","설명":"고지서를 받은 날부터 15일 이내 신청, 연기 1년ㆍ분할 2년의 범위(영 제70조의8)"},{"이름":"독촉","설명":"사용승인 신청 시까지 완납하지 않으면 납부기한 후 10일 이내 독촉장(영 제70조의9)"}]}],"함정":"연기와 분할의 기간이 각각 1년, 2년이라는 숫자가 핵심이다. 선지 1은 사유(사업의 뚜렷한 손실)를 맞게 써 놓아 숫자만 바꿔 놓았다. 선지 4에서 부과 기한 2개월과 납부 기한(사용승인 신청 시까지)을 섞어 읽지 않아야 한다."}},{"i":"S2-2-1-공법-13","r":"S2","g":2,"c":2,"n":53,"s":"공법","q":"국토의 계획 및 이용에 관한 법령의 규정 내용으로 틀린 것은?","b":null,"bs":"없음","img":[],"ch":["시ㆍ도지사는 국토교통부장관에게 시범도시의 지정을 요청하려면 미리 해당 시ㆍ도도시계획위원회의 심의를 거쳐야 한다.","국토교통부장관은 시범도시를 지정하려면 중앙도시계획위원회의 심의를 거쳐야 한다.","도지사는 시ㆍ군 도시ㆍ군관리계획이 광역도시계획이나 도시ㆍ군기본계획의 취지에 부합하지 아니하다고 판단하면 시장 또는 군수에게 기한을 정하여 그 조정을 요구할 수 있다.","행정청이 아닌 도시ㆍ군계획시설사업 시행자의 처분에 대한 행정심판은 그 시행자를 지정한 자에게 제기하여야 한다.","국토교통부장관이 도시ㆍ군계획시설사업 시행자의 지정을 취소하려면 청문을 실시하여야 한다."],"a":[1],"L":"공1-8","o":"변형","x":{"한줄":"시ㆍ도지사가 시범도시 지정을 요청할 때 거치는 시ㆍ도도시계획위원회 절차는 심의가 아니라 자문이다.","근거":[{"법령":"국토의 계획 및 이용에 관한 법률 시행령","조문":"제126조제5항","원문":"시ㆍ도지사는 법 제127조제1항의 규정에 의하여 국토교통부장관에게 시범도시의 지정을 요청하고자 하는 때에는 미리 당해 시ㆍ도도시계획위원회의 자문을 거쳐야 한다."},{"법령":"국토의 계획 및 이용에 관한 법률 시행령","조문":"제126조제7항","원문":"국토교통부장관은 시범도시를 지정하려면 중앙도시계획위원회의 심의를 거쳐야 한다."},{"법령":"국토의 계획 및 이용에 관한 법률","조문":"제138조제3항","원문":"도지사는 시ㆍ군 도시ㆍ군관리계획이 광역도시계획이나 도시ㆍ군기본계획의 취지에 부합하지 아니하다고 판단되는 경우에는 시장 또는 군수에게 기한을 정하여 그 도시ㆍ군관리계획의 조정을 요구할 수 있다. 이 경우 시장 또는 군수는 그 도시ㆍ군관리계획을 재검토하여 정비하여야 한다."},{"법령":"국토의 계획 및 이용에 관한 법률","조문":"제134조","원문":"이 법에 따른 도시ㆍ군계획시설사업 시행자의 처분에 대하여는 「행정심판법」에 따라 행정심판을 제기할 수 있다. 이 경우 행정청이 아닌 시행자의 처분에 대하여는 제86조제5항에 따라 그 시행자를 지정한 자에게 행정심판을 제기하여야 한다."},{"법령":"국토의 계획 및 이용에 관한 법률","조문":"제136조제2호","원문":"국토교통부장관, 시ㆍ도지사, 시장ㆍ군수 또는 구청장은 제133조제1항에 따라 다음 각 호의 어느 하나에 해당하는 처분을 하려면 청문을 하여야 한다. 2. 제86조제5항에 따른 도시ㆍ군계획시설사업의 시행자 지정의 취소"}],"선지":[{"번호":1,"판정":"틀림","설명":"시ㆍ도지사는 지정을 요청하려면 미리 해당 시ㆍ도도시계획위원회의 ‘자문’을 거친다(영 제126조제5항)."},{"번호":2,"판정":"옳음","설명":"국토교통부장관이 시범도시를 지정하려면 중앙도시계획위원회 심의를 거친다(영 제126조제7항)."},{"번호":3,"판정":"옳음","설명":"도지사는 시ㆍ군 도시ㆍ군관리계획이 광역도시계획이나 기본계획의 취지에 맞지 않으면 기한을 정해 조정을 요구할 수 있고, 시장ㆍ군수는 재검토해 정비한다(법 제138조제3항)."},{"번호":4,"판정":"옳음","설명":"행정청이 아닌 시행자의 처분에 대한 행정심판은 법 제86조제5항에 따라 시행자를 지정한 자에게 제기한다(법 제134조)."},{"번호":5,"판정":"옳음","설명":"시행자 지정의 취소는 청문 대상이다(법 제136조제2호)."}],"개념":[{"종류":"흐름","제목":"시범도시의 지정(법 제127조, 영 제126조ㆍ제127조)","단계":[{"이름":"지정 요청","설명":"관계 중앙행정기관의 장 또는 시ㆍ도지사가 국토교통부장관에게 요청(법 제127조제1항)"},{"이름":"주민ㆍ지방자치단체 의견","설명":"설문조사ㆍ열람 등으로 주민 의견을 들은 후 관계 지방자치단체의 장 의견(영 제126조제4항)"},{"이름":"시ㆍ도도시계획위원회 자문","설명":"시ㆍ도지사가 요청할 때 미리 거침(영 제126조제5항)"},{"이름":"심의","설명":"국토교통부장관이 중앙도시계획위원회 심의(영 제126조제7항)"},{"이름":"공고","설명":"관보와 국토교통부 인터넷 홈페이지에 공고하고 관계 행정기관에 통보(영 제126조제8항)"}]},{"종류":"표","제목":"감독ㆍ청문ㆍ행정심판","머리":["구분","내용","근거"],"행":[["조정 요구(국토교통부장관)","기본계획ㆍ관리계획이 국가계획ㆍ광역도시계획에, 관리계획이 기본계획에 부합하지 않으면 시ㆍ도지사ㆍ시장ㆍ군수에게 조정 요구","법 제138조제2항"],["조정 요구(도지사)","시ㆍ군 관리계획이 광역도시계획ㆍ기본계획에 부합하지 않으면 시장ㆍ군수에게 조정 요구","법 제138조제3항"],["청문 대상","개발행위허가의 취소, 시설사업 시행자 지정의 취소, 실시계획인가의 취소","법 제136조"],["행정심판","시설사업 시행자의 처분에 대해 제기, 행정청이 아닌 시행자는 지정권자에게","법 제134조"],["시범도시 공모","국토교통부장관이 공모할 때 응모 자격은 특별시장ㆍ광역시장ㆍ특별자치시장ㆍ특별자치도지사ㆍ시장ㆍ군수ㆍ구청장","영 제127조제2항"]]}],"함정":"자문과 심의를 바꿔 놓은 선지 1이 정답이다. 조정 요구의 방향도 구분해야 한다. 국토교통부장관은 기본계획과 관리계획 모두에, 도지사는 시ㆍ군의 관리계획에만 조정을 요구한다."}},{"i":"S2-2-1-공법-14","r":"S2","g":2,"c":2,"n":54,"s":"공법","q":"도시개발법령상 개발계획에 따라 도시개발구역을 지정한 후에 개발계획에 포함시킬 수 있는 사항은?","b":null,"bs":"없음","img":[],"ch":["환경보전계획","보건의료시설 및 복지시설의 설치계획","원형지로 공급될 대상 토지 및 개발 방향","임대주택건설계획 등 세입자 등의 주거 및 생활 안정 대책","도시개발구역을 둘 이상의 사업시행지구로 분할하여 도시개발사업을 시행하는 경우 그 분할에 관한 사항"],"a":[4],"L":"공2-1","o":"기출","x":{"한줄":"구역 지정 후에 개발계획에 포함할 수 있는 사항은 제13호~제16호이고, 임대주택건설계획 등 세입자 주거ㆍ생활 안정 대책이 그중 하나다.","근거":[{"법령":"도시개발법","조문":"제5조제1항","원문":"개발계획에는 다음 각 호의 사항이 포함되어야 한다. 다만, 제13호부터 제16호까지의 규정에 해당하는 사항은 도시개발구역을 지정한 후에 개발계획에 포함시킬 수 있다. 3. 제3조의2에 따라 도시개발구역을 둘 이상의 사업시행지구로 분할하거나 서로 떨어진 둘 이상의 지역을 하나의 구역으로 결합하여 도시개발사업을 시행하는 경우에는 그 분할이나 결합에 관한 사항 7의2. 제25조의2에 따라 원형지로 공급될 대상 토지 및 개발 방향 9. 환경보전계획 10. 보건의료시설 및 복지시설의 설치계획 13. 도시개발구역 밖의 지역에 기반시설을 설치하여야 하는 경우에는 그 시설의 설치에 필요한 비용의 부담 계획 14. 수용(收用) 또는 사용의 대상이 되는 토지ㆍ건축물 또는 토지에 정착한 물건과 이에 관한 소유권 외의 권리, 광업권, 어업권, 양식업권, 물의 사용에 관한 권리(이하 \"토지등\"이라 한다)가 있는 경우에는 그 세부목록 15. 임대주택건설계획 등 세입자 등의 주거 및 생활 안정 대책 16. 제21조의2에 따른 순환개발 등 단계적 사업추진이 필요한 경우 사업추진 계획 등에 관한 사항"}],"선지":[{"번호":1,"판정":"틀림","설명":"환경보전계획은 제9호 사항이어서 구역을 지정할 때 개발계획에 담아야 한다(법 제5조제1항제9호)."},{"번호":2,"판정":"틀림","설명":"보건의료시설 및 복지시설의 설치계획은 제10호 사항으로 구역 지정 때 포함한다(법 제5조제1항제10호)."},{"번호":3,"판정":"틀림","설명":"원형지로 공급될 대상 토지 및 개발 방향은 제7호의2 사항으로 구역 지정 때 포함한다(법 제5조제1항제7호의2)."},{"번호":4,"판정":"옳음","설명":"임대주택건설계획 등 세입자 등의 주거 및 생활 안정 대책은 제15호 사항이어서 구역 지정 후에 포함할 수 있다(법 제5조제1항 단서)."},{"번호":5,"판정":"틀림","설명":"구역을 둘 이상의 사업시행지구로 분할하거나 결합하는 사항은 제3호 사항으로 구역 지정 때 포함한다(법 제5조제1항제3호)."}],"개념":[{"종류":"표","제목":"개발계획 포함사항의 시기(법 제5조제1항)","머리":["시기","호","내용"],"행":[["구역 지정 때 포함","제1호~제12호","명칭ㆍ위치ㆍ면적, 지정 목적과 시행기간, 분할ㆍ결합, 시행자, 시행방식, 인구수용계획, 토지이용계획, 원형지, 교통처리, 환경보전, 보건의료ㆍ복지시설, 기반시설, 재원조달"],["구역 지정 후 포함 가능","제13호","구역 밖 기반시설 설치 비용 부담 계획"],["구역 지정 후 포함 가능","제14호","수용 또는 사용 대상 토지등의 세부목록"],["구역 지정 후 포함 가능","제15호","임대주택건설계획 등 세입자 등의 주거ㆍ생활 안정 대책"],["구역 지정 후 포함 가능","제16호","순환개발 등 단계적 사업추진 계획"],["대통령령 사항","제17호","학교시설계획, 국가유산 보호계획, 공동구 등 지하매설물계획 등(영 제8조제1항)"]]},{"종류":"표","제목":"개발계획을 구역 지정 후에 수립하는 경우(법 제4조, 제5조제3항, 영 제9조)","머리":["구분","내용"],"행":[["사유","개발계획안을 공모하거나 대통령령으로 정하는 지역에 구역을 지정하는 경우(법 제4조제1항 단서)"],["지정 때 정할 계획","구역의 명칭ㆍ위치ㆍ면적, 지정 목적, 시행방식, 시행자, 개략적 인구수용계획, 개략적 토지이용계획(영 제9조제1항)"],["환지 방식의 동의","환지 방식이 적용되는 토지 면적의 3분의 2 이상 토지소유자와 소유자 총수의 2분의 1 이상(법 제4조제4항)"],["대규모 구역","330만제곱미터 이상이면 주거ㆍ생산ㆍ교육ㆍ유통ㆍ위락 등 기능이 조화되도록 노력(영 제9조제3항)"]]}],"함정":"지정 후에 넣을 수 있는 호는 마지막 네 개(제13호~제16호)다. 선지 5의 구역 분할(제3호)과 제16호의 단계적 사업추진은 둘 다 사업을 나누는 내용이라 구분이 어렵지만, 분할은 지정 때 정하고 단계적 추진 계획만 지정 후에 넣는다."}},{"i":"S2-2-1-공법-15","r":"S2","g":2,"c":2,"n":55,"s":"공법","q":"도시개발법령상 도시개발사업 조합에 관한 설명으로 옳은 것은?","b":null,"bs":"없음","img":[],"ch":["조합을 설립하려면 도시개발구역의 토지 소유자 10명이상이 정관을 작성하여 지정권자에게 조합 설립의 인가를 받아야 한다.","조합이 설립인가를 받은 사항 중 청산에 관한 사항을 변경하려는 경우에는 지정권자에게 신고하여야 한다.","다른 조합원으로부터 해당 도시개발구역에 그가 가지고 있는 토지 소유권 전부를 이전 받은 조합원은 정관으로 정하는 바에 따라 본래의 의결권과는 별도로 그 토지소유권을 이전한 조합원의 의결권을 승계할 수 있다.","조합은 총회의 권한을 대행하게 하기 위하여 대의원회를 두어야 한다.","조합의 임원으로 선임된 자가 금고 이상의 형을 선고받으면 그 날부터 임원의 자격을 상실한다."],"a":[3],"L":"공2-2","o":"기출","x":{"한줄":"토지 소유권 전부를 이전받은 조합원은 정관이 정하는 바에 따라 본래의 의결권과 별도로 이전한 조합원의 의결권을 승계할 수 있다.","근거":[{"법령":"도시개발법","조문":"제13조제1항","원문":"조합을 설립하려면 도시개발구역의 토지 소유자 7명 이상이 대통령령으로 정하는 사항을 포함한 정관을 작성하여 지정권자에게 조합 설립의 인가를 받아야 한다."},{"법령":"도시개발법","조문":"제13조제2항","원문":"조합이 제1항에 따라 인가를 받은 사항을 변경하려면 지정권자로부터 변경인가를 받아야 한다. 다만, 대통령령으로 정하는 경미한 사항을 변경하려는 경우에는 신고하여야 한다."},{"법령":"도시개발법 시행령","조문":"제30조","원문":"법 제13조제2항 단서에서 \"대통령령으로 정하는 경미한 사항을 변경하려는 경우\"란 다음 각 호의 경우를 말한다. 1. 주된 사무소의 소재지를 변경하려는 경우 2. 공고방법을 변경하려는 경우"},{"법령":"도시개발법 시행령","조문":"제32조제2항제1호","원문":"조합원의 권리 및 의무는 다음 각 호와 같다. 1. 보유토지의 면적과 관계없는 평등한 의결권. 다만, 다른 조합원으로부터 해당 도시개발구역에 그가 가지고 있는 토지 소유권 전부를 이전 받은 조합원은 정관으로 정하는 바에 따라 본래의 의결권과는 별도로 그 토지 소유권을 이전한 조합원의 의결권을 승계할 수 있다."},{"법령":"도시개발법 시행령","조문":"제36조제1항","원문":"의결권을 가진 조합원의 수가 50인 이상인 조합은 총회의 권한을 대행하게 하기 위하여 대의원회를 둘 수 있다."},{"법령":"도시개발법","조문":"제14조제4항","원문":"조합의 임원으로 선임된 자가 제3항 각 호의 어느 하나에 해당하게 된 경우에는 그 다음 날부터 임원의 자격을 상실한다."}],"선지":[{"번호":1,"판정":"틀림","설명":"조합 설립은 토지소유자 7명 이상이 정관을 작성해 인가를 받는다(법 제13조제1항). 10명이 아니다."},{"번호":2,"판정":"틀림","설명":"인가받은 사항의 변경은 변경인가가 원칙이다. 신고로 되는 경미한 사항은 주된 사무소 소재지와 공고방법 변경뿐이다(법 제13조제2항, 영 제30조). 청산에 관한 사항은 변경인가 대상이다."},{"번호":3,"판정":"옳음","설명":"조합원의 의결권은 보유 토지 면적과 관계없이 평등하지만, 다른 조합원의 토지 소유권 전부를 이전받은 조합원은 정관이 정하는 바에 따라 이전한 조합원의 의결권을 별도로 승계할 수 있다(영 제32조제2항제1호)."},{"번호":4,"판정":"틀림","설명":"의결권을 가진 조합원이 50인 이상인 조합이 대의원회를 ‘둘 수 있다’. 반드시 두어야 하는 것은 아니다(영 제36조제1항)."},{"번호":5,"판정":"틀림","설명":"임원 결격사유에 해당하게 되면 그 ‘다음 날부터’ 임원 자격을 상실한다(법 제14조제4항)."}],"개념":[{"종류":"흐름","제목":"도시개발조합의 설립","단계":[{"이름":"정관 작성","설명":"토지소유자 7명 이상이 정관 작성(법 제13조제1항), 정관 기재사항은 영 제29조"},{"이름":"동의","설명":"인가 신청 전에 구역 토지면적의 3분의 2 이상 소유자와 소유자 총수의 2분의 1 이상 동의(법 제13조제3항)"},{"이름":"설립 인가","설명":"지정권자의 인가, 변경도 변경인가(경미한 사항은 신고)"},{"이름":"설립 등기","설명":"인가받은 날부터 30일 이내 주된 사무소 소재지에서 등기(영 제32조제1항), 등기하면 법인으로 성립(법 제15조제2항)"},{"이름":"운영","설명":"조합장 1명, 이사, 감사 임원, 총회 의결, 50인 이상이면 대의원회를 둘 수 있음(영 제33조ㆍ제36조)"}]},{"종류":"표","제목":"조합의 임원과 총회","머리":["구분","내용","근거"],"행":[["임원 겸직","조합의 다른 임원이나 직원을 겸할 수 없음","법 제14조제2항"],["임원 결격","피성년후견인ㆍ피한정후견인ㆍ미성년자, 복권되지 않은 파산선고자, 금고 이상 형 집행 종료 후 2년이 지나지 않은 자 등","법 제14조제3항"],["자격 상실","결격사유에 해당하게 된 날의 다음 날부터","법 제14조제4항"],["대의원 수","의결권을 가진 조합원 총수의 100분의 10 이상","영 제36조제2항"],["대의원회가 대행 못하는 사항","정관 변경, 개발계획ㆍ실시계획 수립(경미한 변경 제외), 환지계획 작성, 임원 선임, 합병ㆍ해산 등","영 제36조제3항"],["총회 의결","정관 변경, 개발계획ㆍ실시계획, 자금 차입, 수지예산, 환지계획, 환지예정지 지정, 체비지 처분방법 등","영 제35조"]]}],"함정":"7명, 신고 대상 두 가지(주된 사무소 소재지, 공고방법), 50인, 다음 날부터가 한 문항에 모여 있다. 정답률은 27퍼센트였다."}},{"i":"S2-2-1-공법-16","r":"S2","g":2,"c":2,"n":56,"s":"공법","q":"도시개발법령상 도시개발사업의 시행자인 지방자치단체가 「주택법」제4조에 따른 주택건설사업자 등으로 하여금 대행하게 할 수 있는 도시개발사업의 범위에 해당하지 않는 것은?","b":null,"bs":"없음","img":[],"ch":["실시설계","부지조성공사","기반시설공사","조성된 토지의 분양","토지상환채권의 발행"],"a":[5],"L":"공2-2","o":"기출","x":{"한줄":"시행자가 주택건설사업자 등에게 대행시킬 수 있는 범위는 실시설계, 부지조성공사, 기반시설공사, 조성된 토지의 분양 네 가지뿐이어서 토지상환채권 발행은 대행 대상이 아니다.","근거":[{"법령":"도시개발법","조문":"제11조제11항","원문":"제1항제1호부터 제4호까지의 규정에 해당하는 자는 도시개발사업을 효율적으로 시행하기 위하여 필요한 경우에는 대통령령으로 정하는 바에 따라 설계ㆍ분양 등 도시개발사업의 일부를 「주택법」 제4조에 따른 주택건설사업자 등으로 하여금 대행하게 할 수 있다."},{"법령":"도시개발법 시행령","조문":"제25조의2제1항","원문":"법 제11조제11항에 따라 주택건설사업자 등에게 대행하게 할 수 있는 도시개발사업의 범위는 다음 각 호와 같다. 1. 실시설계 2. 부지조성공사 3. 기반시설공사 4. 조성된 토지의 분양"},{"법령":"도시개발법","조문":"제23조제1항","원문":"시행자는 토지 소유자가 원하면 토지등의 매수 대금의 일부를 지급하기 위하여 대통령령으로 정하는 바에 따라 사업 시행으로 조성된 토지ㆍ건축물로 상환하는 채권(이하 \"토지상환채권\"이라 한다)을 발행할 수 있다. 다만, 제11조제1항제5호부터 제11호까지의 규정에 해당하는 자는 대통령령으로 정하는 금융기관 등으로부터 지급보증을 받은 경우에만 이를 발행할 수 있다."}],"선지":[{"번호":1,"판정":"옳음","설명":"실시설계는 대행 범위다(영 제25조의2제1항제1호)."},{"번호":2,"판정":"옳음","설명":"부지조성공사는 대행 범위다(영 제25조의2제1항제2호)."},{"번호":3,"판정":"옳음","설명":"기반시설공사는 대행 범위다(영 제25조의2제1항제3호)."},{"번호":4,"판정":"옳음","설명":"조성된 토지의 분양은 대행 범위다(영 제25조의2제1항제4호)."},{"번호":5,"판정":"틀림","설명":"토지상환채권은 시행자가 발행하고(법 제23조제1항), 영 제25조의2제1항의 대행 범위에 들어 있지 않다."}],"개념":[{"종류":"흐름","제목":"도시개발사업의 대행(법 제11조제11항, 영 제25조의2)","단계":[{"이름":"대행 주체","설명":"시행자 중 국가ㆍ지방자치단체, 대통령령으로 정한 공공기관, 정부출연기관, 지방공사(법 제11조제1항제1호~제4호)"},{"이름":"대행 범위","설명":"실시설계, 부지조성공사, 기반시설공사, 조성된 토지의 분양(영 제25조의2제1항)"},{"이름":"공고","설명":"개발사업의 목적ㆍ종류ㆍ시행기간, 대행개발사업자의 자격요건ㆍ선정기준 등을 공고(영 제25조의2제2항)"},{"이름":"선정","설명":"경쟁입찰 방식으로 대행개발사업자 선정(영 제25조의2제2항)"},{"이름":"계약","설명":"대행에 관한 계약 체결(영 제25조의2제3항)"}]},{"종류":"표","제목":"도시개발사업의 시행자(법 제11조제1항)","머리":["호","시행자"],"행":[["제1호~제4호","국가ㆍ지방자치단체, 대통령령으로 정하는 공공기관, 정부출연기관, 지방공사"],["제5호","도시개발구역의 토지 소유자"],["제6호","토지 소유자가 설립한 조합(사업 전부를 환지 방식으로 시행하는 경우만)"],["제7호~제8호","과밀억제권역에서 이전하는 법인, 주택법에 따라 등록한 주택건설사업자"],["제9호ㆍ제9호의2","토목공사업 등 시행능력이 있는 자, 등록 부동산개발업자"],["제10호ㆍ제11호","부동산투자회사, 시행자가 출자해 설립한 법인"],["토지상환채권(법 제23조)","시행자가 발행, 제5호~제11호의 시행자는 지급보증을 받은 경우에만 발행, 발행계획은 지정권자 승인"]]}],"함정":"대행 범위는 열거된 네 가지로 한정된다. 분양까지 맡길 수 있다는 점과, 채권 발행처럼 자금 조달에 속하는 일은 시행자가 직접 한다는 점을 구분해야 한다."}},{"i":"S2-2-1-공법-17","r":"S2","g":2,"c":2,"n":57,"s":"공법","q":"도시개발법령상 환지 방식에 의한 사업 시행에 관한 설명으로 틀린 것은?","b":null,"bs":"없음","img":[],"ch":["환지 예정지가 지정되면 종전 토지의 소유자와 임차권자등은 환지 예정지 지정의 효력발생일부터 환지처분이 공고되는 날까지 종전의 토지를 사용하거나 수익할 수 없다.","환지 계획에서 정하여진 환지는 그 환지처분이 공고된 날부터 종전의 토지로 본다.","행정청이 아닌 시행자가 환지 계획을 작성한 경우에는 특별자치도지사ㆍ시장ㆍ군수 또는 구청장의 인가를 받아야 한다.","입체 환지의 신청 기간은 시행자가 신청 사항을 통지한 날부터 30일 이상 60일 이하로 하여야 한다.","청산금은 환지처분이 공고된 날의 다음 날에 확정된다."],"a":[2],"L":"공2-4","o":"변형","x":{"한줄":"환지는 환지처분이 공고된 날의 다음 날부터 종전의 토지로 본다. 공고된 날 당일이 아니다.","근거":[{"법령":"도시개발법","조문":"제42조제1항","원문":"환지 계획에서 정하여진 환지는 그 환지처분이 공고된 날의 다음 날부터 종전의 토지로 보며, 환지 계획에서 환지를 정하지 아니한 종전의 토지에 있던 권리는 그 환지처분이 공고된 날이 끝나는 때에 소멸한다."},{"법령":"도시개발법","조문":"제36조제1항","원문":"환지 예정지가 지정되면 종전의 토지의 소유자와 임차권자등은 환지 예정지 지정의 효력발생일부터 환지처분이 공고되는 날까지 환지 예정지나 해당 부분에 대하여 종전과 같은 내용의 권리를 행사할 수 있으며 종전의 토지는 사용하거나 수익할 수 없다."},{"법령":"도시개발법","조문":"제29조제1항","원문":"행정청이 아닌 시행자가 제28조에 따라 환지 계획을 작성한 경우에는 특별자치도지사ㆍ시장ㆍ군수 또는 구청장의 인가를 받아야 한다."},{"법령":"도시개발법","조문":"제32조제4항","원문":"제1항에 따른 입체 환지의 신청 기간은 제3항에 따라 통지한 날부터 30일 이상 60일 이하로 하여야 한다. 다만, 시행자는 제28조제1항에 따른 환지 계획의 작성에 지장이 없다고 판단하는 경우에는 20일의 범위에서 그 신청기간을 연장할 수 있다."},{"법령":"도시개발법","조문":"제42조제6항","원문":"제41조에 따른 청산금은 환지처분이 공고된 날의 다음 날에 확정된다."}],"선지":[{"번호":1,"판정":"옳음","설명":"환지 예정지가 지정되면 종전 토지의 소유자와 임차권자등은 환지 예정지에서 종전과 같은 권리를 행사하고, 종전의 토지는 사용ㆍ수익할 수 없다(법 제36조제1항)."},{"번호":2,"판정":"틀림","설명":"환지는 환지처분이 공고된 날의 ‘다음 날’부터 종전의 토지로 본다. 환지를 정하지 않은 종전 토지의 권리는 공고된 날이 끝나는 때 소멸한다(법 제42조제1항)."},{"번호":3,"판정":"옳음","설명":"행정청이 아닌 시행자는 환지 계획 작성 후 시장ㆍ군수 등의 인가를 받는다(법 제29조제1항). 행정청인 시행자는 인가가 필요 없다."},{"번호":4,"판정":"옳음","설명":"입체 환지 신청 기간은 통지한 날부터 30일 이상 60일 이하다. 환지 계획 작성에 지장이 없으면 20일의 범위에서 연장할 수 있다(법 제32조제4항)."},{"번호":5,"판정":"옳음","설명":"청산금은 환지처분이 공고된 날의 다음 날에 확정된다(법 제42조제6항). 확정된 청산금은 공고 후 징수ㆍ교부한다(법 제46조제1항)."}],"개념":[{"종류":"표","제목":"환지처분의 효과(법 제42조)","머리":["대상","효과","시점"],"행":[["환지","종전의 토지로 봄","공고된 날의 다음 날"],["환지를 정하지 않은 종전 토지의 권리","소멸","공고된 날이 끝나는 때"],["지역권","종전의 토지에 존속, 행사할 이익이 없어진 지역권은 소멸","공고된 날이 끝나는 때"],["체비지","시행자가 소유권 취득(이미 처분된 체비지는 매입자가 등기를 마친 때)","공고된 날의 다음 날"],["보류지","환지 계획에서 정한 자가 소유권 취득","공고된 날의 다음 날"],["청산금","확정","공고된 날의 다음 날"],["입체 환지","건축물의 일부와 토지의 공유지분 취득","공고된 날의 다음 날"]]},{"종류":"흐름","제목":"환지 방식의 사업 진행","단계":[{"이름":"환지 계획 작성","설명":"환지 설계, 환지 명세, 청산 대상 토지 명세, 체비지ㆍ보류지 명세 등(법 제28조제1항)"},{"이름":"공람ㆍ의견","설명":"토지 소유자와 임차권자등에게 알리고 공람, 의견서 제출, 공람 기일 종료일부터 60일 이내 검토 결과 통보(법 제29조제3항~제6항)"},{"이름":"인가","설명":"행정청이 아닌 시행자는 시장ㆍ군수 등의 인가(법 제29조제1항)"},{"이름":"환지 예정지 지정","설명":"지정 효력발생일부터 환지처분 공고일까지 종전 토지의 사용ㆍ수익 불가(법 제35조ㆍ제36조)"},{"이름":"공사 완료와 준공검사","설명":"공사 완료 공고ㆍ공람 후 준공검사(법 제40조제1항~제3항)"},{"이름":"환지처분 공고","설명":"준공검사 후 대통령령으로 정한 기간에 환지처분, 토지 소유자에게 통지하고 공고(법 제40조제4항ㆍ제5항)"},{"이름":"등기","설명":"공고 후 14일 이내 관할 등기소에 알려 촉탁 또는 신청(법 제43조제1항)"},{"이름":"청산금 징수ㆍ교부","설명":"환지처분 공고 후, 청산금 권리는 5년간 행사하지 않으면 소멸(법 제46조ㆍ제47조)"}]}],"함정":"소멸 시점과 환지 효력 시점이 다르다. 환지를 정하지 않은 종전 토지의 권리는 공고된 날이 끝나는 때에, 환지는 공고된 날의 다음 날에 효력이 생긴다. 선지 2는 이 둘을 같은 날로 만들었다."}},{"i":"S2-2-1-공법-18","r":"S2","g":2,"c":2,"n":58,"s":"공법","q":"도시개발법령상 공동으로 도시개발사업을 시행하려는 자가 정하는 규약에 포함되어야 할 사항 중 환지방식으로 시행하는 경우에만 포함되는 것은?","b":null,"bs":"없음","img":[],"ch":["사업의 범위","토지등의 관리 및 처분","공공시설용지의 부담","보류지 및 체비지의 관리ㆍ처분","토지에 대한 소유권의 변동 등 시행자에게 통보하여야 할 사항"],"a":[4],"L":"공2-4","o":"변형","x":{"한줄":"규약 포함사항 중 환지방식에서만 해당하는 것은 토지평가협의회, 환지계획ㆍ환지예정지, 보류지ㆍ체비지, 청산 네 가지이다.","근거":[{"법령":"도시개발법 시행령","조문":"제21조","원문":"법 제11조제3항에 따라 공동으로 도시개발사업을 시행하려는 자가 정하는 규약에는 다음 각 호의 사항이 포함되어야 한다. 다만, 제12호ㆍ제14호ㆍ제16호 및 제18호는 환지방식으로 도시개발사업을 시행하는 경우에만 해당한다. 1. 사업의 명칭 2. 사업의 목적 3. 도시개발구역의 위치 및 면적 4. 사업의 시행기간 5. 사업의 범위 6. 주된 사무소의 소재지 7. 임원을 정할 경우에는 그 자격ㆍ수ㆍ임기ㆍ직무 및 선임방법 8. 회의에 관한 사항 9. 비용부담 10. 회계 및 계약 11. 공고의 방법 12. 토지평가협의회의 구성 및 운영 13. 토지등의 가액의 평가방법 14. 환지계획 및 환지예정지의 지정 15. 토지등의 관리 및 처분 16. 보류지 및 체비지의 관리ㆍ처분 17. 공공시설용지의 부담 18. 청산(淸算) 19. 토지에 대한 소유권의 변동 등 시행자에게 통보하여야 할 사항 20. 그 밖에 국토교통부령으로 정하는 사항"}],"선지":[{"번호":1,"판정":"틀림","설명":"사업의 범위는 방식과 관계없이 모든 규약에 포함한다(영 제21조제5호)."},{"번호":2,"판정":"틀림","설명":"토지등의 관리 및 처분은 방식과 관계없이 포함한다(영 제21조제15호). 환지 방식의 보류지ㆍ체비지 관리ㆍ처분(제16호)과 다른 항목이다."},{"번호":3,"판정":"틀림","설명":"공공시설용지의 부담은 방식과 관계없이 포함한다(영 제21조제17호)."},{"번호":4,"판정":"옳음","설명":"보류지 및 체비지의 관리ㆍ처분은 환지방식으로 시행하는 경우에만 해당한다(영 제21조제16호 및 단서)."},{"번호":5,"판정":"틀림","설명":"소유권 변동 등 시행자에게 통보할 사항은 방식과 관계없이 포함한다(영 제21조제19호)."}],"개념":[{"종류":"표","제목":"규약 포함사항(영 제21조)","머리":["구분","호","사항"],"행":[["환지방식에서만","제12호","토지평가협의회의 구성 및 운영"],["환지방식에서만","제14호","환지계획 및 환지예정지의 지정"],["환지방식에서만","제16호","보류지 및 체비지의 관리ㆍ처분"],["환지방식에서만","제18호","청산"],["방식과 무관","제1호~제11호","사업의 명칭ㆍ목적, 구역의 위치ㆍ면적, 시행기간, 사업의 범위, 주된 사무소, 임원, 회의, 비용부담, 회계ㆍ계약, 공고방법"],["방식과 무관","제13호ㆍ제15호ㆍ제17호ㆍ제19호ㆍ제20호","토지등의 가액 평가방법, 토지등의 관리ㆍ처분, 공공시설용지의 부담, 소유권 변동 통보사항, 국토교통부령 사항"]]},{"종류":"비교","제목":"규약ㆍ시행규정ㆍ정관","왼쪽":{"이름":"규약(영 제21조)","항목":["토지 소유자 2인 이상 또는 토지 소유자와 법 제11조제1항제7호~제10호의 자가 공동으로 시행할 때 지정권자가 정하게 함(법 제11조제3항)","20개 호, 제12ㆍ14ㆍ16ㆍ18호는 환지방식만"]},"오른쪽":{"이름":"시행규정(영 제22조)","항목":["지방자치단체등이 전부를 환지 방식으로 시행하는 경우 등에 작성(법 제11조제4항)","규약 항목 중 임원(제7호)과 회의(제8호)를 뺀 사항과 사업관리비를 정함(영 제22조제2항)","시행자가 시ㆍ도지사 또는 시장ㆍ군수ㆍ구청장이면 조례로 정함(영 제22조제4항)"]}}],"함정":"‘토지등의 관리 및 처분’(제15호)과 ‘보류지 및 체비지의 관리ㆍ처분’(제16호)은 이름이 비슷하다. 앞의 것은 모든 방식에 공통이고 뒤의 것만 환지방식 전용이다. 선지 1ㆍ3ㆍ5도 모두 공통 사항이다."}},{"i":"S2-2-1-공법-19","r":"S2","g":2,"c":2,"n":59,"s":"공법","q":"도시 및 주거환경정비법령상 도시ㆍ주거환경정비기본계획(이하 ‘기본계획’)의 수립에 관한 설명으로 틀린 것은?","b":null,"bs":"없음","img":[],"ch":["특별시장ㆍ광역시장ㆍ특별자치시장ㆍ특별자치도지사 또는 시장은 관할 구역에 대하여 기본계획을 10년 단위로 수립하여야 하며, 도지사가 대도시가 아닌 시로서 기본계획을 수립할 필요가 없다고 인정하는 시에 대하여는 수립하지 아니할 수 있다.","기본계획의 수립권자는 기본계획에 대하여 5년마다 타당성을 검토하여 그 결과를 기본계획에 반영하여야 한다.","기본계획의 수립권자가 기본계획을 수립하려면 14일 이상 주민에게 공람하여 의견을 들어야 하고, 지방의회는 기본계획을 통지받은 날부터 30일 이내에 의견을 제시하여야 하며 의견 제시 없이 30일이 지나면 이의가 없는 것으로 본다.","대도시의 시장은 기본계획을 수립하거나 변경하려면 관계 행정기관의 장과 협의한 후 지방도시계획위원회의 심의를 거쳐야 한다.","기본계획의 수립권자는 기본계획을 수립하거나 변경한 때에는 지체 없이 해당 지방자치단체의 공보에 고시하고 일반인이 열람할 수 있도록 하여야 한다."],"a":[3],"L":"공3-1","o":"변형","x":{"한줄":"기본계획에 대한 지방의회의 의견 제시 기한은 통지한 날부터 60일이고, 의견 제시 없이 60일이 지나면 이의가 없는 것으로 본다.","근거":[{"법령":"도시 및 주거환경정비법","조문":"제4조","원문":"특별시장ㆍ광역시장ㆍ특별자치시장ㆍ특별자치도지사 또는 시장은 관할 구역에 대하여 도시ㆍ주거환경정비기본계획(이하 \"기본계획\"이라 한다)을 10년 단위로 수립하여야 한다. 다만, 도지사가 대도시가 아닌 시로서 기본계획을 수립할 필요가 없다고 인정하는 시에 대하여는 기본계획을 수립하지 아니할 수 있다. ② 특별시장ㆍ광역시장ㆍ특별자치시장ㆍ특별자치도지사 또는 시장(이하 \"기본계획의 수립권자\"라 한다)은 기본계획에 대하여 5년마다 타당성을 검토하여 그 결과를 기본계획에 반영하여야 한다."},{"법령":"도시 및 주거환경정비법","조문":"제6조","원문":"기본계획의 수립권자는 기본계획을 수립하거나 변경하려는 경우에는 14일 이상 주민에게 공람하여 의견을 들어야 하며, 제시된 의견이 타당하다고 인정되면 이를 기본계획에 반영하여야 한다. ② 기본계획의 수립권자는 제1항에 따른 공람과 함께 지방의회의 의견을 들어야 한다. 이 경우 지방의회는 기본계획의 수립권자가 기본계획을 통지한 날부터 60일 이내에 의견을 제시하여야 하며, 의견제시 없이 60일이 지난 경우 이의가 없는 것으로 본다. ③ 제1항 및 제2항에도 불구하고 대통령령으로 정하는 경미한 사항을 변경하는 경우에는 주민공람과 지방의회의 의견청취 절차를 거치지 아니할 수 있다."},{"법령":"도시 및 주거환경정비법","조문":"제7조제1항","원문":"기본계획의 수립권자(대도시의 시장이 아닌 시장은 제외한다)는 기본계획을 수립하거나 변경하려면 관계 행정기관의 장과 협의한 후 「국토의 계획 및 이용에 관한 법률」 제113조제1항 및 제2항에 따른 지방도시계획위원회(이하 \"지방도시계획위원회\"라 한다)의 심의를 거쳐야 한다. 다만, 대통령령으로 정하는 경미한 사항을 변경하는 경우에는 관계 행정기관의 장과의 협의 및 지방도시계획위원회의 심의를 거치지 아니한다."},{"법령":"도시 및 주거환경정비법","조문":"제7조제3항","원문":"기본계획의 수립권자는 기본계획을 수립하거나 변경한 때에는 지체 없이 이를 해당 지방자치단체의 공보에 고시하고 일반인이 열람할 수 있도록 하여야 한다."}],"선지":[{"번호":1,"판정":"옳음","설명":"기본계획은 10년 단위로 수립한다. 도지사가 대도시가 아닌 시로서 수립할 필요가 없다고 인정하는 시는 수립하지 않을 수 있다(법 제4조제1항)."},{"번호":2,"판정":"옳음","설명":"5년마다 타당성을 검토해 그 결과를 기본계획에 반영한다(법 제4조제2항)."},{"번호":3,"판정":"틀림","설명":"지방의회는 통지한 날부터 60일 이내에 의견을 제시하고, 60일이 지나면 이의가 없는 것으로 본다. 주민 공람은 14일 이상이다(법 제6조제1항ㆍ제2항)."},{"번호":4,"판정":"옳음","설명":"대도시의 시장은 관계 행정기관의 장과 협의한 뒤 지방도시계획위원회 심의를 거친다. 대도시가 아닌 시장은 도지사의 승인을 받는다(법 제7조제1항ㆍ제2항)."},{"번호":5,"판정":"옳음","설명":"수립ㆍ변경한 때에는 지체 없이 공보에 고시하고 일반인이 열람할 수 있게 하며, 고시한 때에는 국토교통부장관에게 보고한다(법 제7조제3항ㆍ제4항)."}],"개념":[{"종류":"표","제목":"기본계획의 수립ㆍ확정 절차","머리":["구분","특별시ㆍ광역시ㆍ특별자치시ㆍ특별자치도ㆍ대도시","대도시가 아닌 시"],"행":[["수립권자","특별시장ㆍ광역시장ㆍ특별자치시장ㆍ특별자치도지사ㆍ시장","시장"],["주민 공람","14일 이상(법 제6조제1항)","같음"],["지방의회 의견","통지한 날부터 60일 이내, 미제시 시 이의 없는 것으로 봄(법 제6조제2항)","같음"],["협의ㆍ심의","관계 행정기관 협의 후 지방도시계획위원회 심의(법 제7조제1항)","도지사의 승인(승인 때 협의ㆍ심의)(법 제7조제2항)"],["고시","지체 없이 공보에 고시하고 열람, 국토교통부장관에게 보고(법 제7조제3항ㆍ제4항)","같음"],["정비","5년마다 타당성 검토(법 제4조제2항)","같음"],["경미한 변경","주민공람ㆍ지방의회 의견청취 생략 가능(법 제6조제3항)","도지사 승인 생략 가능(법 제7조제2항 단서)"]]},{"종류":"표","제목":"기본계획의 내용(법 제5조)","머리":["구분","내용"],"행":[["포함사항","정비사업의 기본방향ㆍ계획기간, 현황, 주거지 관리계획, 토지이용ㆍ정비기반시설ㆍ공동이용시설ㆍ교통계획, 환경계획, 사회복지시설 설치계획, 광역적 재정비 방향, 정비예정구역의 개략적 범위, 단계별 정비사업 추진계획, 밀도계획, 세입자 주거안정대책"],["생략 가능","생활권의 설정, 생활권별 기반시설 설치계획ㆍ주택수급계획, 생활권별 주거지의 정비ㆍ보전ㆍ관리 방향을 포함하면 정비예정구역의 개략적 범위(제9호)와 단계별 추진계획(제10호)을 생략할 수 있음(법 제5조제2항)"]]}],"함정":"주민 공람은 14일 이상이고 지방의회 의견 제시는 60일 이내여서 두 기한이 다르다. 선지 3은 지방의회 기한을 30일로 바꿔 놓았다. 대도시의 시장은 협의와 심의를, 대도시가 아닌 시의 시장은 도지사 승인을 거친다."}},{"i":"S2-2-1-공법-20","r":"S2","g":2,"c":2,"n":60,"s":"공법","q":"도시 및 주거환경정비법령상 “토지등소유자”에 해당하지 않는 자는?","b":null,"bs":"없음","img":[],"ch":["주거환경개선사업 정비구역에 위치한 건축물의 소유자","재개발사업 정비구역에 위치한 토지의 지상권자","재개발사업 정비구역에 위치한 건축물의 소유자","재건축사업 정비구역에 위치한 건축물 및 그 부속토지의 소유자","재건축사업 정비구역에 위치한 건축물 부속토지의 지상권자"],"a":[5],"L":"공3-1","o":"기출","x":{"한줄":"재건축사업의 토지등소유자는 건축물 및 그 부속토지의 소유자뿐이고, 지상권자는 재개발사업과 주거환경개선사업에서만 토지등소유자가 된다.","근거":[{"법령":"도시 및 주거환경정비법","조문":"제2조제9호","원문":"이 법에서 사용하는 용어의 뜻은 다음과 같다. 9. \"토지등소유자\"란 다음 각 목의 어느 하나에 해당하는 자를 말한다. 다만, 제27조제1항에 따라 「자본시장과 금융투자업에 관한 법률」 제8조제7항에 따른 신탁업자(이하 \"신탁업자\"라 한다)가 사업시행자로 지정된 경우 토지등소유자가 정비사업을 목적으로 신탁업자에게 신탁한 토지 또는 건축물에 대하여는 위탁자를 토지등소유자로 본다. 가. 주거환경개선사업 및 재개발사업의 경우에는 정비구역에 위치한 토지 또는 건축물의 소유자 또는 그 지상권자 나. 재건축사업의 경우에는 정비구역에 위치한 건축물 및 그 부속토지의 소유자"}],"선지":[{"번호":1,"판정":"옳음","설명":"주거환경개선사업은 정비구역에 위치한 토지 또는 건축물의 소유자 또는 그 지상권자가 토지등소유자다(법 제2조제9호가목)."},{"번호":2,"판정":"옳음","설명":"재개발사업은 토지의 소유자뿐 아니라 그 지상권자도 토지등소유자다(법 제2조제9호가목)."},{"번호":3,"판정":"옳음","설명":"재개발사업의 건축물 소유자는 토지등소유자다(법 제2조제9호가목)."},{"번호":4,"판정":"옳음","설명":"재건축사업은 건축물 및 그 부속토지의 소유자가 토지등소유자다(법 제2조제9호나목)."},{"번호":5,"판정":"틀림","설명":"재건축사업은 건축물 및 부속토지의 ‘소유자’만 토지등소유자다. 부속토지의 지상권자는 해당하지 않는다(법 제2조제9호나목)."}],"개념":[{"종류":"표","제목":"정비사업별 토지등소유자(법 제2조제9호)","머리":["정비사업","토지등소유자"],"행":[["주거환경개선사업","정비구역에 위치한 토지 또는 건축물의 소유자 또는 그 지상권자"],["재개발사업","정비구역에 위치한 토지 또는 건축물의 소유자 또는 그 지상권자"],["재건축사업","정비구역에 위치한 건축물 및 그 부속토지의 소유자"],["신탁업자가 사업시행자로 지정된 경우","정비사업을 목적으로 신탁한 토지 또는 건축물에 대하여는 위탁자를 토지등소유자로 봄"]]},{"종류":"비교","제목":"재개발사업과 재건축사업(법 제2조제2호)","왼쪽":{"이름":"재개발사업","항목":["정비기반시설이 열악하고 노후ㆍ불량건축물이 밀집한 지역의 주거환경 개선","상업지역ㆍ공업지역 등에서 도시기능 회복 및 상권활성화 등을 위한 도시환경 개선","토지 또는 건축물의 소유자와 지상권자가 토지등소유자"]},"오른쪽":{"이름":"재건축사업","항목":["정비기반시설은 양호하나 노후ㆍ불량건축물에 해당하는 공동주택이 밀집한 지역의 주거환경 개선","건축물 및 그 부속토지의 소유자만 토지등소유자","토지만 가진 자나 지상권자는 토지등소유자가 아님"]}}],"함정":"재건축은 ‘건축물 및 부속토지’를 함께 가진 소유자만 토지등소유자다. 선지 2와 선지 5의 지상권자를 비교해야 한다. 재개발사업의 토지 지상권자는 포함되고 재건축사업의 부속토지 지상권자는 제외된다. 이 문항의 정답률은 28퍼센트였다."}},{"i":"S2-2-1-공법-21","r":"S2","g":2,"c":2,"n":61,"s":"공법","q":"도시 및 주거환경정비법령상 조합에 관한 설명으로 옳은 것은?","b":null,"bs":"없음","img":[],"ch":["조합임원의 임기는 5년 이하의 범위에서 정관으로 정하되, 연임할 수 있다.","토지등소유자의 수가 100인을 초과하는 조합에는 감사를 3명 이상 둔다.","대의원회는 정관으로 정하는 바에 따라 임기 중 궐위된 조합임원 중 조합장이 아닌 자를 보궐선임할 수 있다.","재개발사업의 추진위원회가 조합을 설립하려면 토지등소유자의 3분의 2 이상 및 토지면적의 2분의 1 이상의 토지소유자의 동의를 받아야 한다.","조합이 정관을 변경하여 조합원의 자격에 관한 사항을 바꾸려면 조합원 과반수의 찬성으로 총회 의결을 거쳐 시장·군수등의 인가를 받으면 된다."],"a":[3],"L":"공3-2","o":"변형","x":{"한줄":"총회 권한 중 조합임원 선임·해임은 대의원회가 대행하지 못하지만, 정관이 정한 임기 중 궐위 보궐선임은 조합장을 뺀 임원에 한해 대의원회가 할 수 있다.","근거":[{"법령":"도시 및 주거환경정비법 시행령","조문":"제43조제6호","원문":"법 제45조제1항제7호에 따른 조합임원의 선임 및 해임과 제42조제1항제2호에 따른 대의원의 선임 및 해임에 관한 사항. 다만, 정관으로 정하는 바에 따라 임기중 궐위된 자(조합장은 제외한다)를 보궐선임하는 경우를 제외한다."},{"법령":"도시 및 주거환경정비법","조문":"제41조제4항","원문":"조합임원의 임기는 3년 이하의 범위에서 정관으로 정하되, 연임할 수 있다."},{"법령":"도시 및 주거환경정비법 시행령","조문":"제40조","원문":"법 제41조제1항에 따라 조합에 두는 이사의 수는 3명 이상으로 하고, 감사의 수는 1명 이상 3명 이하로 한다. 다만, 토지등소유자의 수가 100인을 초과하는 경우에는 이사의 수를 5명 이상으로 한다."},{"법령":"도시 및 주거환경정비법","조문":"제35조제2항","원문":"재개발사업의 추진위원회(제31조제7항에 따라 추진위원회를 구성하지 아니하는 경우에는 토지등소유자를 말한다)가 조합을 설립하려면 토지등소유자의 4분의 3 이상 및 토지면적의 2분의 1 이상의 토지소유자의 동의를 받아 … 시장ㆍ군수등의 인가를 받아야 한다."},{"법령":"도시 및 주거환경정비법","조문":"제40조제3항","원문":"조합이 정관을 변경하려는 경우에는 … 총회를 개최하여 조합원 과반수의 찬성으로 시장ㆍ군수등의 인가를 받아야 한다. 다만, 제1항제2호ㆍ제3호ㆍ제4호ㆍ제8호ㆍ제13호 또는 제16호의 경우에는 조합원 3분의 2 이상의 찬성으로 한다."}],"선지":[{"번호":1,"판정":"틀림","설명":"임기는 3년 이하의 범위에서 정관으로 정하고 연임할 수 있다(법 제41조제4항)."},{"번호":2,"판정":"틀림","설명":"감사는 토지등소유자 수와 관계없이 1명 이상 3명 이하다. 100인을 초과하면 늘어나는 쪽은 이사로 5명 이상이다(영 제40조)."},{"번호":3,"판정":"옳음","설명":"임기 중 궐위된 임원을 정관에 따라 보궐선임하는 것은 대의원회가 총회 권한을 대행할 수 없는 사항에서 빠진다. 다만 궐위된 자가 조합장이면 제외된다(영 제43조제6호 단서)."},{"번호":4,"판정":"틀림","설명":"재개발조합 설립 동의는 토지등소유자 4분의 3 이상 및 토지면적 2분의 1 이상이다(법 제35조제2항)."},{"번호":5,"판정":"틀림","설명":"조합원의 자격은 정관 기재사항 제2호다. 이 항목을 바꾸는 정관 변경은 조합원 3분의 2 이상의 찬성이 있어야 한다(법 제40조제1항제2호, 제3항 단서)."}],"개념":[{"종류":"표","제목":"조합 설립·정관 변경·총회 의결의 정족수","머리":["구분","요건","조문"],"행":[["추진위원회 구성","토지등소유자 과반수 동의, 위원장 포함 5명 이상","법 제31조제1항"],["재개발 조합설립","토지등소유자 4분의 3 이상 + 토지면적 2분의 1 이상 토지소유자","법 제35조제2항"],["재건축 조합설립","각 동 구분소유자 과반수(동별 구분소유자 5 이하는 제외) + 전체 구분소유자 100분의 70 이상 + 토지면적 100분의 70 이상","법 제35조제3항"],["주택단지 아닌 지역이 포함된 재건축","그 지역 토지 또는 건축물 소유자 4분의 3 이상 + 토지면적 3분의 2 이상","법 제35조제4항"],["설립인가 사항 변경","총회에서 조합원 3분의 2 이상 찬성(경미한 사항은 신고)","법 제35조제5항"],["정관 변경","조합원 과반수 / 조합원 자격·제명·탈퇴·구역 위치와 면적·비용부담과 회계·정비사업비 부담 시기와 절차·시공자와 설계자 선정은 3분의 2 이상","법 제40조제3항"],["사업시행계획서·관리처분계획 의결","조합원 과반수 / 정비사업비가 100분의 10 이상 늘면 3분의 2 이상","법 제45조제4항"]]},{"종류":"표","제목":"조합임원과 대의원회","머리":["항목","내용","조문"],"행":[["임원 구성","조합장 1명, 이사, 감사","법 제41조제1항"],["이사·감사의 수","이사 3명 이상(토지등소유자 100인 초과 시 5명 이상), 감사 1명 이상 3명 이하","영 제40조"],["조합장 자격","정비구역 건축물·토지 5년 이상 소유, 또는 선임일 직전 3년 중 1년 이상 거주","법 제41조제1항"],["임기","3년 이하, 연임 가능","법 제41조제4항"],["대의원회 설치","조합원 100명 이상이면 의무, 조합원의 10분의 1 이상으로 구성","법 제46조제1항·제2항"],["대의원 자격","조합장이 아닌 조합임원은 대의원이 될 수 없다","법 제46조제3항"],["보궐선임","임기 중 궐위된 임원은 정관에 따라 보궐선임, 조합장은 대의원회 불가","영 제43조제6호"]]}],"함정":"임기를 5년으로, 감사를 3명 이상으로 바꾼 선지는 법 제41조제4항(3년 이하)과 영 제40조(감사 1~3명)로 가려낸다. 재개발 조합설립 동의는 4분의 3 + 토지면적 2분의 1이고 70퍼센트는 재건축 주택단지 요건이다. 정관 변경은 과반수가 원칙이며 조합원 자격 등 6개 항목만 3분의 2다."}},{"i":"S2-2-1-공법-22","r":"S2","g":2,"c":2,"n":62,"s":"공법","q":"도시 및 주거환경정비법령상 임시거주시설의 설치 등에 관한 규정의 일부이다. ( )에 들어갈 내용으로 옳은 것은?","b":"○ 사업시행자는 주거환경개선사업 및 ( ㄱ )사업의 시행으로 철거되는 주택의 소유자 또는 세입자에게 해당 정비구역 안과 밖에 위치한 임대주택 등의 시설에 임시로 거주하게 하거나 주택자금의 융자를 알선하는 등 임시거주에 상응하는 조치를 하여야 한다.\n○ 사업시행자는 정비사업의 공사를 완료한 때에는 완료한 날부터 ( ㄴ )일 이내에 임시거주시설을 철거하고, 사용한 건축물이나 토지를 원상회복하여야 한다.","bs":"글자","img":[],"ch":["ㄱ: 재건축, ㄴ: 20","ㄱ: 재건축, ㄴ: 60","ㄱ: 재개발, ㄴ: 20","ㄱ: 재개발, ㄴ: 30","ㄱ: 재개발, ㄴ: 60"],"a":[4],"L":"공3-2","o":"기출","x":{"한줄":"임시거주 조치 의무는 주거환경개선사업과 재개발사업의 철거 대상자에게 있고, 임시거주시설은 공사 완료일부터 30일 이내에 철거한다.","근거":[{"법령":"도시 및 주거환경정비법","조문":"제61조제1항","원문":"사업시행자는 주거환경개선사업 및 재개발사업의 시행으로 철거되는 주택의 소유자 또는 세입자에게 해당 정비구역 안과 밖에 위치한 임대주택 등의 시설에 임시로 거주하게 하거나 주택자금의 융자를 알선하는 등 임시거주에 상응하는 조치를 하여야 한다."},{"법령":"도시 및 주거환경정비법","조문":"제61조제4항","원문":"사업시행자는 정비사업의 공사를 완료한 때에는 완료한 날부터 30일 이내에 임시거주시설을 철거하고, 사용한 건축물이나 토지를 원상회복하여야 한다."}],"선지":[{"번호":1,"판정":"-","설명":"ㄱ은 재개발이다. 재건축은 임시거주 조치 의무 대상이 아니고, ㄴ도 30일이다(법 제61조제1항·제4항)."},{"번호":2,"판정":"-","설명":"ㄱ 재건축이 틀렸고 ㄴ 60일도 틀렸다(법 제61조제1항·제4항)."},{"번호":3,"판정":"-","설명":"ㄱ 재개발은 맞지만 ㄴ은 20일이 아니라 30일이다(법 제61조제4항)."},{"번호":4,"판정":"-","설명":"ㄱ 재개발, ㄴ 30일이 법 제61조제1항·제4항과 일치한다."},{"번호":5,"판정":"-","설명":"ㄱ 재개발은 맞지만 ㄴ은 60일이 아니라 30일이다(법 제61조제4항)."}],"개념":[{"종류":"표","제목":"임시거주시설·임시상가 한눈에","머리":["항목","내용","조문"],"행":[["조치 의무 대상","주거환경개선사업·재개발사업으로 철거되는 주택의 소유자·세입자(재건축 제외)","법 제61조제1항"],["조치 방법","구역 안팎의 임대주택 등에 임시 거주, 주택자금 융자 알선 등","법 제61조제1항"],["시설·토지 확보","국가·지방자치단체·공공단체·개인의 시설이나 토지를 일시 사용","법 제61조제2항"],["국가·지방자치단체의 사용신청 처리","영 제53조 사유가 없으면 거절 불가, 사용료·대부료 면제","법 제61조제3항"],["철거·원상회복","공사 완료일부터 30일 이내","법 제61조제4항"],["임시상가","재개발사업의 사업시행자가 이주 상가세입자용으로 설치할 수 있음","법 제61조제5항"],["비용 부담","시장·군수등이 아닌 사업시행자 사업의 임시거주시설 건설비를 시장·군수등이 일부 또는 전부 부담할 수 있음","법 제92조제2항"]]},{"종류":"흐름","제목":"임시거주시설 설치에서 철거까지","단계":[{"이름":"철거 대상자 확인","설명":"주거환경개선·재개발사업으로 철거되는 주택의 소유자와 세입자(법 제61조제1항)"},{"이름":"임시거주 조치","설명":"구역 안팎 임대주택 등에 거주시키거나 주택자금 융자 알선(법 제61조제1항)"},{"이름":"시설·토지 일시 사용","설명":"국가·지방자치단체는 제3자와 매매계약을 이미 체결했거나 사용계획이 확정된 경우 등 영 제53조 사유가 없으면 거절하지 못하고 사용료·대부료는 면제(법 제61조제3항, 영 제53조)"},{"이름":"공사 완료","설명":"정비사업의 공사를 마침"},{"이름":"철거·원상회복","설명":"완료한 날부터 30일 이내에 임시거주시설 철거, 사용한 건축물·토지 원상회복(법 제61조제4항)"}]}],"함정":"재건축을 ㄱ에 넣은 선지 1, 2는 법 제61조제1항에 재건축이 없어 탈락한다. ㄴ의 20일과 60일은 30일과 다르다. 조치 의무 대상은 주거환경개선사업과 재개발사업뿐이다."}},{"i":"S2-2-1-공법-23","r":"S2","g":2,"c":2,"n":63,"s":"공법","q":"도시 및 주거환경정비법령상 조합의 임원에 관한 설명으로 틀린 것은?","b":null,"bs":"없음","img":[],"ch":["토지등소유자의 수가 100인을 초과하는 경우 조합에 두는 이사의 수는 5명 이상으로 한다.","조합임원의 임기는 3년 이하의 범위에서 정관으로 정하되, 연임할 수 있다.","조합장이 아닌 조합임원은 대의원이 될 수 있다.","조합임원은 같은 목적의 정비사업을 하는 다른 조합의 임원 또는 직원을 겸할 수 없다.","시장ㆍ군수등이 전문조합관리인을 선정한 경우 전문조합관리인이 업무를 대행할 임원은 당연 퇴임한다."],"a":[3],"L":"공3-2","o":"기출","x":{"한줄":"대의원회에는 조합장만 들어갈 수 있고, 조합장이 아닌 조합임원은 대의원이 될 수 없다.","근거":[{"법령":"도시 및 주거환경정비법","조문":"제46조제3항","원문":"조합장이 아닌 조합임원은 대의원이 될 수 없다."},{"법령":"도시 및 주거환경정비법 시행령","조문":"제40조","원문":"법 제41조제1항에 따라 조합에 두는 이사의 수는 3명 이상으로 하고, 감사의 수는 1명 이상 3명 이하로 한다. 다만, 토지등소유자의 수가 100인을 초과하는 경우에는 이사의 수를 5명 이상으로 한다."},{"법령":"도시 및 주거환경정비법","조문":"제42조제4항","원문":"조합임원은 같은 목적의 정비사업을 하는 다른 조합의 임원 또는 직원을 겸할 수 없다."},{"법령":"도시 및 주거환경정비법","조문":"제43조제5항","원문":"제41조제5항제2호에 따라 시장ㆍ군수등이 전문조합관리인을 선정한 경우 전문조합관리인이 업무를 대행할 임원은 당연 퇴임한다."}],"선지":[{"번호":1,"판정":"옳음","설명":"100인을 초과하면 이사는 5명 이상이다(영 제40조 단서)."},{"번호":2,"판정":"옳음","설명":"임기는 3년 이하이고 연임할 수 있다(법 제41조제4항)."},{"번호":3,"판정":"틀림","설명":"조합장이 아닌 조합임원은 대의원이 될 수 없다(법 제46조제3항). 조합장은 대의원회 의장이 되면서 대의원으로 본다(법 제42조제2항)."},{"번호":4,"판정":"옳음","설명":"같은 목적의 정비사업을 하는 다른 조합의 임원·직원과 겸직할 수 없다(법 제42조제4항)."},{"번호":5,"판정":"옳음","설명":"총회가 조합원 과반수 출석과 출석 과반수 동의로 선정을 요청해 시장·군수등이 전문조합관리인을 선정한 경우, 대행 대상 임원은 당연 퇴임한다(법 제43조제5항, 제41조제5항제2호)."}],"개념":[{"종류":"표","제목":"조합임원의 결격사유(법 제43조제1항)","머리":["구분","결격 사유"],"행":[["행위능력","미성년자·피성년후견인·피한정후견인"],["파산","파산선고를 받고 복권되지 아니한 자"],["실형","금고 이상의 실형 집행이 끝나거나 면제된 날부터 2년이 지나지 아니한 자"],["집행유예","금고 이상의 형의 집행유예 기간 중에 있는 자"],["이 법 위반","이 법을 위반하여 벌금 100만원 이상 형을 선고받고 10년이 지나지 아니한 자"],["인가권자 관련자","조합설립 인가권자인 지방자치단체의 장, 지방의회의원 또는 그 배우자·직계존속·직계비속"]]},{"종류":"흐름","제목":"전문조합관리인 선정","단계":[{"이름":"선정 사유 발생","설명":"조합임원이 직무를 수행할 수 없게 된 때부터 6개월 이상 선임되지 않았거나, 총회가 조합원 과반수 출석과 출석 과반수 동의로 선정을 요청(법 제41조제5항)"},{"이름":"시장·군수등 선정","설명":"시·도조례로 정하는 바에 따라 변호사·회계사·기술사 등 대통령령 요건을 갖춘 자를 선정(법 제41조제5항)"},{"이름":"업무 대행","설명":"전문조합관리인이 조합임원의 업무를 대행"},{"이름":"임원 당연 퇴임","설명":"총회 요청(제2호)에 따라 선정한 경우 전문조합관리인이 업무를 대행할 임원은 당연 퇴임(법 제43조제5항)"}]}],"함정":"임원이면 대의원이 될 수 있다는 문장이 오답이다. 대의원이 되는 임원은 조합장뿐이고 이사·감사는 될 수 없다(법 제46조제3항). 이사 5명 이상은 토지등소유자 100인 초과일 때이고 기본은 3명 이상이다."}},{"i":"S2-2-1-공법-24","r":"S2","g":2,"c":2,"n":64,"s":"공법","q":"도시 및 주거환경정비법령상 청산금 및 비용부담 등에 관한 설명으로 옳은 것은?","b":null,"bs":"없음","img":[],"ch":["청산금을 징수할 권리는 소유권 이전고시일부터 3년간 행사하지 아니하면 소멸한다.","정비구역의 국유ㆍ공유재산은 정비사업 외의 목적으로 매각되거나 양도될 수 없다.","청산금을 지급받을 자가 받기를 거부하더라도 사업시행자는 그 청산금을 공탁할 수는 없다.","시장ㆍ군수등이 아닌 사업시행자는 부과금을 체납하는 자가 있는 때에는 지방세 체납처분의 예에 따라 부과ㆍ징수할 수 있다.","국가 또는 지방자치단체는 토지임대부 분양주택을 공급받는 자에게 해당 공급비용의 전부를 융자할 수는 없다."],"a":[2],"L":"공3-3","o":"기출","x":{"한줄":"정비구역의 국유·공유재산은 정비사업 외의 목적으로 매각하거나 양도할 수 없다.","근거":[{"법령":"도시 및 주거환경정비법","조문":"제98조제3항","원문":"정비구역의 국유ㆍ공유재산은 정비사업 외의 목적으로 매각되거나 양도될 수 없다."},{"법령":"도시 및 주거환경정비법","조문":"제90조제2항·제3항","원문":"제89조제1항에 따른 청산금을 지급받을 자가 받을 수 없거나 받기를 거부한 때에는 사업시행자는 그 청산금을 공탁할 수 있다. / 청산금을 지급(분할지급을 포함한다)받을 권리 또는 이를 징수할 권리는 제86조제2항에 따른 이전고시일의 다음 날부터 5년간 행사하지 아니하면 소멸한다."},{"법령":"도시 및 주거환경정비법","조문":"제93조제4항·제5항","원문":"시장ㆍ군수등이 아닌 사업시행자는 부과금 또는 연체료를 체납하는 자가 있는 때에는 시장ㆍ군수등에게 그 부과ㆍ징수를 위탁할 수 있다. / 시장ㆍ군수등은 제4항에 따라 부과ㆍ징수를 위탁받은 경우에는 지방세 체납처분의 예에 따라 부과ㆍ징수할 수 있다."},{"법령":"도시 및 주거환경정비법","조문":"제95조제6항","원문":"국가 또는 지방자치단체는 제80조제2항에 따라 토지임대부 분양주택을 공급받는 자에게 해당 공급비용의 전부 또는 일부를 보조 또는 융자할 수 있다."}],"선지":[{"번호":1,"판정":"틀림","설명":"청산금 징수권은 이전고시일의 다음 날부터 5년간 행사하지 않으면 소멸한다(법 제90조제3항)."},{"번호":2,"판정":"옳음","설명":"법 제98조제3항 그대로다. 정비구역 국·공유재산은 정비사업 목적으로만 매각·양도된다."},{"번호":3,"판정":"틀림","설명":"받을 수 없거나 받기를 거부하면 사업시행자는 청산금을 공탁할 수 있다(법 제90조제2항)."},{"번호":4,"판정":"틀림","설명":"시장·군수등이 아닌 사업시행자는 시장·군수등에게 부과·징수를 위탁하고, 지방세 체납처분의 예로 징수하는 쪽은 위탁받은 시장·군수등이다(법 제93조제4항·제5항)."},{"번호":5,"판정":"틀림","설명":"전부 또는 일부를 보조하거나 융자할 수 있다. 전부 융자도 가능하다(법 제95조제6항)."}],"개념":[{"종류":"흐름","제목":"이전고시와 청산금","단계":[{"이름":"이전고시","설명":"공사 완료고시 뒤 지체 없이 대지확정측량·분할절차를 거쳐 분양받을 자에게 통지하고 소유권 이전, 지방자치단체 공보에 고시한 뒤 시장·군수등에게 보고(법 제86조제1항·제2항)"},{"이름":"소유권 취득","설명":"고시가 있은 날의 다음 날 대지·건축물의 소유권 취득(법 제86조제2항)"},{"이름":"청산금 징수·지급","설명":"종전 자산 가격과 분양받은 자산 가격의 차액을 이전고시 후 징수·지급, 정관등이나 총회 의결이 있으면 관리처분계획인가 후부터 이전고시일까지 분할징수·분할지급 가능(법 제89조제1항·제2항)"},{"이름":"체납·수령거부","설명":"시장·군수등인 사업시행자는 지방세 체납처분의 예로 징수, 지급받을 자가 거부하면 공탁 가능(법 제90조제1항·제2항)"},{"이름":"소멸","설명":"이전고시일의 다음 날부터 5년간 행사하지 않으면 청산금 지급받을 권리와 징수할 권리 소멸(법 제90조제3항)"}]},{"종류":"표","제목":"비용부담과 국·공유재산","머리":["항목","내용","조문"],"행":[["정비사업비 부담","법령에 특별한 규정이 없으면 사업시행자 부담","법 제92조제1항"],["시장·군수등의 비용 부담","시장·군수등이 아닌 사업시행자 사업의 주요 정비기반시설·공동이용시설, 임시거주시설 건설비의 전부 또는 일부 부담 가능","법 제92조제2항"],["부과금","토지등소유자에게 비용과 수입의 차액을 부과·징수, 납부를 게을리하면 연체료","법 제93조제1항·제2항"],["부과금 체납","시장·군수등이 아닌 사업시행자는 시장·군수등에게 위탁, 시장·군수등은 지방세 체납처분의 예로 징수하고 징수액의 100분의 4를 교부받음","법 제93조제4항·제5항"],["국·공유재산 협의","사업시행계획에 처분 내용이 있으면 미리 관리청과 협의, 관리청은 20일 이내 의견 제시","법 제98조제1항·제2항"],["국·공유재산 처분","정비사업 외 목적 매각·양도 불가, 사업시행자 등에게 수의계약으로 우선 매각·임대 가능","법 제98조제3항·제4항"],["정비기반시설 귀속","새로 설치한 시설은 관리청에 무상 귀속, 용도가 폐지되는 종래 시설은 사업시행자에게 귀속(시장·군수등 또는 토지주택공사등 시행) 또는 설치비용 범위에서 무상 양도(그 외)","법 제97조제1항·제2항"]]}],"함정":"청산금 소멸시효는 이전고시일의 다음 날부터 5년이고 3년이 아니다. 청산금은 수령을 거부하면 공탁할 수 있고, 토지임대부 분양주택 공급비용은 전부도 융자할 수 있다."}},{"i":"S2-2-1-공법-25","r":"S2","g":2,"c":2,"n":65,"s":"공법","q":"건축법령상 제1종 근린생활시설에 해당하는 것은? (단, 동일한 건축물 안에서 당해 용도에 쓰이는 바닥면적의 합계는 1,000 m²임)","b":null,"bs":"없음","img":[],"ch":["극장","서점","탁구장","파출소","산후조리원"],"a":[5],"L":"공4-1","o":"기출","x":{"한줄":"산후조리원은 면적 제한 없이 제1종 근린생활시설이고, 나머지는 1,000㎡이면 면적 요건을 넘거나 채우지 못해 제1종에서 빠진다.","근거":[{"법령":"건축법 시행령","조문":"별표 1 제3호라목","원문":"의원, 치과의원, 한의원, 침술원, 접골원(接骨院), 조산원, 안마원, 산후조리원 등 주민의 진료ㆍ치료 등을 위한 시설"},{"법령":"건축법 시행령","조문":"별표 1 제3호가목·마목·바목","원문":"식품ㆍ잡화ㆍ의류ㆍ완구ㆍ서적ㆍ건축자재ㆍ의약품ㆍ의료기기 등 일용품을 판매하는 소매점으로서 … 바닥면적의 합계가 1천 제곱미터 미만인 것 / 탁구장, 체육도장으로서 … 500제곱미터 미만인 것 / 지역자치센터, 파출소, 지구대, 소방서, 우체국, 방송국, 보건소, 공공도서관, 건강보험공단 사무소 등 … 바닥면적의 합계가 1천 제곱미터 미만인 것"}],"선지":[{"번호":1,"판정":"-","설명":"공연장은 500㎡ 미만일 때만 제2종 근린생활시설이다(별표 1 제4호가목). 1,000㎡이므로 근린생활시설이 아니라 문화 및 집회시설이다."},{"번호":2,"판정":"-","설명":"서적 소매점은 1천㎡ '미만'이어야 제1종이다(별표 1 제3호가목). 1,000㎡는 미만이 아니므로 제1종에서 빠지고 서점으로서 제2종 근린생활시설이 된다(별표 1 제4호라목)."},{"번호":3,"판정":"-","설명":"탁구장은 500㎡ 미만일 때만 제1종이다(별표 1 제3호마목). 1,000㎡는 제2종에도 해당하지 않아 운동시설이다(별표 1 제13호가목)."},{"번호":4,"판정":"-","설명":"파출소 등 공공업무시설은 1천㎡ '미만'이어야 제1종이다(별표 1 제3호바목). 1,000㎡는 업무시설 중 공공업무시설이다(별표 1 제14호가목)."},{"번호":5,"판정":"-","설명":"산후조리원은 바닥면적 제한이 없는 제1종 근린생활시설이다(별표 1 제3호라목)."}],"개념":[{"종류":"표","제목":"제1종 근린생활시설 면적 요건(별표 1 제3호)","머리":["시설","바닥면적 합계 요건"],"행":[["일용품 소매점(식품·잡화·서적 등)","1천㎡ 미만"],["휴게음식점·제과점","300㎡ 미만"],["탁구장·체육도장","500㎡ 미만"],["파출소·우체국·보건소 등 공공업무시설","1천㎡ 미만"],["통신용 시설·전기자동차 충전소","각 1천㎡ 미만"],["금융업소·사무소·부동산중개사무소 등","30㎡ 미만"],["동물병원·동물미용실","300㎡ 미만"],["이용원·미용원·목욕장·세탁소, 의원·한의원·조산원·산후조리원, 마을회관 등","면적 제한 없음"]]},{"종류":"비교","제목":"제1종과 제2종 근린생활시설의 갈림길","왼쪽":{"이름":"제1종 근린생활시설","항목":["소매점 1천㎡ 미만","휴게음식점·제과점 300㎡ 미만","탁구장·체육도장 500㎡ 미만","공공업무시설 1천㎡ 미만","산후조리원 등 진료시설은 면적 제한 없음"]},"오른쪽":{"이름":"제2종 근린생활시설","항목":["서점(제1종에 해당하지 않는 것) 면적 제한 없음","공연장·종교집회장 500㎡ 미만","일반음식점 면적 제한 없음","휴게음식점·제과점 300㎡ 이상","학원·교습소 500㎡ 미만","독서실·기원"]}}],"함정":"서점·탁구장·파출소는 이름만 보면 근린생활시설이다. 1,000㎡이면 소매점 '1천㎡ 미만', 탁구장 '500㎡ 미만', 공공업무시설 '1천㎡ 미만' 요건을 채우지 못한다. 서점은 제1종이 아니라 제2종 근린생활시설이다."}},{"i":"S2-2-1-공법-26","r":"S2","g":2,"c":2,"n":66,"s":"공법","q":"甲은 A광역시 B구에서 18층, 연면적 합계 6만 제곱미터의 허가대상 건축물을 신축하려고 한다. 건축법령상 이에 관한 설명으로 옳은 것은? (단, 건축법령상 특례규정은 고려하지 않음)","b":null,"bs":"없음","img":[],"ch":["甲은 A광역시장의 허가를 받아야 한다.","甲이 건축허가를 받은 경우에도 공사용 가설건축물을 축조하려면 따로 축조신고를 하여야 한다.","A광역시장이 지역계획에 특히 필요하다고 인정하여 B구청장의 건축허가를 받은 건축물의 착공을 제한하는 경우, 제한기간은 2년 이내로 하며 연장할 수 없다.","국토교통부장관은 주무부장관이 국가유산의 보존을 위하여 특히 필요하다고 인정하여 요청하면 B구청장의 허가를 받은 해당 건축물의 착공을 제한할 수 있다.","甲이 착공신고를 할 때 공사감리자를 지정한 경우에도 신고서에는 공사시공자만 서명하면 된다."],"a":[4],"L":"공4-2","o":"변형","x":{"한줄":"국토교통부장관은 주무부장관이 국가유산 보존 등을 이유로 요청하면 허가권자의 건축허가나 허가받은 건축물의 착공을 제한할 수 있다.","근거":[{"법령":"건축법","조문":"제18조제1항","원문":"국토교통부장관은 국토관리를 위하여 특히 필요하다고 인정하거나 주무부장관이 국방, 「국가유산기본법」 제3조에 따른 국가유산의 보존, 환경보전 또는 국민경제를 위하여 특히 필요하다고 인정하여 요청하면 허가권자의 건축허가나 허가를 받은 건축물의 착공을 제한할 수 있다."},{"법령":"건축법 시행령","조문":"제8조제1항","원문":"법 제11조제1항 단서에 따라 특별시장 또는 광역시장의 허가를 받아야 하는 건축물의 건축은 층수가 21층 이상이거나 연면적의 합계가 10만 제곱미터 이상인 건축물의 건축 … 을 말한다."},{"법령":"건축법","조문":"제11조제5항","원문":"제1항에 따른 건축허가를 받으면 다음 각 호의 허가 등을 받거나 신고를 한 것으로 본다. 1. 제20조제3항에 따른 공사용 가설건축물의 축조신고 2. 제83조에 따른 공작물의 축조신고 …"},{"법령":"건축법","조문":"제18조제4항","원문":"제1항이나 제2항에 따라 건축허가나 건축물의 착공을 제한하는 경우 제한기간은 2년 이내로 한다. 다만, 1회에 한하여 1년 이내의 범위에서 제한기간을 연장할 수 있다."},{"법령":"건축법","조문":"제21조제2항","원문":"제1항에 따라 공사계획을 신고하거나 변경신고를 하는 경우 해당 공사감리자(제25조제1항에 따른 공사감리자를 지정한 경우만 해당된다)와 공사시공자가 신고서에 함께 서명하여야 한다."}],"선지":[{"번호":1,"판정":"틀림","설명":"광역시장 허가 대상은 21층 이상이거나 연면적 10만㎡ 이상이다. 18층·6만㎡는 어느 쪽도 채우지 못해 B구청장의 허가를 받는다(법 제11조제1항, 영 제8조제1항)."},{"번호":2,"판정":"틀림","설명":"건축허가를 받으면 공사용 가설건축물 축조신고와 공작물 축조신고를 한 것으로 본다(법 제11조제5항제1호·제2호)."},{"번호":3,"판정":"틀림","설명":"제한기간은 2년 이내이고 1회에 한해 1년 이내로 연장할 수 있다(법 제18조제4항)."},{"번호":4,"판정":"옳음","설명":"국토교통부장관의 제한권은 허가권자가 구청장이어도 미친다(법 제18조제1항)."},{"번호":5,"판정":"틀림","설명":"공사감리자를 지정한 경우에는 공사감리자와 공사시공자가 신고서에 함께 서명한다(법 제21조제2항)."}],"개념":[{"종류":"표","제목":"건축허가권자와 도지사 승인","머리":["구분","내용","조문"],"행":[["원칙","특별자치시장·특별자치도지사·시장·군수·구청장의 허가","법 제11조제1항"],["특별시·광역시 예외","21층 이상이거나 연면적 합계 10만㎡ 이상(연면적 10분의 3 이상을 증축해 이 규모가 되는 경우 포함)인 건축물은 특별시장·광역시장 허가","영 제8조제1항"],["예외의 예외","공장, 창고, 지방건축위원회 심의를 거친 건축물(초고층 제외)은 구청장 허가","영 제8조제1항 단서"],["도지사 승인","시장·군수가 21층 이상 등 건축물, 환경·수질 보호구역의 3층 이상 또는 1천㎡ 이상 위락·숙박 등 건축물을 허가하려면 미리 도지사 승인","법 제11조제2항"],["허가의 의제","공사용 가설건축물·공작물 축조신고, 개발행위허가, 산지전용허가·신고, 농지전용허가 등","법 제11조제5항"]]},{"종류":"표","제목":"건축허가·착공 제한(법 제18조)","머리":["구분","국토교통부장관","특별시장·광역시장·도지사"],"행":[["제한 사유","국토관리상 특히 필요, 또는 주무부장관이 국방·국가유산 보존·환경보전·국민경제를 위해 요청","지역계획이나 도시·군계획에 특히 필요"],["제한 대상","허가권자의 건축허가, 허가받은 건축물의 착공","시장·군수·구청장의 건축허가, 허가받은 건축물의 착공"],["절차","주민의견 청취 후 건축위원회 심의","주민의견 청취 후 건축위원회 심의, 제한 즉시 국토교통부장관에게 보고"],["기간","2년 이내, 1회 한해 1년 이내 연장","2년 이내, 1회 한해 1년 이내 연장"],["통보","제한 목적·기간·대상 등을 허가권자에게 통보, 허가권자는 지체 없이 공고","같음"]]}],"함정":"광역시 건축물이라는 이유만으로 광역시장 허가가 되지 않는다. 21층 이상 또는 연면적 10만㎡ 이상이어야 한다. 가설건축물·공작물 축조신고는 건축허가에 의제된다. 착공 제한기간은 2년 이내에 1회 1년 연장이다."}},{"i":"S2-2-1-공법-27","r":"S2","g":2,"c":2,"n":67,"s":"공법","q":"건축법령상 건축 관련 입지와 규모의 사전결정에 관한 설명으로 틀린 것은?","b":null,"bs":"없음","img":[],"ch":["건축허가 대상 건축물을 건축하려는 자는 건축허가를 신청하기 전에 허가권자에게 건축허가를 받기 위하여 신청자가 고려하여야 할 사항에 대한 사전결정을 신청할 수 있다.","사전결정신청자는 건축위원회 심의와 「도시교통정비촉진법」에 따른 교통영향평가서의 검토를 동시에 신청할 수 있다.","허가권자는 사전결정이 신청된 건축물의 대지면적이 「환경영향평가법」에 따른 소규모 환경영향평가 대상 사업인 경우 기후에너지환경부장관이나 지방환경관서의 장과 소규모 환경영향평가에 관한 협의를 하여야 한다.","허가권자는 사전결정을 하려면 미리 관계 행정기관의 장과 협의하여야 하며, 협의를 요청받은 관계 행정기관의 장은 요청받은 날부터 10일 이내에 의견을 제출하여야 한다.","사전결정신청자가 사전결정을 통지받은 날부터 2년 이내에 건축허가를 신청하지 아니하면 그 사전결정의 효력이 상실된다."],"a":[4],"L":"공4-2","o":"기출","x":{"한줄":"사전결정에 따른 의제 사항을 협의하는 관계 행정기관의 장은 요청받은 날부터 10일이 아니라 15일 이내에 의견을 제출해야 한다.","근거":[{"법령":"건축법","조문":"제10조제7항","원문":"허가권자는 제6항 각 호의 어느 하나에 해당되는 내용이 포함된 사전결정을 하려면 미리 관계 행정기관의 장과 협의하여야 하며, 협의를 요청받은 관계 행정기관의 장은 요청받은 날부터 15일 이내에 의견을 제출하여야 한다."},{"법령":"건축법","조문":"제10조제9항","원문":"사전결정신청자는 제4항에 따른 사전결정을 통지받은 날부터 2년 이내에 제11조에 따른 건축허가를 신청하여야 하며, 이 기간에 건축허가를 신청하지 아니하면 사전결정의 효력이 상실된다."}],"선지":[{"번호":1,"판정":"옳음","설명":"허가 대상 건축물을 건축하려는 자는 허가 신청 전에 사전결정을 신청할 수 있다(법 제10조제1항제3호)."},{"번호":2,"판정":"옳음","설명":"건축위원회 심의와 교통영향평가서 검토를 동시에 신청할 수 있다(법 제10조제2항)."},{"번호":3,"판정":"옳음","설명":"소규모 환경영향평가 대상 사업이면 기후에너지환경부장관이나 지방환경관서의 장과 협의한다(법 제10조제3항)."},{"번호":4,"판정":"틀림","설명":"관계 행정기관의 장은 15일 이내에 의견을 제출하고, 기간 내 제출하지 않으면 협의가 이루어진 것으로 본다(법 제10조제7항·제8항)."},{"번호":5,"판정":"옳음","설명":"통지받은 날부터 2년 이내에 건축허가를 신청해야 하고, 그러지 않으면 사전결정의 효력이 상실된다(법 제10조제9항)."}],"개념":[{"종류":"흐름","제목":"사전결정에서 건축허가까지","단계":[{"이름":"사전결정 신청","설명":"허가 대상 건축물을 건축하려는 자가 허가 신청 전에 허가권자에게 신청. 건축 허용 여부, 건축 가능 규모, 허가 신청 시 고려할 사항(법 제10조제1항)"},{"이름":"동시 신청·협의","설명":"건축위원회 심의와 교통영향평가서 검토를 동시에 신청 가능. 소규모 환경영향평가 대상이면 기후에너지환경부장관 또는 지방환경관서의 장과 협의(법 제10조제2항·제3항)"},{"이름":"관계 행정기관 협의","설명":"의제되는 허가 내용이 있으면 미리 협의, 요청받은 날부터 15일 이내 의견 제출, 미제출 시 협의된 것으로 봄(법 제10조제7항·제8항)"},{"이름":"사전결정 통지","설명":"허가권자가 입지·규모·용도 등을 사전결정해 신청자에게 통지(법 제10조제4항)"},{"이름":"건축허가 신청","설명":"통지받은 날부터 2년 이내에 건축허가 신청. 넘기면 효력 상실(법 제10조제9항)"}]},{"종류":"표","제목":"사전결정 통지로 의제되는 허가(법 제10조제6항)","머리":["의제 대상","근거 법률"],"행":[["개발행위허가","국토의 계획 및 이용에 관한 법률 제56조"],["산지전용허가·신고, 산지일시사용허가·신고(보전산지는 도시지역만)","산지관리법 제14조·제15조·제15조의2"],["농지전용허가·신고·협의","농지법 제34조·제35조·제43조"],["하천점용허가","하천법 제33조"]]}],"함정":"협의 기간은 15일이고 10일이 아니다. 효력 상실 기준은 착공이 아니라 건축허가 신청이며 기간은 2년이다. 선지 3의 기후에너지환경부장관은 현행 명칭이라 맞는 문장이다.","개정":"소규모 환경영향평가 협의 상대 기관이 환경부장관에서 기후에너지환경부장관으로 바뀌었다(2025.10.1, 법 제10조제3항). 정답은 달라지지 않는다."}},{"i":"S2-2-1-공법-28","r":"S2","g":2,"c":2,"n":68,"s":"공법","q":"건축법령상 건축물의 면적 등의 산정방법으로 옳은 것은?","b":null,"bs":"없음","img":[],"ch":["공동주택으로서 지상층에 설치한 기계실과 어린이놀이터의 면적은 바닥면적에 산입하지 아니한다.","용적률을 산정할 때 지상층의 주차용(해당 건축물의 부속용도인 경우만 해당한다)으로 쓰는 면적은 연면적에 산입한다.","건축물의 1층 전체에 필로티가 설치되어 있는 경우에도 건축물의 높이 제한 규정을 적용할 때에는 필로티의 층고를 포함하여 높이를 산정한다.","지하층은 건축물의 층수에 산입한다.","건축물이 부분에 따라 그 층수가 다른 경우에는 그 중 가장 적은 층수를 그 건축물의 층수로 본다."],"a":[1],"L":"공4-3","o":"변형","x":{"한줄":"공동주택의 지상층 기계실·전기실·어린이놀이터·조경시설·생활폐기물 보관시설은 바닥면적에 넣지 않는다.","근거":[{"법령":"건축법 시행령","조문":"제119조제1항제3호마목","원문":"공동주택으로서 지상층에 설치한 기계실, 전기실, 어린이놀이터, 조경시설 및 생활폐기물 보관시설의 면적은 바닥면적에 산입하지 않는다."},{"법령":"건축법 시행령","조문":"제119조제1항제4호","원문":"연면적: 하나의 건축물 각 층의 바닥면적의 합계로 하되, 용적률을 산정할 때에는 다음 각 목에 해당하는 면적은 제외한다. 가. 지하층의 면적 나. 지상층의 주차용(해당 건축물의 부속용도인 경우만 해당한다)으로 쓰는 면적 …"},{"법령":"건축법 시행령","조문":"제119조제1항제5호","원문":"건축물의 높이: 지표면으로부터 그 건축물의 상단까지의 높이[건축물의 1층 전체에 필로티 … 가 설치되어 있는 경우에는 법 제60조 및 법 제61조제2항을 적용할 때 필로티의 층고를 제외한 높이]로 한다."},{"법령":"건축법 시행령","조문":"제119조제1항제9호","원문":"층수: 다음 각 목에 해당하는 것은 건축물의 층수에 산입하지 않고, … 건축물이 부분에 따라 그 층수가 다른 경우에는 그 중 가장 많은 층수를 그 건축물의 층수로 본다. … 나. 지하층"}],"선지":[{"번호":1,"판정":"옳음","설명":"공동주택의 지상층 기계실·전기실·어린이놀이터·조경시설·생활폐기물 보관시설은 바닥면적에 산입하지 않는다(영 제119조제1항제3호마목)."},{"번호":2,"판정":"틀림","설명":"용적률 산정 연면적에서 제외되는 것은 지하층 면적과 지상층의 주차용 면적(부속용도인 경우)이다(영 제119조제1항제4호)."},{"번호":3,"판정":"틀림","설명":"1층 전체가 필로티이면 법 제60조·제61조제2항을 적용할 때 필로티의 층고를 제외한 높이로 산정한다(영 제119조제1항제5호)."},{"번호":4,"판정":"틀림","설명":"지하층은 건축물의 층수에 산입하지 않는다(영 제119조제1항제9호나목)."},{"번호":5,"판정":"틀림","설명":"층수가 부분마다 다르면 가장 많은 층수를 그 건축물의 층수로 본다(영 제119조제1항제9호)."}],"개념":[{"종류":"표","제목":"면적·높이·층수 산정 기준(영 제119조제1항)","머리":["구분","산정 방법","예외·주의"],"행":[["대지면적","수평투영면적","건축선과 도로 사이 대지, 도시·군계획시설 도로·공원 포함 대지는 제외"],["건축면적","외벽 중심선으로 둘러싸인 부분의 수평투영면적","처마·차양 등 외벽 중심선에서 1미터 이상 돌출 시 끝에서 1미터 후퇴한 선(전통사찰 4미터, 한옥 2미터 등)"],["바닥면적","벽·기둥 구획 중심선으로 둘러싸인 부분의 수평투영면적","벽·기둥 구획이 없으면 지붕 끝에서 1미터 후퇴한 선"],["연면적","각 층 바닥면적의 합계","용적률 산정 시 지하층, 지상층 부속 주차용 면적, 피난안전구역 면적 등 제외"],["건축물의 높이","지표면에서 건축물 상단까지","1층 전체가 필로티면 법 제60조·제61조제2항 적용 시 필로티 층고 제외"],["층고","방의 바닥구조체 윗면에서 위층 바닥구조체 윗면까지","한 방에서 층 높이가 다르면 면적 가중평균"],["층수","층의 구분이 불명확하면 높이 4미터마다 1개 층","지하층, 옥탑 등 건축면적 8분의 1 이하 부분은 불산입, 부분별 층수가 다르면 가장 많은 층수"]]},{"종류":"표","제목":"바닥면적에 산입하지 않는 것(영 제119조제1항제3호)","머리":["항목","내용"],"행":[["필로티","벽면적의 2분의 1 이상이 공간인 필로티 부분이 공중 통행·차량 통행·주차에 전용되는 경우와 공동주택의 경우"],["공동주택 지상층 시설","기계실, 전기실, 어린이놀이터, 조경시설, 생활폐기물 보관시설"],["옥상 등 구조물","승강기탑, 계단탑, 장식탑, 옥상·옥외·지하의 물탱크·기름탱크·냉각탑·정화조 설치 구조물"],["다락","층고 1.5미터(경사지붕은 1.8미터) 이하인 다락"],["지하주차장 경사로","지상층에서 지하 1층으로 내려가는 부분"]]}],"함정":"'산입한다'와 '산입하지 아니한다'를 뒤집은 선지가 나온다. 용적률 연면적에서 빠지는 것은 지하층과 부속 주차용 지상층 면적이다. 층수는 가장 많은 층수를 따르고 평균하지 않으며, 지하층은 층수에 넣지 않는다."}},{"i":"S2-2-1-공법-29","r":"S2","g":2,"c":2,"n":69,"s":"공법","q":"건축법령상 건축물에 공개 공지 또는 공개 공간을 설치하여야 하는 대상지역에 해당하지 않는 것은? (단, 특별자치시장·특별자치도지사 또는 시장·군수·구청장이 별도로 지정·공고하는 지역은 고려하지 않음)","b":null,"bs":"없음","img":[],"ch":["제3종일반주거지역","제1종전용주거지역","일반상업지역","준공업지역","준주거지역"],"a":[2],"L":"공4-3","o":"변형","x":{"한줄":"공개공지 대상지역은 일반주거지역·준주거지역·상업지역·준공업지역이고, 전용주거지역은 들어가지 않는다.","근거":[{"법령":"건축법","조문":"제43조제1항","원문":"다음 각 호의 어느 하나에 해당하는 지역의 환경을 쾌적하게 조성하기 위하여 대통령령으로 정하는 용도와 규모의 건축물은 … 공개 공지(空地: 공터) 또는 공개 공간 … 을 설치하여야 한다. 1. 일반주거지역, 준주거지역 2. 상업지역 3. 준공업지역 4. 특별자치시장ㆍ특별자치도지사 또는 시장ㆍ군수ㆍ구청장이 도시화의 가능성이 크거나 노후 산업단지의 정비가 필요하다고 인정하여 지정ㆍ공고하는 지역"}],"선지":[{"번호":1,"판정":"-","설명":"제3종일반주거지역은 일반주거지역에 속한다(법 제43조제1항제1호)."},{"번호":2,"판정":"-","설명":"전용주거지역은 대상지역 열거에 없다. 일반주거지역·준주거지역과 구별해야 한다(법 제43조제1항)."},{"번호":3,"판정":"-","설명":"일반상업지역은 상업지역에 속한다(법 제43조제1항제2호)."},{"번호":4,"판정":"-","설명":"준공업지역이 대상이다(법 제43조제1항제3호). 일반공업지역·전용공업지역은 대상이 아니다."},{"번호":5,"판정":"-","설명":"준주거지역이 대상이다(법 제43조제1항제1호)."}],"개념":[{"종류":"표","제목":"공개공지등 대상지역·대상건축물·운영","머리":["항목","내용","조문"],"행":[["대상지역","일반주거지역, 준주거지역, 상업지역, 준공업지역, 시장·군수·구청장이 도시화 가능성이나 노후 산업단지 정비를 이유로 지정·공고하는 지역","법 제43조제1항"],["대상건축물","문화 및 집회시설, 종교시설, 판매시설(농수산물유통시설 제외), 여객용 운수시설, 업무시설, 숙박시설로 해당 용도 바닥면적 합계 5천㎡ 이상","영 제27조의2제1항제1호"],["설치 면적","대지면적의 100분의 10 이하 범위에서 건축조례로 정함","영 제27조의2제2항"],["건축기준 완화","용적률은 해당 지역 용적률의 1.2배 이하, 높이 제한은 해당 건축물 높이기준의 1.2배 이하","영 제27조의2제4항"],["행사 개최","연간 60일 이내에 건축조례에 따라 문화행사·판촉활동 가능, 울타리 설치 등 이용 방해는 불가","영 제27조의2제6항"],["금지 행위","영업을 위한 점유, 물건 적치, 출입 차단, 시설 훼손 등","법 제43조제4항, 영 제27조의2제7항"]]},{"종류":"비교","제목":"공개공지 대상 여부로 본 용도지역","왼쪽":{"이름":"대상지역","항목":["제1·2·3종 일반주거지역","준주거지역","중심·일반·근린·유통 상업지역","준공업지역"]},"오른쪽":{"이름":"대상지역이 아닌 곳","항목":["전용주거지역","전용공업지역·일반공업지역","녹지지역","관리지역·농림지역·자연환경보전지역"]}}],"함정":"전용주거지역은 주거지역이어도 대상지역이 아니다. 대상은 일반주거지역·준주거지역이다. 공업지역은 준공업지역만 해당한다. 대상건축물 요건(5천㎡ 이상)은 지역 요건과 별개다."}},{"i":"S2-2-1-공법-30","r":"S2","g":2,"c":2,"n":70,"s":"공법","q":"건축주 甲은 수면 위에 건축물을 건축하고자 한다. 건축법령상 그 건축물의 대지의 범위를 설정하기 곤란한 경우 甲이 허가권자에게 완화 적용을 요청할 수 없는 기준은? (단, 다른 조건과 조례는 고려하지 않음)","b":null,"bs":"없음","img":[],"ch":["대지의 조경","공개 공지 등의 확보","건축물의 높이 제한","대지의 안전","건축물 내진등급의 설정"],"a":[5],"L":"공4-3","o":"기출","x":{"한줄":"수면 위 건축물처럼 대지 범위를 정하기 곤란하면 법 제40조~제47조, 제55조~제57조, 제60조, 제61조 기준의 완화를 요청할 수 있는데, 내진등급 설정은 여기에 들지 않는다.","근거":[{"법령":"건축법 시행령","조문":"제6조제1항제1호","원문":"수면 위에 건축하는 건축물 등 대지의 범위를 설정하기 곤란한 경우: 법 제40조부터 제47조까지, 법 제55조부터 제57조까지, 법 제60조 및 법 제61조에 따른 기준"},{"법령":"건축법","조문":"제5조제1항","원문":"건축주, 설계자, 공사시공자 또는 공사감리자(이하 \"건축관계자\"라 한다)는 업무를 수행할 때 이 법을 적용하는 것이 매우 불합리하다고 인정되는 대지나 건축물로서 대통령령으로 정하는 것에 대하여는 이 법의 기준을 완화하여 적용할 것을 허가권자에게 요청할 수 있다."}],"선지":[{"번호":1,"판정":"-","설명":"대지의 조경은 법 제42조로 법 제40조~제47조 범위에 들어 완화 요청이 가능하다."},{"번호":2,"판정":"-","설명":"공개 공지 등의 확보는 법 제43조로 같은 범위에 들어 요청이 가능하다."},{"번호":3,"판정":"-","설명":"건축물의 높이 제한은 법 제60조·제61조에 해당해 요청이 가능하다."},{"번호":4,"판정":"-","설명":"대지의 안전은 법 제40조로 요청이 가능하다."},{"번호":5,"판정":"-","설명":"내진등급 설정은 구조안전 기준(법 제48조 이하)이다. 영 제6조제1항제1호가 열거한 조문에 없어 이 사유로는 완화를 요청할 수 없다."}],"개념":[{"종류":"표","제목":"적용의 완화 요청 사유와 완화 대상 기준(영 제6조제1항)","머리":["사유","완화 대상 기준(건축법 조문)"],"행":[["수면 위 건축 등 대지 범위 설정 곤란","제40조~제47조, 제55조~제57조, 제60조, 제61조"],["거실이 없는 통신시설·기계설비시설","제44조~제46조(대지와 도로, 건축선)"],["31층 이상 건축물(전부 공동주택 제외), 발전소·제철소 등 특수 용도","제43조, 제49조~제52조, 제62조, 제64조, 제67조, 제68조"],["전통사찰·전통한옥 등 시·도 건축조례로 정하는 지역","제2조제1항제11호, 제44조, 제46조, 제60조제3항"],["경사지 계단식 공동주택, 초고층 건축물","제55조(건폐율)"],["리모델링 활성화 구역, 사용승인 후 15년 이상 건축물 등","제42조, 제43조, 제46조, 제55조, 제56조, 제58조, 제60조, 제61조제2항"]]},{"종류":"흐름","제목":"적용 완화 요청 절차","단계":[{"이름":"완화 요청","설명":"건축관계자(건축주·설계자·공사시공자·공사감리자)가 허가권자에게 요청(법 제5조제1항)"},{"이름":"건축위원회 심의","설명":"허가권자가 심의를 거쳐 완화 여부와 적용 범위 결정(법 제5조제2항)"},{"이름":"결과 통지","설명":"결정 결과를 신청인에게 알림. 요청·결정 절차는 지방자치단체 조례로 정함(법 제5조제2항·제3항)"}]}],"함정":"수면 위 건축물은 법 제40조~제47조, 제55조~제57조, 제60조, 제61조 기준의 완화를 요청할 수 있다. 대지의 조경·공개공지·대지의 안전은 이 범위에 있고 내진등급(구조안전)은 없다."}},{"i":"S2-2-1-공법-31","r":"S2","g":2,"c":2,"n":71,"s":"공법","q":"건축법령상 건축등과 관련된 분쟁으로서 건축분쟁전문위원회의 조정 및 재정의 대상이 되지 않는 것은? (단, 「건설산업기본법」 제69조에 따른 조정의 대상이 되는 분쟁은 제외함)","b":null,"bs":"없음","img":[],"ch":["‘건축주’와 ‘해당 건축물의 건축으로 피해를 입은 인근주민’ 간의 분쟁","‘건축허가권자’와 ‘해당 건축물의 건축으로 피해를 입은 인근주민’ 간의 분쟁","‘공사감리자’와 ‘관계전문기술자’ 간의 분쟁","‘설계자’와 ‘공사시공자’ 간의 분쟁","‘해당 건축물의 건축으로 피해를 입은 인근주민’ 상호 간의 분쟁"],"a":[2],"L":"공4-4","o":"변형","x":{"한줄":"분쟁위원회의 대상은 건축관계자·관계전문기술자·인근주민 상호 간 분쟁이고, 허가권자는 당사자에 들어 있지 않다.","근거":[{"법령":"건축법","조문":"제88조제1항","원문":"건축등과 관련된 다음 각 호의 분쟁(「건설산업기본법」 제69조에 따른 조정의 대상이 되는 분쟁은 제외한다. 이하 같다)의 조정(調停) 및 재정(裁定)을 하기 위하여 국토교통부에 건축분쟁전문위원회(이하 \"분쟁위원회\"라 한다)를 둔다. 1. 건축관계자와 해당 건축물의 건축등으로 피해를 입은 인근주민(이하 \"인근주민\"이라 한다) 간의 분쟁 2. 관계전문기술자와 인근주민 간의 분쟁 3. 건축관계자와 관계전문기술자 간의 분쟁 4. 건축관계자 간의 분쟁 5. 인근주민 간의 분쟁 6. 관계전문기술자 간의 분쟁 7. 그 밖에 대통령령으로 정하는 사항"},{"법령":"건축법","조문":"제5조제1항","원문":"건축주, 설계자, 공사시공자 또는 공사감리자(이하 \"건축관계자\"라 한다)"}],"선지":[{"번호":1,"판정":"-","설명":"건축주는 건축관계자다. 건축관계자와 인근주민 간 분쟁이므로 대상이다(법 제88조제1항제1호)."},{"번호":2,"판정":"-","설명":"허가권자는 건축관계자도 관계전문기술자도 인근주민도 아니다. 이 분쟁은 법 제88조제1항 각 호에 없어 대상이 아니다."},{"번호":3,"판정":"-","설명":"공사감리자는 건축관계자라서 관계전문기술자와의 분쟁은 대상이다(법 제88조제1항제3호)."},{"번호":4,"판정":"-","설명":"설계자와 공사시공자는 모두 건축관계자다. 건축관계자 간 분쟁이므로 대상이다(법 제88조제1항제4호)."},{"번호":5,"판정":"-","설명":"인근주민 간의 분쟁도 대상이다(법 제88조제1항제5호)."}],"개념":[{"종류":"표","제목":"건축분쟁전문위원회","머리":["항목","내용","조문"],"행":[["설치","국토교통부","법 제88조제1항"],["대상 분쟁","건축관계자·관계전문기술자·인근주민 상호 간 분쟁 6종과 대통령령 사항","법 제88조제1항"],["구성","위원장·부위원장 각 1명을 포함한 15명 이내","법 제89조제1항"],["위원 임기","공무원이 아닌 위원 3년, 연임 가능","법 제89조제5항"],["의결","재적위원 과반수 출석, 출석위원 과반수 찬성","법 제89조제6항"],["신청","조정은 당사자 중 1명 이상, 재정은 당사자 간 합의","법 제92조제2항"],["처리 기간","조정 60일 이내, 재정 120일 이내(부득이하면 의결로 연장)","법 제92조제3항"],["공사 중지","긴급한 위해 방지 등 특별한 사유가 없으면 신청만으로 공사 중지 불가","법 제93조제3항"]]},{"종류":"표","제목":"이행강제금(법 제80조)","머리":["항목","내용"],"행":[["부과 요건","시정명령을 받고 시정기간 내에 이행하지 않은 건축주등에게 이행기한을 정해 부과"],["금액(건폐율·용적률 초과, 무허가·무신고)","1㎡ 시가표준액의 100분의 50에 위반면적을 곱한 금액 이하에서 영이 정한 비율을 곱한 금액"],["금액(그 밖의 위반)","건축물 시가표준액의 100분의 10 범위에서 영이 정한 금액"],["감경","연면적 60㎡ 이하 주거용 건축물 등은 금액의 2분의 1 범위에서 조례로 정함"],["가중","영리목적·상습 위반은 100분의 100 범위에서 조례로 가중"],["절차","미리 문서로 계고, 부과 때 금액·사유·납기·이의제기 방법을 문서로 밝힘"],["반복 부과","최초 시정명령일 기준 1년에 2회 이내에서 조례로 정한 횟수, 이행할 때까지"],["이행 시","새 이행강제금 부과는 즉시 중지, 이미 부과한 금액은 징수"]]}],"함정":"분쟁 당사자에 허가권자가 들어간 선지는 대상이 아니다. 건축관계자는 건축주·설계자·공사시공자·공사감리자 4자다. 설계자와 공사시공자 간, 공사감리자와 관계전문기술자 간 분쟁은 모두 대상이다."}},{"i":"S2-2-1-공법-32","r":"S2","g":2,"c":2,"n":72,"s":"공법","q":"주택법령상 주택건설사업의 등록과 주택건설사업자에 관한 설명으로 옳은 것은?","b":null,"bs":"없음","img":[],"ch":["지방자치단체가 30호의 단독주택을 건설하는 주택건설사업을 시행하려면 국토교통부장관에게 등록하여야 한다.","지방공사가 20세대의 도시형 생활주택을 건설하는 주택 건설사업을 시행하려면 국토교통부장관에게 등록하여야 한다.","등록사업자는 등록사항에 변경이 있으면 변경 사유가 발생한 날부터 60일 이내에 국토교통부장관에게 신고하여야 한다.","세대수를 증가하지 않는 리모델링주택조합이 그 구성원의 주택을 건설하는 경우에는 한국토지주택공사와 공동으로 사업을 시행하여야 한다.","거짓으로 주택건설사업을 등록하여 그 등록이 말소된 후 2년이 지나지 아니한 자는 주택건설사업의 등록을 할 수 없다."],"a":[5],"L":"공5-1","o":"기출","x":{"한줄":"등록이 말소된 뒤 2년이 지나지 않은 자는 등록 결격이고, 거짓 등록은 필요적 말소 사유다.","근거":[{"법령":"주택법","조문":"제6조제5호","원문":"제8조에 따라 등록이 말소(제6조제1호 및 제2호에 해당하여 말소된 경우는 제외한다)된 후 2년이 지나지 아니한 자"},{"법령":"주택법","조문":"제4조제1항","원문":"연간 대통령령으로 정하는 호수(戶數) 이상의 주택건설사업을 시행하려는 자 … 는 국토교통부장관에게 등록하여야 한다. 다만, 다음 각 호의 사업주체의 경우에는 그러하지 아니하다. 1. 국가ㆍ지방자치단체 2. 한국토지주택공사 3. 지방공사 …"},{"법령":"주택법 시행령","조문":"제14조제1항","원문":"법 제4조제1항 각 호 외의 부분 본문에서 \"대통령령으로 정하는 호수\"란 다음 각 호의 구분에 따른 호수 또는 세대수를 말한다. 1. 단독주택의 경우: 20호 2. 공동주택의 경우: 20세대. 다만, 도시형 생활주택(제10조제2항제1호의 경우를 포함한다)은 30세대로 한다."},{"법령":"주택법 시행령","조문":"제15조제3항","원문":"등록사업자는 등록사항에 변경이 있으면 국토교통부령으로 정하는 바에 따라 변경 사유가 발생한 날부터 30일 이내에 국토교통부장관에게 신고하여야 한다."},{"법령":"주택법","조문":"제5조제2항","원문":"제11조에 따라 설립된 주택조합(세대수를 증가하지 아니하는 리모델링주택조합은 제외한다)이 그 구성원의 주택을 건설하는 경우에는 대통령령으로 정하는 바에 따라 등록사업자(지방자치단체ㆍ한국토지주택공사 및 지방공사를 포함한다)와 공동으로 사업을 시행할 수 있다."}],"선지":[{"번호":1,"판정":"틀림","설명":"국가·지방자치단체·한국토지주택공사·지방공사는 등록 대상에서 빠진다(법 제4조제1항 단서)."},{"번호":2,"판정":"틀림","설명":"지방공사는 등록 제외 사업주체다(법 제4조제1항제3호). 도시형 생활주택의 등록 기준도 20세대가 아니라 30세대다(영 제14조제1항제2호 단서)."},{"번호":3,"판정":"틀림","설명":"변경신고는 변경 사유가 발생한 날부터 30일 이내다(영 제15조제3항)."},{"번호":4,"판정":"틀림","설명":"세대수를 증가하지 않는 리모델링주택조합은 공동사업주체 규정(법 제5조제2항)에서 제외되고, 그 외 조합의 공동시행도 '할 수 있다'이지 의무가 아니다."},{"번호":5,"판정":"옳음","설명":"거짓 등록은 말소 사유이고(법 제8조제1항제1호), 말소 후 2년이 지나지 않으면 등록할 수 없다(법 제6조제5호)."}],"개념":[{"종류":"표","제목":"주택건설사업 등의 등록","머리":["항목","내용","조문"],"행":[["등록 대상","연간 단독주택 20호, 공동주택 20세대(도시형 생활주택 30세대), 대지조성 1만㎡ 이상 시행","법 제4조제1항, 영 제14조"],["등록 제외","국가·지방자치단체, 한국토지주택공사, 지방공사, 주택건설 목적 공익법인, 공동사업 주택조합·고용자","법 제4조제1항 단서"],["등록 기준","자본금 3억원(개인은 자산평가액 6억원) 이상, 건축 분야 기술인 1명 이상, 사무실","영 제14조제3항"],["변경 신고","변경 사유 발생일부터 30일 이내","영 제15조제3항"],["결격사유","미성년자·피성년후견인·피한정후견인, 파산 미복권, 금고 이상 실형 집행 후 2년 미경과, 집행유예 중, 등록말소 후 2년 미경과, 이런 임원이 있는 법인","법 제6조"],["말소·영업정지","1년 이내 영업정지 또는 말소. 거짓 등록과 등록증 대여는 말소하여야 함","법 제8조제1항"]]},{"종류":"비교","제목":"공동사업주체(법 제5조)","왼쪽":{"이름":"공동시행 '할 수 있는' 경우","항목":["토지소유자 + 등록사업자","주택조합 + 등록사업자(지방자치단체·한국토지주택공사·지방공사 포함)","세대수를 증가하지 않는 리모델링주택조합은 이 규정에서 제외"]},"오른쪽":{"이름":"공동시행 '하여야 하는' 경우","항목":["고용자가 근로자의 주택을 건설하는 경우 등록사업자와 공동 시행","공동사업주체 간 업무·비용·책임 분담은 당사자 협약"]}}],"함정":"지방자치단체·지방공사는 규모와 관계없이 등록 대상에서 빠진다. 변경신고 기한은 30일이고 60일이 아니다. 공동시행이 의무인 쪽은 고용자뿐이고 토지소유자·주택조합은 할 수 있다."}},{"i":"S2-2-1-공법-33","r":"S2","g":2,"c":2,"n":73,"s":"공법","q":"주택법령상 지역주택조합의 설립인가신청을 위하여 제출하여야 하는 서류에 해당하지 않는 것은?","b":null,"bs":"없음","img":[],"ch":["창립총회 회의록","조합원 명부","조합원 전원이 자필로 연명한 조합규약","주택단지 전체의 구분소유자와 의결권의 각 3분의 2 이상의 결의를 증명하는 서류","해당 주택건설대지의 15퍼센트 이상에 해당하는 토지의 소유권을 확보하였음을 증명하는 서류"],"a":[4],"L":"공5-1","o":"변형","x":{"한줄":"구분소유자와 의결권의 결의를 증명하는 서류는 리모델링주택조합의 제출 서류이고 지역주택조합에는 해당하지 않는다.","근거":[{"법령":"주택법 시행령","조문":"제20조제1항제1호가목","원문":"지역주택조합 또는 직장주택조합의 경우 1) 창립총회 회의록 2) 조합장선출동의서 3) 조합원 전원이 자필로 연명(連名)한 조합규약 4) 조합원 명부 5) 사업계획서 6) 해당 주택건설대지의 80퍼센트 이상에 해당하는 토지의 사용권원을 확보하였음을 증명하는 서류 7) 해당 주택건설대지의 15퍼센트 이상에 해당하는 토지의 소유권을 확보하였음을 증명하는 서류 8) 그 밖에 국토교통부령으로 정하는 서류"},{"법령":"주택법 시행령","조문":"제20조제1항제1호나목","원문":"리모델링주택조합의 경우 1) 가목1)부터 5)까지의 서류 2) 법 제11조제3항 각 호의 결의를 증명하는 서류 …"},{"법령":"주택법","조문":"제11조제3항","원문":"제1항에 따라 주택을 리모델링하기 위하여 주택조합을 설립하려는 경우에는 … 1. 주택단지 전체를 리모델링하고자 하는 경우에는 주택단지 전체의 구분소유자와 의결권의 각 3분의 2 이상의 결의 및 각 동의 구분소유자와 의결권의 각 과반수의 결의"}],"선지":[{"번호":1,"판정":"-","설명":"창립총회 회의록은 지역·직장·리모델링 조합이 모두 내는 서류다(영 제20조제1항제1호가목1)·나목1))."},{"번호":2,"판정":"-","설명":"조합원 명부도 같은 서류 목록에 있다(영 제20조제1항제1호가목4))."},{"번호":3,"판정":"-","설명":"조합원 전원이 자필로 연명한 조합규약을 낸다(영 제20조제1항제1호가목3))."},{"번호":4,"판정":"-","설명":"이 결의서는 리모델링주택조합에 요구되는 서류다(법 제11조제3항, 영 제20조제1항제1호나목2)). 지역주택조합 서류가 아니다."},{"번호":5,"판정":"-","설명":"지역주택조합은 대지의 15퍼센트 이상 토지소유권과 80퍼센트 이상 사용권원을 증명해야 한다(법 제11조제2항, 영 제20조제1항제1호가목6)·7))."}],"개념":[{"종류":"비교","제목":"설립인가 신청 서류: 지역·직장주택조합과 리모델링주택조합","왼쪽":{"이름":"지역·직장주택조합","항목":["창립총회 회의록","조합장선출동의서","조합원 전원이 자필로 연명한 조합규약","조합원 명부","사업계획서","대지 80퍼센트 이상 사용권원 증명서류","대지 15퍼센트 이상 소유권 증명서류"]},"오른쪽":{"이름":"리모델링주택조합","항목":["창립총회 회의록, 조합장선출동의서, 조합규약, 조합원 명부, 사업계획서","구분소유자·의결권 결의 증명서류","건축기준 완화 적용이 결정된 경우 그 증명서류","사용검사일 또는 사용승인일부터 대수선 10년 등 기간 경과 증명서류"]}},{"종류":"표","제목":"주택조합 설립 요건","머리":["구분","요건","조문"],"행":[["지역·직장주택조합(인가)","대지의 80퍼센트 이상 사용권원 + 15퍼센트 이상 소유권","법 제11조제2항"],["리모델링주택조합(인가) 단지 전체","주택단지 전체의 구분소유자·의결권 각 3분의 2 이상 + 각 동 구분소유자·의결권 각 과반수 결의","법 제11조제3항제1호"],["리모델링주택조합(인가) 동 단위","그 동의 구분소유자·의결권 각 3분의 2 이상 결의","법 제11조제3항제2호"],["국민주택을 공급받기 위한 직장주택조합","인가가 아니라 신고","법 제11조제5항"],["조합원 구성(리모델링 제외)","주택건설 예정 세대수의 50퍼센트 이상 조합원, 조합원 20명 이상. 인가일부터 사용검사일까지 유지","영 제20조제7항"],["총회 직접 출석","원칙 조합원의 100분의 10 이상, 창립총회 등은 100분의 20 이상","영 제20조제4항"],["해산인가 신청","해산 결의 총회의 의결정족수에 해당하는 조합원의 동의를 받은 정산서","영 제20조제1항제3호"]]}],"함정":"리모델링주택조합 서류(구분소유자·의결권 결의 증명)와 해산인가 서류(정산서)를 지역주택조합 설립인가 서류로 넣은 선지가 오답이다. 지역주택조합은 80퍼센트 사용권원과 15퍼센트 소유권을 증명한다."}},{"i":"S2-2-1-공법-34","r":"S2","g":2,"c":2,"n":74,"s":"공법","q":"주택법령상 주택상환사채에 관한 설명으로 틀린 것은?","b":null,"bs":"없음","img":[],"ch":["주택상환사채의 상환기간은 발행일부터 주택의 공급계약체결일까지 3년을 초과할 수 없다.","등록사업자가 주택상환사채를 발행하려면 법인으로서 자본금이 5억원 이상이고 최근 3년간 연평균 주택건설 실적이 300호 이상이어야 하며, 금융기관 또는 주택도시보증공사의 보증을 받아야 한다.","주택상환사채를 발행하려는 자는 주택상환사채발행계획을 수립하여 시ㆍ도지사의 승인을 받아야 한다.","등록사업자의 등록이 말소된 경우에도 그 등록사업자가 발행한 주택상환사채의 효력에는 영향이 없다.","주택상환사채는 해외이주 등 부득이한 사유가 있는 경우를 제외하고는 양도하거나 중도에 해약할 수 없다."],"a":[3],"L":"공5-1","o":"변형","x":{"한줄":"주택상환사채발행계획의 승인권자는 시·도지사가 아니라 국토교통부장관이다.","근거":[{"법령":"주택법","조문":"제80조제2항","원문":"주택상환사채를 발행하려는 자는 대통령령으로 정하는 바에 따라 주택상환사채발행계획을 수립하여 국토교통부장관의 승인을 받아야 한다."},{"법령":"주택법 시행령","조문":"제84조제1항","원문":"법 제80조제1항 후단에서 \"대통령령으로 정하는 기준\"이란 다음 각 호의 기준 모두를 말한다. 1. 법인으로서 자본금이 5억원 이상일 것 2. 「건설산업기본법」 제9조에 따라 건설업 등록을 한 자일 것 3. 최근 3년간 연평균 주택건설 실적이 300호 이상일 것"},{"법령":"주택법 시행령","조문":"제86조","원문":"① 주택상환사채의 상환기간은 3년을 초과할 수 없다. ② 제1항의 상환기간은 주택상환사채 발행일부터 주택의 공급계약체결일까지의 기간으로 한다. ③ 주택상환사채는 양도하거나 중도에 해약할 수 없다. 다만, 해외이주 등 국토교통부령으로 정하는 부득이한 사유가 있는 경우는 예외로 한다."},{"법령":"주택법","조문":"제82조","원문":"제8조에 따라 등록사업자의 등록이 말소된 경우에도 등록사업자가 발행한 주택상환사채의 효력에는 영향을 미치지 아니한다."}],"선지":[{"번호":1,"판정":"옳음","설명":"상환기간은 발행일부터 공급계약체결일까지이고 3년을 넘지 못한다(영 제86조제1항·제2항)."},{"번호":2,"판정":"옳음","설명":"등록사업자의 발행 요건이다. 자본금 5억원 이상 법인, 건설업 등록, 최근 3년 연평균 300호 이상 실적(영 제84조제1항)과 보증(법 제80조제1항 후단)을 갖춘다."},{"번호":3,"판정":"틀림","설명":"발행계획은 국토교통부장관의 승인을 받는다(법 제80조제2항)."},{"번호":4,"판정":"옳음","설명":"등록이 말소돼도 이미 발행한 주택상환사채의 효력은 그대로다(법 제82조)."},{"번호":5,"판정":"옳음","설명":"양도와 중도해약은 원칙적으로 금지되고 해외이주 등 부득이한 사유만 예외다(영 제86조제3항)."}],"개념":[{"종류":"표","제목":"주택상환사채","머리":["항목","내용","조문"],"행":[["발행 주체","한국토지주택공사, 등록사업자","법 제80조제1항"],["등록사업자 요건","법인·자본금 5억원 이상·건설업 등록·최근 3년 연평균 주택건설 300호 이상 + 금융기관 또는 주택도시보증공사 보증","법 제80조제1항, 영 제84조제1항"],["발행 규모(등록사업자)","최근 3년간 연평균 주택건설 호수 이내","영 제84조제2항"],["발행계획 승인","국토교통부장관 승인. 택지 권리 증명서류, 보증서, 발행대행계약서·납입금 관리계약서 첨부(뒤의 서류는 모집공고 전 제출 가능)","법 제80조제2항, 영 제85조제1항"],["증권 형식","기명증권. 명의변경은 사채원부에 취득자의 성명·주소를 기록, 채권에 성명을 기록하지 않으면 대항 불가","법 제81조제2항"],["상환","발행조건에 따라 주택을 건설해 상환, 상환기간 3년 초과 불가","법 제81조제1항, 영 제86조"],["납입금 용도","택지 구입·조성, 주택건설자재 구입, 건설공사비 충당, 장관 승인 비용","영 제87조제1항"],["등록 말소와의 관계","발행한 사채의 효력에 영향 없음","법 제82조"]]},{"종류":"흐름","제목":"주택상환사채 발행 절차","단계":[{"이름":"발행계획 수립·승인","설명":"발행자가 계획을 수립하고 국토교통부장관 승인. 택지 권리 증명서류와 보증서 첨부(법 제80조제2항, 영 제85조제1항)"},{"이름":"관할 시·도지사 통보","설명":"승인한 국토교통부장관이 발행 대상지역 관할 시·도지사에게 내용 통보(영 제85조제3항)"},{"이름":"모집공고안 제출","설명":"모집 전에 모집공고안을 작성해 국토교통부장관에게 제출(영 제85조제4항)"},{"이름":"발행·납입금 관리","설명":"액면 또는 할인 발행, 납입금은 보증기관과 협의한 금융기관에서 관리(영 제83조제1항, 제87조제2항)"},{"이름":"주택 건설·상환","설명":"발행조건에 따라 주택을 건설해 상환. 발행일부터 공급계약체결일까지 3년 이내(법 제81조제1항, 영 제86조)"}]}],"함정":"승인권자는 국토교통부장관이다. 사업계획승인권자(시·도지사, 시장·군수)와는 다르다. 등록사업자의 등록이 말소돼도 이미 발행한 주택상환사채의 효력은 유지된다."}},{"i":"S2-2-1-공법-35","r":"S2","g":2,"c":2,"n":75,"s":"공법","q":"주택법령상 주택의 사용검사 등에 관한 설명으로 틀린 것은?","b":null,"bs":"없음","img":[],"ch":["하나의 주택단지의 입주자를 분할 모집하여 전체 단지의 사용검사를 마치기 전에 입주가 필요한 경우에는 공사가 완료된 주택에 대하여 동별로 사용검사를 받을 수 있다.","사용검사는 사용검사 신청일부터 15일 이내에 하여야 한다.","사업주체는 건축물의 동별로 공사가 완료된 경우로서 사용검사권자의 임시 사용승인을 받은 경우에는 사용검사를 받기 전에 주택을 사용하게 할 수 있다.","사업주체가 파산 등으로 사용검사를 받을 수 없는 경우에는 해당 주택의 시공을 보증한 자, 해당 주택의 시공자 또는 입주예정자는 사용검사를 받을 수 있다.","무단거주가 아닌 입주예정자가 사업주체의 파산 등으로 사용검사를 받을 때에는 입주예정자의 대표회의가 사용검사권자에게 사용검사를 신청할 때 하자보수보증금을 예치하여야 한다."],"a":[4],"L":"공5-2","o":"기출","x":{"한줄":"사업주체가 파산 등으로 사용검사를 받을 수 없을 때 대신 받을 수 있는 자는 시공보증자 또는 입주예정자이고, 시공자는 들어가지 않는다.","근거":[{"법령":"주택법","조문":"제49조제3항","원문":"제1항에도 불구하고 다음 각 호의 구분에 따라 해당 주택의 시공을 보증한 자, 해당 주택의 시공자 또는 입주예정자는 대통령령으로 정하는 바에 따라 사용검사를 받을 수 있다. 1. 사업주체가 파산 등으로 사용검사를 받을 수 없는 경우에는 해당 주택의 시공을 보증한 자 또는 입주예정자 2. 사업주체가 정당한 이유 없이 사용검사를 위한 절차를 이행하지 아니하는 경우에는 해당 주택의 시공을 보증한 자, 해당 주택의 시공자 또는 입주예정자 …"},{"법령":"주택법 시행령","조문":"제54조제2항·제4항","원문":"법 제49조제1항 단서에서 … 2. 하나의 주택단지의 입주자를 분할 모집하여 전체 단지의 사용검사를 마치기 전에 입주가 필요한 경우 … / 제3항에 따른 사용검사는 신청일부터 15일 이내에 하여야 한다."},{"법령":"주택법 시행령","조문":"제56조제1항제1호","원문":"법 제49조제4항 단서에서 \"대통령령으로 정하는 경우\"란 다음 각 호의 구분에 따른 경우를 말한다. 1. 주택건설사업의 경우: 건축물의 동별로 공사가 완료된 경우"},{"법령":"주택법","조문":"제50조제1항","원문":"제49조제3항에 따라 사업주체의 파산 등으로 입주예정자가 사용검사를 받을 때에는 「공동주택관리법」 제38조제1항에도 불구하고 입주예정자의 대표회의가 사용검사권자에게 사용검사를 신청할 때 하자보수보증금을 예치하여야 한다."}],"선지":[{"번호":1,"판정":"옳음","설명":"입주자를 분할 모집해 전체 사용검사 전 입주가 필요한 경우는 동별 사용검사 사유다(영 제54조제2항제2호)."},{"번호":2,"판정":"옳음","설명":"사용검사는 신청일부터 15일 이내에 한다(영 제54조제4항)."},{"번호":3,"판정":"옳음","설명":"동별 공사 완료 시 임시 사용승인을 받으면 사용검사 전에 사용하게 할 수 있다(법 제49조제4항, 영 제56조제1항제1호)."},{"번호":4,"판정":"틀림","설명":"사업주체의 파산 등에는 시공보증자 또는 입주예정자만 사용검사를 받을 수 있다. 시공자까지 들어가는 경우는 사업주체가 정당한 이유 없이 절차를 이행하지 않을 때다(법 제49조제3항제1호·제2호)."},{"번호":5,"판정":"옳음","설명":"입주예정자 대표회의가 사용검사를 신청할 때 하자보수보증금을 예치한다(법 제50조제1항)."}],"개념":[{"종류":"표","제목":"사용검사 정리","머리":["항목","내용","조문"],"행":[["원칙","사업계획승인 사업을 완료하면 시장·군수·구청장의 사용검사(국가·한국토지주택공사 사업 등은 국토교통부장관)","법 제49조제1항"],["분할 사용검사","공구별 분할 승인을 받은 경우 완공된 주택에 공구별로","법 제49조제1항 단서"],["동별 사용검사","승인조건 미이행, 입주자 분할 모집 후 전체 사용검사 전 입주 필요, 승인권자가 필요하다고 인정","영 제54조제2항"],["검사 기한·확인","신청일부터 15일 이내. 사업계획 적합 여부와 사용검사 전 조치할 하자 조치 여부 확인","영 제54조제3항·제4항"],["사용검사 전 사용","금지. 동별 공사 완료 + 임시 사용승인(공동주택은 세대별도 가능)이면 예외","법 제49조제4항, 영 제56조"],["사업주체 파산 등","시공보증자 또는 입주예정자가 사용검사","법 제49조제3항제1호"],["정당한 이유 없는 미이행","시공보증자·시공자·입주예정자가 사용검사. 사용검사권자는 사업주체에게 이유 제출 요청, 사업주체는 7일 이내 의견 통지","법 제49조제3항제2호, 영 제55조제4항"],["입주예정자 사용검사 시","입주예정자 대표회의가 신청 시 하자보수보증금 예치","법 제50조제1항"]]},{"종류":"흐름","제목":"사업주체 파산 시 사용검사","단계":[{"이름":"사업주체 파산 등","설명":"주택건설사업을 계속할 수 없는 상태(영 제55조제1항)"},{"이름":"시공보증자 시공","설명":"시공보증자가 잔여공사를 시공하고 사용검사를 받음(영 제55조제1항 본문)"},{"이름":"보증자 부재","설명":"시공보증자가 없거나 파산 등으로 시공할 수 없으면 입주예정자 대표회의가 시공자를 정해 잔여공사를 시공하고 사용검사(영 제55조제1항 단서)"},{"이름":"하자보수보증금 예치","설명":"입주예정자 대표회의가 신청할 때 예치(법 제50조제1항)"},{"이름":"명의 등재","설명":"시공보증자 또는 세대별 입주자 명의로 건축물관리대장 등재, 소유권보존등기 가능(영 제55조제2항)"}]}],"함정":"사업주체 파산 때 사용검사를 받는 자는 시공보증자·입주예정자이고, 시공자는 정당한 이유 없이 절차를 이행하지 않는 경우에만 들어간다. 15일 이내 검사, 동별 임시 사용승인은 맞는 문장이다."}},{"i":"S2-2-1-공법-36","r":"S2","g":2,"c":2,"n":76,"s":"공법","q":"주택법령상 사업계획승인권자가 사업주체의 신청을 받아 공사의 착수기간을 연장할 수 있는 경우가 아닌 것은? (단, 공사에 착수하지 못할 다른 부득이한 사유는 고려하지 않음.)","b":null,"bs":"없음","img":[],"ch":["사업주체가 시공자 선정을 마치지 못하여 공사 착수가 지연되는 경우","「매장유산 보호 및 조사에 관한 법률」에 따라 국가유산청장의 매장유산 발굴허가를 받은 경우","천재지변으로 인하여 공사 착수가 지연되는 경우","공공택지의 개발·조성을 위한 계획에 포함된 기반시설의 설치 지연으로 공사 착수가 지연되는 경우","해당 사업시행지에 대한 소유권 분쟁(소송절차가 진행 중인 경우)으로 인하여 공사 착수가 지연되는 경우"],"a":[1],"L":"공5-2","o":"변형","x":{"한줄":"착수기간 연장 사유는 영 제31조에 열거되어 있는데, 사업주체 내부의 시공자 선정 지연은 열거에 없다.","근거":[{"법령":"주택법 시행령","조문":"제31조","원문":"법 제16조제1항 각 호 외의 부분 단서에서 \"대통령령으로 정하는 정당한 사유가 있다고 인정하는 경우\"란 다음 각 호의 어느 하나에 해당하는 경우를 말한다. 1. 「매장유산 보호 및 조사에 관한 법률」 제11조에 따라 국가유산청장의 매장유산 발굴허가를 받은 경우 2. 해당 사업시행지에 대한 소유권 분쟁(소송절차가 진행 중인 경우만 해당한다)으로 인하여 공사 착수가 지연되는 경우 3. 법 제15조에 따른 사업계획승인의 조건으로 부과된 사항을 이행함에 따라 공사 착수가 지연되는 경우 4. 천재지변 또는 사업주체에게 책임이 없는 불가항력적인 사유로 인하여 공사 착수가 지연되는 경우 5. 공공택지의 개발ㆍ조성을 위한 계획에 포함된 기반시설의 설치 지연으로 공사 착수가 지연되는 경우 6. 해당 지역의 미분양주택 증가 등으로 사업성이 악화될 우려가 있거나 주택건설경기가 침체되는 등 공사에 착수하지 못할 부득이한 사유가 있다고 사업계획승인권자가 인정하는 경우"},{"법령":"주택법","조문":"제16조제1항","원문":"… 사업계획승인권자는 대통령령으로 정하는 정당한 사유가 있다고 인정하는 경우에는 사업주체의 신청을 받아 그 사유가 없어진 날부터 1년의 범위에서 제1호 또는 제2호가목에 따른 공사의 착수기간을 연장할 수 있다."}],"선지":[{"번호":1,"판정":"-","설명":"시공자 선정 지연은 영 제31조 각 호에 없다. 연장 사유가 아니다."},{"번호":2,"판정":"-","설명":"매장유산 발굴허가를 받은 경우는 영 제31조제1호 사유다."},{"번호":3,"판정":"-","설명":"천재지변은 영 제31조제4호 사유다."},{"번호":4,"판정":"-","설명":"공공택지 기반시설 설치 지연은 영 제31조제5호 사유다."},{"번호":5,"판정":"-","설명":"소유권 분쟁은 소송절차가 진행 중인 경우에 한해 영 제31조제2호 사유가 된다."}],"개념":[{"종류":"표","제목":"공사 착수기간 연장 사유(영 제31조)","머리":["호","사유"],"행":[["1","매장유산 발굴허가(국가유산청장)를 받은 경우"],["2","사업시행지 소유권 분쟁(소송절차가 진행 중인 경우만)"],["3","사업계획승인 조건으로 부과된 사항을 이행하느라 지연되는 경우"],["4","천재지변 또는 사업주체에게 책임 없는 불가항력"],["5","공공택지 개발·조성 계획에 포함된 기반시설의 설치 지연"],["6","미분양 증가·주택건설경기 침체 등으로 승인권자가 부득이하다고 인정하는 경우"]]},{"종류":"흐름","제목":"사업계획승인에서 취소까지","단계":[{"이름":"승인 신청·승인","설명":"정당한 사유가 없으면 신청받은 날부터 60일 이내에 승인 여부 통보(영 제30조제1항). 승인 후 고시(법 제15조제6항)"},{"이름":"공사 시작","설명":"승인받은 날부터 5년 이내. 공구 분할 시 최초 공구 5년, 나머지 공구는 최초 착공신고일부터 2년(법 제16조제1항)"},{"이름":"착수기간 연장","설명":"영 제31조 사유가 있으면 사업주체 신청으로 그 사유가 없어진 날부터 1년 범위에서 연장(법 제16조제1항)"},{"이름":"착공신고 수리","설명":"신고를 받은 날부터 20일 이내 수리 여부 통지(법 제16조제2항·제3항)"},{"이름":"승인 취소","설명":"공사 미착수, 경매·공매로 대지소유권 상실, 부도·파산 등으로 공사 완료 불가 시 취소 가능. 소유권 상실·부도 사유는 정상화 계획을 심사한 뒤 결정(법 제16조제4항·제5항)"}]}],"함정":"연장 사유는 영 제31조의 6가지로 열거되고, 시공자 선정이나 자금 조달 같은 사업주체 내부 사정은 없다. 소유권 분쟁은 소송절차가 진행 중인 경우만 사유가 된다. 연장 기간은 사유가 없어진 날부터 1년 범위다.","개정":"연장 사유 제1호의 근거 법률과 허가권자가 「매장유산 보호 및 조사에 관한 법률」·국가유산청장으로 바뀌었다(영 제31조제1호). 정답은 달라지지 않는다."}},{"i":"S2-2-1-공법-37","r":"S2","g":2,"c":2,"n":77,"s":"공법","q":"주택법령상 입주자저축에 관한 설명으로 틀린 것은?","b":null,"bs":"없음","img":[],"ch":["입주자저축정보를 제공하는 입주자저축취급기관의 장은 입주자저축정보의 명의인이 요구하더라도 입주자저축정보의 제공사실을 통보하지 아니할 수 있다.","국토교통부장관으로부터 ｢주택법｣에 따라 입주자저축정보의 제공 요청을 받은 입주자저축취급기관의 장은 ｢금융실명거래 및 비밀보장에 관한 법률｣에도 불구하고 입주자저축정보를 제공하여야 한다.","“입주자저축”이란 국민주택과 민영주택을 공급받기 위하여 가입하는 주택청약종합저축을 말한다.","국토교통부장관은 입주자저축의 납입방식ㆍ금액 및 조건 등에 필요한 사항에 관한 국토교통부령을 제정하거나 개정할 때에는 재정경제부장관과 미리 협의해야 한다.","입주자저축은 한 사람이 한 계좌만 가입할 수 있다."],"a":[1],"L":"공5-3","o":"기출","x":{"한줄":"정보를 제공한 취급기관은 제공 사실을 명의인에게 알리지 않을 수 있지만, 명의인이 요구하면 반드시 알려야 한다.","근거":[{"법령":"주택법","조문":"제56조제7항","원문":"제6항에 따라 입주자저축정보를 제공한 입주자저축취급기관의 장은 「금융실명거래 및 비밀보장에 관한 법률」 제4조의2제1항에도 불구하고 입주자저축정보의 제공사실을 명의인에게 통보하지 아니할 수 있다. 다만, 입주자저축정보를 제공하는 입주자저축취급기관의 장은 입주자저축정보의 명의인이 요구할 때에는 입주자저축정보의 제공사실을 통보하여야 한다."},{"법령":"주택법","조문":"제56조제2항·제4항·제6항","원문":"제1항에서 \"입주자저축\"이란 국민주택과 민영주택을 공급받기 위하여 가입하는 주택청약종합저축을 말한다. / 입주자저축은 한 사람이 한 계좌만 가입할 수 있다. / 제5항에 따라 입주자저축정보의 제공 요청을 받은 입주자저축취급기관의 장은 「금융실명거래 및 비밀보장에 관한 법률」 제4조에도 불구하고 입주자저축정보를 제공하여야 한다."},{"법령":"주택법 시행령","조문":"제58조의3","원문":"국토교통부장관은 법 제56조제9항에 따라 입주자저축에 관한 국토교통부령을 제정하거나 개정할 때에는 재정경제부장관과 미리 협의해야 한다."}],"선지":[{"번호":1,"판정":"틀림","설명":"명의인이 요구하면 제공 사실을 통보해야 한다. 요구에도 알리지 않아도 된다는 문장은 틀리다(법 제56조제7항 단서)."},{"번호":2,"판정":"옳음","설명":"요청을 받은 취급기관의 장은 금융실명법 제4조에도 불구하고 정보를 제공해야 한다(법 제56조제6항)."},{"번호":3,"판정":"옳음","설명":"입주자저축은 국민주택과 민영주택을 공급받기 위해 가입하는 주택청약종합저축이다(법 제56조제2항)."},{"번호":4,"판정":"옳음","설명":"입주자저축 국토교통부령을 제정·개정할 때의 협의 상대는 재정경제부장관이다(영 제58조의3)."},{"번호":5,"판정":"옳음","설명":"한 사람이 한 계좌만 가입한다(법 제56조제4항)."}],"개념":[{"종류":"표","제목":"입주자저축(법 제56조)","머리":["항목","내용","조문"],"행":[["정의","국민주택과 민영주택을 공급받기 위해 가입하는 주택청약종합저축","제2항"],["취급기관","은행법상 은행 중 국토교통부장관이 지정","제3항"],["가입 제한","한 사람이 한 계좌","제4항"],["정보 제공 요청 업무","입주자자격·재당첨 제한·공급 순위 확인, 기존 가입 여부 확인, 세금우대저축자료 중계, 정보 정확성 유지","제5항"],["제공 의무","요청을 받은 취급기관의 장은 금융실명법 제4조에도 불구하고 제공","제6항"],["명의인 통보","통보하지 않을 수 있으나, 명의인이 요구하면 통보","제7항"],["제공 방식","정보통신망 이용(불가피한 사유는 예외)","제8항"],["부령 제·개정","국토교통부령 제정·개정 시 재정경제부장관과 미리 협의","영 제58조의3"],["목적 외 사용","업무 종사자는 목적 외 사용·제공·누설 금지","제10항"]]},{"종류":"흐름","제목":"입주자저축정보 제공 절차","단계":[{"이름":"정보 제공 요청","설명":"국토교통부장관이 공급 자격 확인 등 법정 업무를 위해 취급기관의 장에게 요청(법 제56조제5항)"},{"이름":"정보 제공","설명":"취급기관의 장이 금융실명법 제4조에도 불구하고 제공. 정보통신망 이용(법 제56조제6항·제8항)"},{"이름":"제공 사실 통보","설명":"명의인에게는 알리지 않을 수 있으나 명의인이 요구하면 통보(법 제56조제7항)"},{"이름":"사용 제한","설명":"업무 목적 외 사용·제공·누설 금지(법 제56조제10항)"}]}],"함정":"제공 사실을 통보하지 않을 수 있다는 원칙에는 단서가 붙는다. 명의인이 요구하면 통보한다. 부령 제·개정 협의 상대는 기획재정부장관이 아니라 재정경제부장관이다.","개정":"입주자저축에 관한 국토교통부령을 제정·개정할 때의 협의 상대가 기획재정부장관에서 재정경제부장관으로 바뀌었다(영 제58조의3, 2025.12.30 개정). 정답은 달라지지 않는다."}},{"i":"S2-2-1-공법-38","r":"S2","g":2,"c":2,"n":78,"s":"공법","q":"주택법령상 분양가상한제가 적용되는 토지임대부 분양주택에 관한 설명으로 옳은 것은?","b":null,"bs":"없음","img":[],"ch":["토지임대부 분양주택 입주자의 거주의무기간은 10년이다.","토지임대부 분양주택의 건축물의 공용부분ㆍ부속건물 및 복리시설은 토지임대부 분양주택 건설사업을 시행하는 자와 분양받은 자들이 공유한다.","토지임대부 분양주택의 분양가격은 건축비로 구성한다.","토지임대부 분양주택의 입주자는 해당 주택의 최초 입주가능일부터 3년 이내에 입주하여야 한다.","토지임대부 분양주택의 토지에 대한 임대차기간은 50년 이내로 한다."],"a":[3],"L":"공5-3","o":"기출","x":{"한줄":"토지임대부 분양주택의 분양가격은 토지는 임대하므로 택지비를 빼고 건축비만으로 구성한다.","근거":[{"법령":"주택법","조문":"제57조제3항","원문":"제1항의 분양가격은 택지비와 건축비로 구성(토지임대부 분양주택의 경우에는 건축비만 해당한다)되며, 구체적인 명세, 산정방식, 감정평가기관 선정방법 등은 국토교통부령으로 정한다."},{"법령":"주택법","조문":"제2조제9호","원문":"\"토지임대부 분양주택\"이란 토지의 소유권은 제15조에 따른 사업계획의 승인을 받아 토지임대부 분양주택 건설사업을 시행하는 자가 가지고, 건축물 및 복리시설(福利施設) 등에 대한 소유권[건축물의 전유부분(專有部分)에 대한 구분소유권은 이를 분양받은 자가 가지고, 건축물의 공용부분ㆍ부속건물 및 복리시설은 분양받은 자들이 공유한다]은 주택을 분양받은 자가 가지는 주택을 말한다."},{"법령":"주택법","조문":"제78조제1항","원문":"토지임대부 분양주택의 토지에 대한 임대차기간은 40년 이내로 한다. 이 경우 토지임대부 분양주택 소유자의 75퍼센트 이상이 계약갱신을 청구하는 경우 40년의 범위에서 이를 갱신할 수 있다."},{"법령":"주택법 시행령","조문":"제60조의2제1항제4호","원문":"토지임대부 분양주택의 경우: 5년"}],"선지":[{"번호":1,"판정":"틀림","설명":"토지임대부 분양주택의 거주의무기간은 5년이다(영 제60조의2제1항제4호)."},{"번호":2,"판정":"틀림","설명":"공용부분·부속건물·복리시설은 분양받은 자들이 공유한다. 건설사업 시행자는 토지 소유권만 가진다(법 제2조제9호)."},{"번호":3,"판정":"옳음","설명":"분양가격은 건축비만으로 구성한다(법 제57조제3항 괄호)."},{"번호":4,"판정":"틀림","설명":"토지임대부 분양주택은 최초 입주가능일에 입주해야 한다. '3년 이내'는 수도권 분양가상한제 적용주택의 입주기한이다(법 제57조의2제1항 본문 괄호)."},{"번호":5,"판정":"틀림","설명":"임대차기간은 40년 이내이고, 소유자 75퍼센트 이상이 청구하면 40년의 범위에서 갱신할 수 있다(법 제78조제1항)."}],"개념":[{"종류":"표","제목":"토지임대부 분양주택 한눈에","머리":["항목","내용","조문"],"행":[["소유 관계","토지는 건설사업 시행자 소유, 전유부분은 분양받은 자, 공용부분·부속건물·복리시설은 분양받은 자들의 공유","법 제2조제9호"],["분양가격","건축비만 해당(택지비 제외)","법 제57조제3항"],["임대차기간","40년 이내, 소유자 75퍼센트 이상 갱신 청구 시 40년 범위에서 갱신","법 제78조제1항"],["지상권","임대차계약을 체결하면 임대차기간 동안 구분소유권 목적의 지상권이 설정된 것으로 봄","법 제78조제2항"],["표준임대차계약서","국토교통부령 표준임대차계약서 사용","법 제78조제3항"],["승계","양수인·상속인이 임대차계약 승계","법 제78조제4항"],["토지임대료","조성원가 또는 감정가격 등 기준, 월별 임대료가 원칙(합의 시 선납·보증금 전환)","법 제78조제5항·제6항"],["입주기한","최초 입주가능일에 입주","법 제57조의2제1항"],["거주의무","거주의무기간 5년. 미이행 시 양도 불가, 부기등기","영 제60조의2제1항제4호, 법 제57조의2제2항·제5항"],["법 적용 순서","이 법에 없는 사항은 집합건물법, 민법 순으로 적용","법 제78조제8항"]]},{"종류":"비교","제목":"분양가격 구성","왼쪽":{"이름":"일반 분양가상한제 적용주택","항목":["택지비 + 건축비","공공택지: 택지 공급가격 + 택지 관련 비용","공공택지 외: 감정평가액 + 택지 관련 비용(매입가격 범위 예외 있음)"]},"오른쪽":{"이름":"토지임대부 분양주택","항목":["건축비만","토지는 임대하므로 택지비 제외","토지는 별도로 토지임대료를 납부"]}}],"함정":"거주의무기간은 5년이고 10년이 아니다. 입주기한 3년은 수도권 분양가상한제 적용주택의 규정이고 토지임대부 분양주택은 최초 입주가능일이다. 임대차기간은 40년 이내이고 공용부분 등은 분양받은 자들이 공유한다."}},{"i":"S2-2-1-공법-39","r":"S2","g":2,"c":2,"n":79,"s":"공법","q":"농지법령상 농지의 전용에 관한 설명으로 옳은 것은?","b":null,"bs":"없음","img":[],"ch":["농지를 농업인 주택의 부지로 전용하려는 자는 농림축산식품부장관의 허가를 받아야 한다.","농지전용허가를 받은 자가 허가를 받은 날부터 1년 이상 대지의 조성 등 농지전용 목적사업에 착수하지 아니하면 허가를 취소하여야 한다.","농지보전부담금은 농지전용허가를 받은 후 목적사업에 착수하기 전까지 납부하면 된다.","대기오염물질배출시설로서 대통령령으로 정하는 시설의 부지로 사용하려는 농지는 계획관리지역에 있더라도 전용허가를 받을 수 없다.","「산지관리법」에 따른 산지전용허가를 받지 아니하고 불법으로 개간한 농지를 산림으로 복구하는 경우에는 농지전용허가를 받지 아니하여도 된다."],"a":[5],"L":"공6-1","o":"변형","x":{"한줄":"산지전용허가 없이 불법으로 개간한 농지를 산림으로 복구하는 경우는 농지전용허가가 필요 없는 예외에 들어 있다.","근거":[{"법령":"농지법","조문":"제34조제1항제4호","원문":"「산지관리법」 제14조에 따른 산지전용허가를 받지 아니하거나 같은 법 제15조에 따른 산지전용신고를 하지 아니하고 불법으로 개간한 농지를 산림으로 복구하는 경우"},{"법령":"농지법","조문":"제35조제1항제1호","원문":"농지를 다음 각 호의 어느 하나에 해당하는 시설의 부지로 전용하려는 자는 대통령령으로 정하는 바에 따라 시장ㆍ군수 또는 자치구구청장에게 신고하여야 한다. 1. 농업인 주택, 어업인 주택, 농축산업용 시설 …, 농수산물 유통ㆍ가공 시설"},{"법령":"농지법","조문":"제39조제1항제4호","원문":"허가를 받거나 신고를 한 후 … 최초로 허가를 받거나 신고를 한 날부터 2년 이상 대지의 조성, 시설물의 설치 등 농지전용 목적사업에 착수하지 아니하거나 농지전용 목적사업에 착수한 후 1년 이상 공사를 중단한 경우 (허가를 취소하거나 … 필요한 조치를 명할 수 있다)"},{"법령":"농지법","조문":"제38조제4항","원문":"농지를 전용하려는 자는 제1항 또는 제2항에 따른 농지보전부담금의 전부 또는 일부를 농지전용허가ㆍ농지전용신고 … 전까지 납부하여야 한다."},{"법령":"농지법","조문":"제37조제1항","원문":"농림축산식품부장관은 제34조제1항에 따른 농지전용허가를 결정할 경우 다음 각 호의 어느 하나에 해당하는 시설의 부지로 사용하려는 농지는 전용을 허가할 수 없다. 다만, 「국토의 계획 및 이용에 관한 법률」에 따른 도시지역ㆍ계획관리지역 및 개발진흥지구에 있는 농지는 다음 각 호의 어느 하나에 해당하는 시설의 부지로 사용하더라도 전용을 허가할 수 있다."}],"선지":[{"번호":1,"판정":"틀림","설명":"농업인 주택 부지는 시장·군수 또는 자치구구청장에게 신고하는 대상이다(법 제35조제1항제1호)."},{"번호":2,"판정":"틀림","설명":"허가일부터 2년 이상 착수하지 않거나 착수 후 1년 이상 공사를 중단한 경우가 사유이고, 허가를 취소할 수 있다. 필요적 취소는 허가를 받은 자가 조치명령을 위반한 경우(제7호)다(법 제39조제1항)."},{"번호":3,"판정":"틀림","설명":"부담금은 농지전용허가·신고 전까지 납부한다(법 제38조제4항)."},{"번호":4,"판정":"틀림","설명":"도시지역·계획관리지역·개발진흥지구의 농지는 이런 시설의 부지로도 허가할 수 있다(법 제37조제1항 단서)."},{"번호":5,"판정":"옳음","설명":"불법 개간 농지를 산림으로 복구하는 경우는 허가 불요 사유다(법 제34조제1항제4호)."}],"개념":[{"종류":"표","제목":"농지 전용·일시사용 제도 비교","머리":["제도","주체·절차","대상","조문"],"행":[["전용허가","농림축산식품부장관 허가","농지를 농업생산·농지개량 외로 사용(허가받은 면적·경계 등 중요 사항 변경 포함)","법 제34조제1항"],["전용협의","주무부장관·지방자치단체장이 농림축산식품부장관과 협의","주거·상업·공업지역 지정, 도시·군계획시설 결정 때 농지가 포함된 경우 등","법 제34조제2항"],["전용신고","시장·군수 또는 자치구구청장에게 신고","농업인·어업인 주택, 농축산업용 시설, 농수산물 유통·가공시설, 어린이놀이터·마을회관 등, 농수산 연구시설·양어장","법 제35조"],["타용도 일시사용허가","시장·군수 또는 자치구구청장 허가, 복구 조건","간이 농수축산업용 시설, 현장사무소·부대시설 설치나 물건 적치·매설 등","법 제36조제1항"],["용도변경 승인","시장·군수 또는 자치구구청장 승인","전용허가·협의·신고로 쓰이는 토지를 정해진 기간 안에 다른 목적으로 사용","법 제40조제1항"],["전용으로 보지 않는 경우","—","농지의 개량시설·농축산물 생산시설·농작업 편의시설 부지","법 제2조제7호 단서"]]},{"종류":"흐름","제목":"전용허가 이후의 의무와 제재","단계":[{"이름":"농지보전부담금 납부","설명":"전용허가·전용신고 전까지 전부 또는 일부를 납부(법 제38조제4항)"},{"이름":"전용허가·신고","설명":"허가 대상은 농림축산식품부장관, 신고 대상은 시장·군수·자치구구청장(법 제34조, 제35조)"},{"이름":"목적사업 착수","설명":"허가·신고일부터 2년 이상 미착수하거나 착수 후 1년 이상 중단하면 취소·조치 사유(법 제39조제1항제4호)"},{"이름":"취소·조치명령","설명":"거짓 허가, 허가조건 위반, 부담금 미납 등은 취소·공사중지 등 가능, 조치명령 위반은 취소하여야 함(법 제39조제1항)"},{"이름":"용도변경","설명":"정해진 기간 안에 다른 목적으로 사용하려면 시장·군수·자치구구청장 승인(법 제40조제1항)"}]}],"함정":"허가와 신고의 주체를 바꾼 선지가 나온다. 농업인 주택·마을회관 부지는 신고(시장·군수·자치구구청장), 일반 전용은 허가(농림축산식품부장관)다. 취소 사유는 2년 미착수와 착수 후 1년 중단이고 취소는 할 수 있다."}},{"i":"S2-2-1-공법-40","r":"S2","g":2,"c":2,"n":80,"s":"공법","q":"농지법령상 농지취득자격증명을 발급받지 아니하고 농지를 취득할 수 있는 경우가 아닌 것은?","b":null,"bs":"없음","img":[],"ch":["시효의 완성으로 농지를 취득하는 경우","공유 농지의 분할로 농지를 취득하는 경우","농업법인의 합병으로 농지를 취득하는 경우","국가나 지방자치단체가 농지를 소유하는 경우","주말ㆍ체험영농을 하려고 농업진흥지역 외의 농지를 소유하는 경우"],"a":[5],"L":"공6-1","o":"기출","x":{"한줄":"주말·체험영농 목적의 농지 소유(법 제6조제2항제3호)는 증명 면제 열거에 없어서 농지취득자격증명과 주말·체험영농계획서가 필요하다.","근거":[{"법령":"농지법","조문":"제8조제1항 단서","원문":"다만, 다음 각 호의 어느 하나에 해당하면 농지취득자격증명을 발급받지 아니하고 농지를 취득할 수 있다. 1. 제6조제2항제1호ㆍ제4호ㆍ제6호ㆍ제8호 또는 제10호(같은 호 바목은 제외한다)에 따라 농지를 취득하는 경우 2. 농업법인의 합병으로 농지를 취득하는 경우 3. 공유 농지의 분할이나 그 밖에 대통령령으로 정하는 원인으로 농지를 취득하는 경우"},{"법령":"농지법 시행령","조문":"제6조제1호","원문":"법 제8조제1항제3호에서 \"그 밖에 대통령령으로 정하는 원인\"이란 다음 각 호의 어느 하나에 해당하는 경우를 말한다. 1. 시효의 완성으로 농지를 취득하는 경우"},{"법령":"농지법","조문":"제8조제2항","원문":"제1항에 따른 농지취득자격증명을 발급받으려는 자는 … 농업경영계획서 또는 주말ㆍ체험영농계획서를 작성하고 … 발급신청을 하여야 한다."}],"선지":[{"번호":1,"판정":"-","설명":"시효 완성 취득은 영 제6조제1호에 따라 증명 면제 사유다(법 제8조제1항제3호)."},{"번호":2,"판정":"-","설명":"공유 농지의 분할은 법 제8조제1항제3호 면제 사유다."},{"번호":3,"판정":"-","설명":"농업법인의 합병은 법 제8조제1항제2호 면제 사유다."},{"번호":4,"판정":"-","설명":"국가나 지방자치단체의 소유는 법 제6조제2항제1호로, 법 제8조제1항제1호 면제 사유다."},{"번호":5,"판정":"-","설명":"법 제6조제2항제3호는 법 제8조제1항제1호의 면제 호수(제1호·제4호·제6호·제8호·제10호)에 없다. 증명을 발급받아야 한다."}],"개념":[{"종류":"표","제목":"농지 소유 예외와 농지취득자격증명(법 제6조제2항, 제8조제1항)","머리":["취득·소유 원인","증명 필요 여부"],"행":[["국가·지방자치단체(제1호)","면제"],["상속(제4호)","면제"],["담보농지 취득(제6호)","면제"],["농지전용협의를 마친 농지(제8호)","면제"],["한국농어촌공사, 농어촌정비법, 매립농지, 토지수용, 장관 협의 공익사업(제10호 가목~마목)","면제"],["농업법인의 합병, 공유 농지의 분할","면제"],["시효 완성, 환매권 행사, 농지이용증진사업 시행계획에 따른 취득(영 제6조)","면제"],["학교·연구기관 등의 시험지·연구지·실습지(제2호)","필요"],["주말·체험영농용 농지(제3호)","필요"],["전용허가·전용신고를 받은 자(제7호)","필요"],["개발사업지구 1천500㎡ 미만 농지(제9호), 평균경사율 15퍼센트 이상 농지(제9호의2)","필요"],["한국토지주택공사의 공공토지비축 농지(제10호 바목)","필요"]]},{"종류":"흐름","제목":"농지취득자격증명 발급 절차","단계":[{"이름":"발급신청","설명":"농지 소재지 시·구·읍·면의 장에게 농업경영계획서 또는 주말·체험영농계획서와 서류를 첨부해 신청. 법 제6조제2항제2호·제7호·제9호·제9호의2·제10호바목은 계획서 제출 면제(법 제8조제2항)"},{"이름":"농지위원회 심의","설명":"농지 투기 성행 우려 지역의 농지 취득자 등은 농지위원회 심의를 거침(법 제8조제3항)"},{"이름":"요건 확인","설명":"취득요건, 소유상한, 계획서의 실현 가능성, 위탁·임대 여부, 최소 면적(일반 1천㎡ 이상, 시설 330㎡ 이상 등)을 확인(영 제7조제2항)"},{"이름":"발급","설명":"신청받은 날부터 7일 이내(계획서 없이 신청하면 4일, 농지위원회 심의 대상은 14일)(법 제8조제4항)"},{"이름":"등기 신청","설명":"소유권 등기 신청 시 농지취득자격증명 첨부(법 제8조제6항)"}]}],"함정":"소유가 허용되는 예외(법 제6조제2항)와 증명이 면제되는 경우(법 제8조제1항)는 같은 목록이 아니다. 주말·체험영농, 학교 실습지, 전용허가를 받은 자 등은 소유가 허용돼도 증명을 받아야 한다."}},{"i":"S2-2-2-공시법-01","r":"S2","g":3,"c":2,"n":1,"s":"공시법","q":"공간정보의 구축 및 관리 등에 관한 법령상 지목의 구분에 관한 설명으로 틀린 것은?","b":null,"bs":"없음","img":[],"ch":["과수류를 집단적으로 재배하는 토지와 이에 접속된 저장고 등 부속시설물의 부지는 과수원으로 하고, 그 토지 안의 주거용 건축물의 부지도 과수원으로 한다.","2필지 이상에 진입하는 통로로 이용되는 토지는 도로로 한다.","국가유산으로 지정된 역사적인 유적·고적·기념물 등을 보존하기 위하여 구획된 토지는 사적지로 하되, 학교용지·공원·종교용지 등 다른 지목으로 된 토지 안의 유적 등을 보호하기 위하여 구획된 토지는 제외한다.","변전소, 송신소, 수신소 및 송유시설 등의 부지는 잡종지로 한다.","석유·석유제품, 액화석유가스, 전기 또는 수소 등의 판매를 위하여 일정한 설비를 갖춘 시설물의 부지는 주유소용지로 한다."],"a":[1],"L":"시1-1","o":"변형","x":{"한줄":"과수원 안에 있는 주거용 건축물의 부지는 과수원이 아니라 대로 한다.","근거":[{"법령":"공간정보의 구축 및 관리 등에 관한 법률 시행령","조문":"제58조제3호","원문":"3. 과수원 사과ㆍ배ㆍ밤ㆍ호두ㆍ귤나무 등 과수류를 집단적으로 재배하는 토지와 이에 접속된 저장고 등 부속시설물의 부지. 다만, 주거용 건축물의 부지는 \"대\"로 한다."},{"법령":"공간정보의 구축 및 관리 등에 관한 법률 시행령","조문":"제58조제14호라목","원문":"라. 2필지 이상에 진입하는 통로로 이용되는 토지"},{"법령":"공간정보의 구축 및 관리 등에 관한 법률 시행령","조문":"제58조제26호","원문":"26. 사적지 국가유산으로 지정된 역사적인 유적ㆍ고적ㆍ기념물 등을 보존하기 위하여 구획된 토지. 다만, 학교용지ㆍ공원ㆍ종교용지 등 다른 지목으로 된 토지에 있는 유적ㆍ고적ㆍ기념물 등을 보호하기 위하여 구획된 토지는 제외한다."},{"법령":"공간정보의 구축 및 관리 등에 관한 법률 시행령","조문":"제58조제28호나목","원문":"나. 변전소, 송신소, 수신소 및 송유시설 등의 부지"},{"법령":"공간정보의 구축 및 관리 등에 관한 법률 시행령","조문":"제58조제12호가목","원문":"가. 석유ㆍ석유제품, 액화석유가스, 전기 또는 수소 등의 판매를 위하여 일정한 설비를 갖춘 시설물의 부지"}],"선지":[{"번호":1,"판정":"틀림","설명":"과수류 재배지와 접속 저장고 등 부속시설물 부지는 과수원이지만, 주거용 건축물의 부지는 대로 한다(영 제58조제3호 단서)."},{"번호":2,"판정":"옳음","설명":"2필지 이상에 진입하는 통로로 이용되는 토지는 도로다(영 제58조제14호라목)."},{"번호":3,"판정":"옳음","설명":"사적지는 국가유산으로 지정된 유적·고적·기념물 보존용 구획 토지다. 학교용지·공원·종교용지 등 다른 지목 토지 안의 유적을 보호하려고 구획한 토지는 사적지에서 빠진다(영 제58조제26호)."},{"번호":4,"판정":"옳음","설명":"변전소·송신소·수신소·송유시설 등의 부지는 잡종지다(영 제58조제28호나목)."},{"번호":5,"판정":"옳음","설명":"석유·석유제품, 액화석유가스, 전기 또는 수소 등의 판매 설비를 갖춘 시설물의 부지는 주유소용지다(영 제58조제12호가목)."}],"개념":[{"종류":"표","제목":"부지 일부가 다른 지목으로 빠지는 지목","머리":["지목","포함되는 토지","제외·예외"],"행":[["과수원","과수류 집단 재배지, 접속 저장고 등 부속시설물 부지","주거용 건축물 부지는 대"],["목장용지","초지 조성 토지, 가축 사육 축사 부지, 접속 부속시설물 부지","주거용 건축물 부지는 대"],["광천지","온수·약수·석유류 등 용출구와 그 유지에 쓰는 부지","송수관·송유관·저장시설 부지"],["염전","소금 채취용 조성 토지, 접속 제염장 등 부속시설물 부지","동력으로 바닷물을 끌어들여 소금을 만드는 공장시설물 부지"],["묘지","매장지, 묘지공원 결정·고시 토지, 봉안시설과 접속 부속시설물 부지","묘지 관리용 건축물 부지는 대"],["주차장","독립적 주차시설 부지, 주차전용 건축물과 접속 부속시설물 부지","노상주차장·부설주차장, 자동차 판매용 물류장·야외전시장"],["사적지","국가유산으로 지정된 유적·고적·기념물 보존용 구획 토지","학교용지·공원·종교용지 등 다른 지목 토지 안의 유적 보호용 구획 토지"],["체육용지","종합운동장·실내체육관·야구장·골프장·스키장·승마장·경륜장 등 부지","정구장·골프연습장·실내수영장·체육도장, 유수를 이용한 요트장·카누장"]]},{"종류":"표","제목":"지목 설정 원칙","머리":["구분","내용","근거"],"행":[["지목의 수","전·답·과수원 등 28종으로 구분","법 제67조제1항"],["필지와 지목","필지마다 하나의 지목을 설정","영 제59조제1항제1호"],["여러 용도로 쓰이는 1필지","주된 용도에 따라 설정","영 제59조제1항제2호"],["일시적·임시적 용도","지목을 변경하지 않음","영 제59조제2항"]]}],"함정":"과수원·목장용지는 저장고·축사 같은 부속시설물까지 같은 지목이지만 주거용 건축물 부지만은 대로 빠진다. 선지 1은 부속시설물 부지가 포함된다는 문장 뒤에 주거용 건축물을 이어 붙였다."}},{"i":"S2-2-2-공시법-02","r":"S2","g":3,"c":2,"n":2,"s":"공시법","q":"공간정보의 구축 및 관리 등에 관한 법령상 토지의 이용 상태와 지목의 연결로 옳은 것은?","b":null,"bs":"없음","img":[],"ch":["온수·약수가 용출되는 용출구와 그 유지에 쓰는 부지, 그 온수를 일정한 장소로 운송하는 송수관의 부지는 모두 광천지로 한다.","천일제염 방식이 아니라 동력으로 바닷물을 끌어들여 소금을 제조하는 공장시설물의 부지는 염전으로 한다.","고속도로의 휴게소 부지는 도로로 한다.","체육시설로서의 영속성과 독립성이 미흡한 실내수영장의 토지는 체육용지로 한다.","「주차장법」에 따른 노상주차장의 부지는 주차장으로 한다."],"a":[3],"L":"시1-1","o":"변형","x":{"한줄":"고속도로의 휴게소 부지는 도로에 해당한다.","근거":[{"법령":"공간정보의 구축 및 관리 등에 관한 법률 시행령","조문":"제58조제14호다목","원문":"다. 고속도로의 휴게소 부지"},{"법령":"공간정보의 구축 및 관리 등에 관한 법률 시행령","조문":"제58조제6호","원문":"6. 광천지 지하에서 온수ㆍ약수ㆍ석유류 등이 용출되는 용출구(湧出口)와 그 유지(維持)에 사용되는 부지. 다만, 온수ㆍ약수ㆍ석유류 등을 일정한 장소로 운송하는 송수관ㆍ송유관 및 저장시설의 부지는 제외한다."},{"법령":"공간정보의 구축 및 관리 등에 관한 법률 시행령","조문":"제58조제7호","원문":"7. 염전 바닷물을 끌어들여 소금을 채취하기 위하여 조성된 토지와 이에 접속된 제염장(製鹽場) 등 부속시설물의 부지. 다만, 천일제염 방식으로 하지 아니하고 동력으로 바닷물을 끌어들여 소금을 제조하는 공장시설물의 부지는 제외한다."},{"법령":"공간정보의 구축 및 관리 등에 관한 법률 시행령","조문":"제58조제23호","원문":"23. 체육용지 국민의 건강증진 등을 위한 체육활동에 적합한 시설과 형태를 갖춘 종합운동장ㆍ실내체육관ㆍ야구장ㆍ골프장ㆍ스키장ㆍ승마장ㆍ경륜장 등 체육시설의 토지와 이에 접속된 부속시설물의 부지. 다만, 체육시설로서의 영속성과 독립성이 미흡한 정구장ㆍ골프연습장ㆍ실내수영장 및 체육도장과 유수(流水)를 이용한 요트장 및 카누장 등의 토지는 제외한다."},{"법령":"공간정보의 구축 및 관리 등에 관한 법률 시행령","조문":"제58조제11호","원문":"11. 주차장 자동차 등의 주차에 필요한 독립적인 시설을 갖춘 부지와 주차전용 건축물 및 이에 접속된 부속시설물의 부지. 다만, 다음 각 목의 어느 하나에 해당하는 시설의 부지는 제외한다. 가. 「주차장법」 제2조제1호가목 및 다목에 따른 노상주차장 및 부설주차장(「주차장법」 제19조제4항에 따라 시설물의 부지 인근에 설치된 부설주차장은 제외한다) 나. 자동차 등의 판매 목적으로 설치된 물류장 및 야외전시장"}],"선지":[{"번호":1,"판정":"틀림","설명":"송수관·송유관 및 저장시설의 부지는 광천지에서 제외된다(영 제58조제6호 단서)."},{"번호":2,"판정":"틀림","설명":"동력으로 바닷물을 끌어들여 소금을 제조하는 공장시설물의 부지는 염전에서 제외된다(영 제58조제7호 단서). 제조업 공장시설물 부지이므로 공장용지에 해당한다."},{"번호":3,"판정":"옳음","설명":"도로에는 고속도로의 휴게소 부지가 포함된다(영 제58조제14호다목)."},{"번호":4,"판정":"틀림","설명":"영속성과 독립성이 미흡한 정구장·골프연습장·실내수영장·체육도장 등은 체육용지에서 제외된다(영 제58조제23호 단서)."},{"번호":5,"판정":"틀림","설명":"「주차장법」상 노상주차장과 부설주차장은 주차장에서 제외된다(영 제58조제11호 단서 가목)."}],"개념":[{"종류":"표","제목":"지목 부호: 앞 글자와 다른 4종","머리":["지목","부호","혼동하기 쉬운 지목"],"행":[["주차장","차","주유소용지(주)와 구별"],["공장용지","장","학교용지(학)·창고용지(창)와 구별"],["하천","천","철도용지(철)·제방(제)과 구별"],["유원지","원","유지(유)·공원(공)과 구별"],["그 밖의 24종","앞 글자 한 자","전·답·과·목·임·광·염·대·학·주·창·도·철·제·구·유·양·수·공·체·종·사·묘·잡"]]},{"종류":"표","제목":"물과 관련된 지목 비교","머리":["지목","토지 내용"],"행":[["답","물을 상시적으로 직접 이용하여 벼·연·미나리·왕골 등을 주로 재배하는 토지"],["하천","자연의 유수가 있거나 있을 것으로 예상되는 토지"],["구거","용수·배수를 위한 인공 수로·둑·부속시설물 부지, 자연의 유수가 있거나 있을 것으로 예상되는 소규모 수로부지"],["유지(溜池)","물이 고이거나 상시 저장된 댐·저수지·소류지·호수·연못 등, 연·왕골 등이 자생하는 배수가 잘 되지 않는 토지"],["양어장","육상에 인공으로 조성된 수산생물 번식·양식 시설 부지와 접속 부속시설물 부지"],["수도용지","물을 정수하여 공급하기 위한 취수·저수·도수·정수·송수·배수 시설 부지와 접속 부속시설물 부지"]]}],"함정":"선지 1, 2, 4, 5는 지목의 본문은 맞고 단서의 제외 부지를 빼 놓은 문장이다. 송수관, 동력식 제염 공장, 실내수영장, 노상주차장이 각각 단서에서 빠진다."}},{"i":"S2-2-2-공시법-03","r":"S2","g":3,"c":2,"n":3,"s":"공시법","q":"공간정보의 구축 및 관리 등에 관한 법령상 지상경계점등록부의 등록사항으로 틀린 것은?","b":null,"bs":"없음","img":[],"ch":["경계점 좌표(경계점좌표등록부 시행지역에 한정한다)","경계점의 사진 파일","지적도면의 색인도와 도곽선의 수치","공부상 지목과 실제 토지이용 지목","경계점 위치 설명도"],"a":[3],"L":"시1-2","o":"변형","x":{"한줄":"지적도면의 색인도와 도곽선의 수치는 지적도·임야도의 등록사항이고 지상경계점등록부의 등록사항이 아니다.","근거":[{"법령":"공간정보의 구축 및 관리 등에 관한 법률","조문":"제65조제2항","원문":"② 지적소관청은 토지의 이동에 따라 지상경계를 새로 정한 경우에는 다음 각 호의 사항을 등록한 지상경계점등록부를 작성ㆍ관리하여야 한다. 1. 토지의 소재 2. 지번 3. 경계점 좌표(경계점좌표등록부 시행지역에 한정한다) 4. 경계점 위치 설명도 5. 그 밖에 국토교통부령으로 정하는 사항"},{"법령":"공간정보의 구축 및 관리 등에 관한 법률 시행규칙","조문":"제60조제2항","원문":"② 법 제65조제2항제5호에서 \"그 밖에 국토교통부령으로 정하는 사항\"이란 다음 각 호의 사항을 말한다. 1. 공부상 지목과 실제 토지이용 지목 2. 경계점의 사진 파일 3. 경계점표지의 종류 및 경계점 위치"},{"법령":"공간정보의 구축 및 관리 등에 관한 법률 시행규칙","조문":"제69조제2항","원문":"② 법 제72조제5호에서 \"그 밖에 국토교통부령으로 정하는 사항\"이란 다음 각 호의 사항을 말한다. 1. 지적도면의 색인도(인접도면의 연결 순서를 표시하기 위하여 기재한 도표와 번호를 말한다) 2. 지적도면의 제명 및 축척 3. 도곽선(圖廓線)과 그 수치"}],"선지":[{"번호":1,"판정":"옳음","설명":"경계점 좌표는 경계점좌표등록부 시행지역에 한정해 등록한다(법 제65조제2항제3호)."},{"번호":2,"판정":"옳음","설명":"경계점의 사진 파일은 규칙으로 정한 등록사항이다(규칙 제60조제2항제2호)."},{"번호":3,"판정":"틀림","설명":"지상경계점등록부 등록사항은 토지의 소재, 지번, 경계점 좌표, 경계점 위치 설명도와 규칙 제60조제2항의 사항이다. 지적도면의 색인도와 도곽선 수치는 지적도·임야도 등록사항이다(규칙 제69조제2항제1호·제3호)."},{"번호":4,"판정":"옳음","설명":"공부상 지목과 실제 토지이용 지목을 함께 적는다(규칙 제60조제2항제1호)."},{"번호":5,"판정":"옳음","설명":"경계점 위치 설명도는 법에서 직접 정한 등록사항이다(법 제65조제2항제4호)."}],"개념":[{"종류":"표","제목":"지상경계점등록부 등록사항","머리":["근거","등록사항"],"행":[["법 제65조제2항제1호","토지의 소재"],["법 제65조제2항제2호","지번"],["법 제65조제2항제3호","경계점 좌표(경계점좌표등록부 시행지역에 한정)"],["법 제65조제2항제4호","경계점 위치 설명도"],["규칙 제60조제2항제1호","공부상 지목과 실제 토지이용 지목"],["규칙 제60조제2항제2호","경계점의 사진 파일"],["규칙 제60조제2항제3호","경계점표지의 종류 및 경계점 위치"]]},{"종류":"표","제목":"지상경계의 결정기준","머리":["상황","결정 위치"],"행":[["연접 토지 간 높낮이 차이 없음","구조물 등의 중앙"],["연접 토지 간 높낮이 차이 있음","구조물 등의 하단부"],["도로·구거 등에 절토된 부분이 있음","경사면의 상단부"],["토지가 해면 또는 수면에 접함","최대만조위 또는 최대만수위가 되는 선"],["공유수면매립지에서 제방 등을 토지에 편입하여 등록","바깥쪽 어깨부분"],["구획 구조물 등의 소유자가 서로 다름","소유권에 따라 결정"]]}],"함정":"지적도면 등록사항(색인도, 제명 및 축척, 도곽선과 수치, 삼각점·지적기준점 위치, 건축물 및 구조물 위치)과 지상경계점등록부 등록사항을 섞어 놓은 문항이다. 도면의 기재 사항은 지상경계점등록부에 오르지 않는다."}},{"i":"S2-2-2-공시법-04","r":"S2","g":3,"c":2,"n":4,"s":"공시법","q":"공간정보의 구축 및 관리 등에 관한 법령상 지적공부와 등록사항의 연결로 옳은 것은?","b":null,"bs":"없음","img":[],"ch":["공유지연명부 - 소유권 지분과 토지소유자가 변경된 날 및 그 원인","임야대장 - 건축물 및 구조물 등의 위치","토지대장 - 경계점 좌표","대지권등록부 - 지목과 면적","지적도 - 토지소유자의 성명과 개별공시지가"],"a":[1],"L":"시1-3","o":"변형","x":{"한줄":"공유지연명부에는 소유권 지분과 토지소유자가 변경된 날 및 그 원인이 등록된다.","근거":[{"법령":"공간정보의 구축 및 관리 등에 관한 법률","조문":"제71조제2항","원문":"② 제1항제5호의 소유자가 둘 이상이면 공유지연명부에 다음 각 호의 사항을 등록하여야 한다. 1. 토지의 소재 2. 지번 3. 소유권 지분 4. 소유자의 성명 또는 명칭, 주소 및 주민등록번호 5. 그 밖에 국토교통부령으로 정하는 사항"},{"법령":"공간정보의 구축 및 관리 등에 관한 법률 시행규칙","조문":"제68조제3항","원문":"③ 법 제71조제2항제5호에서 \"그 밖에 국토교통부령으로 정하는 사항\"이란 다음 각 호의 사항을 말한다. 1. 토지의 고유번호 2. 필지별 공유지연명부의 장번호 3. 토지소유자가 변경된 날과 그 원인"},{"법령":"공간정보의 구축 및 관리 등에 관한 법률 시행규칙","조문":"제69조제2항","원문":"② 법 제72조제5호에서 \"그 밖에 국토교통부령으로 정하는 사항\"이란 다음 각 호의 사항을 말한다. 1. 지적도면의 색인도(인접도면의 연결 순서를 표시하기 위하여 기재한 도표와 번호를 말한다) 2. 지적도면의 제명 및 축척 3. 도곽선(圖廓線)과 그 수치 4. 좌표에 의하여 계산된 경계점 간의 거리(경계점좌표등록부를 갖춰 두는 지역으로 한정한다) 5. 삼각점 및 지적기준점의 위치 6. 건축물 및 구조물 등의 위치"},{"법령":"공간정보의 구축 및 관리 등에 관한 법률","조문":"제73조","원문":"지적소관청은 제86조에 따른 도시개발사업 등에 따라 새로이 지적공부에 등록하는 토지에 대하여는 다음 각 호의 사항을 등록한 경계점좌표등록부를 작성하고 갖춰 두어야 한다. 1. 토지의 소재 2. 지번 3. 좌표"}],"선지":[{"번호":1,"판정":"옳음","설명":"공유지연명부에는 소유권 지분(법 제71조제2항제3호)과 토지소유자가 변경된 날 및 그 원인(규칙 제68조제3항제3호)을 등록한다."},{"번호":2,"판정":"틀림","설명":"건축물 및 구조물 등의 위치는 지적도·임야도의 등록사항이다(규칙 제69조제2항제6호). 임야대장은 소재, 지번, 지목, 면적, 소유자 등을 등록한다(법 제71조제1항)."},{"번호":3,"판정":"틀림","설명":"경계점 좌표는 경계점좌표등록부에 등록한다(법 제73조제3호)."},{"번호":4,"판정":"틀림","설명":"대지권등록부에는 소재, 지번, 대지권 비율, 소유자 등을 등록한다(법 제71조제3항). 지목과 면적은 토지대장·임야대장 사항이다."},{"번호":5,"판정":"틀림","설명":"지적도에는 소재, 지번, 지목, 경계와 규칙 제69조제2항의 사항을 등록한다(법 제72조). 소유자 성명과 개별공시지가는 토지대장·임야대장 사항이다(법 제71조제1항, 규칙 제68조제2항제6호)."}],"개념":[{"종류":"표","제목":"지적공부별 등록사항","머리":["공부","법에서 정한 사항","규칙에서 정한 사항"],"행":[["토지대장·임야대장","소재, 지번, 지목, 면적, 소유자의 성명 또는 명칭·주소·주민등록번호","고유번호, 도면번호·장번호·축척, 토지의 이동사유, 소유자 변경일과 원인, 토지등급 또는 기준수확량등급과 설정·수정 연월일, 개별공시지가와 그 기준일"],["공유지연명부","소재, 지번, 소유권 지분, 소유자의 성명·주소·주민등록번호","고유번호, 필지별 공유지연명부 장번호, 소유자 변경일과 원인"],["대지권등록부","소재, 지번, 대지권 비율, 소유자의 성명·주소·주민등록번호","고유번호, 전유부분의 건물표시, 건물의 명칭, 장번호, 소유자 변경일과 원인, 소유권 지분"],["지적도·임야도","소재, 지번, 지목, 경계","색인도, 제명 및 축척, 도곽선과 수치, 경계점 간 거리(좌표지역), 삼각점·지적기준점 위치, 건축물 및 구조물 등의 위치"],["경계점좌표등록부","소재, 지번, 좌표","고유번호, 지적도면의 번호, 장번호, 부호 및 부호도"]]},{"종류":"표","제목":"등록사항이 올라가는 공부 찾기","머리":["등록사항","공부"],"행":[["면적","토지대장·임야대장"],["개별공시지가와 그 기준일","토지대장·임야대장"],["소유권 지분","공유지연명부, 대지권등록부"],["대지권 비율","대지권등록부"],["경계","지적도·임야도"],["경계점 좌표","경계점좌표등록부"],["소유자 변경일과 원인","토지대장·임야대장·공유지연명부·대지권등록부 모두"]]}],"함정":"등록사항이 비슷한 공부끼리 바꿔 놓은 연결형 문항이다. 소유자 변경일과 원인은 대장·명부 네 가지에 공통이다. 선지 5는 도면인 지적도에 소유자 성명과 개별공시지가를 붙였다."}},{"i":"S2-2-2-공시법-05","r":"S2","g":3,"c":2,"n":5,"s":"공시법","q":"공간정보의 구축 및 관리 등에 관한 법령상 연속지적도의 관리 등에 관한 설명으로 옳은 것은?","b":null,"bs":"없음","img":[],"ch":["지적소관청은 연속지적도의 관리 및 정비에 관한 정책을 수립ㆍ시행하여야 한다.","지적소관청은 지적도ㆍ임야도에 등록된 사항에 대하여 토지의 이동 또는 오류사항을 정비한 때에는 이를 연속지적도에 반영하여야 한다.","시ㆍ도지사는 지적소관청의 연속지적도 정비에 필요한 경비의 전부 또는 일부를 지원하여야 한다.","시ㆍ도지사는 연속지적도를 체계적으로 관리하기 위하여 연속지적도 정보관리체계를 구축ㆍ운영하여야 한다.","시ㆍ도지사는 연속지적도 정보관리체계의 구축ㆍ운영에 관한 업무를 한국국토정보공사에 위탁하여야 한다."],"a":[2],"L":"시1-3","o":"기출","x":{"한줄":"지적도·임야도의 토지이동이나 오류를 정비한 지적소관청은 그 내용을 연속지적도에 반영해야 한다.","근거":[{"법령":"공간정보의 구축 및 관리 등에 관한 법률","조문":"제90조의2제1항·제2항","원문":"① 국토교통부장관은 연속지적도의 관리 및 정비에 관한 정책을 수립ㆍ시행하여야 한다. ② 지적소관청은 지적도ㆍ임야도에 등록된 사항에 대하여 토지의 이동 또는 오류사항을 정비한 때에는 이를 연속지적도에 반영하여야 한다."},{"법령":"공간정보의 구축 및 관리 등에 관한 법률","조문":"제90조의2제3항~제5항","원문":"③ 국토교통부장관은 제2항에 따른 지적소관청의 연속지적도 정비에 필요한 경비의 전부 또는 일부를 지원할 수 있다. ④ 국토교통부장관은 연속지적도를 체계적으로 관리하기 위하여 대통령령으로 정하는 바에 따라 연속지적도 정보관리체계를 구축ㆍ운영할 수 있다. ⑤ 국토교통부장관 또는 지적소관청은 제2항에 따른 연속지적도의 관리ㆍ정비 및 제4항에 따른 연속지적도 정보관리체계의 구축ㆍ운영에 관한 업무를 대통령령으로 정하는 법인, 단체 또는 기관에 위탁할 수 있다. 이 경우 위탁관리에 필요한 경비의 전부 또는 일부를 지원할 수 있다."}],"선지":[{"번호":1,"판정":"틀림","설명":"연속지적도의 관리·정비 정책은 국토교통부장관이 수립·시행한다(법 제90조의2제1항)."},{"번호":2,"판정":"옳음","설명":"지적소관청은 토지의 이동이나 오류를 정비한 때 연속지적도에 반영해야 한다(법 제90조의2제2항)."},{"번호":3,"판정":"틀림","설명":"정비 경비를 지원하는 주체는 국토교통부장관이고, 지원은 의무가 아니라 할 수 있는 사항이다(법 제90조의2제3항)."},{"번호":4,"판정":"틀림","설명":"정보관리체계는 국토교통부장관이 구축·운영할 수 있다(법 제90조의2제4항). 시·도지사의 의무가 아니다."},{"번호":5,"판정":"틀림","설명":"관리·정비와 정보관리체계 운영 업무는 국토교통부장관 또는 지적소관청이 대통령령으로 정하는 법인·단체·기관에 위탁할 수 있다(법 제90조의2제5항). 특정 기관에 위탁하여야 한다고 정하지 않았다."}],"개념":[{"종류":"표","제목":"연속지적도 관리: 주체와 의무 정도","머리":["사항","주체","성격"],"행":[["관리·정비 정책 수립·시행","국토교통부장관","하여야 한다"],["지적도·임야도 정비 사항을 연속지적도에 반영","지적소관청","하여야 한다"],["지적소관청의 정비 경비 지원(전부 또는 일부)","국토교통부장관","할 수 있다"],["연속지적도 정보관리체계 구축·운영","국토교통부장관","할 수 있다"],["관리·정비 및 정보관리체계 운영 업무 위탁","국토교통부장관 또는 지적소관청","할 수 있다"]]},{"종류":"비교","제목":"지적도와 연속지적도","왼쪽":{"이름":"지적도","항목":["법 제2조제19호의 지적공부에 해당","지적측량 등으로 조사한 토지의 표시를 기록","소재, 지번, 지목, 경계를 등록","경계점좌표등록부 시행지역 도면에는 \"이 도면에 의하여 측량을 할 수 없음\"을 적음"]},"오른쪽":{"이름":"연속지적도","항목":["지적공부 열거(법 제2조제19호)에 들지 않음","지적측량 없이 전산화된 지적도·임야도 파일로 경계점들을 연결해 작성","측량에 활용할 수 없는 도면","지적전산자료에 포함(법 제76조제1항)"]}}],"함정":"선지 1, 3, 4, 5는 주체를 시·도지사나 지적소관청으로 바꾸고 재량 규정을 의무로 바꾼 문장이다. 정책 수립·경비 지원·정보관리체계는 국토교통부장관 몫이고, 지적소관청의 일은 정비 사항 반영이다."}},{"i":"S2-2-2-공시법-06","r":"S2","g":3,"c":2,"n":6,"s":"공시법","q":"공간정보의 구축 및 관리 등에 관한 법령상 지적서고의 설치기준 등에 관한 설명으로 틀린 것은?","b":null,"bs":"없음","img":[],"ch":["지적서고는 지적사무를 처리하는 사무실과 연접하여 설치하여야 한다.","지적서고의 골조는 철근콘크리트 이상의 강질로 하고, 바닥과 벽은 단층으로 하되 영구적인 방수설비를 하여야 한다.","창문과 출입문은 2중으로 하되, 바깥쪽 문은 반드시 철제로 하고 안쪽 문은 곤충·쥐 등의 침입을 막을 수 있도록 철망 등을 설치하여야 한다.","지적서고는 제한구역으로 지정하고 출입자를 지적사무담당공무원으로 한정하며, 인화물질의 반입을 금지한다.","지적공부 보관상자는 벽으로부터 15센티미터 이상 띄워야 하며, 높이 10센티미터 이상의 깔판 위에 올려놓아야 한다."],"a":[2],"L":"시1-3","o":"변형","x":{"한줄":"지적서고의 바닥과 벽은 단층이 아니라 2중으로 하고 영구적인 방수설비를 해야 한다.","근거":[{"법령":"공간정보의 구축 및 관리 등에 관한 법률 시행규칙","조문":"제65조제1항·제2항","원문":"① 법 제69조제1항에 따른 지적서고는 지적사무를 처리하는 사무실과 연접(連接)하여 설치하여야 한다.\n1. 골조는 철근콘크리트 이상의 강질로 할 것\n3. 바닥과 벽은 2중으로 하고 영구적인 방수설비를 할 것\n4. 창문과 출입문은 2중으로 하되, 바깥쪽 문은 반드시 철제로 하고 안쪽 문은 곤충ㆍ쥐 등의 침입을 막을 수 있도록 철망 등을 설치할 것"},{"법령":"공간정보의 구축 및 관리 등에 관한 법률 시행규칙","조문":"제65조제3항·제4항","원문":"1. 지적서고는 제한구역으로 지정하고, 출입자를 지적사무담당공무원으로 한정할 것\n2. 지적서고에는 인화물질의 반입을 금지하며, 지적공부, 지적 관계 서류 및 지적측량장비만 보관할 것\n④ 지적공부 보관상자는 벽으로부터 15센티미터 이상 띄워야 하며, 높이 10센티미터 이상의 깔판 위에 올려놓아야 한다."}],"선지":[{"번호":1,"판정":"옳음","설명":"지적서고는 지적사무를 처리하는 사무실과 연접하여 설치한다(규칙 제65조제1항)."},{"번호":2,"판정":"틀림","설명":"바닥과 벽은 2중으로 하고 영구적인 방수설비를 한다(규칙 제65조제2항제3호). 골조를 철근콘크리트 이상의 강질로 하는 부분(제1호)은 맞다."},{"번호":3,"판정":"옳음","설명":"창문과 출입문은 2중으로 하고, 바깥쪽 문은 철제, 안쪽 문은 철망 등을 설치한다(규칙 제65조제2항제4호)."},{"번호":4,"판정":"옳음","설명":"제한구역 지정, 출입자 한정, 인화물질 반입 금지는 관리기준이다(규칙 제65조제3항)."},{"번호":5,"판정":"옳음","설명":"보관상자는 벽에서 15센티미터 이상 띄우고 높이 10센티미터 이상의 깔판 위에 둔다(규칙 제65조제4항)."}],"개념":[{"종류":"표","제목":"지적서고의 설치·관리 기준","머리":["구분","기준"],"행":[["위치","지적사무를 처리하는 사무실과 연접"],["골조","철근콘크리트 이상의 강질"],["바닥·벽","2중, 영구적인 방수설비"],["창문·출입문","2중, 바깥쪽 문은 철제, 안쪽 문은 곤충·쥐 침입을 막는 철망 등"],["온도·습도","자동조절장치 설치, 연중 평균온도 섭씨 20±5도, 연중평균습도 65±5퍼센트"],["전기시설","단독퓨즈 설치, 소화장비 비치"],["출입·보관","제한구역, 출입자는 지적사무담당공무원, 인화물질 반입 금지, 지적공부·지적 관계 서류·지적측량장비만 보관"],["보관상자","벽에서 15센티미터 이상 띄움, 높이 10센티미터 이상 깔판 위"]]},{"종류":"흐름","제목":"지적공부 복구 절차","단계":[{"이름":"복구자료 조사","설명":"지적공부 등본, 측량 결과도, 토지이동정리 결의서, 등기사항증명서, 복제된 지적공부, 법원 확정판결서 등(규칙 제72조)"},{"이름":"조사서·복구자료도 작성","설명":"토지대장·임야대장·공유지연명부는 지적복구자료 조사서, 지적도면은 복구자료도 작성"},{"이름":"복구측량","설명":"면적 증감이 영 제19조제1항제2호가목 허용범위를 초과하거나 복구자료도를 작성할 자료가 없으면 실시"},{"이름":"게시","설명":"복구할 토지의 표시 등을 시·군·구 게시판 및 인터넷 홈페이지에 15일 이상 게시"},{"이름":"이의신청","설명":"게시기간 내에 지적소관청에 신청, 이유 있으면 시정 조치"},{"이름":"복구","설명":"조사서·복구자료도·복구측량 결과도에 따라 대장과 도면 복구"}]}],"함정":"숫자와 재질이 많은 조문이라 한 글자씩 바뀐다. 바닥·벽은 2중, 창문·출입문도 2중이며 바깥쪽이 철제다. 안쪽을 철제로 바꾼 문장이 자주 나온다."}},{"i":"S2-2-2-공시법-07","r":"S2","g":3,"c":2,"n":7,"s":"공시법","q":"공간정보의 구축 및 관리 등에 관한 법령상 등록전환에 따른 면적 결정에 관한 설명으로 옳은 것은?","b":null,"bs":"없음","img":[],"ch":["임야대장의 면적과 등록전환될 면적의 차이가 허용범위 이내이면 임야대장의 면적을 등록전환 면적으로 결정한다.","임야대장의 면적과 등록전환될 면적의 차이가 허용범위 이내이면 등록전환될 면적을 등록전환 면적으로 결정한다.","임야대장의 면적과 등록전환될 면적의 차이가 허용범위를 초과하면 지적측량수행자가 임야대장의 면적 또는 임야도의 경계를 직권으로 정정한다.","임야대장의 면적과 등록전환될 면적의 차이가 허용범위를 초과하면 지적소관청이 시·도지사의 승인을 받아 등록전환될 면적을 등록전환 면적으로 결정한다.","오차의 허용범위를 계산할 때 축척이 3천분의 1인 지역의 축척분모는 3천으로 한다."],"a":[2],"L":"시1-4","o":"변형","x":{"한줄":"차이가 허용범위 이내면 등록전환될 면적이 등록전환 면적이 된다.","근거":[{"법령":"공간정보의 구축 및 관리 등에 관한 법률 시행령","조문":"제19조제1항제1호","원문":"1. 등록전환을 하는 경우 가. 임야대장의 면적과 등록전환될 면적의 오차 허용범위는 다음의 계산식에 따른다. 이 경우 오차의 허용범위를 계산할 때 축척이 3천분의 1인 지역의 축척분모는 6천으로 한다.\n나. 임야대장의 면적과 등록전환될 면적의 차이가 가목의 계산식에 따른 허용범위 이내인 경우에는 등록전환될 면적을 등록전환 면적으로 결정하고, 허용범위를 초과하는 경우에는 임야대장의 면적 또는 임야도의 경계를 지적소관청이 직권으로 정정하여야 한다."}],"선지":[{"번호":1,"판정":"틀림","설명":"허용범위 이내이면 임야대장 면적이 아니라 등록전환될 면적을 등록전환 면적으로 결정한다(영 제19조제1항제1호나목)."},{"번호":2,"판정":"옳음","설명":"허용범위 이내이면 등록전환될 면적이 등록전환 면적이다(영 제19조제1항제1호나목)."},{"번호":3,"판정":"틀림","설명":"허용범위를 초과하면 정정의 주체는 지적측량수행자가 아니라 지적소관청이다(영 제19조제1항제1호나목)."},{"번호":4,"판정":"틀림","설명":"초과하면 시·도지사의 승인으로 면적을 정하는 방식이 아니라, 지적소관청이 임야대장의 면적 또는 임야도의 경계를 직권으로 정정한다(영 제19조제1항제1호나목)."},{"번호":5,"판정":"틀림","설명":"축척이 3천분의 1인 지역의 축척분모는 6천으로 계산한다(영 제19조제1항제1호가목)."}],"개념":[{"종류":"계산","제목":"등록전환 오차 허용면적 계산 예","단계":[{"설명":"허용면적 공식(A: 오차 허용면적, M: 임야도 축척분모, F: 등록전환될 면적)","식":"A = 0.026² × M × √F","값":"A = 0.000676 × M × √F"},{"설명":"축척 1/3000 지역이면 M은 6000, 등록전환될 면적 F를 400㎡로 대입","식":"A = 0.000676 × 6000 × √400","값":"0.000676 × 6000 × 20"},{"설명":"계산","식":"4.056 × 20","값":"A = 81.12㎡"},{"설명":"판단: 임야대장 면적과의 차이가 81.12㎡ 이내면 등록전환될 면적으로 결정, 초과하면 지적소관청이 임야대장 면적 또는 임야도 경계를 직권 정정","식":"차이 ≤ A","값":"등록전환될 면적으로 결정"}]},{"종류":"표","제목":"토지이동 신청 기한","머리":["이동","기한","근거"],"행":[["신규등록","사유 발생일부터 60일 이내","법 제77조"],["등록전환","사유 발생일부터 60일 이내","법 제78조"],["분할(1필지 일부 용도 변경)","용도가 변경된 날부터 60일 이내","법 제79조제2항"],["합병(공동주택 부지·도로·제방·하천·구거·유지 등)","사유 발생일부터 60일 이내","법 제80조제2항"],["지목변경","사유 발생일부터 60일 이내","법 제81조"],["바다로 된 토지의 등록말소","통지를 받은 날부터 90일 이내에 신청하지 않으면 말소","법 제82조제2항"]]}],"함정":"허용범위 초과 때의 처리 주체와 방법을 묻는 선지가 둘이다. 정정은 지적소관청이 직권으로 하고, 시·도지사 승인이나 지적측량수행자 결정은 이 조항에 없다. 선지 5의 3천분의 1 지역 축척분모는 3천이 아니라 6천이다."}},{"i":"S2-2-2-공시법-08","r":"S2","g":3,"c":2,"n":8,"s":"공시법","q":"공간정보의 구축 및 관리 등에 관한 법령상 바다로 된 토지의 등록말소 및 회복 등에 관한 설명으로 틀린 것은?","b":null,"bs":"없음","img":[],"ch":["지적소관청은 지적공부에 등록된 토지가 지형의 변화 등으로 바다로 된 경우로서 원상으로 회복될 수 없거나 다른 지목의 토지로 될 가능성이 없으면, 지적공부에 등록된 토지소유자에게 등록말소 신청을 하도록 통지하여야 한다.","통지를 받은 토지소유자가 통지를 받은 날부터 90일 이내에 등록말소 신청을 하지 아니하면, 지적소관청은 직권으로 그 지적공부의 등록사항을 말소하여야 한다.","지적소관청이 바다로 된 토지의 등록을 말소한 경우에는 지적공부만 정리하고, 토지의 표시 변경에 관한 등기는 촉탁하지 아니한다.","말소한 토지가 지형의 변화 등으로 다시 토지가 되어 회복등록을 하려면, 그 지적측량성과와 등록말소 당시의 지적공부 등 관계 자료에 따라야 한다.","지적소관청이 지적공부의 등록사항을 말소하거나 회복등록한 때에는 토지소유자와 해당 공유수면의 관리청 모두에게 그 정리 결과를 통지하여야 한다."],"a":[3],"L":"시1-4","o":"변형","x":{"한줄":"바다로 된 토지의 등록말소는 지적소관청이 지체 없이 관할 등기관서에 등기를 촉탁하는 사유에 들어간다.","근거":[{"법령":"공간정보의 구축 및 관리 등에 관한 법률","조문":"제82조","원문":"① 지적소관청은 지적공부에 등록된 토지가 지형의 변화 등으로 바다로 된 경우로서 원상(原狀)으로 회복될 수 없거나 다른 지목의 토지로 될 가능성이 없는 경우에는 지적공부에 등록된 토지소유자에게 지적공부의 등록말소 신청을 하도록 통지하여야 한다. ② 지적소관청은 제1항에 따른 토지소유자가 통지를 받은 날부터 90일 이내에 등록말소 신청을 하지 아니하면 대통령령으로 정하는 바에 따라 등록을 말소한다. ③ 지적소관청은 제2항에 따라 말소한 토지가 지형의 변화 등으로 다시 토지가 된 경우에는 대통령령으로 정하는 바에 따라 토지로 회복등록을 할 수 있다."},{"법령":"공간정보의 구축 및 관리 등에 관한 법률 시행령","조문":"제68조","원문":"① 법 제82조제2항에 따라 토지소유자가 등록말소 신청을 하지 아니하면 지적소관청이 직권으로 그 지적공부의 등록사항을 말소하여야 한다. ② 지적소관청은 법 제82조제3항에 따라 회복등록을 하려면 그 지적측량성과 및 등록말소 당시의 지적공부 등 관계 자료에 따라야 한다. ③ 제1항 및 제2항에 따라 지적공부의 등록사항을 말소하거나 회복등록하였을 때에는 그 정리 결과를 토지소유자 및 해당 공유수면의 관리청에 통지하여야 한다."},{"법령":"공간정보의 구축 및 관리 등에 관한 법률","조문":"제89조제1항","원문":"① 지적소관청은 제64조제2항(신규등록은 제외한다), 제66조제2항, 제82조, 제83조제2항, 제84조제2항 또는 제85조제2항에 따른 사유로 토지의 표시 변경에 관한 등기를 할 필요가 있는 경우에는 지체 없이 관할 등기관서에 그 등기를 촉탁하여야 한다. 이 경우 등기촉탁은 국가가 국가를 위하여 하는 등기로 본다."}],"선지":[{"번호":1,"판정":"옳음","설명":"원상회복이 불가능하거나 다른 지목으로 될 가능성이 없는 경우에는 소유자에게 등록말소 신청을 하도록 통지한다(법 제82조제1항)."},{"번호":2,"판정":"옳음","설명":"통지를 받은 날부터 90일 이내에 신청하지 않으면 지적소관청이 직권으로 말소한다(법 제82조제2항, 영 제68조제1항)."},{"번호":3,"판정":"틀림","설명":"법 제82조에 따른 등록말소는 등기촉탁 사유다. 지적소관청은 토지의 표시 변경에 관한 등기를 할 필요가 있으면 지체 없이 관할 등기관서에 촉탁한다(법 제89조제1항)."},{"번호":4,"판정":"옳음","설명":"회복등록은 지적측량성과와 등록말소 당시의 지적공부 등 관계 자료에 따른다(영 제68조제2항)."},{"번호":5,"판정":"옳음","설명":"말소나 회복등록의 정리 결과는 토지소유자와 해당 공유수면의 관리청에 통지한다(영 제68조제3항)."}],"개념":[{"종류":"흐름","제목":"바다로 된 토지의 등록말소와 회복","단계":[{"이름":"등록말소 신청 통지","설명":"지형 변화로 바다가 되고 원상회복이 불가능하거나 다른 지목으로 될 가능성이 없는 경우, 지적소관청이 토지소유자에게 통지(법 제82조제1항)"},{"이름":"토지소유자의 신청","설명":"통지를 받은 날부터 90일 이내"},{"이름":"직권 말소","설명":"90일 이내에 신청하지 않으면 지적소관청이 직권으로 지적공부의 등록사항 말소(영 제68조제1항)"},{"이름":"등기촉탁","설명":"토지의 표시 변경에 관한 등기가 필요하면 지체 없이 관할 등기관서에 촉탁(법 제89조제1항)"},{"이름":"회복등록","설명":"다시 토지가 된 경우 지적측량성과와 말소 당시의 지적공부 등 관계 자료에 따라 회복등록(영 제68조제2항)"},{"이름":"통지","설명":"정리 결과를 토지소유자와 해당 공유수면의 관리청에 통지"}]},{"종류":"표","제목":"지적소관청의 등기촉탁 사유(법 제89조제1항)","머리":["근거","사유","비고"],"행":[["법 제64조제2항","토지소유자 신청 또는 지적소관청 직권에 따른 토지의 이동 결정","신규등록은 촉탁 제외"],["법 제66조제2항","지번 변경","시·도지사 또는 대도시 시장의 승인"],["법 제82조","바다로 된 토지의 등록말소","토지소유자 신청 또는 직권"],["법 제83조제2항","축척변경","확정공고 후 정리"],["법 제84조제2항","지적소관청 직권 등록사항 정정","직권 조사·측량"],["법 제85조제2항","행정구역 개편에 따른 지번 새로 부여","새 지번부여지역의 지번"]]}],"함정":"말소 신청 기간은 통지를 받은 날부터 90일이다. 토지소유자가 신청하지 않으면 지적소관청이 직권으로 말소하고, 이 경우에도 등기촉탁이 따른다."}},{"i":"S2-2-2-공시법-09","r":"S2","g":3,"c":2,"n":9,"s":"공시법","q":"공간정보의 구축 및 관리 등에 관한 법령상 축척변경위원회에 관한 설명으로 틀린 것은?","b":null,"bs":"없음","img":[],"ch":["축척변경위원회는 5명 이상 10명 이하의 위원으로 구성하되, 위원의 3분의 1 이상을 토지소유자로 하여야 한다.","축척변경 시행지역의 토지소유자가 5명 이하일 때에는 토지소유자 전원을 위원으로 위촉하여야 한다.","위원장은 위원 중에서 지적소관청이 지명한다.","축척변경위원회의 회의는 위원장을 포함한 재적위원 과반수의 출석으로 개의하고, 출석위원 과반수의 찬성으로 의결한다.","위원장이 회의를 소집할 때에는 회의 일시·장소 및 심의안건을 회의 개최 5일 전까지 각 위원에게 서면으로 통지하여야 한다."],"a":[1],"L":"시1-4","o":"변형","x":{"한줄":"축척변경위원회 위원 중 토지소유자는 2분의 1 이상이어야 한다. 3분의 1 이상이 아니다.","근거":[{"법령":"공간정보의 구축 및 관리 등에 관한 법률 시행령","조문":"제79조제1항~제3항","원문":"① 축척변경위원회는 5명 이상 10명 이하의 위원으로 구성하되, 위원의 2분의 1 이상을 토지소유자로 하여야 한다. 이 경우 그 축척변경 시행지역의 토지소유자가 5명 이하일 때에는 토지소유자 전원을 위원으로 위촉하여야 한다. ② 위원장은 위원 중에서 지적소관청이 지명한다. ③ 위원은 다음 각 호의 사람 중에서 지적소관청이 위촉한다. 1. 해당 축척변경 시행지역의 토지소유자로서 지역 사정에 정통한 사람 2. 지적에 관하여 전문지식을 가진 사람"},{"법령":"공간정보의 구축 및 관리 등에 관한 법률 시행령","조문":"제81조제2항·제3항","원문":"② 축척변경위원회의 회의는 위원장을 포함한 재적위원 과반수의 출석으로 개의(開議)하고, 출석위원 과반수의 찬성으로 의결한다. ③ 위원장은 축척변경위원회의 회의를 소집할 때에는 회의일시ㆍ장소 및 심의안건을 회의 개최 5일 전까지 각 위원에게 서면으로 통지하여야 한다."}],"선지":[{"번호":1,"판정":"틀림","설명":"위원의 2분의 1 이상을 토지소유자로 한다(영 제79조제1항)."},{"번호":2,"판정":"옳음","설명":"토지소유자가 5명 이하이면 전원을 위원으로 위촉한다(영 제79조제1항 후단)."},{"번호":3,"판정":"옳음","설명":"위원장은 위원 중에서 지적소관청이 지명한다(영 제79조제2항)."},{"번호":4,"판정":"옳음","설명":"재적위원 과반수 출석으로 개의하고 출석위원 과반수 찬성으로 의결한다(영 제81조제2항)."},{"번호":5,"판정":"옳음","설명":"회의 소집 통지는 회의 개최 5일 전까지 서면으로 한다(영 제81조제3항)."}],"개념":[{"종류":"표","제목":"축척변경위원회 구성·운영","머리":["구분","내용","근거"],"행":[["구성","5명 이상 10명 이하, 위원의 2분의 1 이상은 토지소유자","영 제79조제1항"],["토지소유자 5명 이하","토지소유자 전원을 위원으로 위촉","영 제79조제1항"],["위원장","위원 중에서 지적소관청이 지명","영 제79조제2항"],["위원 위촉","시행지역 토지소유자로서 지역 사정에 정통한 사람, 지적에 관하여 전문지식을 가진 사람 중 지적소관청이 위촉","영 제79조제3항"],["개의·의결","재적위원 과반수 출석 개의, 출석위원 과반수 찬성 의결","영 제81조제2항"],["소집 통지","회의 일시·장소·심의안건을 개최 5일 전까지 서면 통지","영 제81조제3항"]]},{"종류":"표","제목":"축척변경 승인과 위원회 의결이 필요한 경우","머리":["구분","절차"],"행":[["원칙","시행지역 토지소유자 3분의 2 이상 동의 → 축척변경위원회 의결 → 시·도지사 또는 대도시 시장 승인(법 제83조제3항)"],["예외 1","합병하려는 토지가 축척이 다른 지적도에 각각 등록되어 있어 축척변경을 하는 경우"],["예외 2","도시개발사업 등 시행지역에서 사업 시행에서 제외된 토지의 축척변경"],["예외의 효과","위원회 의결과 승인 없이 축척변경 가능"],["위원회 심의사항","시행계획, 지번별 제곱미터당 금액 결정과 청산금 산정, 청산금 이의신청, 그 밖에 지적소관청이 부치는 사항(영 제80조)"]]}],"함정":"숫자 한 곳만 바꾼 유형이다. 구성 인원은 5명 이상 10명 이하, 토지소유자 비율은 2분의 1 이상, 소집 통지는 5일 전이다. 소유자가 5명 이하이면 전원이 위원이 된다."}},{"i":"S2-2-2-공시법-10","r":"S2","g":3,"c":2,"n":10,"s":"공시법","q":"공간정보의 구축 및 관리 등에 관한 법령상 지적소관청은 축척변경에 따른 청산금의 납부 및 지급이 완료되었을 때 지체 없이 축척변경의 확정공고를 하여야 한다. 이 경우 확정공고에 포함되어야 할 사항으로 틀린 것은?","b":null,"bs":"없음","img":[],"ch":["토지의 소재 및 지역명","축척변경 지번별 조서","청산금 조서","지적도의 축척","지역별 제곱미터당 금액조서"],"a":[5],"L":"시1-4","o":"기출","x":{"한줄":"확정공고에는 지역별 제곱미터당 금액조서가 들어가지 않는다. 포함 사항은 토지의 소재 및 지역명, 축척변경 지번별 조서, 청산금 조서, 지적도의 축척 네 가지다.","근거":[{"법령":"공간정보의 구축 및 관리 등에 관한 법률 시행규칙","조문":"제92조제1항","원문":"① 영 제78조제1항에 따른 축척변경의 확정공고에는 다음 각 호의 사항이 포함되어야 한다. 1. 토지의 소재 및 지역명 2. 영 제73조에 따른 축척변경 지번별 조서 3. 영 제75조제4항에 따른 청산금 조서 4. 지적도의 축척"},{"법령":"공간정보의 구축 및 관리 등에 관한 법률 시행령","조문":"제78조","원문":"① 청산금의 납부 및 지급이 완료되었을 때에는 지적소관청은 지체 없이 축척변경의 확정공고를 하여야 한다. ② 지적소관청은 제1항에 따른 확정공고를 하였을 때에는 지체 없이 축척변경에 따라 확정된 사항을 지적공부에 등록하여야 한다. ③ 축척변경 시행지역의 토지는 제1항에 따른 확정공고일에 토지의 이동이 있는 것으로 본다."}],"선지":[{"번호":1,"판정":"옳음","설명":"토지의 소재 및 지역명은 확정공고 사항이다(규칙 제92조제1항제1호)."},{"번호":2,"판정":"옳음","설명":"축척변경 지번별 조서는 확정공고 사항이다(규칙 제92조제1항제2호)."},{"번호":3,"판정":"옳음","설명":"청산금 조서는 확정공고 사항이다(규칙 제92조제1항제3호)."},{"번호":4,"판정":"옳음","설명":"지적도의 축척은 확정공고 사항이다(규칙 제92조제1항제4호)."},{"번호":5,"판정":"틀림","설명":"제곱미터당 금액은 축척변경위원회 의결로 지번별로 정해 청산금 산정에 쓴다(영 제75조제2항). 이를 정리한 조서는 확정공고 사항 네 가지에 들지 않는다."}],"개념":[{"종류":"흐름","제목":"축척변경 절차","단계":[{"이름":"승인 신청","설명":"소유자 3분의 2 이상 동의와 위원회 의결을 거쳐 시·도지사 또는 대도시 시장에게 승인 신청(법 제83조제3항, 영 제70조)"},{"이름":"시행공고","설명":"승인을 받으면 지체 없이 20일 이상 공고(영 제71조제1항)"},{"이름":"경계점표지 설치","설명":"토지소유자·점유자가 시행공고일부터 30일 이내 점유 경계에 설치(영 제71조제3항)"},{"이름":"측량과 지번별 조서","설명":"새 축척으로 지번·지목·면적·경계 또는 좌표를 정하고, 시행공고일 현재 면적과 측량 후 면적을 비교한 지번별 조서 작성(영 제72조, 제73조)"},{"이름":"청산금 산정·공고","설명":"위원회 의결로 지번별 제곱미터당 금액 결정, 청산금 조서 작성, 15일 이상 공고(영 제75조)"},{"이름":"납부고지·수령통지","설명":"공고한 날부터 20일 이내, 납부는 고지받은 날부터 6개월 이내, 지급은 통지한 날부터 6개월 이내(영 제76조)"},{"이름":"이의신청","설명":"납부고지·수령통지를 받은 날부터 1개월 이내, 위원회 심의를 거쳐 1개월 이내 결정(영 제77조)"},{"이름":"확정공고","설명":"청산금 납부·지급 완료 후 지체 없이 확정공고, 지적공부 등록, 확정공고일에 토지의 이동이 있는 것으로 봄(영 제78조)"}]},{"종류":"표","제목":"축척변경 확정공고 사항","머리":["확정공고에 포함","확정공고에 포함되지 않음"],"행":[["토지의 소재 및 지역명","지번별 제곱미터당 금액조서"],["축척변경 지번별 조서","축척변경 시행계획"],["청산금 조서","축척변경 승인신청서"],["지적도의 축척","토지소유자 동의서"]]}],"함정":"청산금 조서와 제곱미터당 금액조서는 둘 다 청산금 서류라 한 묶음으로 보인다. 확정공고에 들어가는 서류는 청산금 조서까지다."}},{"i":"S2-2-2-공시법-11","r":"S2","g":3,"c":2,"n":11,"s":"공시법","q":"공간정보의 구축 및 관리 등에 관한 법령상 지적위원회 등에 관한 설명으로 옳은 것은?","b":null,"bs":"없음","img":[],"ch":["지적측량성과에 대하여 다툼이 있는 경우 토지소유자, 이해관계인 또는 지적측량수행자는 관할 시ㆍ도지사를 거쳐 중앙지적위원회에 지적측량 적부심사를 청구할 수 있다.","중앙지적위원회는 지적재조사 기본계획의 수립 및 변경에 관한 사항을 심의ㆍ의결한다.","중앙지적위원회의 위원장이 회의를 소집할 때에는 회의 일시ㆍ장소 및 심의 안건을 회의 7일 전까지 각 위원에게 서면으로 통지하여야 한다.","중앙지적위원회가 현지조사를 위해 필요할 때에는 지적측량수행자에게 그 소속 측량기술자 중 지적기술자를 참여시키도록 요청할 수 있다.","중앙지적위원회로부터 의결서를 받은 국토교통부장관은 그 의결서를 지적소관청에 송부하여야 한다."],"a":[4],"L":"시1-5","o":"기출","x":{"한줄":"중앙지적위원회는 현지조사 때 지적측량수행자에게 소속 지적기술자를 참여시키도록 요청할 수 있다.","근거":[{"법령":"공간정보의 구축 및 관리 등에 관한 법률","조문":"제29조제1항","원문":"① 토지소유자, 이해관계인 또는 지적측량수행자는 지적측량성과에 대하여 다툼이 있는 경우에는 대통령령으로 정하는 바에 따라 관할 시ㆍ도지사를 거쳐 지방지적위원회에 지적측량 적부심사를 청구할 수 있다."},{"법령":"공간정보의 구축 및 관리 등에 관한 법률","조문":"제28조제1항","원문":"① 다음 각 호의 사항을 심의ㆍ의결하기 위하여 국토교통부에 중앙지적위원회를 둔다. 1. 지적 관련 정책 개발 및 업무 개선 등에 관한 사항 2. 지적측량기술의 연구ㆍ개발 및 보급에 관한 사항 3. 제29조제6항에 따른 지적측량 적부심사(適否審査)에 대한 재심사(再審査) 4. 제39조에 따른 측량기술자 중 지적분야 측량기술자(이하 \"지적기술자\"라 한다)의 양성에 관한 사항 5. 제42조에 따른 지적기술자의 업무정지 처분 및 징계요구에 관한 사항"},{"법령":"공간정보의 구축 및 관리 등에 관한 법률 시행령","조문":"제21조제5항","원문":"⑤ 위원장이 중앙지적위원회의 회의를 소집할 때에는 회의 일시ㆍ장소 및 심의 안건을 회의 5일 전까지 각 위원에게 서면으로 통지하여야 한다."},{"법령":"공간정보의 구축 및 관리 등에 관한 법률 시행령","조문":"제22조","원문":"제21조제4항에 따라 중앙지적위원회가 현지조사를 하려는 경우에는 관계 공무원을 지정하여 지적측량 및 자료조사 등 현지조사를 하고 그 결과를 보고하게 할 수 있으며, 필요할 때에는 법 제24조제1항 각 호의 어느 하나에 해당하는 자(이하 \"지적측량수행자\"라 한다)에게 그 소속 측량기술자 중 지적분야 측량기술자(이하 \"지적기술자\"라 한다)를 참여시키도록 요청할 수 있다."},{"법령":"공간정보의 구축 및 관리 등에 관한 법률","조문":"제29조제8항","원문":"⑧ 제7항에 따라 중앙지적위원회로부터 의결서를 받은 국토교통부장관은 그 의결서를 관할 시ㆍ도지사에게 송부하여야 한다."}],"선지":[{"번호":1,"판정":"틀림","설명":"적부심사는 관할 시·도지사를 거쳐 지방지적위원회에 청구한다(법 제29조제1항). 중앙지적위원회는 재심사를 맡는다."},{"번호":2,"판정":"틀림","설명":"중앙지적위원회 심의·의결사항은 지적 관련 정책 개발 및 업무 개선, 지적측량기술의 연구·개발 및 보급, 적부심사 재심사, 지적기술자 양성, 지적기술자의 업무정지 처분 및 징계요구다(법 제28조제1항). 지적재조사 기본계획은 들어 있지 않다."},{"번호":3,"판정":"틀림","설명":"회의 소집 통지는 회의 5일 전까지다(영 제21조제5항)."},{"번호":4,"판정":"옳음","설명":"현지조사를 하려면 관계 공무원을 지정하고, 필요하면 지적측량수행자에게 소속 지적기술자를 참여시키도록 요청할 수 있다(영 제22조)."},{"번호":5,"판정":"틀림","설명":"중앙지적위원회 의결서를 받은 국토교통부장관은 이를 관할 시·도지사에게 송부한다(법 제29조제8항). 지적소관청에 보내는 사람은 시·도지사다(제9항)."}],"개념":[{"종류":"흐름","제목":"지적측량 적부심사와 재심사","단계":[{"이름":"적부심사 청구","설명":"토지소유자·이해관계인·지적측량수행자가 지적측량성과에 다툼이 있을 때 시·도지사를 거쳐 지방지적위원회에 청구(법 제29조제1항)"},{"이름":"조사·회부","설명":"시·도지사가 30일 이내에 측량 경위와 성과, 토지이동·소유권 변동 연혁, 현황 실측도를 조사해 지방지적위원회에 회부(법 제29조제2항)"},{"이름":"심의·의결","설명":"회부받은 날부터 60일 이내, 부득이하면 의결로 30일 이내 한 번만 연장(법 제29조제3항)"},{"이름":"의결서 통지","설명":"의결서를 받은 시·도지사가 7일 이내에 청구인과 이해관계인에게 통지(법 제29조제5항)"},{"이름":"재심사 청구","설명":"불복하면 의결서를 받은 날부터 90일 이내에 국토교통부장관을 거쳐 중앙지적위원회에 청구(법 제29조제6항)"},{"이름":"정리","설명":"재심사 청구가 없거나 중앙위 의결이 있으면 지적소관청이 의결서 내용에 따라 지적공부 정정 또는 측량성과 수정(법 제29조제9항·제10항)"}]},{"종류":"표","제목":"중앙지적위원회 구성·회의","머리":["구분","내용","근거"],"행":[["구성","위원장·부위원장 포함 5명 이상 10명 이하","영 제20조제1항"],["위원장·부위원장","국토교통부 지적업무 담당 국장, 담당 과장","영 제20조제2항"],["위원 임기","위원장·부위원장 제외 위원은 2년","영 제20조제4항"],["개의·의결","재적위원 과반수 출석, 출석위원 과반수 찬성","영 제21조제3항"],["소집 통지","회의 5일 전까지 서면","영 제21조제5항"],["재심사 사안 관련 위원","그 안건의 심의·의결에 참석 불가","영 제21조제6항"]]}],"함정":"적부심사는 지방지적위원회가 먼저 맡고, 중앙지적위원회는 불복 재심사를 맡는다. 청구 경로가 시·도지사를 거치는 점은 같아 보여서 선지 1의 '중앙'만 바꿔 놓은 문장을 놓친다. 선지 3의 날짜 5일, 선지 5의 송부 대상도 자주 바뀐다."}},{"i":"S2-2-2-공시법-12","r":"S2","g":3,"c":2,"n":12,"s":"공시법","q":"공간정보의 구축 및 관리 등에 관한 법령상 중앙지적위원회의 심의·의결사항으로 틀린 것은?","b":null,"bs":"없음","img":[],"ch":["측량기술자 중 지적분야 측량기술자(지적기술자)의 양성에 관한 사항","지적측량기술의 연구ㆍ개발 및 보급에 관한 사항","지적측량성과에 다툼이 있어 청구된 지적측량 적부심사 청구사항(최초 심사)","지적측량 적부심사에 대한 재심사","지적기술자의 업무정지 처분 및 징계요구에 관한 사항"],"a":[3],"L":"시1-5","o":"변형","x":{"한줄":"최초의 적부심사 청구사항은 시·도에 두는 지방지적위원회가 심의·의결한다.","근거":[{"법령":"공간정보의 구축 및 관리 등에 관한 법률","조문":"제28조제1항·제2항","원문":"① 다음 각 호의 사항을 심의ㆍ의결하기 위하여 국토교통부에 중앙지적위원회를 둔다. 1. 지적 관련 정책 개발 및 업무 개선 등에 관한 사항 2. 지적측량기술의 연구ㆍ개발 및 보급에 관한 사항 3. 제29조제6항에 따른 지적측량 적부심사(適否審査)에 대한 재심사(再審査) 4. 제39조에 따른 측량기술자 중 지적분야 측량기술자(이하 \"지적기술자\"라 한다)의 양성에 관한 사항 5. 제42조에 따른 지적기술자의 업무정지 처분 및 징계요구에 관한 사항\n② 제29조에 따른 지적측량에 대한 적부심사 청구사항을 심의ㆍ의결하기 위하여 특별시ㆍ통합특별시ㆍ광역시ㆍ특별자치시ㆍ도 또는 특별자치도(이하 \"시ㆍ도\"라 한다)에 지방지적위원회를 둔다."}],"선지":[{"번호":1,"판정":"옳음","설명":"지적기술자의 양성에 관한 사항은 중앙지적위원회 소관이다(법 제28조제1항제4호)."},{"번호":2,"판정":"옳음","설명":"지적측량기술의 연구·개발 및 보급에 관한 사항은 중앙지적위원회 소관이다(법 제28조제1항제2호)."},{"번호":3,"판정":"틀림","설명":"적부심사 청구사항은 시·도에 두는 지방지적위원회가 심의·의결한다(법 제28조제2항)."},{"번호":4,"판정":"옳음","설명":"적부심사에 대한 재심사는 중앙지적위원회가 한다(법 제28조제1항제3호, 제29조제6항)."},{"번호":5,"판정":"옳음","설명":"지적기술자의 업무정지 처분 및 징계요구에 관한 사항은 중앙지적위원회 소관이다(법 제28조제1항제5호)."}],"개념":[{"종류":"비교","제목":"중앙지적위원회와 지방지적위원회","왼쪽":{"이름":"중앙지적위원회(국토교통부)","항목":["지적 관련 정책 개발 및 업무 개선","지적측량기술의 연구·개발 및 보급","적부심사에 대한 재심사","지적기술자 양성","지적기술자의 업무정지 처분 및 징계요구","위원장은 국토교통부 지적업무 담당 국장"]},"오른쪽":{"이름":"지방지적위원회(시·도)","항목":["지적측량 적부심사 청구사항 심의·의결(법 제28조제2항)","청구는 시·도지사를 거쳐 제출","시·도지사가 30일 이내 조사 후 회부","회부받은 날부터 60일 이내 의결, 30일 이내 한 번 연장 가능","구성과 회의는 중앙지적위원회 규정을 준용(영 제23조)"]}},{"종류":"표","제목":"적부심사 관련 기간","머리":["단계","기간","근거"],"행":[["시·도지사의 조사·회부","청구를 받은 날부터 30일 이내","법 제29조제2항"],["지방지적위원회 의결","회부받은 날부터 60일 이내, 30일 이내 한 번 연장","법 제29조제3항"],["의결서 통지","시·도지사가 의결서를 받은 날부터 7일 이내","법 제29조제5항"],["재심사 청구","의결서를 받은 날부터 90일 이내","법 제29조제6항"]]}],"함정":"적부심사 청구사항은 지방지적위원회가 먼저 심의하고, 중앙지적위원회는 그 의결에 불복한 재심사만 맡는다. 선지 3과 선지 4는 둘 다 적부심사라는 말이 붙지만 맡는 위원회가 다르다."}},{"i":"S2-2-2-공시법-13","r":"S2","g":3,"c":2,"n":13,"s":"공시법","q":"공간정보의 구축 및 관리 등에 관한 법령상 지적측량이 필요한 경우 중 토지소유자 등 이해관계인이 지적측량수행자에게 지적측량을 의뢰할 수 없는 것은?","b":null,"bs":"없음","img":[],"ch":["「지적재조사에 관한 특별법」에 따른 지적재조사사업으로 토지의 이동이 있는 경우","지적공부를 복구하는 경우","도시개발사업 등의 시행지역에서 토지의 이동이 있는 경우","지적공부의 등록사항을 정정하는 경우","경계점을 지상에 복원하는 경우"],"a":[1],"L":"시1-5","o":"변형","x":{"한줄":"지적재조사사업으로 인한 토지 이동은 법 제24조제1항의 의뢰 대상에서 빠진다(제23조제1항제3호자목 제외).","근거":[{"법령":"공간정보의 구축 및 관리 등에 관한 법률","조문":"제23조제1항","원문":"① 다음 각 호의 어느 하나에 해당하는 경우에는 지적측량을 하여야 한다. 1. 제7조제1항제3호에 따른 지적기준점을 정하는 경우 2. 제25조에 따라 지적측량성과를 검사하는 경우 3. 다음 각 목의 어느 하나에 해당하는 경우로서 측량을 할 필요가 있는 경우 가. 제74조에 따라 지적공부를 복구하는 경우 나. 제77조에 따라 토지를 신규등록하는 경우 다. 제78조에 따라 토지를 등록전환하는 경우 라. 제79조에 따라 토지를 분할하는 경우 마. 제82조에 따라 바다가 된 토지의 등록을 말소하는 경우 바. 제83조에 따라 축척을 변경하는 경우 사. 제84조에 따라 지적공부의 등록사항을 정정하는 경우 아. 제86조에 따른 도시개발사업 등의 시행지역에서 토지의 이동이 있는 경우 자. 「지적재조사에 관한 특별법」에 따른 지적재조사사업에 따라 토지의 이동이 있는 경우 4. 경계점을 지상에 복원하는 경우 5. 그 밖에 대통령령으로 정하는 경우"},{"법령":"공간정보의 구축 및 관리 등에 관한 법률","조문":"제24조제1항","원문":"① 토지소유자 등 이해관계인은 제23조제1항제1호 및 제3호(자목은 제외한다)부터 제5호까지의 사유로 지적측량을 할 필요가 있는 경우에는 다음 각 호의 어느 하나에 해당하는 자(이하 \"지적측량수행자\"라 한다)에게 지적측량을 의뢰하여야 한다."}],"선지":[{"번호":1,"판정":"틀림","설명":"지적재조사사업에 따른 토지 이동은 법 제23조제1항제3호자목이다. 법 제24조제1항이 자목을 의뢰 대상에서 제외한다."},{"번호":2,"판정":"옳음","설명":"지적공부 복구는 제23조제1항제3호가목이어서 의뢰 대상이다(법 제24조제1항)."},{"번호":3,"판정":"옳음","설명":"도시개발사업 등 시행지역의 토지 이동은 제3호아목이고 의뢰 대상이다."},{"번호":4,"판정":"옳음","설명":"등록사항 정정은 제3호사목이고 의뢰 대상이다."},{"번호":5,"판정":"옳음","설명":"경계점을 지상에 복원하는 경우는 제4호이고 의뢰 대상이다."}],"개념":[{"종류":"표","제목":"지적측량을 하여야 하는 경우(법 제23조제1항)","머리":["구분","사유","의뢰 대상"],"행":[["제1호","지적기준점을 정하는 경우","의뢰 대상"],["제2호","지적측량성과를 검사하는 경우","의뢰 대상 아님"],["제3호 가~마","복구, 신규등록, 등록전환, 분할, 바다 등록말소","의뢰 대상"],["제3호 바~사","축척변경, 등록사항 정정","의뢰 대상"],["제3호 아","도시개발사업 등 시행지역의 토지 이동","의뢰 대상"],["제3호 자","지적재조사사업에 따른 토지 이동","의뢰 대상 아님"],["제4호","경계점을 지상에 복원하는 경우","의뢰 대상"],["제5호","지상건축물 등의 현황을 지적도·임야도 경계와 대비해 표시하는 데 필요한 경우(지적현황측량, 영 제18조)","의뢰 대상"]]},{"종류":"표","제목":"지적측량 기간(규칙 제25조)","머리":["구분","기간"],"행":[["측량기간","5일"],["측량검사기간","4일"],["지적기준점을 설치하는 측량·검사, 기준점 15점 이하","4일"],["지적기준점이 15점을 초과","4일에 15점을 초과하는 4점마다 1일 가산"],["의뢰인과 수행자가 합의하여 따로 정한 경우","합의한 기간, 전체의 4분의 3은 측량기간, 4분의 1은 측량검사기간"],["수행계획서","의뢰를 받은 다음 날까지 지적소관청에 제출"]]}],"함정":"의뢰 대상에서 빠지는 토지 이동 사유는 지적재조사사업이다. 지적측량성과 검사(제23조제1항제2호)도 법 제24조제1항의 의뢰 사유에 들어 있지 않다. 이 검사는 지적측량수행자가 측량한 뒤 시·도지사, 대도시 시장 또는 지적소관청에게 받는 절차다(법 제25조)."}},{"i":"S2-2-2-공시법-14","r":"S2","g":3,"c":2,"n":14,"s":"공시법","q":"부동산등기법상 등기의 당사자능력에 관한 설명으로 틀린 것은?","b":null,"bs":"없음","img":[],"ch":["법인 아닌 사단(社團)은 그 사단 명의로 대표자가 등기를 신청할 수 있다.","시설물로서의 학교는 학교 명의로 등기할 수 없다.","행정조직인 읍, 면은 등기의 당사자능력이 없다.","민법상 조합을 채무자로 표시하여 조합재산에 근저당권설정등기를 할 수 있다.","외국인은 법령이나 조약의 제한이 없는 한 자기 명의로 등기신청을 하고 등기명의인이 될 수 있다."],"a":[4],"L":"시2-1","o":"기출","x":{"한줄":"민법상 조합은 등기의 당사자능력이 없어서 조합 명의나 조합을 채무자로 하는 등기를 할 수 없다.","근거":[{"법령":"부동산등기법","조문":"제26조","원문":"① 종중(宗中), 문중(門中), 그 밖에 대표자나 관리인이 있는 법인 아닌 사단(社團)이나 재단(財團)에 속하는 부동산의 등기에 관하여는 그 사단이나 재단을 등기권리자 또는 등기의무자로 한다. ② 제1항의 등기는 그 사단이나 재단의 명의로 그 대표자나 관리인이 신청한다."},{"이론":"등기 당사자능력(등기선례·예규)","내용":"권리능력이 있는 자연인·법인과, 법 제26조의 법인 아닌 사단·재단은 등기명의인이 된다. 시설물인 학교, 행정조직인 읍·면·동, 민법상 조합은 당사자능력이 없고, 조합재산은 조합원 전원의 합유로 등기한다."}],"선지":[{"번호":1,"판정":"옳음","설명":"대표자나 관리인이 있는 법인 아닌 사단은 그 사단 명의로 대표자가 신청한다(법 제26조)."},{"번호":2,"판정":"옳음","설명":"시설물로서의 학교는 권리의 주체가 아니다. 학교를 설립한 학교법인 등의 명의로 등기한다."},{"번호":3,"판정":"옳음","설명":"읍·면은 독립한 권리주체가 아닌 행정조직이다. 지방자치단체 명의로 등기한다."},{"번호":4,"판정":"틀림","설명":"민법상 조합은 법인격이 없고 법인 아닌 사단에도 해당하지 않아 당사자능력이 없다. 조합재산은 조합원 전원의 합유로 등기한다."},{"번호":5,"판정":"옳음","설명":"외국인도 법령이나 조약의 제한이 없으면 등기명의인이 된다."}],"개념":[{"종류":"표","제목":"등기 당사자능력 정리","머리":["대상","당사자능력","등기 방법"],"행":[["자연인(내국인·외국인)","있음","자기 명의. 외국인은 법령·조약의 제한 범위에서"],["법인","있음","법인 명의"],["법인 아닌 사단·재단","있음(대표자 또는 관리인이 있는 경우)","사단·재단 명의, 대표자·관리인이 신청(법 제26조)"],["시설물로서의 학교","없음","학교법인 등 설립 주체 명의"],["행정조직인 읍·면·동","없음","지방자치단체 명의"],["민법상 조합","없음","조합원 전원의 합유 명의"]]},{"종류":"표","제목":"법인 아닌 사단·재단의 등기신청 첨부정보(규칙 제48조)","머리":["첨부정보","비고"],"행":[["정관이나 그 밖의 규약","항상"],["대표자나 관리인임을 증명하는 정보","등기되어 있는 대표자·관리인이 신청하면 제외"],["「민법」 제276조제1항의 결의가 있음을 증명하는 정보","법인 아닌 사단이 등기의무자인 경우에 한정"],["대표자나 관리인의 주소 및 주민등록번호를 증명하는 정보","항상"]]}],"함정":"법인 아닌 사단은 사단 명의로 등기하지만 민법상 조합은 당사자능력이 없다. 조합재산은 조합원 전원의 합유로 등기한다. 이 차이가 선지 1과 선지 4의 갈림이다."}},{"i":"S2-2-2-공시법-15","r":"S2","g":3,"c":2,"n":15,"s":"공시법","q":"부동산등기용등록번호에 관한 설명으로 옳은 것은?","b":null,"bs":"없음","img":[],"ch":["국가·지방자치단체·국제기관 및 외국정부의 등록번호는 대법원장이 지정·고시한다.","법인의 등록번호는 대법원 소재지를 관할하는 등기소의 등기관이 부여한다.","외국인의 등록번호는 체류지를 관할하는 등기소의 등기관이 부여한다.","주민등록번호가 없는 재외국민의 등록번호는 체류지를 관할하는 시장·군수 또는 구청장이 부여한다.","법인 아닌 사단이나 재단의 등록번호는 시장·군수 또는 구청장이 부여한다."],"a":[5],"L":"시2-1","o":"변형","x":{"한줄":"법인 아닌 사단이나 재단의 등록번호는 시장·군수 또는 구청장이 부여한다.","근거":[{"법령":"부동산등기법","조문":"제49조","원문":"① 제48조제2항에 따른 부동산등기용등록번호(이하 \"등록번호\"라 한다)는 다음 각 호의 방법에 따라 부여한다. 1. 국가ㆍ지방자치단체ㆍ국제기관 및 외국정부의 등록번호는 국토교통부장관이 지정ㆍ고시한다. 2. 주민등록번호가 없는 재외국민의 등록번호는 대법원 소재지 관할 등기소의 등기관이 부여하고, 법인의 등록번호는 주된 사무소(회사의 경우에는 본점, 외국법인의 경우에는 국내에 최초로 설치 등기를 한 영업소나 사무소를 말한다) 소재지 관할 등기소의 등기관이 부여한다. 3. 법인 아닌 사단이나 재단 및 국내에 영업소나 사무소의 설치 등기를 하지 아니한 외국법인의 등록번호는 시장(「제주특별자치도 설치 및 국제자유도시 조성을 위한 특별법」 제10조제2항에 따른 행정시의 시장을 포함하며, 「지방자치법」 제3조제3항에 따라 자치구가 아닌 구를 두는 시의 시장은 제외한다), 군수 또는 구청장(자치구가 아닌 구의 구청장을 포함한다)이 부여한다. 4. 외국인의 등록번호는 체류지(국내에 체류지가 없는 경우에는 대법원 소재지에 체류지가 있는 것으로 본다)를 관할하는 지방출입국ㆍ외국인관서의 장이 부여한다. ② 제1항제2호에 따른 등록번호의 부여절차는 대법원규칙으로 정하고, 제1항제3호와 제4호에 따른 등록번호의 부여절차는 대통령령으로 정한다."}],"선지":[{"번호":1,"판정":"틀림","설명":"국가·지방자치단체·국제기관·외국정부의 등록번호는 국토교통부장관이 지정·고시한다(법 제49조제1항제1호)."},{"번호":2,"판정":"틀림","설명":"법인의 등록번호는 주된 사무소(회사는 본점, 외국법인은 국내에 최초로 설치 등기를 한 영업소나 사무소) 소재지 관할 등기소의 등기관이 부여한다(법 제49조제1항제2호). 대법원 소재지 관할 등기소 등기관은 재외국민 번호를 부여한다."},{"번호":3,"판정":"틀림","설명":"외국인의 등록번호는 체류지(국내에 체류지가 없으면 대법원 소재지에 있는 것으로 본다)를 관할하는 지방출입국·외국인관서의 장이 부여한다(법 제49조제1항제4호)."},{"번호":4,"판정":"틀림","설명":"주민등록번호가 없는 재외국민의 등록번호는 대법원 소재지 관할 등기소의 등기관이 부여한다(법 제49조제1항제2호)."},{"번호":5,"판정":"옳음","설명":"법인 아닌 사단·재단과 국내에 영업소나 사무소의 설치 등기를 하지 않은 외국법인의 등록번호는 시장·군수·구청장이 부여한다(법 제49조제1항제3호)."}],"개념":[{"종류":"표","제목":"부동산등기용등록번호 부여 주체(법 제49조제1항)","머리":["대상","부여·지정 주체"],"행":[["국가·지방자치단체·국제기관·외국정부","국토교통부장관이 지정·고시"],["주민등록번호가 없는 재외국민","대법원 소재지 관할 등기소의 등기관"],["법인(회사는 본점, 외국법인은 국내 최초 설치 등기 영업소·사무소 기준)","주된 사무소 소재지 관할 등기소의 등기관"],["법인 아닌 사단·재단","시장·군수·구청장"],["국내에 영업소·사무소 설치 등기를 하지 않은 외국법인","시장·군수·구청장"],["외국인","체류지 관할 지방출입국·외국인관서의 장(체류지가 국내에 없으면 대법원 소재지에 체류지가 있는 것으로 봄)"]]},{"종류":"표","제목":"부여절차의 근거 규정(법 제49조제2항)","머리":["대상","절차를 정하는 규정"],"행":[["주민등록번호가 없는 재외국민, 법인","대법원규칙"],["법인 아닌 사단·재단, 설치 등기를 하지 않은 외국법인","대통령령"],["외국인","대통령령"]]}],"함정":"부여 주체가 다섯 갈래이고 선지마다 주체를 하나씩 바꿔 놓았다. 외국법인은 국내에 설치 등기를 했는지에 따라 등기관 또는 시장·군수·구청장으로 갈린다. 외국인은 등기관이 아니라 지방출입국·외국인관서의 장이다."}},{"i":"S2-2-2-공시법-16","r":"S2","g":3,"c":2,"n":16,"s":"공시법","q":"등기신청의 각하결정에 대한 이의신청에 따라 관할 지방법원이 기록명령을 한 경우, 그 기록명령에 따른 등기를 할 수 있는 것은?","b":null,"bs":"없음","img":[],"ch":["소유권이전등기의 기록명령이 있었으나, 그 기록명령에 따른 등기 전에 제3자 명의로 소유권이전등기가 되어 있는 경우","지상권설정등기의 기록명령이 있었으나, 그 기록명령에 따른 등기 전에 동일한 부분에 전세권설정등기가 되어 있는 경우","말소등기의 기록명령이 있었으나, 그 기록명령에 따른 등기 전에 말소 대상 권리를 목적으로 하는 제3자의 권리가 등기되어 등기상 이해관계인이 생긴 경우","전세권설정등기의 기록명령이 있었으나, 그 기록명령에 따른 등기 전에 동일한 부분에 저당권설정등기가 되어 있는 경우","등기관이 기록명령에 따른 등기를 하기 위해 신청인에게 첨부정보를 다시 제공하도록 명령하였으나 신청인이 이에 응하지 않은 경우"],"a":[4],"L":"시2-2","o":"변형","x":{"한줄":"전세권설정 기록명령 앞에 동일한 부분의 저당권설정등기가 있어도 규칙 제161조의 불능 사유가 아니므로 기록명령대로 등기한다.","근거":[{"법령":"부동산등기규칙","조문":"제161조제1항","원문":"① 등기신청의 각하결정에 대한 이의신청에 따라 관할 지방법원이 그 등기의 기록명령을 하였더라도 다음 각 호의 어느 하나에 해당하는 경우에는 그 기록명령에 따른 등기를 할 수 없다. 1. 권리이전등기의 기록명령이 있었으나, 그 기록명령에 따른 등기 전에 제3자 명의로 권리이전등기가 되어 있는 경우 2. 지상권, 지역권, 전세권 또는 임차권의 설정등기의 기록명령이 있었으나, 그 기록명령에 따른 등기 전에 동일한 부분에 지상권, 전세권 또는 임차권의 설정등기가 되어 있는 경우 3. 말소등기의 기록명령이 있었으나 그 기록명령에 따른 등기 전에 등기상 이해관계인이 발생한 경우 4. 등기관이 기록명령에 따른 등기를 하기 위하여 신청인에게 첨부정보를 다시 등기소에 제공할 것을 명령하였으나 신청인이 이에 응하지 아니한 경우"}],"선지":[{"번호":1,"판정":"틀림","설명":"권리이전등기의 기록명령 전에 제3자 명의로 권리이전등기가 되어 있으면 등기할 수 없다(규칙 제161조제1항제1호)."},{"번호":2,"판정":"틀림","설명":"지상권·지역권·전세권·임차권 설정등기의 기록명령 전에 동일한 부분에 지상권·전세권·임차권 설정등기가 있으면 등기할 수 없다(규칙 제161조제1항제2호). 지상권과 전세권도 이 범위에 든다."},{"번호":3,"판정":"틀림","설명":"말소등기의 기록명령 전에 등기상 이해관계인이 생기면 등기할 수 없다(규칙 제161조제1항제3호)."},{"번호":4,"판정":"옳음","설명":"제2호가 막는 앞선 등기는 지상권·전세권·임차권 설정등기뿐이다. 저당권설정등기는 해당하지 않아 기록명령에 따라 등기한다."},{"번호":5,"판정":"틀림","설명":"첨부정보를 다시 제공하라는 명령에 신청인이 응하지 않으면 등기할 수 없다(규칙 제161조제1항제4호)."}],"개념":[{"종류":"흐름","제목":"등기관의 결정·처분에 대한 이의신청","단계":[{"이름":"이의신청","설명":"등기관의 결정 또는 처분에 이의가 있는 자가 그 등기관이 속한 지방법원(관할 지방법원)에 신청. 이의신청서는 결정·처분을 한 등기관이 속한 등기소에 제출(법 제100조, 제101조)"},{"이름":"새로운 사실 금지","설명":"새로운 사실이나 새로운 증거방법을 근거로 이의신청을 할 수 없음(법 제102조)"},{"이름":"등기관의 조치","설명":"이유 있으면 해당 처분. 이유 없으면 이의신청일부터 3일 이내에 의견을 붙여 관할 지방법원에 송부. 등기를 마친 후의 이의는 3일 이내 송부하고 등기상 이해관계인에게 알림(법 제103조)"},{"이름":"처분 전 조치","설명":"관할 지방법원은 결정 전에 가등기 또는 이의가 있다는 뜻의 부기등기를 명령할 수 있음(법 제106조)"},{"이름":"법원의 결정","설명":"이유를 붙여 결정. 이유 있으면 등기관에게 해당 처분을 명령하고 이의신청인과 등기상 이해관계 있는 자에게 알림(법 제105조제1항)"},{"이름":"항고","설명":"결정에 대해 「비송사건절차법」에 따라 항고. 이의에는 집행정지의 효력이 없음(법 제105조제2항, 제104조)"}]},{"종류":"표","제목":"기록명령에 따른 등기를 할 수 없는 경우(규칙 제161조제1항)","머리":["기록명령","그 사이에 생긴 사정","등기 가능 여부"],"행":[["권리이전등기","제3자 명의로 권리이전등기가 되어 있음","불가"],["지상권·지역권·전세권·임차권 설정등기","동일한 부분에 지상권·전세권·임차권 설정등기가 되어 있음","불가"],["말소등기","등기상 이해관계인이 발생","불가"],["모든 기록명령","첨부정보를 다시 제공하라는 등기관 명령에 신청인이 불응","불가"],["전세권설정등기","동일한 부분에 저당권설정등기가 되어 있음","가능(제2호 범위 밖)"]]}],"함정":"선지 2와 4는 모양이 같다. 앞선 등기가 지상권·전세권·임차권 설정이면 막히고 저당권설정이면 막히지 않는다. 말소등기는 등기상 이해관계인이 생긴 것만으로 막힌다(선지 3)."}},{"i":"S2-2-2-공시법-17","r":"S2","g":3,"c":2,"n":17,"s":"공시법","q":"방문신청을 위한 등기신청서의 작성 및 제공에 관한 설명으로 틀린 것은?","b":null,"bs":"없음","img":[],"ch":["신청서가 여러 장일 때에는 신청인 또는 그 대리인이 간인을 하여야 하며, 신청서에 서명을 하였으면 각 장마다 연결되는 서명으로 간인을 대신할 수 있다.","등기권리자 또는 등기의무자가 여러 명인 경우 신청서의 간인은 그 전원이 하여야 한다.","신청서의 문자를 삭제한 경우에는 그 글자 수를 난외에 적고 문자의 앞뒤에 괄호를 붙여 날인 또는 서명하여야 하며, 삭제한 문자는 해독할 수 있도록 글자체를 남겨 두어야 한다.","같은 채권의 담보를 위하여 소유자가 다른 여러 개의 부동산에 대한 저당권설정등기를 신청하는 경우에는 1건의 신청정보로 일괄하여 신청할 수 있다.","신청서에 첨부한 등기신청위임장은 신청인이 원본 환부를 청구할 수 없다."],"a":[2],"L":"시2-2","o":"변형","x":{"한줄":"간인은 등기권리자 또는 등기의무자가 여러 명이면 그중 1명이 하면 된다.","근거":[{"법령":"부동산등기규칙","조문":"제56조제2항","원문":"② 신청서가 여러 장일 때에는 신청인 또는 그 대리인이 간인을 하여야 하고, 등기권리자 또는 등기의무자가 여러 명일 때에는 그 중 1명이 간인하는 방법으로 한다. 다만, 신청서에 서명을 하였을 때에는 각 장마다 연결되는 서명을 함으로써 간인을 대신한다."},{"법령":"부동산등기규칙","조문":"제57조제2항","원문":"② 제1항의 서면에 적은 문자의 정정, 삽입 또는 삭제를 한 경우에는 그 글자 수를 난외(欄外)에 적으며 문자의 앞뒤에 괄호를 붙이고 이에 날인 또는 서명하여야 한다. 이 경우 삭제한 문자는 해독할 수 있게 글자체를 남겨두어야 한다."},{"법령":"부동산등기규칙","조문":"제47조제1항제1호","원문":"① 법 제25조 단서에 따라 다음 각 호의 경우에는 1건의 신청정보로 일괄하여 신청하거나 촉탁할 수 있다. 1. 같은 채권의 담보를 위하여 소유자가 다른 여러 개의 부동산에 대한 저당권설정등기를 신청하는 경우"},{"법령":"부동산등기규칙","조문":"제59조","원문":"제59조(첨부서면의 원본 환부의 청구) 신청서에 첨부한 서류의 원본의 환부를 청구하는 경우에 신청인은 그 원본과 같다는 뜻을 적은 사본을 첨부하여야 하고, 등기관이 서류의 원본을 환부할 때에는 그 사본에 원본 환부의 뜻을 적고 기명날인하여야 한다. 다만, 다음 각 호의 서류에 대하여는 환부를 청구할 수 없다. 1. 등기신청위임장, 제46조제1항제8호, 제111조제2항의 확인정보를 담고 있는 서면 등 해당 등기신청만을 위하여 작성한 서류"}],"선지":[{"번호":1,"판정":"옳음","설명":"신청서가 여러 장이면 신청인 또는 대리인이 간인하고, 서명한 때에는 각 장마다 연결되는 서명으로 간인을 대신한다(규칙 제56조제2항)."},{"번호":2,"판정":"틀림","설명":"등기권리자 또는 등기의무자가 여러 명이면 그중 1명이 간인한다(규칙 제56조제2항)."},{"번호":3,"판정":"옳음","설명":"정정·삽입·삭제 문자의 글자 수를 난외에 적고 앞뒤에 괄호를 붙여 날인 또는 서명한다. 삭제한 문자는 해독할 수 있게 글자체를 남긴다(규칙 제57조제2항)."},{"번호":4,"판정":"옳음","설명":"소유자가 다른 여러 부동산에 대한 같은 채권 담보 저당권설정등기는 1건의 신청정보로 일괄 신청한다(규칙 제47조제1항제1호)."},{"번호":5,"판정":"옳음","설명":"해당 등기신청만을 위해 작성한 등기신청위임장 등은 원본 환부를 청구할 수 없다(규칙 제59조제1호)."}],"개념":[{"종류":"표","제목":"방문신청 서면 작성 규칙","머리":["항목","내용","근거"],"행":[["기명날인·서명","신청인 또는 그 대리인이 기명날인하거나 서명","규칙 제56조제1항"],["간인","신청인 또는 대리인이 하고, 권리자·의무자가 여럿이면 그중 1명이 함. 서명한 때에는 각 장마다 연결되는 서명으로 대신","규칙 제56조제2항"],["첨부서면","첨부정보를 담은 서면을 첨부","규칙 제56조제3항"],["문자 정정·삽입·삭제","글자 수를 난외에 적고 앞뒤에 괄호, 날인 또는 서명. 삭제한 문자는 해독 가능하게 남김","규칙 제57조제2항"],["원본 환부","원본과 같다는 뜻을 적은 사본 첨부. 등기신청위임장 등과 인감증명, 법인등기사항증명서, 주민등록표등본·초본, 가족관계등록사항별증명서, 건축물대장·토지대장·임야대장 등본은 환부 불가","규칙 제59조"]]},{"종류":"표","제목":"1건의 신청정보 원칙과 예외","머리":["구분","내용","근거"],"행":[["원칙","등기신청은 1건당 1개의 부동산에 관한 신청정보","법 제25조 본문"],["예외 1","등기목적과 등기원인이 동일하면 여러 개의 부동산 일괄 제공 가능","법 제25조 단서"],["예외 2","같은 채권의 담보를 위한 소유자가 다른 여러 부동산의 저당권설정등기","규칙 제47조제1항제1호"],["예외 3","관할 등기소가 다른 여러 부동산의 공동저당·전세권설정 등은 그중 하나의 관할 등기소에 1건으로 신청 가능","법 제7조의2, 규칙 제163조"]]}],"함정":"간인은 등기권리자나 등기의무자가 여럿이어도 그중 1명이 한다. 신청서에 서명을 했으면 각 장마다 연결되는 서명이 간인을 대신한다.","개정":"2025년 1월 31일 시행 부동산등기법 제7조의2 신설로 관할 등기소가 서로 다른 여러 부동산의 공동저당 등은 그중 하나의 관할 등기소에 1건의 신청정보로 일괄 신청할 수 있다(법 제25조 단서, 규칙 제163조). 종전 기출의 '관할이 다르면 일괄신청 불가' 문장은 현행법으로는 틀린 설명이다."}},{"i":"S2-2-2-공시법-18","r":"S2","g":3,"c":2,"n":18,"s":"공시법","q":"2022년에 체결된 ｢부동산 거래신고 등에 관한 법률｣제3조제1항제1호의 부동산 매매계약의 계약서를 등기원인증서로 하는 소유권이전등기에 관한 설명으로 틀린 것은?","b":null,"bs":"없음","img":[],"ch":["신청인은 위 법률에 따라 신고한 거래가액을 신청정보의 내용으로 등기소에 제공해야 한다.","신청인은 시장ㆍ군수 또는 구청장이 제공한 거래계약신고필증정보를 첨부정보로서 등기소에 제공해야 한다.","신고 관할관청이 같은 거래부동산이 2개 이상인 경우, 신청인은 매매목록을 첨부정보로서 등기소에 제공해야 한다.","거래부동산이 1개라 하더라도 여러 명의 매도인과 여러명의 매수인 사이의 매매계약인 경우에는 매매목록을 첨부정보로서 등기소에 제공해야 한다.","등기관은 거래가액을 등기기록 중 갑구의 등기원인란에 기록하는 방법으로 등기한다."],"a":[5],"L":"시2-2","o":"기출","x":{"한줄":"거래가액은 갑구의 권리자 및 기타사항란에 기록하고, 등기원인란에 기록하지 않는다.","근거":[{"법령":"부동산등기규칙","조문":"제124조제2항","원문":"② 「부동산 거래신고 등에 관한 법률」 제3조제1항에서 정하는 계약을 등기원인으로 하는 소유권이전등기를 신청하는 경우에는 거래가액을 신청정보의 내용으로 등기소에 제공하고, 시장ㆍ군수 또는 구청장으로부터 제공받은 거래계약신고필증정보를 첨부정보로서 등기소에 제공하여야 한다. 이 경우 대법원예규로 정하는 바에 따라 거래부동산이 2개 이상인 경우 또는 거래부동산이 1개라 하더라도 여러 명의 매도인과 여러 명의 매수인 사이의 매매계약인 경우에는 매매목록도 첨부정보로서 등기소에 제공하여야 한다."},{"법령":"부동산등기규칙","조문":"제125조","원문":"제125조(거래가액의 등기방법) 등기관이 거래가액을 등기할 때에는 다음 각 호의 구분에 따른 방법으로 한다. 1. 매매목록의 제공이 필요 없는 경우 : 등기기록 중 갑구의 권리자 및 기타사항란에 거래가액을 기록하는 방법 2. 매매목록이 제공된 경우 : 거래가액과 부동산의 표시를 기록한 매매목록을 전자적으로 작성하여 번호를 부여하고 등기기록 중 갑구의 권리자 및 기타사항란에 그 매매목록의 번호를 기록하는 방법"},{"법령":"부동산등기법","조문":"제68조","원문":"제68조(거래가액의 등기) 등기관이 「부동산 거래신고 등에 관한 법률」 제3조제1항에서 정하는 계약을 등기원인으로 한 소유권이전등기를 하는 경우에는 대법원규칙으로 정하는 바에 따라 거래가액을 기록한다."}],"선지":[{"번호":1,"판정":"옳음","설명":"신고한 거래가액은 신청정보의 내용으로 제공한다(규칙 제124조제2항)."},{"번호":2,"판정":"옳음","설명":"시장·군수·구청장에게서 제공받은 거래계약신고필증정보를 첨부정보로 제공한다(규칙 제124조제2항)."},{"번호":3,"판정":"옳음","설명":"거래부동산이 2개 이상이면 매매목록을 첨부정보로 제공한다(규칙 제124조제2항, 대법원예규)."},{"번호":4,"판정":"옳음","설명":"거래부동산이 1개여도 매도인과 매수인이 각각 여럿이면 매매목록을 제공한다(규칙 제124조제2항)."},{"번호":5,"판정":"틀림","설명":"거래가액은 갑구의 권리자 및 기타사항란에 기록한다. 매매목록이 제공되면 그 매매목록의 번호를 같은 란에 기록한다(규칙 제125조)."}],"개념":[{"종류":"흐름","제목":"매매계약에 따른 소유권이전등기와 거래가액 등기","단계":[{"이름":"매매계약 체결","설명":"부동산 매매계약 등 「부동산 거래신고 등에 관한 법률」 제3조제1항 계약"},{"이름":"거래신고","설명":"거래당사자가 계약 체결일부터 30일 이내에 관할 시장·군수·구청장에게 신고. 개업공인중개사가 계약서를 작성·교부했으면 그 개업공인중개사가 신고(같은 법 제3조)"},{"이름":"신고필증정보 제공","설명":"시장·군수·구청장이 거래계약신고필증정보를 제공"},{"이름":"등기신청","설명":"신청정보에 신고한 거래가액 제공, 첨부정보에 거래계약신고필증정보. 거래부동산이 2개 이상이거나 여러 매도인·매수인이면 매매목록도 제공(규칙 제124조)"},{"이름":"거래가액 기록","설명":"갑구의 권리자 및 기타사항란에 거래가액 기록, 매매목록이 있으면 매매목록 번호를 기록(규칙 제125조)"}]},{"종류":"표","제목":"거래가액 등기 정리","머리":["상황","제공할 정보","등기기록 기록"],"행":[["거래부동산 1개, 매도인·매수인 각 1명","거래가액(신청정보), 거래계약신고필증정보(첨부정보)","갑구 권리자 및 기타사항란에 거래가액"],["거래부동산 2개 이상","위 정보와 매매목록","갑구 권리자 및 기타사항란에 매매목록 번호"],["거래부동산 1개, 매도인·매수인이 여럿","위 정보와 매매목록","갑구 권리자 및 기타사항란에 매매목록 번호"],["거래가액의 의미","「부동산 거래신고 등에 관한 법률」 제3조에 따라 신고한 금액","규칙 제124조제1항"]]}],"함정":"거래가액이 기록되는 곳을 등기원인란으로 착각하게 하는 문항이다. 등기원인란에는 원인과 연월일이 들어가고, 거래가액은 권리자 및 기타사항란에 들어간다. 매매목록이 필요한 두 경우(부동산 2개 이상, 당사자 여럿)도 함께 묻는다."}},{"i":"S2-2-2-공시법-19","r":"S2","g":3,"c":2,"n":19,"s":"공시법","q":"부동산등기에 관한 설명으로 틀린 것은?","b":null,"bs":"없음","img":[],"ch":["공용부분이라는 뜻을 정한 규약을 폐지한 경우, 공용부분의 취득자는 지체 없이 소유권보존등기를 신청하여야 한다.","토지의 분할이나 합병이 있는 경우 그 토지 소유권의 등기명의인은 그 사실이 있는 때부터 1개월 이내에 변경등기를 신청하여야 한다.","합필하려는 모든 토지에 등기원인 및 그 연월일과 접수번호가 동일한 저당권등기가 있는 경우에도 합필의 등기를 할 수 없다.","건물의 분할, 구분, 합병이 있는 경우 그 건물 소유권의 등기명의인은 그 사실이 있는 때부터 1개월 이내에 변경등기를 신청하여야 한다.","1동의 건물에 속하는 구분건물 중 일부만에 관하여 소유권보존등기를 신청하는 경우에는 나머지 구분건물의 표시에 관한 등기를 동시에 신청하여야 한다."],"a":[3],"L":"시2-3","o":"변형","x":{"한줄":"합필하려는 모든 토지에 등기원인·연월일·접수번호가 같은 저당권등기가 있으면 합필등기를 할 수 있다.","근거":[{"법령":"부동산등기법","조문":"제37조제1항","원문":"① 합필(合筆)하려는 토지에 다음 각 호의 등기 외의 권리에 관한 등기가 있는 경우에는 합필의 등기를 할 수 없다. 1. 소유권ㆍ지상권ㆍ전세권ㆍ임차권 및 승역지(承役地: 편익제공지)에 하는 지역권의 등기 2. 합필하려는 모든 토지에 있는 등기원인 및 그 연월일과 접수번호가 동일한 저당권에 관한 등기 3. 합필하려는 모든 토지에 있는 제81조제1항 각 호의 등기사항이 동일한 신탁등기"},{"법령":"부동산등기법","조문":"제35조","원문":"제35조(변경등기의 신청) 토지의 분할, 합병이 있는 경우와 제34조의 등기사항에 변경이 있는 경우에는 그 토지 소유권의 등기명의인은 그 사실이 있는 때부터 1개월 이내에 그 등기를 신청하여야 한다."},{"법령":"부동산등기법","조문":"제41조제1항","원문":"① 건물의 분할, 구분, 합병이 있는 경우와 제40조의 등기사항에 변경이 있는 경우에는 그 건물 소유권의 등기명의인은 그 사실이 있는 때부터 1개월 이내에 그 등기를 신청하여야 한다."},{"법령":"부동산등기법","조문":"제46조제1항","원문":"① 1동의 건물에 속하는 구분건물 중 일부만에 관하여 소유권보존등기를 신청하는 경우에는 나머지 구분건물의 표시에 관한 등기를 동시에 신청하여야 한다."},{"법령":"부동산등기법","조문":"제47조제2항","원문":"② 공용부분이라는 뜻을 정한 규약을 폐지한 경우에 공용부분의 취득자는 지체 없이 소유권보존등기를 신청하여야 한다."}],"선지":[{"번호":1,"판정":"옳음","설명":"규약 폐지의 경우 공용부분의 취득자가 지체 없이 소유권보존등기를 신청한다(법 제47조제2항)."},{"번호":2,"판정":"옳음","설명":"토지의 분할·합병이 있으면 소유권 등기명의인이 그 사실이 있는 때부터 1개월 이내에 신청한다(법 제35조)."},{"번호":3,"판정":"틀림","설명":"합필하려는 모든 토지에 있는 저당권등기의 등기원인 및 그 연월일과 접수번호가 동일하면 합필의 등기를 할 수 있다(법 제37조제1항제2호). 소유권·지상권·전세권·임차권과 승역지 지역권 등기도 합필 제한 사유가 아니다."},{"번호":4,"판정":"옳음","설명":"건물의 분할·구분·합병이 있으면 소유권 등기명의인이 1개월 이내에 변경등기를 신청한다(법 제41조제1항)."},{"번호":5,"판정":"옳음","설명":"구분건물 중 일부만 보존등기를 신청할 때에는 나머지 구분건물의 표시등기를 동시에 신청한다(법 제46조제1항)."}],"개념":[{"종류":"표","제목":"표시에 관한 등기 신청 기한","머리":["등기","신청인","기한","근거"],"행":[["토지 분할·합병, 표제부 사항 변경","토지 소유권의 등기명의인","그 사실이 있는 때부터 1개월 이내","법 제35조"],["토지 멸실","토지 소유권의 등기명의인","그 사실이 있는 때부터 1개월 이내","법 제39조"],["건물 분할·구분·합병, 표제부 사항 변경","건물 소유권의 등기명의인","그 사실이 있는 때부터 1개월 이내","법 제41조제1항"],["건물 멸실","건물 소유권의 등기명의인(미신청 시 건물대지 소유자가 대위)","그 사실이 있는 때부터 1개월 이내","법 제43조"],["존재하지 않는 건물의 등기","소유권의 등기명의인","지체 없이 멸실등기","법 제44조제1항"],["규약 폐지에 따른 공용부분","공용부분의 취득자","지체 없이 소유권보존등기","법 제47조제2항"]]},{"종류":"표","제목":"합필·합병 제한: 있어도 되는 등기","머리":["구분","합필(토지, 법 제37조)","합병(건물, 법 제42조)"],"행":[["소유권","가능","가능"],["지상권","가능","불가"],["전세권","가능","가능"],["임차권","가능","가능"],["승역지 지역권","가능","불가"],["저당권","합필하려는 모든 토지에 등기원인 및 그 연월일과 접수번호가 동일하면 가능","합병하려는 모든 건물에 등기원인 및 그 연월일과 접수번호가 동일하면 가능"],["신탁등기","합필하려는 모든 토지에 법 제81조제1항 각 호의 등기사항이 동일하면 가능","합병하려는 모든 건물에 법 제81조제1항 각 호의 등기사항이 동일하면 가능"]]}],"함정":"저당권이 있다고 모두 합필이 막히는 것은 아니다. 합필하려는 모든 토지에서 등기원인·연월일·접수번호가 같은 저당권은 허용된다. 토지 합필에서 허용되는 지상권과 승역지 지역권은 건물 합병의 허용 목록에 없다."}},{"i":"S2-2-2-공시법-20","r":"S2","g":3,"c":2,"n":20,"s":"공시법","q":"공동소유에 관한 등기에 대한 설명으로 옳은 것은?","b":null,"bs":"없음","img":[],"ch":["공유자 중 1인이 자기 지분의 일부를 이전하는 등기를 할 때 등기원인에 공유물분할금지약정이 있으면 그 약정도 기록하며, 그 약정의 변경등기는 공유자 전원이 공동으로 신청하여야 한다.","합유로 소유권이전등기를 하는 경우 합유자별 지분을 등기기록에 기록한다.","공유 농지를 분할하여 공유물분할을 원인으로 소유권이전등기를 신청하는 경우, 농지취득자격증명을 첨부하여야 한다.","갑구 순위번호 2번에 기록된 A의 공유지분 3분의 2 중 절반을 B에게 이전하는 경우, 등기목적란에 \"2번 A 지분 3분의 2 중 일부(2분의 1)이전\"으로 기록한다.","법인 아닌 사단 A가 매수인으로서 B와의 매매를 원인으로 소유권이전등기를 신청하는 경우, 특별한 사정이 없는 한 A의 사원총회 결의가 있음을 증명하는 정보를 제공하여야 한다."],"a":[1],"L":"시2-3","o":"변형","x":{"한줄":"공유물분할금지약정은 지분 일부이전등기에 함께 기록하고, 그 약정의 변경등기는 공유자 전원이 공동으로 신청한다.","근거":[{"법령":"부동산등기법","조문":"제67조","원문":"① 등기관이 소유권의 일부에 관한 이전등기를 할 때에는 이전되는 지분을 기록하여야 한다. 이 경우 등기원인에 「민법」 제268조제1항 단서의 약정이 있을 때에는 그 약정에 관한 사항도 기록하여야 한다. ② 제1항 후단의 약정의 변경등기는 공유자 전원이 공동으로 신청하여야 한다."},{"법령":"부동산등기법","조문":"제48조제4항","원문":"④ 제1항제5호의 권리자가 2인 이상인 경우에는 권리자별 지분을 기록하여야 하고 등기할 권리가 합유(合有)인 때에는 그 뜻을 기록하여야 한다."},{"법령":"농지법","조문":"제8조제1항제3호","원문":"①농지를 취득하려는 자는 농지 소재지를 관할하는 시장(구를 두지 아니한 시의 시장을 말하며, 도농 복합 형태의 시는 농지 소재지가 동지역인 경우만을 말한다), 구청장(도농 복합 형태의 시의 구에서는 농지 소재지가 동지역인 경우만을 말한다), 읍장 또는 면장(이하 \"시ㆍ구ㆍ읍ㆍ면의 장\"이라 한다)에게서 농지취득자격증명을 발급받아야 한다. 다만, 다음 각 호의 어느 하나에 해당하면 농지취득자격증명을 발급받지 아니하고 농지를 취득할 수 있다. 1. 제6조제2항제1호ㆍ제4호ㆍ제6호ㆍ제8호 또는 제10호(같은 호 바목은 제외한다)에 따라 농지를 취득하는 경우 2. 농업법인의 합병으로 농지를 취득하는 경우 3. 공유 농지의 분할이나 그 밖에 대통령령으로 정하는 원인으로 농지를 취득하는 경우"},{"법령":"부동산등기규칙","조문":"제105조","원문":"① 등기할 권리자가 2인 이상일 때에는 그 지분을 신청정보의 내용으로 등기소에 제공하여야 한다. ② 제1항의 경우에 등기할 권리가 합유일 때에는 합유라는 뜻을 신청정보의 내용으로 등기소에 제공하여야 한다."},{"법령":"부동산등기규칙","조문":"제48조제3호","원문":"3. 「민법」 제276조제1항의 결의가 있음을 증명하는 정보(법인 아닌 사단이 등기의무자인 경우로 한정한다)"},{"이론":"지분 일부이전의 등기목적 기록례(등기예규)","내용":"이전하는 지분이 전체 중 얼마인지를 괄호에 적는다. 3분의 2 중 절반을 이전하면 이전되는 지분은 전체의 3분의 1이므로 \"일부(3분의 1)이전\"으로 적는다."}],"선지":[{"번호":1,"판정":"옳음","설명":"일부이전등기에는 이전 지분을 기록하고, 민법 제268조제1항 단서의 약정이 있으면 그 약정도 기록한다. 약정의 변경등기는 공유자 전원이 공동으로 신청한다(법 제67조)."},{"번호":2,"판정":"틀림","설명":"권리자가 2인 이상이면 지분을 기록하지만, 합유이면 합유라는 뜻만 기록하고 합유자별 지분은 기록하지 않는다(법 제48조제4항, 규칙 제105조)."},{"번호":3,"판정":"틀림","설명":"공유 농지의 분할로 농지를 취득하는 경우에는 농지취득자격증명이 필요 없다(농지법 제8조제1항제3호)."},{"번호":4,"판정":"틀림","설명":"3분의 2 중 절반은 전체의 3분의 1이다. 등기목적은 \"2번 A 지분 3분의 2 중 일부(3분의 1)이전\"으로 기록한다."},{"번호":5,"판정":"틀림","설명":"사원총회 결의 증명정보는 법인 아닌 사단이 등기의무자인 경우에 제공한다(규칙 제48조제3호). A가 매수인으로서 권리를 취득하는 경우는 해당하지 않는다."}],"개념":[{"종류":"비교","제목":"공유와 합유의 등기","왼쪽":{"이름":"공유","항목":["권리자 2인 이상이면 권리자별 지분을 기록(법 제48조제4항)","신청정보에도 지분 제공(규칙 제105조제1항)","지분 일부이전등기: 이전되는 지분 기록, 공유물분할금지약정이 있으면 함께 기록(법 제67조제1항)","약정의 변경등기: 공유자 전원이 공동 신청(법 제67조제2항)","공유 농지의 분할 취득: 농지취득자격증명 불필요"]},"오른쪽":{"이름":"합유","항목":["합유라는 뜻을 기록(법 제48조제4항)","신청정보에 합유라는 뜻을 제공(규칙 제105조제2항)","합유자별 지분은 기록하지 않음","법인 아닌 사단의 부동산은 사단 명의로 등기(법 제26조)","민법상 조합재산은 조합원 전원의 합유 명의로 등기"]}},{"종류":"표","제목":"법인 아닌 사단·재단의 등기","머리":["상황","내용","근거"],"행":[["등기명의","사단·재단 명의, 대표자·관리인이 신청","법 제26조"],["등기기록 기록","대표자·관리인의 성명, 주소, 주민등록번호도 기록","법 제48조제3항"],["등기의무자일 때 첨부","민법 제276조제1항의 결의(사원총회 결의)가 있음을 증명하는 정보","규칙 제48조제3호"],["등기권리자일 때","사원총회 결의 증명정보 불필요","규칙 제48조제3호 반대해석"]]}],"함정":"선지 4는 절반이라는 말을 그대로 따라 2분의 1이라고 적은 문장이다. 괄호 안에는 이전되는 지분이 전체에서 차지하는 몫을 적는다. 선지 5는 의무자일 때만 사원총회 결의 정보가 필요하다는 점을 뒤집었다."}},{"i":"S2-2-2-공시법-21","r":"S2","g":3,"c":2,"n":21,"s":"공시법","q":"합필의 등기를 할 수 있는 경우를 모두 고른 것은? (단, 토지소유자가 지적소관청에 토지합병을 신청할 당시부터 아래의 등기가 존재함)","b":"ㄱ. 합필하려는 토지에 지상권의 등기가 있는 경우\nㄴ. 합필하려는 토지의 소유자별 공유지분이 다른 경우\nㄷ. 합필하려는 토지에 가등기담보권의 등기가 있는 경우\nㄹ. 합필하려는 토지에 승역지에 하는 지역권의 등기가 있는 경우\nㅁ. 합필하려는 모든 토지에 등기원인 및 그 연월일과 접수번호가 동일한 저당권의 등기가 있는 경우","bs":"글자","img":[],"ch":["ㄱ, ㄴ","ㄷ, ㅁ","ㄱ, ㄴ, ㄷ","ㄱ, ㄹ, ㅁ","ㄴ, ㄷ, ㄹ, ㅁ"],"a":[4],"L":"시2-3","o":"기출","x":{"한줄":"합필등기는 소유권·지상권·전세권·임차권, 승역지 지역권, 모든 토지에 동일한 저당권·신탁등기만 있을 때 할 수 있으므로 ㄱ, ㄹ, ㅁ 이 가능하다.","근거":[{"법령":"부동산등기법","조문":"제37조제1항","원문":"합필(合筆)하려는 토지에 다음 각 호의 등기 외의 권리에 관한 등기가 있는 경우에는 합필의 등기를 할 수 없다. 1. 소유권ㆍ지상권ㆍ전세권ㆍ임차권 및 승역지(承役地: 편익제공지)에 하는 지역권의 등기 2. 합필하려는 모든 토지에 있는 등기원인 및 그 연월일과 접수번호가 동일한 저당권에 관한 등기 3. 합필하려는 모든 토지에 있는 제81조제1항 각 호의 등기사항이 동일한 신탁등기"},{"법령":"공간정보의 구축 및 관리 등에 관한 법률 시행령","조문":"제66조제3항제5호","원문":"합병하려는 토지의 소유자별 공유지분이 다른 경우"}],"선지":[{"번호":1,"판정":"-","설명":"ㄱ 은 가능하나 ㄴ 은 불가능하다. 소유자별 공유지분이 다르면 지적 합병 단계에서 막힌다(공간정보법 시행령 제66조제3항제5호)."},{"번호":2,"판정":"-","설명":"ㄷ 은 불가능하다. 가등기담보권은 법 제37조제1항 각 호에 없다. ㅁ 은 가능하다."},{"번호":3,"판정":"-","설명":"ㄴ, ㄷ 이 불가능하다."},{"번호":4,"판정":"-","설명":"ㄱ(법 제37조제1항제1호 지상권), ㄹ(같은 호 승역지 지역권), ㅁ(같은 항 제2호) 모두 가능하다."},{"번호":5,"판정":"-","설명":"ㄴ, ㄷ 이 불가능하다."}],"보기판정":[{"기호":"ㄱ","판정":"옳음","설명":"지상권의 등기는 합필 제한 대상이 아니다(법 제37조제1항제1호)."},{"기호":"ㄴ","판정":"틀림","설명":"소유자별 공유지분이 다르면 지적소관청이 합병 신청을 받아주지 않는다(공간정보법 제80조제3항제3호, 시행령 제66조제3항제5호). 합병이 안 되므로 합필등기를 할 수 없다."},{"기호":"ㄷ","판정":"틀림","설명":"가등기담보권은 소유권·지상권·전세권·임차권·승역지 지역권·저당권·신탁 어디에도 속하지 않아 합필을 막는다(법 제37조제1항)."},{"기호":"ㄹ","판정":"옳음","설명":"승역지에 하는 지역권의 등기는 허용된다. 요역지에 하는 지역권은 이 목록에 없다(법 제37조제1항제1호)."},{"기호":"ㅁ","판정":"옳음","설명":"모든 토지에 원인·연월일·접수번호가 같은 저당권이면 허용된다(법 제37조제1항제2호)."}],"개념":[{"종류":"표","제목":"합필(합병)등기가 가능한 등기와 불가능한 등기","머리":["등기","합필 가능 여부","비고"],"행":[["소유권·지상권·전세권·임차권","가능","법 제37조제1항제1호"],["승역지에 하는 지역권","가능","요역지 지역권은 불가"],["모든 토지에 같은 저당권","가능","원인·연월일·접수번호 동일"],["모든 토지에 같은 신탁등기","가능","신탁원부 기록사항 동일"],["가등기담보권·가압류·가처분 등","불가","나머지 등기 전부"],["한쪽에만 있는 저당권","불가","모든 토지에 있어야 함"]]},{"종류":"흐름","제목":"토지 합병과 합필등기","단계":[{"이름":"합병 신청","설명":"토지소유자가 지적소관청에 신청. 소유자 다름·지목 다름·제한 등기 있음·공유지분 다름이면 신청 불가"},{"이름":"대장 합병 등록","설명":"지적소관청이 지적공부에 합병 등록"},{"이름":"합필등기 신청","설명":"소유권 등기명의인이 합병이 있는 때부터 1개월 이내 신청(법 제35조)"},{"이름":"등기관 심사","설명":"법 제37조제1항 위반이면 각하하고 지체 없이 지적소관청에 통지(법 제37조제2항)"}]}],"함정":"ㄴ 을 고르기 쉽다. 공유지분이 다른 사정은 등기부의 문제처럼 보이지만 지적소관청 단계에서 합병 신청이 막히므로 합필등기까지 가지 못한다. 지상권·승역지 지역권·같은 저당권은 가능하고 가등기담보권만 막힌다는 구분이 핵심이다."}},{"i":"S2-2-2-공시법-22","r":"S2","g":3,"c":2,"n":22,"s":"공시법","q":"저당권의 등기에 관한 설명으로 옳은 것은?","b":null,"bs":"없음","img":[],"ch":["채무자와 저당권설정자가 동일한 근저당권설정등기를 신청하는 경우, 채무자의 성명과 주소는 신청정보의 내용으로 제공하지 않는다.","소유권 외의 권리를 목적으로 하는 저당권설정등기를 신청하는 경우, 그 권리의 표시에 관한 사항은 신청정보의 내용으로 제공하지 않아도 된다.","동일한 채권에 관하여 4개의 부동산을 공동담보로 하는 저당권설정등기를 하는 경우, 등기관은 공동담보목록을 작성하여야 한다.","채권 일부의 대위변제로 인한 저당권 일부이전등기를 하는 경우, 등기관은 변제액을 기록하여야 한다.","공동저당 대위등기를 신청하는 경우, 배당표 정보는 첨부정보로 제공하지 않아도 된다."],"a":[4],"L":"시2-4","o":"변형","x":{"한줄":"채권 일부를 대위변제하여 저당권 일부이전등기를 하면 등기관이 변제액을 기록한다.","근거":[{"법령":"부동산등기법","조문":"제79조","원문":"등기관이 채권의 일부에 대한 양도 또는 대위변제(代位辨濟)로 인한 저당권 일부이전등기를 할 때에는 제48조에서 규정한 사항 외에 양도액 또는 변제액을 기록하여야 한다."},{"법령":"부동산등기법","조문":"제78조제2항","원문":"등기관은 제1항의 경우에 부동산이 5개 이상일 때에는 공동담보목록을 작성하여야 한다."},{"법령":"부동산등기규칙","조문":"제131조제2항","원문":"저당권설정의 등기를 신청하는 경우에 그 권리의 목적이 소유권 외의 권리일 때에는 그 권리의 표시에 관한 사항을 신청정보의 내용으로 등기소에 제공하여야 한다."},{"법령":"부동산등기규칙","조문":"제138조","원문":"공동저당 대위등기를 신청하는 경우에는 법 제80조의 등기사항을 신청정보의 내용으로 등기소에 제공하고, 배당표 정보를 첨부정보로서 등기소에 제공하여야 한다."}],"선지":[{"번호":1,"판정":"틀림","설명":"근저당권설정등기에는 채무자의 성명(명칭)과 주소(소재지)를 반드시 기록하므로, 설정자와 같은 사람이어도 신청정보에 제공한다(법 제75조제2항제2호, 규칙 제131조제1항)."},{"번호":2,"판정":"틀림","설명":"권리의 표시에 관한 사항을 신청정보로 제공하여야 한다(규칙 제131조제2항)."},{"번호":3,"판정":"틀림","설명":"공동담보목록은 부동산이 5개 이상일 때 작성한다. 4개이면 각 부동산의 등기기록에 공동담보라는 뜻만 기록한다(법 제78조제1항·제2항)."},{"번호":4,"판정":"옳음","설명":"저당권 일부이전등기에는 양도액 또는 변제액을 기록한다(법 제79조). 신청인은 변제의 목적인 채권액을 신청정보로 제공한다(규칙 제137조제2항)."},{"번호":5,"판정":"틀림","설명":"배당표 정보를 첨부정보로 제공하여야 한다(규칙 제138조)."}],"개념":[{"종류":"표","제목":"저당권·근저당권설정등기의 기록사항","머리":["구분","반드시 기록","약정이 있을 때만 기록"],"행":[["저당권(법 제75조제1항)","채권액, 채무자의 성명·주소","변제기, 이자와 발생기·지급시기, 원본·이자 지급장소, 손해배상 약정, 민법 제358조 단서 약정, 채권의 조건"],["근저당권(법 제75조제2항)","채권의 최고액, 채무자의 성명·주소","민법 제358조 단서 약정, 존속기간"],["금액 아닌 채권 담보(법 제77조)","채권의 평가액","-"]]},{"종류":"표","제목":"저당권 관련 신청정보·기록사항","머리":["상황","신청정보·첨부정보","등기관 기록"],"행":[["금액 아닌 채권을 담보","채권의 평가액 제공(규칙 제131조제3항)","채권의 평가액(법 제77조)"],["소유권 외 권리가 목적","그 권리의 표시 제공(규칙 제131조제2항)","-"],["부동산 5개 이상 공동담보","각 부동산의 표시 제공(규칙 제133조제1항)","공동담보목록 작성(법 제78조제2항)"],["4개 이하 공동담보","각 부동산의 표시 제공","각 등기기록에 공동담보라는 뜻(법 제78조제1항)"],["저당권 이전","채권과 같이 이전한다는 뜻 제공(규칙 제137조제1항)","-"],["채권 일부 양도·대위변제","양도·변제한 채권액 제공(규칙 제137조제2항)","양도액·변제액(법 제79조)"],["공동저당 대위등기","법 제80조 등기사항 + 배당표 정보 첨부(규칙 제138조)","매각 부동산·매각대금·선순위자 변제액(법 제80조)"]]}],"함정":"공동담보목록의 기준 부동산 수가 5개 이상이다. 3개나 4개로 알고 있으면 선지 3 을 고른다. 채무자가 설정자와 같은 경우의 생략 가능 여부, 대위등기의 배당표 첨부 여부는 법에 예외 규정이 없다."}},{"i":"S2-2-2-공시법-23","r":"S2","g":3,"c":2,"n":23,"s":"공시법","q":"가등기에 관한 설명으로 옳은 것은?","b":null,"bs":"없음","img":[],"ch":["소유권이전청구권이 정지조건부인 경우에는 그 청구권을 보전하기 위한 가등기를 할 수 없다.","가등기권리자는 가등기의무자의 승낙이나 가등기를 명하는 가처분명령이 없어도 단독으로 가등기를 신청할 수 있다.","가등기명의인은 가등기의무자와 공동으로만 그 가등기의 말소를 신청할 수 있다.","소유권이전청구권 보전 가등기에 의하여 소유권이전의 본등기를 한 경우, 가등기 후 본등기 전에 마쳐진 지상권설정등기는 직권말소의 대상이 아니다.","저당권설정등기청구권 보전 가등기에 의하여 저당권설정의 본등기를 한 경우, 가등기 후 본등기 전에 마쳐진 등기는 직권말소의 대상이 되지 않는다."],"a":[5],"L":"시2-5","o":"변형","x":{"한줄":"저당권설정등기청구권 보전 가등기로 본등기를 하면 가등기 후 본등기 전의 등기는 직권말소 대상이 아니다.","근거":[{"법령":"부동산등기규칙","조문":"제148조제3항","원문":"저당권설정등기청구권보전 가등기에 의하여 저당권설정의 본등기를 한 경우 가등기 후 본등기 전에 마쳐진 등기는 직권말소의 대상이 되지 아니한다."},{"법령":"부동산등기규칙","조문":"제147조제1항","원문":"등기관이 소유권이전등기청구권보전 가등기에 의하여 소유권이전의 본등기를 한 경우에는 법 제92조제1항에 따라 가등기 후 본등기 전에 마쳐진 등기 중 다음 각 호의 등기를 제외하고는 모두 직권으로 말소한다."},{"법령":"부동산등기법","조문":"제88조","원문":"가등기는 제3조 각 호의 어느 하나에 해당하는 권리의 설정, 이전, 변경 또는 소멸의 청구권(請求權)을 보전(保全)하려는 때에 한다. 그 청구권이 시기부(始期附) 또는 정지조건부(停止條件附)일 경우나 그 밖에 장래에 확정될 것인 경우에도 같다."}],"선지":[{"번호":1,"판정":"틀림","설명":"정지조건부 청구권도 가등기할 수 있다(법 제88조)."},{"번호":2,"판정":"틀림","설명":"가등기권리자의 단독신청에는 가등기의무자의 승낙이나 가처분명령이 필요하다(법 제89조, 규칙 제145조제2항)."},{"번호":3,"판정":"틀림","설명":"가등기명의인은 단독으로 말소를 신청할 수 있다(법 제93조제1항)."},{"번호":4,"판정":"틀림","설명":"지상권설정등기는 규칙 제147조제1항 각 호의 제외 대상(가등기상 권리를 목적으로 하는 가압류·가처분, 가등기 전 담보가등기·전세권·저당권에 의한 임의경매개시결정등기, 가등기권자에게 대항할 수 있는 주택임차권등기등 등)에 없으므로 직권말소한다."},{"번호":5,"판정":"옳음","설명":"가등기 후 본등기 전에 마쳐진 등기는 어느 것도 직권말소하지 않는다(규칙 제148조제3항)."}],"개념":[{"종류":"표","제목":"가등기에 의한 본등기와 직권말소","머리":["가등기 종류","직권말소하는 등기","말소하지 않는 등기"],"행":[["소유권이전청구권","가등기 후 본등기 전에 마쳐진 등기 전부(제외 대상 빼고)","가등기상 권리 대상 가압류·가처분, 가등기 전 담보가등기·전세권·저당권에 의한 임의경매개시결정등기, 가등기 전 가압류에 의한 강제경매개시결정등기, 대항력 있는 주택임차권등기등(규칙 제147조제1항)"],["지상권·전세권·임차권설정청구권","동일 부분의 지상권·지역권·전세권·임차권설정등기, 대항력 없는 주택임차권등기등(규칙 제148조제1항)","소유권이전등기·가등기, 가압류·가처분, 체납처분 압류, 저당권설정등기, 다른 부분의 설정등기(규칙 제148조제2항)"],["저당권설정청구권","없음","가등기 후 본등기 전 등기 전부(규칙 제148조제3항)"]]},{"종류":"표","제목":"가등기 대상과 신청·말소","머리":["항목","내용","근거"],"행":[["대상","제3조 권리의 설정·이전·변경·소멸 청구권. 시기부·정지조건부·장래 확정 청구권 포함","법 제88조"],["신청","공동신청 원칙. 의무자 승낙이나 가처분명령이 있으면 권리자 단독","법 제23조제1항, 제89조"],["가처분명령","부동산 소재지 관할 지방법원이 소명이 있으면 발령","법 제90조"],["본등기 순위","가등기의 순위에 따른다. 가등기 순위번호 사용","법 제91조, 규칙 제146조"],["말소","가등기명의인 단독. 의무자·이해관계인은 명의인 승낙서를 받아 단독","법 제93조"]]}],"함정":"선지 4 를 고르기 쉽다. 소유권이전 본등기에서는 지상권설정등기가 제외 대상에 없어 말소되고, 직권말소가 없는 경우는 저당권설정 가등기의 본등기다. 소유권, 지상권 등, 저당권 세 종류로 나누어 기억해야 한다."}},{"i":"S2-2-2-공시법-24","r":"S2","g":3,"c":2,"n":24,"s":"공시법","q":"가등기에 관한 설명으로 틀린 것은?","b":null,"bs":"없음","img":[],"ch":["가등기로 보전하려는 등기청구권이 해제조건부인 경우에는 가등기를 할 수 없다.","소유권이전청구권 가등기는 주등기의 방식으로 한다.","가등기는 가등기권리자와 가등기의무자가 공동으로 신청할 수 있다.","가등기에 기한 본등기를 금지하는 취지의 가처분등기의 촉탁이 있는 경우, 등기관은 이를 각하하여야 한다.","소유권이전청구권 가등기에 기하여 본등기를 하는 경우, 등기관은 그 가등기를 말소하는 표시를 하여야 한다."],"a":[5],"L":"시2-5","o":"기출","x":{"한줄":"가등기에 의한 본등기는 가등기의 순위번호를 사용하여 하므로 가등기를 말소하는 표시를 하지 않는다.","근거":[{"법령":"부동산등기규칙","조문":"제146조","원문":"가등기를 한 후 본등기의 신청이 있을 때에는 가등기의 순위번호를 사용하여 본등기를 하여야 한다."},{"법령":"부동산등기법","조문":"제91조","원문":"가등기에 의한 본등기(本登記)를 한 경우 본등기의 순위는 가등기의 순위에 따른다."},{"법령":"부동산등기법","조문":"제88조","원문":"가등기는 제3조 각 호의 어느 하나에 해당하는 권리의 설정, 이전, 변경 또는 소멸의 청구권(請求權)을 보전(保全)하려는 때에 한다. 그 청구권이 시기부(始期附) 또는 정지조건부(停止條件附)일 경우나 그 밖에 장래에 확정될 것인 경우에도 같다."}],"선지":[{"번호":1,"판정":"옳음","설명":"법 제88조가 가등기를 허용하는 청구권은 시기부·정지조건부·장래 확정될 청구권이다. 해제조건부 청구권은 이미 효력이 발생한 청구권이어서 가등기 대상이 아니다."},{"번호":2,"판정":"옳음","설명":"소유권이전청구권 가등기는 주등기로 한다. 부기로 하는 등기는 법 제52조에 열거된 소유권 외의 권리에 관한 등기 등이다."},{"번호":3,"판정":"옳음","설명":"원칙대로 권리자와 의무자가 공동으로 신청한다(법 제23조제1항). 승낙이나 가처분명령이 있으면 권리자 단독신청도 가능하다(법 제89조)."},{"번호":4,"판정":"옳음","설명":"가등기에 기한 본등기를 금지하는 가처분은 등기할 사항이 아니므로 각하한다(법 제29조제2호)."},{"번호":5,"판정":"틀림","설명":"본등기는 가등기의 순위번호를 사용해서 하고, 그 순위는 가등기의 순위에 따른다. 가등기 말소 표시는 하지 않는다(규칙 제146조, 법 제91조)."}],"개념":[{"종류":"표","제목":"가등기 대상 청구권","머리":["청구권","가등기 가능 여부","비고"],"행":[["시기부 청구권","가능","법 제88조"],["정지조건부 청구권","가능","법 제88조"],["장래 확정될 청구권","가능","법 제88조"],["해제조건부 청구권","불가","현재 효력이 있는 청구권"],["소유권 외 권리의 이전청구권(임차권 등)","가능","제3조 각 호의 권리"]]},{"종류":"흐름","제목":"가등기에서 본등기까지","단계":[{"이름":"가등기 신청","설명":"권리자와 의무자 공동신청. 의무자 승낙이나 가처분명령이 있으면 권리자 단독(법 제23조제1항, 제89조)"},{"이름":"가등기 기록","설명":"소유권이전청구권 가등기는 주등기로 기록"},{"이름":"본등기 신청","설명":"가등기의 순위번호를 사용하여 본등기(규칙 제146조)"},{"이름":"직권말소","설명":"가등기 후 본등기 전에 마쳐진 침해 등기를 말소하고 말소한 뜻을 기록(법 제92조, 규칙 제149조)"}]}],"함정":"선지 5 가 정답이다. 본등기 후 가등기가 말소 표시되어 없어질 것으로 생각하기 쉽다. 본등기는 가등기의 순위번호로 하며, 말소 표시를 하는 대상은 가등기 후 본등기 전에 마쳐진 침해 등기다."}},{"i":"S2-2-2-세법-01","r":"S2","g":3,"c":2,"n":25,"s":"세법","q":"거주자인 개인 甲이 乙로부터 부동산을 취득하여 보유하고 있다가 丙에게 양도하였다. 甲의 부동산 관련조세의 납세의무에 관한 설명으로 틀린 것은? (단, 주어진 조건 외에는 고려하지 않음)","b":null,"bs":"없음","img":[],"ch":["甲이 乙로부터 증여받은 것이라면 그 계약일에 취득세 납세의무가 성립한다.","甲이 乙로부터 부동산을 취득 후 재산세 과세기준일까지 등기하지 않았다면 재산세와 관련하여 乙은 부동산 소재지 관할 지방자치단체의 장에게 소유권변동사실을 신고할 의무가 있다.","甲이 종합부동산세를 신고납부방식으로 납부하고자 하는 경우 과세표준과 세액을 해당 연도 12월 1일부터 12월 15일까지 관할 세무서장에게 신고하는 때에 종합부동산세 납세의무는 확정된다.","甲이 乙로부터 부동산을 40만원에 취득한 경우 등록면허세 납세의무가 있다.","양도소득세의 예정신고만으로 甲의 양도소득세 납세의무가 확정되지 아니한다."],"a":[5],"L":"세1-1","o":"기출","x":{"한줄":"소득세는 납세의무자가 신고했을 때 세액이 확정되므로, 양도소득세는 예정신고만으로도 납세의무가 확정된다.","근거":[{"법령":"국세기본법","조문":"제22조제2항","원문":"② 다음 각 호의 국세는 납세의무자가 과세표준과 세액을 정부에 신고했을 때에 확정된다."},{"법령":"국세기본법","조문":"제22조제2항제1호","원문":"1. 소득세"},{"법령":"소득세법","조문":"제110조제4항","원문":"④ 예정신고를 한 자는 제1항에도 불구하고 해당 소득에 대한 확정신고를 하지 아니할 수 있다."},{"법령":"종합부동산세법","조문":"제16조제3항","원문":"③제1항 및 제2항에도 불구하고 종합부동산세를 신고납부방식으로 납부하고자 하는 납세의무자는 종합부동산세의 과세표준과 세액을 해당 연도 12월 1일부터 12월 15일까지 대통령령으로 정하는 바에 따라 관할세무서장에게 신고하여야 한다."},{"법령":"지방세법","조문":"제23조제1호라목","원문":"라. 제17조에 해당하는 물건의 등기 또는 등록"},{"법령":"지방세법","조문":"제120조제1항제1호","원문":"1. 재산의 소유권 변동 또는 과세대상 재산의 변동 사유가 발생하였으나 과세기준일까지 그 등기ㆍ등록이 되지 아니한 재산의 공부상 소유자"}],"선지":[{"번호":1,"판정":"옳음","설명":"증여 같은 무상취득은 계약일에 취득한 것으로 보므로 그날 취득세 납세의무가 성립한다(지방세기본법 제34조제1항제1호, 지방세법 시행령 제20조제1항)."},{"번호":2,"판정":"옳음","설명":"매매로 소유권이 넘어갔는데 과세기준일(6월 1일)까지 등기가 안 됐으면 공부상 소유자 乙이 과세기준일부터 15일 이내에 신고한다(지방세법 제120조제1항제1호)."},{"번호":3,"판정":"옳음","설명":"종합부동산세는 정부 결정이 원칙이지만 12월 1일부터 12월 15일 사이에 신고납부방식으로 신고하면 신고하는 때 확정된다(국세기본법 제22조제2항제9호, 종합부동산세법 제16조제3항)."},{"번호":4,"판정":"옳음","설명":"취득가액 50만원 이하는 취득세 면세점이라 그 소유권이전등기는 등록면허세 과세대상이 된다. 등기를 하는 甲이 납세의무자다(지방세법 제23조제1호라목, 제17조제1항, 제24조)."},{"번호":5,"판정":"틀림","설명":"양도소득세도 소득세이므로 예정신고를 하는 때 세액이 확정된다(국세기본법 제22조제2항제1호). 예정신고를 한 자가 확정신고를 생략할 수 있는 것도 이 때문이다(소득세법 제110조제4항)."}],"개념":[{"종류":"표","제목":"세목별 납세의무 성립시기와 확정 방식","머리":["세목","성립시기","확정"],"행":[["취득세","과세물건을 취득하는 때","신고하는 때"],["등록면허세(등록)","재산권을 등기·등록하는 때","신고하는 때"],["재산세","과세기준일(6월 1일)","지방자치단체가 결정하는 때"],["종합부동산세","과세기준일(6월 1일)","정부 결정, 신고납부를 택하면 신고하는 때"],["소득세(양도소득세 포함)","과세기간이 끝나는 때","신고하는 때"],["예정신고하는 소득세","과세표준이 되는 금액이 발생한 달의 말일","신고하는 때"]]},{"종류":"흐름","제목":"종합부동산세 부과·신고납부 절차","단계":[{"이름":"과세기준일","설명":"6월 1일. 이날 주택분 재산세 납세의무자가 종합부동산세 납세의무자다."},{"이름":"합산배제·특례 신청","설명":"9월 16일부터 9월 30일까지 관할세무서장에게 합산배제 주택 보유현황 신고, 1세대 1주택자 특례 신청."},{"이름":"고지서 발급","설명":"납부기간 개시 5일 전까지 발급한다. 납부기간은 12월 1일부터 12월 15일."},{"이름":"신고납부 선택","설명":"12월 1일부터 12월 15일까지 신고하면 정부의 결정은 없었던 것으로 보고, 신고하는 때 세액이 확정된다."},{"이름":"분납","설명":"납부할 세액이 250만원을 초과하면 납부기한이 지난 날부터 6개월 이내에 나누어 낼 수 있다."}]}],"함정":"4번은 40만원이라 면세라고 보고 틀린 문장으로 고르는 경우가 많다. 면세점(50만원 이하)은 취득세에 있고, 그 물건의 등기는 등록면허세 대상으로 넘어온다. 3번의 12월 1일~15일은 맞는 신고 기한이다. 5번은 확정신고를 거쳐야 확정된다고 보면 옳은 문장처럼 보인다."}},{"i":"S2-2-2-세법-02","r":"S2","g":3,"c":2,"n":26,"s":"세법","q":"국세기본법령상 국세의 부과제척기간에 관한 설명으로 옳은 것은?","b":null,"bs":"없음","img":[],"ch":["납세자가 「조세범 처벌법」에 따른 사기나 그 밖의 부정한 행위로 종합소득세를 포탈하는 경우(역외거래 제외) 그 국세를 부과할 수 있는 날부터 15년을 부과제척기간으로 한다.","지방국세청장은 「행정소송법」에 따른 소송에 대한 판결이 확정된 경우 그 판결이 확정된 날부터 2년이 지나기전까지 경정이나 그 밖에 필요한 처분을 할 수 있다.","세무서장은 「감사원법」에 따른 심사청구에 대한 결정에 의하여 명의대여 사실이 확인되는 경우에는 당초의 부과처분을 취소하고 그 결정이 확정된 날부터 1년 이내에 실제로 사업을 경영한 자에게 경정이나 그 밖에 필요한 처분을 할 수 있다.","종합부동산세의 경우 부과제척기간의 기산일은 과세표준과 세액에 대한 신고기한의 다음 날이다.","납세자가 법정신고기한까지 과세표준신고서를 제출하지 아니한 경우(역외거래 제외)에는 해당 국세를 부과할 수 있는 날부터 10년을 부과제척기간으로 한다."],"a":[3],"L":"세1-1","o":"기출","x":{"한줄":"감사원법에 따른 심사청구 결정으로 명의대여 사실이 확인되면, 결정이 확정된 날부터 1년 이내에 당초 처분을 취소하고 실제 경영자에게 경정 등을 할 수 있다.","근거":[{"법령":"국세기본법","조문":"제26조의2제7항","원문":"⑦ 제1항부터 제5항까지의 규정에도 불구하고 제6항제1호의 결정 또는 판결에 의하여 다음 각 호의 어느 하나에 해당하게 된 경우에는 당초의 부과처분을 취소하고 그 결정 또는 판결이 확정된 날부터 1년 이내에 다음 각 호의 구분에 따른 자에게 경정이나 그 밖에 필요한 처분을 할 수 있다."},{"법령":"국세기본법","조문":"제26조의2제7항제1호","원문":"1. 명의대여 사실이 확인된 경우: 실제로 사업을 경영한 자"},{"법령":"국세기본법","조문":"제26조의2제6항제1호","원문":"1. 제7장에 따른 이의신청, 심사청구, 심판청구, 「감사원법」에 따른 심사청구 또는 「행정소송법」에 따른 소송에 대한 결정이나 판결이 확정된 경우: 결정 또는 판결이 확정된 날부터 1년"},{"법령":"국세기본법","조문":"제26조의2제2항제1호","원문":"1. 납세자가 법정신고기한까지 과세표준신고서를 제출하지 아니한 경우: 해당 국세를 부과할 수 있는 날부터 7년(역외거래의 경우 10년)"},{"법령":"국세기본법","조문":"제26조의2제2항제2호","원문":"2. 납세자가 대통령령으로 정하는 사기나 그 밖의 부정한 행위(이하 \"부정행위\"라 한다)로 국세를 포탈(逋脫)하거나 환급ㆍ공제를 받은 경우: 그 국세를 부과할 수 있는 날부터 10년(역외거래에서 발생한 부정행위로 국세를 포탈하거나 환급ㆍ공제받은 경우에는 15년)"},{"법령":"국세기본법 시행령","조문":"제12조의3제1항제2호","원문":"2. 종합부동산세 및 인지세의 경우 해당 국세의 납세의무가 성립한 날"}],"선지":[{"번호":1,"판정":"틀림","설명":"부정행위로 종합소득세를 포탈한 경우 부과제척기간은 10년이다. 15년은 역외거래에서 발생한 부정행위일 때만 적용한다(국세기본법 제26조의2제2항제2호)."},{"번호":2,"판정":"틀림","설명":"소송 판결이 확정되면 확정일부터 1년이 지나기 전까지 경정 등 필요한 처분을 할 수 있다. 2년이 아니다(국세기본법 제26조의2제6항제1호)."},{"번호":3,"판정":"옳음","설명":"감사원법에 따른 심사청구 결정으로 명의대여가 확인되면 당초 부과처분을 취소하고 결정 확정일부터 1년 이내에 실제 사업 경영자에게 경정 등을 한다(국세기본법 제26조의2제7항제1호)."},{"번호":4,"판정":"틀림","설명":"종합부동산세는 신고기한 다음 날이 아니라 납세의무 성립일(과세기준일 6월 1일)부터 제척기간을 센다(국세기본법 시행령 제12조의3제1항제2호)."},{"번호":5,"판정":"틀림","설명":"법정신고기한까지 신고서를 내지 않은 경우 제척기간은 7년이고, 역외거래일 때 10년이다(국세기본법 제26조의2제2항제1호)."}],"개념":[{"종류":"표","제목":"부과제척기간 한눈에","머리":["사유","국세(역외거래 아님)","국세(역외거래)","지방세"],"행":[["원칙","5년","7년","5년"],["법정신고기한까지 무신고","7년","10년","7년(상속·증여·명의신탁·과점주주 취득은 10년)"],["사기·부정행위로 포탈·환급","10년","15년","10년"],["상속세·증여세","10년(부정행위·미신고·거짓신고는 15년)","-","-"],["기산일(신고하는 국세)","신고기한 다음 날","-","부과할 수 있는 날(대통령령)"],["기산일(종합부동산세·인지세)","납세의무 성립일","-","-"]]},{"종류":"표","제목":"제척기간이 지나도 처분이 가능한 경우(국세)","머리":["사유","처분 가능 기간","처분 상대방"],"행":[["이의신청·심사청구·심판청구·감사원 심사청구·행정소송 결정·판결 확정","확정일부터 1년","-"],["위 결정·판결로 명의대여 사실 확인","확정일부터 1년(당초 처분 취소)","실제로 사업을 경영한 자"],["위 결정·판결로 재산 귀속이 명의일 뿐임이 확인","확정일부터 1년(당초 처분 취소)","재산의 사실상 귀속자"],["국제조세 경정청구·조정권고","청구일·권고일부터 2개월","-"],["조세조약 상호합의 종결","절차 종료일부터 1년","-"]]}],"함정":"1번은 15년을 부정행위 일반의 기간으로 외우면 고르게 된다. 15년은 역외거래에서 발생한 부정행위, 상속·증여세의 특수 사유에 붙는 숫자다. 2번은 1년을 2년으로 바꿨고, 4번은 종합부동산세를 다른 신고 세목처럼 신고기한 다음 날로 센 것이다."}},{"i":"S2-2-2-세법-03","r":"S2","g":3,"c":2,"n":27,"s":"세법","q":"지방세법령상 취득세 과세물건의 취득시기에 관한 설명으로 틀린 것은? (단, 취득 후 계약 해제는 고려하지 않음)","b":null,"bs":"없음","img":[],"ch":["증여로 인한 취득은 그 계약일에, 상속으로 인한 취득은 상속개시일에 취득한 것으로 본다.","유상승계취득은 사실상의 잔금지급일에 취득한 것으로 보며, 사실상의 잔금지급일을 확인할 수 없고 계약상 잔금지급일도 명시되지 않은 경우에는 계약일부터 60일이 지난 날에 취득한 것으로 본다.","건축물을 건축하여 취득하는 경우에는 사용승인서를 내주는 날과 사실상의 사용일 중 빠른 날을 취득일로 본다.","「민법」 제245조에 따른 점유로 인한 부동산 취득은 점유를 개시한 날을 취득일로 본다.","매립ㆍ간척으로 토지를 원시취득하는 경우 공사준공인가일 전에 사용승낙을 받았다면 사용승낙일과 사실상 사용일 중 빠른 날을 취득일로 본다."],"a":[4],"L":"세2-1","o":"변형","x":{"한줄":"점유로 인한 취득은 점유개시일이 아니라 취득물건의 등기일 또는 등록일을 취득일로 본다.","근거":[{"법령":"지방세법 시행령","조문":"제20조제12항","원문":"⑫ 「민법」 제245조 및 제247조에 따른 점유로 인한 취득의 경우에는 취득물건의 등기일 또는 등록일을 취득일로 본다."},{"법령":"지방세법 시행령","조문":"제20조제1항","원문":"무상취득의 경우에는 그 계약일(상속 또는 유증으로 인한 취득의 경우에는 상속 또는 유증 개시일을 말한다)에 취득한 것으로 본다."},{"법령":"지방세법 시행령","조문":"제20조제2항","원문":"② 유상승계취득의 경우에는 사실상의 잔금지급일(신고인이 제출한 자료로 사실상의 잔금지급일을 확인할 수 없는 경우에는 계약상의 잔금지급일을 말하고, 계약상 잔금 지급일이 명시되지 않은 경우에는 계약일부터 60일이 경과한 날을 말한다)에 취득한 것으로 본다."},{"법령":"지방세법 시행령","조문":"제20조제6항","원문":"…를 내주는 날(사용승인서를 내주기 전에 임시사용승인을 받은 경우에는 그 임시사용승인일을 말하고, 사용승인서 또는 임시사용승인서를 받을 수 없는 건축물의 경우에는 사실상 사용이 가능한 날을 말한다)과 사실상의 사용일 중 빠른 날을 취득일로 본다."},{"법령":"지방세법 시행령","조문":"제20조제8항","원문":"⑧ 관계 법령에 따라 매립ㆍ간척 등으로 토지를 원시취득하는 경우에는 공사준공인가일을 취득일로 본다. 다만, 공사준공인가일 전에 사용승낙ㆍ허가를 받거나 사실상 사용하는 경우에는 사용승낙일ㆍ허가일 또는 사실상 사용일 중 빠른 날을 취득일로 본다."}],"선지":[{"번호":1,"판정":"옳음","설명":"무상취득은 계약일, 상속·유증은 개시일이 취득일이다(시행령 제20조제1항)."},{"번호":2,"판정":"옳음","설명":"잔금지급일은 사실상 지급일, 확인이 안 되면 계약상 지급일, 계약서에 없으면 계약일부터 60일이 지난 날 순서로 정한다(시행령 제20조제2항)."},{"번호":3,"판정":"옳음","설명":"건축·개수는 사용승인서(임시사용승인이면 그날)를 내주는 날과 사실상의 사용일 중 빠른 날이다(시행령 제20조제6항)."},{"번호":4,"판정":"틀림","설명":"민법상 점유취득시효로 취득하는 경우는 점유개시일이 아니라 취득물건의 등기일 또는 등록일이 취득일이다(시행령 제20조제12항)."},{"번호":5,"판정":"옳음","설명":"매립·간척 원시취득은 공사준공인가일이 원칙이고, 그 전에 사용승낙·허가를 받거나 사실상 사용하면 그 날들 중 빠른 날이다(시행령 제20조제8항)."}],"개념":[{"종류":"표","제목":"취득 유형별 취득일","머리":["취득 유형","취득일","근거"],"행":[["무상취득(증여 등)","계약일","시행령 제20조제1항"],["상속·유증","상속·유증 개시일","시행령 제20조제1항"],["유상승계취득","사실상 잔금지급일(확인 불가 시 계약상 잔금지급일, 명시 없으면 계약일부터 60일 경과한 날)","시행령 제20조제2항"],["연부취득","사실상 연부금 지급일","시행령 제20조제5항"],["건축·개수","사용승인서(임시사용승인이면 그날)를 내주는 날과 사실상 사용일 중 빠른 날","시행령 제20조제6항"],["주택조합 비조합원용 토지","주택법 제49조에 따른 사용검사를 받은 날","시행령 제20조제7항"],["재건축조합 비조합원용 토지","소유권이전 고시일의 다음 날","시행령 제20조제7항"],["매립·간척 원시취득","공사준공인가일(그 전 사용승낙·허가·사실상 사용이 있으면 그중 빠른 날)","시행령 제20조제8항"],["토지 지목변경","사실상 변경일과 공부상 변경일 중 빠른 날(그 전에 사용한 부분은 사실상 사용일)","시행령 제20조제10항"],["점유취득시효·재산분할","등기일 또는 등록일","시행령 제20조제12항·제13항"],["취득일 전에 등기·등록한 경우(무상·유상승계·연부)","그 등기일 또는 등록일","시행령 제20조제14항"]]},{"종류":"흐름","제목":"유상승계취득의 취득일 판단 순서","단계":[{"이름":"사실상 잔금지급일","설명":"신고인이 낸 자료로 사실상 잔금지급일이 확인되면 그날이 취득일이다."},{"이름":"계약상 잔금지급일","설명":"사실상 지급일을 확인할 수 없으면 계약서에 적힌 잔금지급일이 취득일이다."},{"이름":"계약일부터 60일이 지난 날","설명":"계약서에 잔금지급일이 없으면 계약일부터 60일이 경과한 날이다."},{"이름":"등기·등록 선행 여부","설명":"위 날짜보다 먼저 등기·등록했으면 그 등기일 또는 등록일에 취득한 것으로 본다."}]}],"함정":"4번은 민법상 점유취득시효에서 점유를 시작한 날을 취득일로 생각하면 옳게 읽힌다. 시효취득은 등기를 해야 소유권이 생기므로 등기일이 취득일이다. 5번의 '빠른 날'을 '늦은 날'로 바꿔 읽는 실수도 잦다."}},{"i":"S2-2-2-세법-04","r":"S2","g":3,"c":2,"n":28,"s":"세법","q":"지방세법상 취득세와 등록면허세의 신고ㆍ납부에 관한 설명으로 옳은 것은? (단, 주어진 조건 외에는 고려하지 않음)","b":null,"bs":"없음","img":[],"ch":["증여로 부동산을 취득한 자는 취득일부터 60일 이내에 과세표준과 세액을 신고ㆍ납부하여야 한다.","외국에 주소를 둔 상속인이 있는 경우 상속으로 취득세 과세물건을 취득한 자는 상속개시일이 속하는 달의 말일부터 9개월 이내에 과세표준과 세액을 신고ㆍ납부하여야 한다.","취득세 과세물건을 사실상 취득한 후 신고하지 아니하고 매각하는 경우에는 산출세액에 100분의 80을 가산한 금액에 무신고가산세를 따로 합하여 징수한다.","등록면허세 과세물건을 등록한 후 대도시 중과세율의 적용대상이 되었을 때에는 대통령령으로 정하는 날부터 30일 이내에 중과세율을 적용한 세액에서 이미 납부한 세액을 공제한 금액을 신고ㆍ납부하여야 한다.","채권자대위자가 납세의무자를 대위하여 부동산 취득에 대한 취득세를 신고납부한 경우, 지방자치단체의 장은 그 사실을 납세의무자에게 통보하지 아니할 수 있다."],"a":[2],"L":"세2-1","o":"변형","x":{"한줄":"상속으로 취득한 경우 신고·납부기한은 상속개시일이 속하는 달의 말일부터 6개월이고, 외국에 주소를 둔 상속인이 있으면 9개월이다.","근거":[{"법령":"지방세법","조문":"제20조제1항","원문":"무상취득(상속은 제외한다) 또는 증여자의 채무를 인수하는 부담부 증여로 인한 취득의 경우는 취득일이 속하는 달의 말일부터 3개월, 상속으로 인한 경우는 상속개시일이 속하는 달의 말일부터, 실종으로 인한 경우는 실종선고일이 속하는 달의 말일부터 각각 6개월(외국에 주소를 둔 상속인이 있는 경우에는 각각 9개월)"},{"법령":"지방세법","조문":"제21조제2항","원문":"② 납세의무자가 취득세 과세물건을 사실상 취득한 후 제20조에 따른 신고를 하지 아니하고 매각하는 경우에는 제1항 및 「지방세기본법」 제53조, 제55조에도 불구하고 산출세액에 100분의 80을 가산한 금액을 세액으로 하여 보통징수의 방법으로 징수한다."},{"법령":"지방세법","조문":"제30조제2항","원문":"② 등록면허세 과세물건을 등록한 후에 해당 과세물건이 제28조제2항에 따른 세율의 적용대상이 되었을 때에는 대통령령으로 정하는 날부터 60일 이내에 제28조제2항에 따른 세율을 적용하여 산출한 세액에서 이미 납부한 세액(가산세는 제외한다)을 공제한 금액을 세액으로 하여 납세지를 관할하는 지방자치단체의 장에게 대통령령으로 정하는 바에 따라 신고하고 납부하여야 한다."},{"법령":"지방세법","조문":"제20조제6항","원문":"⑥ 지방자치단체의 장은 제5항에 따른 채권자대위자의 신고납부가 있는 경우 납세의무자에게 그 사실을 즉시 통보하여야 한다."}],"선지":[{"번호":1,"판정":"틀림","설명":"증여 같은 무상취득의 신고·납부기한은 취득일이 속하는 달의 말일부터 3개월이다. 60일은 유상취득의 기한이다(지방세법 제20조제1항)."},{"번호":2,"판정":"옳음","설명":"상속은 상속개시일이 속하는 달의 말일부터 6개월, 외국에 주소를 둔 상속인이 있으면 9개월이다(지방세법 제20조제1항)."},{"번호":3,"판정":"틀림","설명":"신고 없이 매각하면 산출세액에 100분의 80을 가산해 징수하고, 지방세기본법상 무신고가산세·납부지연가산세는 따로 붙이지 않는다(지방세법 제21조제2항)."},{"번호":4,"판정":"틀림","설명":"중과세율 적용대상이 된 때의 신고·납부기한은 대통령령으로 정하는 날부터 60일 이내다. 이미 납부한 세액을 공제할 때 가산세는 뺀다(지방세법 제30조제2항)."},{"번호":5,"판정":"틀림","설명":"채권자대위자의 신고납부가 있으면 지방자치단체의 장은 납세의무자에게 그 사실을 즉시 통보하여야 한다(지방세법 제20조제6항)."}],"개념":[{"종류":"표","제목":"취득세 신고·납부기한","머리":["사유","기한"],"행":[["유상취득 등 일반","취득일부터 60일"],["무상취득(상속 제외)","취득일이 속하는 달의 말일부터 3개월"],["증여자의 채무를 인수하는 부담부 증여","취득일이 속하는 달의 말일부터 3개월"],["상속","상속개시일이 속하는 달의 말일부터 6개월(외국에 주소를 둔 상속인이 있으면 9개월)"],["실종","실종선고일이 속하는 달의 말일부터 6개월(외국 주소 상속인이 있으면 9개월)"],["취득 후 중과세율 적용대상이 된 경우","대통령령으로 정하는 날부터 60일 이내(이미 낸 세액은 가산세를 빼고 공제)"],["비과세·감면 후 추징대상이 된 경우","사유 발생일부터 60일 이내"],["신고·납부기한 이내에 등기·등록하려는 경우","등기·등록 신청서를 접수하는 날까지"]]},{"종류":"계산","제목":"신고 없이 매각한 경우 징수세액(취득세 본세 기준)","단계":[{"설명":"가정: 농지 외 토지를 매매로 5억원에 취득. 그 밖의 원인 농지 외의 세율은 1천분의 40","식":"5억원 × 4%","값":"산출세액 2,000만원"},{"설명":"신고 없이 매각하면 산출세액에 100분의 80을 가산한다","식":"2,000만원 × 80%","값":"가산액 1,600만원"},{"설명":"무신고가산세·납부지연가산세는 따로 붙이지 않는다","식":"2,000만원 + 1,600만원","값":"징수세액 3,600만원"}]}],"함정":"1번은 60일이 일반 기한인 점만 외워 증여에도 적용한 것이다. 3번은 100분의 80 가산에 무신고가산세를 더 얹은 것이다. 80% 가산은 무신고가산세·납부지연가산세 대신 적용한다. 5번은 대위자 신고납부 뒤 통보를 임의로 읽은 것이다. 4번은 30일과 60일, 가산세 포함 여부를 같이 바꿨다."}},{"i":"S2-2-2-세법-05","r":"S2","g":3,"c":2,"n":29,"s":"세법","q":"지방세법상 취득세의 납세의무에 관한 설명으로 틀린 것은?","b":null,"bs":"없음","img":[],"ch":["상속으로 취득하는 경우 상속인 각자가 상속받는 취득물건(지분)을 취득한 것으로 보며, 공동상속인은 연대하여 납부할 의무를 진다.","법인 설립 시에 발행하는 주식을 취득하여 과점주주가 된 경우에는 그 법인의 부동산등을 취득한 것으로 보지 아니한다.","직계비속이 직계존속의 부동산을 취득하는 경우 증여로 취득한 것으로 보되, 취득자의 소득으로 그 대가를 지급한 사실이 증명되면(대통령령으로 정하는 예외 제외) 유상으로 취득한 것으로 본다.","형제자매의 부동산을 매매로 취득하는 경우에도 증여로 취득한 것으로 본다.","주택조합이 조합원용으로 취득하는 조합주택용 부동산은 조합원이 취득한 것으로 보고, 조합원에게 귀속되지 아니하는 부동산은 주택조합이 취득한 것으로 본다."],"a":[4],"L":"세2-1","o":"변형","x":{"한줄":"증여 간주 규정은 배우자와 직계존비속 사이의 취득에만 적용하고, 형제자매 사이의 매매는 대상이 아니다.","근거":[{"법령":"지방세법","조문":"제7조제11항","원문":"⑪ 배우자 또는 직계존비속의 부동산등을 취득하는 경우에는 증여로 취득한 것으로 본다."},{"법령":"지방세법","조문":"제7조제11항제4호","원문":"4. 해당 부동산등의 취득을 위하여 그 대가를 지급한 사실이 다음 각 목의 어느 하나에 의하여 증명되는 경우."},{"법령":"지방세법","조문":"제7조제11항제4호가목","원문":"가. 그 대가를 지급하기 위한 취득자의 소득이 증명되는 경우"},{"법령":"지방세법","조문":"제7조제7항","원문":"상속인 각자가 상속받는 취득물건(지분을 취득하는 경우에는 그 지분에 해당하는 취득물건을 말한다)을 취득한 것으로 본다. 이 경우 상속인의 납부의무에 관하여는 「지방세기본법」 제44조제1항 및 제5항을 준용한다."},{"법령":"지방세법","조문":"제7조제5항","원문":"(법인설립 시에 발행하는 주식 또는 지분을 취득함으로써 과점주주가 된 경우에는 취득으로 보지 아니한다)"},{"법령":"지방세법","조문":"제7조제8항","원문":"해당 조합원용으로 취득하는 조합주택용 부동산(공동주택과 부대시설ㆍ복리시설 및 그 부속토지를 말한다)은 그 조합원이 취득한 것으로 본다. 다만, 조합원에게 귀속되지 아니하는 부동산(이하 이 장에서 \"비조합원용 부동산\"이라 한다)은 제외한다."}],"선지":[{"번호":1,"판정":"옳음","설명":"상속은 상속인 각자가 자기 지분을 취득한 것으로 보고, 납부의무는 지방세기본법 제44조의 연대납세의무 규정을 준용한다(지방세법 제7조제7항)."},{"번호":2,"판정":"옳음","설명":"법인 설립 때 발행하는 주식을 취득해서 과점주주가 된 경우는 간주취득에서 뺀다(지방세법 제7조제5항)."},{"번호":3,"판정":"옳음","설명":"직계존비속 간 취득은 증여로 보는 것이 원칙이고, 취득자의 소득으로 대가를 지급한 사실이 증명되면 유상이다. 대가가 시가인정액보다 3억원 이상 또는 100분의 30 이상 낮은 범위에서 대통령령으로 정하는 경우는 유상에서 빠진다(지방세법 제7조제11항제4호)."},{"번호":4,"판정":"틀림","설명":"증여 간주 규정의 대상은 배우자와 직계존비속뿐이다. 형제자매는 포함되지 않으므로 매매로 취득하면 유상취득이다(지방세법 제7조제11항)."},{"번호":5,"판정":"옳음","설명":"조합원용 조합주택용 부동산은 조합원이 취득한 것으로 보고, 비조합원용 부동산은 그 간주에서 제외되어 주택조합이 취득자가 된다(지방세법 제7조제8항)."}],"개념":[{"종류":"표","제목":"배우자·직계존비속 간 취득의 증여 간주와 유상 예외","머리":["구분","취득 원인 판단"],"행":[["배우자·직계존비속 간 매매","증여로 취득한 것으로 본다(원칙)"],["공매(경매 포함)로 취득","전체를 유상으로 본다"],["파산선고로 처분되는 부동산 취득","전체를 유상으로 본다"],["등기·등록이 필요한 부동산끼리 교환","전체를 유상으로 본다"],["소득·재산 처분·담보·이미 과세받은 상속·증여재산 등으로 대가 지급이 증명됨","유상. 단 대가가 시가인정액보다 3억원 이상 또는 100분의 30 이상 낮은 범위로서 대통령령이 정하는 경우는 제외"],["형제자매 간 매매","간주 규정의 대상이 아니다"],["증여자의 채무를 인수하는 부담부증여(배우자·직계존비속 제외)","채무액 상당 부분은 유상, 나머지는 무상"]]},{"종류":"비교","제목":"주택조합등 조합원용·비조합원용 부동산","왼쪽":{"이름":"조합원용 부동산","항목":["대상: 조합주택용 부동산(공동주택, 부대시설·복리시설, 부속토지)","취득자: 그 조합원","주택조합등이 취득해도 조합원이 취득한 것으로 본다"]},"오른쪽":{"이름":"비조합원용 부동산","항목":["대상: 조합원에게 귀속되지 아니하는 부동산","취득자: 주택조합등","토지 취득일: 주택조합은 사용검사를 받은 날, 재건축조합은 소유권이전 고시일의 다음 날(시행령 제20조제7항)"]}}],"함정":"3번은 직계존비속 사이의 취득이 모두 증여라고 외우면 틀린 문장으로 읽는다. 유상으로 인정되는 사유가 따로 있다. 4번은 가족 사이의 거래를 모두 증여로 확장한 것이다. 규정이 적용되는 범위는 배우자와 직계존비속뿐이다.","개정":"배우자·직계존비속 간 유상취득 인정에는 2025.12.31 개정으로 대가가 시가인정액보다 3억원 이상 또는 100분의 30 이상 낮은 범위에서 대통령령으로 정하는 경우를 제외하는 단서가 붙었다(지방세법 제7조제11항제4호 단서)."}},{"i":"S2-2-2-세법-06","r":"S2","g":3,"c":2,"n":30,"s":"세법","q":"지방세법령상 등록면허세에 관한 설명으로 옳은 것은?","b":null,"bs":"없음","img":[],"ch":["취득가액이 50만원인 토지의 소유권 이전등기를 하는 자는 등록면허세 납세의무가 없다.","부동산 등기에 대한 등록면허세의 납세지는 소유자의 주소지이다.","부동산 등기에 대한 등록면허세의 과세표준은 취득당시의 가액으로 한다.","월 임대차금액의 1천분의 2로 계산한 임차권 설정등기의 등록면허세액이 11만2천500원보다 적을 때에는 11만2천500원으로 한다.","채권자대위자는 납세의무자를 대위하여 부동산의 등기에 대한 등록면허세를 신고납부할 수 있다."],"a":[5],"L":"세2-2","o":"기출","x":{"한줄":"채권자대위권으로 등기를 신청하려는 채권자는 납세의무자를 대위하여 부동산 등기의 등록면허세를 신고납부할 수 있다.","근거":[{"법령":"지방세법","조문":"제30조제5항","원문":"⑤ 채권자대위자는 납세의무자를 대위하여 부동산의 등기에 대한 등록면허세를 신고납부할 수 있다."},{"법령":"지방세법","조문":"제23조제1호라목","원문":"라. 제17조에 해당하는 물건의 등기 또는 등록"},{"법령":"지방세법","조문":"제17조제1항","원문":"① 취득가액이 50만원 이하일 때에는 취득세를 부과하지 아니한다."},{"법령":"지방세법","조문":"제25조제1항제1호","원문":"1. 부동산 등기: 부동산 소재지"},{"법령":"지방세법","조문":"제27조제1항","원문":"① 부동산, 선박, 항공기, 자동차 및 건설기계의 등록에 대한 등록면허세(이하 이 절에서 \"등록면허세\"라 한다)의 과세표준은 등록 당시의 가액으로 한다."},{"법령":"지방세법","조문":"제28조제1항","원문":"다만, 제1호부터 제5호까지 및 제5호의2의 규정에 따라 산출한 세액이 해당 각 호의 그 밖의 등기 또는 등록 세율보다 적을 때에는 그 밖의 등기 또는 등록 세율을 적용한다."},{"법령":"지방세법","조문":"제28조제1항제1호마목","원문":"마. 그 밖의 등기: 건당 6천원"}],"선지":[{"번호":1,"판정":"틀림","설명":"취득가액 50만원 이하는 취득세를 부과하지 않는 면세점이고, 그 물건의 소유권 이전등기는 등록면허세 과세대상이 된다. 납세의무가 있다(지방세법 제23조제1호라목, 제17조제1항)."},{"번호":2,"판정":"틀림","설명":"부동산 등기에 대한 등록면허세의 납세지는 부동산 소재지다(지방세법 제25조제1항제1호)."},{"번호":3,"판정":"틀림","설명":"과세표준은 등록 당시의 가액이다. 취득당시가액은 취득을 원인으로 하는 등록(제23조제1호 각 목)에서 쓴다(지방세법 제27조제1항·제3항)."},{"번호":4,"판정":"틀림","설명":"부동산 등기의 세액이 그 밖의 등기 세율보다 적으면 건당 6천원을 적용한다. 11만2천500원은 영리법인 설립·합병 등기의 최저세액이다(지방세법 제28조제1항)."},{"번호":5,"판정":"옳음","설명":"채권자대위자는 납세의무자를 대위하여 부동산 등기의 등록면허세를 신고납부할 수 있고, 지방자치단체의 장은 그 사실을 납세의무자에게 즉시 통보한다(지방세법 제30조제5항·제6항)."}],"개념":[{"종류":"표","제목":"부동산 등기 등록면허세 표준세율","머리":["등기","과세표준","세율"],"행":[["소유권 보존","부동산 가액","1천분의 8"],["소유권 이전(유상)","부동산 가액","1천분의 20(유상 주택은 주택 취득세율의 100분의 50)"],["소유권 이전(무상)","부동산 가액","1천분의 15"],["소유권 이전(상속)","부동산 가액","1천분의 8"],["지상권","부동산 가액","1천분의 2"],["저당권","채권금액","1천분의 2"],["지역권","요역지 가액","1천분의 2"],["전세권","전세금액","1천분의 2"],["임차권","월 임대차금액","1천분의 2"],["경매신청·가압류·가처분","채권금액","1천분의 2"],["그 밖의 등기","건당","6천원"]]},{"종류":"비교","제목":"취득세와 등록면허세(부동산)","왼쪽":{"이름":"취득세","항목":["납세의무자: 부동산등을 취득한 자","납세지: 부동산 소재지","과세표준: 취득당시가액","면세점: 취득가액 50만원 이하","신고·납부: 취득일부터 60일 등"]},"오른쪽":{"이름":"등록면허세(등록)","항목":["납세의무자: 등록을 하는 자","납세지: 부동산 소재지","과세표준: 등록 당시의 가액(신고가 없거나 시가표준액보다 적으면 시가표준액)","취득세 면세점 이하 물건의 등기에도 과세","신고·납부: 등록을 하기 전까지"]}}],"함정":"1번은 등록면허세에도 면세점이 있다고 보고 옳은 문장으로 처리하는 경우가 많다. 면세점은 취득세에 있고, 그 때문에 등기가 등록면허세로 넘어온다. 4번의 11만2천500원은 법인 설립 등기 숫자를 임차권에 끌어온 함정이다."}},{"i":"S2-2-2-세법-07","r":"S2","g":3,"c":2,"n":31,"s":"세법","q":"지방세법상 재산세 과세대상에 대한 표준세율 적용에 관한 설명으로 옳은 것은?","b":null,"bs":"없음","img":[],"ch":["종합합산과세대상 토지는 납세의무자가 전국에 소유한 종합합산과세대상 토지의 가액을 모두 합한 금액을 과세표준으로 하여 세율을 적용한다.","주택의 토지와 건물의 소유자가 다른 경우 해당 주택의 토지와 건물의 가액을 합산한 과세표준에 주택의 세율을 적용한다.","분리과세대상 토지는 납세의무자가 해당 지방자치단체 관할구역에 소유한 분리과세대상 토지의 가액을 모두 합한 금액을 과세표준으로 하여 세율을 적용한다.","납세의무자가 해당 지방자치단체 관할구역에 2개 이상의 주택을 소유한 경우 그 주택의 가액을 모두 합한 금액을 과세표준으로 하여 주택의 세율을 적용한다.","건축물에 대한 재산세는 건축물의 가액에 따라 4단계 초과누진세율을 적용한다."],"a":[2],"L":"세2-3","o":"변형","x":{"한줄":"토지와 건물의 소유자가 달라도 주택은 하나의 과세대상이므로 토지와 건물 가액을 합산한 과세표준에 주택 세율을 적용한다.","근거":[{"법령":"지방세법","조문":"제113조제3항","원문":"③ 주택을 2명 이상이 공동으로 소유하거나 토지와 건물의 소유자가 다를 경우 해당 주택에 대한 세율을 적용할 때 해당 주택의 토지와 건물의 가액을 합산한 과세표준에 제111조제1항제3호의 세율 또는 제111조의2제1항의 세율을 적용한다."},{"법령":"지방세법","조문":"제113조제1항제1호","원문":"1. 종합합산과세대상: 납세의무자가 소유하고 있는 해당 지방자치단체 관할구역에 있는 종합합산과세대상이 되는 토지의 가액을 모두 합한 금액을 과세표준으로 하여 제111조제1항제1호가목의 세율을 적용한다."},{"법령":"지방세법","조문":"제113조제1항제3호","원문":"3. 분리과세대상: 분리과세대상이 되는 해당 토지의 가액을 과세표준으로 하여 제111조제1항제1호다목의 세율을 적용한다."},{"법령":"지방세법","조문":"제113조제2항","원문":"② 주택에 대한 재산세는 주택별로 제111조제1항제3호의 세율 또는 제111조의2제1항의 세율을 적용한다."},{"법령":"지방세법","조문":"제111조제1항제2호다목","원문":"다. 그 밖의 건축물: 과세표준의 1천분의 2.5"}],"선지":[{"번호":1,"판정":"틀림","설명":"합산 범위는 전국이 아니라 해당 지방자치단체 관할구역에 있는 토지다(지방세법 제113조제1항제1호)."},{"번호":2,"판정":"옳음","설명":"공동소유이거나 토지와 건물의 소유자가 다른 주택은 토지와 건물의 가액을 합산한 과세표준에 주택 세율을 적용한다(지방세법 제113조제3항)."},{"번호":3,"판정":"틀림","설명":"분리과세대상은 합산하지 않고 해당 토지의 가액별로 세율을 적용한다(지방세법 제113조제1항제3호)."},{"번호":4,"판정":"틀림","설명":"주택은 주택별로 세율을 적용한다. 여러 채의 가액을 합산하지 않는다(지방세법 제113조제2항)."},{"번호":5,"판정":"틀림","설명":"건축물은 골프장·고급오락장용 1천분의 40, 일부 공장용 1천분의 5, 그 밖의 건축물 1천분의 2.5의 비례세율이다. 초과누진세율은 종합합산·별도합산 토지와 주택에만 있다(지방세법 제111조제1항)."}],"개념":[{"종류":"표","제목":"재산세 세율 적용 방법","머리":["대상","과세표준 합산","세율 형태"],"행":[["종합합산과세대상 토지","해당 지방자치단체 관할구역 안의 토지 가액 합산","3단계 초과누진(1천분의 2~5)"],["별도합산과세대상 토지","해당 지방자치단체 관할구역 안의 토지 가액 합산","3단계 초과누진(1천분의 2~4)"],["분리과세대상 토지","토지별로 적용","비례(1천분의 0.7·2·40)"],["건축물","건축물별","비례(1천분의 2.5·5·40)"],["주택","주택별(공동소유·토지와 건물 소유자 상이 시 토지와 건물 가액 합산)","4단계 초과누진(1천분의 1~4)"],["선박","선박별","고급선박 1천분의 50, 그 밖의 선박 1천분의 3"],["항공기","항공기별","1천분의 3"]]},{"종류":"계산","제목":"초과누진세율 적용 예","단계":[{"설명":"주택 과세표준 1억5천만원. 6천만원 초과 1억5천만원 이하 구간은 6만원에 6천만원 초과금액의 1천분의 1.5를 더한다","식":"60,000원 + (1억5천만원 − 6천만원) × 0.15%","값":"60,000원 + 135,000원 = 195,000원"},{"설명":"별도합산 토지 과세표준 3억원. 2억원 초과 10억원 이하 구간은 40만원에 2억원 초과금액의 1천분의 3을 더한다","식":"400,000원 + (3억원 − 2억원) × 0.3%","값":"400,000원 + 300,000원 = 700,000원"}]}],"함정":"합산 단위를 묻는 문항이다. 토지는 종합합산·별도합산만 관할구역별로 합산하고 분리과세는 합산하지 않는다. 주택은 몇 채를 가졌든 주택별로 계산하되, 한 채를 공동소유하거나 토지와 건물 소유자가 다를 때만 토지와 건물 가액을 합친다. 5번은 건축물을 주택과 같은 누진 구조로 착각한 것이다."}},{"i":"S2-2-2-세법-08","r":"S2","g":3,"c":2,"n":32,"s":"세법","q":"지방세법령상 재산세의 표준세율에 관한 설명으로 틀린 것은? (단, 지방세관계법령상 감면 및 특례는 고려하지 않음)","b":null,"bs":"없음","img":[],"ch":["법령에서 정하는 고급선박 및 고급오락장용 건축물의 경우 고급선박의 표준세율이 고급오락장용 건축물의 표준세율보다 높다.","특별시 지역에서 「국토의 계획 및 이용에 관한 법률」과 그 밖의 관계 법령에 따라 지정된 주거지역 및 해당 지방자치단체의 조례로 정하는 지역의 대통령령으로 정하는 공장용 건축물의 표준세율은 과세표준의 1천분의 5이다.","주택(법령으로 정하는 1세대 1주택 아님)의 경우 표준세율은 최저 1천분의 1에서 최고 1천분의 4까지 4단계 초과누진세율로 적용한다.","항공기의 표준세율은 1천분의 3으로 법령에서 정하는 고급선박을 제외한 그 밖의 선박의 표준세율과 동일하다.","지방자치단체의 장은 특별한 재정수요나 재해 등의 발생으로 재산세의 세율 조정이 불가피하다고 인정되는 경우 조례로 정하는 바에 따라 표준세율의 100분의 50의 범위에서 가감할 수 있다. 다만, 가감한 세율은 해당연도를 포함하여 3년간 적용한다."],"a":[5],"L":"세2-3","o":"기출","x":{"한줄":"재산세 표준세율을 조례로 가감하는 경우 가감한 세율은 해당 연도에만 적용한다.","근거":[{"법령":"지방세법","조문":"제111조제3항","원문":"③ 지방자치단체의 장은 특별한 재정수요나 재해 등의 발생으로 재산세의 세율 조정이 불가피하다고 인정되는 경우 조례로 정하는 바에 따라 제1항의 표준세율의 100분의 50의 범위에서 가감할 수 있다. 다만, 가감한 세율은 해당 연도에만 적용한다."},{"법령":"지방세법","조문":"제111조제1항제4호가목","원문":"가. 제13조제5항제5호에 따른 고급선박: 과세표준의 1천분의 50"},{"법령":"지방세법","조문":"제111조제1항제2호가목","원문":"가. 제13조제5항에 따른 골프장, 고급오락장용 건축물: 과세표준의 1천분의 40"},{"법령":"지방세법","조문":"제111조제1항제2호나목","원문":"지정된 주거지역 및 해당 지방자치단체의 조례로 정하는 지역의 대통령령으로 정하는 공장용 건축물: 과세표준의 1천분의 5"},{"법령":"지방세법","조문":"제111조제1항제4호나목","원문":"나. 그 밖의 선박: 과세표준의 1천분의 3"},{"법령":"지방세법","조문":"제111조제1항제5호","원문":"5. 항공기: 과세표준의 1천분의 3"},{"법령":"지방세법","조문":"제111조의2제1항","원문":"대통령령으로 정하는 1세대 1주택(제4조제1항에 따른 시가표준액이 9억원 이하인 주택에 한정한다)에 대해서는 다음의 세율을 적용한다."}],"선지":[{"번호":1,"판정":"옳음","설명":"고급선박은 1천분의 50, 고급오락장용 건축물은 1천분의 40이다(지방세법 제111조제1항제4호가목, 제2호가목)."},{"번호":2,"판정":"옳음","설명":"특별시 등 지역의 주거지역과 조례로 정한 지역에 있는 대통령령 정한 공장용 건축물은 1천분의 5다(지방세법 제111조제1항제2호나목)."},{"번호":3,"판정":"옳음","설명":"1세대 1주택 특례(제111조의2)에 해당하지 않는 일반 주택은 과세표준 6천만원 이하 1천분의 1에서 3억원 초과 1천분의 4까지 4단계 초과누진세율이다(지방세법 제111조제1항제3호나목)."},{"번호":4,"판정":"옳음","설명":"항공기 1천분의 3은 고급선박을 뺀 그 밖의 선박의 세율과 같다(지방세법 제111조제1항제4호나목, 제5호)."},{"번호":5,"판정":"틀림","설명":"표준세율의 100분의 50 범위에서 가감한 세율은 해당 연도에만 적용한다. 3년간 적용하는 규정은 없다(지방세법 제111조제3항)."}],"개념":[{"종류":"표","제목":"재산세 표준세율","머리":["대상","세율"],"행":[["종합합산과세대상 토지","5천만원 이하 1천분의 2 / 1억원 이하 1천분의 3 / 1억원 초과 1천분의 5 (초과누진)"],["별도합산과세대상 토지","2억원 이하 1천분의 2 / 10억원 이하 1천분의 3 / 10억원 초과 1천분의 4 (초과누진)"],["분리과세 토지(전·답·과수원·목장용지·임야)","1천분의 0.7"],["분리과세 토지(골프장·고급오락장용)","1천분의 40"],["분리과세 토지(그 밖의 토지)","1천분의 2"],["건축물(골프장·고급오락장용)","1천분의 40"],["건축물(시 지역 주거지역 등의 공장용)","1천분의 5"],["건축물(그 밖)","1천분의 2.5"],["주택","6천만원 이하 1천분의 1 / 1억5천만원 이하 1천분의 1.5 / 3억원 이하 1천분의 2.5 / 3억원 초과 1천분의 4 (초과누진)"],["선박(고급선박 / 그 밖)","1천분의 50 / 1천분의 3"],["항공기","1천분의 3"]]},{"종류":"계산","제목":"주택 재산세 산출 예","단계":[{"설명":"주택 과세표준 4억원은 3억원 초과 구간이다. 57만원에 3억원 초과금액의 1천분의 4를 더한다","식":"570,000원 + (4억원 − 3억원) × 0.4%","값":"570,000원 + 400,000원 = 970,000원"}]}],"함정":"5번은 가감 범위(100분의 50)는 맞고 적용 기간만 3년으로 바꾼 문장이다. 숫자 하나만 틀려서 앞부분이 맞다는 이유로 넘기기 쉽다. 1번의 고급선박 1천분의 50과 고급오락장 1천분의 40은 순서를 바꿔 외우는 경우가 많다."}},{"i":"S2-2-2-세법-09","r":"S2","g":3,"c":2,"n":33,"s":"세법","q":"지방세법령상 재산세 과세기준일 현재 납세의무자로 틀린 것은?","b":null,"bs":"없음","img":[],"ch":["공부상에 개인 등의 명의로 등재되어 있는 사실상의 종중재산으로서 종중소유임을 신고하지 아니하였을 경우: 종중","상속이 개시된 재산으로서 상속등기가 이행되지 아니하고 사실상의 소유자를 신고하지 아니하였을 경우: 행정안전부령으로 정하는 주된 상속자","｢도시 및 주거환경정비법｣에 따른 정비사업(재개발사업만 해당한다)의 시행에 따른 환지계획에서 일정한 토지를 환지로 정하지 아니하고 체비지로 정한 경우: 사업시행자","｢채무자 회생 및 파산에 관한 법률｣에 따른 파산선고 이후 파산종결의 결정까지 파산재단에 속하는 재산의 경우: 공부상 소유자","지방자치단체와 재산세 과세대상 재산을 연부(年賦)로 매매계약을 체결하고 그 재산의 사용권을 무상으로 받은 경우: 그 매수계약자"],"a":[1],"L":"세2-3","o":"기출","x":{"한줄":"사실상 종중재산이라도 종중 소유임을 신고하지 않으면 재산세 납세의무자는 종중이 아니라 공부상 소유자다.","근거":[{"법령":"지방세법","조문":"제107조제2항제3호","원문":"3. 공부상에 개인 등의 명의로 등재되어 있는 사실상의 종중재산으로서 종중소유임을 신고하지 아니하였을 때에는 공부상 소유자"},{"법령":"지방세법","조문":"제107조제2항제2호","원문":"2. 상속이 개시된 재산으로서 상속등기가 이행되지 아니하고 사실상의 소유자를 신고하지 아니하였을 때에는 행정안전부령으로 정하는 주된 상속자"},{"법령":"지방세법","조문":"제107조제2항제6호","원문":"6. 「도시개발법」에 따라 시행하는 환지(換地) 방식에 의한 도시개발사업 및 「도시 및 주거환경정비법」에 따른 정비사업(재개발사업만 해당한다)의 시행에 따른 환지계획에서 일정한 토지를 환지로 정하지 아니하고 체비지 또는 보류지로 정한 경우에는 사업시행자"},{"법령":"지방세법","조문":"제107조제2항제8호","원문":"8. 「채무자 회생 및 파산에 관한 법률」에 따른 파산선고 이후 파산종결의 결정까지 파산재단에 속하는 재산의 경우 공부상 소유자"},{"법령":"지방세법","조문":"제107조제2항제4호","원문":"4. 국가, 지방자치단체, 지방자치단체조합과 재산세 과세대상 재산을 연부(年賦)로 매매계약을 체결하고 그 재산의 사용권을 무상으로 받은 경우에는 그 매수계약자"}],"선지":[{"번호":1,"판정":"틀림","설명":"종중 소유임을 신고하지 않은 사실상 종중재산은 공부상 소유자가 납세의무자다(지방세법 제107조제2항제3호)."},{"번호":2,"판정":"옳음","설명":"상속등기가 안 되고 사실상 소유자 신고도 없으면 행정안전부령으로 정하는 주된 상속자가 납부한다(지방세법 제107조제2항제2호)."},{"번호":3,"판정":"옳음","설명":"재개발사업 등의 환지계획에서 체비지·보류지로 정한 토지는 사업시행자가 납세의무자다(지방세법 제107조제2항제6호)."},{"번호":4,"판정":"옳음","설명":"파산선고 이후 파산종결 결정까지 파산재단 재산은 공부상 소유자가 납세의무자다(지방세법 제107조제2항제8호)."},{"번호":5,"판정":"옳음","설명":"국가·지방자치단체와 연부매매계약을 맺고 사용권을 무상으로 받았으면 그 매수계약자가 납세의무자다(지방세법 제107조제2항제4호)."}],"개념":[{"종류":"표","제목":"재산세 납세의무자 특례(과세기준일 현재)","머리":["상황","납세의무자"],"행":[["원칙","과세기준일 현재 재산을 사실상 소유하고 있는 자(공유재산은 지분권자)"],["소유권 변동 후 신고 없어 사실상 소유자를 알 수 없음","공부상 소유자"],["상속등기 안 되고 사실상 소유자 신고 없음","행정안전부령이 정하는 주된 상속자"],["사실상 종중재산을 개인 명의로 등재, 종중 소유 신고 없음","공부상 소유자"],["국가·지방자치단체·지방자치단체조합과 연부매매하고 사용권을 무상으로 받음","그 매수계약자"],["수탁자 명의 신탁재산","위탁자"],["도시개발 환지방식·재개발사업의 체비지·보류지","사업시행자"],["외국인 소유 항공기·선박을 임차하여 수입","수입하는 자"],["파산선고 이후 파산종결까지 파산재단 재산","공부상 소유자"]]},{"종류":"표","제목":"재산세 신고의무자(과세기준일부터 15일 이내)","머리":["신고 대상 사유","신고의무자"],"행":[["소유권 변동이 있었으나 과세기준일까지 등기·등록이 안 된 재산","공부상 소유자"],["상속이 개시되었으나 상속등기가 안 된 재산","주된 상속자"],["사실상 종중재산으로 공부상 개인 명의","공부상 소유자"],["수탁자 명의로 등기·등록된 신탁재산","수탁자"],["1세대가 2주택 이상 소유하면서 1세대 1주택 특례세율을 받으려는 경우","그 세대원"],["공부상 현황과 사실상 현황이 다르거나 변경된 경우","해당 재산의 사실상 소유자"]]}],"함정":"1번은 실제 주인이 종중이니 종중이 낸다고 보는 경우가 많다. 신고하지 않은 책임은 공부상 소유자가 진다. 3번은 체비지만 적혀 있지만 조문이 체비지 또는 보류지이므로 옳은 문장이다."}},{"i":"S2-2-2-세법-10","r":"S2","g":3,"c":2,"n":34,"s":"세법","q":"종합부동산세법상 종합부동산세에 관한 설명으로 틀린 것은? (단, 감면은 고려하지 않음)","b":null,"bs":"없음","img":[],"ch":["과세기준일 현재 종합합산과세대상 토지의 공시가격 합계액이 5억원인 토지분 재산세 납세의무자는 토지분 종합부동산세를 납부할 의무가 있다.","수탁자 명의로 등기된 신탁주택의 경우 위탁자가 종합부동산세를 납부할 의무가 있다.","종합부동산세를 신고납부방식으로 납부하려는 납세의무자가 해당 연도 12월 1일부터 12월 15일까지 과세표준과 세액을 신고한 경우 관할세무서장의 결정은 없었던 것으로 본다.","과세기준일 현재 만 70세 이상이면서 해당 주택을 15년 이상 보유한 1세대 1주택자의 연령별 공제와 보유기간별 공제는 공제율 합계 100분의 80의 범위에서 중복하여 적용할 수 있다.","관할세무서장은 종합부동산세로 납부할 세액이 600만원인 경우 최대 300만원의 세액을 납부기한이 지난 날부터 6개월 이내에 분납하게 할 수 있다."],"a":[1],"L":"세3-1","o":"변형","x":{"한줄":"종합합산과세대상 토지는 공시가격 합계액이 5억원을 '초과'해야 납세의무가 생기므로 딱 5억원이면 납세의무가 없다.","근거":[{"법령":"종합부동산세법","조문":"제12조제1항제1호","원문":"1. 종합합산과세대상인 경우에는 국내에 소재하는 해당 과세대상토지의 공시가격을 합한 금액이 5억원을 초과하는 자"},{"법령":"종합부동산세법","조문":"제7조제2항","원문":"이 경우 위탁자가 신탁주택을 소유한 것으로 본다."},{"법령":"종합부동산세법","조문":"제16조제3항","원문":"이 경우 제1항의 규정에 따른 결정은 없었던 것으로 본다."},{"법령":"종합부동산세법","조문":"제9조제5항","원문":"이 경우 제6항부터 제9항까지는 공제율 합계 100분의 80의 범위에서 중복하여 적용할 수 있다."},{"법령":"종합부동산세법","조문":"제9조제6항","원문":"⑥과세기준일 현재 만 60세 이상인 1세대 1주택자의 공제액은 제1항ㆍ제3항 및 제4항에 따라 산출된 세액에 다음 표에 따른 연령별 공제율을 곱한 금액으로 한다."},{"법령":"종합부동산세법","조문":"제20조","원문":"제20조(분납) 관할세무서장은 종합부동산세로 납부하여야 할 세액이 250만원을 초과하는 경우에는 대통령령으로 정하는 바에 따라 그 세액의 일부를 납부기한이 지난 날부터 6개월 이내에 분납하게 할 수 있다."},{"법령":"종합부동산세법 시행령","조문":"제16조제1항제2호","원문":"2. 납부하여야 할 세액이 5백만원을 초과하는 때에는 해당 세액의 100분의 50 이하의 금액"}],"선지":[{"번호":1,"판정":"틀림","설명":"종합합산과세대상 토지는 공시가격 합계액이 5억원을 초과해야 납세의무자가 된다. 5억원이면 해당하지 않는다(종합부동산세법 제12조제1항제1호)."},{"번호":2,"판정":"옳음","설명":"수탁자 명의 신탁주택은 위탁자가 납세의무자이고 위탁자가 그 주택을 소유한 것으로 본다(종합부동산세법 제7조제2항)."},{"번호":3,"판정":"옳음","설명":"12월 1일부터 12월 15일 사이에 신고납부방식으로 신고하면 정부의 결정은 없었던 것으로 본다(종합부동산세법 제16조제3항)."},{"번호":4,"판정":"옳음","설명":"만 70세 이상은 100분의 40, 15년 이상 보유는 100분의 50이어서 합치면 90이지만 공제율 합계는 100분의 80 범위에서만 중복 적용한다(종합부동산세법 제9조제5항·제6항·제8항)."},{"번호":5,"판정":"옳음","설명":"납부할 세액이 500만원을 초과하면 그 세액의 100분의 50 이하를 분납할 수 있다. 600만원이면 최대 300만원이다(종합부동산세법 제20조, 시행령 제16조제1항제2호)."}],"개념":[{"종류":"표","제목":"종합부동산세 과세표준 공제금액과 세율","머리":["구분","내용"],"행":[["주택 공제금액","1세대 1주택자 12억원 / 2.7%·5% 세율 적용 법인 0원 / 그 밖의 자 9억원"],["주택분 공정시장가액비율","100분의 60(시행령 제2조의4)"],["종합합산 토지 공제금액","5억원(납세의무자 요건은 공시가격 합계 5억원 초과)"],["별도합산 토지 공제금액","80억원(납세의무자 요건은 공시가격 합계 80억원 초과)"],["주택 세율(2주택 이하)","3억원 이하 1천분의 5 / 6억원 이하 1천분의 7 / 12억원 이하 1천분의 10 / 25억원 이하 1천분의 13 / 50억원 이하 1천분의 15 / 94억원 이하 1천분의 20 / 94억원 초과 1천분의 27"],["주택 세율(3주택 이상)","12억원 이하까지 위와 같고, 25억원 이하 1천분의 20 / 50억원 이하 1천분의 30 / 94억원 이하 1천분의 40 / 94억원 초과 1천분의 50"],["법인 주택 세율","2주택 이하 1천분의 27, 3주택 이상 1천분의 50(공익법인등 등은 일반 세율)"],["종합합산 토지 세율","15억원 이하 1천분의 10 / 45억원 이하 1천분의 20 / 45억원 초과 1천분의 30"],["별도합산 토지 세율","200억원 이하 1천분의 5 / 400억원 이하 1천분의 6 / 400억원 초과 1천분의 7"]]},{"종류":"계산","제목":"1세대 1주택자 공제율 한도와 분납","단계":[{"설명":"연령별 공제율(만 70세 이상)과 보유기간별 공제율(15년 이상)을 더한다","식":"40% + 50%","값":"90%"},{"설명":"공제율 합계는 100분의 80 범위에서만 중복 적용한다","식":"min(90%, 80%)","값":"80%"},{"설명":"납부할 세액 600만원은 500만원 초과이므로 100분의 50 이하를 분납할 수 있다","식":"600만원 × 50%","값":"최대 300만원"},{"설명":"납부할 세액 400만원은 250만원 초과 500만원 이하이므로 250만원을 뺀 금액이 분납 가능액이다","식":"400만원 − 250만원","값":"최대 150만원"}]}],"함정":"1번은 '5억원 이상'으로 읽기 쉽다. 토지분 납세의무자는 공시가격 합계가 종합합산 5억원 초과, 별도합산 80억원 초과다. 4번은 합계가 90이라 80을 넘는다는 이유로 틀렸다고 고르는 경우가 있으나 문장이 말하는 것은 '80의 범위에서 중복 적용'이다.","개정":"1세대 1주택자 연령·보유 공제율 합계 한도는 옛 기출의 100분의 70에서 현재 100분의 80으로 바뀌었다(종합부동산세법 제9조제5항)."}},{"i":"S2-2-2-세법-11","r":"S2","g":3,"c":2,"n":35,"s":"세법","q":"소득세법상 거주자가 국내에 있는 토지(비사업용 토지 아님)를 양도한 경우 양도소득세의 신고ㆍ납부에 관한 설명으로 틀린 것은? (단, 주어진 조건 외에는 고려하지 않음)","b":null,"bs":"없음","img":[],"ch":["양도일이 속하는 달의 말일부터 2개월 이내에 양도소득과세표준을 납세지 관할 세무서장에게 예정신고하여야 한다.","예정신고를 한 자는 해당 과세기간에 누진세율 적용대상 자산에 대한 예정신고를 2회 이상 하는 경우 등 대통령령으로 정하는 경우가 아니면 해당 소득에 대한 확정신고를 하지 아니할 수 있다.","토지거래계약에 관한 허가구역 안의 토지를 허가받기 전에 대금을 청산하고 양도한 경우 예정신고 기한은 대금을 청산한 날이 속하는 달의 말일부터 2개월이다.","예정신고납부할 세액이 1천500만원인 경우 500만원을 납부기한이 지난 후 2개월 이내에 분할납부할 수 있다.","해당 과세기간의 양도소득금액이 있는 거주자는 그 과세기간의 다음 연도 5월 1일부터 5월 31일까지 확정신고를 하여야 한다. 과세표준이 없거나 결손금액이 있는 경우에도 같다."],"a":[3],"L":"세3-2","o":"변형","x":{"한줄":"허가구역 토지를 허가받기 전에 대금을 청산한 경우 예정신고 기한은 대금청산일이 아니라 허가일(허가 전 지정 해제 시 해제일)이 속하는 달의 말일부터 2개월이다.","근거":[{"법령":"소득세법","조문":"제105조제1항제1호","원문":"1. 제94조제1항제1호ㆍ제2호ㆍ제4호 및 제6호에 따른 자산을 양도한 경우에는 그 양도일이 속하는 달의 말일부터 2개월. 다만, 「부동산 거래신고 등에 관한 법률」 제10조제1항에 따른 토지거래계약에 관한 허가구역에 있는 토지를 양도할 때 토지거래계약허가를 받기 전에 대금을 청산한 경우에는 그 허가일(토지거래계약허가를 받기 전에 허가구역의 지정이 해제된 경우에는 그 해제일을 말한다)이 속하는 달의 말일부터 2개월로 한다."},{"법령":"소득세법","조문":"제110조제1항","원문":"① 해당 과세기간의 양도소득금액이 있는 거주자는 그 양도소득 과세표준을 그 과세기간의 다음 연도 5월 1일부터 5월 31일까지"},{"법령":"소득세법","조문":"제110조제2항","원문":"② 제1항은 해당 과세기간의 과세표준이 없거나 결손금액이 있는 경우에도 적용한다."},{"법령":"소득세법","조문":"제110조제4항","원문":"④ 예정신고를 한 자는 제1항에도 불구하고 해당 소득에 대한 확정신고를 하지 아니할 수 있다. 다만, 해당 과세기간에 누진세율 적용대상 자산에 대한 예정신고를 2회 이상 하는 경우 등으로서 대통령령으로 정하는 경우에는 그러하지 아니하다."},{"법령":"소득세법","조문":"제112조","원문":"제112조(양도소득세의 분할납부) 거주자로서 제106조 또는 제111조에 따라 납부할 세액이 각각 1천만원을 초과하는 자는 대통령령으로 정하는 바에 따라 그 납부할 세액의 일부를 납부기한이 지난 후 2개월 이내에 분할납부할 수 있다."},{"법령":"소득세법 시행령","조문":"제175조제1호","원문":"1. 납부할 세액이 2천만원이하인 때에는 1천만원을 초과하는 금액"}],"선지":[{"번호":1,"판정":"옳음","설명":"토지·건물 등은 양도일이 속하는 달의 말일부터 2개월 이내에 예정신고한다(소득세법 제105조제1항제1호)."},{"번호":2,"판정":"옳음","설명":"예정신고를 한 자는 확정신고를 하지 않을 수 있다. 같은 과세기간에 누진세율 대상 자산의 예정신고를 2회 이상 하는 등 대통령령으로 정하는 경우는 예외다(소득세법 제110조제4항, 시행령 제173조제5항)."},{"번호":3,"판정":"틀림","설명":"토지거래허가를 받기 전에 대금을 청산한 경우 기한의 기산점은 허가일(허가 전에 지정이 해제되면 해제일)이 속하는 달의 말일이다(소득세법 제105조제1항제1호 단서)."},{"번호":4,"판정":"옳음","설명":"납부할 세액이 1천만원을 초과하면 분할납부할 수 있고, 2천만원 이하이면 1천만원을 초과하는 금액이다. 1천500만원이면 500만원이다(소득세법 제112조, 시행령 제175조제1호)."},{"번호":5,"판정":"옳음","설명":"확정신고는 다음 연도 5월 1일부터 5월 31일까지이고, 과세표준이 없거나 결손금액이 있는 경우에도 한다(소득세법 제110조제1항·제2항)."}],"개념":[{"종류":"표","제목":"양도소득세 신고·납부 기한","머리":["구분","기한"],"행":[["예정신고(토지·건물·부동산에 관한 권리·기타자산)","양도일이 속하는 달의 말일부터 2개월"],["예정신고(토지거래허가구역 토지, 허가 전 대금 청산)","허가일(허가 전 해제 시 해제일)이 속하는 달의 말일부터 2개월"],["예정신고(부담부증여 채무액 해당 부분)","양도일이 속하는 달의 말일부터 3개월"],["예정신고(주식등)","양도일이 속하는 반기의 말일부터 2개월"],["확정신고","과세기간의 다음 연도 5월 1일부터 5월 31일까지"],["양도차익이 없거나 양도차손이 발생한 경우","예정신고 의무가 있다"],["분할납부 기간","납부기한이 지난 후 2개월 이내"]]},{"종류":"계산","제목":"분할납부 가능 금액","단계":[{"설명":"납부할 세액이 1천만원을 초과하는지 본다","식":"세액 > 1,000만원","값":"분할납부 대상"},{"설명":"세액 1,500만원(2천만원 이하): 1천만원 초과 금액","식":"1,500만원 − 1,000만원","값":"500만원"},{"설명":"세액 3,000만원(2천만원 초과): 세액의 100분의 50 이하","식":"3,000만원 × 50%","값":"1,500만원"}]}],"함정":"3번은 대금을 청산한 날을 기준으로 잡는 실수가 잦다. 허가 전 청산이면 기산점이 허가일로 늦춰진다. 4번은 세액의 50%를 분납하는 문장으로 보기 쉽지만 2천만원 이하일 때는 1천만원을 초과하는 금액이다."}},{"i":"S2-2-2-세법-12","r":"S2","g":3,"c":2,"n":36,"s":"세법","q":"소득세법상 미등기양도자산에 관한 설명으로 옳은 것은?","b":null,"bs":"없음","img":[],"ch":["건설사업자가 「도시개발법」에 따라 공사용역 대가로 취득한 체비지를 토지구획환지처분공고 후에 양도하는 토지는 미등기양도자산에 해당하지 않는다.","장기할부조건으로 취득한 자산으로서 그 계약조건에 의하여 양도 당시 취득등기가 불가능한 자산을 양도하는 경우에도 미등기양도자산에 해당한다.","보유기간이 3년 이상인 미등기양도자산에 대해서는 장기보유특별공제를 적용한다.","미등기양도자산의 양도소득금액에 대해서는 양도소득 기본공제를 적용하지 아니한다.","미등기양도자산에 대한 양도소득세율은 양도소득 과세표준의 100분의 60이다."],"a":[4],"L":"세3-2","o":"변형","x":{"한줄":"미등기양도자산은 양도소득 기본공제를 받을 수 없고, 비과세·장기보유특별공제 배제와 100분의 70 세율이 함께 적용된다.","근거":[{"법령":"소득세법","조문":"제103조제1항제1호","원문":"1. 제94조제1항제1호ㆍ제2호 및 제4호에 따른 소득. 다만, 제104조제3항에 따른 미등기양도자산의 양도소득금액에 대해서는 그러하지 아니하다."},{"법령":"소득세법","조문":"제104조제1항제10호","원문":"10. 미등기양도자산"},{"법령":"소득세법","조문":"제104조제3항","원문":"③ 제1항제10호에서 \"미등기양도자산\"이란 제94조제1항제1호 및 제2호에서 규정하는 자산을 취득한 자가 그 자산 취득에 관한 등기를 하지 아니하고 양도하는 것을 말한다. 다만, 대통령령으로 정하는 자산은 제외한다."},{"법령":"소득세법","조문":"제95조제2항","원문":"제104조제3항에 따른 미등기양도자산과 같은 조 제7항 각 호에 따른 자산은 제외한다)으로서 보유기간이 3년 이상인 것"},{"법령":"소득세법","조문":"제91조제1항","원문":"① 제104조제3항에서 규정하는 미등기양도자산에 대하여는 이 법 또는 이 법 외의 법률 중 양도소득에 대한 소득세의 비과세에 관한 규정을 적용하지 아니한다."},{"법령":"소득세법 시행령","조문":"제168조제1항제1호","원문":"1. 장기할부조건으로 취득한 자산으로서 그 계약조건에 의하여 양도 당시 그 자산의 취득에 관한 등기가 불가능한 자산"},{"법령":"소득세법 시행령","조문":"제168조제1항제7호","원문":"7. 건설사업자가 「도시개발법」에 따라 공사용역 대가로 취득한 체비지를 토지구획환지처분공고 전에 양도하는 토지"}],"선지":[{"번호":1,"판정":"틀림","설명":"체비지 양도가 미등기양도자산에서 빠지는 것은 환지처분공고 '전'에 양도할 때다. 공고 후 양도는 해당하지 않는다(소득세법 시행령 제168조제1항제7호)."},{"번호":2,"판정":"틀림","설명":"장기할부조건으로 취득해 계약조건상 등기가 불가능한 자산은 미등기양도자산에서 제외된다(소득세법 시행령 제168조제1항제1호)."},{"번호":3,"판정":"틀림","설명":"미등기양도자산은 장기보유특별공제 대상에서 제외된다(소득세법 제95조제2항)."},{"번호":4,"판정":"옳음","설명":"양도소득 기본공제는 미등기양도자산의 양도소득금액에는 적용하지 않는다(소득세법 제103조제1항제1호 단서)."},{"번호":5,"판정":"틀림","설명":"미등기양도자산의 세율은 양도소득 과세표준의 100분의 70이다(소득세법 제104조제1항제10호)."}],"개념":[{"종류":"표","제목":"미등기양도자산과 등기양도자산의 취급 차이","머리":["항목","미등기양도자산","등기된 자산"],"행":[["양도소득세 비과세·감면","비과세 규정 적용 배제(제91조제1항)","요건 충족 시 적용"],["장기보유특별공제","적용하지 않음","보유기간 3년 이상 시 적용"],["양도소득 기본공제(연 250만원)","적용하지 않음","적용"],["세율","양도소득 과세표준의 100분의 70","보유기간별 100분의 40·50(주택은 60·70) 또는 기본세율"]]},{"종류":"계산","제목":"미등기양도 시 세액 차이(보유기간 2년 이상 상가, 과세표준 1억원 가정)","단계":[{"설명":"미등기양도자산은 과세표준에 100분의 70을 곱한다","식":"1억원 × 70%","값":"7,000만원"},{"설명":"등기된 자산이면 기본세율을 적용한다. 8,800만원 초과 1억5천만원 이하 구간은 1,536만원에 8,800만원 초과금액의 100분의 35를 더한다","식":"1,536만원 + (1억원 − 8,800만원) × 35%","값":"1,536만원 + 420만원 = 1,956만원"}]}],"함정":"미등기양도자산에서 제외되는 자산(시행령 제168조)은 문구 하나로 갈린다. 장기할부조건으로 취득하고 등기가 불가능한 자산은 제외 대상이어서 2번이 틀리고, 체비지는 환지처분공고 전 양도만 제외 대상이어서 1번이 틀린다. 3번과 4번은 장기보유특별공제와 기본공제가 둘 다 배제된다는 점을 하나씩 따로 묻는다.","개정":"건설업자에서 건설사업자로 용어가 바뀌었다(소득세법 시행령 제168조제1항제7호). 결론은 달라지지 않는다."}},{"i":"S2-2-2-세법-13","r":"S2","g":3,"c":2,"n":37,"s":"세법","q":"소득세법상 거주자의 양도소득세 비과세에 관한 설명으로 옳은 것은? (단, 주어진 조건 외의 예외 사유는 고려하지 않음)","b":null,"bs":"없음","img":[],"ch":["취득 당시 조정대상지역에 있던 1주택을 3년간 보유하면서 1년간 거주한 1세대가 그 주택을 양도하는 경우(고가주택 아님) 1세대 1주택 비과세 요건을 충족한다.","1년 이상 거주한 1주택을 근무상의 형편 등 재정경제부령으로 정하는 부득이한 사유로 양도하는 경우(고가주택 아님)에는 보유기간이 2년에 미달해도 비과세된다.","양도 당시 실지거래가액이 15억원인 1세대 1주택의 양도로 발생하는 양도차익 전부가 비과세된다.","경작상 필요에 의하여 교환하는 농지는 교환으로 새로 취득하는 농지를 5년 이상 농지소재지에 거주하면서 경작하는 경우에 한하여 비과세된다(쌍방 토지가액의 차액이 가액이 큰 편의 4분의 1 이하임).","미등기양도자산에 해당하는 1세대 1주택도 요건을 갖추면 양도소득세가 비과세된다."],"a":[2],"L":"세3-2","o":"변형","x":{"한줄":"1년 이상 거주한 주택을 취학, 근무상의 형편, 질병의 요양 등 부득이한 사유로 양도하면 보유기간과 거주기간 제한 없이 1세대 1주택으로 본다.","근거":[{"법령":"소득세법 시행령","조문":"제154조제1항제3호","원문":"3. 1년이상 거주한 주택을 재정경제부령으로 정하는 취학, 근무상의 형편, 질병의 요양, 그 밖에 부득이한 사유로 양도하는 경우"},{"법령":"소득세법 시행령","조문":"제154조제1항","원문":"취득 당시에 「주택법」 제63조의2제1항제1호에 따른 조정대상지역(이하 \"조정대상지역\"이라 한다)에 있는 주택의 경우에는 해당 주택의 보유기간이 2년(제8항제2호에 해당하는 거주자의 주택인 경우에는 3년) 이상이고 그 보유기간 중 거주기간이 2년 이상인 것"},{"법령":"소득세법","조문":"제89조제1항제3호","원문":"3. 다음 각 목의 어느 하나에 해당하는 주택(주택 및 이에 딸린 토지의 양도 당시 실지거래가액의 합계액이 12억원을 초과하는 고가주택은 제외한다)"},{"법령":"소득세법 시행령","조문":"제153조제1항제3호","원문":"3. 경작상 필요에 의하여 교환하는 농지. 다만, 교환에 의하여 새로이 취득하는 농지를 3년이상 농지소재지에 거주하면서 경작하는 경우에 한한다."},{"법령":"소득세법","조문":"제91조제1항","원문":"① 제104조제3항에서 규정하는 미등기양도자산에 대하여는 이 법 또는 이 법 외의 법률 중 양도소득에 대한 소득세의 비과세에 관한 규정을 적용하지 아니한다."}],"선지":[{"번호":1,"판정":"틀림","설명":"취득 당시 조정대상지역에 있던 주택은 보유 2년에 더해 보유기간 중 거주 2년 이상이어야 한다. 거주 1년은 부족하다(소득세법 시행령 제154조제1항)."},{"번호":2,"판정":"옳음","설명":"1년 이상 거주한 주택을 취학, 근무상의 형편, 질병의 요양 등 부득이한 사유로 양도하면 보유기간·거주기간의 제한을 받지 않는다(소득세법 시행령 제154조제1항제3호)."},{"번호":3,"판정":"틀림","설명":"실지거래가액이 12억원을 넘는 고가주택은 1세대 1주택 비과세 대상에서 제외된다. 15억원 주택의 양도차익은 전부 비과세되지 않는다(소득세법 제89조제1항제3호)."},{"번호":4,"판정":"틀림","설명":"경작상 필요에 의한 교환은 새로 취득하는 농지를 3년 이상 농지소재지에 거주하면서 경작해야 한다. 5년이 아니다(소득세법 시행령 제153조제1항제3호)."},{"번호":5,"판정":"틀림","설명":"미등기양도자산에는 양도소득세 비과세 규정을 적용하지 않는다(소득세법 제91조제1항)."}],"개념":[{"종류":"표","제목":"1세대 1주택 비과세 요건","머리":["구분","내용"],"행":[["기본 요건","양도일 현재 국내 1주택, 보유기간 2년 이상"],["취득 당시 조정대상지역 주택","보유기간 2년 이상 + 그 기간 중 거주 2년 이상"],["보유·거주기간 제한 없음","임대주택 임차일부터 세대전원 5년 이상 거주, 협의매수·수용, 해외이주(출국일부터 2년 이내 양도), 1년 이상 국외 취학·근무(출국일부터 2년 이내 양도), 1년 이상 거주한 주택을 부득이한 사유로 양도"],["고가주택","양도 당시 실지거래가액 12억원 초과 주택은 비과세 대상에서 제외"],["주택부수토지 한도(도시지역 안 수도권 주거·상업·공업지역)","건물 정착면적의 3배"],["주택부수토지 한도(수도권 녹지지역, 수도권 밖 도시지역)","건물 정착면적의 5배"],["주택부수토지 한도(도시지역 밖)","건물 정착면적의 10배"]]},{"종류":"표","제목":"농지 교환·분합 비과세(시행령 제153조)","머리":["요건","내용"],"행":[["차액 요건","교환·분합하는 쌍방 토지가액의 차액이 가액이 큰 편의 4분의 1 이하"],["유형 1","국가·지방자치단체가 시행하는 사업으로 교환·분합"],["유형 2","국가·지방자치단체 소유 토지와 교환·분합"],["유형 3","경작상 필요에 의한 교환. 새 농지를 3년 이상 농지소재지에 거주하며 경작"],["유형 4","농어촌정비법·농지법 등에 따른 교환·분합"]]}],"함정":"1번은 보유 3년이라 조건을 다 채웠다고 착각하기 쉽다. 조정대상지역에서 취득한 주택은 거주 2년이 별도로 필요하다. 3번은 12억원 초과분만 과세되는 줄 알고 비과세로 읽는 경우도 있으나 고가주택은 비과세 규정 자체가 적용되지 않는다. 4번의 3년을 5년으로 바꾼 숫자 함정도 반복된다.","개정":"고가주택 기준은 옛 기출의 실지거래가액 9억원 초과에서 현재 12억원 초과로 올랐다(소득세법 제89조제1항제3호)."}},{"i":"S2-2-2-세법-14","r":"S2","g":3,"c":2,"n":38,"s":"세법","q":"소득세법상 등기된 국내 부동산에 대한 양도소득과세표준의 세율에 관한 내용으로 옳은 것은? (단, 비사업용 토지, 조합원입주권, 분양권, 다주택자 중과는 고려하지 않음)","b":null,"bs":"없음","img":[],"ch":["11개월 보유한 주택: 100분의 60","1년 3개월 보유한 상가건물: 100분의 50","9개월 보유한 토지: 100분의 50","2년 6개월 보유한 상가건물: 100분의 40","1년 6개월 보유한 주택: 100분의 40"],"a":[3],"L":"세3-2","o":"변형","x":{"한줄":"토지·건물은 보유기간 1년 미만이면 100분의 50, 1년 이상 2년 미만이면 100분의 40이고, 주택은 각각 100분의 70, 100분의 60이다.","근거":[{"법령":"소득세법","조문":"제104조제1항제3호","원문":"3. 제94조제1항제1호 및 제2호에 따른 자산으로서 그 보유기간이 1년 미만인 것"},{"법령":"소득세법","조문":"제104조제1항제3호","원문":"양도소득 과세표준의 100분의 50(주택, 조합원입주권 및 분양권의 경우에는 100분의 70)"},{"법령":"소득세법","조문":"제104조제1항제2호","원문":"양도소득 과세표준의 100분의 40[주택(이에 딸린 토지로서 대통령령으로 정하는 토지를 포함한다. 이하 이 항에서 같다), 조합원입주권 및 분양권의 경우에는 100분의 60]"},{"법령":"소득세법","조문":"제104조제1항제1호","원문":"제55조제1항에 따른 세율(분양권의 경우에는 양도소득 과세표준의 100분의 60)"}],"선지":[{"번호":1,"판정":"틀림","설명":"보유기간 1년 미만 주택은 100분의 70이다. 100분의 60은 1년 이상 2년 미만 주택의 세율이다(소득세법 제104조제1항제2호·제3호)."},{"번호":2,"판정":"틀림","설명":"보유기간 1년 이상 2년 미만 상가건물은 100분의 40이다(소득세법 제104조제1항제2호)."},{"번호":3,"판정":"옳음","설명":"보유기간 1년 미만 토지·건물은 양도소득 과세표준의 100분의 50이다(소득세법 제104조제1항제3호)."},{"번호":4,"판정":"틀림","설명":"보유기간 2년 이상 상가건물은 100분의 40이 아니라 기본세율(6%~45%)이다(소득세법 제104조제1항제1호)."},{"번호":5,"판정":"틀림","설명":"보유기간 1년 이상 2년 미만 주택은 100분의 60이다(소득세법 제104조제1항제2호)."}],"개념":[{"종류":"표","제목":"등기된 부동산 양도소득세율(비사업용 토지·다주택 중과 제외)","머리":["보유기간","토지·건물","주택·조합원입주권"],"행":[["1년 미만","100분의 50","100분의 70"],["1년 이상 2년 미만","100분의 40","100분의 60"],["2년 이상","기본세율(6%~45%)","기본세율(6%~45%)"],["미등기양도","100분의 70","100분의 70"]]},{"종류":"계산","제목":"양도소득과세표준 1억원인 상가건물의 산출세액","단계":[{"설명":"보유기간 9개월(1년 미만)","식":"1억원 × 50%","값":"5,000만원"},{"설명":"보유기간 1년 3개월(1년 이상 2년 미만)","식":"1억원 × 40%","값":"4,000만원"},{"설명":"보유기간 2년 6개월(2년 이상)은 기본세율. 8,800만원 초과 1억5천만원 이하 구간","식":"1,536만원 + (1억원 − 8,800만원) × 35%","값":"1,536만원 + 420만원 = 1,956만원"}]}],"함정":"주택과 토지·건물의 단기 세율이 다르다. 1년 미만은 주택 70 / 토지·건물 50, 1~2년은 주택 60 / 토지·건물 40이다. 4번은 2년 이상도 40이라고 외우면 고르게 된다. 2년 이상은 기본세율이다.","개정":"주택·조합원입주권의 단기 세율은 2021년 6월 1일 양도분부터 1년 미만 100분의 70, 1년 이상 2년 미만 100분의 60으로 올랐다. 예전 기출의 주택 40%·30%류 보기는 현행 기준으로 틀린 내용이다(소득세법 제104조제1항제2호·제3호)."}},{"i":"S2-2-2-세법-15","r":"S2","g":3,"c":2,"n":39,"s":"세법","q":"소득세법상 양도소득세에 관한 설명으로 옳은 것은? (단, 주어진 조건 외에는 고려하지 않음)","b":null,"bs":"없음","img":[],"ch":["거주자가 국외에 있는 토지를 양도한 경우 양도일까지 계속하여 5년 이상 국내에 주소 또는 거소를 두었다면 양도소득세 납세의무가 있고, 그 양도소득과세표준을 예정신고하여야 한다.","거주자가 국외에 있는 건물을 양도한 경우 양도일까지 계속하여 5년 이상 국내에 주소를 두었다면 양도소득금액을 계산할 때 장기보유특별공제를 적용한다.","거주자가 국내에 있는 상가건물을 양도한 경우 거주자의 주소지와 상가건물의 소재지가 다르면 양도소득세의 납세지는 상가건물의 소재지이다.","거주자가 국외에 있는 토지를 양도한 경우에는 양도소득 기본공제를 적용하지 아니한다.","국외자산의 양도가액은 양도 당시의 실지거래가액을 확인할 수 있는 경우에도 양도 당시의 시가로 한다."],"a":[1],"L":"세3-2","o":"변형","x":{"한줄":"국외 토지를 양도해도 양도일까지 계속 5년 이상 국내에 주소나 거소를 둔 거주자는 양도소득세 납세의무가 있고, 예정신고 규정이 준용된다.","근거":[{"법령":"소득세법","조문":"제118조의2","원문":"제118조의2(국외자산 양도소득의 범위) 거주자(해당 자산의 양도일까지 계속 5년 이상 국내에 주소 또는 거소를 둔 자만 해당한다)의 국외에 있는 자산의 양도에 대한 양도소득은"},{"법령":"소득세법","조문":"제118조의8","원문":"제118조의8(국외자산 양도에 대한 준용규정) 국외자산의 양도에 대한 양도소득세의 과세에 관하여는 제89조, 제90조, 제92조, 제95조, 제97조제3항, 제98조, 제100조, 제101조, 제105조부터 제107조까지, 제110조부터 제112조까지, 제114조, 제114조의2 및 제115조부터 제118조까지를 준용한다. 다만, 제95조에 따른 장기보유 특별공제액은 공제하지 아니한다."},{"법령":"소득세법","조문":"제118조의7제1항","원문":"① 국외자산의 양도에 대한 양도소득이 있는 거주자에 대해서는 해당 과세기간의 양도소득금액에서 연 250만원을 공제한다."},{"법령":"소득세법","조문":"제118조의3제1항","원문":"① 제118조의2에 따른 자산(이하 이 절에서 \"국외자산\"이라 한다)의 양도가액은 그 자산의 양도 당시의 실지거래가액으로 한다."},{"법령":"소득세법","조문":"제6조제1항","원문":"① 거주자의 소득세 납세지는 그 주소지로 한다. 다만, 주소지가 없는 경우에는 그 거소지로 한다."}],"선지":[{"번호":1,"판정":"옳음","설명":"거주자가 양도일까지 계속 5년 이상 국내에 주소나 거소를 두었다면 국외자산 양도소득에 납세의무가 있고, 제105조 예정신고 규정이 준용된다(소득세법 제118조의2, 제118조의8)."},{"번호":2,"판정":"틀림","설명":"국외자산 양도에는 제95조의 장기보유특별공제액을 공제하지 않는다(소득세법 제118조의8 단서)."},{"번호":3,"판정":"틀림","설명":"거주자의 소득세 납세지는 주소지다. 양도자산 소재지가 아니다(소득세법 제6조제1항)."},{"번호":4,"판정":"틀림","설명":"국외자산 양도소득이 있는 거주자에게도 연 250만원의 양도소득 기본공제를 적용한다(소득세법 제118조의7제1항)."},{"번호":5,"판정":"틀림","설명":"국외자산의 양도가액은 실지거래가액이 원칙이고, 확인할 수 없을 때 시가를 쓴다(소득세법 제118조의3제1항)."}],"개념":[{"종류":"표","제목":"국외자산 양도소득세","머리":["항목","내용"],"행":[["납세의무자","양도일까지 계속 5년 이상 국내에 주소 또는 거소를 둔 거주자"],["과세대상","토지·건물, 부동산에 관한 권리(부동산을 취득할 수 있는 권리·지상권·전세권·부동산임차권), 대통령령으로 정하는 기타자산"],["양도가액","양도 당시 실지거래가액(확인할 수 없으면 양도자산 소재국의 양도 당시 시가)"],["장기보유특별공제","공제하지 않음"],["양도소득 기본공제","연 250만원"],["세율","종합소득 기본세율(소득세법 제55조제1항)"],["신고","예정신고·확정신고·분할납부 규정을 준용"],["외국납부세액","세액공제 방법과 필요경비 산입 방법 중 선택"]]},{"종류":"비교","제목":"소득세 납세지","왼쪽":{"이름":"거주자","항목":["원칙: 주소지","주소지가 없으면 거소지","양도소득세도 양도자산 소재지가 아니라 주소지"]},"오른쪽":{"이름":"비거주자","항목":["국내사업장 소재지","국내사업장이 둘 이상이면 주된 국내사업장 소재지","국내사업장이 없으면 국내원천소득이 발생하는 장소"]}}],"함정":"3번은 부동산이니 소재지가 납세지일 것 같지만 거주자의 소득세 납세지는 주소지다. 2번은 국내 부동산과 같은 공제를 국외 자산에도 준다고 읽은 것이다. 장기보유특별공제는 국내 토지·건물에만 적용된다."}},{"i":"S2-2-2-세법-16","r":"S2","g":3,"c":2,"n":40,"s":"세법","q":"소득세법상 거주자의 부동산과 관련된 사업소득에 관한 설명으로 옳은 것은? (단, 주어진 조건 외에는 고려하지 않음)","b":null,"bs":"없음","img":[],"ch":["기준시가가 13억원인 국내 소재 주택 1개를 소유한 자의 주택임대소득은 비과세된다.","「공익사업을 위한 토지 등의 취득 및 보상에 관한 법률」에 따른 공익사업과 관련하여 지역권을 대여함으로써 발생하는 소득은 부동산업에서 발생하는 사업소득에 해당하지 아니한다.","상가건물 임대업에서 발생한 결손금은 종합소득 과세표준을 계산할 때 근로소득금액 등에서 공제한다.","주택을 공동소유하는 경우 주택임대소득 비과세 판단을 위한 주택 수는 공동소유자 각자의 소유로 계산한다.","다가구주택은 구분 등기 여부와 관계없이 1개의 주택으로 보아 주택 수를 계산한다."],"a":[2],"L":"세3-3","o":"변형","x":{"한줄":"공익사업과 관련한 지역권·지상권 설정·대여 소득은 부동산업 사업소득에서 제외되어 기타소득으로 과세된다.","근거":[{"법령":"소득세법","조문":"제19조제1항제12호","원문":"12. 부동산업에서 발생하는 소득. 다만, 「공익사업을 위한 토지 등의 취득 및 보상에 관한 법률」 제4조에 따른 공익사업과 관련하여 지역권ㆍ지상권(지하 또는 공중에 설정된 권리를 포함한다)을 설정하거나 대여함으로써 발생하는 소득은 제외한다."},{"법령":"소득세법","조문":"제21조제1항제9호","원문":"9. 「공익사업을 위한 토지 등의 취득 및 보상에 관한 법률」 제4조에 따른 공익사업과 관련하여 지역권ㆍ지상권(지하 또는 공중에 설정된 권리를 포함한다)을 설정하거나 대여함으로써 발생하는 소득"},{"법령":"소득세법","조문":"제12조제2호나목","원문":"나. 1개의 주택을 소유하는 자의 주택임대소득(제99조에 따른 기준시가가 12억원을 초과하는 주택 및 국외에 소재하는 주택의 임대소득은 제외한다)"},{"법령":"소득세법","조문":"제45조제2항","원문":"② 제1항에도 불구하고 다음 각 호의 어느 하나에 해당하는 사업(이하 \"부동산임대업\"이라 한다)에서 발생한 결손금은 종합소득 과세표준을 계산할 때 공제하지 아니한다. 다만, 주거용 건물 임대업의 경우에는 그러하지 아니하다."},{"법령":"소득세법 시행령","조문":"제8조의2제3항제2호","원문":"2. 공동소유하는 주택은 지분이 가장 큰 사람의 소유로 계산(지분이 가장 큰 사람이 2명 이상인 경우로서 그들이 합의하여 그들 중 1명을 해당 주택 임대수입의 귀속자로 정한 경우에는 그의 소유로 계산한다)."},{"법령":"소득세법 시행령","조문":"제8조의2제3항제1호","원문":"1. 다가구주택은 1개의 주택으로 보되, 구분 등기된 경우에는 각각을 1개의 주택으로 계산"}],"선지":[{"번호":1,"판정":"틀림","설명":"기준시가가 12억원을 초과하는 주택의 임대소득은 1주택이어도 비과세에서 제외된다(소득세법 제12조제2호나목)."},{"번호":2,"판정":"옳음","설명":"공익사업 관련 지역권·지상권을 설정하거나 대여해 얻는 소득은 부동산업 사업소득에서 빠지고 기타소득이다(소득세법 제19조제1항제12호 단서, 제21조제1항제9호)."},{"번호":3,"판정":"틀림","설명":"상가 같은 비주거용 부동산임대업의 결손금은 종합소득 과세표준을 계산할 때 공제하지 않는다. 주거용 건물 임대업만 예외다(소득세법 제45조제2항)."},{"번호":4,"판정":"틀림","설명":"공동소유 주택은 지분이 가장 큰 사람의 소유로 계산한다. 지분이 같은 경우 합의로 정한 1명의 소유가 되는 방식이며, 예외로 연간 임대수입 600만원 이상이거나 12억원 초과 주택의 지분 100분의 30 초과 보유자도 본인 소유로 계산한다(소득세법 시행령 제8조의2제3항제2호)."},{"번호":5,"판정":"틀림","설명":"다가구주택은 1개의 주택으로 보지만 구분 등기된 경우에는 각각을 1개의 주택으로 계산한다(소득세법 시행령 제8조의2제3항제1호)."}],"개념":[{"종류":"표","제목":"주택임대소득 비과세·주택 수 계산","머리":["구분","내용"],"행":[["비과세 요건","1개의 주택을 소유하는 자의 주택임대소득"],["비과세 제외","기준시가 12억원 초과 주택, 국외에 소재하는 주택"],["다가구주택","1개의 주택으로 보되 구분 등기되면 각각 1개"],["공동소유 주택","지분이 가장 큰 사람의 소유(동률이면 합의한 1명). 연 임대수입 600만원 이상인 사람, 12억원 초과 주택 지분 100분의 30 초과 보유자는 본인 소유로도 계산"],["임차 후 전대","임차인의 주택으로 계산"],["본인·배우자","각각 소유한 주택을 합산"]]},{"종류":"비교","제목":"부동산임대업 결손금 공제","왼쪽":{"이름":"주거용 건물 임대업","항목":["결손금: 종합소득 과세표준 계산 시 근로소득금액 등에서 순서대로 공제","이월결손금: 사업소득금액 등에서 공제"]},"오른쪽":{"이름":"그 밖의 부동산임대업(상가·토지 등)","항목":["결손금: 종합소득 과세표준 계산 시 공제하지 않음","이월결손금: 부동산임대업의 소득금액에서만 공제","이월결손금 공제기간: 발생 과세기간 종료일부터 15년 이내"]}}],"함정":"3번은 결손금이 다른 소득과 통산된다고 보는 오해다. 부동산임대업의 결손금 통산 배제에서 주거용 건물 임대업만 예외다. 1번은 1주택이면 무조건 비과세라는 오해이고, 기준시가 12억원 초과와 국외 소재 주택은 제외된다."}}];